export enum GameState {
  MENU = 'MENU',
  BRIEFING = 'BRIEFING',
  PLAYING = 'PLAYING',
  PAUSED = 'PAUSED',
  GAMEOVER = 'GAMEOVER',
  VICTORY = 'VICTORY',
  LEVEL_COMPLETE = 'LEVEL_COMPLETE',
  SHOP = 'SHOP',
  LEVEL_SELECT = 'LEVEL_SELECT'
}

export enum RobotUnit {
  SENTINEL = 'SENTINEL',
  STRIKER = 'STRIKER',
  FALCON = 'FALCON',
  TITAN = 'TITAN',
  SPECTER = 'SPECTER'
}

export interface LevelInfo {
  level: number;
  title: string;
  description: string;
  threatLevel: string;
  enemyType: string;
}

export interface Upgrades {
  robotTier: number;
  weaponTier: number;
}

export interface Vector {
  x: number;
  y: number;
}

export interface Entity {
  pos: Vector;
  vel: Vector;
  width: number;
  height: number;
  health: number;
  maxHealth: number;
}

export interface Bullet extends Entity {
  owner: 'player' | 'enemy';
  damage?: number;
  color?: string;
}

export interface Enemy extends Entity {
  id: number;
  isDead: boolean;
  type: string;
  lastShot: number;
  hasSplit?: boolean;
  sequenceStage?: number;
  sequenceTimer?: number;
}

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { speed: 4, jump: -11, color: '#00f3ff', hpMult: 1.0, fireRate: 15, name: "SENTINEL" },
  [RobotUnit.STRIKER]: { speed: 9, jump: -9, color: '#fbbf24', hpMult: 0.8, fireRate: 8, name: "STRIKER" },
  [RobotUnit.FALCON]: { speed: 7, jump: -10, color: '#22d3ee', hpMult: 0.7, fireRate: 12, name: "FALCON" },
  [RobotUnit.TITAN]: { speed: 2.5, jump: -13, color: '#ef4444', hpMult: 2.5, fireRate: 30, name: "TITAN" },
  [RobotUnit.SPECTER]: { speed: 6, jump: -12, color: '#a855f7', hpMult: 0.6, fireRate: 20, name: "SPECTER" },
};

const SQUAD_COLORS = ['#00f3ff', '#fbbf24', '#22d3ee', '#ef4444', '#a855f7'];

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [currentUnit, setCurrentUnit] = useState<RobotUnit>(RobotUnit.SENTINEL);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [distance, setDistance] = useState(0);
  const [isCinematic, setIsCinematic] = useState(false);
  const [cinematicText, setCinematicText] = useState("");

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      maxHealth: 100,
    },
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    allies: [] as any[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    unit: RobotUnit.SENTINEL,
    level: level,
    cinematic: false,
    particles: [] as any[]
  });

  useEffect(() => { engineRef.current.isPaused = isPaused; }, [isPaused]);
  useEffect(() => { engineRef.current.unit = currentUnit; }, [currentUnit]);
  useEffect(() => { engineRef.current.level = level; }, [level]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff44');
    grad.addColorStop(1, '#00000088');
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.5)';
    ctx.stroke();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy = false) => {
    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    if (facing === -1) ctx.scale(-1, 1);

    const stats = ROBOT_STATS[unit];
    const color = isEnemy ? '#ff0055' : stats.color;
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8;

    switch(unit) {
      case RobotUnit.SENTINEL:
        drawMechanicalPart(ctx, -12, -18, 24, 28, color, 4);
        drawMechanicalPart(ctx, -8, -30, 16, 12, '#222', 6);
        drawMechanicalPart(ctx, -10, 10, 8, 14 + legSwing/2, '#222', 2);
        drawMechanicalPart(ctx, 2, 10, 8, 14 - legSwing/2, '#222', 2);
        drawMechanicalPart(ctx, 4, -10, 18, 8, '#444', 2);
        break;
      case RobotUnit.STRIKER:
        // Striker has wheels
        drawMechanicalPart(ctx, -16, -10, 32, 14, color, 8);
        drawMechanicalPart(ctx, -10, -22, 20, 12, '#111', 4);
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(-12, 8, 6, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(12, 8, 6, 0, Math.PI * 2); ctx.fill();
        break;
      case RobotUnit.FALCON:
        // Falcon has wings
        drawMechanicalPart(ctx, -10, -20, 20, 24, color, 2);
        drawMechanicalPart(ctx, -6, -30, 12, 10, '#222', 8);
        ctx.beginPath();
        ctx.moveTo(-5, -15); ctx.lineTo(-25, -25); ctx.lineTo(-5, -5); ctx.closePath();
        ctx.fillStyle = color; ctx.fill();
        break;
      case RobotUnit.TITAN:
        // Huge heavy unit
        drawMechanicalPart(ctx, -24, -30, 48, 40, color, 10);
        drawMechanicalPart(ctx, -12, -45, 24, 15, '#222', 8);
        drawMechanicalPart(ctx, -20, 10, 14, 24, '#111', 2);
        drawMechanicalPart(ctx, 6, 10, 14, 24, '#111', 2);
        break;
      case RobotUnit.SPECTER:
        // Sleek sniper
        drawMechanicalPart(ctx, -8, -25, 16, 34, color, 12);
        drawMechanicalPart(ctx, -6, -35, 12, 10, '#111', 12);
        drawMechanicalPart(ctx, 2, -15, 28, 4, '#555', 0); // Long barrel
        break;
    }

    // Glow effect
    ctx.fillStyle = isEnemy ? '#ff0000' : '#ffffff';
    ctx.beginPath(); ctx.arc(unit === RobotUnit.TITAN ? 0 : 4, -24, 2, 0, Math.PI * 2); ctx.fill();

    ctx.restore();
  };

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    const baseHP = 100 + (upgrades.robotTier * 50);
    const stats = ROBOT_STATS[currentUnit];

    e.player.maxHealth = baseHP * stats.hpMult;
    setMaxHealth(e.player.maxHealth);
    setHealth(e.player.maxHealth);

    e.player.pos = { x: 100, y: 300 };
    e.player.vel = { x: 0, y: 0 };
    e.player.invulnerable = 0;
    e.bullets = [];
    e.cameraX = 0;
    e.cinematic = false;
    e.particles = [];
    setIsCinematic(false);
    setCinematicText("");
    setDistance(0);

    const enemies: Enemy[] = [];
    const floorY = 398;

    for (let i = 0; i < 4; i++) {
      enemies.push({ 
        id: i, 
        pos: { x: 800 + i * 600, y: floorY - 48 }, 
        vel: { x: (Math.random() - 0.5) * 3, y: 0 }, 
        width: 32, 
        height: 48, 
        health: 50 + level * 15, 
        maxHealth: 50 + level * 15, 
        isDead: false, 
        type: 'bot', 
        lastShot: 0 
      });
    }
    enemies.push({ 
      id: 4, 
      pos: { x: 3200, y: floorY - 96 }, 
      vel: { x: 0, y: 0 }, 
      width: 64, 
      height: 96, 
      health: 400 + level * 40, 
      maxHealth: 400 + level * 40, 
      isDead: false, 
      type: 'titan', 
      lastShot: 0 
    });

    e.enemies = enemies;
  }, [level, upgrades, currentUnit]);

  useEffect(() => {
    resetLevel();
    const handleKeyDown = (e: KeyboardEvent) => {
      if (engineRef.current.cinematic) return;
      engineRef.current.keys[e.code] = true;
      if (e.code === 'Digit1') setCurrentUnit(RobotUnit.SENTINEL);
      if (e.code === 'Digit2') setCurrentUnit(RobotUnit.STRIKER);
      if (e.code === 'Digit3') setCurrentUnit(RobotUnit.FALCON);
      if (e.code === 'Digit4') setCurrentUnit(RobotUnit.TITAN);
      if (e.code === 'Digit5') setCurrentUnit(RobotUnit.SPECTER);
    };
    const handleKeyUp = (e: KeyboardEvent) => { engineRef.current.keys[e.code] = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!engineRef.current.isPaused) update();
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const e = engineRef.current;
      const { player, enemies, bullets, keys } = e;
      const stats = ROBOT_STATS[e.unit];
      e.frame++;

      // Movement
      if (!e.cinematic) {
        if (keys['ArrowRight'] || keys['KeyD']) { player.vel.x = stats.speed; player.facing = 1; }
        else if (keys['ArrowLeft'] || keys['KeyA']) { player.vel.x = -stats.speed; player.facing = -1; }
        else { player.vel.x *= 0.8; }

        if (e.unit === RobotUnit.FALCON) {
          if (keys['ArrowUp'] || keys['KeyW']) player.vel.y = -stats.speed;
          else if (keys['ArrowDown'] || keys['KeyS']) player.vel.y = stats.speed;
          else player.vel.y *= 0.8;
          player.grounded = false;
        } else {
          if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.grounded) {
            player.vel.y = stats.jump;
            player.grounded = false;
          }
          player.vel.y += GRAVITY;
        }
      }

      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;

      const floorY = 398;
      const ph = e.unit === RobotUnit.TITAN ? 80 : 48;
      if (player.pos.y > floorY - ph) { player.pos.y = floorY - ph; player.vel.y = 0; player.grounded = true; }
      if (player.pos.x < 0) player.pos.x = 0;
      setDistance(player.pos.x);

      // Weapons
      const fr = Math.max(5, stats.fireRate - upgrades.weaponTier * 2);
      if (!e.cinematic && keys['Space'] && e.frame - player.lastShot > fr) {
        soundService.playShoot();
        const dmg = e.unit === RobotUnit.TITAN ? 60 : (e.unit === RobotUnit.SPECTER ? 80 : 25);
        bullets.push({ 
          pos: { x: player.pos.x + (player.facing === 1 ? 32 : 0), y: player.pos.y + 15 }, 
          vel: { x: player.facing * (e.unit === RobotUnit.SPECTER ? 25 : 15), y: 0 }, 
          width: e.unit === RobotUnit.TITAN ? 15 : 8, 
          height: e.unit === RobotUnit.TITAN ? 8 : 4, 
          owner: 'player', 
          health: 1, maxHealth: 1, damage: dmg, color: stats.color 
        });
        player.lastShot = e.frame;
      }

      // Bullets update
      for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i]; b.pos.x += b.vel.x; b.pos.y += b.vel.y;
        if (Math.abs(b.pos.x - player.pos.x) > 1000) bullets.splice(i, 1);
      }

      // Enemy logic
      let allDead = true;
      enemies.forEach(en => {
        if (en.isDead) return;
        allDead = false;
        en.pos.x += en.vel.x;
        if (Math.random() < 0.01) en.vel.x *= -1;

        if (Math.abs(en.pos.x - player.pos.x) < 500 && e.frame - en.lastShot > 90) {
          bullets.push({ pos: {x: en.pos.x, y: en.pos.y + 15}, vel: {x: Math.sign(player.pos.x - en.pos.x) * 5, y: 0}, width: 8, height: 4, owner: 'enemy', health: 1, maxHealth: 1, damage: 10 });
          en.lastShot = e.frame;
        }

        bullets.forEach((b, idx) => {
          if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) {
            en.health -= b.damage || 20; bullets.splice(idx, 1);
            if (en.health <= 0) en.isDead = true;
          }
        });

        if (!player.invulnerable && player.pos.x < en.pos.x + en.width && player.pos.x + player.width > en.pos.x && player.pos.y < en.pos.y + en.height && player.pos.y + player.height > en.pos.y) {
           setHealth(h => h - 20); player.invulnerable = 60; soundService.playLose();
        }
      });

      if (health <= 0) onDie();
      if (allDead) onWin();

      if (player.invulnerable > 0) player.invulnerable--;
      e.cameraX = player.pos.x - CANVAS_WIDTH/3;
      if (e.cameraX < 0) e.cameraX = 0;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const e = engineRef.current;

      ctx.fillStyle = '#050510'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
      ctx.fillStyle = '#1c1c1c'; ctx.fillRect(0, 398, CANVAS_WIDTH, 52);

      e.enemies.forEach(en => { if(!en.isDead) {
        drawUnit(ctx, en.pos.x - e.cameraX, en.pos.y, en.width, en.height, RobotUnit.SENTINEL, -1, e.frame, true);
      }});

      const ph = e.unit === RobotUnit.TITAN ? 80 : 48;
      const pw = e.unit === RobotUnit.TITAN ? 64 : 32;
      drawUnit(ctx, e.player.pos.x - e.cameraX, e.player.pos.y, pw, ph, e.unit, e.player.facing, e.frame);

      e.bullets.forEach(b => { 
        ctx.fillStyle = b.color || (b.owner === 'player' ? '#00f3ff' : '#ff0055'); 
        ctx.fillRect(b.pos.x - e.cameraX, b.pos.y, b.width, b.height); 
      });
    };

    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [resetLevel, onWin, onDie, level, upgrades, currentUnit]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden">
      <div className="absolute top-4 left-4 z-10 space-y-2 pointer-events-none">
        <div className="bg-black/60 border border-cyan-500 p-3 rounded backdrop-blur">
          <div className="text-[10px] text-cyan-400 font-bold uppercase mb-1 flex justify-between">
            <span>{ROBOT_STATS[currentUnit].name} INTEGRITY</span>
            <span>{Math.round(health)}/{Math.round(maxHealth)}</span>
          </div>
          <div className="w-48 h-2 bg-gray-900 rounded-full overflow-hidden">
            <div className="h-full bg-cyan-500 shadow-[0_0_10px_cyan]" style={{ width: `${(health / maxHealth) * 100}%` }}></div>
          </div>
        </div>
        <div className="flex gap-2">
           {Object.keys(ROBOT_STATS).map((u, i) => (
             <div key={u} className={`w-8 h-8 flex items-center justify-center rounded border ${currentUnit === u ? 'border-white bg-white/20' : 'border-gray-700 bg-black/40'} text-[10px] font-bold`}>
               {i + 1}
             </div>
           ))}
        </div>
      </div>
      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full aspect-video shadow-2xl rounded-lg border-2 border-cyan-900/50" />
    </div>
  );
};

export default GameView;

import React from 'react';

interface MainMenuProps {
  onStart: () => void;
  onContinue: () => void;
  onOpenShop: () => void;
  onOpenLevelSelect: () => void;
  hasSave: boolean;
}

const MainMenu: React.FC<MainMenuProps> = ({ onStart, onContinue, onOpenShop, onOpenLevelSelect, hasSave }) => {
  return (
    <div className="h-full w-full flex flex-col items-center justify-center bg-gradient-to-b from-gray-950 to-blue-950 p-4">
      <div className="max-w-2xl text-center space-y-8">
        <div className="relative">
          <h1 className="text-7xl md:text-8xl font-black italic tracking-tighter text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 to-blue-600 drop-shadow-[0_0_20px_rgba(34,211,238,0.4)] font-orbitron">
            CYBER<span className="text-white">COP</span>
          </h1>
          <div className="absolute -top-4 -right-4 bg-red-600 text-white px-3 py-1 text-xs font-bold uppercase rotate-12 font-orbitron">
            SQUAD 5
          </div>
        </div>

        <p className="text-cyan-200 text-xl tracking-widest uppercase font-orbitron">Deploy the Squad. Neutralize the Rogue AI.</p>

        <div className="flex flex-col items-center space-y-4">
          {hasSave && (
            <button 
              onClick={onContinue}
              className="w-72 py-4 bg-cyan-600 hover:bg-cyan-500 text-white font-bold text-2xl border-b-4 border-cyan-900 transition-all transform hover:scale-105 active:scale-95 shadow-[0_0_15px_rgba(6,182,212,0.4)] font-orbitron"
            >
              CONTINUE MISSION
            </button>
          )}

          <div className="flex flex-col md:flex-row gap-4 w-72 md:w-auto">
            <button 
              onClick={onOpenLevelSelect}
              className="flex-none w-full md:w-32 py-4 bg-emerald-700 hover:bg-emerald-600 text-white font-bold text-2xl border-b-4 border-emerald-900 transition-all transform hover:scale-105 active:scale-95 shadow-[0_0_15px_rgba(16,185,129,0.3)] flex items-center justify-center font-orbitron"
              title="Select Sector"
            >
              LEVELS
            </button>

            <button 
              onClick={onStart}
              className={`flex-1 min-w-[18rem] py-4 text-white font-bold text-2xl transition-all transform hover:scale-105 active:scale-95 border-b-4 font-orbitron ${hasSave ? 'bg-gray-800 border-gray-950 hover:bg-gray-700' : 'bg-blue-600 border-blue-900 hover:bg-blue-500'}`}
            >
              {hasSave ? 'NEW GAME' : 'INITIALIZE SQUAD'}
            </button>

            <button 
              onClick={onOpenShop}
              className="flex-none w-full md:w-32 py-4 bg-yellow-600 hover:bg-yellow-500 text-white font-bold text-2xl border-b-4 border-yellow-800 transition-all transform hover:scale-105 active:scale-95 shadow-[0_0_15px_rgba(202,138,4,0.3)] flex items-center justify-center font-orbitron"
              title="Visit Cyber-Armory"
            >
              SHOP
            </button>
          </div>

          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-gray-400 text-[10px] pt-8 font-mono">
            <div className="flex flex-col items-center">
              <span className="bg-gray-800 px-2 py-1 rounded mb-1 border border-gray-700 text-white font-bold">WASD</span>
              <span>MOVE / JUMP</span>
            </div>
            <div className="flex flex-col items-center">
              <span className="bg-cyan-900 px-2 py-1 rounded mb-1 border border-cyan-700 text-cyan-400 font-bold">1-5</span>
              <span>SWITCH ROBOT</span>
            </div>
            <div className="flex flex-col items-center">
              <span className="bg-gray-800 px-2 py-1 rounded mb-1 border border-gray-700 text-white font-bold">SPACE</span>
              <span>FIRE WEAPON</span>
            </div>
            <div className="flex flex-col items-center">
              <span className="bg-gray-800 px-2 py-1 rounded mb-1 border border-gray-700 text-white font-bold">P</span>
              <span>PAUSE</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default MainMenu;

