  Hammer
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";

// Fix: Initialize the Gemini API client using the environment variable API_KEY
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Standard UI Components
const Button = ({ children, onClick, variant = 'primary', className = '', disabled = false }: any) => {
  const base = "px-6 py-2 rounded-lg font-semibold transition-all duration-200 flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed";
  const variants: any = {
    primary: "bg-blue-600 hover:bg-blue-500 text-white shadow-lg shadow-blue-900/20",
    secondary: "bg-slate-800 hover:bg-slate-700 text-slate-200 border border-slate-700",
    danger: "bg-red-600 hover:bg-red-500 text-white",
    success: "bg-emerald-600 hover:bg-emerald-500 text-white",
  };
  return (
    <button onClick={onClick} disabled={disabled} className={`${base} ${variants[variant]} ${className}`}>
      {children}
    </button>
  );
};

const Card = ({ children, className = "" }: any) => (
  <div className={`bg-slate-900 border border-slate-800 rounded-xl p-6 shadow-xl ${className}`}>
    {children}
  </div>
);

// State Machine types
type AppState = 'LEARN' | 'PRACTICE' | 'RESULTS';

interface Question {
  id: number;
  question: string;
  options: string[];
  correctAnswer: string;
  explanation: string;
}

const UNITS = [
  {
    id: 1,
    title: "Lathe Overview and Safety",
    content: `
      <h2 class="text-2xl font-bold text-blue-400 mb-4">What is a Lathe?</h2>
      <p class="mb-4">A <strong>lathe</strong> is a machine tool that rotates a workpiece about an axis of rotation to perform various operations such as cutting, sanding, knurling, drilling, deformation, facing, and turning, with tools that are applied to the workpiece to create an object with symmetry about that axis.</p>
      <p class="mb-6">In simpler terms, it's a machine that spins a piece of material (like metal or wood) very fast, and you use various tools to shape it while it's spinning.</p>

      <h2 class="text-2xl font-bold text-blue-400 mb-4">Why Use a Lathe?</h2>
      <ul class="list-disc pl-6 space-y-2 mb-6">
        <li><strong>Precision:</strong> High tolerances for perfect fit.</li>
        <li><strong>Efficiency:</strong> Rapid and accurate material removal.</li>
        <li><strong>Versatility:</strong> Wide range of tasks with different attachments.</li>
        <li><strong>Symmetry:</strong> Ideal for cylindrical and conical shapes.</li>
      </ul>

      <h2 class="text-2xl font-bold text-blue-400 mb-4">Types of Lathes</h2>
      <ul class="list-disc pl-6 space-y-2 mb-6">
        <li><strong>Engine Lathe:</strong> The common workhorse for various metalworking tasks.</li>
        <li><strong>Turret Lathe:</strong> Designed for mass production with multiple tool turrets.</li>
        <li><strong>CNC Lathe:</strong> Computer-controlled for extreme precision.</li>
        <li><strong>Wood Lathe:</strong> Specifically for woodworking.</li>
      </ul>

      <div class="bg-red-900/20 border-l-4 border-red-500 p-4 mb-6">
        <h2 class="text-xl font-bold text-red-400 mb-2 flex items-center gap-2">
          <ShieldAlert size={20} /> Lathe Safety
        </h2>
        <ul class="list-disc pl-5 space-y-1 text-red-100">
          <li>No loose clothing, jewelry, or long hair loose.</li>
          <li>ALWAYS wear ANSI-approved safety glasses.</li>
          <li>Never leave the machine running unattended.</li>
          <li><strong>CRITICAL:</strong> Remove the chuck key immediately after use.</li>
          <li>Use a brush or vacuum to remove chips, never your hands.</li>
        </ul>
      </div>
    `
  },
  {
    id: 2,
    title: "Basic Lathe Skills",
    content: `
      <h2 class="text-2xl font-bold text-blue-400 mb-4">Components of the Engine Lathe</h2>
      <div class="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
        <div><strong>Bed:</strong> The heavy horizontal foundation.</div>
        <div><strong>Headstock:</strong> Contains motor, gears, and spindle.</div>
        <div><strong>Chuck:</strong> Attached to spindle, holds workpiece.</div>
        <div><strong>Tailstock:</strong> Supports long pieces or holds drills.</div>
        <div><strong>Carriage:</strong> Carries the cutting tool along the bed.</div>
        <div><strong>Cross-slide:</strong> Moves tool perpendicular to the bed.</div>
        <div><strong>Compound Rest:</strong> Rotates for cutting angles.</div>
        <div><strong>Tool Post:</strong> Holds the cutting tool.</div>
      </div>

      <h2 class="text-2xl font-bold text-blue-400 mb-4">Basic Operations</h2>
      <ul class="list-decimal pl-6 space-y-4 mb-6">
        <li><strong>Mounting:</strong> Using a three-jaw chuck. Remember to remove the key!</li>
        <li><strong>Facing:</strong> Machining the end of a workpiece to make it flat and perpendicular.</li>
        <li><strong>Turning:</strong> Reducing diameter to create a cylindrical shape.</li>
        <li><strong>Drilling:</strong> Using the tailstock to create holes in the center.</li>
      </ul>
    `
  },
  {
    id: 3,
    title: "Advanced Lathe Skills",
    content: `
      <h2 class="text-2xl font-bold text-blue-400 mb-4">Tapering</h2>
      <p class="mb-4">Creating a conical shape where diameter changes along the length.</p>
      <ul class="list-disc pl-6 space-y-2 mb-6">
        <li><strong>Compound Rest:</strong> Short, steep tapers.</li>
        <li><strong>Offsetting Tailstock:</strong> Long, gradual tapers.</li>
        <li><strong>Taper Attachment:</strong> Automated tapering.</li>
      </ul>

      <h2 class="text-2xl font-bold text-blue-400 mb-4">Boring</h2>
      <p class="mb-6">Enlarging an existing hole or machining an internal cylindrical surface using a <strong>boring bar</strong>.</p>

      <h2 class="text-2xl font-bold text-blue-400 mb-4">Thread Cutting</h2>
      <p class="mb-4">Creating screw threads. A complex process requiring:</p>
      <ul class="list-disc pl-6 space-y-2 mb-6">
        <li>Calculating gear settings for pitch.</li>
        <li>Specialized 60-degree threading tool.</li>
        <li>Engaging the <strong>Half-Nut</strong> to couple carriage to leadscrew.</li>
        <li>Multiple light passes using the threading dial.</li>
      </ul>
    `
  }
];

export default function LatheMaster() {
  const [appState, setAppState] = useState<AppState>('LEARN');
  const [currentUnit, setCurrentUnit] = useState(0);
  const [quizQuestions, setQuizQuestions] = useState<Question[]>([]);
  const [currentQuestionIdx, setCurrentQuestionIdx] = useState(0);
  const [userAnswers, setUserAnswers] = useState<string[]>([]);
  const [isGeneratingQuiz, setIsGeneratingQuiz] = useState(false);
  const [isGeneratingImage, setIsGeneratingImage] = useState(false);
  const [rewardImage, setRewardImage] = useState<string | null>(null);
  const [quizError, setQuizError] = useState<string | null>(null);

  // Fix: use global ai instance to fetch quiz questions using recommended JSON schema
  const fetchQuiz = async () => {
    setIsGeneratingQuiz(true);
    setQuizError(null);
    try {
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `Generate 5 multiple choice questions about lathe safety, components, and operations based on the following training material: ${JSON.stringify(UNITS)}. Each question must have 4 options and one correct answer.`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              questions: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    id: { type: Type.INTEGER },
                    question: { type: Type.STRING },
                    options: { type: Type.ARRAY, items: { type: Type.STRING } },
                    correctAnswer: { type: Type.STRING },
                    explanation: { type: Type.STRING }
                  },
                  required: ["id", "question", "options", "correctAnswer", "explanation"]
                }
              }
            },
            required: ["questions"]
          }
        }
      });

      const data = JSON.parse(response.text || "{}");
      if (data.questions) {
        setQuizQuestions(data.questions as Question[]);
        setUserAnswers([]);
        setCurrentQuestionIdx(0);
      }
    } catch (err) {
      setQuizError("Failed to load quiz. Please check your API connection.");
      console.error(err);
    } finally {
      setIsGeneratingQuiz(false);
    }
  };

  // Fix: Implement native image generation using gemini-2.5-flash-image
  const generateReward = async () => {
    setIsGeneratingImage(true);
    try {
      const prompt = "A high-quality, professional photograph of a handmade brass hammer and a steel center punch resting on a machinist's workbench, industrial lighting, depth of field.";
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-image",
        contents: {
          parts: [{ text: prompt }]
        }
      });

      // Fix: Iterate through response parts to extract the inline image data
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) {
          const base64Data = part.inlineData.data;
          const mimeType = part.inlineData.mimeType || 'image/png';
          setRewardImage(`data:${mimeType};base64,${base64Data}`);
          break;
        }
      }
    } catch (err) {
      console.error("Reward generation failed:", err);
    } finally {
      setIsGeneratingImage(false);
    }
  };

  const handleAnswer = (answer: string) => {
    const newAnswers = [...userAnswers, answer];
    setUserAnswers(newAnswers);
    if (currentQuestionIdx < quizQuestions.length - 1) {
      setCurrentQuestionIdx(prev => prev + 1);
    } else {
      setAppState('RESULTS');
      const allCorrect = quizQuestions.every((q, idx) => newAnswers[idx] === q.correctAnswer);
      if (allCorrect) {
        generateReward();
      }
    }
  };

  const score = useMemo(() => {
    return userAnswers.reduce((acc, ans, idx) => {
      return ans === quizQuestions[idx]?.correctAnswer ? acc + 1 : acc;
    }, 0);
  }, [userAnswers, quizQuestions]);

  return (
    <div className="min-h-screen bg-slate-950 text-slate-200 p-4 md:p-8 font-sans">
      {/* Header */}
      <header className="max-w-5xl mx-auto mb-8 flex flex-col md:flex-row md:items-center justify-between gap-4 border-b border-slate-800 pb-6">
        <div className="flex items-center gap-3">
          <div className="p-3 bg-blue-600 rounded-lg shadow-lg shadow-blue-500/20">
            <Wrench className="text-white" size={28} />
          </div>
          <div>
            <h1 className="text-3xl font-black tracking-tight text-white font-orbitron">LATHE<span className="text-blue-500">MASTER</span></h1>
            <p className="text-slate-400 text-sm">Industrial Precision Training v1.0</p>
          </div>
        </div>

        <nav className="flex gap-2 bg-slate-900 p-1 rounded-xl border border-slate-800">
