import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;

// Robot-specific stats for Humanoid vs Alt-mode
const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { 
    name: "SENTINEL", color: '#00f3ff', hpMult: 1.0, 
    robot: { speed: 4, jump: -11, fireRate: 15 },
    alt: { speed: 8, jump: -5, fireRate: 25, type: 'Car' }
  },
  [RobotUnit.STRIKER]: { 
    name: "STRIKER", color: '#fbbf24', hpMult: 0.8,
    robot: { speed: 6, jump: -10, fireRate: 10 },
    alt: { speed: 12, jump: -4, fireRate: 20, type: 'Bike' }
  },
  [RobotUnit.FALCON]: { 
    name: "FALCON", color: '#22d3ee', hpMult: 0.7,
    robot: { speed: 5, jump: -10, fireRate: 12 },
    alt: { speed: 7, jump: -7, fireRate: 15, type: 'Jet' } // Jet has special flight physics
  },
  [RobotUnit.TITAN]: { 
    name: "TITAN", color: '#ef4444', hpMult: 2.5,
    robot: { speed: 2.5, jump: -12, fireRate: 30 },
    alt: { speed: 4, jump: 0, fireRate: 20, type: 'Tank' }
  },
  [RobotUnit.SPECTER]: { 
    name: "SPECTER", color: '#a855f7', hpMult: 0.6,
    robot: { speed: 5, jump: -11, fireRate: 20 },
    alt: { speed: 6, jump: -14, fireRate: 40, type: 'Sphere' }
  },
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [currentUnit, setCurrentUnit] = useState<RobotUnit>(RobotUnit.SENTINEL);
  const [isTransformed, setIsTransformed] = useState(false);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [distance, setDistance] = useState(0);

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      maxHealth: 100,
      isTransformed: false,
    },
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    unit: RobotUnit.SENTINEL,
    level: level,
  });

  useEffect(() => { engineRef.current.isPaused = isPaused; }, [isPaused]);
  useEffect(() => { 
    engineRef.current.unit = currentUnit;
    // When switching units, reset transformation for sanity
    engineRef.current.player.isTransformed = false;
    setIsTransformed(false);
  }, [currentUnit]);
  useEffect(() => { engineRef.current.level = level; }, [level]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff44');
    grad.addColorStop(1, '#00000088');
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.5)';
    ctx.stroke();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8;
    const armSwing = Math.cos(time) * 10;

    // Torso
    drawMechanicalPart(ctx, -12, -18, 24, 28, color, 4);
    // Head
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#222', 6);
    // Eyes
    ctx.fillStyle = isEnemy ? '#ff0000' : '#00f3ff';
    ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);

    // Arms
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#333', 2); // Back arm
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#333', 2);  // Front arm

    // Legs
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#222', 2);
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, color: string, frame: number) => {
    const time = frame * 0.2;
    switch(unit) {
      case RobotUnit.SENTINEL: // Police Sedan
        drawMechanicalPart(ctx, -24, -10, 48, 18, color, 8); // Body
        drawMechanicalPart(ctx, -16, -20, 30, 12, '#111', 4); // Roof
        // Wheels
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(-15, 10, 7, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(15, 10, 7, 0, Math.PI * 2); ctx.fill();
        // Light bar
        ctx.fillStyle = frame % 10 < 5 ? '#ff0000' : '#0000ff';
        ctx.fillRect(-4, -22, 10, 3);
        break;
      case RobotUnit.STRIKER: // Interceptor Bike
        drawMechanicalPart(ctx, -18, -8, 36, 12, color, 4);
        drawMechanicalPart(ctx, -5, -18, 18, 12, '#222', 2);
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(-18, 8, 9, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(18, 8, 9, 0, Math.PI * 2); ctx.fill();
        break;
      case RobotUnit.FALCON: // VTOL Jet
        drawMechanicalPart(ctx, -20, -10, 40, 15, color, 12);
        // Wings
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(-10, -5); ctx.lineTo(-30, -15); ctx.lineTo(-10, 5); ctx.fill();
        // Thruster
        ctx.fillStyle = '#ffaa00';
        ctx.fillRect(-28, -5, 8, 5);
        break;
      case RobotUnit.TITAN: // Heavy Tank
        drawMechanicalPart(ctx, -30, -10, 60, 22, color, 4);
        drawMechanicalPart(ctx, -15, -25, 30, 15, '#222', 4); // Turret
        drawMechanicalPart(ctx, 10, -20, 25, 5, '#444', 0); // Barrel
        // Tread details
        ctx.fillStyle = '#111';
        ctx.fillRect(-28, 8, 56, 6);
        break;
      case RobotUnit.SPECTER: // Stealth Sphere
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.arc(0, 0, 18, 0, Math.PI * 2); ctx.fill();
        ctx.strokeStyle = '#fff'; ctx.lineWidth = 1; ctx.stroke();
        // Eye
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(8, -4, 4, 0, Math.PI * 2); ctx.fill();
        break;
    }
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy = false, isInvuln = false, isTransformed = false) => {
    if (isInvuln && frame % 4 < 2) return;

    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    if (facing === -1) ctx.scale(-1, 1);

    const stats = ROBOT_STATS[unit];
    const color = isEnemy ? '#ff0055' : stats.color;

    if (isTransformed && !isEnemy) {
      drawAltMode(ctx, unit, color, frame);
    } else {
      drawHumanoid(ctx, color, frame, isEnemy);
    }

    ctx.restore();
  };

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    const stats = ROBOT_STATS[currentUnit];
    const baseHP = 100 + (upgrades.robotTier * 50);

    e.player.maxHealth = baseHP * stats.hpMult;
    setMaxHealth(e.player.maxHealth);
    setHealth(e.player.maxHealth);

    e.player.pos = { x: 100, y: 300 };
    e.player.vel = { x: 0, y: 0 };
    e.player.invulnerable = 0;
    e.player.isTransformed = false;
    setIsTransformed(false);
    e.bullets = [];
    e.cameraX = 0;
    setDistance(0);

    const enemies: Enemy[] = [];
    const floorY = 398;
    for (let i = 0; i < 4; i++) {
      enemies.push({ 
        id: i, 
        pos: { x: 800 + i * 600, y: floorY - 48 }, 
        vel: { x: (Math.random() - 0.5) * 3, y: 0 }, 
        width: 32, 
        height: 48, 
        health: 50 + level * 15, 
        maxHealth: 50 + level * 15, 
        isDead: false, 
        type: 'bot', 
        lastShot: 0 
      });
    }
    enemies.push({ 
      id: 4, 
      pos: { x: 3200, y: floorY - 96 }, 
      vel: { x: 0, y: 0 }, 
      width: 64, 
      height: 96, 
      health: 400 + level * 40, 
      maxHealth: 400 + level * 40, 
      isDead: false, 
      type: 'titan', 
      lastShot: 0 
    });
    e.enemies = enemies;
  }, [level, upgrades, currentUnit]);

  useEffect(() => {
    resetLevel();
    const handleKeyDown = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = true;
      if (e.code === 'Digit1') setCurrentUnit(RobotUnit.SENTINEL);
      if (e.code === 'Digit2') setCurrentUnit(RobotUnit.STRIKER);
      if (e.code === 'Digit3') setCurrentUnit(RobotUnit.FALCON);
      if (e.code === 'Digit4') setCurrentUnit(RobotUnit.TITAN);
      if (e.code === 'Digit5') setCurrentUnit(RobotUnit.SPECTER);

      if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') {
        engineRef.current.player.isTransformed = !engineRef.current.player.isTransformed;
        setIsTransformed(engineRef.current.player.isTransformed);
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => { engineRef.current.keys[e.code] = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!engineRef.current.isPaused) update();
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const e = engineRef.current;
      const { player, enemies, bullets, keys } = e;
      const stats = ROBOT_STATS[e.unit];
      const currentStats = player.isTransformed ? stats.alt : stats.robot;
      e.frame++;

      const ph = player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48);
      const pw = player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32);

      // Movement
      if (keys['ArrowRight'] || keys['KeyD']) { player.vel.x = currentStats.speed; player.facing = 1; }
      else if (keys['ArrowLeft'] || keys['KeyA']) { player.vel.x = -currentStats.speed; player.facing = -1; }
      else { player.vel.x *= 0.8; }

      // Flight / Jump logic
      const isFalconAlt = e.unit === RobotUnit.FALCON && player.isTransformed;
      if (isFalconAlt) {
        if (keys['ArrowUp'] || keys['KeyW']) player.vel.y = -currentStats.speed;
        else if (keys['ArrowDown'] || keys['KeyS']) player.vel.y = currentStats.speed;
        else player.vel.y *= 0.9;
        player.grounded = false;
      } else {
        if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.grounded) {
          player.vel.y = currentStats.jump;
          player.grounded = false;
        }
        player.vel.y += GRAVITY;
      }

      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;

      const floorY = 398;
      if (player.pos.y > floorY - ph) { 
        player.pos.y = floorY - ph; 
        player.vel.y = 0; 
        player.grounded = true; 
      }
      if (player.pos.x < 0) player.pos.x = 0;
      setDistance(player.pos.x);

      // Firing
      const fr = Math.max(5, currentStats.fireRate - upgrades.weaponTier * 2);
      if (keys['Space'] && e.frame - player.lastShot > fr) {
        soundService.playShoot();
        const dmg = player.isTransformed ? 40 : (e.unit === RobotUnit.TITAN ? 60 : (e.unit === RobotUnit.SPECTER ? 80 : 25));
        bullets.push({ 
          pos: { x: player.pos.x + (player.facing === 1 ? pw : 0), y: player.pos.y + ph/2 }, 
          vel: { x: player.facing * (e.unit === RobotUnit.SPECTER ? 25 : 15), y: 0 }, 
          width: player.isTransformed ? 12 : 8, 
          height: 4, 
          owner: 'player', 
          health: 1, maxHealth: 1, damage: dmg, color: stats.color 
        });
        player.lastShot = e.frame;
      }

      // Bullet Physics
      for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i]; 
        b.pos.x += b.vel.x; 
        b.pos.y += b.vel.y;

        if (b.owner === 'enemy' && !player.invulnerable) {
          if (b.pos.x < player.pos.x + pw && b.pos.x + b.width > player.pos.x &&
              b.pos.y < player.pos.y + ph && b.pos.y + b.height > player.pos.y) {
            setHealth(h => Math.max(0, h - (b.damage || 10)));
            player.invulnerable = 40;
            bullets.splice(i, 1);
            soundService.playLose();
            continue;
          }
        }

        if (Math.abs(b.pos.x - player.pos.x) > 1000) {
          bullets.splice(i, 1);
        }
      }

      // Enemy Logic
      let allDead = true;
      enemies.forEach(en => {
        if (en.isDead) return;
        allDead = false;
        en.pos.x += en.vel.x;

        if (Math.abs(en.pos.x - player.pos.x) < 500 && e.frame - en.lastShot > 100) {
          bullets.push({ 
            pos: { x: en.pos.x, y: en.pos.y + 15 }, 
            vel: { x: Math.sign(player.pos.x - en.pos.x) * 5, y: 0 }, 
            width: 10, height: 6, 
            owner: 'enemy', 
            health: 1, maxHealth: 1, 
            damage: 15, 
            color: '#ff0055' 
          });
          en.lastShot = e.frame;
        }

        bullets.forEach((b, idx) => {
          if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) {
            en.health -= b.damage || 20; 
            bullets.splice(idx, 1);
            if (en.health <= 0) en.isDead = true;
          }
        });

        if (!player.invulnerable && player.pos.x < en.pos.x + en.width && player.pos.x + pw > en.pos.x && player.pos.y < en.pos.y + en.height && player.pos.y + ph > en.pos.y) {
           setHealth(h => Math.max(0, h - 25)); 
           player.invulnerable = 60; 
           soundService.playLose();
        }
      });

      if (health <= 0) onDie();
      if (allDead) onWin();
      if (player.invulnerable > 0) player.invulnerable--;
      e.cameraX = player.pos.x - CANVAS_WIDTH/3;
      if (e.cameraX < 0) e.cameraX = 0;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const e = engineRef.current;
      ctx.fillStyle = '#050510'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

      // Grid floor
      ctx.fillStyle = '#1c1c1c'; ctx.fillRect(0, 398, CANVAS_WIDTH, 52);
      ctx.strokeStyle = '#222';
      for(let i=0; i<CANVAS_WIDTH; i+=40) {
        ctx.beginPath(); ctx.moveTo(i - (e.cameraX % 40), 398); ctx.lineTo(i - (e.cameraX % 40), CANVAS_HEIGHT); ctx.stroke();
      }

      e.enemies.forEach(en => { 
        if(!en.isDead) drawUnit(ctx, en.pos.x - e.cameraX, en.pos.y, en.width, en.height, RobotUnit.SENTINEL, -1, e.frame, true); 
      });

      const player = e.player;
      const ph = player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48);
      const pw = player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32);

      drawUnit(ctx, player.pos.x - e.cameraX, player.pos.y, pw, ph, e.unit, player.facing, e.frame, false, player.invulnerable > 0, player.isTransformed);

      e.bullets.forEach(b => { 
        ctx.fillStyle = b.color || (b.owner === 'player' ? '#00f3ff' : '#ff0055'); 
        ctx.fillRect(b.pos.x - e.cameraX, b.pos.y, b.width, b.height); 
      });
    };

    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [resetLevel, onWin, onDie, level, upgrades, health, currentUnit]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden">
      <div className="absolute top-4 left-4 z-10 space-y-4 pointer-events-none">
        {/* Integrity Bar */}
        <div className="bg-black/80 border border-cyan-500/50 p-3 rounded backdrop-blur-md shadow-lg">
          <div className="text-[10px] text-cyan-400 font-bold uppercase mb-1 flex justify-between font-orbitron">
            <span>{ROBOT_STATS[currentUnit].name} INTEGRITY</span>
            <span>{Math.round(health)}/{Math.round(maxHealth)}</span>
          </div>
          <div className="w-48 h-2.5 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
            <div 
              className="h-full shadow-[0_0_15px_#00f3ff] transition-all duration-300" 
              style={{ 
                width: `${(health / maxHealth) * 100}%`,
                backgroundColor: health < maxHealth * 0.3 ? '#ef4444' : '#00f3ff'
              }} 
            />
          </div>
          <div className="mt-2 text-[8px] text-white/50 font-mono flex justify-between">
            <span>MODE: {isTransformed ? `ALT (${ROBOT_STATS[currentUnit].alt.type})` : 'HUMANOID'}</span>
            <span className="animate-pulse">[SHIFT TO TOGGLE]</span>
          </div>
        </div>

        {/* Improved Robot Selector */}
        <div className="flex flex-col gap-2 pointer-events-auto">
           <div className="text-[10px] text-white/50 font-bold uppercase tracking-tighter ml-1 font-orbitron">SQUAD_DEPLOYMENT [1-5]</div>
           <div className="flex gap-2">
           {(Object.keys(ROBOT_STATS) as RobotUnit[]).map((u, i) => {
             const stats = ROBOT_STATS[u];
             const isActive = currentUnit === u;
             return (
               <button 
                 key={u} 
                 onClick={() => setCurrentUnit(u)}
                 className={`group relative w-12 h-12 flex flex-col items-center justify-center rounded-sm border-2 transition-all duration-200 ${
                   isActive 
                     ? 'bg-white/10' 
                     : 'border-gray-800 bg-black/60 hover:border-gray-600'
                 }`}
                 style={{
                   borderColor: isActive ? stats.color : '',
                   boxShadow: isActive ? `0 0 20px ${stats.color}50, inset 0 0 8px ${stats.color}30` : 'none'
                 }}
               >
                 {isActive && (
                   <>
                     <div className="absolute -top-1.5 -left-1.5 w-3 h-3 border-t-2 border-l-2" style={{ borderColor: stats.color }} />
                     <div className="absolute -bottom-1.5 -right-1.5 w-3 h-3 border-b-2 border-r-2" style={{ borderColor: stats.color }} />
                   </>
                 )}

                 <span className={`text-xl font-black font-orbitron transition-colors ${isActive ? 'text-white' : 'text-gray-600'}`}>
                   {i + 1}
                 </span>

                 <div className={`absolute -bottom-8 px-2 py-0.5 rounded bg-black/90 border border-gray-700 text-[8px] font-bold uppercase tracking-widest text-white transition-opacity whitespace-nowrap ${isActive ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}>
                    {stats.name}
                 </div>

                 {isActive && (
                    <div className="absolute -top-4 left-1/2 -translate-x-1/2 w-1.5 h-1.5 bg-white rounded-full animate-ping" />
                 )}
               </button>
             );
           })}
           </div>
        </div>
      </div>

      <div className="absolute top-4 right-4 z-10 text-right pointer-events-none font-orbitron">
        <div className="text-[10px] text-cyan-500 font-bold uppercase tracking-widest">Active Sector</div>
        <div className="text-3xl font-black text-white italic drop-shadow-md">{level.toString().padStart(2, '0')}</div>
      </div>

      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full aspect-video shadow-2xl rounded-lg border-2 border-cyan-900/50" />

      {health < maxHealth * 0.3 && (
        <div className="absolute inset-0 pointer-events-none border-[16px] border-red-600/20 animate-pulse shadow-[inset_0_0_100px_rgba(239,68,68,0.3)]"></div>
      )}

      {/* Controls Overlay for new players */}
      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 pointer-events-none text-white/30 text-[9px] font-mono tracking-widest uppercase flex gap-8">
        <span>WASD: Move</span>
        <span>Space: Fire</span>
        <span>Shift: Transform</span>
        <span>1-5: Switch Squad</span>
      </div>
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { 
    name: "SENTINEL", color: '#00f3ff', hpMult: 1.0, 
    robot: { speed: 4, jump: -11, fireRate: 15 },
    alt: { speed: 8, jump: -5, fireRate: 25, type: 'Car' }
  },
  [RobotUnit.STRIKER]: { 
    name: "STRIKER", color: '#fbbf24', hpMult: 0.8,
    robot: { speed: 6, jump: -10, fireRate: 10 },
    alt: { speed: 12, jump: -4, fireRate: 20, type: 'Bike' }
  },
  [RobotUnit.FALCON]: { 
    name: "FALCON", color: '#22d3ee', hpMult: 0.7,
    robot: { speed: 5, jump: -10, fireRate: 12 },
    alt: { speed: 7, jump: -7, fireRate: 15, type: 'Jet' }
  },
  [RobotUnit.TITAN]: { 
    name: "TITAN", color: '#ef4444', hpMult: 2.5,
    robot: { speed: 2.5, jump: -12, fireRate: 30 },
    alt: { speed: 4, jump: 0, fireRate: 20, type: 'Tank' }
  },
  [RobotUnit.SPECTER]: { 
    name: "SPECTER", color: '#a855f7', hpMult: 0.6,
    robot: { speed: 5, jump: -11, fireRate: 20 },
    alt: { speed: 6, jump: -14, fireRate: 40, type: 'Sphere' }
  },
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [currentUnit, setCurrentUnit] = useState<RobotUnit>(RobotUnit.SENTINEL);
  const [isTransformed, setIsTransformed] = useState(false);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [distance, setDistance] = useState(0);

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      maxHealth: 100,
      isTransformed: false,
    },
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    unit: RobotUnit.SENTINEL,
    level: level,
  });

  useEffect(() => { engineRef.current.isPaused = isPaused; }, [isPaused]);
  useEffect(() => { 
    engineRef.current.unit = currentUnit;
    engineRef.current.player.isTransformed = false;
    setIsTransformed(false);
  }, [currentUnit]);
  useEffect(() => { engineRef.current.level = level; }, [level]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff44');
    grad.addColorStop(1, '#00000088');
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.5)';
    ctx.stroke();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, type = 'bot') => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8;
    const armSwing = Math.cos(time) * 10;

    // Scale enemy visuals slightly based on type
    let scale = 1;
    if (type === 'scout') scale = 0.8;
    if (type === 'heavy' || type === 'titan') scale = 1.4;

    ctx.save();
    ctx.scale(scale, scale);

    // Torso
    drawMechanicalPart(ctx, -12, -18, 24, 28, color, 4);
    // Head
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#222', 6);
    // Eyes
    ctx.fillStyle = isEnemy ? (type === 'sniper' ? '#fff' : '#ff0000') : '#00f3ff';
    ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);

    // Arms
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#333', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#333', 2);

    // Legs
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#222', 2);

    ctx.restore();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, color: string, frame: number) => {
    switch(unit) {
      case RobotUnit.SENTINEL:
        drawMechanicalPart(ctx, -24, -10, 48, 18, color, 8);
        drawMechanicalPart(ctx, -16, -20, 30, 12, '#111', 4);
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(-15, 10, 7, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(15, 10, 7, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = frame % 10 < 5 ? '#ff0000' : '#0000ff';
        ctx.fillRect(-4, -22, 10, 3);
        break;
      case RobotUnit.STRIKER:
        drawMechanicalPart(ctx, -18, -8, 36, 12, color, 4);
        drawMechanicalPart(ctx, -5, -18, 18, 12, '#222', 2);
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(-18, 8, 9, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(18, 8, 9, 0, Math.PI * 2); ctx.fill();
        break;
      case RobotUnit.FALCON:
        drawMechanicalPart(ctx, -20, -10, 40, 15, color, 12);
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(-10, -5); ctx.lineTo(-30, -15); ctx.lineTo(-10, 5); ctx.fill();
        ctx.fillStyle = '#ffaa00';
        ctx.fillRect(-28, -5, 8, 5);
        break;
      case RobotUnit.TITAN:
        drawMechanicalPart(ctx, -30, -10, 60, 22, color, 4);
        drawMechanicalPart(ctx, -15, -25, 30, 15, '#222', 4);
        drawMechanicalPart(ctx, 10, -20, 25, 5, '#444', 0);
        ctx.fillStyle = '#111';
        ctx.fillRect(-28, 8, 56, 6);
        break;
      case RobotUnit.SPECTER:
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.arc(0, 0, 18, 0, Math.PI * 2); ctx.fill();
        ctx.strokeStyle = '#fff'; ctx.lineWidth = 1; ctx.stroke();
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(8, -4, 4, 0, Math.PI * 2); ctx.fill();
        break;
    }
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy = false, isInvuln = false, isTransformed = false, type = 'bot') => {
    if (isInvuln && frame % 4 < 2) return;

    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    if (facing === -1) ctx.scale(-1, 1);

    const stats = ROBOT_STATS[unit];
    const color = isEnemy ? '#ff0055' : stats.color;

    if (isTransformed && !isEnemy) {
      drawAltMode(ctx, unit, color, frame);
    } else {
      drawHumanoid(ctx, color, frame, isEnemy, type);
    }

    ctx.restore();
  };

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    const stats = ROBOT_STATS[currentUnit];
    const baseHP = 100 + (upgrades.robotTier * 50);

    e.player.maxHealth = baseHP * stats.hpMult;
    setMaxHealth(e.player.maxHealth);
    setHealth(e.player.maxHealth);

    e.player.pos = { x: 100, y: 300 };
    e.player.vel = { x: 0, y: 0 };
    e.player.invulnerable = 0;
    e.player.isTransformed = false;
    setIsTransformed(false);
    e.bullets = [];
    e.cameraX = 0;
    setDistance(0);

    const enemies: Enemy[] = [];
    const floorY = 398;

    // Level difficulty scaling
    const enemyTypes = ['bot', 'scout', 'sniper', 'heavy'];
    for (let i = 0; i < 4; i++) {
      const type = enemyTypes[i % (level < 5 ? 1 : level < 10 ? 2 : 4)];
      let w = 32, h = 48, hp = 50 + level * 15;
      if (type === 'scout') { w = 24; h = 36; hp = 40 + level * 5; }
      if (type === 'heavy') { w = 48; h = 72; hp = 150 + level * 20; }

      enemies.push({ 
        id: i, 
        pos: { x: 800 + i * 700, y: floorY - h }, 
        vel: { x: 0, y: 0 }, 
        width: w, 
        height: h, 
        health: hp, 
        maxHealth: hp, 
        isDead: false, 
        type: type, 
        lastShot: 0,
        sequenceStage: 0,
        sequenceTimer: 0
      });
    }

    // Boss at end of level
    enemies.push({ 
      id: 4, 
      pos: { x: 4000, y: floorY - 96 }, 
      vel: { x: 0, y: 0 }, 
      width: 80, 
      height: 96, 
      health: 500 + level * 50, 
      maxHealth: 500 + level * 50, 
      isDead: false, 
      type: 'titan', 
      lastShot: 0 
    });
    e.enemies = enemies;
  }, [level, upgrades, currentUnit]);

  useEffect(() => {
    resetLevel();
    const handleKeyDown = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = true;
      if (e.code === 'Digit1') setCurrentUnit(RobotUnit.SENTINEL);
      if (e.code === 'Digit2') setCurrentUnit(RobotUnit.STRIKER);
      if (e.code === 'Digit3') setCurrentUnit(RobotUnit.FALCON);
      if (e.code === 'Digit4') setCurrentUnit(RobotUnit.TITAN);
      if (e.code === 'Digit5') setCurrentUnit(RobotUnit.SPECTER);

      if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') {
        engineRef.current.player.isTransformed = !engineRef.current.player.isTransformed;
        setIsTransformed(engineRef.current.player.isTransformed);
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => { engineRef.current.keys[e.code] = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!engineRef.current.isPaused) update();
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const e = engineRef.current;
      const { player, enemies, bullets, keys } = e;
      const stats = ROBOT_STATS[e.unit];
      const currentStats = player.isTransformed ? stats.alt : stats.robot;
      e.frame++;

      const ph = player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48);
      const pw = player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32);

      // Player Movement
      if (keys['ArrowRight'] || keys['KeyD']) { player.vel.x = currentStats.speed; player.facing = 1; }
      else if (keys['ArrowLeft'] || keys['KeyA']) { player.vel.x = -currentStats.speed; player.facing = -1; }
      else { player.vel.x *= 0.8; }

      if (e.unit === RobotUnit.FALCON && player.isTransformed) {
        if (keys['ArrowUp'] || keys['KeyW']) player.vel.y = -currentStats.speed;
        else if (keys['ArrowDown'] || keys['KeyS']) player.vel.y = currentStats.speed;
        else player.vel.y *= 0.9;
        player.grounded = false;
      } else {
        if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.grounded) {
          player.vel.y = currentStats.jump;
          player.grounded = false;
        }
        player.vel.y += GRAVITY;
      }

      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;

      const floorY = 398;
      if (player.pos.y > floorY - ph) { 
        player.pos.y = floorY - ph; 
        player.vel.y = 0; 
        player.grounded = true; 
      }
      if (player.pos.x < 0) player.pos.x = 0;
      setDistance(player.pos.x);

      // Player Firing
      const fr = Math.max(5, currentStats.fireRate - upgrades.weaponTier * 2);
      if (keys['Space'] && e.frame - player.lastShot > fr) {
        soundService.playShoot();
        const dmg = player.isTransformed ? 40 : (e.unit === RobotUnit.TITAN ? 60 : (e.unit === RobotUnit.SPECTER ? 80 : 25));
        bullets.push({ 
          pos: { x: player.pos.x + (player.facing === 1 ? pw : 0), y: player.pos.y + ph/2 }, 
          vel: { x: player.facing * (e.unit === RobotUnit.SPECTER ? 25 : 15), y: 0 }, 
          width: player.isTransformed ? 12 : 8, 
          height: 4, 
          owner: 'player', 
          health: 1, maxHealth: 1, damage: dmg, color: stats.color 
        });
        player.lastShot = e.frame;
      }

      // Bullet Physics
      for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i]; 
        b.pos.x += b.vel.x; 
        b.pos.y += b.vel.y;

        if (b.owner === 'enemy' && !player.invulnerable) {
          if (b.pos.x < player.pos.x + pw && b.pos.x + b.width > player.pos.x &&
              b.pos.y < player.pos.y + ph && b.pos.y + b.height > player.pos.y) {
            setHealth(h => Math.max(0, h - (b.damage || 10)));
            player.invulnerable = 40;
            bullets.splice(i, 1);
            soundService.playLose();
            continue;
          }
        }

        if (Math.abs(b.pos.x - player.pos.x) > 1200) {
          bullets.splice(i, 1);
        }
      }

      // ENEMY AI ENHANCEMENTS
      let allDead = true;
      enemies.forEach(en => {
        if (en.isDead) return;
        allDead = false;

        const dist = Math.abs(en.pos.x - player.pos.x);
        const dir = Math.sign(player.pos.x - en.pos.x);
        const hpPercent = en.health / en.maxHealth;

        // Positioning Logic
        switch(en.type) {
          case 'bot':
            if (dist > 350) en.vel.x = dir * 2;
            else if (dist < 200) en.vel.x = -dir * 2;
            else en.vel.x *= 0.8;
            break;
          case 'scout':
            en.vel.x = dir * 4; // Aggressive
            break;
          case 'sniper':
            if (dist < 500) en.vel.x = -dir * 3; // Keep distance
            else en.vel.x *= 0.5;
            break;
          case 'heavy':
          case 'titan':
            en.vel.x = dir * 1; // Slow advance
            break;
        }

        // Low health retreat behavior (Coordinated retreat)
        if (hpPercent < 0.3 && en.type !== 'scout') {
          en.vel.x = -dir * 3;
        }

        en.pos.x += en.vel.x;

        // Attack Pattern Logic
        if (dist < 600) {
          const cooldown = en.type === 'heavy' ? 120 : en.type === 'scout' ? 60 : en.type === 'sniper' ? 180 : 100;

          if (e.frame - en.lastShot > cooldown) {
            switch(en.type) {
              case 'bot':
                // Simple shot
                bullets.push({ pos: {x: en.pos.x, y: en.pos.y + 15}, vel: {x: dir * 6, y: 0}, width: 10, height: 4, owner: 'enemy', health: 1, maxHealth: 1, damage: 10, color: '#f00' });
                en.lastShot = e.frame;
                break;
              case 'scout':
                // Burst fire (3 quick shots)
                if (en.sequenceStage < 3) {
                   if (e.frame % 10 === 0) {
                      bullets.push({ pos: {x: en.pos.x, y: en.pos.y + 10}, vel: {x: dir * 8, y: 0}, width: 6, height: 3, owner: 'enemy', health: 1, maxHealth: 1, damage: 5, color: '#f55' });
                      en.sequenceStage++;
                   }
                } else {
                   en.sequenceStage = 0;
                   en.lastShot = e.frame;
                }
                break;
              case 'sniper':
                // High speed rail shot
                bullets.push({ pos: {x: en.pos.x, y: en.pos.y + 10}, vel: {x: dir * 14, y: 0}, width: 16, height: 2, owner: 'enemy', health: 1, maxHealth: 1, damage: 30, color: '#fff' });
                en.lastShot = e.frame;
                break;
              case 'heavy':
              case 'titan':
                // Spread shot
                for(let j=-1; j<=1; j++) {
                  bullets.push({ pos: {x: en.pos.x, y: en.pos.y + 30}, vel: {x: dir * 5, y: j * 1}, width: 12, height: 8, owner: 'enemy', health: 1, maxHealth: 1, damage: 20, color: '#f00' });
                }
                en.lastShot = e.frame;
                break;
            }
          }
        }

        // Damage calculation (Player to Enemy)
        bullets.forEach((b, idx) => {
          if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) {
            en.health -= b.damage || 20; 
            bullets.splice(idx, 1);
            if (en.health <= 0) en.isDead = true;
          }
        });

        // Collision calculation
        if (!player.invulnerable && player.pos.x < en.pos.x + en.width && player.pos.x + pw > en.pos.x && player.pos.y < en.pos.y + en.height && player.pos.y + ph > en.pos.y) {
           setHealth(h => Math.max(0, h - (en.type === 'heavy' ? 40 : 25))); 
           player.invulnerable = 60; 
           soundService.playLose();
        }
      });

      if (health <= 0) onDie();
      if (allDead) onWin();
      if (player.invulnerable > 0) player.invulnerable--;
      e.cameraX = player.pos.x - CANVAS_WIDTH/3;
      if (e.cameraX < 0) e.cameraX = 0;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const e = engineRef.current;
      ctx.fillStyle = '#050510'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

      // Grid floor
      ctx.fillStyle = '#1c1c1c'; ctx.fillRect(0, 398, CANVAS_WIDTH, 52);
      ctx.strokeStyle = '#222';
      for(let i=0; i<CANVAS_WIDTH; i+=40) {
        ctx.beginPath(); ctx.moveTo(i - (e.cameraX % 40), 398); ctx.lineTo(i - (e.cameraX % 40), CANVAS_HEIGHT); ctx.stroke();
      }

      e.enemies.forEach(en => { 
        if(!en.isDead) drawUnit(ctx, en.pos.x - e.cameraX, en.pos.y, en.width, en.height, RobotUnit.SENTINEL, Math.sign(e.player.pos.x - en.pos.x), e.frame, true, false, false, en.type); 
      });

      const player = e.player;
      const ph = player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48);
      const pw = player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32);

      drawUnit(ctx, player.pos.x - e.cameraX, player.pos.y, pw, ph, e.unit, player.facing, e.frame, false, player.invulnerable > 0, player.isTransformed);

      e.bullets.forEach(b => { 
        ctx.fillStyle = b.color || (b.owner === 'player' ? '#00f3ff' : '#ff0055'); 
        ctx.fillRect(b.pos.x - e.cameraX, b.pos.y, b.width, b.height); 
      });
    };

    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [resetLevel, onWin, onDie, level, upgrades, health, currentUnit]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden">
      <div className="absolute top-4 left-4 z-10 space-y-4 pointer-events-none">
        {/* Integrity Bar */}
        <div className="bg-black/80 border border-cyan-500/50 p-3 rounded backdrop-blur-md shadow-lg">
          <div className="text-[10px] text-cyan-400 font-bold uppercase mb-1 flex justify-between font-orbitron">
            <span>{ROBOT_STATS[currentUnit].name} INTEGRITY</span>
            <span>{Math.round(health)}/{Math.round(maxHealth)}</span>
          </div>
          <div className="w-48 h-2.5 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
            <div 
              className="h-full shadow-[0_0_15px_#00f3ff] transition-all duration-300" 
              style={{ 
                width: `${(health / maxHealth) * 100}%`,
                backgroundColor: health < maxHealth * 0.3 ? '#ef4444' : '#00f3ff'
              }} 
            />
          </div>
          <div className="mt-2 text-[8px] text-white/50 font-mono flex justify-between">
            <span>MODE: {isTransformed ? `ALT (${ROBOT_STATS[currentUnit].alt.type})` : 'HUMANOID'}</span>
            <span className="animate-pulse">[SHIFT TO TOGGLE]</span>
          </div>
        </div>

        {/* Improved Robot Selector */}
        <div className="flex flex-col gap-2 pointer-events-auto">
           <div className="text-[10px] text-white/50 font-bold uppercase tracking-tighter ml-1 font-orbitron">SQUAD_DEPLOYMENT [1-5]</div>
           <div className="flex gap-2">
           {(Object.keys(ROBOT_STATS) as RobotUnit[]).map((u, i) => {
             const stats = ROBOT_STATS[u];
             const isActive = currentUnit === u;
             return (
               <button 
                 key={u} 
                 onClick={() => setCurrentUnit(u)}
                 className={`group relative w-12 h-12 flex flex-col items-center justify-center rounded-sm border-2 transition-all duration-200 ${
                   isActive 
                     ? 'bg-white/10' 
                     : 'border-gray-800 bg-black/60 hover:border-gray-600'
                 }`}
                 style={{
                   borderColor: isActive ? stats.color : '',
                   boxShadow: isActive ? `0 0 20px ${stats.color}50, inset 0 0 8px ${stats.color}30` : 'none'
                 }}
               >
                 {isActive && (
                   <>
                     <div className="absolute -top-1.5 -left-1.5 w-3 h-3 border-t-2 border-l-2" style={{ borderColor: stats.color }} />
                     <div className="absolute -bottom-1.5 -right-1.5 w-3 h-3 border-b-2 border-r-2" style={{ borderColor: stats.color }} />
                   </>
                 )}
                 <span className={`text-xl font-black font-orbitron transition-colors ${isActive ? 'text-white' : 'text-gray-600'}`}>
                   {i + 1}
                 </span>
                 <div className={`absolute -bottom-8 px-2 py-0.5 rounded bg-black/90 border border-gray-700 text-[8px] font-bold uppercase tracking-widest text-white transition-opacity whitespace-nowrap ${isActive ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}>
                    {stats.name}
                 </div>
                 {isActive && (
                    <div className="absolute -top-4 left-1/2 -translate-x-1/2 w-1.5 h-1.5 bg-white rounded-full animate-ping" />
                 )}
               </button>
             );
           })}
           </div>
        </div>
      </div>

      <div className="absolute top-4 right-4 z-10 text-right pointer-events-none font-orbitron">
        <div className="text-[10px] text-cyan-500 font-bold uppercase tracking-widest">Active Sector</div>
        <div className="text-3xl font-black text-white italic drop-shadow-md">{level.toString().padStart(2, '0')}</div>
      </div>

      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full aspect-video shadow-2xl rounded-lg border-2 border-cyan-900/50" />

      {health < maxHealth * 0.3 && (
        <div className="absolute inset-0 pointer-events-none border-[16px] border-red-600/20 animate-pulse shadow-[inset_0_0_100px_rgba(239,68,68,0.3)]"></div>
      )}

      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 pointer-events-none text-white/30 text-[9px] font-mono tracking-widest uppercase flex gap-8">
        <span>WASD: Move</span>
        <span>Space: Fire</span>
        <span>Shift: Transform</span>
        <span>1-5: Switch Squad</span>
      </div>
    </div>
  );
};

export default GameView;

export enum GameState {
  MENU = 'MENU',
  BRIEFING = 'BRIEFING',
  PLAYING = 'PLAYING',
  PAUSED = 'PAUSED',
  GAMEOVER = 'GAMEOVER',
  VICTORY = 'VICTORY',
  LEVEL_COMPLETE = 'LEVEL_COMPLETE',
  SHOP = 'SHOP',
  LEVEL_SELECT = 'LEVEL_SELECT'
}

export enum RobotUnit {
  SENTINEL = 'SENTINEL',
  STRIKER = 'STRIKER',
  FALCON = 'FALCON',
  TITAN = 'TITAN',
  SPECTER = 'SPECTER'
}

export interface LevelInfo {
  level: number;
  title: string;
  description: string;
  threatLevel: string;
  enemyType: string;
}

export interface Upgrades {
  robotTier: number;
  weaponTier: number;
}

export interface Vector {
  x: number;
  y: number;
}

export interface Entity {
  pos: Vector;
  vel: Vector;
  width: number;
  height: number;
  health: number;
  maxHealth: number;
}

export interface Bullet extends Entity {
  owner: 'player' | 'enemy';
  damage?: number;
  color?: string;
}

export interface Enemy extends Entity {
  id: number;
  isDead: boolean;
  type: string;
  lastShot: number;
  hasSplit?: boolean;
  sequenceStage?: number;
  sequenceTimer?: number;
  isTransformed?: boolean;
  transformTimer?: number;
}

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { 
    name: "SENTINEL", color: '#00f3ff', hpMult: 1.0, 
    robot: { speed: 4, jump: -11, fireRate: 15 },
    alt: { speed: 8, jump: -5, fireRate: 25, type: 'Car' }
  },
  [RobotUnit.STRIKER]: { 
    name: "STRIKER", color: '#fbbf24', hpMult: 0.8,
    robot: { speed: 6, jump: -10, fireRate: 10 },
    alt: { speed: 12, jump: -4, fireRate: 20, type: 'Bike' }
  },
  [RobotUnit.FALCON]: { 
    name: "FALCON", color: '#22d3ee', hpMult: 0.7,
    robot: { speed: 5, jump: -10, fireRate: 12 },
    alt: { speed: 7, jump: -7, fireRate: 15, type: 'Jet' }
  },
  [RobotUnit.TITAN]: { 
    name: "TITAN", color: '#ef4444', hpMult: 2.5,
    robot: { speed: 2.5, jump: -12, fireRate: 30 },
    alt: { speed: 4, jump: 0, fireRate: 20, type: 'Tank' }
  },
  [RobotUnit.SPECTER]: { 
    name: "SPECTER", color: '#a855f7', hpMult: 0.6,
    robot: { speed: 5, jump: -11, fireRate: 20 },
    alt: { speed: 6, jump: -14, fireRate: 40, type: 'Sphere' }
  },
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [currentUnit, setCurrentUnit] = useState<RobotUnit>(RobotUnit.SENTINEL);
  const [isTransformed, setIsTransformed] = useState(false);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [distance, setDistance] = useState(0);

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      maxHealth: 100,
      isTransformed: false,
    },
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    unit: RobotUnit.SENTINEL,
    level: level,
  });

  useEffect(() => { engineRef.current.isPaused = isPaused; }, [isPaused]);
  useEffect(() => { 
    engineRef.current.unit = currentUnit;
    engineRef.current.player.isTransformed = false;
    setIsTransformed(false);
  }, [currentUnit]);
  useEffect(() => { engineRef.current.level = level; }, [level]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff44');
    grad.addColorStop(1, '#00000088');
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.5)';
    ctx.stroke();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, type = 'bot', isTransformed = false) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8;
    const armSwing = Math.cos(time) * 10;

    let scale = 1;
    if (type === 'scout') scale = 0.8;
    if (type === 'heavy' || type === 'titan') scale = 1.4;

    // Transformed enemies are larger and vibrate
    if (isEnemy && isTransformed) {
      scale *= 1.2;
      ctx.translate((Math.random() - 0.5) * 2, (Math.random() - 0.5) * 2);
    }

    ctx.save();
    ctx.scale(scale, scale);

    // Transformed glow
    if (isEnemy && isTransformed) {
      ctx.shadowBlur = 15;
      ctx.shadowColor = '#ff0000';
    }

    // Torso
    drawMechanicalPart(ctx, -12, -18, 24, 28, isTransformed ? '#500' : color, 4);
    // Head
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#222', 6);
    // Eyes
    ctx.fillStyle = isEnemy ? (type === 'sniper' ? '#fff' : (isTransformed ? '#fff' : '#ff0000')) : '#00f3ff';
    ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);

    // Arms
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#333', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#333', 2);

    // Legs
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#222', 2);

    // Core energy for transformed units
    if (isEnemy && isTransformed) {
      ctx.fillStyle = frame % 6 < 3 ? '#ff0000' : '#ffffff';
      ctx.beginPath();
      ctx.arc(0, -4, 4 + Math.sin(frame * 0.3) * 2, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.restore();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, color: string, frame: number) => {
    switch(unit) {
      case RobotUnit.SENTINEL:
        drawMechanicalPart(ctx, -24, -10, 48, 18, color, 8);
        drawMechanicalPart(ctx, -16, -20, 30, 12, '#111', 4);
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(-15, 10, 7, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(15, 10, 7, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = frame % 10 < 5 ? '#ff0000' : '#0000ff';
        ctx.fillRect(-4, -22, 10, 3);
        break;
      case RobotUnit.STRIKER:
        drawMechanicalPart(ctx, -18, -8, 36, 12, color, 4);
        drawMechanicalPart(ctx, -5, -18, 18, 12, '#222', 2);
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(-18, 8, 9, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(18, 8, 9, 0, Math.PI * 2); ctx.fill();
        break;
      case RobotUnit.FALCON:
        drawMechanicalPart(ctx, -20, -10, 40, 15, color, 12);
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(-10, -5); ctx.lineTo(-30, -15); ctx.lineTo(-10, 5); ctx.fill();
        ctx.fillStyle = '#ffaa00';
        ctx.fillRect(-28, -5, 8, 5);
        break;
      case RobotUnit.TITAN:
        drawMechanicalPart(ctx, -30, -10, 60, 22, color, 4);
        drawMechanicalPart(ctx, -15, -25, 30, 15, '#222', 4);
        drawMechanicalPart(ctx, 10, -20, 25, 5, '#444', 0);
        ctx.fillStyle = '#111';
        ctx.fillRect(-28, 8, 56, 6);
        break;
      case RobotUnit.SPECTER:
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.arc(0, 0, 18, 0, Math.PI * 2); ctx.fill();
        ctx.strokeStyle = '#fff'; ctx.lineWidth = 1; ctx.stroke();
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(8, -4, 4, 0, Math.PI * 2); ctx.fill();
        break;
    }
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy = false, isInvuln = false, isTransformed = false, type = 'bot') => {
    if (isInvuln && frame % 4 < 2) return;

    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    if (facing === -1) ctx.scale(-1, 1);

    const stats = ROBOT_STATS[unit];
    const color = isEnemy ? '#ff0055' : stats.color;

    if (isTransformed && !isEnemy) {
      drawAltMode(ctx, unit, color, frame);
    } else {
      drawHumanoid(ctx, color, frame, isEnemy, type, isTransformed);
    }

    ctx.restore();
  };

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    const stats = ROBOT_STATS[currentUnit];
    const baseHP = 100 + (upgrades.robotTier * 50);

    e.player.maxHealth = baseHP * stats.hpMult;
    setMaxHealth(e.player.maxHealth);
    setHealth(e.player.maxHealth);

    e.player.pos = { x: 100, y: 300 };
    e.player.vel = { x: 0, y: 0 };
    e.player.invulnerable = 0;
    e.player.isTransformed = false;
    setIsTransformed(false);
    e.bullets = [];
    e.cameraX = 0;
    setDistance(0);

    const enemies: Enemy[] = [];
    const floorY = 398;

    const enemyTypes = ['bot', 'scout', 'sniper', 'heavy'];
    for (let i = 0; i < 4; i++) {
      const type = enemyTypes[i % (level < 5 ? 1 : level < 10 ? 2 : 4)];
      let w = 32, h = 48, hp = 50 + level * 15;
      if (type === 'scout') { w = 24; h = 36; hp = 40 + level * 5; }
      if (type === 'heavy') { w = 48; h = 72; hp = 150 + level * 20; }

      enemies.push({ 
        id: i, 
        pos: { x: 800 + i * 700, y: floorY - h }, 
        vel: { x: 0, y: 0 }, 
        width: w, 
        height: h, 
        health: hp, 
        maxHealth: hp, 
        isDead: false, 
        type: type, 
        lastShot: 0,
        sequenceStage: 0,
        sequenceTimer: 0,
        isTransformed: false,
        transformTimer: 0
      });
    }

    enemies.push({ 
      id: 4, 
      pos: { x: 4000, y: floorY - 96 }, 
      vel: { x: 0, y: 0 }, 
      width: 80, 
      height: 96, 
      health: 500 + level * 50, 
      maxHealth: 500 + level * 50, 
      isDead: false, 
      type: 'titan', 
      lastShot: 0,
      isTransformed: false
    });
    e.enemies = enemies;
  }, [level, upgrades, currentUnit]);

  useEffect(() => {
    resetLevel();
    const handleKeyDown = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = true;
      if (e.code === 'Digit1') setCurrentUnit(RobotUnit.SENTINEL);
      if (e.code === 'Digit2') setCurrentUnit(RobotUnit.STRIKER);
      if (e.code === 'Digit3') setCurrentUnit(RobotUnit.FALCON);
      if (e.code === 'Digit4') setCurrentUnit(RobotUnit.TITAN);
      if (e.code === 'Digit5') setCurrentUnit(RobotUnit.SPECTER);

      if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') {
        engineRef.current.player.isTransformed = !engineRef.current.player.isTransformed;
        setIsTransformed(engineRef.current.player.isTransformed);
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => { engineRef.current.keys[e.code] = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!engineRef.current.isPaused) update();
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const e = engineRef.current;
      const { player, enemies, bullets, keys } = e;
      const stats = ROBOT_STATS[e.unit];
      const currentStats = player.isTransformed ? stats.alt : stats.robot;
      e.frame++;

      const ph = player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48);
      const pw = player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32);

      if (keys['ArrowRight'] || keys['KeyD']) { player.vel.x = currentStats.speed; player.facing = 1; }
      else if (keys['ArrowLeft'] || keys['KeyA']) { player.vel.x = -currentStats.speed; player.facing = -1; }
      else { player.vel.x *= 0.8; }

      if (e.unit === RobotUnit.FALCON && player.isTransformed) {
        if (keys['ArrowUp'] || keys['KeyW']) player.vel.y = -currentStats.speed;
        else if (keys['ArrowDown'] || keys['KeyS']) player.vel.y = currentStats.speed;
        else player.vel.y *= 0.9;
        player.grounded = false;
      } else {
        if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.grounded) {
          player.vel.y = currentStats.jump;
          player.grounded = false;
        }
        player.vel.y += GRAVITY;
      }

      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;

      const floorY = 398;
      if (player.pos.y > floorY - ph) { 
        player.pos.y = floorY - ph; 
        player.vel.y = 0; 
        player.grounded = true; 
      }
      if (player.pos.x < 0) player.pos.x = 0;
      setDistance(player.pos.x);

      const fr = Math.max(5, currentStats.fireRate - upgrades.weaponTier * 2);
      if (keys['Space'] && e.frame - player.lastShot > fr) {
        soundService.playShoot();
        const dmg = player.isTransformed ? 40 : (e.unit === RobotUnit.TITAN ? 60 : (e.unit === RobotUnit.SPECTER ? 80 : 25));
        bullets.push({ 
          pos: { x: player.pos.x + (player.facing === 1 ? pw : 0), y: player.pos.y + ph/2 }, 
          vel: { x: player.facing * (e.unit === RobotUnit.SPECTER ? 25 : 15), y: 0 }, 
          width: player.isTransformed ? 12 : 8, 
          height: 4, 
          owner: 'player', 
          health: 1, maxHealth: 1, damage: dmg, color: stats.color 
        });
        player.lastShot = e.frame;
      }

      for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i]; 
        b.pos.x += b.vel.x; 
        b.pos.y += b.vel.y;

        if (b.owner === 'enemy' && !player.invulnerable) {
          if (b.pos.x < player.pos.x + pw && b.pos.x + b.width > player.pos.x &&
              b.pos.y < player.pos.y + ph && b.pos.y + b.height > player.pos.y) {
            setHealth(h => Math.max(0, h - (b.damage || 10)));
            player.invulnerable = 40;
            bullets.splice(i, 1);
            soundService.playLose();
            continue;
          }
        }

        if (Math.abs(b.pos.x - player.pos.x) > 1200) {
          bullets.splice(i, 1);
        }
      }

      let allDead = true;
      enemies.forEach(en => {
        if (en.isDead) return;
        allDead = false;

        const dist = Math.abs(en.pos.x - player.pos.x);
        const dir = Math.sign(player.pos.x - en.pos.x);
        const hpPercent = en.health / en.maxHealth;

        // CHECK FOR ENEMY TRANSFORMATION
        if (hpPercent < 0.3 && !en.isTransformed) {
          en.isTransformed = true;
          en.transformTimer = 30; // Brief logic delay for visual impact if needed
          // Boosted stats on transformation
          en.width *= 1.2;
          en.height *= 1.2;
        }

        const moveMult = en.isTransformed ? 1.8 : 1.0;

        // Positioning Logic
        switch(en.type) {
          case 'bot':
            if (dist > 350) en.vel.x = dir * 2 * moveMult;
            else if (dist < 200) en.vel.x = -dir * 2 * moveMult;
            else en.vel.x *= 0.8;
            break;
          case 'scout':
            en.vel.x = dir * 4 * moveMult;
            break;
          case 'sniper':
            if (dist < 500) en.vel.x = -dir * 3 * moveMult;
            else en.vel.x *= 0.5;
            break;
          case 'heavy':
          case 'titan':
            en.vel.x = dir * 1 * moveMult;
            break;
        }

        if (hpPercent < 0.3 && en.type !== 'scout' && !en.isTransformed) {
          en.vel.x = -dir * 3;
        }

        en.pos.x += en.vel.x;

        if (dist < 600) {
          const rawCooldown = en.type === 'heavy' ? 120 : en.type === 'scout' ? 60 : en.type === 'sniper' ? 180 : 100;
          const cooldown = en.isTransformed ? rawCooldown * 0.5 : rawCooldown;

          if (e.frame - en.lastShot > cooldown) {
            switch(en.type) {
              case 'bot':
                bullets.push({ pos: {x: en.pos.x, y: en.pos.y + 15}, vel: {x: dir * (en.isTransformed ? 10 : 6), y: 0}, width: 10, height: 4, owner: 'enemy', health: 1, maxHealth: 1, damage: en.isTransformed ? 15 : 10, color: '#f00' });
                en.lastShot = e.frame;
                break;
              case 'scout':
                if (en.sequenceStage < (en.isTransformed ? 5 : 3)) {
                   if (e.frame % (en.isTransformed ? 5 : 10) === 0) {
                      bullets.push({ pos: {x: en.pos.x, y: en.pos.y + 10}, vel: {x: dir * (en.isTransformed ? 12 : 8), y: 0}, width: 6, height: 3, owner: 'enemy', health: 1, maxHealth: 1, damage: 5, color: '#f55' });
                      en.sequenceStage++;
                   }
                } else {
                   en.sequenceStage = 0;
                   en.lastShot = e.frame;
                }
                break;
              case 'sniper':
                bullets.push({ pos: {x: en.pos.x, y: en.pos.y + 10}, vel: {x: dir * 14, y: 0}, width: 16, height: 2, owner: 'enemy', health: 1, maxHealth: 1, damage: 30, color: '#fff' });
                en.lastShot = e.frame;
                break;
              case 'heavy':
              case 'titan':
                const numBullets = en.isTransformed ? 5 : 3;
                for(let j=-(numBullets>>1); j<=(numBullets>>1); j++) {
                  bullets.push({ pos: {x: en.pos.x, y: en.pos.y + 30}, vel: {x: dir * 5, y: j * (en.isTransformed ? 1.5 : 1)}, width: 12, height: 8, owner: 'enemy', health: 1, maxHealth: 1, damage: 20, color: '#f00' });
                }
                en.lastShot = e.frame;
                break;
            }
          }
        }

        bullets.forEach((b, idx) => {
          if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) {
            en.health -= b.damage || 20; 
            bullets.splice(idx, 1);
            if (en.health <= 0) en.isDead = true;
          }
        });

        if (!player.invulnerable && player.pos.x < en.pos.x + en.width && player.pos.x + pw > en.pos.x && player.pos.y < en.pos.y + en.height && player.pos.y + ph > en.pos.y) {
           setHealth(h => Math.max(0, h - (en.type === 'heavy' ? 40 : 25))); 
           player.invulnerable = 60; 
           soundService.playLose();
        }
      });

      if (health <= 0) onDie();
      if (allDead) onWin();
      if (player.invulnerable > 0) player.invulnerable--;
      e.cameraX = player.pos.x - CANVAS_WIDTH/3;
      if (e.cameraX < 0) e.cameraX = 0;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const e = engineRef.current;
      ctx.fillStyle = '#050510'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

      ctx.fillStyle = '#1c1c1c'; ctx.fillRect(0, 398, CANVAS_WIDTH, 52);
      ctx.strokeStyle = '#222';
      for(let i=0; i<CANVAS_WIDTH; i+=40) {
        ctx.beginPath(); ctx.moveTo(i - (e.cameraX % 40), 398); ctx.lineTo(i - (e.cameraX % 40), CANVAS_HEIGHT); ctx.stroke();
      }

      e.enemies.forEach(en => { 
        if(!en.isDead) drawUnit(ctx, en.pos.x - e.cameraX, en.pos.y, en.width, en.height, RobotUnit.SENTINEL, Math.sign(e.player.pos.x - en.pos.x), e.frame, true, false, en.isTransformed, en.type); 
      });

      const player = e.player;
      const ph = player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48);
      const pw = player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32);

      drawUnit(ctx, player.pos.x - e.cameraX, player.pos.y, pw, ph, e.unit, player.facing, e.frame, false, player.invulnerable > 0, player.isTransformed);

      e.bullets.forEach(b => { 
        ctx.fillStyle = b.color || (b.owner === 'player' ? '#00f3ff' : '#ff0055'); 
        ctx.fillRect(b.pos.x - e.cameraX, b.pos.y, b.width, b.height); 
      });
    };

    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [resetLevel, onWin, onDie, level, upgrades, health, currentUnit]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden">
      <div className="absolute top-4 left-4 z-10 space-y-4 pointer-events-none">
        <div className="bg-black/80 border border-cyan-500/50 p-3 rounded backdrop-blur-md shadow-lg">
          <div className="text-[10px] text-cyan-400 font-bold uppercase mb-1 flex justify-between font-orbitron">
            <span>{ROBOT_STATS[currentUnit].name} INTEGRITY</span>
            <span>{Math.round(health)}/{Math.round(maxHealth)}</span>
          </div>
          <div className="w-48 h-2.5 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
            <div 
              className="h-full shadow-[0_0_15px_#00f3ff] transition-all duration-300" 
              style={{ 
                width: `${(health / maxHealth) * 100}%`,
                backgroundColor: health < maxHealth * 0.3 ? '#ef4444' : '#00f3ff'
              }} 
            />
          </div>
          <div className="mt-2 text-[8px] text-white/50 font-mono flex justify-between">
            <span>MODE: {isTransformed ? `ALT (${ROBOT_STATS[currentUnit].alt.type})` : 'HUMANOID'}</span>
            <span className="animate-pulse">[SHIFT TO TOGGLE]</span>
          </div>
        </div>

        <div className="flex flex-col gap-2 pointer-events-auto">
           <div className="text-[10px] text-white/50 font-bold uppercase tracking-tighter ml-1 font-orbitron">SQUAD_DEPLOYMENT [1-5]</div>
           <div className="flex gap-2">
           {(Object.keys(ROBOT_STATS) as RobotUnit[]).map((u, i) => {
             const stats = ROBOT_STATS[u];
             const isActive = currentUnit === u;
             return (
               <button 
                 key={u} 
                 onClick={() => setCurrentUnit(u)}
                 className={`group relative w-12 h-12 flex flex-col items-center justify-center rounded-sm border-2 transition-all duration-200 ${
                   isActive 
                     ? 'bg-white/10' 
                     : 'border-gray-800 bg-black/60 hover:border-gray-600'
                 }`}
                 style={{
                   borderColor: isActive ? stats.color : '',
                   boxShadow: isActive ? `0 0 20px ${stats.color}50, inset 0 0 8px ${stats.color}30` : 'none'
                 }}
               >
                 {isActive && (
                   <>
                     <div className="absolute -top-1.5 -left-1.5 w-3 h-3 border-t-2 border-l-2" style={{ borderColor: stats.color }} />
                     <div className="absolute -bottom-1.5 -right-1.5 w-3 h-3 border-b-2 border-r-2" style={{ borderColor: stats.color }} />
                   </>
                 )}
                 <span className={`text-xl font-black font-orbitron transition-colors ${isActive ? 'text-white' : 'text-gray-600'}`}>
                   {i + 1}
                 </span>
                 <div className={`absolute -bottom-8 px-2 py-0.5 rounded bg-black/90 border border-gray-700 text-[8px] font-bold uppercase tracking-widest text-white transition-opacity whitespace-nowrap ${isActive ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}>
                    {stats.name}
                 </div>
                 {isActive && (
                    <div className="absolute -top-4 left-1/2 -translate-x-1/2 w-1.5 h-1.5 bg-white rounded-full animate-ping" />
                 )}
               </button>
             );
           })}
           </div>
        </div>
      </div>

      <div className="absolute top-4 right-4 z-10 text-right pointer-events-none font-orbitron">
        <div className="text-[10px] text-cyan-500 font-bold uppercase tracking-widest">Active Sector</div>
        <div className="text-3xl font-black text-white italic drop-shadow-md">{level.toString().padStart(2, '0')}</div>
      </div>

      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full aspect-video shadow-2xl rounded-lg border-2 border-cyan-900/50" />

      {health < maxHealth * 0.3 && (
        <div className="absolute inset-0 pointer-events-none border-[16px] border-red-600/20 animate-pulse shadow-[inset_0_0_100px_rgba(239,68,68,0.3)]"></div>
      )}

      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 pointer-events-none text-white/30 text-[9px] font-mono tracking-widest uppercase flex gap-8">
        <span>WASD: Move</span>
        <span>Space: Fire</span>
        <span>Shift: Transform</span>
        <span>1-5: Switch Squad</span>
      </div>
    </div>
  );
};

export default GameView;

export enum GameState {
  MENU = 'MENU',
  BRIEFING = 'BRIEFING',
  PLAYING = 'PLAYING',
  PAUSED = 'PAUSED',
  GAMEOVER = 'GAMEOVER',
  VICTORY = 'VICTORY',
  LEVEL_COMPLETE = 'LEVEL_COMPLETE',
  SHOP = 'SHOP',
  LEVEL_SELECT = 'LEVEL_SELECT'
}

export enum RobotUnit {
  SENTINEL = 'SENTINEL',
  STRIKER = 'STRIKER',
  FALCON = 'FALCON',
  TITAN = 'TITAN',
  SPECTER = 'SPECTER'
}

export interface LevelInfo {
  level: number;
  title: string;
  description: string;
  threatLevel: string;
  enemyType: string;
}

export interface Upgrades {
  robotTier: number;
  weaponTier: number;
}

export interface Vector {
  x: number;
  y: number;
}

export interface Entity {
  pos: Vector;
  vel: Vector;
  width: number;
  height: number;
  health: number;
  maxHealth: number;
}

export interface Bullet extends Entity {
  owner: 'player' | 'enemy';
  damage?: number;
  color?: string;
}

export interface Enemy extends Entity {
  id: number;
  isDead: boolean;
  type: string;
  lastShot: number;
  hasSplit?: boolean;
  sequenceStage?: number;
  sequenceTimer?: number;
  isTransformed?: boolean;
  transformTimer?: number;
}

import React from 'react';
import { createRoot } from 'react-dom/client';
import App from './App';

const container = document.getElementById('root');
if (container) {
  const root = createRoot(container);
  root.render(<App />);
}

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { 
    name: "SENTINEL", color: '#00f3ff', hpMult: 1.0, 
    robot: { speed: 4, jump: -11, fireRate: 15 },
    alt: { speed: 8, jump: -5, fireRate: 25, type: 'Car' }
  },
  [RobotUnit.STRIKER]: { 
    name: "STRIKER", color: '#fbbf24', hpMult: 0.8,
    robot: { speed: 6, jump: -10, fireRate: 10 },
    alt: { speed: 12, jump: -4, fireRate: 20, type: 'Bike' }
  },
  [RobotUnit.FALCON]: { 
    name: "FALCON", color: '#22d3ee', hpMult: 0.7,
    robot: { speed: 5, jump: -10, fireRate: 12 },
    alt: { speed: 7, jump: -7, fireRate: 15, type: 'Jet' }
  },
  [RobotUnit.TITAN]: { 
    name: "TITAN", color: '#ef4444', hpMult: 2.5,
    robot: { speed: 2.5, jump: -12, fireRate: 30 },
    alt: { speed: 4, jump: 0, fireRate: 20, type: 'Tank' }
  },
  [RobotUnit.SPECTER]: { 
    name: "SPECTER", color: '#a855f7', hpMult: 0.6,
    robot: { speed: 5, jump: -11, fireRate: 20 },
    alt: { speed: 6, jump: -14, fireRate: 40, type: 'Sphere' }
  },
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [currentUnit, setCurrentUnit] = useState<RobotUnit>(RobotUnit.SENTINEL);
  const [isTransformed, setIsTransformed] = useState(false);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [distance, setDistance] = useState(0);

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      maxHealth: 100,
      isTransformed: false,
    },
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    unit: RobotUnit.SENTINEL,
    level: level,
  });

  useEffect(() => { engineRef.current.isPaused = isPaused; }, [isPaused]);
  useEffect(() => { 
    engineRef.current.unit = currentUnit;
    engineRef.current.player.isTransformed = false;
    setIsTransformed(false);
  }, [currentUnit]);
  useEffect(() => { engineRef.current.level = level; }, [level]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff44');
    grad.addColorStop(1, '#00000088');
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.5)';
    ctx.stroke();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, type = 'bot', isTransformed = false) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8;
    const armSwing = Math.cos(time) * 10;

    let scale = 1;
    if (type === 'scout') scale = 0.8;
    if (type === 'heavy' || type === 'titan') scale = 1.4;

    // Transformed visual buffs
    if (isEnemy && isTransformed) {
      scale *= 1.25;
      // Vibration effect
      ctx.translate((Math.random() - 0.5) * 3, (Math.random() - 0.5) * 3);
    }

    ctx.save();
    ctx.scale(scale, scale);

    if (isEnemy && isTransformed) {
      ctx.shadowBlur = 20;
      ctx.shadowColor = '#ff3300';
    }

    // Torso
    drawMechanicalPart(ctx, -12, -18, 24, 28, isTransformed ? '#400' : color, 4);
    // Head
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    // Eyes
    ctx.fillStyle = isEnemy ? (isTransformed ? '#fff' : '#ff0000') : '#00f3ff';
    ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);

    // Arms
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);

    // Legs
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);

    // Core Overdrive Core
    if (isEnemy && isTransformed) {
      const corePulse = Math.sin(frame * 0.4) * 3;
      ctx.fillStyle = frame % 4 < 2 ? '#ff0000' : '#ffffff';
      ctx.beginPath();
      ctx.arc(0, -5, 5 + corePulse, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.restore();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, color: string, frame: number) => {
    switch(unit) {
      case RobotUnit.SENTINEL:
        drawMechanicalPart(ctx, -24, -10, 48, 18, color, 8);
        drawMechanicalPart(ctx, -16, -20, 30, 12, '#111', 4);
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(-15, 10, 7, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(15, 10, 7, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = frame % 10 < 5 ? '#ff0000' : '#0000ff';
        ctx.fillRect(-4, -22, 10, 3);
        break;
      case RobotUnit.STRIKER:
        drawMechanicalPart(ctx, -18, -8, 36, 12, color, 4);
        drawMechanicalPart(ctx, -5, -18, 18, 12, '#222', 2);
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(-18, 8, 9, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(18, 8, 9, 0, Math.PI * 2); ctx.fill();
        break;
      case RobotUnit.FALCON:
        drawMechanicalPart(ctx, -20, -10, 40, 15, color, 12);
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(-10, -5); ctx.lineTo(-30, -15); ctx.lineTo(-10, 5); ctx.fill();
        ctx.fillStyle = '#ffaa00';
        ctx.fillRect(-28, -5, 8, 5);
        break;
      case RobotUnit.TITAN:
        drawMechanicalPart(ctx, -30, -10, 60, 22, color, 4);
        drawMechanicalPart(ctx, -15, -25, 30, 15, '#222', 4);
        drawMechanicalPart(ctx, 10, -20, 25, 5, '#444', 0);
        ctx.fillStyle = '#111';
        ctx.fillRect(-28, 8, 56, 6);
        break;
      case RobotUnit.SPECTER:
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.arc(0, 0, 18, 0, Math.PI * 2); ctx.fill();
        ctx.strokeStyle = '#fff'; ctx.lineWidth = 1; ctx.stroke();
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(8, -4, 4, 0, Math.PI * 2); ctx.fill();
        break;
    }
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy = false, isInvuln = false, isTransformed = false, type = 'bot') => {
    if (isInvuln && frame % 4 < 2) return;

    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    if (facing === -1) ctx.scale(-1, 1);

    const stats = ROBOT_STATS[unit];
    const color = isEnemy ? '#ff0055' : stats.color;

    if (isTransformed && !isEnemy) {
      drawAltMode(ctx, unit, color, frame);
    } else {
      drawHumanoid(ctx, color, frame, isEnemy, type, isTransformed);
    }

    ctx.restore();
  };

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    const stats = ROBOT_STATS[currentUnit];
    const baseHP = 100 + (upgrades.robotTier * 50);

    e.player.maxHealth = baseHP * stats.hpMult;
    setMaxHealth(e.player.maxHealth);
    setHealth(e.player.maxHealth);

    e.player.pos = { x: 100, y: 300 };
    e.player.vel = { x: 0, y: 0 };
    e.player.invulnerable = 0;
    e.player.isTransformed = false;
    setIsTransformed(false);
    e.bullets = [];
    e.cameraX = 0;
    setDistance(0);

    const enemies: Enemy[] = [];
    const floorY = 398;

    const enemyTypes = ['bot', 'scout', 'sniper', 'heavy'];
    for (let i = 0; i < 4; i++) {
      const type = enemyTypes[i % (level < 5 ? 1 : level < 10 ? 2 : 4)];
      let w = 32, h = 48, hp = 50 + level * 15;
      if (type === 'scout') { w = 24; h = 36; hp = 40 + level * 5; }
      if (type === 'heavy') { w = 48; h = 72; hp = 150 + level * 20; }

      enemies.push({ 
        id: i, 
        pos: { x: 800 + i * 700, y: floorY - h }, 
        vel: { x: 0, y: 0 }, 
        width: w, 
        height: h, 
        health: hp, 
        maxHealth: hp, 
        isDead: false, 
        type: type, 
        lastShot: 0,
        sequenceStage: 0,
        sequenceTimer: 0,
        isTransformed: false,
        transformTimer: 0
      });
    }

    enemies.push({ 
      id: 4, 
      pos: { x: 4000, y: floorY - 96 }, 
      vel: { x: 0, y: 0 }, 
      width: 80, 
      height: 96, 
      health: 500 + level * 50, 
      maxHealth: 500 + level * 50, 
      isDead: false, 
      type: 'titan', 
      lastShot: 0,
      isTransformed: false
    });
    e.enemies = enemies;
  }, [level, upgrades, currentUnit]);

  useEffect(() => {
    resetLevel();
    const handleKeyDown = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = true;
      if (e.code === 'Digit1') setCurrentUnit(RobotUnit.SENTINEL);
      if (e.code === 'Digit2') setCurrentUnit(RobotUnit.STRIKER);
      if (e.code === 'Digit3') setCurrentUnit(RobotUnit.FALCON);
      if (e.code === 'Digit4') setCurrentUnit(RobotUnit.TITAN);
      if (e.code === 'Digit5') setCurrentUnit(RobotUnit.SPECTER);

      if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') {
        engineRef.current.player.isTransformed = !engineRef.current.player.isTransformed;
        setIsTransformed(engineRef.current.player.isTransformed);
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => { engineRef.current.keys[e.code] = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!engineRef.current.isPaused) update();
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const e = engineRef.current;
      const { player, enemies, bullets, keys } = e;
      const stats = ROBOT_STATS[e.unit];
      const currentStats = player.isTransformed ? stats.alt : stats.robot;
      e.frame++;

      const ph = player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48);
      const pw = player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32);

      // Player Movement
      if (keys['ArrowRight'] || keys['KeyD']) { player.vel.x = currentStats.speed; player.facing = 1; }
      else if (keys['ArrowLeft'] || keys['KeyA']) { player.vel.x = -currentStats.speed; player.facing = -1; }
      else { player.vel.x *= 0.8; }

      if (e.unit === RobotUnit.FALCON && player.isTransformed) {
        if (keys['ArrowUp'] || keys['KeyW']) player.vel.y = -currentStats.speed;
        else if (keys['ArrowDown'] || keys['KeyS']) player.vel.y = currentStats.speed;
        else player.vel.y *= 0.9;
        player.grounded = false;
      } else {
        if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.grounded) {
          player.vel.y = currentStats.jump;
          player.grounded = false;
        }
        player.vel.y += GRAVITY;
      }

      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;

      const floorY = 398;
      if (player.pos.y > floorY - ph) { 
        player.pos.y = floorY - ph; 
        player.vel.y = 0; 
        player.grounded = true; 
      }
      if (player.pos.x < 0) player.pos.x = 0;
      setDistance(player.pos.x);

      // Player Firing
      const fr = Math.max(5, currentStats.fireRate - upgrades.weaponTier * 2);
      if (keys['Space'] && e.frame - player.lastShot > fr) {
        soundService.playShoot();
        const dmg = player.isTransformed ? 40 : (e.unit === RobotUnit.TITAN ? 60 : (e.unit === RobotUnit.SPECTER ? 80 : 25));
        bullets.push({ 
          pos: { x: player.pos.x + (player.facing === 1 ? pw : 0), y: player.pos.y + ph/2 }, 
          vel: { x: player.facing * (e.unit === RobotUnit.SPECTER ? 25 : 15), y: 0 }, 
          width: player.isTransformed ? 12 : 8, 
          height: 4, 
          owner: 'player', 
          health: 1, maxHealth: 1, damage: dmg, color: stats.color 
        });
        player.lastShot = e.frame;
      }

      // Bullet Physics
      for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i]; 
        b.pos.x += b.vel.x; 
        b.pos.y += b.vel.y;

        if (b.owner === 'enemy' && !player.invulnerable) {
          if (b.pos.x < player.pos.x + pw && b.pos.x + b.width > player.pos.x &&
              b.pos.y < player.pos.y + ph && b.pos.y + b.height > player.pos.y) {
            setHealth(h => Math.max(0, h - (b.damage || 10)));
            player.invulnerable = 40;
            bullets.splice(i, 1);
            soundService.playLose();
            continue;
          }
        }

        if (Math.abs(b.pos.x - player.pos.x) > 1200) {
          bullets.splice(i, 1);
        }
      }

      // Enemy AI with Transformation Mechanic
      let allDead = true;
      enemies.forEach(en => {
        if (en.isDead) return;
        allDead = false;

        const dist = Math.abs(en.pos.x - player.pos.x);
        const dir = Math.sign(player.pos.x - en.pos.x);
        const hpPercent = en.health / en.maxHealth;

        // CHECK TRANSFORMATION: ENEMY OVERDRIVE AT < 30% HP
        if (hpPercent < 0.3 && !en.isTransformed) {
          en.isTransformed = true;
          en.width *= 1.3;
          en.height *= 1.3;
          // One-time health boost or shield can be added here if desired
        }

        const moveMult = en.isTransformed ? 2.2 : 1.0;

        // Positioning Logic
        switch(en.type) {
          case 'bot':
            if (dist > 350) en.vel.x = dir * 2 * moveMult;
            else if (dist < 200) en.vel.x = -dir * 2 * moveMult;
            else en.vel.x *= 0.8;
            break;
          case 'scout':
            en.vel.x = dir * 4 * moveMult;
            break;
          case 'sniper':
            if (dist < 500) en.vel.x = -dir * 3 * moveMult;
            else en.vel.x *= 0.5;
            break;
          case 'heavy':
          case 'titan':
            en.vel.x = dir * 1 * moveMult;
            break;
        }

        // Retreat logic before transforming
        if (hpPercent < 0.5 && hpPercent >= 0.3 && en.type !== 'scout') {
          en.vel.x = -dir * 2.5;
        }

        en.pos.x += en.vel.x;

        // Attack Patterns
        if (dist < 600) {
          const rawCooldown = en.type === 'heavy' ? 120 : en.type === 'scout' ? 60 : en.type === 'sniper' ? 180 : 100;
          const cooldown = en.isTransformed ? rawCooldown * 0.4 : rawCooldown;

          if (e.frame - en.lastShot > cooldown) {
            switch(en.type) {
              case 'bot':
                bullets.push({ pos: {x: en.pos.x, y: en.pos.y + 15}, vel: {x: dir * (en.isTransformed ? 12 : 6), y: 0}, width: en.isTransformed ? 15 : 10, height: en.isTransformed ? 6 : 4, owner: 'enemy', health: 1, maxHealth: 1, damage: en.isTransformed ? 18 : 10, color: '#f00' });
                en.lastShot = e.frame;
                break;
              case 'scout':
                if (en.sequenceStage < (en.isTransformed ? 6 : 3)) {
                   if (e.frame % (en.isTransformed ? 4 : 8) === 0) {
                      bullets.push({ pos: {x: en.pos.x, y: en.pos.y + 10}, vel: {x: dir * (en.isTransformed ? 14 : 9), y: (Math.random()-0.5)*2}, width: 6, height: 3, owner: 'enemy', health: 1, maxHealth: 1, damage: 6, color: '#f55' });
                      en.sequenceStage++;
                   }
                } else {
                   en.sequenceStage = 0;
                   en.lastShot = e.frame;
                }
                break;
              case 'sniper':
                bullets.push({ pos: {x: en.pos.x, y: en.pos.y + 10}, vel: {x: dir * 16, y: 0}, width: 24, height: 2, owner: 'enemy', health: 1, maxHealth: 1, damage: en.isTransformed ? 45 : 30, color: '#fff' });
                en.lastShot = e.frame;
                break;
              case 'heavy':
              case 'titan':
                const numBullets = en.isTransformed ? 7 : 3;
                for(let j=-(numBullets>>1); j<=(numBullets>>1); j++) {
                  bullets.push({ pos: {x: en.pos.x, y: en.pos.y + 30}, vel: {x: dir * 6, y: j * (en.isTransformed ? 2 : 1.2)}, width: 14, height: 10, owner: 'enemy', health: 1, maxHealth: 1, damage: 25, color: '#f00' });
                }
                en.lastShot = e.frame;
                break;
            }
          }
        }

        // Damage calculation (Player to Enemy)
        bullets.forEach((b, idx) => {
          if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) {
            en.health -= b.damage || 20; 
            bullets.splice(idx, 1);
            if (en.health <= 0) en.isDead = true;
          }
        });

        // Player collision
        if (!player.invulnerable && player.pos.x < en.pos.x + en.width && player.pos.x + pw > en.pos.x && player.pos.y < en.pos.y + en.height && player.pos.y + ph > en.pos.y) {
           setHealth(h => Math.max(0, h - (en.type === 'heavy' ? 45 : 25))); 
           player.invulnerable = 60; 
           soundService.playLose();
        }
      });

      if (health <= 0) onDie();
      if (allDead) onWin();
      if (player.invulnerable > 0) player.invulnerable--;
      e.cameraX = player.pos.x - CANVAS_WIDTH/3;
      if (e.cameraX < 0) e.cameraX = 0;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const e = engineRef.current;
      ctx.fillStyle = '#050510'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

      ctx.fillStyle = '#1c1c1c'; ctx.fillRect(0, 398, CANVAS_WIDTH, 52);
      ctx.strokeStyle = '#222';
      for(let i=0; i<CANVAS_WIDTH; i+=40) {
        ctx.beginPath(); ctx.moveTo(i - (e.cameraX % 40), 398); ctx.lineTo(i - (e.cameraX % 40), CANVAS_HEIGHT); ctx.stroke();
      }

      e.enemies.forEach(en => { 
        if(!en.isDead) drawUnit(ctx, en.pos.x - e.cameraX, en.pos.y, en.width, en.height, RobotUnit.SENTINEL, Math.sign(e.player.pos.x - en.pos.x), e.frame, true, false, en.isTransformed, en.type); 
      });

      const player = e.player;
      const ph = player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48);
      const pw = player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32);

      drawUnit(ctx, player.pos.x - e.cameraX, player.pos.y, pw, ph, e.unit, player.facing, e.frame, false, player.invulnerable > 0, player.isTransformed);

      e.bullets.forEach(b => { 
        ctx.fillStyle = b.color || (b.owner === 'player' ? '#00f3ff' : '#ff0055'); 
        ctx.fillRect(b.pos.x - e.cameraX, b.pos.y, b.width, b.height); 
      });
    };

    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [resetLevel, onWin, onDie, level, upgrades, health, currentUnit]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden">
      <div className="absolute top-4 left-4 z-10 space-y-4 pointer-events-none">
        {/* Integrity Bar */}
        <div className="bg-black/80 border border-cyan-500/50 p-3 rounded backdrop-blur-md shadow-lg">
          <div className="text-[10px] text-cyan-400 font-bold uppercase mb-1 flex justify-between font-orbitron">
            <span>{ROBOT_STATS[currentUnit].name} INTEGRITY</span>
            <span>{Math.round(health)}/{Math.round(maxHealth)}</span>
          </div>
          <div className="w-48 h-2.5 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
            <div 
              className="h-full shadow-[0_0_15px_#00f3ff] transition-all duration-300" 
              style={{ 
                width: `${(health / maxHealth) * 100}%`,
                backgroundColor: health < maxHealth * 0.3 ? '#ef4444' : '#00f3ff'
              }} 
            />
          </div>
          <div className="mt-2 text-[8px] text-white/50 font-mono flex justify-between">
            <span>MODE: {isTransformed ? `ALT (${ROBOT_STATS[currentUnit].alt.type})` : 'HUMANOID'}</span>
            <span className="animate-pulse">[SHIFT TO TOGGLE]</span>
          </div>
        </div>

        {/* Robot Selector */}
        <div className="flex flex-col gap-2 pointer-events-auto">
           <div className="text-[10px] text-white/50 font-bold uppercase tracking-tighter ml-1 font-orbitron">SQUAD_DEPLOYMENT [1-5]</div>
           <div className="flex gap-2">
           {(Object.keys(ROBOT_STATS) as RobotUnit[]).map((u, i) => {
             const stats = ROBOT_STATS[u];
             const isActive = currentUnit === u;
             return (
               <button 
                 key={u} 
                 onClick={() => setCurrentUnit(u)}
                 className={`group relative w-12 h-12 flex flex-col items-center justify-center rounded-sm border-2 transition-all duration-200 ${
                   isActive 
                     ? 'bg-white/10' 
                     : 'border-gray-800 bg-black/60 hover:border-gray-600'
                 }`}
                 style={{
                   borderColor: isActive ? stats.color : '',
                   boxShadow: isActive ? `0 0 20px ${stats.color}50, inset 0 0 8px ${stats.color}30` : 'none'
                 }}
               >
                 {isActive && (
                   <>
                     <div className="absolute -top-1.5 -left-1.5 w-3 h-3 border-t-2 border-l-2" style={{ borderColor: stats.color }} />
                     <div className="absolute -bottom-1.5 -right-1.5 w-3 h-3 border-b-2 border-r-2" style={{ borderColor: stats.color }} />
                   </>
                 )}
                 <span className={`text-xl font-black font-orbitron transition-colors ${isActive ? 'text-white' : 'text-gray-600'}`}>
                   {i + 1}
                 </span>
                 <div className={`absolute -bottom-8 px-2 py-0.5 rounded bg-black/90 border border-gray-700 text-[8px] font-bold uppercase tracking-widest text-white transition-opacity whitespace-nowrap ${isActive ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}>
                    {stats.name}
                 </div>
                 {isActive && (
                    <div className="absolute -top-4 left-1/2 -translate-x-1/2 w-1.5 h-1.5 bg-white rounded-full animate-ping" />
                 )}
               </button>
             );
           })}
           </div>
        </div>
      </div>

      <div className="absolute top-4 right-4 z-10 text-right pointer-events-none font-orbitron">
        <div className="text-[10px] text-cyan-500 font-bold uppercase tracking-widest">Active Sector</div>
        <div className="text-3xl font-black text-white italic drop-shadow-md">{level.toString().padStart(2, '0')}</div>
      </div>

      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full aspect-video shadow-2xl rounded-lg border-2 border-cyan-900/50" />

      {health < maxHealth * 0.3 && (
        <div className="absolute inset-0 pointer-events-none border-[16px] border-red-600/20 animate-pulse shadow-[inset_0_0_100px_rgba(239,68,68,0.3)]"></div>
      )}

      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 pointer-events-none text-white/30 text-[9px] font-mono tracking-widest uppercase flex gap-8">
        <span>WASD: Move</span>
        <span>Space: Fire</span>
        <span>Shift: Transform</span>
        <span>1-5: Switch Squad</span>
      </div>
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const SHIELD_DURATION = 20 * 60; // 20 seconds at 60fps

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { 
    name: "SENTINEL", color: '#00f3ff', hpMult: 1.0, 
    robot: { speed: 4, jump: -11, fireRate: 15 },
    alt: { speed: 8, jump: -5, fireRate: 25, type: 'Car' }
  },
  [RobotUnit.STRIKER]: { 
    name: "STRIKER", color: '#fbbf24', hpMult: 0.8,
    robot: { speed: 6, jump: -10, fireRate: 10 },
    alt: { speed: 12, jump: -4, fireRate: 20, type: 'Bike' }
  },
  [RobotUnit.FALCON]: { 
    name: "FALCON", color: '#22d3ee', hpMult: 0.7,
    robot: { speed: 5, jump: -10, fireRate: 12 },
    alt: { speed: 7, jump: -7, fireRate: 15, type: 'Jet' }
  },
  [RobotUnit.TITAN]: { 
    name: "TITAN", color: '#ef4444', hpMult: 2.5,
    robot: { speed: 2.5, jump: -12, fireRate: 30 },
    alt: { speed: 4, jump: 0, fireRate: 20, type: 'Tank' }
  },
  [RobotUnit.SPECTER]: { 
    name: "SPECTER", color: '#a855f7', hpMult: 0.6,
    robot: { speed: 5, jump: -11, fireRate: 20 },
    alt: { speed: 6, jump: -14, fireRate: 40, type: 'Sphere' }
  },
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [currentUnit, setCurrentUnit] = useState<RobotUnit>(RobotUnit.SENTINEL);
  const [isTransformed, setIsTransformed] = useState(false);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [distance, setDistance] = useState(0);
  const [shieldTimeRemaining, setShieldTimeRemaining] = useState(0);

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      maxHealth: 100,
      isTransformed: false,
      shieldTimer: 0,
    },
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    unit: RobotUnit.SENTINEL,
    level: level,
  });

  useEffect(() => { engineRef.current.isPaused = isPaused; }, [isPaused]);
  useEffect(() => { 
    engineRef.current.unit = currentUnit;
    engineRef.current.player.isTransformed = false;
    setIsTransformed(false);
  }, [currentUnit]);
  useEffect(() => { engineRef.current.level = level; }, [level]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff44');
    grad.addColorStop(1, '#00000088');
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.5)';
    ctx.stroke();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, type = 'bot', isTransformed = false) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8;
    const armSwing = Math.cos(time) * 10;

    let scale = 1;
    if (type === 'scout') scale = 0.8;
    if (type === 'heavy' || type === 'titan') scale = 1.4;

    if (isEnemy && isTransformed) {
      scale *= 1.25;
      ctx.translate((Math.random() - 0.5) * 3, (Math.random() - 0.5) * 3);
    }

    ctx.save();
    ctx.scale(scale, scale);

    if (isEnemy && isTransformed) {
      ctx.shadowBlur = 20;
      ctx.shadowColor = '#ff3300';
    }

    drawMechanicalPart(ctx, -12, -18, 24, 28, isTransformed ? '#400' : color, 4);
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? (isTransformed ? '#fff' : '#ff0000') : '#00f3ff';
    ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);

    if (isEnemy && isTransformed) {
      const corePulse = Math.sin(frame * 0.4) * 3;
      ctx.fillStyle = frame % 4 < 2 ? '#ff0000' : '#ffffff';
      ctx.beginPath();
      ctx.arc(0, -5, 5 + corePulse, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.restore();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, color: string, frame: number) => {
    switch(unit) {
      case RobotUnit.SENTINEL:
        drawMechanicalPart(ctx, -24, -10, 48, 18, color, 8);
        drawMechanicalPart(ctx, -16, -20, 30, 12, '#111', 4);
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(-15, 10, 7, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(15, 10, 7, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = frame % 10 < 5 ? '#ff0000' : '#0000ff';
        ctx.fillRect(-4, -22, 10, 3);
        break;
      case RobotUnit.STRIKER:
        drawMechanicalPart(ctx, -18, -8, 36, 12, color, 4);
        drawMechanicalPart(ctx, -5, -18, 18, 12, '#222', 2);
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(-18, 8, 9, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(18, 8, 9, 0, Math.PI * 2); ctx.fill();
        break;
      case RobotUnit.FALCON:
        drawMechanicalPart(ctx, -20, -10, 40, 15, color, 12);
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(-10, -5); ctx.lineTo(-30, -15); ctx.lineTo(-10, 5); ctx.fill();
        ctx.fillStyle = '#ffaa00';
        ctx.fillRect(-28, -5, 8, 5);
        break;
      case RobotUnit.TITAN:
        drawMechanicalPart(ctx, -30, -10, 60, 22, color, 4);
        drawMechanicalPart(ctx, -15, -25, 30, 15, '#222', 4);
        drawMechanicalPart(ctx, 10, -20, 25, 5, '#444', 0);
        ctx.fillStyle = '#111';
        ctx.fillRect(-28, 8, 56, 6);
        break;
      case RobotUnit.SPECTER:
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.arc(0, 0, 18, 0, Math.PI * 2); ctx.fill();
        ctx.strokeStyle = '#fff'; ctx.lineWidth = 1; ctx.stroke();
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(8, -4, 4, 0, Math.PI * 2); ctx.fill();
        break;
    }
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy = false, isInvuln = false, isTransformed = false, type = 'bot') => {
    if (isInvuln && frame % 4 < 2) return;

    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    if (facing === -1) ctx.scale(-1, 1);

    const stats = ROBOT_STATS[unit];
    const color = isEnemy ? '#ff0055' : stats.color;

    if (isTransformed && !isEnemy) {
      drawAltMode(ctx, unit, color, frame);
    } else {
      drawHumanoid(ctx, color, frame, isEnemy, type, isTransformed);
    }

    ctx.restore();
  };

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    const stats = ROBOT_STATS[currentUnit];
    const baseHP = 100 + (upgrades.robotTier * 50);

    e.player.maxHealth = baseHP * stats.hpMult;
    e.player.shieldTimer = 0;
    setShieldTimeRemaining(0);
    setMaxHealth(e.player.maxHealth);
    setHealth(e.player.maxHealth);

    e.player.pos = { x: 100, y: 300 };
    e.player.vel = { x: 0, y: 0 };
    e.player.invulnerable = 0;
    e.player.isTransformed = false;
    setIsTransformed(false);
    e.bullets = [];
    e.cameraX = 0;
    setDistance(0);

    const enemies: Enemy[] = [];
    const floorY = 398;

    const enemyTypes = ['bot', 'scout', 'sniper', 'heavy'];
    for (let i = 0; i < 4; i++) {
      const type = enemyTypes[i % (level < 5 ? 1 : level < 10 ? 2 : 4)];
      let w = 32, h = 48, hp = 50 + level * 15;
      if (type === 'scout') { w = 24; h = 36; hp = 40 + level * 5; }
      if (type === 'heavy') { w = 48; h = 72; hp = 150 + level * 20; }

      enemies.push({ 
        id: i, 
        pos: { x: 800 + i * 700, y: floorY - h }, 
        vel: { x: 0, y: 0 }, 
        width: w, 
        height: h, 
        health: hp, 
        maxHealth: hp, 
        isDead: false, 
        type: type, 
        lastShot: 0,
        sequenceStage: 0,
        sequenceTimer: 0,
        isTransformed: false,
        transformTimer: 0
      });
    }

    enemies.push({ 
      id: 4, 
      pos: { x: 4000, y: floorY - 96 }, 
      vel: { x: 0, y: 0 }, 
      width: 80, 
      height: 96, 
      health: 500 + level * 50, 
      maxHealth: 500 + level * 50, 
      isDead: false, 
      type: 'titan', 
      lastShot: 0,
      isTransformed: false
    });
    e.enemies = enemies;
  }, [level, upgrades, currentUnit]);

  useEffect(() => {
    resetLevel();
    const handleKeyDown = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = true;
      if (e.code === 'Digit1') setCurrentUnit(RobotUnit.SENTINEL);
      if (e.code === 'Digit2') setCurrentUnit(RobotUnit.STRIKER);
      if (e.code === 'Digit3') setCurrentUnit(RobotUnit.FALCON);
      if (e.code === 'Digit4') setCurrentUnit(RobotUnit.TITAN);
      if (e.code === 'Digit5') setCurrentUnit(RobotUnit.SPECTER);

      if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') {
        engineRef.current.player.isTransformed = !engineRef.current.player.isTransformed;
        setIsTransformed(engineRef.current.player.isTransformed);
      }

      if (e.code === 'KeyU') {
        engineRef.current.player.shieldTimer = SHIELD_DURATION;
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => { engineRef.current.keys[e.code] = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!engineRef.current.isPaused) update();
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const e = engineRef.current;
      const { player, enemies, bullets, keys } = e;
      const stats = ROBOT_STATS[e.unit];
      const currentStats = player.isTransformed ? stats.alt : stats.robot;
      e.frame++;

      if (player.shieldTimer > 0) {
        player.shieldTimer--;
        if (e.frame % 30 === 0) setShieldTimeRemaining(Math.ceil(player.shieldTimer / 60));
      } else if (shieldTimeRemaining > 0) {
        setShieldTimeRemaining(0);
      }

      const ph = player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48);
      const pw = player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32);

      if (keys['ArrowRight'] || keys['KeyD']) { player.vel.x = currentStats.speed; player.facing = 1; }
      else if (keys['ArrowLeft'] || keys['KeyA']) { player.vel.x = -currentStats.speed; player.facing = -1; }
      else { player.vel.x *= 0.8; }

      if (e.unit === RobotUnit.FALCON && player.isTransformed) {
        if (keys['ArrowUp'] || keys['KeyW']) player.vel.y = -currentStats.speed;
        else if (keys['ArrowDown'] || keys['KeyS']) player.vel.y = currentStats.speed;
        else player.vel.y *= 0.9;
        player.grounded = false;
      } else {
        if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.grounded) {
          player.vel.y = currentStats.jump;
          player.grounded = false;
        }
        player.vel.y += GRAVITY;
      }

      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;

      const floorY = 398;
      if (player.pos.y > floorY - ph) { 
        player.pos.y = floorY - ph; 
        player.vel.y = 0; 
        player.grounded = true; 
      }
      if (player.pos.x < 0) player.pos.x = 0;
      setDistance(player.pos.x);

      const fr = Math.max(5, currentStats.fireRate - upgrades.weaponTier * 2);
      if (keys['Space'] && e.frame - player.lastShot > fr) {
        soundService.playShoot();
        const dmg = player.isTransformed ? 40 : (e.unit === RobotUnit.TITAN ? 60 : (e.unit === RobotUnit.SPECTER ? 80 : 25));
        bullets.push({ 
          pos: { x: player.pos.x + (player.facing === 1 ? pw : 0), y: player.pos.y + ph/2 }, 
          vel: { x: player.facing * (e.unit === RobotUnit.SPECTER ? 25 : 15), y: 0 }, 
          width: player.isTransformed ? 12 : 8, 
          height: 4, 
          owner: 'player', 
          health: 1, maxHealth: 1, damage: dmg, color: stats.color 
        });
        player.lastShot = e.frame;
      }

      for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i]; 
        b.pos.x += b.vel.x; 
        b.pos.y += b.vel.y;

        if (b.owner === 'enemy' && !player.invulnerable && player.shieldTimer <= 0) {
          if (b.pos.x < player.pos.x + pw && b.pos.x + b.width > player.pos.x &&
              b.pos.y < player.pos.y + ph && b.pos.y + b.height > player.pos.y) {
            setHealth(h => Math.max(0, h - (b.damage || 10)));
            player.invulnerable = 40;
            bullets.splice(i, 1);
            soundService.playLose();
            continue;
          }
        } else if (b.owner === 'enemy' && player.shieldTimer > 0) {
          // Bullets dissolve on shield
          if (b.pos.x < player.pos.x + pw + 20 && b.pos.x + b.width > player.pos.x - 20 &&
              b.pos.y < player.pos.y + ph + 20 && b.pos.y + b.height > player.pos.y - 20) {
            bullets.splice(i, 1);
            continue;
          }
        }

        if (Math.abs(b.pos.x - player.pos.x) > 1200) {
          bullets.splice(i, 1);
        }
      }

      let allDead = true;
      enemies.forEach(en => {
        if (en.isDead) return;
        allDead = false;

        const dist = Math.abs(en.pos.x - player.pos.x);
        const dir = Math.sign(player.pos.x - en.pos.x);
        const hpPercent = en.health / en.maxHealth;

        if (hpPercent < 0.3 && !en.isTransformed) {
          en.isTransformed = true;
          en.width *= 1.3;
          en.height *= 1.3;
        }

        const moveMult = en.isTransformed ? 2.2 : 1.0;

        switch(en.type) {
          case 'bot':
            if (dist > 350) en.vel.x = dir * 2 * moveMult;
            else if (dist < 200) en.vel.x = -dir * 2 * moveMult;
            else en.vel.x *= 0.8;
            break;
          case 'scout':
            en.vel.x = dir * 4 * moveMult;
            break;
          case 'sniper':
            if (dist < 500) en.vel.x = -dir * 3 * moveMult;
            else en.vel.x *= 0.5;
            break;
          case 'heavy':
          case 'titan':
            en.vel.x = dir * 1 * moveMult;
            break;
        }

        if (hpPercent < 0.5 && hpPercent >= 0.3 && en.type !== 'scout') {
          en.vel.x = -dir * 2.5;
        }

        en.pos.x += en.vel.x;

        if (dist < 600) {
          const rawCooldown = en.type === 'heavy' ? 120 : en.type === 'scout' ? 60 : en.type === 'sniper' ? 180 : 100;
          const cooldown = en.isTransformed ? rawCooldown * 0.4 : rawCooldown;

          if (e.frame - en.lastShot > cooldown) {
            switch(en.type) {
              case 'bot':
                bullets.push({ pos: {x: en.pos.x, y: en.pos.y + 15}, vel: {x: dir * (en.isTransformed ? 12 : 6), y: 0}, width: en.isTransformed ? 15 : 10, height: en.isTransformed ? 6 : 4, owner: 'enemy', health: 1, maxHealth: 1, damage: en.isTransformed ? 18 : 10, color: '#f00' });
                en.lastShot = e.frame;
                break;
              case 'scout':
                if (en.sequenceStage < (en.isTransformed ? 6 : 3)) {
                   if (e.frame % (en.isTransformed ? 4 : 8) === 0) {
                      bullets.push({ pos: {x: en.pos.x, y: en.pos.y + 10}, vel: {x: dir * (en.isTransformed ? 14 : 9), y: (Math.random()-0.5)*2}, width: 6, height: 3, owner: 'enemy', health: 1, maxHealth: 1, damage: 6, color: '#f55' });
                      en.sequenceStage++;
                   }
                } else {
                   en.sequenceStage = 0;
                   en.lastShot = e.frame;
                }
                break;
              case 'sniper':
                bullets.push({ pos: {x: en.pos.x, y: en.pos.y + 10}, vel: {x: dir * 16, y: 0}, width: 24, height: 2, owner: 'enemy', health: 1, maxHealth: 1, damage: en.isTransformed ? 45 : 30, color: '#fff' });
                en.lastShot = e.frame;
                break;
              case 'heavy':
              case 'titan':
                const numBullets = en.isTransformed ? 7 : 3;
                for(let j=-(numBullets>>1); j<=(numBullets>>1); j++) {
                  bullets.push({ pos: {x: en.pos.x, y: en.pos.y + 30}, vel: {x: dir * 6, y: j * (en.isTransformed ? 2 : 1.2)}, width: 14, height: 10, owner: 'enemy', health: 1, maxHealth: 1, damage: 25, color: '#f00' });
                }
                en.lastShot = e.frame;
                break;
            }
          }
        }

        bullets.forEach((b, idx) => {
          if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) {
            en.health -= b.damage || 20; 
            bullets.splice(idx, 1);
            if (en.health <= 0) en.isDead = true;
          }
        });

        if (!player.invulnerable && player.shieldTimer <= 0 && player.pos.x < en.pos.x + en.width && player.pos.x + pw > en.pos.x && player.pos.y < en.pos.y + en.height && player.pos.y + ph > en.pos.y) {
           setHealth(h => Math.max(0, h - (en.type === 'heavy' ? 45 : 25))); 
           player.invulnerable = 60; 
           soundService.playLose();
        }
      });

      if (health <= 0) onDie();
      if (allDead) onWin();
      if (player.invulnerable > 0) player.invulnerable--;
      e.cameraX = player.pos.x - CANVAS_WIDTH/3;
      if (e.cameraX < 0) e.cameraX = 0;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const e = engineRef.current;
      ctx.fillStyle = '#050510'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

      ctx.fillStyle = '#1c1c1c'; ctx.fillRect(0, 398, CANVAS_WIDTH, 52);
      ctx.strokeStyle = '#222';
      for(let i=0; i<CANVAS_WIDTH; i+=40) {
        ctx.beginPath(); ctx.moveTo(i - (e.cameraX % 40), 398); ctx.lineTo(i - (e.cameraX % 40), CANVAS_HEIGHT); ctx.stroke();
      }

      e.enemies.forEach(en => { 
        if(!en.isDead) drawUnit(ctx, en.pos.x - e.cameraX, en.pos.y, en.width, en.height, RobotUnit.SENTINEL, Math.sign(e.player.pos.x - en.pos.x), e.frame, true, false, en.isTransformed, en.type); 
      });

      const player = e.player;
      const ph = player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48);
      const pw = player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32);

      drawUnit(ctx, player.pos.x - e.cameraX, player.pos.y, pw, ph, e.unit, player.facing, e.frame, false, player.invulnerable > 0, player.isTransformed);

      // Draw Shield Visuals
      if (player.shieldTimer > 0) {
        const shieldPulse = Math.sin(e.frame * 0.1) * 5;
        ctx.save();
        ctx.translate(player.pos.x - e.cameraX + pw / 2, player.pos.y + ph / 2);
        ctx.beginPath();
        ctx.arc(0, 0, Math.max(pw, ph) * 0.8 + shieldPulse, 0, Math.PI * 2);
        ctx.strokeStyle = '#00f3ff';
        ctx.lineWidth = 3;
        ctx.shadowBlur = 15;
        ctx.shadowColor = '#00f3ff';
        ctx.stroke();

        // Hexagon pattern inside
        ctx.globalAlpha = 0.2;
        ctx.fillStyle = '#00f3ff';
        ctx.fill();
        ctx.restore();
      }

      e.bullets.forEach(b => { 
        ctx.fillStyle = b.color || (b.owner === 'player' ? '#00f3ff' : '#ff0055'); 
        ctx.fillRect(b.pos.x - e.cameraX, b.pos.y, b.width, b.height); 
      });
    };

    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [resetLevel, onWin, onDie, level, upgrades, health, currentUnit, shieldTimeRemaining]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden">
      <div className="absolute top-4 left-4 z-10 space-y-4 pointer-events-none">
        {/* Integrity Bar */}
        <div className="bg-black/80 border border-cyan-500/50 p-3 rounded backdrop-blur-md shadow-lg">
          <div className="text-[10px] text-cyan-400 font-bold uppercase mb-1 flex justify-between font-orbitron">
            <span>{ROBOT_STATS[currentUnit].name} INTEGRITY</span>
            <span>{Math.round(health)}/{Math.round(maxHealth)}</span>
          </div>
          <div className="w-48 h-2.5 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
            <div 
              className="h-full shadow-[0_0_15px_#00f3ff] transition-all duration-300" 
              style={{ 
                width: `${(health / maxHealth) * 100}%`,
                backgroundColor: health < maxHealth * 0.3 ? '#ef4444' : '#00f3ff'
              }} 
            />
          </div>
          {shieldTimeRemaining > 0 && (
            <div className="mt-2 flex items-center gap-2">
              <div className="text-[10px] text-blue-400 font-black animate-pulse font-orbitron">SHIELD ACTIVE: {shieldTimeRemaining}s</div>
              <div className="flex-1 h-1 bg-blue-900 rounded-full overflow-hidden">
                <div className="h-full bg-cyan-400" style={{ width: `${(shieldTimeRemaining / 20) * 100}%` }}></div>
              </div>
            </div>
          )}
          <div className="mt-2 text-[8px] text-white/50 font-mono flex justify-between">
            <span>MODE: {isTransformed ? `ALT (${ROBOT_STATS[currentUnit].alt.type})` : 'HUMANOID'}</span>
            <span className="animate-pulse">[SHIFT TO TOGGLE]</span>
          </div>
        </div>

        {/* Robot Selector */}
        <div className="flex flex-col gap-2 pointer-events-auto">
           <div className="text-[10px] text-white/50 font-bold uppercase tracking-tighter ml-1 font-orbitron">SQUAD_DEPLOYMENT [1-5]</div>
           <div className="flex gap-2">
           {(Object.keys(ROBOT_STATS) as RobotUnit[]).map((u, i) => {
             const stats = ROBOT_STATS[u];
             const isActive = currentUnit === u;
             return (
               <button 
                 key={u} 
                 onClick={() => setCurrentUnit(u)}
                 className={`group relative w-12 h-12 flex flex-col items-center justify-center rounded-sm border-2 transition-all duration-200 ${
                   isActive 
                     ? 'bg-white/10' 
                     : 'border-gray-800 bg-black/60 hover:border-gray-600'
                 }`}
                 style={{
                   borderColor: isActive ? stats.color : '',
                   boxShadow: isActive ? `0 0 20px ${stats.color}50, inset 0 0 8px ${stats.color}30` : 'none'
                 }}
               >
                 {isActive && (
                   <>
                     <div className="absolute -top-1.5 -left-1.5 w-3 h-3 border-t-2 border-l-2" style={{ borderColor: stats.color }} />
                     <div className="absolute -bottom-1.5 -right-1.5 w-3 h-3 border-b-2 border-r-2" style={{ borderColor: stats.color }} />
                   </>
                 )}
                 <span className={`text-xl font-black font-orbitron transition-colors ${isActive ? 'text-white' : 'text-gray-600'}`}>
                   {i + 1}
                 </span>
                 <div className={`absolute -bottom-8 px-2 py-0.5 rounded bg-black/90 border border-gray-700 text-[8px] font-bold uppercase tracking-widest text-white transition-opacity whitespace-nowrap ${isActive ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}>
                    {stats.name}
                 </div>
                 {isActive && (
                    <div className="absolute -top-4 left-1/2 -translate-x-1/2 w-1.5 h-1.5 bg-white rounded-full animate-ping" />
                 )}
               </button>
             );
           })}
           </div>
        </div>
      </div>

      <div className="absolute top-4 right-4 z-10 text-right pointer-events-none font-orbitron">
        <div className="text-[10px] text-cyan-500 font-bold uppercase tracking-widest">Active Sector</div>
        <div className="text-3xl font-black text-white italic drop-shadow-md">{level.toString().padStart(2, '0')}</div>
      </div>

      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full aspect-video shadow-2xl rounded-lg border-2 border-cyan-900/50" />

      {health < maxHealth * 0.3 && (
        <div className="absolute inset-0 pointer-events-none border-[16px] border-red-600/20 animate-pulse shadow-[inset_0_0_100px_rgba(239,68,68,0.3)]"></div>
      )}

      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 pointer-events-none text-white/30 text-[9px] font-mono tracking-widest uppercase flex gap-8">
        <span>WASD: Move</span>
        <span>Space: Fire</span>
        <span>Shift: Transform</span>
        <span>U: Activate Shield</span>
        <span>1-5: Switch Squad</span>
      </div>
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const SHIELD_DURATION = 20 * 60; // 20 seconds at 60fps

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { 
    name: "SENTINEL", color: '#00f3ff', hpMult: 1.0, 
    robot: { speed: 4, jump: -11, fireRate: 15 },
    alt: { speed: 8, jump: -5, fireRate: 25, type: 'Car' }
  },
  [RobotUnit.STRIKER]: { 
    name: "STRIKER", color: '#fbbf24', hpMult: 0.8,
    robot: { speed: 6, jump: -10, fireRate: 10 },
    alt: { speed: 12, jump: -4, fireRate: 20, type: 'Bike' }
  },
  [RobotUnit.FALCON]: { 
    name: "FALCON", color: '#22d3ee', hpMult: 0.7,
    robot: { speed: 5, jump: -10, fireRate: 12 },
    alt: { speed: 7, jump: -7, fireRate: 15, type: 'Jet' }
  },
  [RobotUnit.TITAN]: { 
    name: "TITAN", color: '#ef4444', hpMult: 2.5,
    robot: { speed: 2.5, jump: -12, fireRate: 30 },
    alt: { speed: 4, jump: 0, fireRate: 20, type: 'Tank' }
  },
  [RobotUnit.SPECTER]: { 
    name: "SPECTER", color: '#a855f7', hpMult: 0.6,
    robot: { speed: 5, jump: -11, fireRate: 20 },
    alt: { speed: 6, jump: -14, fireRate: 40, type: 'Sphere' }
  },
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [currentUnit, setCurrentUnit] = useState<RobotUnit>(RobotUnit.SENTINEL);
  const [isTransformed, setIsTransformed] = useState(false);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [distance, setDistance] = useState(0);
  const [shieldTimeRemaining, setShieldTimeRemaining] = useState(0);

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      maxHealth: 100,
      isTransformed: false,
      shieldTimer: 0,
    },
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    unit: RobotUnit.SENTINEL,
    level: level,
  });

  useEffect(() => { engineRef.current.isPaused = isPaused; }, [isPaused]);
  useEffect(() => { 
    engineRef.current.unit = currentUnit;
    engineRef.current.player.isTransformed = false;
    setIsTransformed(false);
  }, [currentUnit]);
  useEffect(() => { engineRef.current.level = level; }, [level]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff44');
    grad.addColorStop(1, '#00000088');
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.5)';
    ctx.stroke();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, type = 'bot', isTransformed = false) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8;
    const armSwing = Math.cos(time) * 10;

    let scale = 1;
    if (type === 'scout') scale = 0.8;
    if (type === 'heavy' || type === 'titan') scale = 1.4;

    if (isEnemy && isTransformed) {
      scale *= 1.25;
      ctx.translate((Math.random() - 0.5) * 3, (Math.random() - 0.5) * 3);
    }

    ctx.save();
    ctx.scale(scale, scale);

    if (isEnemy && isTransformed) {
      ctx.shadowBlur = 20;
      ctx.shadowColor = '#ff3300';
    }

    drawMechanicalPart(ctx, -12, -18, 24, 28, isTransformed ? '#400' : color, 4);
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? (isTransformed ? '#fff' : '#ff0000') : '#00f3ff';
    ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);

    if (isEnemy && isTransformed) {
      const corePulse = Math.sin(frame * 0.4) * 3;
      ctx.fillStyle = frame % 4 < 2 ? '#ff0000' : '#ffffff';
      ctx.beginPath();
      ctx.arc(0, -5, 5 + corePulse, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.restore();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, color: string, frame: number) => {
    switch(unit) {
      case RobotUnit.SENTINEL:
        drawMechanicalPart(ctx, -24, -10, 48, 18, color, 8);
        drawMechanicalPart(ctx, -16, -20, 30, 12, '#111', 4);
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(-15, 10, 7, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(15, 10, 7, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = frame % 10 < 5 ? '#ff0000' : '#0000ff';
        ctx.fillRect(-4, -22, 10, 3);
        break;
      case RobotUnit.STRIKER:
        drawMechanicalPart(ctx, -18, -8, 36, 12, color, 4);
        drawMechanicalPart(ctx, -5, -18, 18, 12, '#222', 2);
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(-18, 8, 9, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(18, 8, 9, 0, Math.PI * 2); ctx.fill();
        break;
      case RobotUnit.FALCON:
        drawMechanicalPart(ctx, -20, -10, 40, 15, color, 12);
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(-10, -5); ctx.lineTo(-30, -15); ctx.lineTo(-10, 5); ctx.fill();
        ctx.fillStyle = '#ffaa00';
        ctx.fillRect(-28, -5, 8, 5);
        break;
      case RobotUnit.TITAN:
        drawMechanicalPart(ctx, -30, -10, 60, 22, color, 4);
        drawMechanicalPart(ctx, -15, -25, 30, 15, '#222', 4);
        drawMechanicalPart(ctx, 10, -20, 25, 5, '#444', 0);
        ctx.fillStyle = '#111';
        ctx.fillRect(-28, 8, 56, 6);
        break;
      case RobotUnit.SPECTER:
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.arc(0, 0, 18, 0, Math.PI * 2); ctx.fill();
        ctx.strokeStyle = '#fff'; ctx.lineWidth = 1; ctx.stroke();
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(8, -4, 4, 0, Math.PI * 2); ctx.fill();
        break;
    }
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy = false, isInvuln = false, isTransformed = false, type = 'bot') => {
    if (isInvuln && frame % 4 < 2) return;

    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    if (facing === -1) ctx.scale(-1, 1);

    const stats = ROBOT_STATS[unit];
    const color = isEnemy ? '#ff0055' : stats.color;

    if (isTransformed && !isEnemy) {
      drawAltMode(ctx, unit, color, frame);
    } else {
      drawHumanoid(ctx, color, frame, isEnemy, type, isTransformed);
    }

    ctx.restore();
  };

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    const stats = ROBOT_STATS[currentUnit];
    const baseHP = 100 + (upgrades.robotTier * 50);

    e.player.maxHealth = baseHP * stats.hpMult;
    e.player.shieldTimer = 0;
    setShieldTimeRemaining(0);
    setMaxHealth(e.player.maxHealth);
    setHealth(e.player.maxHealth);

    e.player.pos = { x: 100, y: 300 };
    e.player.vel = { x: 0, y: 0 };
    e.player.invulnerable = 0;
    e.player.isTransformed = false;
    setIsTransformed(false);
    e.bullets = [];
    e.cameraX = 0;
    setDistance(0);

    const enemies: Enemy[] = [];
    const floorY = 398;

    const enemyTypes = ['bot', 'scout', 'sniper', 'heavy'];
    for (let i = 0; i < 4; i++) {
      const type = enemyTypes[i % (level < 5 ? 1 : level < 10 ? 2 : 4)];
      let w = 32, h = 48, hp = 50 + level * 15;
      if (type === 'scout') { w = 24; h = 36; hp = 40 + level * 5; }
      if (type === 'heavy') { w = 48; h = 72; hp = 150 + level * 20; }

      enemies.push({ 
        id: i, 
        pos: { x: 800 + i * 700, y: floorY - h }, 
        vel: { x: 0, y: 0 }, 
        width: w, 
        height: h, 
        health: hp, 
        maxHealth: hp, 
        isDead: false, 
        type: type, 
        lastShot: 0,
        sequenceStage: 0,
        sequenceTimer: 0,
        isTransformed: false,
        transformTimer: 0
      });
    }

    enemies.push({ 
      id: 4, 
      pos: { x: 4000, y: floorY - 96 }, 
      vel: { x: 0, y: 0 }, 
      width: 80, 
      height: 96, 
      health: 500 + level * 50, 
      maxHealth: 500 + level * 50, 
      isDead: false, 
      type: 'titan', 
      lastShot: 0,
      isTransformed: false
    });
    e.enemies = enemies;
  }, [level, upgrades, currentUnit]);

  useEffect(() => {
    resetLevel();
    const handleKeyDown = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = true;
      if (e.code === 'Digit1') setCurrentUnit(RobotUnit.SENTINEL);
      if (e.code === 'Digit2') setCurrentUnit(RobotUnit.STRIKER);
      if (e.code === 'Digit3') setCurrentUnit(RobotUnit.FALCON);
      if (e.code === 'Digit4') setCurrentUnit(RobotUnit.TITAN);
      if (e.code === 'Digit5') setCurrentUnit(RobotUnit.SPECTER);

      if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') {
        engineRef.current.player.isTransformed = !engineRef.current.player.isTransformed;
        setIsTransformed(engineRef.current.player.isTransformed);
      }

      if (e.code === 'KeyU') {
        engineRef.current.player.shieldTimer = SHIELD_DURATION;
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => { engineRef.current.keys[e.code] = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!engineRef.current.isPaused) update();
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const e = engineRef.current;
      const { player, enemies, bullets, keys } = e;
      const stats = ROBOT_STATS[e.unit];
      const currentStats = player.isTransformed ? stats.alt : stats.robot;
      e.frame++;

      if (player.shieldTimer > 0) {
        player.shieldTimer--;
        if (e.frame % 30 === 0) setShieldTimeRemaining(Math.ceil(player.shieldTimer / 60));
      } else if (shieldTimeRemaining > 0) {
        setShieldTimeRemaining(0);
      }

      const ph = player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48);
      const pw = player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32);

      if (keys['ArrowRight'] || keys['KeyD']) { player.vel.x = currentStats.speed; player.facing = 1; }
      else if (keys['ArrowLeft'] || keys['KeyA']) { player.vel.x = -currentStats.speed; player.facing = -1; }
      else { player.vel.x *= 0.8; }

      if (e.unit === RobotUnit.FALCON && player.isTransformed) {
        if (keys['ArrowUp'] || keys['KeyW']) player.vel.y = -currentStats.speed;
        else if (keys['ArrowDown'] || keys['KeyS']) player.vel.y = currentStats.speed;
        else player.vel.y *= 0.9;
        player.grounded = false;
      } else {
        if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.grounded) {
          player.vel.y = currentStats.jump;
          player.grounded = false;
        }
        player.vel.y += GRAVITY;
      }

      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;

      const floorY = 398;
      if (player.pos.y > floorY - ph) { 
        player.pos.y = floorY - ph; 
        player.vel.y = 0; 
        player.grounded = true; 
      }
      if (player.pos.x < 0) player.pos.x = 0;
      setDistance(player.pos.x);

      const fr = Math.max(5, currentStats.fireRate - upgrades.weaponTier * 2);
      if (keys['Space'] && e.frame - player.lastShot > fr) {
        soundService.playShoot();
        const dmg = player.isTransformed ? 40 : (e.unit === RobotUnit.TITAN ? 60 : (e.unit === RobotUnit.SPECTER ? 80 : 25));
        bullets.push({ 
          pos: { x: player.pos.x + (player.facing === 1 ? pw : 0), y: player.pos.y + ph/2 }, 
          vel: { x: player.facing * (e.unit === RobotUnit.SPECTER ? 25 : 15), y: 0 }, 
          width: player.isTransformed ? 12 : 8, 
          height: 4, 
          owner: 'player', 
          health: 1, maxHealth: 1, damage: dmg, color: stats.color 
        });
        player.lastShot = e.frame;
      }

      for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i]; 
        b.pos.x += b.vel.x; 
        b.pos.y += b.vel.y;

        if (b.owner === 'enemy' && !player.invulnerable && player.shieldTimer <= 0) {
          if (b.pos.x < player.pos.x + pw && b.pos.x + b.width > player.pos.x &&
              b.pos.y < player.pos.y + ph && b.pos.y + b.height > player.pos.y) {
            setHealth(h => Math.max(0, h - (b.damage || 20))); // Increased fallback/base bullet damage
            player.invulnerable = 40;
            bullets.splice(i, 1);
            soundService.playLose();
            continue;
          }
        } else if (b.owner === 'enemy' && player.shieldTimer > 0) {
          if (b.pos.x < player.pos.x + pw + 20 && b.pos.x + b.width > player.pos.x - 20 &&
              b.pos.y < player.pos.y + ph + 20 && b.pos.y + b.height > player.pos.y - 20) {
            bullets.splice(i, 1);
            continue;
          }
        }

        if (Math.abs(b.pos.x - player.pos.x) > 1200) {
          bullets.splice(i, 1);
        }
      }

      let allDead = true;
      enemies.forEach(en => {
        if (en.isDead) return;
        allDead = false;

        const dist = Math.abs(en.pos.x - player.pos.x);
        const dir = Math.sign(player.pos.x - en.pos.x);
        const hpPercent = en.health / en.maxHealth;

        if (hpPercent < 0.3 && !en.isTransformed) {
          en.isTransformed = true;
          en.width *= 1.3;
          en.height *= 1.3;
        }

        const moveMult = en.isTransformed ? 2.2 : 1.0;

        switch(en.type) {
          case 'bot':
            if (dist > 350) en.vel.x = dir * 2 * moveMult;
            else if (dist < 200) en.vel.x = -dir * 2 * moveMult;
            else en.vel.x *= 0.8;
            break;
          case 'scout':
            en.vel.x = dir * 4 * moveMult;
            break;
          case 'sniper':
            if (dist < 500) en.vel.x = -dir * 3 * moveMult;
            else en.vel.x *= 0.5;
            break;
          case 'heavy':
          case 'titan':
            en.vel.x = dir * 1 * moveMult;
            break;
        }

        if (hpPercent < 0.5 && hpPercent >= 0.3 && en.type !== 'scout') {
          en.vel.x = -dir * 2.5;
        }

        en.pos.x += en.vel.x;

        if (dist < 600) {
          const rawCooldown = en.type === 'heavy' ? 120 : en.type === 'scout' ? 60 : en.type === 'sniper' ? 180 : 100;
          const cooldown = en.isTransformed ? rawCooldown * 0.4 : rawCooldown;

          if (e.frame - en.lastShot > cooldown) {
            switch(en.type) {
              case 'bot':
                // Damage increased from 10 to 18 (base) and 15 to 25 (transformed)
                bullets.push({ 
                  pos: {x: en.pos.x, y: en.pos.y + 15}, 
                  vel: {x: dir * (en.isTransformed ? 12 : 6), y: 0}, 
                  width: en.isTransformed ? 15 : 10, 
                  height: en.isTransformed ? 6 : 4, 
                  owner: 'enemy', health: 1, maxHealth: 1, 
                  damage: en.isTransformed ? 25 : 15, 
                  color: '#f00' 
                });
                en.lastShot = e.frame;
                break;
              case 'scout':
                // Damage increased from 6 to 10 per shot
                if (en.sequenceStage < (en.isTransformed ? 6 : 3)) {
                   if (e.frame % (en.isTransformed ? 4 : 8) === 0) {
                      bullets.push({ 
                        pos: {x: en.pos.x, y: en.pos.y + 10}, 
                        vel: {x: dir * (en.isTransformed ? 14 : 9), y: (Math.random()-0.5)*2}, 
                        width: 6, height: 3, 
                        owner: 'enemy', health: 1, maxHealth: 1, 
                        damage: 10, 
                        color: '#f55' 
                      });
                      en.sequenceStage++;
                   }
                } else {
                   en.sequenceStage = 0;
                   en.lastShot = e.frame;
                }
                break;
              case 'sniper':
                // Damage increased from 30 to 45 (base) and 45 to 65 (transformed)
                bullets.push({ 
                  pos: {x: en.pos.x, y: en.pos.y + 10}, 
                  vel: {x: dir * 16, y: 0}, 
                  width: 24, height: 2, 
                  owner: 'enemy', health: 1, maxHealth: 1, 
                  damage: en.isTransformed ? 65 : 45, 
                  color: '#fff' 
                });
                en.lastShot = e.frame;
                break;
              case 'heavy':
              case 'titan':
                // Damage increased from 25 to 40
                const numBullets = en.isTransformed ? 7 : 3;
                for(let j=-(numBullets>>1); j<=(numBullets>>1); j++) {
                  bullets.push({ 
                    pos: {x: en.pos.x, y: en.pos.y + 30}, 
                    vel: {x: dir * 6, y: j * (en.isTransformed ? 2 : 1.2)}, 
                    width: 14, height: 10, 
                    owner: 'enemy', health: 1, maxHealth: 1, 
                    damage: 40, 
                    color: '#f00' 
                  });
                }
                en.lastShot = e.frame;
                break;
            }
          }
        }

        bullets.forEach((b, idx) => {
          if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) {
            en.health -= b.damage || 20; 
            bullets.splice(idx, 1);
            if (en.health <= 0) en.isDead = true;
          }
        });

        // Collision Damage increased from 25/45 to 40/60
        if (!player.invulnerable && player.shieldTimer <= 0 && player.pos.x < en.pos.x + en.width && player.pos.x + pw > en.pos.x && player.pos.y < en.pos.y + en.height && player.pos.y + ph > en.pos.y) {
           setHealth(h => Math.max(0, h - (en.type === 'heavy' ? 60 : 40))); 
           player.invulnerable = 60; 
           soundService.playLose();
        }
      });

      if (health <= 0) onDie();
      if (allDead) onWin();
      if (player.invulnerable > 0) player.invulnerable--;
      e.cameraX = player.pos.x - CANVAS_WIDTH/3;
      if (e.cameraX < 0) e.cameraX = 0;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const e = engineRef.current;
      ctx.fillStyle = '#050510'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

      ctx.fillStyle = '#1c1c1c'; ctx.fillRect(0, 398, CANVAS_WIDTH, 52);
      ctx.strokeStyle = '#222';
      for(let i=0; i<CANVAS_WIDTH; i+=40) {
        ctx.beginPath(); ctx.moveTo(i - (e.cameraX % 40), 398); ctx.lineTo(i - (e.cameraX % 40), CANVAS_HEIGHT); ctx.stroke();
      }

      e.enemies.forEach(en => { 
        if(!en.isDead) drawUnit(ctx, en.pos.x - e.cameraX, en.pos.y, en.width, en.height, RobotUnit.SENTINEL, Math.sign(e.player.pos.x - en.pos.x), e.frame, true, false, en.isTransformed, en.type); 
      });

      const player = e.player;
      const ph = player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48);
      const pw = player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32);

      drawUnit(ctx, player.pos.x - e.cameraX, player.pos.y, pw, ph, e.unit, player.facing, e.frame, false, player.invulnerable > 0, player.isTransformed);

      if (player.shieldTimer > 0) {
        const shieldPulse = Math.sin(e.frame * 0.1) * 5;
        ctx.save();
        ctx.translate(player.pos.x - e.cameraX + pw / 2, player.pos.y + ph / 2);
        ctx.beginPath();
        ctx.arc(0, 0, Math.max(pw, ph) * 0.8 + shieldPulse, 0, Math.PI * 2);
        ctx.strokeStyle = '#00f3ff';
        ctx.lineWidth = 3;
        ctx.shadowBlur = 15;
        ctx.shadowColor = '#00f3ff';
        ctx.stroke();
        ctx.globalAlpha = 0.2;
        ctx.fillStyle = '#00f3ff';
        ctx.fill();
        ctx.restore();
      }

      e.bullets.forEach(b => { 
        ctx.fillStyle = b.color || (b.owner === 'player' ? '#00f3ff' : '#ff0055'); 
        ctx.fillRect(b.pos.x - e.cameraX, b.pos.y, b.width, b.height); 
      });
    };

    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [resetLevel, onWin, onDie, level, upgrades, health, currentUnit, shieldTimeRemaining]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden">
      <div className="absolute top-4 left-4 z-10 space-y-4 pointer-events-none">
        <div className="bg-black/80 border border-cyan-500/50 p-3 rounded backdrop-blur-md shadow-lg">
          <div className="text-[10px] text-cyan-400 font-bold uppercase mb-1 flex justify-between font-orbitron">
            <span>{ROBOT_STATS[currentUnit].name} INTEGRITY</span>
            <span>{Math.round(health)}/{Math.round(maxHealth)}</span>
          </div>
          <div className="w-48 h-2.5 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
            <div 
              className="h-full shadow-[0_0_15px_#00f3ff] transition-all duration-300" 
              style={{ 
                width: `${(health / maxHealth) * 100}%`,
                backgroundColor: health < maxHealth * 0.3 ? '#ef4444' : '#00f3ff'
              }} 
            />
          </div>
          {shieldTimeRemaining > 0 && (
            <div className="mt-2 flex items-center gap-2">
              <div className="text-[10px] text-blue-400 font-black animate-pulse font-orbitron">SHIELD ACTIVE: {shieldTimeRemaining}s</div>
              <div className="flex-1 h-1 bg-blue-900 rounded-full overflow-hidden">
                <div className="h-full bg-cyan-400" style={{ width: `${(shieldTimeRemaining / 20) * 100}%` }}></div>
              </div>
            </div>
          )}
          <div className="mt-2 text-[8px] text-white/50 font-mono flex justify-between">
            <span>MODE: {isTransformed ? `ALT (${ROBOT_STATS[currentUnit].alt.type})` : 'HUMANOID'}</span>
            <span className="animate-pulse text-cyan-400 font-bold">[SHIFT TO TOGGLE]</span>
          </div>
        </div>

        <div className="flex flex-col gap-2 pointer-events-auto">
           <div className="text-[10px] text-white/50 font-bold uppercase tracking-tighter ml-1 font-orbitron">SQUAD_DEPLOYMENT [1-5]</div>
           <div className="flex gap-2">
           {(Object.keys(ROBOT_STATS) as RobotUnit[]).map((u, i) => {
             const stats = ROBOT_STATS[u];
             const isActive = currentUnit === u;
             return (
               <button 
                 key={u} 
                 onClick={() => setCurrentUnit(u)}
                 className={`group relative w-12 h-12 flex flex-col items-center justify-center rounded-sm border-2 transition-all duration-200 ${
                   isActive 
                     ? 'bg-white/10' 
                     : 'border-gray-800 bg-black/60 hover:border-gray-600'
                 }`}
                 style={{
                   borderColor: isActive ? stats.color : '',
                   boxShadow: isActive ? `0 0 20px ${stats.color}50, inset 0 0 8px ${stats.color}30` : 'none'
                 }}
               >
                 {isActive && (
                   <>
                     <div className="absolute -top-1.5 -left-1.5 w-3 h-3 border-t-2 border-l-2" style={{ borderColor: stats.color }} />
                     <div className="absolute -bottom-1.5 -right-1.5 w-3 h-3 border-b-2 border-r-2" style={{ borderColor: stats.color }} />
                   </>
                 )}
                 <span className={`text-xl font-black font-orbitron transition-colors ${isActive ? 'text-white' : 'text-gray-600'}`}>
                   {i + 1}
                 </span>
                 <div className={`absolute -bottom-8 px-2 py-0.5 rounded bg-black/90 border border-gray-700 text-[8px] font-bold uppercase tracking-widest text-white transition-opacity whitespace-nowrap ${isActive ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}>
                    {stats.name}
                 </div>
                 {isActive && (
                    <div className="absolute -top-4 left-1/2 -translate-x-1/2 w-1.5 h-1.5 bg-white rounded-full animate-ping" />
                 )}
               </button>
             );
           })}
           </div>
        </div>
      </div>

      <div className="absolute top-4 right-4 z-10 text-right pointer-events-none font-orbitron">
        <div className="text-[10px] text-cyan-500 font-bold uppercase tracking-widest">Active Sector</div>
        <div className="text-3xl font-black text-white italic drop-shadow-md">{level.toString().padStart(2, '0')}</div>
      </div>

      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full aspect-video shadow-2xl rounded-lg border-2 border-cyan-900/50" />

      {health < maxHealth * 0.3 && (
        <div className="absolute inset-0 pointer-events-none border-[16px] border-red-600/20 animate-pulse shadow-[inset_0_0_100px_rgba(239,68,68,0.3)]"></div>
      )}

      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 pointer-events-none text-white/30 text-[9px] font-mono tracking-widest uppercase flex gap-8">
        <span>WASD: Move</span>
        <span>Space: Fire</span>
        <span>Shift: Transform</span>
        <span>U: Activate Shield</span>
        <span>1-5: Switch Squad</span>
      </div>
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const SHIELD_DURATION = 20 * 60; // 20 seconds at 60fps

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { 
    name: "SENTINEL", color: '#00f3ff', hpMult: 1.0, 
    robot: { speed: 4, jump: -11, fireRate: 15 },
    alt: { speed: 8, jump: -5, fireRate: 25, type: 'Car' }
  },
  [RobotUnit.STRIKER]: { 
    name: "STRIKER", color: '#fbbf24', hpMult: 0.8,
    robot: { speed: 6, jump: -10, fireRate: 10 },
    alt: { speed: 12, jump: -4, fireRate: 20, type: 'Bike' }
  },
  [RobotUnit.FALCON]: { 
    name: "FALCON", color: '#22d3ee', hpMult: 0.7,
    robot: { speed: 5, jump: -10, fireRate: 12 },
    alt: { speed: 7, jump: -7, fireRate: 15, type: 'Jet' }
  },
  [RobotUnit.TITAN]: { 
    name: "TITAN", color: '#ef4444', hpMult: 2.5,
    robot: { speed: 2.5, jump: -12, fireRate: 30 },
    alt: { speed: 4, jump: 0, fireRate: 20, type: 'Tank' }
  },
  [RobotUnit.SPECTER]: { 
    name: "SPECTER", color: '#a855f7', hpMult: 0.6,
    robot: { speed: 5, jump: -11, fireRate: 20 },
    alt: { speed: 6, jump: -14, fireRate: 40, type: 'Sphere' }
  },
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [currentUnit, setCurrentUnit] = useState<RobotUnit>(RobotUnit.SENTINEL);
  const [isTransformed, setIsTransformed] = useState(false);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [distance, setDistance] = useState(0);
  const [shieldTimeRemaining, setShieldTimeRemaining] = useState(0);

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      maxHealth: 100,
      isTransformed: false,
      shieldTimer: 0,
    },
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    unit: RobotUnit.SENTINEL,
    level: level,
  });

  useEffect(() => { engineRef.current.isPaused = isPaused; }, [isPaused]);
  useEffect(() => { 
    engineRef.current.unit = currentUnit;
    engineRef.current.player.isTransformed = false;
    setIsTransformed(false);
  }, [currentUnit]);
  useEffect(() => { engineRef.current.level = level; }, [level]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff44');
    grad.addColorStop(1, '#00000088');
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.5)';
    ctx.stroke();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, type = 'bot', isTransformed = false) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8;
    const armSwing = Math.cos(time) * 10;

    let scale = 1;
    if (type === 'scout') scale = 0.8;
    if (type === 'heavy' || type === 'titan') scale = 1.4;

    if (isEnemy && isTransformed) {
      scale *= 1.25;
      ctx.translate((Math.random() - 0.5) * 3, (Math.random() - 0.5) * 3);
    }

    ctx.save();
    ctx.scale(scale, scale);

    if (isEnemy && isTransformed) {
      ctx.shadowBlur = 20;
      ctx.shadowColor = '#ff3300';
    }

    drawMechanicalPart(ctx, -12, -18, 24, 28, isTransformed ? '#400' : color, 4);
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? (isTransformed ? '#fff' : '#ff0000') : '#00f3ff';
    ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);

    if (isEnemy && isTransformed) {
      const corePulse = Math.sin(frame * 0.4) * 3;
      ctx.fillStyle = frame % 4 < 2 ? '#ff0000' : '#ffffff';
      ctx.beginPath();
      ctx.arc(0, -5, 5 + corePulse, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.restore();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, color: string, frame: number) => {
    switch(unit) {
      case RobotUnit.SENTINEL:
        drawMechanicalPart(ctx, -24, -10, 48, 18, color, 8);
        drawMechanicalPart(ctx, -16, -20, 30, 12, '#111', 4);
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(-15, 10, 7, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(15, 10, 7, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = frame % 10 < 5 ? '#ff0000' : '#0000ff';
        ctx.fillRect(-4, -22, 10, 3);
        break;
      case RobotUnit.STRIKER:
        drawMechanicalPart(ctx, -18, -8, 36, 12, color, 4);
        drawMechanicalPart(ctx, -5, -18, 18, 12, '#222', 2);
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(-18, 8, 9, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(18, 8, 9, 0, Math.PI * 2); ctx.fill();
        break;
      case RobotUnit.FALCON:
        drawMechanicalPart(ctx, -20, -10, 40, 15, color, 12);
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(-10, -5); ctx.lineTo(-30, -15); ctx.lineTo(-10, 5); ctx.fill();
        ctx.fillStyle = '#ffaa00';
        ctx.fillRect(-28, -5, 8, 5);
        break;
      case RobotUnit.TITAN:
        drawMechanicalPart(ctx, -30, -10, 60, 22, color, 4);
        drawMechanicalPart(ctx, -15, -25, 30, 15, '#222', 4);
        drawMechanicalPart(ctx, 10, -20, 25, 5, '#444', 0);
        ctx.fillStyle = '#111';
        ctx.fillRect(-28, 8, 56, 6);
        break;
      case RobotUnit.SPECTER:
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.arc(0, 0, 18, 0, Math.PI * 2); ctx.fill();
        ctx.strokeStyle = '#fff'; ctx.lineWidth = 1; ctx.stroke();
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(8, -4, 4, 0, Math.PI * 2); ctx.fill();
        break;
    }
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy = false, isInvuln = false, isTransformed = false, type = 'bot') => {
    if (isInvuln && frame % 4 < 2) return;

    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    if (facing === -1) ctx.scale(-1, 1);

    const stats = ROBOT_STATS[unit];
    const color = isEnemy ? '#ff0055' : stats.color;

    if (isTransformed && !isEnemy) {
      drawAltMode(ctx, unit, color, frame);
    } else {
      drawHumanoid(ctx, color, frame, isEnemy, type, isTransformed);
    }

    ctx.restore();
  };

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    const stats = ROBOT_STATS[currentUnit];
    const baseHP = 100 + (upgrades.robotTier * 50);

    e.player.maxHealth = baseHP * stats.hpMult;
    e.player.shieldTimer = 0;
    setShieldTimeRemaining(0);
    setMaxHealth(e.player.maxHealth);
    setHealth(e.player.maxHealth);

    e.player.pos = { x: 100, y: 300 };
    e.player.vel = { x: 0, y: 0 };
    e.player.invulnerable = 0;
    e.player.isTransformed = false;
    setIsTransformed(false);
    e.bullets = [];
    e.cameraX = 0;
    setDistance(0);

    const enemies: Enemy[] = [];
    const floorY = 398;

    const enemyTypes = ['bot', 'scout', 'sniper', 'heavy'];
    for (let i = 0; i < 4; i++) {
      const type = enemyTypes[i % (level < 5 ? 1 : level < 10 ? 2 : 4)];
      let w = 32, h = 48, hp = 50 + level * 15;
      if (type === 'scout') { w = 24; h = 36; hp = 40 + level * 5; }
      if (type === 'heavy') { w = 48; h = 72; hp = 150 + level * 20; }

      enemies.push({ 
        id: i, 
        pos: { x: 800 + i * 700, y: floorY - h }, 
        vel: { x: 0, y: 0 }, 
        width: w, 
        height: h, 
        health: hp, 
        maxHealth: hp, 
        isDead: false, 
        type: type, 
        lastShot: 0,
        sequenceStage: 0,
        sequenceTimer: 0,
        isTransformed: false,
        transformTimer: 0
      });
    }

    enemies.push({ 
      id: 4, 
      pos: { x: 4000, y: floorY - 96 }, 
      vel: { x: 0, y: 0 }, 
      width: 80, 
      height: 96, 
      health: 500 + level * 50, 
      maxHealth: 500 + level * 50, 
      isDead: false, 
      type: 'titan', 
      lastShot: 0,
      isTransformed: false
    });
    e.enemies = enemies;
  }, [level, upgrades, currentUnit]);

  useEffect(() => {
    resetLevel();
    const handleKeyDown = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = true;
      if (e.code === 'Digit1') setCurrentUnit(RobotUnit.SENTINEL);
      if (e.code === 'Digit2') setCurrentUnit(RobotUnit.STRIKER);
      if (e.code === 'Digit3') setCurrentUnit(RobotUnit.FALCON);
      if (e.code === 'Digit4') setCurrentUnit(RobotUnit.TITAN);
      if (e.code === 'Digit5') setCurrentUnit(RobotUnit.SPECTER);

      if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') {
        engineRef.current.player.isTransformed = !engineRef.current.player.isTransformed;
        setIsTransformed(engineRef.current.player.isTransformed);
      }

      if (e.code === 'KeyU') {
        engineRef.current.player.shieldTimer = SHIELD_DURATION;
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => { engineRef.current.keys[e.code] = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!engineRef.current.isPaused) update();
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const e = engineRef.current;
      const { player, enemies, bullets, keys } = e;
      const stats = ROBOT_STATS[e.unit];
      const currentStats = player.isTransformed ? stats.alt : stats.robot;
      e.frame++;

      if (player.shieldTimer > 0) {
        player.shieldTimer--;
        if (e.frame % 30 === 0) setShieldTimeRemaining(Math.ceil(player.shieldTimer / 60));
      } else if (shieldTimeRemaining > 0) {
        setShieldTimeRemaining(0);
      }

      const ph = player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48);
      const pw = player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32);

      if (keys['ArrowRight'] || keys['KeyD']) { player.vel.x = currentStats.speed; player.facing = 1; }
      else if (keys['ArrowLeft'] || keys['KeyA']) { player.vel.x = -currentStats.speed; player.facing = -1; }
      else { player.vel.x *= 0.8; }

      if (e.unit === RobotUnit.FALCON && player.isTransformed) {
        if (keys['ArrowUp'] || keys['KeyW']) player.vel.y = -currentStats.speed;
        else if (keys['ArrowDown'] || keys['KeyS']) player.vel.y = currentStats.speed;
        else player.vel.y *= 0.9;
        player.grounded = false;
      } else {
        if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.grounded) {
          player.vel.y = currentStats.jump;
          player.grounded = false;
        }
        player.vel.y += GRAVITY;
      }

      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;

      const floorY = 398;
      if (player.pos.y > floorY - ph) { 
        player.pos.y = floorY - ph; 
        player.vel.y = 0; 
        player.grounded = true; 
      }
      if (player.pos.x < 0) player.pos.x = 0;
      setDistance(player.pos.x);

      const fr = Math.max(5, currentStats.fireRate - upgrades.weaponTier * 2);
      if (keys['Space'] && e.frame - player.lastShot > fr) {
        soundService.playShoot();
        const dmg = player.isTransformed ? 40 : (e.unit === RobotUnit.TITAN ? 60 : (e.unit === RobotUnit.SPECTER ? 80 : 25));
        bullets.push({ 
          pos: { x: player.pos.x + (player.facing === 1 ? pw : 0), y: player.pos.y + ph/2 }, 
          vel: { x: player.facing * (e.unit === RobotUnit.SPECTER ? 25 : 15), y: 0 }, 
          width: player.isTransformed ? 12 : 8, 
          height: 4, 
          owner: 'player', 
          health: 1, maxHealth: 1, damage: dmg, color: stats.color 
        });
        player.lastShot = e.frame;
      }

      for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i]; 
        b.pos.x += b.vel.x; 
        b.pos.y += b.vel.y;

        if (b.owner === 'enemy' && !player.invulnerable && player.shieldTimer <= 0) {
          if (b.pos.x < player.pos.x + pw && b.pos.x + b.width > player.pos.x &&
              b.pos.y < player.pos.y + ph && b.pos.y + b.height > player.pos.y) {
            setHealth(h => Math.max(0, h - (b.damage || 40))); // Significantly increased base/fallback damage
            player.invulnerable = 40;
            bullets.splice(i, 1);
            soundService.playLose();
            continue;
          }
        } else if (b.owner === 'enemy' && player.shieldTimer > 0) {
          if (b.pos.x < player.pos.x + pw + 20 && b.pos.x + b.width > player.pos.x - 20 &&
              b.pos.y < player.pos.y + ph + 20 && b.pos.y + b.height > player.pos.y - 20) {
            bullets.splice(i, 1);
            continue;
          }
        }

        if (Math.abs(b.pos.x - player.pos.x) > 1200) {
          bullets.splice(i, 1);
        }
      }

      let allDead = true;
      enemies.forEach(en => {
        if (en.isDead) return;
        allDead = false;

        const dist = Math.abs(en.pos.x - player.pos.x);
        const dir = Math.sign(player.pos.x - en.pos.x);
        const hpPercent = en.health / en.maxHealth;

        if (hpPercent < 0.3 && !en.isTransformed) {
          en.isTransformed = true;
          en.width *= 1.3;
          en.height *= 1.3;
        }

        const moveMult = en.isTransformed ? 2.2 : 1.0;

        switch(en.type) {
          case 'bot':
            if (dist > 350) en.vel.x = dir * 2 * moveMult;
            else if (dist < 200) en.vel.x = -dir * 2 * moveMult;
            else en.vel.x *= 0.8;
            break;
          case 'scout':
            en.vel.x = dir * 4 * moveMult;
            break;
          case 'sniper':
            if (dist < 500) en.vel.x = -dir * 3 * moveMult;
            else en.vel.x *= 0.5;
            break;
          case 'heavy':
          case 'titan':
            en.vel.x = dir * 1 * moveMult;
            break;
        }

        if (hpPercent < 0.5 && hpPercent >= 0.3 && en.type !== 'scout') {
          en.vel.x = -dir * 2.5;
        }

        en.pos.x += en.vel.x;

        if (dist < 600) {
          const rawCooldown = en.type === 'heavy' ? 120 : en.type === 'scout' ? 60 : en.type === 'sniper' ? 180 : 100;
          const cooldown = en.isTransformed ? rawCooldown * 0.4 : rawCooldown;

          if (e.frame - en.lastShot > cooldown) {
            switch(en.type) {
              case 'bot':
                // Substantially increased: 15/25 -> 35/60
                bullets.push({ 
                  pos: {x: en.pos.x, y: en.pos.y + 15}, 
                  vel: {x: dir * (en.isTransformed ? 12 : 6), y: 0}, 
                  width: en.isTransformed ? 15 : 10, 
                  height: en.isTransformed ? 6 : 4, 
                  owner: 'enemy', health: 1, maxHealth: 1, 
                  damage: en.isTransformed ? 60 : 35, 
                  color: '#f00' 
                });
                en.lastShot = e.frame;
                break;
              case 'scout':
                // Substantially increased: 10 -> 25 per hit in burst
                if (en.sequenceStage < (en.isTransformed ? 6 : 3)) {
                   if (e.frame % (en.isTransformed ? 4 : 8) === 0) {
                      bullets.push({ 
                        pos: {x: en.pos.x, y: en.pos.y + 10}, 
                        vel: {x: dir * (en.isTransformed ? 14 : 9), y: (Math.random()-0.5)*2}, 
                        width: 6, height: 3, 
                        owner: 'enemy', health: 1, maxHealth: 1, 
                        damage: 25, 
                        color: '#f55' 
                      });
                      en.sequenceStage++;
                   }
                } else {
                   en.sequenceStage = 0;
                   en.lastShot = e.frame;
                }
                break;
              case 'sniper':
                // Deadly: 45/65 -> 100/180
                bullets.push({ 
                  pos: {x: en.pos.x, y: en.pos.y + 10}, 
                  vel: {x: dir * 16, y: 0}, 
                  width: 24, height: 2, 
                  owner: 'enemy', health: 1, maxHealth: 1, 
                  damage: en.isTransformed ? 180 : 100, 
                  color: '#fff' 
                });
                en.lastShot = e.frame;
                break;
              case 'heavy':
              case 'titan':
                // Devastating spread: 40 -> 100 per bullet
                const numBullets = en.isTransformed ? 7 : 3;
                for(let j=-(numBullets>>1); j<=(numBullets>>1); j++) {
                  bullets.push({ 
                    pos: {x: en.pos.x, y: en.pos.y + 30}, 
                    vel: {x: dir * 6, y: j * (en.isTransformed ? 2 : 1.2)}, 
                    width: 14, height: 10, 
                    owner: 'enemy', health: 1, maxHealth: 1, 
                    damage: 100, 
                    color: '#f00' 
                  });
                }
                en.lastShot = e.frame;
                break;
            }
          }
        }

        bullets.forEach((b, idx) => {
          if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) {
            en.health -= b.damage || 20; 
            bullets.splice(idx, 1);
            if (en.health <= 0) en.isDead = true;
          }
        });

        // Lethal Collision Damage: 40/60 -> 80/150
        if (!player.invulnerable && player.shieldTimer <= 0 && player.pos.x < en.pos.x + en.width && player.pos.x + pw > en.pos.x && player.pos.y < en.pos.y + en.height && player.pos.y + ph > en.pos.y) {
           setHealth(h => Math.max(0, h - (en.type === 'heavy' || en.type === 'titan' ? 150 : 80))); 
           player.invulnerable = 60; 
           soundService.playLose();
        }
      });

      if (health <= 0) onDie();
      if (allDead) onWin();
      if (player.invulnerable > 0) player.invulnerable--;
      e.cameraX = player.pos.x - CANVAS_WIDTH/3;
      if (e.cameraX < 0) e.cameraX = 0;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const e = engineRef.current;
      ctx.fillStyle = '#050510'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

      ctx.fillStyle = '#1c1c1c'; ctx.fillRect(0, 398, CANVAS_WIDTH, 52);
      ctx.strokeStyle = '#222';
      for(let i=0; i<CANVAS_WIDTH; i+=40) {
        ctx.beginPath(); ctx.moveTo(i - (e.cameraX % 40), 398); ctx.lineTo(i - (e.cameraX % 40), CANVAS_HEIGHT); ctx.stroke();
      }

      e.enemies.forEach(en => { 
        if(!en.isDead) drawUnit(ctx, en.pos.x - e.cameraX, en.pos.y, en.width, en.height, RobotUnit.SENTINEL, Math.sign(e.player.pos.x - en.pos.x), e.frame, true, false, en.isTransformed, en.type); 
      });

      const player = e.player;
      const ph = player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48);
      const pw = player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32);

      drawUnit(ctx, player.pos.x - e.cameraX, player.pos.y, pw, ph, e.unit, player.facing, e.frame, false, player.invulnerable > 0, player.isTransformed);

      if (player.shieldTimer > 0) {
        const shieldPulse = Math.sin(e.frame * 0.1) * 5;
        ctx.save();
        ctx.translate(player.pos.x - e.cameraX + pw / 2, player.pos.y + ph / 2);
        ctx.beginPath();
        ctx.arc(0, 0, Math.max(pw, ph) * 0.8 + shieldPulse, 0, Math.PI * 2);
        ctx.strokeStyle = '#00f3ff';
        ctx.lineWidth = 3;
        ctx.shadowBlur = 15;
        ctx.shadowColor = '#00f3ff';
        ctx.stroke();
        ctx.globalAlpha = 0.2;
        ctx.fillStyle = '#00f3ff';
        ctx.fill();
        ctx.restore();
      }

      e.bullets.forEach(b => { 
        ctx.fillStyle = b.color || (b.owner === 'player' ? '#00f3ff' : '#ff0055'); 
        ctx.fillRect(b.pos.x - e.cameraX, b.pos.y, b.width, b.height); 
      });
    };

    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [resetLevel, onWin, onDie, level, upgrades, health, currentUnit, shieldTimeRemaining]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden">
      <div className="absolute top-4 left-4 z-10 space-y-4 pointer-events-none">
        <div className="bg-black/80 border border-cyan-500/50 p-3 rounded backdrop-blur-md shadow-lg">
          <div className="text-[10px] text-cyan-400 font-bold uppercase mb-1 flex justify-between font-orbitron">
            <span>{ROBOT_STATS[currentUnit].name} INTEGRITY</span>
            <span>{Math.round(health)}/{Math.round(maxHealth)}</span>
          </div>
          <div className="w-48 h-2.5 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
            <div 
              className="h-full shadow-[0_0_15px_#00f3ff] transition-all duration-300" 
              style={{ 
                width: `${(health / maxHealth) * 100}%`,
                backgroundColor: health < maxHealth * 0.3 ? '#ef4444' : '#00f3ff'
              }} 
            />
          </div>
          {shieldTimeRemaining > 0 && (
            <div className="mt-2 flex items-center gap-2">
              <div className="text-[10px] text-blue-400 font-black animate-pulse font-orbitron">SHIELD ACTIVE: {shieldTimeRemaining}s</div>
              <div className="flex-1 h-1 bg-blue-900 rounded-full overflow-hidden">
                <div className="h-full bg-cyan-400" style={{ width: `${(shieldTimeRemaining / 20) * 100}%` }}></div>
              </div>
            </div>
          )}
          <div className="mt-2 text-[8px] text-white/50 font-mono flex justify-between">
            <span>MODE: {isTransformed ? `ALT (${ROBOT_STATS[currentUnit].alt.type})` : 'HUMANOID'}</span>
            <span className="animate-pulse text-red-500 font-bold uppercase">[DANGER: HIGH LETHALITY]</span>
          </div>
        </div>

        <div className="flex flex-col gap-2 pointer-events-auto">
           <div className="text-[10px] text-white/50 font-bold uppercase tracking-tighter ml-1 font-orbitron">SQUAD_DEPLOYMENT [1-5]</div>
           <div className="flex gap-2">
           {(Object.keys(ROBOT_STATS) as RobotUnit[]).map((u, i) => {
             const stats = ROBOT_STATS[u];
             const isActive = currentUnit === u;
             return (
               <button 
                 key={u} 
                 onClick={() => setCurrentUnit(u)}
                 className={`group relative w-12 h-12 flex flex-col items-center justify-center rounded-sm border-2 transition-all duration-200 ${
                   isActive 
                     ? 'bg-white/10' 
                     : 'border-gray-800 bg-black/60 hover:border-gray-600'
                 }`}
                 style={{
                   borderColor: isActive ? stats.color : '',
                   boxShadow: isActive ? `0 0 20px ${stats.color}50, inset 0 0 8px ${stats.color}30` : 'none'
                 }}
               >
                 {isActive && (
                   <>
                     <div className="absolute -top-1.5 -left-1.5 w-3 h-3 border-t-2 border-l-2" style={{ borderColor: stats.color }} />
                     <div className="absolute -bottom-1.5 -right-1.5 w-3 h-3 border-b-2 border-r-2" style={{ borderColor: stats.color }} />
                   </>
                 )}
                 <span className={`text-xl font-black font-orbitron transition-colors ${isActive ? 'text-white' : 'text-gray-600'}`}>
                   {i + 1}
                 </span>
                 <div className={`absolute -bottom-8 px-2 py-0.5 rounded bg-black/90 border border-gray-700 text-[8px] font-bold uppercase tracking-widest text-white transition-opacity whitespace-nowrap ${isActive ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}>
                    {stats.name}
                 </div>
                 {isActive && (
                    <div className="absolute -top-4 left-1/2 -translate-x-1/2 w-1.5 h-1.5 bg-white rounded-full animate-ping" />
                 )}
               </button>
             );
           })}
           </div>
        </div>
      </div>

      <div className="absolute top-4 right-4 z-10 text-right pointer-events-none font-orbitron">
        <div className="text-[10px] text-cyan-500 font-bold uppercase tracking-widest">Active Sector</div>
        <div className="text-3xl font-black text-white italic drop-shadow-md">{level.toString().padStart(2, '0')}</div>
      </div>

      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full aspect-video shadow-2xl rounded-lg border-2 border-cyan-900/50" />

      {health < maxHealth * 0.3 && (
        <div className="absolute inset-0 pointer-events-none border-[16px] border-red-600/20 animate-pulse shadow-[inset_0_0_100px_rgba(239,68,68,0.3)]"></div>
      )}

      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 pointer-events-none text-white/30 text-[9px] font-mono tracking-widest uppercase flex gap-8">
        <span>WASD: Move</span>
        <span>Space: Fire</span>
        <span>Shift: Transform</span>
        <span>U: Shield</span>
        <span>1-5: Switch Squad</span>
      </div>
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';
import { Pause, Play, Shield, Zap } from 'lucide-react';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
  onPauseToggle?: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const SHIELD_DURATION = 20 * 60; // 20 seconds at 60fps
const SHIELD_COOLDOWN = 40 * 60; // 40 seconds cooldown

interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  life: number;
  color: string;
  size: number;
}

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { 
    name: "SENTINEL", color: '#00f3ff', hpMult: 1.0, 
    robot: { speed: 4, jump: -11, fireRate: 15 },
    alt: { speed: 8, jump: -5, fireRate: 25, type: 'Car' }
  },
  [RobotUnit.STRIKER]: { 
    name: "STRIKER", color: '#fbbf24', hpMult: 0.8,
    robot: { speed: 6, jump: -10, fireRate: 10 },
    alt: { speed: 12, jump: -4, fireRate: 20, type: 'Bike' }
  },
  [RobotUnit.FALCON]: { 
    name: "FALCON", color: '#22d3ee', hpMult: 0.7,
    robot: { speed: 5, jump: -10, fireRate: 12 },
    alt: { speed: 7, jump: -7, fireRate: 15, type: 'Jet' }
  },
  [RobotUnit.TITAN]: { 
    name: "TITAN", color: '#ef4444', hpMult: 2.5,
    robot: { speed: 2.5, jump: -12, fireRate: 30 },
    alt: { speed: 4, jump: 0, fireRate: 20, type: 'Tank' }
  },
  [RobotUnit.SPECTER]: { 
    name: "SPECTER", color: '#a855f7', hpMult: 0.6,
    robot: { speed: 5, jump: -11, fireRate: 20 },
    alt: { speed: 6, jump: -14, fireRate: 40, type: 'Sphere' }
  },
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie, onPauseToggle }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [currentUnit, setCurrentUnit] = useState<RobotUnit>(RobotUnit.SENTINEL);
  const [isTransformed, setIsTransformed] = useState(false);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [distance, setDistance] = useState(0);
  const [shieldTimeRemaining, setShieldTimeRemaining] = useState(0);
  const [shieldCooldownRemaining, setShieldCooldownRemaining] = useState(0);

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      maxHealth: 100,
      isTransformed: false,
      shieldTimer: 0,
      shieldCooldown: 0,
    },
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    particles: [] as Particle[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    unit: RobotUnit.SENTINEL,
    level: level,
    screenShake: 0,
  });

  useEffect(() => { engineRef.current.isPaused = isPaused; }, [isPaused]);
  useEffect(() => { 
    engineRef.current.unit = currentUnit;
    engineRef.current.player.isTransformed = false;
    setIsTransformed(false);
  }, [currentUnit]);
  useEffect(() => { engineRef.current.level = level; }, [level]);

  const createExplosion = (x: number, y: number, color: string, count = 15) => {
    for (let i = 0; i < count; i++) {
      engineRef.current.particles.push({
        x, y,
        vx: (Math.random() - 0.5) * 8,
        vy: (Math.random() - 0.5) * 8,
        life: 20 + Math.random() * 20,
        color: color,
        size: 1 + Math.random() * 3
      });
    }
  };

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff44');
    grad.addColorStop(1, '#00000088');
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.5)';
    ctx.stroke();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, type = 'bot', isTransformed = false) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8;
    const armSwing = Math.cos(time) * 10;

    let scale = 1;
    if (type === 'scout') scale = 0.8;
    if (type === 'heavy' || type === 'titan') scale = 1.4;

    if (isEnemy && isTransformed) {
      scale *= 1.25;
      ctx.translate((Math.random() - 0.5) * 3, (Math.random() - 0.5) * 3);
    }

    ctx.save();
    ctx.scale(scale, scale);

    if (isEnemy && isTransformed) {
      ctx.shadowBlur = 20;
      ctx.shadowColor = '#ff3300';
    }

    drawMechanicalPart(ctx, -12, -18, 24, 28, isTransformed ? '#400' : color, 4);
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? (isTransformed ? '#fff' : '#ff0000') : '#00f3ff';
    ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);

    if (isEnemy && isTransformed) {
      const corePulse = Math.sin(frame * 0.4) * 3;
      ctx.fillStyle = frame % 4 < 2 ? '#ff0000' : '#ffffff';
      ctx.beginPath();
      ctx.arc(0, -5, 5 + corePulse, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.restore();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, color: string, frame: number) => {
    switch(unit) {
      case RobotUnit.SENTINEL:
        drawMechanicalPart(ctx, -24, -10, 48, 18, color, 8);
        drawMechanicalPart(ctx, -16, -20, 30, 12, '#111', 4);
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(-15, 10, 7, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(15, 10, 7, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = frame % 10 < 5 ? '#ff0000' : '#0000ff';
        ctx.fillRect(-4, -22, 10, 3);
        break;
      case RobotUnit.STRIKER:
        drawMechanicalPart(ctx, -18, -8, 36, 12, color, 4);
        drawMechanicalPart(ctx, -5, -18, 18, 12, '#222', 2);
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(-18, 8, 9, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(18, 8, 9, 0, Math.PI * 2); ctx.fill();
        break;
      default:
        // Placeholder for other units' alt modes
        drawMechanicalPart(ctx, -20, -10, 40, 20, color, 4);
        break;
    }
  };

  // Fix: Missing return statement and closing braces for GameView component.
  // This return statement ensures the canvas and health bar are rendered.
  // Also adding the default export to satisfy the import in App.tsx.
  return (
    <div className="relative w-full h-full">
      <canvas
        ref={canvasRef}
        width={CANVAS_WIDTH}
        height={CANVAS_HEIGHT}
        className="w-full h-full object-contain bg-slate-900 border-b-4 border-cyan-500 shadow-[0_0_50px_rgba(6,182,212,0.1)]"
      />
      <div className="absolute top-6 left-6 flex flex-col gap-4">
        <div className="bg-black/70 border-l-4 border-cyan-500 p-4 backdrop-blur-md shadow-xl">
          <div className="text-[10px] text-cyan-400 font-black uppercase tracking-widest mb-1 font-mono">Squad Status: Active</div>
          <div className="w-48 h-3 bg-gray-900 rounded-sm overflow-hidden border border-gray-800">
            <div 
              className="h-full bg-gradient-to-r from-cyan-600 to-blue-400 shadow-[0_0_10px_rgba(34,211,238,0.5)] transition-all duration-300" 
              style={{ width: `${health}%` }}
            />
          </div>
          <div className="flex justify-between mt-1">
             <span className="text-[8px] text-gray-500 font-mono">SECTOR_{level.toString().padStart(2, '0')}</span>
             <span className="text-[8px] text-cyan-300 font-mono font-bold uppercase">{ROBOT_STATS[currentUnit].name}</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const SHIELD_DURATION = 20 * 60; // 20 seconds at 60fps

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { 
    name: "SENTINEL", color: '#00f3ff', hpMult: 1.0, 
    robot: { speed: 4, jump: -11, fireRate: 15 },
    alt: { speed: 8, jump: -5, fireRate: 25, type: 'Car' }
  },
  [RobotUnit.STRIKER]: { 
    name: "STRIKER", color: '#fbbf24', hpMult: 0.8,
    robot: { speed: 6, jump: -10, fireRate: 10 },
    alt: { speed: 12, jump: -4, fireRate: 20, type: 'Bike' }
  },
  [RobotUnit.FALCON]: { 
    name: "FALCON", color: '#22d3ee', hpMult: 0.7,
    robot: { speed: 5, jump: -10, fireRate: 12 },
    alt: { speed: 7, jump: -7, fireRate: 15, type: 'Jet' }
  },
  [RobotUnit.TITAN]: { 
    name: "TITAN", color: '#ef4444', hpMult: 2.5,
    robot: { speed: 2.5, jump: -12, fireRate: 30 },
    alt: { speed: 4, jump: 0, fireRate: 20, type: 'Tank' }
  },
  [RobotUnit.SPECTER]: { 
    name: "SPECTER", color: '#a855f7', hpMult: 0.6,
    robot: { speed: 5, jump: -11, fireRate: 20 },
    alt: { speed: 6, jump: -14, fireRate: 40, type: 'Sphere' }
  },
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [currentUnit, setCurrentUnit] = useState<RobotUnit>(RobotUnit.SENTINEL);
  const [isTransformed, setIsTransformed] = useState(false);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [distance, setDistance] = useState(0);
  const [shieldTimeRemaining, setShieldTimeRemaining] = useState(0);

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      maxHealth: 100,
      isTransformed: false,
      shieldTimer: 0,
    },
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    unit: RobotUnit.SENTINEL,
    level: level,
  });

  useEffect(() => { engineRef.current.isPaused = isPaused; }, [isPaused]);
  useEffect(() => { 
    engineRef.current.unit = currentUnit;
    engineRef.current.player.isTransformed = false;
    setIsTransformed(false);
  }, [currentUnit]);
  useEffect(() => { engineRef.current.level = level; }, [level]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff44');
    grad.addColorStop(1, '#00000088');
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.5)';
    ctx.stroke();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, type = 'bot', isTransformed = false) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8;
    const armSwing = Math.cos(time) * 10;

    let scale = 1;
    if (type === 'scout') scale = 0.8;
    if (type === 'heavy' || type === 'titan') scale = 1.4;

    if (isEnemy && isTransformed) {
      scale *= 1.25;
      ctx.translate((Math.random() - 0.5) * 3, (Math.random() - 0.5) * 3);
    }

    ctx.save();
    ctx.scale(scale, scale);

    if (isEnemy && isTransformed) {
      ctx.shadowBlur = 20;
      ctx.shadowColor = '#ff3300';
    }

    drawMechanicalPart(ctx, -12, -18, 24, 28, isTransformed ? '#400' : color, 4);
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? (isTransformed ? '#fff' : '#ff0000') : '#00f3ff';
    ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);

    if (isEnemy && isTransformed) {
      const corePulse = Math.sin(frame * 0.4) * 3;
      ctx.fillStyle = frame % 4 < 2 ? '#ff0000' : '#ffffff';
      ctx.beginPath();
      ctx.arc(0, -5, 5 + corePulse, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.restore();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, color: string, frame: number) => {
    switch(unit) {
      case RobotUnit.SENTINEL:
        drawMechanicalPart(ctx, -24, -10, 48, 18, color, 8);
        drawMechanicalPart(ctx, -16, -20, 30, 12, '#111', 4);
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(-15, 10, 7, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(15, 10, 7, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = frame % 10 < 5 ? '#ff0000' : '#0000ff';
        ctx.fillRect(-4, -22, 10, 3);
        break;
      case RobotUnit.STRIKER:
        drawMechanicalPart(ctx, -18, -8, 36, 12, color, 4);
        drawMechanicalPart(ctx, -5, -18, 18, 12, '#222', 2);
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(-18, 8, 9, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(18, 8, 9, 0, Math.PI * 2); ctx.fill();
        break;
      case RobotUnit.FALCON:
        drawMechanicalPart(ctx, -20, -10, 40, 15, color, 12);
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(-10, -5); ctx.lineTo(-30, -15); ctx.lineTo(-10, 5); ctx.fill();
        ctx.fillStyle = '#ffaa00';
        ctx.fillRect(-28, -5, 8, 5);
        break;
      case RobotUnit.TITAN:
        drawMechanicalPart(ctx, -30, -10, 60, 22, color, 4);
        drawMechanicalPart(ctx, -15, -25, 30, 15, '#222', 4);
        drawMechanicalPart(ctx, 10, -20, 25, 5, '#444', 0);
        ctx.fillStyle = '#111';
        ctx.fillRect(-28, 8, 56, 6);
        break;
      case RobotUnit.SPECTER:
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.arc(0, 0, 18, 0, Math.PI * 2); ctx.fill();
        ctx.strokeStyle = '#fff'; ctx.lineWidth = 1; ctx.stroke();
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(8, -4, 4, 0, Math.PI * 2); ctx.fill();
        break;
    }
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy = false, isInvuln = false, isTransformed = false, type = 'bot') => {
    if (isInvuln && frame % 4 < 2) return;

    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    if (facing === -1) ctx.scale(-1, 1);

    const stats = ROBOT_STATS[unit];
    const color = isEnemy ? '#ff0055' : stats.color;

    if (isTransformed && !isEnemy) {
      drawAltMode(ctx, unit, color, frame);
    } else {
      drawHumanoid(ctx, color, frame, isEnemy, type, isTransformed);
    }

    ctx.restore();
  };

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    const stats = ROBOT_STATS[currentUnit];
    const baseHP = 100 + (upgrades.robotTier * 50);

    e.player.maxHealth = baseHP * stats.hpMult;
    e.player.shieldTimer = 0;
    setShieldTimeRemaining(0);
    setMaxHealth(e.player.maxHealth);
    setHealth(e.player.maxHealth);

    e.player.pos = { x: 100, y: 300 };
    e.player.vel = { x: 0, y: 0 };
    e.player.invulnerable = 0;
    e.player.isTransformed = false;
    setIsTransformed(false);
    e.bullets = [];
    e.cameraX = 0;
    setDistance(0);

    const enemies: Enemy[] = [];
    const floorY = 398;

    const enemyTypes = ['bot', 'scout', 'sniper', 'heavy'];
    for (let i = 0; i < 4; i++) {
      const type = enemyTypes[i % (level < 5 ? 1 : level < 10 ? 2 : 4)];
      let w = 32, h = 48, hp = (50 + level * 15) * 4; // Significantly buffed HP (x4)
      if (type === 'scout') { w = 24; h = 36; hp = (40 + level * 5) * 4; }
      if (type === 'heavy') { w = 48; h = 72; hp = (150 + level * 20) * 4; }

      enemies.push({ 
        id: i, 
        pos: { x: 800 + i * 700, y: floorY - h }, 
        vel: { x: 0, y: 0 }, 
        width: w, 
        height: h, 
        health: hp, 
        maxHealth: hp, 
        isDead: false, 
        type: type, 
        lastShot: 0,
        sequenceStage: 0,
        sequenceTimer: 0,
        isTransformed: false,
        transformTimer: 0
      });
    }

    enemies.push({ 
      id: 4, 
      pos: { x: 4000, y: floorY - 96 }, 
      vel: { x: 0, y: 0 }, 
      width: 80, 
      height: 96, 
      health: (500 + level * 50) * 4, // Boss buffed too
      maxHealth: (500 + level * 50) * 4, 
      isDead: false, 
      type: 'titan', 
      lastShot: 0,
      isTransformed: false
    });
    e.enemies = enemies;
  }, [level, upgrades, currentUnit]);

  useEffect(() => {
    resetLevel();
    const handleKeyDown = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = true;
      if (e.code === 'Digit1') setCurrentUnit(RobotUnit.SENTINEL);
      if (e.code === 'Digit2') setCurrentUnit(RobotUnit.STRIKER);
      if (e.code === 'Digit3') setCurrentUnit(RobotUnit.FALCON);
      if (e.code === 'Digit4') setCurrentUnit(RobotUnit.TITAN);
      if (e.code === 'Digit5') setCurrentUnit(RobotUnit.SPECTER);

      if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') {
        engineRef.current.player.isTransformed = !engineRef.current.player.isTransformed;
        setIsTransformed(engineRef.current.player.isTransformed);
      }

      if (e.code === 'KeyU') {
        engineRef.current.player.shieldTimer = SHIELD_DURATION;
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => { engineRef.current.keys[e.code] = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!engineRef.current.isPaused) update();
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const e = engineRef.current;
      const { player, enemies, bullets, keys } = e;
      const stats = ROBOT_STATS[e.unit];
      const currentStats = player.isTransformed ? stats.alt : stats.robot;
      e.frame++;

      if (player.shieldTimer > 0) {
        player.shieldTimer--;
        if (e.frame % 30 === 0) setShieldTimeRemaining(Math.ceil(player.shieldTimer / 60));
      } else if (shieldTimeRemaining > 0) {
        setShieldTimeRemaining(0);
      }

      const ph = player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48);
      const pw = player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32);

      if (keys['ArrowRight'] || keys['KeyD']) { player.vel.x = currentStats.speed; player.facing = 1; }
      else if (keys['ArrowLeft'] || keys['KeyA']) { player.vel.x = -currentStats.speed; player.facing = -1; }
      else { player.vel.x *= 0.8; }

      if (e.unit === RobotUnit.FALCON && player.isTransformed) {
        if (keys['ArrowUp'] || keys['KeyW']) player.vel.y = -currentStats.speed;
        else if (keys['ArrowDown'] || keys['KeyS']) player.vel.y = currentStats.speed;
        else player.vel.y *= 0.9;
        player.grounded = false;
      } else {
        if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.grounded) {
          player.vel.y = currentStats.jump;
          player.grounded = false;
        }
        player.vel.y += GRAVITY;
      }

      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;

      const floorY = 398;
      if (player.pos.y > floorY - ph) { 
        player.pos.y = floorY - ph; 
        player.vel.y = 0; 
        player.grounded = true; 
      }
      if (player.pos.x < 0) player.pos.x = 0;
      setDistance(player.pos.x);

      const fr = Math.max(5, currentStats.fireRate - upgrades.weaponTier * 2);
      if (keys['Space'] && e.frame - player.lastShot > fr) {
        soundService.playShoot();
        const dmg = player.isTransformed ? 40 : (e.unit === RobotUnit.TITAN ? 60 : (e.unit === RobotUnit.SPECTER ? 80 : 25));
        bullets.push({ 
          pos: { x: player.pos.x + (player.facing === 1 ? pw : 0), y: player.pos.y + ph/2 }, 
          vel: { x: player.facing * (e.unit === RobotUnit.SPECTER ? 25 : 15), y: 0 }, 
          width: player.isTransformed ? 12 : 8, 
          height: 4, 
          owner: 'player', 
          health: 1, maxHealth: 1, damage: dmg, color: stats.color 
        });
        player.lastShot = e.frame;
      }

      for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i]; 
        b.pos.x += b.vel.x; 
        b.pos.y += b.vel.y;

        if (b.owner === 'enemy' && !player.invulnerable && player.shieldTimer <= 0) {
          if (b.pos.x < player.pos.x + pw && b.pos.x + b.width > player.pos.x &&
              b.pos.y < player.pos.y + ph && b.pos.y + b.height > player.pos.y) {
            setHealth(h => Math.max(0, h - (b.damage || 40)));
            player.invulnerable = 40;
            bullets.splice(i, 1);
            soundService.playLose();
            continue;
          }
        } else if (b.owner === 'enemy' && player.shieldTimer > 0) {
          if (b.pos.x < player.pos.x + pw + 20 && b.pos.x + b.width > player.pos.x - 20 &&
              b.pos.y < player.pos.y + ph + 20 && b.pos.y + b.height > player.pos.y - 20) {
            bullets.splice(i, 1);
            continue;
          }
        }

        if (Math.abs(b.pos.x - player.pos.x) > 1200) {
          bullets.splice(i, 1);
        }
      }

      let allDead = true;
      enemies.forEach(en => {
        if (en.isDead) return;
        allDead = false;

        const dist = Math.abs(en.pos.x - player.pos.x);
        const dir = Math.sign(player.pos.x - en.pos.x);
        const hpPercent = en.health / en.maxHealth;

        if (hpPercent < 0.3 && !en.isTransformed) {
          en.isTransformed = true;
          en.width *= 1.3;
          en.height *= 1.3;
        }

        const moveMult = en.isTransformed ? 2.2 : 1.0;

        switch(en.type) {
          case 'bot':
            if (dist > 350) en.vel.x = dir * 2 * moveMult;
            else if (dist < 200) en.vel.x = -dir * 2 * moveMult;
            else en.vel.x *= 0.8;
            break;
          case 'scout':
            en.vel.x = dir * 4 * moveMult;
            break;
          case 'sniper':
            if (dist < 500) en.vel.x = -dir * 3 * moveMult;
            else en.vel.x *= 0.5;
            break;
          case 'heavy':
          case 'titan':
            en.vel.x = dir * 1 * moveMult;
            break;
        }

        if (hpPercent < 0.5 && hpPercent >= 0.3 && en.type !== 'scout') {
          en.vel.x = -dir * 2.5;
        }

        en.pos.x += en.vel.x;

        if (dist < 600) {
          const rawCooldown = en.type === 'heavy' ? 120 : en.type === 'scout' ? 60 : en.type === 'sniper' ? 180 : 100;
          const cooldown = en.isTransformed ? rawCooldown * 0.4 : rawCooldown;

          if (e.frame - en.lastShot > cooldown) {
            switch(en.type) {
              case 'bot':
                bullets.push({ 
                  pos: {x: en.pos.x, y: en.pos.y + 15}, 
                  vel: {x: dir * (en.isTransformed ? 12 : 6), y: 0}, 
                  width: en.isTransformed ? 15 : 10, 
                  height: en.isTransformed ? 6 : 4, 
                  owner: 'enemy', health: 1, maxHealth: 1, 
                  damage: en.isTransformed ? 60 : 35, 
                  color: '#f00' 
                });
                en.lastShot = e.frame;
                break;
              case 'scout':
                if (en.sequenceStage < (en.isTransformed ? 6 : 3)) {
                   if (e.frame % (en.isTransformed ? 4 : 8) === 0) {
                      bullets.push({ 
                        pos: {x: en.pos.x, y: en.pos.y + 10}, 
                        vel: {x: dir * (en.isTransformed ? 14 : 9), y: (Math.random()-0.5)*2}, 
                        width: 6, height: 3, 
                        owner: 'enemy', health: 1, maxHealth: 1, 
                        damage: 25, 
                        color: '#f55' 
                      });
                      en.sequenceStage++;
                   }
                } else {
                   en.sequenceStage = 0;
                   en.lastShot = e.frame;
                }
                break;
              case 'sniper':
                bullets.push({ 
                  pos: {x: en.pos.x, y: en.pos.y + 10}, 
                  vel: {x: dir * 16, y: 0}, 
                  width: 24, height: 2, 
                  owner: 'enemy', health: 1, maxHealth: 1, 
                  damage: en.isTransformed ? 180 : 100, 
                  color: '#fff' 
                });
                en.lastShot = e.frame;
                break;
              case 'heavy':
              case 'titan':
                const numBullets = en.isTransformed ? 7 : 3;
                for(let j=-(numBullets>>1); j<=(numBullets>>1); j++) {
                  bullets.push({ 
                    pos: {x: en.pos.x, y: en.pos.y + 30}, 
                    vel: {x: dir * 6, y: j * (en.isTransformed ? 2 : 1.2)}, 
                    width: 14, height: 10, 
                    owner: 'enemy', health: 1, maxHealth: 1, 
                    damage: 100, 
                    color: '#f00' 
                  });
                }
                en.lastShot = e.frame;
                break;
            }
          }
        }

        bullets.forEach((b, idx) => {
          if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) {
            en.health -= b.damage || 20; 
            bullets.splice(idx, 1);
            if (en.health <= 0) en.isDead = true;
          }
        });

        if (!player.invulnerable && player.shieldTimer <= 0 && player.pos.x < en.pos.x + en.width && player.pos.x + pw > en.pos.x && player.pos.y < en.pos.y + en.height && player.pos.y + ph > en.pos.y) {
           setHealth(h => Math.max(0, h - (en.type === 'heavy' || en.type === 'titan' ? 150 : 80))); 
           player.invulnerable = 60; 
           soundService.playLose();
        }
      });

      if (health <= 0) onDie();
      if (allDead) onWin();
      if (player.invulnerable > 0) player.invulnerable--;
      e.cameraX = player.pos.x - CANVAS_WIDTH/3;
      if (e.cameraX < 0) e.cameraX = 0;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const e = engineRef.current;
      ctx.fillStyle = '#050510'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

      ctx.fillStyle = '#1c1c1c'; ctx.fillRect(0, 398, CANVAS_WIDTH, 52);
      ctx.strokeStyle = '#222';
      for(let i=0; i<CANVAS_WIDTH; i+=40) {
        ctx.beginPath(); ctx.moveTo(i - (e.cameraX % 40), 398); ctx.lineTo(i - (e.cameraX % 40), CANVAS_HEIGHT); ctx.stroke();
      }

      e.enemies.forEach(en => { 
        if(!en.isDead) drawUnit(ctx, en.pos.x - e.cameraX, en.pos.y, en.width, en.height, RobotUnit.SENTINEL, Math.sign(e.player.pos.x - en.pos.x), e.frame, true, false, en.isTransformed, en.type); 
      });

      const player = e.player;
      const ph = player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48);
      const pw = player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32);

      drawUnit(ctx, player.pos.x - e.cameraX, player.pos.y, pw, ph, e.unit, player.facing, e.frame, false, player.invulnerable > 0, player.isTransformed);

      if (player.shieldTimer > 0) {
        const shieldPulse = Math.sin(e.frame * 0.1) * 5;
        ctx.save();
        ctx.translate(player.pos.x - e.cameraX + pw / 2, player.pos.y + ph / 2);
        ctx.beginPath();
        ctx.arc(0, 0, Math.max(pw, ph) * 0.8 + shieldPulse, 0, Math.PI * 2);
        ctx.strokeStyle = '#00f3ff';
        ctx.lineWidth = 3;
        ctx.shadowBlur = 15;
        ctx.shadowColor = '#00f3ff';
        ctx.stroke();
        ctx.globalAlpha = 0.2;
        ctx.fillStyle = '#00f3ff';
        ctx.fill();
        ctx.restore();
      }

      e.bullets.forEach(b => { 
        ctx.fillStyle = b.color || (b.owner === 'player' ? '#00f3ff' : '#ff0055'); 
        ctx.fillRect(b.pos.x - e.cameraX, b.pos.y, b.width, b.height); 
      });
    };

    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [resetLevel, onWin, onDie, level, upgrades, health, currentUnit, shieldTimeRemaining]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden">
      <div className="absolute top-4 left-4 z-10 space-y-4 pointer-events-none">
        <div className="bg-black/80 border border-cyan-500/50 p-3 rounded backdrop-blur-md shadow-lg">
          <div className="text-[10px] text-cyan-400 font-bold uppercase mb-1 flex justify-between font-orbitron">
            <span>{ROBOT_STATS[currentUnit].name} INTEGRITY</span>
            <span>{Math.round(health)}/{Math.round(maxHealth)}</span>
          </div>
          <div className="w-48 h-2.5 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
            <div 
              className="h-full shadow-[0_0_15px_#00f3ff] transition-all duration-300" 
              style={{ 
                width: `${(health / maxHealth) * 100}%`,
                backgroundColor: health < maxHealth * 0.3 ? '#ef4444' : '#00f3ff'
              }} 
            />
          </div>
          {shieldTimeRemaining > 0 && (
            <div className="mt-2 flex items-center gap-2">
              <div className="text-[10px] text-blue-400 font-black animate-pulse font-orbitron">SHIELD ACTIVE: {shieldTimeRemaining}s</div>
              <div className="flex-1 h-1 bg-blue-900 rounded-full overflow-hidden">
                <div className="h-full bg-cyan-400" style={{ width: `${(shieldTimeRemaining / 20) * 100}%` }}></div>
              </div>
            </div>
          )}
          <div className="mt-2 text-[8px] text-white/50 font-mono flex justify-between">
            <span>MODE: {isTransformed ? `ALT (${ROBOT_STATS[currentUnit].alt.type})` : 'HUMANOID'}</span>
            <span className="animate-pulse text-red-500 font-bold uppercase">[Lethality: Critical]</span>
          </div>
        </div>

        <div className="flex flex-col gap-2 pointer-events-auto">
           <div className="text-[10px] text-white/50 font-bold uppercase tracking-tighter ml-1 font-orbitron">SQUAD_DEPLOYMENT [1-5]</div>
           <div className="flex gap-2">
           {(Object.keys(ROBOT_STATS) as RobotUnit[]).map((u, i) => {
             const stats = ROBOT_STATS[u];
             const isActive = currentUnit === u;
             return (
               <button 
                 key={u} 
                 onClick={() => setCurrentUnit(u)}
                 className={`group relative w-12 h-12 flex flex-col items-center justify-center rounded-sm border-2 transition-all duration-200 ${
                   isActive 
                     ? 'bg-white/10' 
                     : 'border-gray-800 bg-black/60 hover:border-gray-600'
                 }`}
                 style={{
                   borderColor: isActive ? stats.color : '',
                   boxShadow: isActive ? `0 0 20px ${stats.color}50, inset 0 0 8px ${stats.color}30` : 'none'
                 }}
               >
                 {isActive && (
                   <>
                     <div className="absolute -top-1.5 -left-1.5 w-3 h-3 border-t-2 border-l-2" style={{ borderColor: stats.color }} />
                     <div className="absolute -bottom-1.5 -right-1.5 w-3 h-3 border-b-2 border-r-2" style={{ borderColor: stats.color }} />
                   </>
                 )}
                 <span className={`text-xl font-black font-orbitron transition-colors ${isActive ? 'text-white' : 'text-gray-600'}`}>
                   {i + 1}
                 </span>
                 <div className={`absolute -bottom-8 px-2 py-0.5 rounded bg-black/90 border border-gray-700 text-[8px] font-bold uppercase tracking-widest text-white transition-opacity whitespace-nowrap ${isActive ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}>
                    {stats.name}
                 </div>
                 {isActive && (
                    <div className="absolute -top-4 left-1/2 -translate-x-1/2 w-1.5 h-1.5 bg-white rounded-full animate-ping" />
                 )}
               </button>
             );
           })}
           </div>
        </div>
      </div>

      <div className="absolute top-4 right-4 z-10 text-right pointer-events-none font-orbitron">
        <div className="text-[10px] text-cyan-500 font-bold uppercase tracking-widest">Active Sector</div>
        <div className="text-3xl font-black text-white italic drop-shadow-md">{level.toString().padStart(2, '0')}</div>
      </div>

      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full aspect-video shadow-2xl rounded-lg border-2 border-cyan-900/50" />

      {health < maxHealth * 0.3 && (
        <div className="absolute inset-0 pointer-events-none border-[16px] border-red-600/20 animate-pulse shadow-[inset_0_0_100px_rgba(239,68,68,0.3)]"></div>
      )}

      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 pointer-events-none text-white/30 text-[9px] font-mono tracking-widest uppercase flex gap-8">
        <span>WASD: Move</span>
        <span>Space: Fire</span>
        <span>Shift: Transform</span>
        <span>U: Shield</span>
        <span>P: Pause</span>
        <span>1-5: Squad</span>
      </div>
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const SHIELD_DURATION = 20 * 60; // 20 seconds at 60fps
const SQUAD_UNION_DURATION = 60 * 60; // 60 seconds at 60fps

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { 
    name: "SENTINEL", color: '#00f3ff', hpMult: 1.0, 
    robot: { speed: 4, jump: -11, fireRate: 15 },
    alt: { speed: 8, jump: -5, fireRate: 25, type: 'Car' }
  },
  [RobotUnit.STRIKER]: { 
    name: "STRIKER", color: '#fbbf24', hpMult: 0.8,
    robot: { speed: 6, jump: -10, fireRate: 10 },
    alt: { speed: 12, jump: -4, fireRate: 20, type: 'Bike' }
  },
  [RobotUnit.FALCON]: { 
    name: "FALCON", color: '#22d3ee', hpMult: 0.7,
    robot: { speed: 5, jump: -10, fireRate: 12 },
    alt: { speed: 7, jump: -7, fireRate: 15, type: 'Jet' }
  },
  [RobotUnit.TITAN]: { 
    name: "TITAN", color: '#ef4444', hpMult: 2.5,
    robot: { speed: 2.5, jump: -12, fireRate: 30 },
    alt: { speed: 4, jump: 0, fireRate: 20, type: 'Tank' }
  },
  [RobotUnit.SPECTER]: { 
    name: "SPECTER", color: '#a855f7', hpMult: 0.6,
    robot: { speed: 5, jump: -11, fireRate: 20 },
    alt: { speed: 6, jump: -14, fireRate: 40, type: 'Sphere' }
  },
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [currentUnit, setCurrentUnit] = useState<RobotUnit>(RobotUnit.SENTINEL);
  const [isTransformed, setIsTransformed] = useState(false);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [distance, setDistance] = useState(0);
  const [shieldTimeRemaining, setShieldTimeRemaining] = useState(0);
  const [unionTimeRemaining, setUnionTimeRemaining] = useState(0);
  const [showCheckpoint, setShowCheckpoint] = useState(false);

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      maxHealth: 100,
      isTransformed: false,
      shieldTimer: 0,
      unionTimer: 0,
      history: [] as {x: number, y: number}[],
      checkpoint: { x: 100, y: 300, reached: false }
    },
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    unit: RobotUnit.SENTINEL,
    level: level,
  });

  useEffect(() => { engineRef.current.isPaused = isPaused; }, [isPaused]);
  useEffect(() => { 
    engineRef.current.unit = currentUnit;
    engineRef.current.player.isTransformed = false;
    setIsTransformed(false);
  }, [currentUnit]);
  useEffect(() => { engineRef.current.level = level; }, [level]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff44');
    grad.addColorStop(1, '#00000088');
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.5)';
    ctx.stroke();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, type = 'bot', isTransformed = false, alpha = 1) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8;
    const armSwing = Math.cos(time) * 10;

    let scale = 1;
    if (type === 'scout') scale = 0.8;
    if (type === 'heavy' || type === 'titan') scale = 1.4;

    if (isEnemy && isTransformed) {
      scale *= 1.25;
      ctx.translate((Math.random() - 0.5) * 3, (Math.random() - 0.5) * 3);
    }

    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(scale, scale);

    if (isEnemy && isTransformed) {
      ctx.shadowBlur = 20;
      ctx.shadowColor = '#ff3300';
    }

    drawMechanicalPart(ctx, -12, -18, 24, 28, isTransformed ? '#400' : color, 4);
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? (isTransformed ? '#fff' : '#ff0000') : '#00f3ff';
    ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);

    if (isEnemy && isTransformed) {
      const corePulse = Math.sin(frame * 0.4) * 3;
      ctx.fillStyle = frame % 4 < 2 ? '#ff0000' : '#ffffff';
      ctx.beginPath();
      ctx.arc(0, -5, 5 + corePulse, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.restore();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, color: string, frame: number, alpha = 1) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    switch(unit) {
      case RobotUnit.SENTINEL:
        drawMechanicalPart(ctx, -24, -10, 48, 18, color, 8);
        drawMechanicalPart(ctx, -16, -20, 30, 12, '#111', 4);
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(-15, 10, 7, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(15, 10, 7, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = frame % 10 < 5 ? '#ff0000' : '#0000ff';
        ctx.fillRect(-4, -22, 10, 3);
        break;
      case RobotUnit.STRIKER:
        drawMechanicalPart(ctx, -18, -8, 36, 12, color, 4);
        drawMechanicalPart(ctx, -5, -18, 18, 12, '#222', 2);
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(-18, 8, 9, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(18, 8, 9, 0, Math.PI * 2); ctx.fill();
        break;
      case RobotUnit.FALCON:
        drawMechanicalPart(ctx, -20, -10, 40, 15, color, 12);
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(-10, -5); ctx.lineTo(-30, -15); ctx.lineTo(-10, 5); ctx.fill();
        ctx.fillStyle = '#ffaa00';
        ctx.fillRect(-28, -5, 8, 5);
        break;
      case RobotUnit.TITAN:
        drawMechanicalPart(ctx, -30, -10, 60, 22, color, 4);
        drawMechanicalPart(ctx, -15, -25, 30, 15, '#222', 4);
        drawMechanicalPart(ctx, 10, -20, 25, 5, '#444', 0);
        ctx.fillStyle = '#111';
        ctx.fillRect(-28, 8, 56, 6);
        break;
      case RobotUnit.SPECTER:
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.arc(0, 0, 18, 0, Math.PI * 2); ctx.fill();
        ctx.strokeStyle = '#fff'; ctx.lineWidth = 1; ctx.stroke();
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(8, -4, 4, 0, Math.PI * 2); ctx.fill();
        break;
    }
    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy = false, isInvuln = false, isTransformed = false, type = 'bot', alpha = 1) => {
    if (isInvuln && frame % 4 < 2) return;

    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    if (facing === -1) ctx.scale(-1, 1);

    const stats = ROBOT_STATS[unit];
    const color = isEnemy ? '#ff0055' : stats.color;

    if (isTransformed && !isEnemy) {
      drawAltMode(ctx, unit, color, frame, alpha);
    } else {
      drawHumanoid(ctx, color, frame, isEnemy, type, isTransformed, alpha);
    }

    ctx.restore();
  };

  const resetLevel = useCallback((fromCheckpoint = false) => {
    const e = engineRef.current;
    const stats = ROBOT_STATS[currentUnit];
    const baseHP = 100 + (upgrades.robotTier * 50);

    e.player.maxHealth = baseHP * stats.hpMult;
    e.player.shieldTimer = 0;
    e.player.unionTimer = 0;
    setShieldTimeRemaining(0);
    setUnionTimeRemaining(0);
    setMaxHealth(e.player.maxHealth);
    setHealth(e.player.maxHealth);

    if (fromCheckpoint && e.player.checkpoint.reached) {
      e.player.pos = { x: e.player.checkpoint.x, y: e.player.checkpoint.y };
    } else {
      e.player.pos = { x: 100, y: 300 };
      e.player.checkpoint.reached = false;
    }

    e.player.vel = { x: 0, y: 0 };
    e.player.invulnerable = 0;
    e.player.isTransformed = false;
    e.player.history = [];
    setIsTransformed(false);
    e.bullets = [];
    e.cameraX = e.player.pos.x - CANVAS_WIDTH/3;
    setDistance(e.player.pos.x);

    // If starting from checkpoint, don't recreate ALREADY dead enemies
    if (!fromCheckpoint) {
      const enemies: Enemy[] = [];
      const floorY = 398;
      const enemyTypes = ['bot', 'scout', 'sniper', 'heavy'];
      for (let i = 0; i < 4; i++) {
        const type = enemyTypes[i % (level < 5 ? 1 : level < 10 ? 2 : 4)];
        let w = 32, h = 48, hp = (50 + level * 15) * 4;
        if (type === 'scout') { w = 24; h = 36; hp = (40 + level * 5) * 4; }
        if (type === 'heavy') { w = 48; h = 72; hp = (150 + level * 20) * 4; }

        enemies.push({ 
          id: i, 
          pos: { x: 800 + i * 700, y: floorY - h }, 
          vel: { x: 0, y: 0 }, 
          width: w, 
          height: h, 
          health: hp, 
          maxHealth: hp, 
          isDead: false, 
          type: type, 
          lastShot: 0,
          sequenceStage: 0,
          sequenceTimer: 0,
          isTransformed: false,
          transformTimer: 0
        });
      }

      enemies.push({ 
        id: 4, 
        pos: { x: 4000, y: floorY - 96 }, 
        vel: { x: 0, y: 0 }, 
        width: 80, 
        height: 96, 
        health: (500 + level * 50) * 4,
        maxHealth: (500 + level * 50) * 4, 
        isDead: false, 
        type: 'titan', 
        lastShot: 0,
        isTransformed: false
      });
      e.enemies = enemies;
    }
  }, [level, upgrades, currentUnit]);

  useEffect(() => {
    resetLevel();
    const handleKeyDown = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = true;
      if (e.code === 'Digit1') setCurrentUnit(RobotUnit.SENTINEL);
      if (e.code === 'Digit2') setCurrentUnit(RobotUnit.STRIKER);
      if (e.code === 'Digit3') setCurrentUnit(RobotUnit.FALCON);
      if (e.code === 'Digit4') setCurrentUnit(RobotUnit.TITAN);
      if (e.code === 'Digit5') setCurrentUnit(RobotUnit.SPECTER);

      if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') {
        engineRef.current.player.isTransformed = !engineRef.current.player.isTransformed;
        setIsTransformed(engineRef.current.player.isTransformed);
      }

      if (e.code === 'KeyU') {
        engineRef.current.player.shieldTimer = SHIELD_DURATION;
      }

      if (e.code === 'KeyT') {
        engineRef.current.player.unionTimer = SQUAD_UNION_DURATION;
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => { engineRef.current.keys[e.code] = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!engineRef.current.isPaused) update();
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const e = engineRef.current;
      const { player, enemies, bullets, keys } = e;
      const stats = ROBOT_STATS[e.unit];
      const currentStats = player.isTransformed ? stats.alt : stats.robot;
      e.frame++;

      // Checkpoint Logic (50% of the way to the boss)
      if (!player.checkpoint.reached && player.pos.x > 2000) {
        player.checkpoint.reached = true;
        player.checkpoint.x = player.pos.x;
        player.checkpoint.y = player.pos.y;
        setShowCheckpoint(true);
        setTimeout(() => setShowCheckpoint(false), 3000);
      }

      // History for companions (snake trail)
      player.history.unshift({ x: player.pos.x, y: player.pos.y });
      if (player.history.length > 200) player.history.pop();

      if (player.shieldTimer > 0) {
        player.shieldTimer--;
        if (e.frame % 30 === 0) setShieldTimeRemaining(Math.ceil(player.shieldTimer / 60));
      } else if (shieldTimeRemaining > 0) {
        setShieldTimeRemaining(0);
      }

      if (player.unionTimer > 0) {
        player.unionTimer--;
        if (e.frame % 30 === 0) setUnionTimeRemaining(Math.ceil(player.unionTimer / 60));
      } else if (unionTimeRemaining > 0) {
        setUnionTimeRemaining(0);
      }

      const ph = player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48);
      const pw = player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32);

      if (keys['ArrowRight'] || keys['KeyD']) { player.vel.x = currentStats.speed; player.facing = 1; }
      else if (keys['ArrowLeft'] || keys['KeyA']) { player.vel.x = -currentStats.speed; player.facing = -1; }
      else { player.vel.x *= 0.8; }

      if (e.unit === RobotUnit.FALCON && player.isTransformed) {
        if (keys['ArrowUp'] || keys['KeyW']) player.vel.y = -currentStats.speed;
        else if (keys['ArrowDown'] || keys['KeyS']) player.vel.y = currentStats.speed;
        else player.vel.y *= 0.9;
        player.grounded = false;
      } else {
        if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.grounded) {
          player.vel.y = currentStats.jump;
          player.grounded = false;
        }
        player.vel.y += GRAVITY;
      }

      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;

      const floorY = 398;
      if (player.pos.y > floorY - ph) { 
        player.pos.y = floorY - ph; 
        player.vel.y = 0; 
        player.grounded = true; 
      }
      if (player.pos.x < 0) player.pos.x = 0;
      setDistance(player.pos.x);

      const fr = Math.max(5, currentStats.fireRate - upgrades.weaponTier * 2);
      if (keys['Space'] && e.frame - player.lastShot > fr) {
        soundService.playShoot();
        const dmg = player.isTransformed ? 40 : (e.unit === RobotUnit.TITAN ? 60 : (e.unit === RobotUnit.SPECTER ? 80 : 25));
        bullets.push({ 
          pos: { x: player.pos.x + (player.facing === 1 ? pw : 0), y: player.pos.y + ph/2 }, 
          vel: { x: player.facing * (e.unit === RobotUnit.SPECTER ? 25 : 15), y: 0 }, 
          width: player.isTransformed ? 12 : 8, 
          height: 4, 
          owner: 'player', 
          health: 1, maxHealth: 1, damage: dmg, color: stats.color 
        });

        // Squad Union Fire
        if (player.unionTimer > 0) {
          (Object.keys(RobotUnit) as RobotUnit[]).forEach((u, i) => {
            if (u === e.unit) return;
            const cStats = ROBOT_STATS[u];
            const histIdx = (i + 1) * 20;
            const histPos = player.history[histIdx] || player.pos;
            bullets.push({
              pos: { x: histPos.x + (player.facing === 1 ? 20 : 0), y: histPos.y + 20 },
              vel: { x: player.facing * 12, y: 0 },
              width: 8, height: 4, owner: 'player', health: 1, maxHealth: 1, damage: 15, color: cStats.color
            });
          });
        }
        player.lastShot = e.frame;
      }

      for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i]; 
        b.pos.x += b.vel.x; 
        b.pos.y += b.vel.y;

        if (b.owner === 'enemy' && !player.invulnerable && player.shieldTimer <= 0) {
          if (b.pos.x < player.pos.x + pw && b.pos.x + b.width > player.pos.x &&
              b.pos.y < player.pos.y + ph && b.pos.y + b.height > player.pos.y) {
            setHealth(h => Math.max(0, h - (b.damage || 40)));
            player.invulnerable = 40;
            bullets.splice(i, 1);
            soundService.playLose();
            continue;
          }
        } else if (b.owner === 'enemy' && player.shieldTimer > 0) {
          if (b.pos.x < player.pos.x + pw + 20 && b.pos.x + b.width > player.pos.x - 20 &&
              b.pos.y < player.pos.y + ph + 20 && b.pos.y + b.height > player.pos.y - 20) {
            bullets.splice(i, 1);
            continue;
          }
        }

        if (Math.abs(b.pos.x - player.pos.x) > 1200) {
          bullets.splice(i, 1);
        }
      }

      let allDead = true;
      enemies.forEach(en => {
        if (en.isDead) return;
        allDead = false;

        const dist = Math.abs(en.pos.x - player.pos.x);
        const dir = Math.sign(player.pos.x - en.pos.x);
        const hpPercent = en.health / en.maxHealth;

        if (hpPercent < 0.3 && !en.isTransformed) {
          en.isTransformed = true;
          en.width *= 1.3;
          en.height *= 1.3;
        }

        const moveMult = en.isTransformed ? 2.2 : 1.0;

        switch(en.type) {
          case 'bot':
            if (dist > 350) en.vel.x = dir * 2 * moveMult;
            else if (dist < 200) en.vel.x = -dir * 2 * moveMult;
            else en.vel.x *= 0.8;
            break;
          case 'scout':
            en.vel.x = dir * 4 * moveMult;
            break;
          case 'sniper':
            if (dist < 500) en.vel.x = -dir * 3 * moveMult;
            else en.vel.x *= 0.5;
            break;
          case 'heavy':
          case 'titan':
            en.vel.x = dir * 1 * moveMult;
            break;
        }

        if (hpPercent < 0.5 && hpPercent >= 0.3 && en.type !== 'scout') {
          en.vel.x = -dir * 2.5;
        }

        en.pos.x += en.vel.x;

        if (dist < 600) {
          const rawCooldown = en.type === 'heavy' ? 120 : en.type === 'scout' ? 60 : en.type === 'sniper' ? 180 : 100;
          const cooldown = en.isTransformed ? rawCooldown * 0.4 : rawCooldown;

          if (e.frame - en.lastShot > cooldown) {
            switch(en.type) {
              case 'bot':
                bullets.push({ 
                  pos: {x: en.pos.x, y: en.pos.y + 15}, 
                  vel: {x: dir * (en.isTransformed ? 12 : 6), y: 0}, 
                  width: en.isTransformed ? 15 : 10, 
                  height: en.isTransformed ? 6 : 4, 
                  owner: 'enemy', health: 1, maxHealth: 1, 
                  damage: en.isTransformed ? 60 : 35, 
                  color: '#f00' 
                });
                en.lastShot = e.frame;
                break;
              case 'scout':
                if (en.sequenceStage < (en.isTransformed ? 6 : 3)) {
                   if (e.frame % (en.isTransformed ? 4 : 8) === 0) {
                      bullets.push({ 
                        pos: {x: en.pos.x, y: en.pos.y + 10}, 
                        vel: {x: dir * (en.isTransformed ? 14 : 9), y: (Math.random()-0.5)*2}, 
                        width: 6, height: 3, 
                        owner: 'enemy', health: 1, maxHealth: 1, 
                        damage: 25, 
                        color: '#f55' 
                      });
                      en.sequenceStage++;
                   }
                } else {
                   en.sequenceStage = 0;
                   en.lastShot = e.frame;
                }
                break;
              case 'sniper':
                bullets.push({ 
                  pos: {x: en.pos.x, y: en.pos.y + 10}, 
                  vel: {x: dir * 16, y: 0}, 
                  width: 24, height: 2, 
                  owner: 'enemy', health: 1, maxHealth: 1, 
                  damage: en.isTransformed ? 180 : 100, 
                  color: '#fff' 
                });
                en.lastShot = e.frame;
                break;
              case 'heavy':
              case 'titan':
                const numBullets = en.isTransformed ? 7 : 3;
                for(let j=-(numBullets>>1); j<=(numBullets>>1); j++) {
                  bullets.push({ 
                    pos: {x: en.pos.x, y: en.pos.y + 30}, 
                    vel: {x: dir * 6, y: j * (en.isTransformed ? 2 : 1.2)}, 
                    width: 14, height: 10, 
                    owner: 'enemy', health: 1, maxHealth: 1, 
                    damage: 100, 
                    color: '#f00' 
                  });
                }
                en.lastShot = e.frame;
                break;
            }
          }
        }

        bullets.forEach((b, idx) => {
          if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) {
            en.health -= b.damage || 20; 
            bullets.splice(idx, 1);
            if (en.health <= 0) en.isDead = true;
          }
        });

        if (!player.invulnerable && player.shieldTimer <= 0 && player.pos.x < en.pos.x + en.width && player.pos.x + pw > en.pos.x && player.pos.y < en.pos.y + en.height && player.pos.y + ph > en.pos.y) {
           setHealth(h => Math.max(0, h - (en.type === 'heavy' || en.type === 'titan' ? 150 : 80))); 
           player.invulnerable = 60; 
           soundService.playLose();
        }
      });

      if (health <= 0) {
        if (player.checkpoint.reached) {
          // Instead of Game Over, reset from checkpoint
          resetLevel(true);
        } else {
          onDie();
        }
      }
      if (allDead) onWin();
      if (player.invulnerable > 0) player.invulnerable--;
      e.cameraX = player.pos.x - CANVAS_WIDTH/3;
      if (e.cameraX < 0) e.cameraX = 0;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const e = engineRef.current;
      ctx.fillStyle = '#050510'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

      ctx.fillStyle = '#1c1c1c'; ctx.fillRect(0, 398, CANVAS_WIDTH, 52);
      ctx.strokeStyle = '#222';
      for(let i=0; i<CANVAS_WIDTH; i+=40) {
        ctx.beginPath(); ctx.moveTo(i - (e.cameraX % 40), 398); ctx.lineTo(i - (e.cameraX % 40), CANVAS_HEIGHT); ctx.stroke();
      }

      e.enemies.forEach(en => { 
        if(!en.isDead) drawUnit(ctx, en.pos.x - e.cameraX, en.pos.y, en.width, en.height, RobotUnit.SENTINEL, Math.sign(e.player.pos.x - en.pos.x), e.frame, true, false, en.isTransformed, en.type); 
      });

      const player = e.player;
      const ph = player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48);
      const pw = player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32);

      // Draw Squad Union Companions
      if (player.unionTimer > 0) {
        (Object.keys(RobotUnit) as RobotUnit[]).forEach((u, i) => {
          if (u === e.unit) return;
          const histIdx = (i + 1) * 20;
          const histPos = player.history[histIdx] || player.pos;
          drawUnit(ctx, histPos.x - e.cameraX, histPos.y, 24, 36, u, player.facing, e.frame, false, false, false, 'bot', 0.5);
        });
      }

      drawUnit(ctx, player.pos.x - e.cameraX, player.pos.y, pw, ph, e.unit, player.facing, e.frame, false, player.invulnerable > 0, player.isTransformed);

      if (player.shieldTimer > 0) {
        const shieldPulse = Math.sin(e.frame * 0.1) * 5;
        ctx.save();
        ctx.translate(player.pos.x - e.cameraX + pw / 2, player.pos.y + ph / 2);
        ctx.beginPath();
        ctx.arc(0, 0, Math.max(pw, ph) * 0.8 + shieldPulse, 0, Math.PI * 2);
        ctx.strokeStyle = '#00f3ff';
        ctx.lineWidth = 3;
        ctx.shadowBlur = 15;
        ctx.shadowColor = '#00f3ff';
        ctx.stroke();
        ctx.globalAlpha = 0.2;
        ctx.fillStyle = '#00f3ff';
        ctx.fill();
        ctx.restore();
      }

      e.bullets.forEach(b => { 
        ctx.fillStyle = b.color || (b.owner === 'player' ? '#00f3ff' : '#ff0055'); 
        ctx.fillRect(b.pos.x - e.cameraX, b.pos.y, b.width, b.height); 
      });
    };

    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [resetLevel, onWin, onDie, level, upgrades, health, currentUnit, shieldTimeRemaining, unionTimeRemaining]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden">
      <div className="absolute top-4 left-4 z-10 space-y-4 pointer-events-none">
        <div className="bg-black/80 border border-cyan-500/50 p-3 rounded backdrop-blur-md shadow-lg">
          <div className="text-[10px] text-cyan-400 font-bold uppercase mb-1 flex justify-between font-orbitron">
            <span>{ROBOT_STATS[currentUnit].name} INTEGRITY</span>
            <span>{Math.round(health)}/{Math.round(maxHealth)}</span>
          </div>
          <div className="w-48 h-2.5 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
            <div 
              className="h-full shadow-[0_0_15px_#00f3ff] transition-all duration-300" 
              style={{ 
                width: `${(health / maxHealth) * 100}%`,
                backgroundColor: health < maxHealth * 0.3 ? '#ef4444' : '#00f3ff'
              }} 
            />
          </div>

          <div className="flex flex-col gap-1 mt-2">
            {shieldTimeRemaining > 0 && (
              <div className="flex items-center gap-2">
                <div className="text-[10px] text-blue-400 font-black animate-pulse font-orbitron">SHIELD: {shieldTimeRemaining}s</div>
                <div className="flex-1 h-1 bg-blue-900 rounded-full overflow-hidden">
                  <div className="h-full bg-cyan-400" style={{ width: `${(shieldTimeRemaining / 20) * 100}%` }}></div>
                </div>
              </div>
            )}
            {unionTimeRemaining > 0 && (
              <div className="flex items-center gap-2">
                <div className="text-[10px] text-purple-400 font-black animate-pulse font-orbitron">SQUAD UNION: {unionTimeRemaining}s</div>
                <div className="flex-1 h-1 bg-purple-900 rounded-full overflow-hidden">
                  <div className="h-full bg-purple-400" style={{ width: `${(unionTimeRemaining / 60) * 100}%` }}></div>
                </div>
              </div>
            )}
          </div>

          <div className="mt-2 text-[8px] text-white/50 font-mono flex justify-between">
            <span>MODE: {isTransformed ? `ALT (${ROBOT_STATS[currentUnit].alt.type})` : 'HUMANOID'}</span>
            <span className="animate-pulse text-red-500 font-bold uppercase">[Critical Operations]</span>
          </div>
        </div>

        <div className="flex flex-col gap-2 pointer-events-auto">
           <div className="text-[10px] text-white/50 font-bold uppercase tracking-tighter ml-1 font-orbitron">SQUAD_DEPLOYMENT [1-5]</div>
           <div className="flex gap-2">
           {(Object.keys(ROBOT_STATS) as RobotUnit[]).map((u, i) => {
             const stats = ROBOT_STATS[u];
             const isActive = currentUnit === u;
             return (
               <button 
                 key={u} 
                 onClick={() => setCurrentUnit(u)}
                 className={`group relative w-12 h-12 flex flex-col items-center justify-center rounded-sm border-2 transition-all duration-200 ${
                   isActive 
                     ? 'bg-white/10' 
                     : 'border-gray-800 bg-black/60 hover:border-gray-600'
                 }`}
                 style={{
                   borderColor: isActive ? stats.color : '',
                   boxShadow: isActive ? `0 0 20px ${stats.color}50, inset 0 0 8px ${stats.color}30` : 'none'
                 }}
               >
                 {isActive && (
                   <>
                     <div className="absolute -top-1.5 -left-1.5 w-3 h-3 border-t-2 border-l-2" style={{ borderColor: stats.color }} />
                     <div className="absolute -bottom-1.5 -right-1.5 w-3 h-3 border-b-2 border-r-2" style={{ borderColor: stats.color }} />
                   </>
                 )}
                 <span className={`text-xl font-black font-orbitron transition-colors ${isActive ? 'text-white' : 'text-gray-600'}`}>
                   {i + 1}
                 </span>
                 <div className={`absolute -bottom-8 px-2 py-0.5 rounded bg-black/90 border border-gray-700 text-[8px] font-bold uppercase tracking-widest text-white transition-opacity whitespace-nowrap ${isActive ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}>
                    {stats.name}
                 </div>
               </button>
             );
           })}
           </div>
        </div>
      </div>

      {showCheckpoint && (
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 pointer-events-none animate-in fade-in zoom-in duration-500">
          <div className="bg-cyan-600/80 border-2 border-white px-8 py-4 backdrop-blur-md shadow-[0_0_50px_#00f3ff]">
            <h3 className="text-3xl font-black text-white italic tracking-tighter uppercase font-orbitron">CHECKPOINT REACHED</h3>
            <p className="text-white font-mono text-center tracking-widest text-xs mt-2">DEPLOYMENT ANCHOR SET</p>
          </div>
        </div>
      )}

      <div className="absolute top-4 right-4 z-10 text-right pointer-events-none font-orbitron">
        <div className="text-[10px] text-cyan-500 font-bold uppercase tracking-widest">Active Sector</div>
        <div className="text-3xl font-black text-white italic drop-shadow-md">{level.toString().padStart(2, '0')}</div>
      </div>

      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full aspect-video shadow-2xl rounded-lg border-2 border-cyan-900/50" />

      {health < maxHealth * 0.3 && (
        <div className="absolute inset-0 pointer-events-none border-[16px] border-red-600/20 animate-pulse shadow-[inset_0_0_100px_rgba(239,68,68,0.3)]"></div>
      )}

      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 pointer-events-none text-white/30 text-[9px] font-mono tracking-widest uppercase flex gap-6">
        <span>WASD: Move</span>
        <span>Space: Fire</span>
        <span>Shift: Alt Mode</span>
        <span>U: Shield</span>
        <span>T: Squad Union</span>
        <span>P: Pause</span>
        <span>1-5: Squad</span>
      </div>
    </div>
  );
};

export default GameView;

export enum GameState {
  MENU = 'MENU',
  BRIEFING = 'BRIEFING',
  PLAYING = 'PLAYING',
  PAUSED = 'PAUSED',
  GAMEOVER = 'GAMEOVER',
  VICTORY = 'VICTORY',
  LEVEL_COMPLETE = 'LEVEL_COMPLETE',
  SHOP = 'SHOP',
  ROBOT_SHOP = 'ROBOT_SHOP',
  LEVEL_SELECT = 'LEVEL_SELECT'
}

export enum RobotUnit {
  SENTINEL = 'SENTINEL',
  STRIKER = 'STRIKER',
  FALCON = 'FALCON',
  TITAN = 'TITAN',
  SPECTER = 'SPECTER'
}

export interface LevelInfo {
  level: number;
  title: string;
  description: string;
  threatLevel: string;
  enemyType: string;
}

export interface Upgrades {
  robotTier: number;
  weaponTier: number;
  unlockedUnits: RobotUnit[];
}

export interface Vector {
  x: number;
  y: number;
}

export interface Entity {
  pos: Vector;
  vel: Vector;
  width: number;
  height: number;
  health: number;
  maxHealth: number;
}

export interface Bullet extends Entity {
  owner: 'player' | 'enemy';
  damage?: number;
  color?: string;
}

export interface Enemy extends Entity {
  id: number;
  isDead: boolean;
  type: string;
  lastShot: number;
  hasSplit?: boolean;
  sequenceStage?: number;
  sequenceTimer?: number;
  isTransformed?: boolean;
  transformTimer?: number;
}

import React, { useState, useEffect, useCallback } from 'react';
import { GameState, LevelInfo, RobotUnit, Upgrades } from './types';
import { getLevelBriefing } from './services/geminiService';
import MainMenu from './components/MainMenu';
import Briefing from './components/Briefing';
import GameView from './components/GameView';
import GameOver from './components/GameOver';
import Victory from './components/Victory';
import Shop from './components/Shop';
import RobotShop from './components/RobotShop';
import LevelSelect from './components/LevelSelect';

const SAVE_KEY = 'cybercop_save_data';

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>(GameState.MENU);
  const [level, setLevel] = useState(1);
  const [maxUnlockedLevel, setMaxUnlockedLevel] = useState(1);
  const [money, setMoney] = useState(0);
  const [upgrades, setUpgrades] = useState<Upgrades>({ 
    robotTier: 0, 
    weaponTier: 0, 
    unlockedUnits: [RobotUnit.SENTINEL] 
  });
  const [briefing, setBriefing] = useState<LevelInfo | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [hasSave, setHasSave] = useState(false);
  const [shopOrigin, setShopOrigin] = useState<GameState>(GameState.MENU);

  // Load progress on mount
  useEffect(() => {
    const savedData = localStorage.getItem(SAVE_KEY);
    if (savedData) {
      const parsed = JSON.parse(savedData);
      setHasSave(true);
      const savedLvl = parsed.level || 1;
      setLevel(savedLvl);
      setMaxUnlockedLevel(parsed.maxUnlockedLevel || savedLvl || 1);
      setMoney(parsed.money || 0);
      setUpgrades(parsed.upgrades || { 
        robotTier: 0, 
        weaponTier: 0, 
        unlockedUnits: [RobotUnit.SENTINEL] 
      });
    }
  }, []);

  // Global pause listener
  useEffect(() => {
    const handleGlobalKeyDown = (e: KeyboardEvent) => {
      if (e.code === 'KeyP') {
        setGameState(prev => {
          if (prev === GameState.PLAYING) return GameState.PAUSED;
          if (prev === GameState.PAUSED) return GameState.PLAYING;
          return prev;
        });
      }
    };
    window.addEventListener('keydown', handleGlobalKeyDown);
    return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, []);

  useEffect(() => {
    if (gameState !== GameState.MENU && gameState !== GameState.PAUSED && gameState !== GameState.LEVEL_SELECT) {
      const saveData = {
        level,
        maxUnlockedLevel,
        money,
        upgrades
      };
      localStorage.setItem(SAVE_KEY, JSON.stringify(saveData));
    }
  }, [level, maxUnlockedLevel, money, upgrades, gameState]);

  const startLevel = useCallback(async (lvl: number) => {
    setIsLoading(true);
    setGameState(GameState.BRIEFING);
    setLevel(lvl);
    const data = await getLevelBriefing(lvl);
    setBriefing(data);
    setIsLoading(false);
  }, []);

  const handleStartGame = () => {
    setLevel(1);
    setMaxUnlockedLevel(1);
    setMoney(0);
    setUpgrades({ robotTier: 0, weaponTier: 0, unlockedUnits: [RobotUnit.SENTINEL] });
    startLevel(1);
  };

  const handleContinueGame = () => {
    const savedData = localStorage.getItem(SAVE_KEY);
    if (savedData) {
      const parsed = JSON.parse(savedData);
      const targetLevel = parsed.level || 1;
      setLevel(targetLevel);
      setMaxUnlockedLevel(parsed.maxUnlockedLevel || targetLevel || 1);
      setMoney(parsed.money || 0);
      setUpgrades(parsed.upgrades || { 
        robotTier: 0, 
        weaponTier: 0, 
        unlockedUnits: [RobotUnit.SENTINEL] 
      });
      startLevel(targetLevel);
    }
  };

  const handleLevelComplete = () => {
    setMoney(prev => prev + 50); // Increased reward for buying robots
    const completedLevel = level;
    const nextLvl = level + 1;

    if (nextLvl > maxUnlockedLevel) {
      setMaxUnlockedLevel(nextLvl);
    }

    if (completedLevel >= 20) {
      setGameState(GameState.VICTORY);
    } else {
      setLevel(nextLvl);
      setGameState(GameState.LEVEL_COMPLETE);
    }
  };

  const openShop = (origin: GameState) => {
    setShopOrigin(origin);
    setGameState(GameState.SHOP);
  };

  const openRobotShop = () => {
    setGameState(GameState.ROBOT_SHOP);
  };

  const openLevelSelect = () => {
    setGameState(GameState.LEVEL_SELECT);
  };

  const handleSelectLevel = (lvlNum: number) => {
    startLevel(lvlNum);
  };

  const handleNextLevel = () => {
    startLevel(level);
  };

  const handleShopExit = () => {
    if (shopOrigin === GameState.MENU) {
      setGameState(GameState.MENU);
      setHasSave(true);
    } else {
      handleNextLevel();
    }
  };

  const handlePlayerDeath = () => {
    setGameState(GameState.GAMEOVER);
  };

  const handleRetry = () => {
    startLevel(level);
  };

  const buyRobotTier = () => {
    if (money >= 100) {
      setMoney(m => m - 100);
      setUpgrades(u => ({ ...u, robotTier: u.robotTier + 1 }));
    }
  };

  const buyWeaponTier = () => {
    if (money >= 50) {
      setMoney(m => m - 50);
      setUpgrades(u => ({ ...u, weaponTier: u.weaponTier + 1 }));
    }
  };

  const unlockRobotUnit = (unit: RobotUnit, price: number) => {
    if (money >= price && !upgrades.unlockedUnits.includes(unit)) {
      setMoney(m => m - price);
      setUpgrades(u => ({
        ...u,
        unlockedUnits: [...u.unlockedUnits, unit]
      }));
    }
  };

  const isGameVisible = gameState === GameState.PLAYING || gameState === GameState.PAUSED;

  return (
    <div className="w-full h-screen bg-black overflow-hidden select-none text-white font-rajdhani">
      {gameState === GameState.MENU && (
        <MainMenu 
          onStart={handleStartGame} 
          onContinue={handleContinueGame} 
          onOpenShop={() => openShop(GameState.MENU)}
          onOpenRobotShop={openRobotShop}
          onOpenLevelSelect={openLevelSelect}
          hasSave={hasSave} 
        />
      )}

      {gameState === GameState.LEVEL_SELECT && (
        <LevelSelect 
          currentUnlocked={maxUnlockedLevel} 
          onSelect={handleSelectLevel} 
          onBack={() => setGameState(GameState.MENU)} 
        />
      )}

      {gameState === GameState.BRIEFING && briefing && (
        <Briefing 
          briefing={briefing} 
          isLoading={isLoading} 
          onConfirm={() => setGameState(GameState.PLAYING)} 
        />
      )}

      {isGameVisible && (
        <GameView 
          level={level} 
          upgrades={upgrades}
          isPaused={gameState === GameState.PAUSED}
          onWin={handleLevelComplete} 
          onDie={handlePlayerDeath} 
        />
      )}

      {gameState === GameState.PAUSED && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex flex-col items-center justify-center z-50 animate-in fade-in duration-200">
          <div className="p-10 border-2 border-cyan-500 bg-black/80 relative overflow-hidden group">
            <div className="absolute top-0 left-0 w-full h-1 bg-cyan-500 animate-scan"></div>
            <h2 className="text-6xl font-black text-cyan-400 italic tracking-tighter uppercase mb-4">SYSTEM SUSPENDED</h2>
            <p className="text-cyan-200 font-mono tracking-widest text-center mb-8">TACTICAL ANALYSIS IN PROGRESS</p>
            <div className="flex flex-col gap-4 items-center">
              <button 
                onClick={() => setGameState(GameState.PLAYING)}
                className="px-12 py-4 bg-cyan-600 hover:bg-cyan-500 text-white font-bold text-2xl border-b-4 border-cyan-900 transition-all w-full uppercase"
              >
                RESUME MISSION
              </button>
              <button 
                onClick={() => setGameState(GameState.MENU)}
                className="px-12 py-2 text-cyan-400 font-bold hover:text-white transition-all uppercase text-sm"
              >
                ABORT TO HQ
              </button>
            </div>
          </div>
        </div>
      )}

      {gameState === GameState.LEVEL_COMPLETE && (
        <div className="fixed inset-0 bg-black/90 flex flex-col items-center justify-center z-50">
          <h2 className="text-5xl text-cyan-400 mb-2 font-black italic tracking-tighter animate-pulse uppercase">
            Sector {level - 1} Secured
          </h2>
          <div className="text-2xl text-yellow-400 mb-8 font-bold tracking-widest font-orbitron">REWARD EARNED: $50</div>
          <div className="flex gap-4 mb-4">
            <button 
              onClick={() => openShop(GameState.LEVEL_COMPLETE)}
              className="px-8 py-4 bg-yellow-600 hover:bg-yellow-500 text-white font-bold rounded-sm border-b-4 border-yellow-800 transition-all active:translate-y-1 w-64 shadow-[0_0_20px_rgba(202,138,4,0.3)] font-orbitron uppercase"
            >
              VISIT ARMORY
            </button>
            <button 
              onClick={() => setGameState(GameState.ROBOT_SHOP)}
              className="px-8 py-4 bg-purple-700 hover:bg-purple-600 text-white font-bold rounded-sm border-b-4 border-purple-900 transition-all active:translate-y-1 w-64 shadow-[0_0_20px_rgba(168,85,247,0.3)] font-orbitron uppercase"
            >
              SQUAD ASSEMBLY
            </button>
          </div>
          <button 
            onClick={handleNextLevel}
            className="px-12 py-3 bg-cyan-700 hover:bg-cyan-600 text-white font-bold rounded-sm transition-all w-[33rem] uppercase tracking-wider font-orbitron"
          >
            Deploy to Sector {level}
          </button>
          <button 
            onClick={() => {
              setGameState(GameState.MENU);
              setHasSave(true);
            }}
            className="px-12 py-2 text-gray-400 font-bold hover:text-white transition-all uppercase text-sm mt-8 border border-gray-800 hover:border-gray-400 bg-gray-950/40"
          >
            Return to HQ
          </button>
        </div>
      )}

      {gameState === GameState.SHOP && (
        <Shop 
          money={money} 
          upgrades={upgrades} 
          onBuyRobot={buyRobotTier} 
          onBuyWeapon={buyWeaponTier} 
          onExit={handleShopExit}
          isFromMenu={shopOrigin === GameState.MENU}
        />
      )}

      {gameState === GameState.ROBOT_SHOP && (
        <RobotShop 
          money={money} 
          unlockedUnits={upgrades.unlockedUnits} 
          onUnlock={unlockRobotUnit} 
          onExit={() => setGameState(GameState.MENU)}
        />
      )}

      {gameState === GameState.GAMEOVER && (
        <GameOver level={level} onRetry={handleRetry} onMenu={() => setGameState(GameState.MENU)} />
      )}

      {gameState === GameState.VICTORY && (
        <Victory onMenu={() => {
          localStorage.removeItem(SAVE_KEY);
          setHasSave(false);
          setGameState(GameState.MENU);
        }} />
      )}
    </div>
  );
};

