    robot: { speed: 3.5, jump: -10, fireRate: 25 },
    alt: { speed: 6, jump: -4, fireRate: 30, type: 'Shield Truck' }
  },
  [RobotUnit.NIGHTSHADE]: { 
    name: "NIGHTSHADE", color: '#6366f1', hpMult: 0.9, 
    robot: { speed: 7, jump: -13, fireRate: 12 },
    alt: { speed: 10, jump: -6, fireRate: 18, type: 'Interceptor' }
  },
  [RobotUnit.BLAZE]: { 
    name: "BLAZE", color: '#f97316', hpMult: 1.2, 
    robot: { speed: 4.5, jump: -11, fireRate: 18 },
    alt: { speed: 7, jump: -5, fireRate: 22, type: 'Rig' }
  },
  [RobotUnit.GLITCH]: { 
    name: "GLITCH", color: '#ec4899', hpMult: 1.0, 
    robot: { speed: 5, jump: -12, fireRate: 14 },
    alt: { speed: 9, jump: -12, fireRate: 16, type: 'Splicer' }
  },
  [RobotUnit.OMEGA]: { 
    name: "OMEGA", color: '#ffffff', hpMult: 3.0, 
    robot: { speed: 6, jump: -14, fireRate: 10 },
    alt: { speed: 10, jump: -8, fireRate: 15, type: 'Fortress' }
  },
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [currentUnit, setCurrentUnit] = useState<RobotUnit>(RobotUnit.SENTINEL);
  const [isTransformed, setIsTransformed] = useState(false);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [distance, setDistance] = useState(0);
  const [shieldTimeRemaining, setShieldTimeRemaining] = useState(0);
  const [unionTimeRemaining, setUnionTimeRemaining] = useState(0);
  const [showCheckpoint, setShowCheckpoint] = useState(false);

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      maxHealth: 100,
      isTransformed: false,
      shieldTimer: 0,
      unionTimer: 0,
      history: [] as {x: number, y: number}[],
      checkpoint: { x: 100, y: 300, reached: false }
    },
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    unit: RobotUnit.SENTINEL,
    level: level,
  });

  useEffect(() => { engineRef.current.isPaused = isPaused; }, [isPaused]);
  useEffect(() => { 
    engineRef.current.unit = currentUnit;
    engineRef.current.player.isTransformed = false;
    setIsTransformed(false);
  }, [currentUnit]);
  useEffect(() => { engineRef.current.level = level; }, [level]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff44');
    grad.addColorStop(1, '#00000088');
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.5)';
    ctx.stroke();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, type = 'bot', isTransformed = false, alpha = 1) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8;
    const armSwing = Math.cos(time) * 10;

    let scale = 1;
    if (type === 'scout') scale = 0.8;
    if (type === 'heavy' || type === 'titan') scale = 1.4;

    if (isEnemy && isTransformed) {
      scale *= 1.25;
      ctx.translate((Math.random() - 0.5) * 3, (Math.random() - 0.5) * 3);
    }

    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(scale, scale);

    if (isEnemy && isTransformed) {
      ctx.shadowBlur = 20;
      ctx.shadowColor = '#ff3300';
    }

    drawMechanicalPart(ctx, -12, -18, 24, 28, isTransformed ? '#400' : color, 4);
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? (isTransformed ? '#fff' : '#ff0000') : (color === '#ffffff' ? '#00f3ff' : '#00f3ff');
    ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);

    if (isEnemy && isTransformed) {
      const corePulse = Math.sin(frame * 0.4) * 3;
      ctx.fillStyle = frame % 4 < 2 ? '#ff0000' : '#ffffff';
      ctx.beginPath();
      ctx.arc(0, -5, 5 + corePulse, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.restore();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, color: string, frame: number, alpha = 1) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    switch(unit) {
      case RobotUnit.SENTINEL:
        drawMechanicalPart(ctx, -24, -10, 48, 18, color, 8);
        drawMechanicalPart(ctx, -16, -20, 30, 12, '#111', 4);
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(-15, 10, 7, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(15, 10, 7, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = frame % 10 < 5 ? '#ff0000' : '#0000ff';
        ctx.fillRect(-4, -22, 10, 3);
        break;
      case RobotUnit.STRIKER:
        drawMechanicalPart(ctx, -18, -8, 36, 12, color, 4);
        drawMechanicalPart(ctx, -5, -18, 18, 12, '#222', 2);
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(-18, 8, 9, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(18, 8, 9, 0, Math.PI * 2); ctx.fill();
        break;
      case RobotUnit.FALCON:
        drawMechanicalPart(ctx, -20, -10, 40, 15, color, 12);
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(-10, -5); ctx.lineTo(-30, -15); ctx.lineTo(-10, 5); ctx.fill();
        ctx.fillStyle = '#ffaa00';
        ctx.fillRect(-28, -5, 8, 5);
        break;
      case RobotUnit.TITAN:
        drawMechanicalPart(ctx, -30, -10, 60, 22, color, 4);
        drawMechanicalPart(ctx, -15, -25, 30, 15, '#222', 4);
        drawMechanicalPart(ctx, 10, -20, 25, 5, '#444', 0);
        ctx.fillStyle = '#111';
        ctx.fillRect(-28, 8, 56, 6);
        break;
      case RobotUnit.SPECTER:
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.arc(0, 0, 18, 0, Math.PI * 2); ctx.fill();
        ctx.strokeStyle = '#fff'; ctx.lineWidth = 1; ctx.stroke();
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(8, -4, 4, 0, Math.PI * 2); ctx.fill();
        break;
      default:
        // Generic alt mode for new units
        drawMechanicalPart(ctx, -25, -12, 50, 24, color, 4);
        drawMechanicalPart(ctx, -10, -22, 20, 10, '#333', 2);
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(-15, 12, 8, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(15, 12, 8, 0, Math.PI * 2); ctx.fill();
        break;
    }
    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy = false, isInvuln = false, isTransformed = false, type = 'bot', alpha = 1) => {
    if (isInvuln && frame % 4 < 2) return;

    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    if (facing === -1) ctx.scale(-1, 1);

    const stats = ROBOT_STATS[unit];
    const color = isEnemy ? '#ff0055' : (stats?.color || '#00f3ff');

    if (isTransformed && !isEnemy) {
      drawAltMode(ctx, unit, color, frame, alpha);
    } else {
      drawHumanoid(ctx, color, frame, isEnemy, type, isTransformed, alpha);
    }

    ctx.restore();
  };

  const resetLevel = useCallback((fromCheckpoint = false) => {
    const e = engineRef.current;
    const stats = ROBOT_STATS[currentUnit];
    const baseHP = 100 + (upgrades.robotTier * 50);

    e.player.maxHealth = baseHP * stats.hpMult;
    e.player.shieldTimer = 0;
    e.player.unionTimer = 0;
    setShieldTimeRemaining(0);
    setUnionTimeRemaining(0);
    setMaxHealth(e.player.maxHealth);
    setHealth(e.player.maxHealth);

    if (fromCheckpoint && e.player.checkpoint.reached) {
      e.player.pos = { x: e.player.checkpoint.x, y: e.player.checkpoint.y };
    } else {
      e.player.pos = { x: 100, y: 300 };
      e.player.checkpoint.reached = false;
    }

    e.player.vel = { x: 0, y: 0 };
    e.player.invulnerable = 0;
    e.player.isTransformed = false;
    e.player.history = [];
    setIsTransformed(false);
    e.bullets = [];
    e.cameraX = e.player.pos.x - CANVAS_WIDTH/3;
    setDistance(e.player.pos.x);

    if (!fromCheckpoint) {
      const enemies: Enemy[] = [];
      const floorY = 398;
      const enemyTypes = ['bot', 'scout', 'sniper', 'heavy'];
      for (let i = 0; i < 4; i++) {
        const type = enemyTypes[i % (level < 5 ? 1 : level < 10 ? 2 : 4)];
        let w = 32, h = 48, hp = (50 + level * 15) * 4;
        if (type === 'scout') { w = 24; h = 36; hp = (40 + level * 5) * 4; }
        if (type === 'heavy') { w = 48; h = 72; hp = (150 + level * 20) * 4; }

        enemies.push({ 
          id: i, 
          pos: { x: 800 + i * 700, y: floorY - h }, 
          vel: { x: 0, y: 0 }, 
          width: w, 
          height: h, 
          health: hp, 
          maxHealth: hp, 
          isDead: false, 
          type: type, 
          lastShot: 0,
          sequenceStage: 0,
          sequenceTimer: 0,
          isTransformed: false,
          transformTimer: 0
        });
      }

      enemies.push({ 
        id: 4, 
        pos: { x: 4000, y: floorY - 96 }, 
        vel: { x: 0, y: 0 }, 
        width: 80, 
        height: 96, 
        health: (500 + level * 50) * 4,
        maxHealth: (500 + level * 50) * 4, 
        isDead: false, 
        type: 'titan', 
        lastShot: 0,
        isTransformed: false
      });
      e.enemies = enemies;
    }
  }, [level, upgrades, currentUnit]);

  useEffect(() => {
    resetLevel();
    const handleKeyDown = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = true;

      const trySwitch = (unit: RobotUnit) => {
        if (upgrades.unlockedUnits.includes(unit)) {
          setCurrentUnit(unit);
        }
      };

      if (e.code === 'Digit1') trySwitch(RobotUnit.SENTINEL);
      if (e.code === 'Digit2') trySwitch(RobotUnit.STRIKER);
      if (e.code === 'Digit3') trySwitch(RobotUnit.FALCON);
      if (e.code === 'Digit4') trySwitch(RobotUnit.TITAN);
      if (e.code === 'Digit5') trySwitch(RobotUnit.SPECTER);
      if (e.code === 'Digit6') trySwitch(RobotUnit.VANGUARD);
      if (e.code === 'Digit7') trySwitch(RobotUnit.NIGHTSHADE);
      if (e.code === 'Digit8') trySwitch(RobotUnit.BLAZE);
      if (e.code === 'Digit9') trySwitch(RobotUnit.GLITCH);
      if (e.code === 'Digit0') trySwitch(RobotUnit.OMEGA);

      if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') {
        engineRef.current.player.isTransformed = !engineRef.current.player.isTransformed;
        setIsTransformed(engineRef.current.player.isTransformed);
      }

      if (e.code === 'KeyU') {
        engineRef.current.player.shieldTimer = SHIELD_DURATION;
      }

      if (e.code === 'KeyT') {
        engineRef.current.player.unionTimer = SQUAD_UNION_DURATION;
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => { engineRef.current.keys[e.code] = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!engineRef.current.isPaused) update();
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const e = engineRef.current;
      const { player, enemies, bullets, keys } = e;
      const stats = ROBOT_STATS[e.unit];
      const currentStats = player.isTransformed ? stats.alt : stats.robot;
      e.frame++;

      if (!player.checkpoint.reached && player.pos.x > 2000) {
        player.checkpoint.reached = true;
        player.checkpoint.x = player.pos.x;
        player.checkpoint.y = player.pos.y;
        setShowCheckpoint(true);
        setTimeout(() => setShowCheckpoint(false), 3000);
      }

      player.history.unshift({ x: player.pos.x, y: player.pos.y });
      if (player.history.length > 200) player.history.pop();

      if (player.shieldTimer > 0) {
        player.shieldTimer--;
        if (e.frame % 30 === 0) setShieldTimeRemaining(Math.ceil(player.shieldTimer / 60));
      } else if (shieldTimeRemaining > 0) {
        setShieldTimeRemaining(0);
      }

      if (player.unionTimer > 0) {
        player.unionTimer--;
        if (e.frame % 30 === 0) setUnionTimeRemaining(Math.ceil(player.unionTimer / 60));
      } else if (unionTimeRemaining > 0) {
        setUnionTimeRemaining(0);
      }

      const ph = player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48);
      const pw = player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32);

      if (keys['ArrowRight'] || keys['KeyD']) { player.vel.x = currentStats.speed; player.facing = 1; }
      else if (keys['ArrowLeft'] || keys['KeyA']) { player.vel.x = -currentStats.speed; player.facing = -1; }
      else { player.vel.x *= 0.8; }

      if (e.unit === RobotUnit.FALCON && player.isTransformed) {
        if (keys['ArrowUp'] || keys['KeyW']) player.vel.y = -currentStats.speed;
        else if (keys['ArrowDown'] || keys['KeyS']) player.vel.y = currentStats.speed;
        else player.vel.y *= 0.9;
        player.grounded = false;
      } else {
        if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.grounded) {
          player.vel.y = currentStats.jump;
          player.grounded = false;
        }
        player.vel.y += GRAVITY;
      }

      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;

      const floorY = 398;
      if (player.pos.y > floorY - ph) { 
        player.pos.y = floorY - ph; 
        player.vel.y = 0; 
        player.grounded = true; 
      }
      if (player.pos.x < 0) player.pos.x = 0;
      setDistance(player.pos.x);

      const fr = Math.max(5, currentStats.fireRate - upgrades.weaponTier * 2);
      if (keys['Space'] && e.frame - player.lastShot > fr) {
        soundService.playShoot();
        const dmg = player.isTransformed ? 40 : (e.unit === RobotUnit.TITAN ? 60 : (e.unit === RobotUnit.SPECTER ? 80 : (e.unit === RobotUnit.OMEGA ? 120 : 25)));
        bullets.push({ 
          pos: { x: player.pos.x + (player.facing === 1 ? pw : 0), y: player.pos.y + ph/2 }, 
          vel: { x: player.facing * (e.unit === RobotUnit.SPECTER ? 25 : 15), y: 0 }, 
          width: player.isTransformed ? 12 : 8, 
          height: 4, 
          owner: 'player', 
          health: 1, maxHealth: 1, damage: dmg, color: stats.color 
        });

        if (player.unionTimer > 0) {
          (Object.keys(RobotUnit) as RobotUnit[]).forEach((u, i) => {
            if (u === e.unit) return;
            if (!upgrades.unlockedUnits.includes(u)) return;

            const cStats = ROBOT_STATS[u];
            const histIdx = (i + 1) * 10; // Tighter pack for 10 units
            const histPos = player.history[histIdx] || player.pos;
            bullets.push({
              pos: { x: histPos.x + (player.facing === 1 ? 20 : 0), y: histPos.y + 20 },
              vel: { x: player.facing * 12, y: 0 },
              width: 8, height: 4, owner: 'player', health: 1, maxHealth: 1, damage: 15, color: cStats.color
            });
          });
        }
        player.lastShot = e.frame;
      }

      for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i]; 
        b.pos.x += b.vel.x; 
        b.pos.y += b.vel.y;

        if (b.owner === 'enemy' && !player.invulnerable && player.shieldTimer <= 0) {
          if (b.pos.x < player.pos.x + pw && b.pos.x + b.width > player.pos.x &&
              b.pos.y < player.pos.y + ph && b.pos.y + b.height > player.pos.y) {
            setHealth(h => Math.max(0, h - (b.damage || 40)));
            player.invulnerable = 40;
            bullets.splice(i, 1);
            soundService.playLose();
            continue;
          }
        } else if (b.owner === 'enemy' && player.shieldTimer > 0) {
          if (b.pos.x < player.pos.x + pw + 20 && b.pos.x + b.width > player.pos.x - 20 &&
              b.pos.y < player.pos.y + ph + 20 && b.pos.y + b.height > player.pos.y - 20) {
            bullets.splice(i, 1);
            continue;
          }
        }

        if (Math.abs(b.pos.x - player.pos.x) > 1200) {
          bullets.splice(i, 1);
        }
      }

      let allDead = true;
      enemies.forEach(en => {
        if (en.isDead) return;
        allDead = false;

        const dist = Math.abs(en.pos.x - player.pos.x);
        const dir = Math.sign(player.pos.x - en.pos.x);
        const hpPercent = en.health / en.maxHealth;

        if (hpPercent < 0.3 && !en.isTransformed) {
          en.isTransformed = true;
          en.width *= 1.3;
          en.height *= 1.3;
        }

        const moveMult = en.isTransformed ? 2.2 : 1.0;

        switch(en.type) {
          case 'bot':
            if (dist > 350) en.vel.x = dir * 2 * moveMult;
            else if (dist < 200) en.vel.x = -dir * 2 * moveMult;
            else en.vel.x *= 0.8;
            break;
          case 'scout':
            en.vel.x = dir * 4 * moveMult;
            break;
          case 'sniper':
            if (dist < 500) en.vel.x = -dir * 3 * moveMult;
            else en.vel.x *= 0.5;
            break;
          case 'heavy':
          case 'titan':
            en.vel.x = dir * 1 * moveMult;
            break;
        }

        if (hpPercent < 0.5 && hpPercent >= 0.3 && en.type !== 'scout') {
          en.vel.x = -dir * 2.5;
        }

        en.pos.x += en.vel.x;

        if (dist < 600) {
          const rawCooldown = en.type === 'heavy' ? 120 : en.type === 'scout' ? 60 : en.type === 'sniper' ? 180 : 100;
          const cooldown = en.isTransformed ? rawCooldown * 0.4 : rawCooldown;

          if (e.frame - en.lastShot > cooldown) {
            switch(en.type) {
              case 'bot':
                bullets.push({ 
                  pos: {x: en.pos.x, y: en.pos.y + 15}, 
                  vel: {x: dir * (en.isTransformed ? 12 : 6), y: 0}, 
                  width: en.isTransformed ? 15 : 10, 
                  height: en.isTransformed ? 6 : 4, 
                  owner: 'enemy', health: 1, maxHealth: 1, 
                  damage: en.isTransformed ? 60 : 35, 
                  color: '#f00' 
                });
                en.lastShot = e.frame;
                break;
              case 'scout':
                if (en.sequenceStage < (en.isTransformed ? 6 : 3)) {
                   if (e.frame % (en.isTransformed ? 4 : 8) === 0) {
                      bullets.push({ 
                        pos: {x: en.pos.x, y: en.pos.y + 10}, 
                        vel: {x: dir * (en.isTransformed ? 14 : 9), y: (Math.random()-0.5)*2}, 
                        width: 6, height: 3, 
                        owner: 'enemy', health: 1, maxHealth: 1, 
                        damage: 25, 
                        color: '#f55' 
                      });
                      en.sequenceStage++;
                   }
                } else {
                   en.sequenceStage = 0;
                   en.lastShot = e.frame;
                }
                break;
              case 'sniper':
                bullets.push({ 
                  pos: {x: en.pos.x, y: en.pos.y + 10}, 
                  vel: {x: dir * 16, y: 0}, 
                  width: 24, height: 2, 
                  owner: 'enemy', health: 1, maxHealth: 1, 
                  damage: en.isTransformed ? 180 : 100, 
                  color: '#fff' 
                });
                en.lastShot = e.frame;
                break;
              case 'heavy':
              case 'titan':
                const numBullets = en.isTransformed ? 7 : 3;
                for(let j=-(numBullets>>1); j<=(numBullets>>1); j++) {
                  bullets.push({ 
                    pos: {x: en.pos.x, y: en.pos.y + 30}, 
                    vel: {x: dir * 6, y: j * (en.isTransformed ? 2 : 1.2)}, 
                    width: 14, height: 10, 
                    owner: 'enemy', health: 1, maxHealth: 1, 
                    damage: 100, 
                    color: '#f00' 
                  });
                }
                en.lastShot = e.frame;
                break;
            }
          }
        }

        bullets.forEach((b, idx) => {
          if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) {
            en.health -= b.damage || 20; 
            bullets.splice(idx, 1);
            if (en.health <= 0) en.isDead = true;
          }
        });

        if (!player.invulnerable && player.shieldTimer <= 0 && player.pos.x < en.pos.x + en.width && player.pos.x + pw > en.pos.x && player.pos.y < en.pos.y + en.height && player.pos.y + ph > en.pos.y) {
           setHealth(h => Math.max(0, h - (en.type === 'heavy' || en.type === 'titan' ? 150 : 80))); 
           player.invulnerable = 60; 
           soundService.playLose();
        }
      });

      if (health <= 0) {
        if (player.checkpoint.reached) {
          resetLevel(true);
        } else {
          onDie();
        }
      }
      if (allDead) onWin();
      if (player.invulnerable > 0) player.invulnerable--;
      e.cameraX = player.pos.x - CANVAS_WIDTH/3;
      if (e.cameraX < 0) e.cameraX = 0;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const e = engineRef.current;
      ctx.fillStyle = '#050510'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

      ctx.fillStyle = '#1c1c1c'; ctx.fillRect(0, 398, CANVAS_WIDTH, 52);
      ctx.strokeStyle = '#222';
      for(let i=0; i<CANVAS_WIDTH; i+=40) {
        ctx.beginPath(); ctx.moveTo(i - (e.cameraX % 40), 398); ctx.lineTo(i - (e.cameraX % 40), CANVAS_HEIGHT); ctx.stroke();
      }

      e.enemies.forEach(en => { 
        if(!en.isDead) drawUnit(ctx, en.pos.x - e.cameraX, en.pos.y, en.width, en.height, RobotUnit.SENTINEL, Math.sign(e.player.pos.x - en.pos.x), e.frame, true, false, en.isTransformed, en.type); 
      });

      const player = e.player;
      const ph = player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48);
      const pw = player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32);

      if (player.unionTimer > 0) {
        (Object.keys(RobotUnit) as RobotUnit[]).forEach((u, i) => {
          if (u === e.unit) return;
          if (!upgrades.unlockedUnits.includes(u)) return;

          const histIdx = (i + 1) * 10;
          const histPos = player.history[histIdx] || player.pos;
          drawUnit(ctx, histPos.x - e.cameraX, histPos.y, 24, 36, u, player.facing, e.frame, false, false, false, 'bot', 0.5);
        });
      }

      drawUnit(ctx, player.pos.x - e.cameraX, player.pos.y, pw, ph, e.unit, player.facing, e.frame, false, player.invulnerable > 0, player.isTransformed);

      if (player.shieldTimer > 0) {
        const shieldPulse = Math.sin(e.frame * 0.1) * 5;
        ctx.save();
        ctx.translate(player.pos.x - e.cameraX + pw / 2, player.pos.y + ph / 2);
        ctx.beginPath();
        ctx.arc(0, 0, Math.max(pw, ph) * 0.8 + shieldPulse, 0, Math.PI * 2);
        ctx.strokeStyle = '#00f3ff';
        ctx.lineWidth = 3;
        ctx.shadowBlur = 15;
        ctx.shadowColor = '#00f3ff';
        ctx.stroke();
        ctx.globalAlpha = 0.2;
        ctx.fillStyle = '#00f3ff';
        ctx.fill();
        ctx.restore();
      }

      e.bullets.forEach(b => { 
        ctx.fillStyle = b.color || (b.owner === 'player' ? '#00f3ff' : '#ff0055'); 
        ctx.fillRect(b.pos.x - e.cameraX, b.pos.y, b.width, b.height); 
      });
    };

    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [resetLevel, onWin, onDie, level, upgrades, health, currentUnit, shieldTimeRemaining, unionTimeRemaining]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden">
      <div className="absolute top-4 left-4 z-10 space-y-4 pointer-events-none w-[400px]">
        <div className="bg-black/80 border border-cyan-500/50 p-3 rounded backdrop-blur-md shadow-lg">
          <div className="text-[10px] text-cyan-400 font-bold uppercase mb-1 flex justify-between font-orbitron">
            <span>{ROBOT_STATS[currentUnit].name} INTEGRITY</span>
            <span>{Math.round(health)}/{Math.round(maxHealth)}</span>
          </div>
          <div className="w-48 h-2.5 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
            <div 
              className="h-full shadow-[0_0_15px_#00f3ff] transition-all duration-300" 
              style={{ 
                width: `${(health / maxHealth) * 100}%`,
                backgroundColor: health < maxHealth * 0.3 ? '#ef4444' : (ROBOT_STATS[currentUnit].color === '#ffffff' ? '#00f3ff' : ROBOT_STATS[currentUnit].color)
              }} 
            />
          </div>

          <div className="flex flex-col gap-1 mt-2">
            {shieldTimeRemaining > 0 && (
              <div className="flex items-center gap-2">
                <div className="text-[10px] text-blue-400 font-black animate-pulse font-orbitron">SHIELD: {shieldTimeRemaining}s</div>
                <div className="flex-1 h-1 bg-blue-900 rounded-full overflow-hidden">
                  <div className="h-full bg-cyan-400" style={{ width: `${(shieldTimeRemaining / 20) * 100}%` }}></div>
                </div>
              </div>
            )}
            {unionTimeRemaining > 0 && (
              <div className="flex items-center gap-2">
                <div className="text-[10px] text-purple-400 font-black animate-pulse font-orbitron">SQUAD UNION: {unionTimeRemaining}s</div>
                <div className="flex-1 h-1 bg-purple-900 rounded-full overflow-hidden">
                  <div className="h-full bg-purple-400" style={{ width: `${(unionTimeRemaining / 60) * 100}%` }}></div>
                </div>
              </div>
            )}
          </div>

          <div className="mt-2 text-[8px] text-white/50 font-mono flex justify-between">
            <span>MODE: {isTransformed ? `ALT (${ROBOT_STATS[currentUnit].alt.type})` : 'HUMANOID'}</span>
            <span className="animate-pulse text-red-500 font-bold uppercase">[Sector: {level}]</span>
          </div>
        </div>

        <div className="flex flex-col gap-1 pointer-events-auto">
           <div className="text-[8px] text-white/50 font-bold uppercase tracking-tighter ml-1 font-orbitron">SQUAD_DEPLOYMENT [1-0]</div>
           <div className="flex flex-wrap gap-1.5 max-w-[320px]">
           {(Object.keys(ROBOT_STATS) as RobotUnit[]).map((u, i) => {
             const stats = ROBOT_STATS[u];
             const isActive = currentUnit === u;
             const isUnlocked = upgrades.unlockedUnits.includes(u);
             const keyLabel = (i + 1) % 10;

             return (
               <button 
                 key={u} 
                 disabled={!isUnlocked}
                 onClick={() => setCurrentUnit(u)}
                 className={`group relative w-10 h-10 flex flex-col items-center justify-center rounded-sm border-2 transition-all duration-200 ${
                   isActive 
                     ? 'bg-white/10' 
                     : isUnlocked 
                       ? 'border-gray-800 bg-black/60 hover:border-gray-600'
                       : 'border-gray-900 bg-black/40 grayscale opacity-20 cursor-not-allowed'
                 }`}
                 style={{
                   borderColor: isActive ? stats.color : '',
                   boxShadow: isActive ? `0 0 15px ${stats.color}50` : 'none'
                 }}
               >
                 {isActive && (
                   <>
                     <div className="absolute -top-1 -left-1 w-2 h-2 border-t-2 border-l-2" style={{ borderColor: stats.color }} />
                     <div className="absolute -bottom-1 -right-1 w-2 h-2 border-b-2 border-r-2" style={{ borderColor: stats.color }} />
                   </>
                 )}
                 <span className={`text-base font-black font-orbitron transition-colors ${isActive ? 'text-white' : isUnlocked ? 'text-gray-600' : 'text-gray-900'}`}>
                   {keyLabel}
                 </span>
                 <div className="absolute -top-6 px-1.5 py-0.5 rounded bg-black/95 border border-gray-800 text-[6px] font-bold uppercase tracking-widest text-white opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap pointer-events-none z-20">
                    {isUnlocked ? stats.name : 'LOCKED'}
                 </div>
               </button>
             );
           })}
           </div>
        </div>
      </div>

      {showCheckpoint && (
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 pointer-events-none animate-in fade-in zoom-in duration-500">
          <div className="bg-cyan-600/80 border-2 border-white px-8 py-4 backdrop-blur-md shadow-[0_0_50px_#00f3ff]">
            <h3 className="text-3xl font-black text-white italic tracking-tighter uppercase font-orbitron">CHECKPOINT REACHED</h3>
            <p className="text-white font-mono text-center tracking-widest text-xs mt-2">DEPLOYMENT ANCHOR SET</p>
          </div>
        </div>
      )}

      <div className="absolute top-4 right-4 z-10 text-right pointer-events-none font-orbitron">
        <div className="text-[10px] text-cyan-500 font-bold uppercase tracking-widest">Active Sector</div>
        <div className="text-3xl font-black text-white italic drop-shadow-md">{level.toString().padStart(2, '0')}</div>
      </div>

      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full aspect-video shadow-2xl rounded-lg border-2 border-cyan-900/50" />

      {health < maxHealth * 0.3 && (
        <div className="absolute inset-0 pointer-events-none border-[16px] border-red-600/20 animate-pulse shadow-[inset_0_0_100px_rgba(239,68,68,0.3)]"></div>
      )}

      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 pointer-events-none text-white/30 text-[8px] font-mono tracking-widest uppercase flex flex-wrap justify-center gap-x-6 gap-y-1 max-w-full px-4 text-center">
        <span>WASD: Move</span>
        <span>Space: Fire</span>
        <span>Shift: Transform</span>
        <span>U: Shield</span>
        <span>T: Union</span>
        <span>P: Pause</span>
        <span>1-0: Switch</span>
      </div>
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const SHIELD_DURATION = 20 * 60; // 20 seconds at 60fps
const SQUAD_UNION_DURATION = 60 * 60; // 60 seconds at 60fps

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { 
    name: "SENTINEL", color: '#00f3ff', hpMult: 1.0, 
    robot: { speed: 4, jump: -11, fireRate: 15 },
    alt: { speed: 8, jump: -5, fireRate: 25, type: 'Car' }
  },
  [RobotUnit.STRIKER]: { 
    name: "STRIKER", color: '#fbbf24', hpMult: 0.8,
    robot: { speed: 6, jump: -10, fireRate: 10 },
    alt: { speed: 12, jump: -4, fireRate: 20, type: 'Bike' }
  },
  [RobotUnit.FALCON]: { 
    name: "FALCON", color: '#22d3ee', hpMult: 0.7,
    robot: { speed: 5, jump: -10, fireRate: 12 },
    alt: { speed: 7, jump: -7, fireRate: 15, type: 'Jet' }
  },
  [RobotUnit.TITAN]: { 
    name: "TITAN", color: '#ef4444', hpMult: 2.5,
    robot: { speed: 2.5, jump: -12, fireRate: 30 },
    alt: { speed: 4, jump: 0, fireRate: 20, type: 'Tank' }
  },
  [RobotUnit.SPECTER]: { 
    name: "SPECTER", color: '#a855f7', hpMult: 0.6,
    robot: { speed: 5, jump: -11, fireRate: 20 },
    alt: { speed: 6, jump: -14, fireRate: 40, type: 'Sphere' }
  },
  [RobotUnit.VANGUARD]: { 
    name: "VANGUARD", color: '#10b981', hpMult: 2.0, 
    robot: { speed: 3.5, jump: -10, fireRate: 25 },
    alt: { speed: 6, jump: -4, fireRate: 30, type: 'Shield Truck' }
  },
  [RobotUnit.NIGHTSHADE]: { 
    name: "NIGHTSHADE", color: '#6366f1', hpMult: 0.9, 
    robot: { speed: 7, jump: -13, fireRate: 12 },
    alt: { speed: 10, jump: -6, fireRate: 18, type: 'Interceptor' }
  },
  [RobotUnit.BLAZE]: { 
    name: "BLAZE", color: '#f97316', hpMult: 1.2, 
    robot: { speed: 4.5, jump: -11, fireRate: 18 },
    alt: { speed: 7, jump: -5, fireRate: 22, type: 'Rig' }
  },
  [RobotUnit.GLITCH]: { 
    name: "GLITCH", color: '#ec4899', hpMult: 1.0, 
    robot: { speed: 5, jump: -12, fireRate: 14 },
    alt: { speed: 9, jump: -12, fireRate: 16, type: 'Splicer' }
  },
  [RobotUnit.OMEGA]: { 
    name: "OMEGA", color: '#ffffff', hpMult: 3.0, 
    robot: { speed: 6, jump: -14, fireRate: 10 },
    alt: { speed: 10, jump: -8, fireRate: 15, type: 'Fortress' }
  },
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [currentUnit, setCurrentUnit] = useState<RobotUnit>(RobotUnit.SENTINEL);
  const [isTransformed, setIsTransformed] = useState(false);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [distance, setDistance] = useState(0);
  const [shieldTimeRemaining, setShieldTimeRemaining] = useState(0);
  const [unionTimeRemaining, setUnionTimeRemaining] = useState(0);
  const [showCheckpoint, setShowCheckpoint] = useState(false);

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      maxHealth: 100,
      isTransformed: false,
      shieldTimer: 0,
      unionTimer: 0,
      history: [] as {x: number, y: number}[],
      checkpoint: { x: 100, y: 300, reached: false }
    },
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    unit: RobotUnit.SENTINEL,
    level: level,
  });

  useEffect(() => { engineRef.current.isPaused = isPaused; }, [isPaused]);
  useEffect(() => { 
    engineRef.current.unit = currentUnit;
    engineRef.current.player.isTransformed = false;
    setIsTransformed(false);
  }, [currentUnit]);
  useEffect(() => { engineRef.current.level = level; }, [level]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff44');
    grad.addColorStop(1, '#00000088');
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.5)';
    ctx.stroke();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, type = 'bot', isTransformed = false, alpha = 1) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8;
    const armSwing = Math.cos(time) * 10;

    let scale = 1;
    if (type === 'scout') scale = 0.8;
    if (type === 'heavy' || type === 'titan') scale = 1.4;

    if (isEnemy && isTransformed) {
      scale *= 1.25;
      ctx.translate((Math.random() - 0.5) * 3, (Math.random() - 0.5) * 3);
    }

    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(scale, scale);

    if (isEnemy && isTransformed) {
      ctx.shadowBlur = 20;
      ctx.shadowColor = '#ff3300';
    }

    drawMechanicalPart(ctx, -12, -18, 24, 28, isTransformed ? '#400' : color, 4);
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? (isTransformed ? '#fff' : '#ff0000') : '#00f3ff';
    ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);

    if (isEnemy && isTransformed) {
      const corePulse = Math.sin(frame * 0.4) * 3;
      ctx.fillStyle = frame % 4 < 2 ? '#ff0000' : '#ffffff';
      ctx.beginPath();
      ctx.arc(0, -5, 5 + corePulse, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.restore();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, color: string, frame: number, alpha = 1) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    switch(unit) {
      case RobotUnit.SENTINEL:
        drawMechanicalPart(ctx, -24, -10, 48, 18, color, 8);
        drawMechanicalPart(ctx, -16, -20, 30, 12, '#111', 4);
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(-15, 10, 7, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(15, 10, 7, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = frame % 10 < 5 ? '#ff0000' : '#0000ff';
        ctx.fillRect(-4, -22, 10, 3);
        break;
      case RobotUnit.STRIKER:
        drawMechanicalPart(ctx, -18, -8, 36, 12, color, 4);
        drawMechanicalPart(ctx, -5, -18, 18, 12, '#222', 2);
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(-18, 8, 9, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(18, 8, 9, 0, Math.PI * 2); ctx.fill();
        break;
      case RobotUnit.FALCON:
        drawMechanicalPart(ctx, -20, -10, 40, 15, color, 12);
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(-10, -5); ctx.lineTo(-30, -15); ctx.lineTo(-10, 5); ctx.fill();
        ctx.fillStyle = '#ffaa00';
        ctx.fillRect(-28, -5, 8, 5);
        break;
      case RobotUnit.TITAN:
        drawMechanicalPart(ctx, -30, -10, 60, 22, color, 4);
        drawMechanicalPart(ctx, -15, -25, 30, 15, '#222', 4);
        drawMechanicalPart(ctx, 10, -20, 25, 5, '#444', 0);
        ctx.fillStyle = '#111';
        ctx.fillRect(-28, 8, 56, 6);
        break;
      case RobotUnit.SPECTER:
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.arc(0, 0, 18, 0, Math.PI * 2); ctx.fill();
        ctx.strokeStyle = '#fff'; ctx.lineWidth = 1; ctx.stroke();
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(8, -4, 4, 0, Math.PI * 2); ctx.fill();
        break;
      default:
        drawMechanicalPart(ctx, -25, -12, 50, 24, color, 6);
        drawMechanicalPart(ctx, -10, -22, 20, 10, '#333', 2);
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(-15, 12, 8, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(15, 12, 8, 0, Math.PI * 2); ctx.fill();
        break;
    }
    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy = false, isInvuln = false, isTransformed = false, type = 'bot', alpha = 1) => {
    if (isInvuln && frame % 4 < 2) return;

    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    if (facing === -1) ctx.scale(-1, 1);

    const stats = ROBOT_STATS[unit];
    const color = isEnemy ? '#ff0055' : (stats?.color || '#00f3ff');

    if (isTransformed && !isEnemy) {
      drawAltMode(ctx, unit, color, frame, alpha);
    } else {
      drawHumanoid(ctx, color, frame, isEnemy, type, isTransformed, alpha);
    }

    ctx.restore();
  };

  const resetLevel = useCallback((fromCheckpoint = false) => {
    const e = engineRef.current;
    const stats = ROBOT_STATS[currentUnit];
    const baseHP = 100 + (upgrades.robotTier * 50);

    e.player.maxHealth = baseHP * stats.hpMult;
    e.player.shieldTimer = 0;
    e.player.unionTimer = 0;
    setShieldTimeRemaining(0);
    setUnionTimeRemaining(0);
    setMaxHealth(e.player.maxHealth);
    setHealth(e.player.maxHealth);

    if (fromCheckpoint && e.player.checkpoint.reached) {
      e.player.pos = { x: e.player.checkpoint.x, y: e.player.checkpoint.y };
    } else {
      e.player.pos = { x: 100, y: 300 };
      e.player.checkpoint.reached = false;
    }

    e.player.vel = { x: 0, y: 0 };
    e.player.invulnerable = 0;
    e.player.isTransformed = false;
    e.player.history = [];
    setIsTransformed(false);
    e.bullets = [];
    e.cameraX = e.player.pos.x - CANVAS_WIDTH/3;
    setDistance(e.player.pos.x);

    if (!fromCheckpoint) {
      const enemies: Enemy[] = [];
      const floorY = 398;
      const enemyTypes = ['bot', 'scout', 'sniper', 'heavy'];
      for (let i = 0; i < 5; i++) {
        const type = enemyTypes[i % (level < 5 ? 1 : level < 10 ? 2 : 4)];
        let w = 32, h = 48, hp = (50 + level * 15) * 4;
        if (type === 'scout') { w = 24; h = 36; hp = (40 + level * 5) * 4; }
        if (type === 'heavy') { w = 48; h = 72; hp = (150 + level * 20) * 4; }

        enemies.push({ 
          id: i, 
          pos: { x: 800 + i * 700, y: floorY - h }, 
          vel: { x: 0, y: 0 }, 
          width: w, 
          height: h, 
          health: hp, 
          maxHealth: hp, 
          isDead: false, 
          type: type, 
          lastShot: 0,
          sequenceStage: 0,
          sequenceTimer: 0,
          isTransformed: false,
          transformTimer: 0
        });
      }
      e.enemies = enemies;
    }
  }, [level, upgrades, currentUnit]);

  useEffect(() => {
    resetLevel();
    const handleKeyDown = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = true;

      const trySwitch = (unit: RobotUnit) => {
        if (upgrades.unlockedUnits.includes(unit)) {
          setCurrentUnit(unit);
        }
      };

      if (e.code === 'Digit1') trySwitch(RobotUnit.SENTINEL);
      if (e.code === 'Digit2') trySwitch(RobotUnit.STRIKER);
      if (e.code === 'Digit3') trySwitch(RobotUnit.FALCON);
      if (e.code === 'Digit4') trySwitch(RobotUnit.TITAN);
      if (e.code === 'Digit5') trySwitch(RobotUnit.SPECTER);
      if (e.code === 'Digit6') trySwitch(RobotUnit.VANGUARD);
      if (e.code === 'Digit7') trySwitch(RobotUnit.NIGHTSHADE);
      if (e.code === 'Digit8') trySwitch(RobotUnit.BLAZE);
      if (e.code === 'Digit9') trySwitch(RobotUnit.GLITCH);
      if (e.code === 'Digit0') trySwitch(RobotUnit.OMEGA);

      if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') {
        engineRef.current.player.isTransformed = !engineRef.current.player.isTransformed;
        setIsTransformed(engineRef.current.player.isTransformed);
      }
      if (e.code === 'KeyU') engineRef.current.player.shieldTimer = SHIELD_DURATION;
      if (e.code === 'KeyT') engineRef.current.player.unionTimer = SQUAD_UNION_DURATION;
    };
    const handleKeyUp = (e: KeyboardEvent) => { engineRef.current.keys[e.code] = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!engineRef.current.isPaused) update();
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const e = engineRef.current;
      const { player, enemies, bullets, keys } = e;
      const stats = ROBOT_STATS[e.unit];
      const currentStats = player.isTransformed ? stats.alt : stats.robot;
      e.frame++;

      if (!player.checkpoint.reached && player.pos.x > 2000) {
        player.checkpoint.reached = true;
        player.checkpoint.x = player.pos.x;
        player.checkpoint.y = player.pos.y;
        setShowCheckpoint(true);
        setTimeout(() => setShowCheckpoint(false), 3000);
      }

      player.history.unshift({ x: player.pos.x, y: player.pos.y });
      if (player.history.length > 200) player.history.pop();

      if (player.shieldTimer > 0) player.shieldTimer--;
      if (player.unionTimer > 0) player.unionTimer--;

      const ph = player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48);
      const pw = player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32);

      if (keys['ArrowRight'] || keys['KeyD']) { player.vel.x = currentStats.speed; player.facing = 1; }
      else if (keys['ArrowLeft'] || keys['KeyA']) { player.vel.x = -currentStats.speed; player.facing = -1; }
      else { player.vel.x *= 0.8; }

      if (e.unit === RobotUnit.FALCON && player.isTransformed) {
        if (keys['ArrowUp'] || keys['KeyW']) player.vel.y = -currentStats.speed;
        else if (keys['ArrowDown'] || keys['KeyS']) player.vel.y = currentStats.speed;
        else player.vel.y *= 0.9;
      } else {
        if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.grounded) {
          player.vel.y = currentStats.jump;
          player.grounded = false;
        }
        player.vel.y += GRAVITY;
      }

      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;

      const floorY = 398;
      if (player.pos.y > floorY - ph) { 
        player.pos.y = floorY - ph; 
        player.vel.y = 0; 
        player.grounded = true; 
      }
      if (player.pos.x < 0) player.pos.x = 0;
      setDistance(player.pos.x);

      const fr = Math.max(5, currentStats.fireRate - upgrades.weaponTier * 2);
      if (keys['Space'] && e.frame - player.lastShot > fr) {
        soundService.playShoot();
        const dmg = 99999; // ONE-HIT KILL DAMAGE
        bullets.push({ 
          pos: { x: player.pos.x + (player.facing === 1 ? pw : 0), y: player.pos.y + ph/2 }, 
          vel: { x: player.facing * 15, y: 0 }, 
          width: 12, height: 4, owner: 'player', health: 1, maxHealth: 1, damage: dmg, color: stats.color 
        });
        player.lastShot = e.frame;
      }

      for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i]; 
        b.pos.x += b.vel.x; 
        b.pos.y += b.vel.y;

        if (b.owner === 'enemy' && !player.invulnerable && player.shieldTimer <= 0) {
          if (b.pos.x < player.pos.x + pw && b.pos.x + b.width > player.pos.x &&
              b.pos.y < player.pos.y + ph && b.pos.y + b.height > player.pos.y) {
            setHealth(h => Math.max(0, h - (b.damage || 20))); // Player doesn't die in one hit!
            player.invulnerable = 40;
            bullets.splice(i, 1);
            soundService.playLose();
            continue;
          }
        }

        if (Math.abs(b.pos.x - player.pos.x) > 1200) bullets.splice(i, 1);
      }

      let allDead = true;
      enemies.forEach(en => {
        if (en.isDead) return;
        allDead = false;

        const dist = Math.abs(en.pos.x - player.pos.x);
        const dir = Math.sign(player.pos.x - en.pos.x);
        en.pos.x += dir * 1;

        if (dist < 600 && e.frame - en.lastShot > 100) {
          bullets.push({ 
            pos: {x: en.pos.x, y: en.pos.y + 15}, 
            vel: {x: dir * 6, y: 0}, 
            width: 10, height: 4, owner: 'enemy', health: 1, maxHealth: 1, damage: 20, color: '#f00' 
          });
          en.lastShot = e.frame;
        }

        bullets.forEach((b, idx) => {
          if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) {
            en.health = 0; // ENEMY DIES IN ONE HIT
            en.isDead = true;
            bullets.splice(idx, 1);
          }
        });
      });

      if (health <= 0) onDie();
      if (allDead) onWin();
      if (player.invulnerable > 0) player.invulnerable--;
      e.cameraX = player.pos.x - CANVAS_WIDTH/3;
      if (e.cameraX < 0) e.cameraX = 0;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const e = engineRef.current;
      ctx.fillStyle = '#050510'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
      ctx.fillStyle = '#1c1c1c'; ctx.fillRect(0, 398, CANVAS_WIDTH, 52);

      e.enemies.forEach(en => { if(!en.isDead) drawUnit(ctx, en.pos.x - e.cameraX, en.pos.y, en.width, en.height, RobotUnit.SENTINEL, Math.sign(e.player.pos.x - en.pos.x), e.frame, true); });
      const player = e.player;
      drawUnit(ctx, player.pos.x - e.cameraX, player.pos.y, player.isTransformed ? 48 : 32, player.isTransformed ? 32 : 48, e.unit, player.facing, e.frame, false, player.invulnerable > 0, player.isTransformed);
      e.bullets.forEach(b => { ctx.fillStyle = b.color || '#00f3ff'; ctx.fillRect(b.pos.x - e.cameraX, b.pos.y, b.width, b.height); });
    };

    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [resetLevel, onWin, onDie, level, upgrades, health, currentUnit]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden">
      <div className="absolute top-4 left-4 z-10 space-y-4 pointer-events-none w-[400px]">
        <div className="bg-black/80 border border-cyan-500/50 p-3 rounded backdrop-blur-md shadow-lg">
          <div className="text-[10px] text-cyan-400 font-bold uppercase mb-1 flex justify-between font-orbitron">
            <span>{ROBOT_STATS[currentUnit].name} INTEGRITY</span>
            <span>{Math.round(health)}/{Math.round(maxHealth)}</span>
          </div>
          <div className="w-48 h-2.5 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
            <div className="h-full shadow-[0_0_15px_#00f3ff] transition-all duration-300" style={{ width: `${(health / maxHealth) * 100}%`, backgroundColor: health < maxHealth * 0.3 ? '#ef4444' : '#00f3ff' }} />
          </div>
        </div>
        <div className="flex flex-wrap gap-1.5 max-w-[320px] pointer-events-auto">
          {(Object.keys(ROBOT_STATS) as RobotUnit[]).map((u, i) => {
            const isUnlocked = upgrades.unlockedUnits.includes(u);
            const isActive = currentUnit === u;
            return (
              <button key={u} disabled={!isUnlocked} onClick={() => setCurrentUnit(u)} className={`w-10 h-10 border-2 transition-all flex items-center justify-center font-orbitron font-bold ${isActive ? 'border-cyan-400 bg-cyan-900/30' : isUnlocked ? 'border-gray-700 bg-black/60' : 'border-gray-900 bg-black/20 opacity-20'}`}>
                {(i + 1) % 10}
              </button>
            );
          })}
        </div>
      </div>
      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full aspect-video shadow-2xl rounded-lg border-2 border-cyan-900/50" />
      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 pointer-events-none text-white/30 text-[8px] font-mono tracking-widest uppercase flex gap-6">
        <span>WASD: Move</span><span>Space: Fire</span><span>Shift: Transform</span><span>1-0: Squad</span>
      </div>
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const SHIELD_DURATION = 20 * 60; // 20 seconds at 60fps
const SQUAD_UNION_DURATION = 60 * 60; // 60 seconds at 60fps

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { 
    name: "SENTINEL", color: '#00f3ff', hpMult: 1.0, 
    robot: { speed: 4, jump: -11, fireRate: 15 },
    alt: { speed: 8, jump: -5, fireRate: 25, type: 'Car' }
  },
  [RobotUnit.STRIKER]: { 
    name: "STRIKER", color: '#fbbf24', hpMult: 0.8,
    robot: { speed: 6, jump: -10, fireRate: 10 },
    alt: { speed: 12, jump: -4, fireRate: 20, type: 'Bike' }
  },
  [RobotUnit.FALCON]: { 
    name: "FALCON", color: '#22d3ee', hpMult: 0.7,
    robot: { speed: 5, jump: -10, fireRate: 12 },
    alt: { speed: 7, jump: -7, fireRate: 15, type: 'Jet' }
  },
  [RobotUnit.TITAN]: { 
    name: "TITAN", color: '#ef4444', hpMult: 2.5,
    robot: { speed: 2.5, jump: -12, fireRate: 30 },
    alt: { speed: 4, jump: 0, fireRate: 20, type: 'Tank' }
  },
  [RobotUnit.SPECTER]: { 
    name: "SPECTER", color: '#a855f7', hpMult: 0.6,
    robot: { speed: 5, jump: -11, fireRate: 20 },
    alt: { speed: 6, jump: -14, fireRate: 40, type: 'Sphere' }
  },
  [RobotUnit.VANGUARD]: { 
    name: "VANGUARD", color: '#10b981', hpMult: 2.0, 
    robot: { speed: 3.5, jump: -10, fireRate: 25 },
    alt: { speed: 6, jump: -4, fireRate: 30, type: 'Shield Truck' }
  },
  [RobotUnit.NIGHTSHADE]: { 
    name: "NIGHTSHADE", color: '#6366f1', hpMult: 0.9, 
    robot: { speed: 7, jump: -13, fireRate: 12 },
    alt: { speed: 10, jump: -6, fireRate: 18, type: 'Interceptor' }
  },
  [RobotUnit.BLAZE]: { 
    name: "BLAZE", color: '#f97316', hpMult: 1.2, 
    robot: { speed: 4.5, jump: -11, fireRate: 18 },
    alt: { speed: 7, jump: -5, fireRate: 22, type: 'Rig' }
  },
  [RobotUnit.GLITCH]: { 
    name: "GLITCH", color: '#ec4899', hpMult: 1.0, 
    robot: { speed: 5, jump: -12, fireRate: 14 },
    alt: { speed: 9, jump: -12, fireRate: 16, type: 'Splicer' }
  },
  [RobotUnit.OMEGA]: { 
    name: "OMEGA", color: '#ffffff', hpMult: 3.0, 
    robot: { speed: 6, jump: -14, fireRate: 10 },
    alt: { speed: 10, jump: -8, fireRate: 15, type: 'Fortress' }
  },
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [currentUnit, setCurrentUnit] = useState<RobotUnit>(RobotUnit.SENTINEL);
  const [isTransformed, setIsTransformed] = useState(false);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [distance, setDistance] = useState(0);
  const [shieldTimeRemaining, setShieldTimeRemaining] = useState(0);
  const [unionTimeRemaining, setUnionTimeRemaining] = useState(0);
  const [showCheckpoint, setShowCheckpoint] = useState(false);

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      maxHealth: 100,
      isTransformed: false,
      shieldTimer: 0,
      unionTimer: 0,
      history: [] as {x: number, y: number}[],
      checkpoint: { x: 100, y: 300, reached: false }
    },
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    unit: RobotUnit.SENTINEL,
    level: level,
  });

  useEffect(() => { engineRef.current.isPaused = isPaused; }, [isPaused]);
  useEffect(() => { 
    engineRef.current.unit = currentUnit;
    engineRef.current.player.isTransformed = false;
    setIsTransformed(false);
  }, [currentUnit]);
  useEffect(() => { engineRef.current.level = level; }, [level]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4, border = true) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff44');
    grad.addColorStop(1, '#00000088');
    ctx.fillStyle = grad;
    ctx.fill();
    if (border) {
      ctx.strokeStyle = 'rgba(0,0,0,0.5)';
      ctx.lineWidth = 1;
      ctx.stroke();
    }
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, type = 'bot', isTransformed = false, alpha = 1, tier = 0) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8;
    const armSwing = Math.cos(time) * 10;

    let scale = 1;
    if (type === 'scout') scale = 0.8;
    if (type === 'heavy' || type === 'titan') scale = 1.4;

    if (isEnemy && isTransformed) {
      scale *= 1.25;
      ctx.translate((Math.random() - 0.5) * 3, (Math.random() - 0.5) * 3);
    }

    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(scale, scale);

    if (isEnemy && isTransformed) {
      ctx.shadowBlur = 20;
      ctx.shadowColor = '#ff3300';
    }

    // Body
    drawMechanicalPart(ctx, -12, -18, 24, 28, isTransformed ? '#400' : color, 4);

    // Chassis Evolution Visuals (Tier Upgrades)
    if (!isEnemy && tier > 0) {
      // Tier 1: Heavy Shoulders
      drawMechanicalPart(ctx, -18, -20, 10, 8, '#333', 2);
      drawMechanicalPart(ctx, 8, -20, 10, 8, '#333', 2);
      // Tier 1: Chest Core
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.arc(0, -5, 4, 0, Math.PI * 2);
      ctx.fill();
    }
    if (!isEnemy && tier > 1) {
      // Tier 2: Heavy Leg Guards
      drawMechanicalPart(ctx, -12, 12, 14, 10, '#444', 2);
      drawMechanicalPart(ctx, -2, 12, 14, 10, '#444', 2);
    }
    if (!isEnemy && tier > 2) {
      // Tier 3+: Reinforced Plating Trim
      ctx.strokeStyle = '#fff';
      ctx.lineWidth = 1.5;
      ctx.strokeRect(-12, -18, 24, 28);
    }

    // Head
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? (isTransformed ? '#fff' : '#ff0000') : '#00f3ff';
    ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);

    // Arms
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);

    // Legs
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);

    if (isEnemy && isTransformed) {
      const corePulse = Math.sin(frame * 0.4) * 3;
      ctx.fillStyle = frame % 4 < 2 ? '#ff0000' : '#ffffff';
      ctx.beginPath();
      ctx.arc(0, -5, 5 + corePulse, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.restore();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, color: string, frame: number, alpha = 1, tier = 0) => {
    ctx.save();
    ctx.globalAlpha = alpha;

    // Chassis tier visuals for vehicles
    const trimColor = tier > 2 ? '#fff' : 'transparent';
    const armorWidth = tier > 0 ? 4 : 0;

    switch(unit) {
      case RobotUnit.SENTINEL:
        drawMechanicalPart(ctx, -24 - (armorWidth/2), -10, 48 + armorWidth, 18, color, 8);
        drawMechanicalPart(ctx, -16, -20, 30, 12, '#111', 4);
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(-15, 10, 7, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(15, 10, 7, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = frame % 10 < 5 ? '#ff0000' : '#0000ff';
        ctx.fillRect(-4, -22, 10, 3);
        break;
      case RobotUnit.STRIKER:
        drawMechanicalPart(ctx, -18, -8, 36, 12, color, 4);
        drawMechanicalPart(ctx, -5, -18, 18, 12, '#222', 2);
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(-18, 8, 9, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(18, 8, 9, 0, Math.PI * 2); ctx.fill();
        break;
      case RobotUnit.FALCON:
        drawMechanicalPart(ctx, -20, -10, 40, 15, color, 12);
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(-10, -5); ctx.lineTo(-30, -15); ctx.lineTo(-10, 5); ctx.fill();
        ctx.fillStyle = '#ffaa00';
        ctx.fillRect(-28, -5, 8, 5);
        if (tier > 0) drawMechanicalPart(ctx, -15, -18, 20, 6, '#333', 2);
        break;
      case RobotUnit.TITAN:
        drawMechanicalPart(ctx, -30, -10, 60, 22, color, 4);
        drawMechanicalPart(ctx, -15, -25, 30, 15, '#222', 4);
        drawMechanicalPart(ctx, 10, -20, 25, 5, '#444', 0);
        ctx.fillStyle = '#111';
        ctx.fillRect(-28, 8, 56, 6);
        if (tier > 1) drawMechanicalPart(ctx, -25, -2, 50, 4, '#555', 0);
        break;
      case RobotUnit.SPECTER:
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.arc(0, 0, 18, 0, Math.PI * 2); ctx.fill();
        ctx.strokeStyle = tier > 0 ? '#00f3ff' : '#fff'; ctx.lineWidth = tier > 0 ? 3 : 1; ctx.stroke();
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(8, -4, 4, 0, Math.PI * 2); ctx.fill();
        break;
      default:
        drawMechanicalPart(ctx, -25, -12, 50, 24, color, 6);
        drawMechanicalPart(ctx, -10, -22, 20, 10, '#333', 2);
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(-15, 12, 8, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(15, 12, 8, 0, Math.PI * 2); ctx.fill();
        if (tier > 0) drawMechanicalPart(ctx, -30, -5, 6, 14, '#222', 2);
        break;
    }

    if (tier > 2) {
      ctx.strokeStyle = '#fff';
      ctx.lineWidth = 1;
      ctx.stroke();
    }

    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy = false, isInvuln = false, isTransformed = false, type = 'bot', alpha = 1, tier = 0) => {
    if (isInvuln && frame % 4 < 2) return;

    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    if (facing === -1) ctx.scale(-1, 1);

    const stats = ROBOT_STATS[unit];
    const color = isEnemy ? '#ff0055' : (stats?.color || '#00f3ff');

    if (isTransformed && !isEnemy) {
      drawAltMode(ctx, unit, color, frame, alpha, tier);
    } else {
      drawHumanoid(ctx, color, frame, isEnemy, type, isTransformed, alpha, tier);
    }

    ctx.restore();
  };

  const resetLevel = useCallback((fromCheckpoint = false) => {
    const e = engineRef.current;
    const stats = ROBOT_STATS[currentUnit];
    const baseHP = 100 + (upgrades.robotTier * 50);

    e.player.maxHealth = baseHP * stats.hpMult;
    e.player.shieldTimer = 0;
    e.player.unionTimer = 0;
    setShieldTimeRemaining(0);
    setUnionTimeRemaining(0);
    setMaxHealth(e.player.maxHealth);
    setHealth(e.player.maxHealth);

    if (fromCheckpoint && e.player.checkpoint.reached) {
      e.player.pos = { x: e.player.checkpoint.x, y: e.player.checkpoint.y };
    } else {
      e.player.pos = { x: 100, y: 300 };
      e.player.checkpoint.reached = false;
    }

    e.player.vel = { x: 0, y: 0 };
    e.player.invulnerable = 0;
    e.player.isTransformed = false;
    e.player.history = [];
    setIsTransformed(false);
    e.bullets = [];
    e.cameraX = e.player.pos.x - CANVAS_WIDTH/3;
    setDistance(e.player.pos.x);

    if (!fromCheckpoint) {
      const enemies: Enemy[] = [];
      const floorY = 398;
      const enemyTypes = ['bot', 'scout', 'sniper', 'heavy'];
      for (let i = 0; i < 5; i++) {
        const type = enemyTypes[i % (level < 5 ? 1 : level < 10 ? 2 : 4)];
        let w = 32, h = 48, hp = (50 + level * 15) * 4;
        if (type === 'scout') { w = 24; h = 36; hp = (40 + level * 5) * 4; }
        if (type === 'heavy') { w = 48; h = 72; hp = (150 + level * 20) * 4; }

        enemies.push({ 
          id: i, 
          pos: { x: 800 + i * 700, y: floorY - h }, 
          vel: { x: 0, y: 0 }, 
          width: w, 
          height: h, 
          health: hp, 
          maxHealth: hp, 
          isDead: false, 
          type: type, 
          lastShot: 0,
          sequenceStage: 0,
          sequenceTimer: 0,
          isTransformed: false,
          transformTimer: 0
        });
      }
      e.enemies = enemies;
    }
  }, [level, upgrades, currentUnit]);

  useEffect(() => {
    resetLevel();
    const handleKeyDown = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = true;

      const trySwitch = (unit: RobotUnit) => {
        if (upgrades.unlockedUnits.includes(unit)) {
          setCurrentUnit(unit);
        }
      };

      if (e.code === 'Digit1') trySwitch(RobotUnit.SENTINEL);
      if (e.code === 'Digit2') trySwitch(RobotUnit.STRIKER);
      if (e.code === 'Digit3') trySwitch(RobotUnit.FALCON);
      if (e.code === 'Digit4') trySwitch(RobotUnit.TITAN);
      if (e.code === 'Digit5') trySwitch(RobotUnit.SPECTER);
      if (e.code === 'Digit6') trySwitch(RobotUnit.VANGUARD);
      if (e.code === 'Digit7') trySwitch(RobotUnit.NIGHTSHADE);
      if (e.code === 'Digit8') trySwitch(RobotUnit.BLAZE);
      if (e.code === 'Digit9') trySwitch(RobotUnit.GLITCH);
      if (e.code === 'Digit0') trySwitch(RobotUnit.OMEGA);

      if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') {
        engineRef.current.player.isTransformed = !engineRef.current.player.isTransformed;
        setIsTransformed(engineRef.current.player.isTransformed);
      }
      if (e.code === 'KeyU') engineRef.current.player.shieldTimer = SHIELD_DURATION;
      if (e.code === 'KeyT') engineRef.current.player.unionTimer = SQUAD_UNION_DURATION;
    };
    const handleKeyUp = (e: KeyboardEvent) => { engineRef.current.keys[e.code] = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!engineRef.current.isPaused) update();
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const e = engineRef.current;
      const { player, enemies, bullets, keys } = e;
      const stats = ROBOT_STATS[e.unit];
      const currentStats = player.isTransformed ? stats.alt : stats.robot;
      e.frame++;

      if (!player.checkpoint.reached && player.pos.x > 2000) {
        player.checkpoint.reached = true;
        player.checkpoint.x = player.pos.x;
        player.checkpoint.y = player.pos.y;
        setShowCheckpoint(true);
        setTimeout(() => setShowCheckpoint(false), 3000);
      }

      player.history.unshift({ x: player.pos.x, y: player.pos.y });
      if (player.history.length > 200) player.history.pop();

      if (player.shieldTimer > 0) player.shieldTimer--;
      if (player.unionTimer > 0) player.unionTimer--;

      const ph = player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48);
      const pw = player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32);

      if (keys['ArrowRight'] || keys['KeyD']) { player.vel.x = currentStats.speed; player.facing = 1; }
      else if (keys['ArrowLeft'] || keys['KeyA']) { player.vel.x = -currentStats.speed; player.facing = -1; }
      else { player.vel.x *= 0.8; }

      if (e.unit === RobotUnit.FALCON && player.isTransformed) {
        if (keys['ArrowUp'] || keys['KeyW']) player.vel.y = -currentStats.speed;
        else if (keys['ArrowDown'] || keys['KeyS']) player.vel.y = currentStats.speed;
        else player.vel.y *= 0.9;
      } else {
        if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.grounded) {
          player.vel.y = currentStats.jump;
          player.grounded = false;
        }
        player.vel.y += GRAVITY;
      }

      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;

      const floorY = 398;
      if (player.pos.y > floorY - ph) { 
        player.pos.y = floorY - ph; 
        player.vel.y = 0; 
        player.grounded = true; 
      }
      if (player.pos.x < 0) player.pos.x = 0;
      setDistance(player.pos.x);

      const fr = Math.max(5, currentStats.fireRate - upgrades.weaponTier * 2);
      if (keys['Space'] && e.frame - player.lastShot > fr) {
        soundService.playShoot();
        const dmg = 99999; 
        bullets.push({ 
          pos: { x: player.pos.x + (player.facing === 1 ? pw : 0), y: player.pos.y + ph/2 }, 
          vel: { x: player.facing * 15, y: 0 }, 
          width: 12, height: 4, owner: 'player', health: 1, maxHealth: 1, damage: dmg, color: stats.color 
        });
        player.lastShot = e.frame;
      }

      for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i]; 
        b.pos.x += b.vel.x; 
        b.pos.y += b.vel.y;

        if (b.owner === 'enemy' && !player.invulnerable && player.shieldTimer <= 0) {
          if (b.pos.x < player.pos.x + pw && b.pos.x + b.width > player.pos.x &&
              b.pos.y < player.pos.y + ph && b.pos.y + b.height > player.pos.y) {
            setHealth(h => Math.max(0, h - (b.damage || 20))); 
            player.invulnerable = 40;
            bullets.splice(i, 1);
            soundService.playLose();
            continue;
          }
        }

        if (Math.abs(b.pos.x - player.pos.x) > 1200) bullets.splice(i, 1);
      }

      let allDead = true;
      enemies.forEach(en => {
        if (en.isDead) return;
        allDead = false;

        const dist = Math.abs(en.pos.x - player.pos.x);
        const dir = Math.sign(player.pos.x - en.pos.x);
        en.pos.x += dir * 1;

        if (dist < 600 && e.frame - en.lastShot > 100) {
          bullets.push({ 
            pos: {x: en.pos.x, y: en.pos.y + 15}, 
            vel: {x: dir * 6, y: 0}, 
            width: 10, height: 4, owner: 'enemy', health: 1, maxHealth: 1, damage: 20, color: '#f00' 
          });
          en.lastShot = e.frame;
        }

        bullets.forEach((b, idx) => {
          if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) {
            en.health = 0; 
            en.isDead = true;
            bullets.splice(idx, 1);
          }
        });
      });

      if (health <= 0) onDie();
      if (allDead) onWin();
      if (player.invulnerable > 0) player.invulnerable--;
      e.cameraX = player.pos.x - CANVAS_WIDTH/3;
      if (e.cameraX < 0) e.cameraX = 0;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const e = engineRef.current;
      ctx.fillStyle = '#050510'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
      ctx.fillStyle = '#1c1c1c'; ctx.fillRect(0, 398, CANVAS_WIDTH, 52);

      e.enemies.forEach(en => { if(!en.isDead) drawUnit(ctx, en.pos.x - e.cameraX, en.pos.y, en.width, en.height, RobotUnit.SENTINEL, Math.sign(e.player.pos.x - en.pos.x), e.frame, true, false, false, en.type); });
      const player = e.player;
      drawUnit(ctx, player.pos.x - e.cameraX, player.pos.y, player.isTransformed ? 48 : 32, player.isTransformed ? 32 : 48, e.unit, player.facing, e.frame, false, player.invulnerable > 0, player.isTransformed, 'bot', 1, upgrades.robotTier);
      e.bullets.forEach(b => { ctx.fillStyle = b.color || '#00f3ff'; ctx.fillRect(b.pos.x - e.cameraX, b.pos.y, b.width, b.height); });
    };

    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [resetLevel, onWin, onDie, level, upgrades, health, currentUnit]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden">
      <div className="absolute top-4 left-4 z-10 space-y-4 pointer-events-none w-[400px]">
        <div className="bg-black/80 border border-cyan-500/50 p-3 rounded backdrop-blur-md shadow-lg">
          <div className="text-[10px] text-cyan-400 font-bold uppercase mb-1 flex justify-between font-orbitron">
            <span>{ROBOT_STATS[currentUnit].name} INTEGRITY [TIER {upgrades.robotTier}]</span>
            <span>{Math.round(health)}/{Math.round(maxHealth)}</span>
          </div>
          <div className="w-48 h-2.5 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
            <div className="h-full shadow-[0_0_15px_#00f3ff] transition-all duration-300" style={{ width: `${(health / maxHealth) * 100}%`, backgroundColor: health < maxHealth * 0.3 ? '#ef4444' : '#00f3ff' }} />
          </div>
        </div>
        <div className="flex flex-wrap gap-1.5 max-w-[320px] pointer-events-auto">
          {(Object.keys(ROBOT_STATS) as RobotUnit[]).map((u, i) => {
            const isUnlocked = upgrades.unlockedUnits.includes(u);
            const isActive = currentUnit === u;
            return (
              <button key={u} disabled={!isUnlocked} onClick={() => setCurrentUnit(u)} className={`w-10 h-10 border-2 transition-all flex items-center justify-center font-orbitron font-bold ${isActive ? 'border-cyan-400 bg-cyan-900/30' : isUnlocked ? 'border-gray-700 bg-black/60' : 'border-gray-900 bg-black/20 opacity-20'}`}>
                {(i + 1) % 10}
              </button>
            );
          })}
        </div>
      </div>
      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full aspect-video shadow-2xl rounded-lg border-2 border-cyan-900/50" />
      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 pointer-events-none text-white/30 text-[8px] font-mono tracking-widest uppercase flex gap-6">
        <span>WASD: Move</span><span>Space: Fire</span><span>Shift: Transform</span><span>1-0: Squad</span>
      </div>
    </div>
  );
};

