const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [currentUnit, setCurrentUnit] = useState<RobotUnit>(RobotUnit.SENTINEL);
  const [isTransformed, setIsTransformed] = useState(false);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [distance, setDistance] = useState(0);
  const [shieldTimeRemaining, setShieldTimeRemaining] = useState(0);
  const [unionTimeRemaining, setUnionTimeRemaining] = useState(0);
  const [showCheckpoint, setShowCheckpoint] = useState(false);

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      maxHealth: 100,
      isTransformed: false,
      shieldTimer: 0,
      unionTimer: 0,
      history: [] as {x: number, y: number}[],
      checkpoint: { x: 100, y: 300, reached: false }
    },
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    unit: RobotUnit.SENTINEL,
    level: level,
  });

  useEffect(() => { engineRef.current.isPaused = isPaused; }, [isPaused]);
  useEffect(() => { 
    engineRef.current.unit = currentUnit;
    engineRef.current.player.isTransformed = false;
    setIsTransformed(false);
  }, [currentUnit]);
  useEffect(() => { engineRef.current.level = level; }, [level]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4, border = true) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff44');
    grad.addColorStop(1, '#00000088');
    ctx.fillStyle = grad;
    ctx.fill();
    if (border) {
      ctx.strokeStyle = 'rgba(0,0,0,0.5)';
      ctx.lineWidth = 1;
      ctx.stroke();
    }
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, type = 'bot', isTransformed = false, alpha = 1, tier = 0) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8;
    const armSwing = Math.cos(time) * 10;

    let scale = 1;
    if (type === 'scout') scale = 0.8;
    if (type === 'heavy' || type === 'titan') scale = 1.4;

    if (isEnemy && isTransformed) {
      scale *= 1.25;
      ctx.translate((Math.random() - 0.5) * 3, (Math.random() - 0.5) * 3);
    }

    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(scale, scale);

    if (isEnemy && isTransformed) {
      ctx.shadowBlur = 20;
      ctx.shadowColor = '#ff3300';
    }

    drawMechanicalPart(ctx, -12, -18, 24, 28, isTransformed ? '#400' : color, 4);

    if (!isEnemy && tier > 0) {
      drawMechanicalPart(ctx, -18, -20, 10, 8, '#333', 2);
      drawMechanicalPart(ctx, 8, -20, 10, 8, '#333', 2);
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.arc(0, -5, 4, 0, Math.PI * 2);
      ctx.fill();
    }
    if (!isEnemy && tier > 1) {
      drawMechanicalPart(ctx, -12, 12, 14, 10, '#444', 2);
      drawMechanicalPart(ctx, -2, 12, 14, 10, '#444', 2);
    }
    if (!isEnemy && tier > 2) {
      ctx.strokeStyle = '#fff';
      ctx.lineWidth = 1.5;
      ctx.strokeRect(-12, -18, 24, 28);
    }

    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? (isTransformed ? '#fff' : '#ff0000') : '#00f3ff';
    ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);

    if (isEnemy && isTransformed) {
      const corePulse = Math.sin(frame * 0.4) * 3;
      ctx.fillStyle = frame % 4 < 2 ? '#ff0000' : '#ffffff';
      ctx.beginPath();
      ctx.arc(0, -5, 5 + corePulse, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.restore();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, color: string, frame: number, alpha = 1, tier = 0) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    const armorWidth = tier > 0 ? 4 : 0;

    switch(unit) {
      case RobotUnit.SENTINEL:
        drawMechanicalPart(ctx, -24 - (armorWidth/2), -10, 48 + armorWidth, 18, color, 8);
        drawMechanicalPart(ctx, -16, -20, 30, 12, '#111', 4);
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(-15, 10, 7, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(15, 10, 7, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = frame % 10 < 5 ? '#ff0000' : '#0000ff';
        ctx.fillRect(-4, -22, 10, 3);
        break;
      case RobotUnit.STRIKER:
        drawMechanicalPart(ctx, -18, -8, 36, 12, color, 4);
        drawMechanicalPart(ctx, -5, -18, 18, 12, '#222', 2);
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(-18, 8, 9, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(18, 8, 9, 0, Math.PI * 2); ctx.fill();
        break;
      case RobotUnit.FALCON:
        drawMechanicalPart(ctx, -20, -10, 40, 15, color, 12);
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(-10, -5); ctx.lineTo(-30, -15); ctx.lineTo(-10, 5); ctx.fill();
        ctx.fillStyle = '#ffaa00';
        ctx.fillRect(-28, -5, 8, 5);
        if (tier > 0) drawMechanicalPart(ctx, -15, -18, 20, 6, '#333', 2);
        break;
      case RobotUnit.TITAN:
        drawMechanicalPart(ctx, -30, -10, 60, 22, color, 4);
        drawMechanicalPart(ctx, -15, -25, 30, 15, '#222', 4);
        drawMechanicalPart(ctx, 10, -20, 25, 5, '#444', 0);
        ctx.fillStyle = '#111';
        ctx.fillRect(-28, 8, 56, 6);
        if (tier > 1) drawMechanicalPart(ctx, -25, -2, 50, 4, '#555', 0);
        break;
      case RobotUnit.SPECTER:
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.arc(0, 0, 18, 0, Math.PI * 2); ctx.fill();
        ctx.strokeStyle = tier > 0 ? '#00f3ff' : '#fff'; ctx.lineWidth = tier > 0 ? 3 : 1; ctx.stroke();
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(8, -4, 4, 0, Math.PI * 2); ctx.fill();
        break;
      default:
        drawMechanicalPart(ctx, -25, -12, 50, 24, color, 6);
        drawMechanicalPart(ctx, -10, -22, 20, 10, '#333', 2);
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.arc(-15, 12, 8, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(15, 12, 8, 0, Math.PI * 2); ctx.fill();
        if (tier > 0) drawMechanicalPart(ctx, -30, -5, 6, 14, '#222', 2);
        break;
    }

    if (tier > 2) {
      ctx.strokeStyle = '#fff';
      ctx.lineWidth = 1;
      ctx.stroke();
    }

    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy = false, isInvuln = false, isTransformed = false, type = 'bot', alpha = 1, tier = 0) => {
    if (isInvuln && frame % 4 < 2) return;

    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    if (facing === -1) ctx.scale(-1, 1);

    const stats = ROBOT_STATS[unit];
    const color = isEnemy ? '#ff0055' : (stats?.color || '#00f3ff');

    if (isTransformed && !isEnemy) {
      drawAltMode(ctx, unit, color, frame, alpha, tier);
    } else {
      drawHumanoid(ctx, color, frame, isEnemy, type, isTransformed, alpha, tier);
    }

    ctx.restore();
  };

  const resetLevel = useCallback((fromCheckpoint = false) => {
    const e = engineRef.current;
    const stats = ROBOT_STATS[currentUnit];
    const baseHP = 100 + (upgrades.robotTier * 50);

    e.player.maxHealth = baseHP * stats.hpMult;
    e.player.shieldTimer = 0;
    e.player.unionTimer = 0;
    setShieldTimeRemaining(0);
    setUnionTimeRemaining(0);
    setMaxHealth(e.player.maxHealth);
    setHealth(e.player.maxHealth);

    if (fromCheckpoint && e.player.checkpoint.reached) {
      e.player.pos = { x: e.player.checkpoint.x, y: e.player.checkpoint.y };
    } else {
      e.player.pos = { x: 100, y: 300 };
      e.player.checkpoint.reached = false;
    }

    e.player.vel = { x: 0, y: 0 };
    e.player.invulnerable = 0;
    e.player.isTransformed = false;
    e.player.history = [];
    setIsTransformed(false);
    e.bullets = [];
    e.cameraX = e.player.pos.x - CANVAS_WIDTH/3;
    setDistance(e.player.pos.x);

    if (!fromCheckpoint) {
      const enemies: Enemy[] = [];
      const floorY = 398;

      if (level === 5) {
        // Special Tank-former Battalion for Level 5
        for (let i = 0; i < 5; i++) {
           const hp = 800;
           enemies.push({ 
             id: i, 
             pos: { x: 1000 + i * 800, y: floorY - 72 }, 
             vel: { x: 0, y: 0 }, 
             width: 48, height: 72, 
             health: hp, maxHealth: hp, 
             isDead: false, type: 'heavy', 
             lastShot: 0, isTransformed: true // Level 5 enemies are ALWAYS transformed "Tank-formers"
           });
        }
      } else {
        const enemyTypes = ['bot', 'scout', 'sniper', 'heavy'];
        for (let i = 0; i < 5; i++) {
          const type = enemyTypes[i % (level < 5 ? 1 : level < 10 ? 2 : 4)];
          let w = 32, h = 48, hp = (50 + level * 15) * 4;
          if (type === 'scout') { w = 24; h = 36; hp = (40 + level * 5) * 4; }
          if (type === 'heavy') { w = 48; h = 72; hp = (150 + level * 20) * 4; }

          enemies.push({ 
            id: i, 
            pos: { x: 800 + i * 700, y: floorY - h }, 
            vel: { x: 0, y: 0 }, 
            width: w, 
            height: h, 
            health: hp, 
            maxHealth: hp, 
            isDead: false, 
            type: type, 
            lastShot: 0,
            sequenceStage: 0,
            sequenceTimer: 0,
            isTransformed: false,
            transformTimer: 0
          });
        }
      }
      e.enemies = enemies;
    }
  }, [level, upgrades, currentUnit]);

  useEffect(() => {
    resetLevel();
    const handleKeyDown = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = true;

      const trySwitch = (unit: RobotUnit) => {
        if (upgrades.unlockedUnits.includes(unit)) {
          setCurrentUnit(unit);
        }
      };

      if (e.code === 'Digit1') trySwitch(RobotUnit.SENTINEL);
      if (e.code === 'Digit2') trySwitch(RobotUnit.STRIKER);
      if (e.code === 'Digit3') trySwitch(RobotUnit.FALCON);
      if (e.code === 'Digit4') trySwitch(RobotUnit.TITAN);
      if (e.code === 'Digit5') trySwitch(RobotUnit.SPECTER);
      if (e.code === 'Digit6') trySwitch(RobotUnit.VANGUARD);
      if (e.code === 'Digit7') trySwitch(RobotUnit.NIGHTSHADE);
      if (e.code === 'Digit8') trySwitch(RobotUnit.BLAZE);
      if (e.code === 'Digit9') trySwitch(RobotUnit.GLITCH);
      if (e.code === 'Digit0') trySwitch(RobotUnit.OMEGA);

      if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') {
        engineRef.current.player.isTransformed = !engineRef.current.player.isTransformed;
        setIsTransformed(engineRef.current.player.isTransformed);
      }
      if (e.code === 'KeyU') engineRef.current.player.shieldTimer = SHIELD_DURATION;
      if (e.code === 'KeyT') engineRef.current.player.unionTimer = SQUAD_UNION_DURATION;
    };
    const handleKeyUp = (e: KeyboardEvent) => { engineRef.current.keys[e.code] = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!engineRef.current.isPaused) update();
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const e = engineRef.current;
      const { player, enemies, bullets, keys } = e;
      const stats = ROBOT_STATS[e.unit];
      const currentStats = player.isTransformed ? stats.alt : stats.robot;
      e.frame++;

      if (!player.checkpoint.reached && player.pos.x > 2000) {
        player.checkpoint.reached = true;
        player.checkpoint.x = player.pos.x;
        player.checkpoint.y = player.pos.y;
        setShowCheckpoint(true);
        setTimeout(() => setShowCheckpoint(false), 3000);
      }

      player.history.unshift({ x: player.pos.x, y: player.pos.y });
      if (player.history.length > 200) player.history.pop();

      if (player.shieldTimer > 0) player.shieldTimer--;
      if (player.unionTimer > 0) player.unionTimer--;

      const ph = player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48);
      const pw = player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32);

      if (keys['ArrowRight'] || keys['KeyD']) { player.vel.x = currentStats.speed; player.facing = 1; }
      else if (keys['ArrowLeft'] || keys['KeyA']) { player.vel.x = -currentStats.speed; player.facing = -1; }
      else { player.vel.x *= 0.8; }

      if (e.unit === RobotUnit.FALCON && player.isTransformed) {
        if (keys['ArrowUp'] || keys['KeyW']) player.vel.y = -currentStats.speed;
        else if (keys['ArrowDown'] || keys['KeyS']) player.vel.y = currentStats.speed;
        else player.vel.y *= 0.9;
      } else {
        if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.grounded) {
          player.vel.y = currentStats.jump;
          player.grounded = false;
        }
        player.vel.y += GRAVITY;
      }

      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;

      const floorY = 398;
      if (player.pos.y > floorY - ph) { 
        player.pos.y = floorY - ph; 
        player.vel.y = 0; 
        player.grounded = true; 
      }
      if (player.pos.x < 0) player.pos.x = 0;
      setDistance(player.pos.x);

      const fr = Math.max(5, currentStats.fireRate - upgrades.weaponTier * 2);
      if (keys['Space'] && e.frame - player.lastShot > fr) {
        soundService.playShoot();
        const dmg = 99999; 
        bullets.push({ 
          pos: { x: player.pos.x + (player.facing === 1 ? pw : 0), y: player.pos.y + ph/2 }, 
          vel: { x: player.facing * 15, y: 0 }, 
          width: 12, height: 4, owner: 'player', health: 1, maxHealth: 1, damage: dmg, color: stats.color 
        });
        player.lastShot = e.frame;
      }

      for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i]; 
        b.pos.x += b.vel.x; 
        b.pos.y += b.vel.y;

        if (b.owner === 'enemy' && !player.invulnerable && player.shieldTimer <= 0) {
          if (b.pos.x < player.pos.x + pw && b.pos.x + b.width > player.pos.x &&
              b.pos.y < player.pos.y + ph && b.pos.y + b.height > player.pos.y) {
            setHealth(h => Math.max(0, h - (b.damage || 20))); 
            player.invulnerable = 40;
            bullets.splice(i, 1);
            soundService.playLose();
            continue;
          }
        }

        if (Math.abs(b.pos.x - player.pos.x) > 1200) bullets.splice(i, 1);
      }

      let allDead = true;
      enemies.forEach(en => {
        if (en.isDead) return;
        allDead = false;

        const dist = Math.abs(en.pos.x - player.pos.x);
        const dir = Math.sign(player.pos.x - en.pos.x);
        en.pos.x += dir * (level === 5 ? 0.5 : 1); // Level 5 tanks are slower but more dangerous

        if (dist < 600 && e.frame - en.lastShot > 100) {
          bullets.push({ 
            pos: {x: en.pos.x, y: en.pos.y + 15}, 
            vel: {x: dir * (level === 5 ? 8 : 6), y: 0}, 
            width: level === 5 ? 16 : 10, 
            height: level === 5 ? 6 : 4, 
            owner: 'enemy', health: 1, maxHealth: 1, 
            damage: level === 5 ? 30 : 20, 
            color: '#f00' 
          });
          en.lastShot = e.frame;
        }

        bullets.forEach((b, idx) => {
          if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) {
            en.health = 0; 
            en.isDead = true;
            bullets.splice(idx, 1);
          }
        });
      });

      if (health <= 0) onDie();
      if (allDead) onWin();
      if (player.invulnerable > 0) player.invulnerable--;
      e.cameraX = player.pos.x - CANVAS_WIDTH/3;
      if (e.cameraX < 0) e.cameraX = 0;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const e = engineRef.current;
      ctx.fillStyle = '#050510'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
      ctx.fillStyle = '#1c1c1c'; ctx.fillRect(0, 398, CANVAS_WIDTH, 52);

      e.enemies.forEach(en => { if(!en.isDead) drawUnit(ctx, en.pos.x - e.cameraX, en.pos.y, en.width, en.height, RobotUnit.SENTINEL, Math.sign(e.player.pos.x - en.pos.x), e.frame, true, false, en.isTransformed, en.type); });
      const player = e.player;
      drawUnit(ctx, player.pos.x - e.cameraX, player.pos.y, player.isTransformed ? 48 : 32, player.isTransformed ? 32 : 48, e.unit, player.facing, e.frame, false, player.invulnerable > 0, player.isTransformed, 'bot', 1, upgrades.robotTier);
      e.bullets.forEach(b => { ctx.fillStyle = b.color || '#00f3ff'; ctx.fillRect(b.pos.x - e.cameraX, b.pos.y, b.width, b.height); });
    };

    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [resetLevel, onWin, onDie, level, upgrades, health, currentUnit]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden">
      <div className="absolute top-4 left-4 z-10 space-y-4 pointer-events-none w-[400px]">
        <div className="bg-black/80 border border-cyan-500/50 p-3 rounded backdrop-blur-md shadow-lg">
          <div className="text-[10px] text-cyan-400 font-bold uppercase mb-1 flex justify-between font-orbitron">
            <span>{ROBOT_STATS[currentUnit].name} INTEGRITY [TIER {upgrades.robotTier}]</span>
            <span>{Math.round(health)}/{Math.round(maxHealth)}</span>
          </div>
          <div className="w-48 h-2.5 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
            <div className="h-full shadow-[0_0_15px_#00f3ff] transition-all duration-300" style={{ width: `${(health / maxHealth) * 100}%`, backgroundColor: health < maxHealth * 0.3 ? '#ef4444' : '#00f3ff' }} />
          </div>
        </div>
        <div className="flex flex-wrap gap-1.5 max-w-[320px] pointer-events-auto">
          {(Object.keys(ROBOT_STATS) as RobotUnit[]).map((u, i) => {
            const isUnlocked = upgrades.unlockedUnits.includes(u);
            const isActive = currentUnit === u;
            return (
              <button key={u} disabled={!isUnlocked} onClick={() => setCurrentUnit(u)} className={`w-10 h-10 border-2 transition-all flex items-center justify-center font-orbitron font-bold ${isActive ? 'border-cyan-400 bg-cyan-900/30' : isUnlocked ? 'border-gray-700 bg-black/60' : 'border-gray-900 bg-black/20 opacity-20'}`}>
                {(i + 1) % 10}
              </button>
            );
          })}
        </div>
      </div>
      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full aspect-video shadow-2xl rounded-lg border-2 border-cyan-900/50" />
      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 pointer-events-none text-white/30 text-[8px] font-mono tracking-widest uppercase flex gap-6">
        <span>WASD: Move</span><span>Space: Fire</span><span>Shift: Transform</span><span>1-0: Squad</span>
      </div>
    </div>
  );
};

export default GameView;

export enum GameState {
  MENU = 'MENU',
  BRIEFING = 'BRIEFING',
  PLAYING = 'PLAYING',
  PAUSED = 'PAUSED',
  GAMEOVER = 'GAMEOVER',
  VICTORY = 'VICTORY',
  LEVEL_COMPLETE = 'LEVEL_COMPLETE',
  SHOP = 'SHOP',
  ROBOT_SHOP = 'ROBOT_SHOP',
  LEVEL_SELECT = 'LEVEL_SELECT'
}

export enum RobotUnit {
  SENTINEL = 'SENTINEL',
  STRIKER = 'STRIKER',
  FALCON = 'FALCON',
  TITAN = 'TITAN',
  SPECTER = 'SPECTER',
  VANGUARD = 'VANGUARD',
  NIGHTSHADE = 'NIGHTSHADE',
  BLAZE = 'BLAZE',
  GLITCH = 'GLITCH',
  OMEGA = 'OMEGA'
}

export interface LevelInfo {
  level: number;
  title: string;
  description: string;
  threatLevel: string;
  enemyType: string;
}

export interface Upgrades {
  robotTier: number;
  weaponTier: number;
  unlockedUnits: RobotUnit[];
}

export interface Vector {
  x: number;
  y: number;
}

export interface Entity {
  pos: Vector;
  vel: Vector;
  width: number;
  height: number;
  health: number;
  maxHealth: number;
}

export interface Bullet extends Entity {
  owner: 'player' | 'enemy';
  damage?: number;
  color?: string;
}

export interface Enemy extends Entity {
  id: number;
  isDead: boolean;
  type: string;
  lastShot: number;
  hasSplit?: boolean;
  sequenceStage?: number;
  sequenceTimer?: number;
  isTransformed?: boolean;
  transformTimer?: number;
  unit?: RobotUnit;
}

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const SHIELD_DURATION = 20 * 60; // 20 seconds at 60fps
const SQUAD_UNION_DURATION = 60 * 60; // 60 seconds at 60fps

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { 
    name: "SENTINEL", color: '#00f3ff', hpMult: 1.0, 
    robot: { speed: 4, jump: -11, fireRate: 15 },
    alt: { speed: 8, jump: -5, fireRate: 25, type: 'Car' }
  },
  [RobotUnit.STRIKER]: { 
    name: "STRIKER", color: '#fbbf24', hpMult: 0.8,
    robot: { speed: 6, jump: -10, fireRate: 10 },
    alt: { speed: 12, jump: -4, fireRate: 20, type: 'Bike' }
  },
  [RobotUnit.FALCON]: { 
    name: "FALCON", color: '#22d3ee', hpMult: 0.7,
    robot: { speed: 5, jump: -10, fireRate: 12 },
    alt: { speed: 7, jump: -7, fireRate: 15, type: 'Jet' }
  },
  [RobotUnit.TITAN]: { 
    name: "TITAN", color: '#ef4444', hpMult: 2.5,
    robot: { speed: 2.5, jump: -12, fireRate: 30 },
    alt: { speed: 4, jump: 0, fireRate: 20, type: 'Tank' }
  },
  [RobotUnit.SPECTER]: { 
    name: "SPECTER", color: '#a855f7', hpMult: 0.6,
    robot: { speed: 5, jump: -11, fireRate: 20 },
    alt: { speed: 6, jump: -14, fireRate: 40, type: 'Sphere' }
  },
  [RobotUnit.VANGUARD]: { 
    name: "VANGUARD", color: '#10b981', hpMult: 2.0, 
    robot: { speed: 3.5, jump: -10, fireRate: 25 },
    alt: { speed: 6, jump: -4, fireRate: 30, type: 'Shield Truck' }
  },
  [RobotUnit.NIGHTSHADE]: { 
    name: "NIGHTSHADE", color: '#6366f1', hpMult: 0.9, 
    robot: { speed: 7, jump: -13, fireRate: 12 },
    alt: { speed: 10, jump: -6, fireRate: 18, type: 'Interceptor' }
  },
  [RobotUnit.BLAZE]: { 
    name: "BLAZE", color: '#f97316', hpMult: 1.2, 
    robot: { speed: 4.5, jump: -11, fireRate: 18 },
    alt: { speed: 7, jump: -5, fireRate: 22, type: 'Rig' }
  },
  [RobotUnit.GLITCH]: { 
    name: "GLITCH", color: '#ec4899', hpMult: 1.0, 
    robot: { speed: 5, jump: -12, fireRate: 14 },
    alt: { speed: 9, jump: -12, fireRate: 16, type: 'Splicer' }
  },
  [RobotUnit.OMEGA]: { 
    name: "OMEGA", color: '#ffffff', hpMult: 3.0, 
    robot: { speed: 6, jump: -14, fireRate: 10 },
    alt: { speed: 10, jump: -8, fireRate: 15, type: 'Fortress' }
  },
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [currentUnit, setCurrentUnit] = useState<RobotUnit>(RobotUnit.SENTINEL);
  const [isTransformed, setIsTransformed] = useState(false);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [distance, setDistance] = useState(0);

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      maxHealth: 100,
      isTransformed: false,
      history: [] as {x: number, y: number}[],
      checkpoint: { x: 100, y: 300, reached: false }
    },
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    unit: RobotUnit.SENTINEL,
    level: level,
  });

  useEffect(() => { engineRef.current.isPaused = isPaused; }, [isPaused]);
  useEffect(() => { 
    engineRef.current.unit = currentUnit;
    engineRef.current.player.isTransformed = false;
    setIsTransformed(false);
  }, [currentUnit]);
  useEffect(() => { engineRef.current.level = level; }, [level]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4, border = true) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff66');
    grad.addColorStop(1, '#000000aa');
    ctx.fillStyle = grad;
    ctx.fill();
    if (border) {
      ctx.strokeStyle = 'rgba(0,0,0,0.6)';
      ctx.lineWidth = 1;
      ctx.stroke();
    }
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, type = 'bot', isTransformed = false, alpha = 1, tier = 0) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8;
    const armSwing = Math.cos(time) * 10;

    let scale = 1;
    if (type === 'scout') scale = 0.8;
    if (type === 'heavy' || type === 'titan') scale = 1.4;

    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(scale, scale);

    // Body
    drawMechanicalPart(ctx, -12, -18, 24, 28, color, 4);

    // Chassis Evolution Visuals
    if (!isEnemy && tier > 0) {
      // Tier 1: Heavy Shoulder Guards
      drawMechanicalPart(ctx, -18, -22, 12, 10, '#333', 2);
      drawMechanicalPart(ctx, 6, -22, 12, 10, '#333', 2);
      // Glowing Reactor Core
      ctx.fillStyle = '#fff';
      ctx.shadowBlur = 10;
      ctx.shadowColor = color;
      ctx.beginPath();
      ctx.arc(0, -6, 4, 0, Math.PI * 2);
      ctx.fill();
      ctx.shadowBlur = 0;
    }
    if (!isEnemy && tier > 1) {
      // Tier 2: Armored Knee Plates & Gauntlets
      drawMechanicalPart(ctx, -14, 10, 8, 8, '#444', 1);
      drawMechanicalPart(ctx, 6, 10, 8, 8, '#444', 1);
      drawMechanicalPart(ctx, -20, -10, 6, 12, '#555', 1);
      drawMechanicalPart(ctx, 14, -10, 6, 12, '#555', 1);
    }
    if (!isEnemy && tier > 2) {
      // Tier 3+: Heavy Helmet Crest and Back Wings
      drawMechanicalPart(ctx, -4, -38, 8, 10, color, 2);
      ctx.fillStyle = '#00f3ff';
      ctx.beginPath();
      ctx.moveTo(-20, -15); ctx.lineTo(-35, -35); ctx.lineTo(-20, -5); ctx.fill();
      ctx.beginPath();
      ctx.moveTo(20, -15); ctx.lineTo(35, -35); ctx.lineTo(20, -5); ctx.fill();
    }

    // Head
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? '#ff0000' : '#00f3ff';
    ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);

    // Arms
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);

    // Legs
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);

    ctx.restore();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, color: string, frame: number, alpha = 1, tier = 0) => {
    ctx.save();
    ctx.globalAlpha = alpha;

    switch(unit) {
      case RobotUnit.SENTINEL:
        // Enhanced Police Car
        drawMechanicalPart(ctx, -28, -10, 56, 20, color, 8);
        drawMechanicalPart(ctx, -18, -22, 36, 14, '#111', 4);
        // Siren Light Bar
        ctx.fillStyle = frame % 10 < 5 ? '#ff0000' : '#0000ff';
        ctx.fillRect(-6, -24, 12, 4);
        // Wheels
        ctx.fillStyle = '#111';
        ctx.beginPath(); ctx.arc(-18, 12, 8, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(18, 12, 8, 0, Math.PI * 2); ctx.fill();
        // Headlights
        ctx.fillStyle = '#ffffaa';
        ctx.fillRect(20, -4, 8, 6);
        // Police Trim
        if (tier > 0) {
          ctx.fillStyle = '#fff';
          ctx.fillRect(-20, -6, 40, 4);
        }
        break;
      case RobotUnit.TITAN:
        // Heavy Tank
        drawMechanicalPart(ctx, -35, -8, 70, 24, color, 4);
        drawMechanicalPart(ctx, -18, -26, 36, 18, '#222', 4);
        // Cannon
        drawMechanicalPart(ctx, 12, -22, 30, 8, '#444', 1);
        // Treads
        ctx.fillStyle = '#111';
        ctx.fillRect(-33, 10, 66, 8);
        for(let i = -30; i < 30; i += 10) {
          ctx.strokeStyle = '#333';
          ctx.strokeRect(i, 10, 8, 8);
        }
        break;
      case RobotUnit.FALCON:
        drawMechanicalPart(ctx, -24, -8, 48, 16, color, 12);
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(-10, -5); ctx.lineTo(-40, -20); ctx.lineTo(-10, 10); ctx.fill();
        ctx.fillStyle = '#ffaa00';
        ctx.fillRect(-35, -5, 10, 6);
        break;
      default:
        drawMechanicalPart(ctx, -25, -12, 50, 24, color, 6);
        drawMechanicalPart(ctx, -10, -22, 20, 10, '#333', 2);
        break;
    }

    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy = false, isInvuln = false, isTransformed = false, type = 'bot', alpha = 1, tier = 0) => {
    if (isInvuln && frame % 4 < 2) return;

    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    if (facing === -1) ctx.scale(-1, 1);

    const stats = ROBOT_STATS[unit];
    const color = isEnemy ? '#ff0055' : (stats?.color || '#00f3ff');

    if (isTransformed) {
      drawAltMode(ctx, unit, color, frame, alpha, tier);
    } else {
      drawHumanoid(ctx, color, frame, isEnemy, type, isTransformed, alpha, tier);
    }

    ctx.restore();
  };

  const resetLevel = useCallback((fromCheckpoint = false) => {
    const e = engineRef.current;
    const stats = ROBOT_STATS[currentUnit];
    const baseHP = 100 + (upgrades.robotTier * 50);

    e.player.maxHealth = baseHP * stats.hpMult;
    setMaxHealth(e.player.maxHealth);
    setHealth(e.player.maxHealth);

    if (fromCheckpoint && e.player.checkpoint.reached) {
      e.player.pos = { x: e.player.checkpoint.x, y: e.player.checkpoint.y };
    } else {
      e.player.pos = { x: 100, y: 300 };
      e.player.checkpoint.reached = false;
    }

    e.player.vel = { x: 0, y: 0 };
    e.player.invulnerable = 0;
    e.player.isTransformed = false;
    setIsTransformed(false);
    e.bullets = [];
    e.cameraX = e.player.pos.x - CANVAS_WIDTH/3;

    const enemies: Enemy[] = [];
    const floorY = 398;

    if (level === 5) {
      // Level 5 Tank-former Battalion
      for (let i = 0; i < 5; i++) {
        enemies.push({ 
          id: i, 
          pos: { x: 1200 + i * 900, y: floorY - 32 }, 
          vel: { x: 0, y: 0 }, 
          width: 70, height: 40, 
          health: 1000, maxHealth: 1000, 
          isDead: false, type: 'heavy', 
          lastShot: 0, 
          isTransformed: true, 
          unit: RobotUnit.TITAN 
        });
      }
    } else {
      const enemyTypes = ['bot', 'scout', 'sniper', 'heavy'];
      for (let i = 0; i < 5; i++) {
        const type = enemyTypes[i % (level < 5 ? 1 : level < 10 ? 2 : 4)];
        let w = 32, h = 48;
        if (type === 'scout') { w = 24; h = 36; }
        if (type === 'heavy') { w = 48; h = 72; }
        enemies.push({ 
          id: i, 
          pos: { x: 800 + i * 800, y: floorY - h }, 
          vel: { x: 0, y: 0 }, 
          width: w, height: h, 
          health: 100, maxHealth: 100, 
          isDead: false, type: type, 
          lastShot: 0, 
          unit: RobotUnit.SENTINEL 
        });
      }
    }
    e.enemies = enemies;
  }, [level, upgrades, currentUnit]);

  useEffect(() => {
    resetLevel();
    const handleKeyDown = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = true;
      if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') {
        engineRef.current.player.isTransformed = !engineRef.current.player.isTransformed;
        setIsTransformed(engineRef.current.player.isTransformed);
      }

      const trySwitch = (unit: RobotUnit) => {
        if (upgrades.unlockedUnits.includes(unit)) setCurrentUnit(unit);
      };
      if (e.code === 'Digit1') trySwitch(RobotUnit.SENTINEL);
      if (e.code === 'Digit2') trySwitch(RobotUnit.STRIKER);
      if (e.code === 'Digit3') trySwitch(RobotUnit.FALCON);
      if (e.code === 'Digit4') trySwitch(RobotUnit.TITAN);
      if (e.code === 'Digit5') trySwitch(RobotUnit.SPECTER);
    };
    const handleKeyUp = (e: KeyboardEvent) => { engineRef.current.keys[e.code] = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!engineRef.current.isPaused) update();
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const e = engineRef.current;
      const { player, enemies, bullets, keys } = e;
      const stats = ROBOT_STATS[e.unit];
      const currentStats = player.isTransformed ? stats.alt : stats.robot;
      e.frame++;

      const ph = player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48);
      const pw = player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32);

      if (keys['ArrowRight'] || keys['KeyD']) { player.vel.x = currentStats.speed; player.facing = 1; }
      else if (keys['ArrowLeft'] || keys['KeyA']) { player.vel.x = -currentStats.speed; player.facing = -1; }
      else { player.vel.x *= 0.8; }

      if (e.unit === RobotUnit.FALCON && player.isTransformed) {
        if (keys['ArrowUp'] || keys['KeyW']) player.vel.y = -currentStats.speed;
        else if (keys['ArrowDown'] || keys['KeyS']) player.vel.y = currentStats.speed;
        else player.vel.y *= 0.9;
      } else {
        if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.grounded) {
          player.vel.y = currentStats.jump;
          player.grounded = false;
        }
        player.vel.y += GRAVITY;
      }

      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;

      const floorY = 398;
      if (player.pos.y > floorY - ph) { player.pos.y = floorY - ph; player.vel.y = 0; player.grounded = true; }
      if (player.pos.x < 0) player.pos.x = 0;
      setDistance(player.pos.x);

      const fr = Math.max(5, currentStats.fireRate - upgrades.weaponTier * 2);
      if (keys['Space'] && e.frame - player.lastShot > fr) {
        soundService.playShoot();
        bullets.push({ 
          pos: { x: player.pos.x + (player.facing === 1 ? pw : 0), y: player.pos.y + ph/2 }, 
          vel: { x: player.facing * 15, y: 0 }, 
          width: 12, height: 4, owner: 'player', health: 1, maxHealth: 1, damage: 99999, color: stats.color 
        });
        player.lastShot = e.frame;
      }

      for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i]; b.pos.x += b.vel.x; b.pos.y += b.vel.y;
        if (b.owner === 'enemy' && !player.invulnerable) {
          if (b.pos.x < player.pos.x + pw && b.pos.x + b.width > player.pos.x &&
              b.pos.y < player.pos.y + ph && b.pos.y + b.height > player.pos.y) {
            setHealth(h => Math.max(0, h - 20)); player.invulnerable = 40;
            bullets.splice(i, 1); soundService.playLose(); continue;
          }
        }
        if (Math.abs(b.pos.x - player.pos.x) > 1000) bullets.splice(i, 1);
      }

      let allDead = true;
      enemies.forEach(en => {
        if (en.isDead) return;
        allDead = false;
        const dir = Math.sign(player.pos.x - en.pos.x);
        en.pos.x += dir * 0.5;
        if (Math.abs(en.pos.x - player.pos.x) < 500 && e.frame - en.lastShot > 120) {
          bullets.push({ 
            pos: {x: en.pos.x, y: en.pos.y + 15}, vel: {x: dir * 6, y: 0}, 
            width: 10, height: 4, owner: 'enemy', health: 1, maxHealth: 1, damage: 20, color: '#f00' 
          });
          en.lastShot = e.frame;
        }
        bullets.forEach((b, idx) => {
          if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) {
            en.isDead = true; bullets.splice(idx, 1);
          }
        });
      });

      if (health <= 0) onDie();
      if (allDead) onWin();
      if (player.invulnerable > 0) player.invulnerable--;
      e.cameraX = player.pos.x - CANVAS_WIDTH/3;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const e = engineRef.current;
      ctx.fillStyle = '#050510'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
      ctx.fillStyle = '#1c1c1c'; ctx.fillRect(0, 398, CANVAS_WIDTH, 52);

      e.enemies.forEach(en => { 
        if(!en.isDead) drawUnit(ctx, en.pos.x - e.cameraX, en.pos.y, en.width, en.height, en.unit || RobotUnit.SENTINEL, Math.sign(e.player.pos.x - en.pos.x), e.frame, true, false, en.isTransformed, en.type); 
      });
      const player = e.player;
      drawUnit(ctx, player.pos.x - e.cameraX, player.pos.y, player.isTransformed ? 48 : 32, player.isTransformed ? 32 : 48, e.unit, player.facing, e.frame, false, player.invulnerable > 0, player.isTransformed, 'bot', 1, upgrades.robotTier);
      e.bullets.forEach(b => { ctx.fillStyle = b.color || '#00f3ff'; ctx.fillRect(b.pos.x - e.cameraX, b.pos.y, b.width, b.height); });
    };

    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [resetLevel, onWin, onDie, level, upgrades, health, currentUnit]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden">
      <div className="absolute top-4 left-4 z-10 space-y-4 pointer-events-none w-[400px]">
        <div className="bg-black/80 border border-cyan-500/50 p-3 rounded backdrop-blur-md shadow-lg">
          <div className="text-[10px] text-cyan-400 font-bold uppercase mb-1 flex justify-between font-orbitron">
            <span>{ROBOT_STATS[currentUnit].name} CHASSIS [TIER {upgrades.robotTier}]</span>
            <span>{Math.round(health)}/{Math.round(maxHealth)}</span>
          </div>
          <div className="w-48 h-2.5 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
            <div className="h-full shadow-[0_0_15px_#00f3ff] transition-all duration-300" style={{ width: `${(health / maxHealth) * 100}%`, backgroundColor: health < maxHealth * 0.3 ? '#ef4444' : '#00f3ff' }} />
          </div>
        </div>
      </div>
      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full aspect-video shadow-2xl rounded-lg border-2 border-cyan-900/50" />
      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 pointer-events-none text-white/30 text-[8px] font-mono tracking-widest uppercase flex gap-6">
        <span>WASD: Move</span><span>Space: Fire</span><span>Shift: Transform</span><span>1-5: Squad</span>
      </div>
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const SHIELD_DURATION = 20 * 60; // 20 seconds at 60fps
const SQUAD_UNION_DURATION = 60 * 60; // 60 seconds (1 minute) at 60fps

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { 
    name: "SENTINEL", color: '#00f3ff', hpMult: 1.0, 
    robot: { speed: 4, jump: -11, fireRate: 15 },
    alt: { speed: 8, jump: -5, fireRate: 25, type: 'Car' }
  },
  [RobotUnit.STRIKER]: { 
    name: "STRIKER", color: '#fbbf24', hpMult: 0.8,
    robot: { speed: 6, jump: -10, fireRate: 10 },
    alt: { speed: 12, jump: -4, fireRate: 20, type: 'Bike' }
  },
  [RobotUnit.FALCON]: { 
    name: "FALCON", color: '#22d3ee', hpMult: 0.7,
    robot: { speed: 5, jump: -10, fireRate: 12 },
    alt: { speed: 7, jump: -7, fireRate: 15, type: 'Jet' }
  },
  [RobotUnit.TITAN]: { 
    name: "TITAN", color: '#ef4444', hpMult: 2.5,
    robot: { speed: 2.5, jump: -12, fireRate: 30 },
    alt: { speed: 4, jump: 0, fireRate: 20, type: 'Tank' }
  },
  [RobotUnit.SPECTER]: { 
    name: "SPECTER", color: '#a855f7', hpMult: 0.6,
    robot: { speed: 5, jump: -11, fireRate: 20 },
    alt: { speed: 6, jump: -14, fireRate: 40, type: 'Energy Sphere' }
  },
  [RobotUnit.VANGUARD]: { 
    name: "VANGUARD", color: '#10b981', hpMult: 2.0, 
    robot: { speed: 3.5, jump: -10, fireRate: 25 },
    alt: { speed: 6, jump: -4, fireRate: 30, type: 'Shield Truck' }
  },
  [RobotUnit.NIGHTSHADE]: { 
    name: "NIGHTSHADE", color: '#6366f1', hpMult: 0.9, 
    robot: { speed: 7, jump: -13, fireRate: 12 },
    alt: { speed: 10, jump: -6, fireRate: 18, type: 'Interceptor' }
  },
  [RobotUnit.BLAZE]: { 
    name: "BLAZE", color: '#f97316', hpMult: 1.2, 
    robot: { speed: 4.5, jump: -11, fireRate: 18 },
    alt: { speed: 7, jump: -5, fireRate: 22, type: 'Rig' }
  },
  [RobotUnit.GLITCH]: { 
    name: "GLITCH", color: '#ec4899', hpMult: 1.0, 
    robot: { speed: 5, jump: -12, fireRate: 14 },
    alt: { speed: 9, jump: -12, fireRate: 16, type: 'Splicer' }
  },
  [RobotUnit.OMEGA]: { 
    name: "OMEGA", color: '#ffffff', hpMult: 3.0, 
    robot: { speed: 6, jump: -14, fireRate: 10 },
    alt: { speed: 10, jump: -8, fireRate: 15, type: 'Fortress' }
  },
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [currentUnit, setCurrentUnit] = useState<RobotUnit>(RobotUnit.SENTINEL);
  const [isTransformed, setIsTransformed] = useState(false);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [distance, setDistance] = useState(0);
  const [unionTime, setUnionTime] = useState(0);

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      maxHealth: 100,
      isTransformed: false,
      unionTimer: 0,
      history: [] as {x: number, y: number}[],
      checkpoint: { x: 100, y: 300, reached: false }
    },
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    unit: RobotUnit.SENTINEL,
    level: level,
  });

  useEffect(() => { engineRef.current.isPaused = isPaused; }, [isPaused]);
  useEffect(() => { 
    engineRef.current.unit = currentUnit;
    engineRef.current.player.isTransformed = false;
    setIsTransformed(false);
  }, [currentUnit]);
  useEffect(() => { engineRef.current.level = level; }, [level]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4, border = true) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff66');
    grad.addColorStop(1, '#000000aa');
    ctx.fillStyle = grad;
    ctx.fill();
    if (border) {
      ctx.strokeStyle = 'rgba(0,0,0,0.6)';
      ctx.lineWidth = 1;
      ctx.stroke();
    }
  };

  const drawCombiner = (ctx: CanvasRenderingContext2D, frame: number, alpha: number) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(1.8, 1.8);

    // Glow effect
    ctx.shadowBlur = 15;
    ctx.shadowColor = '#fff';

    // Massive Chest (Sentinel + Titan mix)
    drawMechanicalPart(ctx, -15, -20, 30, 35, '#00f3ff', 6);
    drawMechanicalPart(ctx, -10, -15, 20, 20, '#ef4444', 4);

    // Core (Specter)
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.arc(0, -5, 6 + Math.sin(frame * 0.2) * 2, 0, Math.PI * 2);
    ctx.fill();

    // Head
    drawMechanicalPart(ctx, -8, -38, 16, 16, '#111', 8);
    ctx.fillStyle = '#fff';
    ctx.fillRect(-5, -30, 10, 2);

    // Massive Wings (Falcon)
    ctx.fillStyle = '#22d3ee';
    ctx.beginPath();
    ctx.moveTo(-15, -15); ctx.lineTo(-45, -40); ctx.lineTo(-15, 5); ctx.fill();
    ctx.beginPath();
    ctx.moveTo(15, -15); ctx.lineTo(45, -40); ctx.lineTo(15, 5); ctx.fill();

    // Striker components on shoulders
    drawMechanicalPart(ctx, -22, -25, 12, 12, '#fbbf24', 2);
    drawMechanicalPart(ctx, 10, -25, 12, 12, '#fbbf24', 2);

    // Thick Legs
    const legSwing = Math.sin(frame * 0.15) * 5;
    drawMechanicalPart(ctx, -12, 15, 12, 22 + legSwing, '#333', 4);
    drawMechanicalPart(ctx, 0, 15, 12, 22 - legSwing, '#333', 4);

    ctx.restore();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, type = 'bot', isTransformed = false, alpha = 1, tier = 0) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8;
    const armSwing = Math.cos(time) * 10;

    let scale = 1;
    if (type === 'scout') scale = 0.8;
    if (type === 'heavy' || type === 'titan') scale = 1.4;

    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(scale, scale);

    // Body
    drawMechanicalPart(ctx, -12, -18, 24, 28, color, 4);

    // Chassis Evolution Visuals
    if (!isEnemy && tier > 0) {
      drawMechanicalPart(ctx, -18, -22, 12, 10, '#333', 2);
      drawMechanicalPart(ctx, 6, -22, 12, 10, '#333', 2);
      ctx.fillStyle = '#fff';
      ctx.shadowBlur = 10;
      ctx.shadowColor = color;
      ctx.beginPath(); ctx.arc(0, -6, 4, 0, Math.PI * 2); ctx.fill();
      ctx.shadowBlur = 0;
    }
    if (!isEnemy && tier > 1) {
      drawMechanicalPart(ctx, -14, 10, 8, 8, '#444', 1);
      drawMechanicalPart(ctx, 6, 10, 8, 8, '#444', 1);
      drawMechanicalPart(ctx, -20, -10, 6, 12, '#555', 1);
      drawMechanicalPart(ctx, 14, -10, 6, 12, '#555', 1);
    }
    if (!isEnemy && tier > 2) {
      drawMechanicalPart(ctx, -4, -38, 8, 10, color, 2);
      ctx.fillStyle = '#00f3ff';
      ctx.beginPath(); ctx.moveTo(-20, -15); ctx.lineTo(-35, -35); ctx.lineTo(-20, -5); ctx.fill();
      ctx.beginPath(); ctx.moveTo(20, -15); ctx.lineTo(35, -35); ctx.lineTo(20, -5); ctx.fill();
    }

    // Head
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? '#ff0000' : '#00f3ff';
    ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);

    // Arms
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);

    // Legs
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);

    ctx.restore();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, color: string, frame: number, alpha = 1, tier = 0) => {
    ctx.save();
    ctx.globalAlpha = alpha;

    switch(unit) {
      case RobotUnit.SENTINEL:
        drawMechanicalPart(ctx, -28, -10, 56, 20, color, 8);
        drawMechanicalPart(ctx, -18, -22, 36, 14, '#111', 4);
        ctx.fillStyle = frame % 10 < 5 ? '#ff0000' : '#0000ff';
        ctx.fillRect(-6, -24, 12, 4);
        ctx.fillStyle = '#111';
        ctx.beginPath(); ctx.arc(-18, 12, 8, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(18, 12, 8, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = '#ffffaa';
        ctx.fillRect(20, -4, 8, 6);
        if (tier > 0) { ctx.fillStyle = '#fff'; ctx.fillRect(-20, -6, 40, 4); }
        break;
      case RobotUnit.TITAN:
        drawMechanicalPart(ctx, -35, -8, 70, 24, color, 4);
        drawMechanicalPart(ctx, -18, -26, 36, 18, '#222', 4);
        drawMechanicalPart(ctx, 12, -22, 30, 8, '#444', 1);
        ctx.fillStyle = '#111';
        ctx.fillRect(-33, 10, 66, 8);
        break;
      case RobotUnit.FALCON:
        drawMechanicalPart(ctx, -24, -8, 48, 16, color, 12);
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(-10, -5); ctx.lineTo(-40, -20); ctx.lineTo(-10, 10); ctx.fill();
        ctx.fillStyle = '#ffaa00';
        ctx.fillRect(-35, -5, 10, 6);
        break;
      default:
        drawMechanicalPart(ctx, -25, -12, 50, 24, color, 6);
        drawMechanicalPart(ctx, -10, -22, 20, 10, '#333', 2);
        break;
    }

    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy = false, isInvuln = false, isTransformed = false, type = 'bot', alpha = 1, tier = 0, isCombiner = false) => {
    if (isInvuln && frame % 4 < 2) return;

    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    if (facing === -1) ctx.scale(-1, 1);

    if (isCombiner) {
      drawCombiner(ctx, frame, alpha);
    } else if (isTransformed) {
      const stats = ROBOT_STATS[unit];
      const color = isEnemy ? '#ff0055' : (stats?.color || '#00f3ff');
      drawAltMode(ctx, unit, color, frame, alpha, tier);
    } else {
      const stats = ROBOT_STATS[unit];
      const color = isEnemy ? '#ff0055' : (stats?.color || '#00f3ff');
      drawHumanoid(ctx, color, frame, isEnemy, type, isTransformed, alpha, tier);
    }

    ctx.restore();
  };

  const resetLevel = useCallback((fromCheckpoint = false) => {
    const e = engineRef.current;
    const stats = ROBOT_STATS[currentUnit];
    const baseHP = 100 + (upgrades.robotTier * 50);

    e.player.maxHealth = baseHP * stats.hpMult;
    e.player.unionTimer = 0;
    setUnionTime(0);
    setMaxHealth(e.player.maxHealth);
    setHealth(e.player.maxHealth);

    if (fromCheckpoint && e.player.checkpoint.reached) {
      e.player.pos = { x: e.player.checkpoint.x, y: e.player.checkpoint.y };
    } else {
      e.player.pos = { x: 100, y: 300 };
      e.player.checkpoint.reached = false;
    }

    e.player.vel = { x: 0, y: 0 };
    e.player.invulnerable = 0;
    e.player.isTransformed = false;
    setIsTransformed(false);
    e.bullets = [];
    e.cameraX = e.player.pos.x - CANVAS_WIDTH/3;

    const enemies: Enemy[] = [];
    const floorY = 398;

    if (level === 5) {
      for (let i = 0; i < 5; i++) {
        enemies.push({ 
          id: i, 
          pos: { x: 1200 + i * 900, y: floorY - 32 }, 
          vel: { x: 0, y: 0 }, 
          width: 70, height: 40, 
          health: 1000, maxHealth: 1000, 
          isDead: false, type: 'heavy', 
          lastShot: 0, 
          isTransformed: true, 
          unit: RobotUnit.TITAN 
        });
      }
    } else {
      const enemyTypes = ['bot', 'scout', 'sniper', 'heavy'];
      for (let i = 0; i < 5; i++) {
        const type = enemyTypes[i % (level < 5 ? 1 : level < 10 ? 2 : 4)];
        let w = 32, h = 48;
        if (type === 'scout') { w = 24; h = 36; }
        if (type === 'heavy') { w = 48; h = 72; }
        enemies.push({ 
          id: i, 
          pos: { x: 800 + i * 800, y: floorY - h }, 
          vel: { x: 0, y: 0 }, 
          width: w, height: h, 
          health: 100, maxHealth: 100, 
          isDead: false, type: type, 
          lastShot: 0, 
          unit: RobotUnit.SENTINEL 
        });
      }
    }
    e.enemies = enemies;
  }, [level, upgrades, currentUnit]);

  useEffect(() => {
    resetLevel();
    const handleKeyDown = (e: KeyboardEvent) => {
      engineRef.current.keys[e.code] = true;
      if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') {
        engineRef.current.player.isTransformed = !engineRef.current.player.isTransformed;
        setIsTransformed(engineRef.current.player.isTransformed);
      }

      // Combiner logic
      if (e.code === 'KeyC' && engineRef.current.player.unionTimer <= 0) {
        engineRef.current.player.unionTimer = SQUAD_UNION_DURATION;
        setHealth(500);
        setMaxHealth(500);
        soundService.playFly(); // Use fly sound as a 'power up' hum
      }

      const trySwitch = (unit: RobotUnit) => {
        if (upgrades.unlockedUnits.includes(unit)) setCurrentUnit(unit);
      };
      if (e.code === 'Digit1') trySwitch(RobotUnit.SENTINEL);
      if (e.code === 'Digit2') trySwitch(RobotUnit.STRIKER);
      if (e.code === 'Digit3') trySwitch(RobotUnit.FALCON);
      if (e.code === 'Digit4') trySwitch(RobotUnit.TITAN);
      if (e.code === 'Digit5') trySwitch(RobotUnit.SPECTER);
    };
    const handleKeyUp = (e: KeyboardEvent) => { engineRef.current.keys[e.code] = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!engineRef.current.isPaused) update();
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const e = engineRef.current;
      const { player, enemies, bullets, keys } = e;
      const isCombiner = player.unionTimer > 0;

      const stats = ROBOT_STATS[e.unit];
      const currentStats = player.isTransformed ? stats.alt : stats.robot;
      e.frame++;

      if (isCombiner) {
        player.unionTimer--;
        setUnionTime(player.unionTimer);
        if (player.unionTimer === 0) {
          // Revert stats
          const baseHP = 100 + (upgrades.robotTier * 50);
          player.maxHealth = baseHP * stats.hpMult;
          setMaxHealth(player.maxHealth);
          setHealth(prev => Math.min(prev, player.maxHealth));
        }
      }

      const ph = isCombiner ? 80 : (player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48));
      const pw = isCombiner ? 64 : (player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32));

      // Movement logic
      const moveSpeed = isCombiner ? 6 : currentStats.speed;
      if (keys['ArrowRight'] || keys['KeyD']) { player.vel.x = moveSpeed; player.facing = 1; }
      else if (keys['ArrowLeft'] || keys['KeyA']) { player.vel.x = -moveSpeed; player.facing = -1; }
      else { player.vel.x *= 0.8; }

      if (e.unit === RobotUnit.FALCON && player.isTransformed) {
        if (keys['ArrowUp'] || keys['KeyW']) player.vel.y = -moveSpeed;
        else if (keys['ArrowDown'] || keys['KeyS']) player.vel.y = moveSpeed;
        else player.vel.y *= 0.9;
      } else {
        const jumpPower = isCombiner ? -15 : currentStats.jump;
        if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.grounded) {
          player.vel.y = jumpPower;
          player.grounded = false;
        }
        player.vel.y += GRAVITY;
      }

      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;

      const floorY = 398;
      if (player.pos.y > floorY - ph) { player.pos.y = floorY - ph; player.vel.y = 0; player.grounded = true; }
      if (player.pos.x < 0) player.pos.x = 0;
      setDistance(player.pos.x);

      // Fire logic
      const fr = isCombiner ? 8 : Math.max(5, currentStats.fireRate - upgrades.weaponTier * 2);
      if (keys['Space'] && e.frame - player.lastShot > fr) {
        soundService.playShoot();
        if (isCombiner) {
          // Massive Super Projectile
          bullets.push({ 
            pos: { x: player.pos.x + (player.facing === 1 ? pw : 0), y: player.pos.y + ph/2 - 10 }, 
            vel: { x: player.facing * 20, y: 0 }, 
            width: 32, height: 20, owner: 'player', health: 1, maxHealth: 1, damage: 99999, color: '#fff' 
          });
        } else {
          bullets.push({ 
            pos: { x: player.pos.x + (player.facing === 1 ? pw : 0), y: player.pos.y + ph/2 }, 
            vel: { x: player.facing * 15, y: 0 }, 
            width: 12, height: 4, owner: 'player', health: 1, maxHealth: 1, damage: 99999, color: stats.color 
          });
        }
        player.lastShot = e.frame;
      }

      // Bullet update
      for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i]; b.pos.x += b.vel.x; b.pos.y += b.vel.y;
        if (b.owner === 'enemy' && !player.invulnerable) {
          if (b.pos.x < player.pos.x + pw && b.pos.x + b.width > player.pos.x &&
              b.pos.y < player.pos.y + ph && b.pos.y + b.height > player.pos.y) {
            setHealth(h => Math.max(0, h - 20)); player.invulnerable = 40;
            bullets.splice(i, 1); soundService.playLose(); continue;
          }
        }
        if (Math.abs(b.pos.x - player.pos.x) > 1000) bullets.splice(i, 1);
      }

      // Enemy update
      let allDead = true;
      enemies.forEach(en => {
        if (en.isDead) return;
        allDead = false;
        const dir = Math.sign(player.pos.x - en.pos.x);
        en.pos.x += dir * 0.5;
        if (Math.abs(en.pos.x - player.pos.x) < 500 && e.frame - en.lastShot > 120) {
          bullets.push({ 
            pos: {x: en.pos.x, y: en.pos.y + 15}, vel: {x: dir * 6, y: 0}, 
            width: 10, height: 4, owner: 'enemy', health: 1, maxHealth: 1, damage: 20, color: '#f00' 
          });
          en.lastShot = e.frame;
        }
        bullets.forEach((b, idx) => {
          if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) {
            en.isDead = true; bullets.splice(idx, 1);
          }
        });
      });

      if (health <= 0) onDie();
      if (allDead) onWin();
      if (player.invulnerable > 0) player.invulnerable--;
      e.cameraX = player.pos.x - CANVAS_WIDTH/3;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const e = engineRef.current;
      ctx.fillStyle = '#050510'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

      // Ground Detail
      ctx.fillStyle = '#111';
      ctx.fillRect(0, 398, CANVAS_WIDTH, 52);
      ctx.strokeStyle = '#222';
      for(let i = 0; i < CANVAS_WIDTH; i += 40) {
        ctx.strokeRect(i - (e.cameraX % 40), 398, 40, 52);
      }

      e.enemies.forEach(en => { 
        if(!en.isDead) drawUnit(ctx, en.pos.x - e.cameraX, en.pos.y, en.width, en.height, en.unit || RobotUnit.SENTINEL, Math.sign(e.player.pos.x - en.pos.x), e.frame, true, false, en.isTransformed, en.type); 
      });

      const player = e.player;
      const isCombiner = player.unionTimer > 0;
      const pw = isCombiner ? 64 : (player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32));
      const ph = isCombiner ? 80 : (player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48));

      drawUnit(ctx, player.pos.x - e.cameraX, player.pos.y, pw, ph, e.unit, player.facing, e.frame, false, player.invulnerable > 0, player.isTransformed, 'bot', 1, upgrades.robotTier, isCombiner);

      e.bullets.forEach(b => { 
        ctx.fillStyle = b.color || '#00f3ff'; 
        if (b.width > 20) {
           // Super projectile glow
           ctx.shadowBlur = 10;
           ctx.shadowColor = b.color || '#fff';
        }
        ctx.fillRect(b.pos.x - e.cameraX, b.pos.y, b.width, b.height); 
        ctx.shadowBlur = 0;
      });
    };

    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [resetLevel, onWin, onDie, level, upgrades, health, currentUnit]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden">
      {/* HUD */}
      <div className="absolute top-4 left-4 z-10 space-y-4 pointer-events-none w-[400px]">
        <div className="bg-black/80 border border-cyan-500/50 p-3 rounded backdrop-blur-md shadow-lg">
          <div className="text-[10px] text-cyan-400 font-bold uppercase mb-1 flex justify-between font-orbitron">
            <span>{engineRef.current.player.unionTimer > 0 ? 'SQUAD COMBINER' : `${ROBOT_STATS[currentUnit].name} CHASSIS [TIER ${upgrades.robotTier}]`}</span>
            <span>{Math.round(health)}/{Math.round(maxHealth)}</span>
          </div>
          <div className="w-48 h-2.5 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
            <div className="h-full shadow-[0_0_15px_#00f3ff] transition-all duration-300" style={{ width: `${(health / maxHealth) * 100}%`, backgroundColor: health < maxHealth * 0.3 ? '#ef4444' : (engineRef.current.player.unionTimer > 0 ? '#fff' : '#00f3ff') }} />
          </div>

          {unionTime > 0 && (
            <div className="mt-2">
              <div className="text-[8px] text-yellow-400 font-bold uppercase mb-0.5 font-orbitron">COMBINER INTEGRITY DURATION</div>
              <div className="w-full h-1 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
                <div className="h-full bg-yellow-500 shadow-[0_0_10px_#fbbf24] transition-all duration-100" style={{ width: `${(unionTime / SQUAD_UNION_DURATION) * 100}%` }} />
              </div>
            </div>
          )}
        </div>
      </div>

      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full aspect-video shadow-2xl rounded-lg border-2 border-cyan-900/50" />

      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 pointer-events-none text-white/30 text-[8px] font-mono tracking-widest uppercase flex gap-6">
        <span>WASD: Move</span><span>Space: Fire</span><span>Shift: Transform</span><span>1-5: Squad</span><span>C: COMBINE</span>
      </div>

      {unionTime > SQUAD_UNION_DURATION - 60 && (
        <div className="absolute inset-0 pointer-events-none flex items-center justify-center animate-out fade-out duration-1000">
          <div className="text-6xl font-black italic text-white font-orbitron tracking-tighter shadow-2xl">SQUAD COMBINATION ENGAGED</div>
        </div>
      )}
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const SQUAD_UNION_DURATION = 60 * 60; // 60 seconds (1 minute) at 60fps

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { 
    name: "SENTINEL", color: '#00f3ff', hpMult: 1.0, 
    robot: { speed: 4, jump: -11, fireRate: 15 },
    alt: { speed: 8, jump: -5, fireRate: 25, type: 'Car' }
  },
  [RobotUnit.STRIKER]: { 
    name: "STRIKER", color: '#fbbf24', hpMult: 0.8,
    robot: { speed: 6, jump: -10, fireRate: 10 },
    alt: { speed: 12, jump: -4, fireRate: 20, type: 'Bike' }
  },
  [RobotUnit.FALCON]: { 
    name: "FALCON", color: '#22d3ee', hpMult: 0.7,
    robot: { speed: 5, jump: -10, fireRate: 12 },
    alt: { speed: 7, jump: -7, fireRate: 15, type: 'Jet' }
  },
  [RobotUnit.TITAN]: { 
    name: "TITAN", color: '#ef4444', hpMult: 2.5,
    robot: { speed: 2.5, jump: -12, fireRate: 30 },
    alt: { speed: 4, jump: 0, fireRate: 20, type: 'Tank' }
  },
  [RobotUnit.SPECTER]: { 
    name: "SPECTER", color: '#a855f7', hpMult: 0.6,
    robot: { speed: 5, jump: -11, fireRate: 20 },
    alt: { speed: 6, jump: -14, fireRate: 40, type: 'Energy Sphere' }
  },
  [RobotUnit.VANGUARD]: { 
    name: "VANGUARD", color: '#10b981', hpMult: 2.0, 
    robot: { speed: 3.5, jump: -10, fireRate: 25 },
    alt: { speed: 6, jump: -4, fireRate: 30, type: 'Shield Truck' }
  },
  [RobotUnit.NIGHTSHADE]: { 
    name: "NIGHTSHADE", color: '#6366f1', hpMult: 0.9, 
    robot: { speed: 7, jump: -13, fireRate: 12 },
    alt: { speed: 10, jump: -6, fireRate: 18, type: 'Interceptor' }
  },
  [RobotUnit.BLAZE]: { 
    name: "BLAZE", color: '#f97316', hpMult: 1.2, 
    robot: { speed: 4.5, jump: -11, fireRate: 18 },
    alt: { speed: 7, jump: -5, fireRate: 22, type: 'Rig' }
  },
  [RobotUnit.GLITCH]: { 
    name: "GLITCH", color: '#ec4899', hpMult: 1.0, 
    robot: { speed: 5, jump: -12, fireRate: 14 },
    alt: { speed: 9, jump: -12, fireRate: 16, type: 'Splicer' }
  },
  [RobotUnit.OMEGA]: { 
    name: "OMEGA", color: '#ffffff', hpMult: 3.0, 
    robot: { speed: 6, jump: -14, fireRate: 10 },
    alt: { speed: 10, jump: -8, fireRate: 15, type: 'Fortress' }
  },
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [currentUnit, setCurrentUnit] = useState<RobotUnit>(RobotUnit.SENTINEL);
  const [isTransformed, setIsTransformed] = useState(false);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [unionTime, setUnionTime] = useState(0);

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      health: 100,
      maxHealth: 100,
      isTransformed: false,
      unionTimer: 0,
      history: [] as {x: number, y: number}[],
      checkpoint: { x: 100, y: 300, reached: false }
    },
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    unit: RobotUnit.SENTINEL,
    level: level,
  });

  // Keep engine ref synced with important props without resetting the loop
  useEffect(() => { engineRef.current.isPaused = isPaused; }, [isPaused]);
  useEffect(() => { engineRef.current.level = level; }, [level]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4, border = true) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff66');
    grad.addColorStop(1, '#000000aa');
    ctx.fillStyle = grad;
    ctx.fill();
    if (border) {
      ctx.strokeStyle = 'rgba(0,0,0,0.6)';
      ctx.lineWidth = 1;
      ctx.stroke();
    }
  };

  const drawCombiner = (ctx: CanvasRenderingContext2D, frame: number, alpha: number) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(1.8, 1.8);
    ctx.shadowBlur = 15;
    ctx.shadowColor = '#fff';
    drawMechanicalPart(ctx, -15, -20, 30, 35, '#00f3ff', 6);
    drawMechanicalPart(ctx, -10, -15, 20, 20, '#ef4444', 4);
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.arc(0, -5, 6 + Math.sin(frame * 0.2) * 2, 0, Math.PI * 2);
    ctx.fill();
    drawMechanicalPart(ctx, -8, -38, 16, 16, '#111', 8);
    ctx.fillStyle = '#fff';
    ctx.fillRect(-5, -30, 10, 2);
    ctx.fillStyle = '#22d3ee';
    ctx.beginPath(); ctx.moveTo(-15, -15); ctx.lineTo(-45, -40); ctx.lineTo(-15, 5); ctx.fill();
    ctx.beginPath(); ctx.moveTo(15, -15); ctx.lineTo(45, -40); ctx.lineTo(15, 5); ctx.fill();
    drawMechanicalPart(ctx, -22, -25, 12, 12, '#fbbf24', 2);
    drawMechanicalPart(ctx, 10, -25, 12, 12, '#fbbf24', 2);
    const legSwing = Math.sin(frame * 0.15) * 5;
    drawMechanicalPart(ctx, -12, 15, 12, 22 + legSwing, '#333', 4);
    drawMechanicalPart(ctx, 0, 15, 12, 22 - legSwing, '#333', 4);
    ctx.restore();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, type = 'bot', alpha = 1, tier = 0) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8;
    const armSwing = Math.cos(time) * 10;
    let scale = 1;
    if (type === 'scout') scale = 0.8;
    if (type === 'heavy' || type === 'titan') scale = 1.4;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(scale, scale);
    drawMechanicalPart(ctx, -12, -18, 24, 28, color, 4);
    if (!isEnemy && tier > 0) {
      drawMechanicalPart(ctx, -18, -22, 12, 10, '#333', 2);
      drawMechanicalPart(ctx, 6, -22, 12, 10, '#333', 2);
      ctx.fillStyle = '#fff'; ctx.shadowBlur = 10; ctx.shadowColor = color; ctx.beginPath(); ctx.arc(0, -6, 4, 0, Math.PI * 2); ctx.fill(); ctx.shadowBlur = 0;
    }
    if (!isEnemy && tier > 1) {
      drawMechanicalPart(ctx, -14, 10, 8, 8, '#444', 1); drawMechanicalPart(ctx, 6, 10, 8, 8, '#444', 1);
      drawMechanicalPart(ctx, -20, -10, 6, 12, '#555', 1); drawMechanicalPart(ctx, 14, -10, 6, 12, '#555', 1);
    }
    if (!isEnemy && tier > 2) {
      drawMechanicalPart(ctx, -4, -38, 8, 10, color, 2);
      ctx.fillStyle = '#00f3ff'; ctx.beginPath(); ctx.moveTo(-20, -15); ctx.lineTo(-35, -35); ctx.lineTo(-20, -5); ctx.fill();
      ctx.beginPath(); ctx.moveTo(20, -15); ctx.lineTo(35, -35); ctx.lineTo(20, -5); ctx.fill();
    }
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? '#ff0000' : '#00f3ff'; ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);
    ctx.restore();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, color: string, frame: number, alpha = 1, tier = 0) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    switch(unit) {
      case RobotUnit.SENTINEL:
        drawMechanicalPart(ctx, -28, -10, 56, 20, color, 8);
        drawMechanicalPart(ctx, -18, -22, 36, 14, '#111', 4);
        ctx.fillStyle = frame % 10 < 5 ? '#ff0000' : '#0000ff'; ctx.fillRect(-6, -24, 12, 4);
        ctx.fillStyle = '#111'; ctx.beginPath(); ctx.arc(-18, 12, 8, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.arc(18, 12, 8, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = '#ffffaa'; ctx.fillRect(20, -4, 8, 6);
        if (tier > 0) { ctx.fillStyle = '#fff'; ctx.fillRect(-20, -6, 40, 4); }
        break;
      case RobotUnit.TITAN:
        drawMechanicalPart(ctx, -35, -8, 70, 24, color, 4);
        drawMechanicalPart(ctx, -18, -26, 36, 18, '#222', 4);
        drawMechanicalPart(ctx, 12, -22, 30, 8, '#444', 1);
        ctx.fillStyle = '#111'; ctx.fillRect(-33, 10, 66, 8);
        break;
      case RobotUnit.FALCON:
        drawMechanicalPart(ctx, -24, -8, 48, 16, color, 12);
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.moveTo(-10, -5); ctx.lineTo(-40, -20); ctx.lineTo(-10, 10); ctx.fill();
        ctx.fillStyle = '#ffaa00'; ctx.fillRect(-35, -5, 10, 6);
        break;
      default:
        drawMechanicalPart(ctx, -25, -12, 50, 24, color, 6);
        drawMechanicalPart(ctx, -10, -22, 20, 10, '#333', 2);
        break;
    }
    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy = false, isInvuln = false, isTransformed = false, type = 'bot', alpha = 1, tier = 0, isCombiner = false) => {
    if (isInvuln && frame % 4 < 2) return;
    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    if (facing === -1) ctx.scale(-1, 1);
    if (isCombiner) {
      drawCombiner(ctx, frame, alpha);
    } else {
      const stats = ROBOT_STATS[unit];
      const color = isEnemy ? '#ff0055' : (stats?.color || '#00f3ff');
      if (isTransformed) {
        drawAltMode(ctx, unit, color, frame, alpha, tier);
      } else {
        drawHumanoid(ctx, color, frame, isEnemy, type, alpha, tier);
      }
    }
    ctx.restore();
  };

  const resetLevel = useCallback((fullReset = true) => {
    const e = engineRef.current;
    const stats = ROBOT_STATS[e.unit];
    const baseHP = 100 + (upgrades.robotTier * 50);

    if (fullReset) {
      e.player.maxHealth = baseHP * stats.hpMult;
      e.player.health = e.player.maxHealth;
      e.player.unionTimer = 0;
      setUnionTime(0);
      setMaxHealth(e.player.maxHealth);
      setHealth(e.player.health);
      e.player.pos = { x: 100, y: 300 };
      e.player.checkpoint.reached = false;
      e.player.vel = { x: 0, y: 0 };
      e.player.invulnerable = 0;
      e.player.isTransformed = false;
      setIsTransformed(false);
      e.bullets = [];
      e.cameraX = 0;

      const enemies: Enemy[] = [];
      const floorY = 398;
      if (e.level === 5) {
        for (let i = 0; i < 5; i++) {
          enemies.push({ 
            id: i, pos: { x: 1200 + i * 900, y: floorY - 32 }, vel: { x: 0, y: 0 }, 
            width: 70, height: 40, health: 1000, maxHealth: 1000, 
            isDead: false, type: 'heavy', lastShot: 0, isTransformed: true, unit: RobotUnit.TITAN 
          });
        }
      } else {
        const enemyTypes = ['bot', 'scout', 'sniper', 'heavy'];
        for (let i = 0; i < 5; i++) {
          const type = enemyTypes[i % (e.level < 5 ? 1 : e.level < 10 ? 2 : 4)];
          let w = 32, h = 48;
          if (type === 'scout') { w = 24; h = 36; }
          if (type === 'heavy') { w = 48; h = 72; }
          enemies.push({ 
            id: i, pos: { x: 800 + i * 800, y: floorY - h }, vel: { x: 0, y: 0 }, 
            width: w, height: h, health: 100, maxHealth: 100, 
            isDead: false, type: type, lastShot: 0, unit: RobotUnit.SENTINEL 
          });
        }
      }
      e.enemies = enemies;
    }
  }, [upgrades.robotTier]);

  useEffect(() => {
    resetLevel(true);
  }, [level, resetLevel]);

  useEffect(() => {
    const e = engineRef.current;
    const handleKeyDown = (ev: KeyboardEvent) => {
      e.keys[ev.code] = true;
      if (ev.code === 'ShiftLeft' || ev.code === 'ShiftRight') {
        e.player.isTransformed = !e.player.isTransformed;
        setIsTransformed(e.player.isTransformed);
      }
      if (ev.code === 'KeyC' && e.player.unionTimer <= 0) {
        e.player.unionTimer = SQUAD_UNION_DURATION;
        e.player.health = 500;
        e.player.maxHealth = 500;
        setHealth(500);
        setMaxHealth(500);
        soundService.playFly();
      }
      const trySwitch = (unit: RobotUnit) => {
        if (upgrades.unlockedUnits.includes(unit)) {
          e.unit = unit;
          setCurrentUnit(unit);
          if (e.player.unionTimer <= 0) {
             const stats = ROBOT_STATS[unit];
             const baseHP = 100 + (upgrades.robotTier * 50);
             e.player.maxHealth = baseHP * stats.hpMult;
             e.player.health = Math.min(e.player.health, e.player.maxHealth);
             setHealth(e.player.health);
             setMaxHealth(e.player.maxHealth);
          }
        }
      };
      if (ev.code === 'Digit1') trySwitch(RobotUnit.SENTINEL);
      if (ev.code === 'Digit2') trySwitch(RobotUnit.STRIKER);
      if (ev.code === 'Digit3') trySwitch(RobotUnit.FALCON);
      if (ev.code === 'Digit4') trySwitch(RobotUnit.TITAN);
      if (ev.code === 'Digit5') trySwitch(RobotUnit.SPECTER);
    };
    const handleKeyUp = (ev: KeyboardEvent) => { e.keys[ev.code] = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!e.isPaused) update();
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const isCombiner = e.player.unionTimer > 0;
      const stats = ROBOT_STATS[e.unit];
      const currentStats = e.player.isTransformed ? stats.alt : stats.robot;
      e.frame++;

      if (isCombiner) {
        e.player.unionTimer--;
        if (e.frame % 10 === 0) setUnionTime(e.player.unionTimer);
        if (e.player.unionTimer === 0) {
          const baseHP = 100 + (upgrades.robotTier * 50);
          e.player.maxHealth = baseHP * stats.hpMult;
          e.player.health = Math.min(e.player.health, e.player.maxHealth);
          setHealth(e.player.health);
          setMaxHealth(e.player.maxHealth);
        }
      }

      const ph = isCombiner ? 80 : (e.player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48));
      const pw = isCombiner ? 64 : (e.player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32));

      const moveSpeed = isCombiner ? 6 : currentStats.speed;
      if (e.keys['ArrowRight'] || e.keys['KeyD']) { e.player.vel.x = moveSpeed; e.player.facing = 1; }
      else if (e.keys['ArrowLeft'] || e.keys['KeyA']) { e.player.vel.x = -moveSpeed; e.player.facing = -1; }
      else { e.player.vel.x *= 0.8; }

      if (e.unit === RobotUnit.FALCON && e.player.isTransformed) {
        if (e.keys['ArrowUp'] || e.keys['KeyW']) e.player.vel.y = -moveSpeed;
        else if (e.keys['ArrowDown'] || e.keys['KeyS']) e.player.vel.y = moveSpeed;
        else e.player.vel.y *= 0.9;
      } else {
        const jumpPower = isCombiner ? -15 : currentStats.jump;
        if ((e.keys['ArrowUp'] || e.keys['KeyW'] || e.keys['Space']) && e.player.grounded) {
          e.player.vel.y = jumpPower;
          e.player.grounded = false;
        }
        e.player.vel.y += GRAVITY;
      }

      e.player.pos.x += e.player.vel.x;
      e.player.pos.y += e.player.vel.y;
      const floorY = 398;
      if (e.player.pos.y > floorY - ph) { e.player.pos.y = floorY - ph; e.player.vel.y = 0; e.player.grounded = true; }
      if (e.player.pos.x < 0) e.player.pos.x = 0;
      if (e.frame % 30 === 0) setDistance(e.player.pos.x);

      const fr = isCombiner ? 8 : Math.max(5, currentStats.fireRate - upgrades.weaponTier * 2);
      if (e.keys['Space'] && e.frame - e.player.lastShot > fr) {
        soundService.playShoot();
        if (isCombiner) {
          e.bullets.push({ pos: { x: e.player.pos.x + (e.player.facing === 1 ? pw : 0), y: e.player.pos.y + ph/2 - 10 }, vel: { x: e.player.facing * 20, y: 0 }, width: 32, height: 20, owner: 'player', health: 1, maxHealth: 1, damage: 99999, color: '#fff' });
        } else {
          e.bullets.push({ pos: { x: e.player.pos.x + (e.player.facing === 1 ? pw : 0), y: e.player.pos.y + ph/2 }, vel: { x: e.player.facing * 15, y: 0 }, width: 12, height: 4, owner: 'player', health: 1, maxHealth: 1, damage: 99999, color: stats.color });
        }
        e.player.lastShot = e.frame;
      }

      for (let i = e.bullets.length - 1; i >= 0; i--) {
        const b = e.bullets[i]; b.pos.x += b.vel.x; b.pos.y += b.vel.y;
        if (b.owner === 'enemy' && !e.player.invulnerable) {
          if (b.pos.x < e.player.pos.x + pw && b.pos.x + b.width > e.player.pos.x && b.pos.y < e.player.pos.y + ph && b.pos.y + b.height > e.player.pos.y) {
            e.player.health = Math.max(0, e.player.health - 20); e.player.invulnerable = 40;
            setHealth(e.player.health);
            e.bullets.splice(i, 1); soundService.playLose(); continue;
          }
        }
        if (Math.abs(b.pos.x - e.player.pos.x) > 1000) e.bullets.splice(i, 1);
      }

      let allDead = true;
      e.enemies.forEach(en => {
        if (en.isDead) return;
        allDead = false;
        const dir = Math.sign(e.player.pos.x - en.pos.x);
        en.pos.x += dir * 0.5;
        if (Math.abs(en.pos.x - e.player.pos.x) < 500 && e.frame - en.lastShot > 120) {
          e.bullets.push({ pos: {x: en.pos.x, y: en.pos.y + 15}, vel: {x: dir * 6, y: 0}, width: 10, height: 4, owner: 'enemy', health: 1, maxHealth: 1, damage: 20, color: '#f00' });
          en.lastShot = e.frame;
        }
        e.bullets.forEach((b, idx) => {
          if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) {
            en.isDead = true; e.bullets.splice(idx, 1);
          }
        });
      });

      if (e.player.health <= 0) onDie();
      if (allDead) onWin();
      if (e.player.invulnerable > 0) e.player.invulnerable--;
      e.cameraX = e.player.pos.x - CANVAS_WIDTH/3;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      ctx.fillStyle = '#050510'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
      ctx.fillStyle = '#111'; ctx.fillRect(0, 398, CANVAS_WIDTH, 52); ctx.strokeStyle = '#222';
      for(let i = 0; i < CANVAS_WIDTH; i += 40) ctx.strokeRect(i - (e.cameraX % 40), 398, 40, 52);
      e.enemies.forEach(en => { if(!en.isDead) drawUnit(ctx, en.pos.x - e.cameraX, en.pos.y, en.width, en.height, en.unit || RobotUnit.SENTINEL, Math.sign(e.player.pos.x - en.pos.x), e.frame, true, false, en.isTransformed, en.type); });
      const isCombiner = e.player.unionTimer > 0;
      const pw = isCombiner ? 64 : (e.player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32));
      const ph = isCombiner ? 80 : (e.player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48));
      drawUnit(ctx, e.player.pos.x - e.cameraX, e.player.pos.y, pw, ph, e.unit, e.player.facing, e.frame, false, e.player.invulnerable > 0, e.player.isTransformed, 'bot', 1, upgrades.robotTier, isCombiner);
      e.bullets.forEach(b => { ctx.fillStyle = b.color || '#00f3ff'; if (b.width > 20) { ctx.shadowBlur = 10; ctx.shadowColor = b.color || '#fff'; } ctx.fillRect(b.pos.x - e.cameraX, b.pos.y, b.width, b.height); ctx.shadowBlur = 0; });
    };

    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [onWin, onDie, upgrades.unlockedUnits, upgrades.weaponTier, upgrades.robotTier]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden">
      <div className="absolute top-4 left-4 z-10 space-y-4 pointer-events-none w-[400px]">
        <div className="bg-black/80 border border-cyan-500/50 p-3 rounded backdrop-blur-md shadow-lg">
          <div className="text-[10px] text-cyan-400 font-bold uppercase mb-1 flex justify-between font-orbitron">
            <span>{unionTime > 0 ? 'SQUAD COMBINER' : `${ROBOT_STATS[currentUnit].name} CHASSIS [TIER ${upgrades.robotTier}]`}</span>
            <span>{Math.round(health)}/{Math.round(maxHealth)}</span>
          </div>
          <div className="w-48 h-2.5 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
            <div className="h-full shadow-[0_0_15px_#00f3ff] transition-all duration-300" style={{ width: `${(health / maxHealth) * 100}%`, backgroundColor: health < maxHealth * 0.3 ? '#ef4444' : (unionTime > 0 ? '#fff' : '#00f3ff') }} />
          </div>
          {unionTime > 0 && (
            <div className="mt-2">
              <div className="text-[8px] text-yellow-400 font-bold uppercase mb-0.5 font-orbitron">COMBINER INTEGRITY DURATION</div>
              <div className="w-full h-1 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
                <div className="h-full bg-yellow-500 shadow-[0_0_10px_#fbbf24] transition-all duration-100" style={{ width: `${(unionTime / SQUAD_UNION_DURATION) * 100}%` }} />
              </div>
            </div>
          )}
        </div>
      </div>
      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full aspect-video shadow-2xl rounded-lg border-2 border-cyan-900/50" />
      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 pointer-events-none text-white/30 text-[8px] font-mono tracking-widest uppercase flex gap-6">
        <span>WASD: Move</span><span>Space: Fire</span><span>Shift: Transform</span><span>1-5: Squad</span><span>C: COMBINE</span>
      </div>
      {unionTime > SQUAD_UNION_DURATION - 60 && (
        <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
          <div className="text-6xl font-black italic text-white font-orbitron tracking-tighter shadow-2xl animate-pulse">SQUAD COMBINATION ENGAGED</div>
        </div>
      )}
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const SQUAD_UNION_DURATION = 60 * 60; // 60 seconds (1 minute) at 60fps

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { 
    name: "SENTINEL", color: '#00f3ff', hpMult: 1.0, 
    robot: { speed: 4, jump: -11, fireRate: 15 },
    alt: { speed: 8, jump: -5, fireRate: 25, type: 'Car' }
  },
  [RobotUnit.STRIKER]: { 
    name: "STRIKER", color: '#fbbf24', hpMult: 0.8,
    robot: { speed: 6, jump: -10, fireRate: 10 },
    alt: { speed: 12, jump: -4, fireRate: 20, type: 'Bike' }
  },
  [RobotUnit.FALCON]: { 
    name: "FALCON", color: '#22d3ee', hpMult: 0.7,
    robot: { speed: 5, jump: -10, fireRate: 12 },
    alt: { speed: 7, jump: -7, fireRate: 15, type: 'Jet' }
  },
  [RobotUnit.TITAN]: { 
    name: "TITAN", color: '#ef4444', hpMult: 2.5,
    robot: { speed: 2.5, jump: -12, fireRate: 30 },
    alt: { speed: 4, jump: 0, fireRate: 20, type: 'Tank' }
  },
  [RobotUnit.SPECTER]: { 
    name: "SPECTER", color: '#a855f7', hpMult: 0.6,
    robot: { speed: 5, jump: -11, fireRate: 20 },
    alt: { speed: 6, jump: -14, fireRate: 40, type: 'Energy Sphere' }
  },
  [RobotUnit.VANGUARD]: { 
    name: "VANGUARD", color: '#10b981', hpMult: 2.0, 
    robot: { speed: 3.5, jump: -10, fireRate: 25 },
    alt: { speed: 6, jump: -4, fireRate: 30, type: 'Shield Truck' }
  },
  [RobotUnit.NIGHTSHADE]: { 
    name: "NIGHTSHADE", color: '#6366f1', hpMult: 0.9, 
    robot: { speed: 7, jump: -13, fireRate: 12 },
    alt: { speed: 10, jump: -6, fireRate: 18, type: 'Interceptor' }
  },
  [RobotUnit.BLAZE]: { 
    name: "BLAZE", color: '#f97316', hpMult: 1.2, 
    robot: { speed: 4.5, jump: -11, fireRate: 18 },
    alt: { speed: 7, jump: -5, fireRate: 22, type: 'Rig' }
  },
  [RobotUnit.GLITCH]: { 
    name: "GLITCH", color: '#ec4899', hpMult: 1.0, 
    robot: { speed: 5, jump: -12, fireRate: 14 },
    alt: { speed: 9, jump: -12, fireRate: 16, type: 'Splicer' }
  },
  [RobotUnit.OMEGA]: { 
    name: "OMEGA", color: '#ffffff', hpMult: 3.0, 
    robot: { speed: 6, jump: -14, fireRate: 10 },
    alt: { speed: 10, jump: -8, fireRate: 15, type: 'Fortress' }
  },
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [currentUnit, setCurrentUnit] = useState<RobotUnit>(RobotUnit.SENTINEL);
  const [isTransformed, setIsTransformed] = useState(false);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [unionTime, setUnionTime] = useState(0);

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      health: 100,
      maxHealth: 100,
      isTransformed: false,
      unionTimer: 0,
      history: [] as {x: number, y: number}[],
      checkpoint: { x: 100, y: 300, reached: false }
    },
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    unit: RobotUnit.SENTINEL,
    level: level,
  });

  // Keep engine ref synced with important props without resetting the loop
  useEffect(() => { engineRef.current.isPaused = isPaused; }, [isPaused]);
  useEffect(() => { engineRef.current.level = level; }, [level]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4, border = true) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff66');
    grad.addColorStop(1, '#000000aa');
    ctx.fillStyle = grad;
    ctx.fill();
    if (border) {
      ctx.strokeStyle = 'rgba(0,0,0,0.6)';
      ctx.lineWidth = 1;
      ctx.stroke();
    }
  };

  const drawCombiner = (ctx: CanvasRenderingContext2D, frame: number, alpha: number) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(1.8, 1.8);
    ctx.shadowBlur = 15;
    ctx.shadowColor = '#fff';
    drawMechanicalPart(ctx, -15, -20, 30, 35, '#00f3ff', 6);
    drawMechanicalPart(ctx, -10, -15, 20, 20, '#ef4444', 4);
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.arc(0, -5, 6 + Math.sin(frame * 0.2) * 2, 0, Math.PI * 2);
    ctx.fill();
    drawMechanicalPart(ctx, -8, -38, 16, 16, '#111', 8);
    ctx.fillStyle = '#fff';
    ctx.fillRect(-5, -30, 10, 2);
    ctx.fillStyle = '#22d3ee';
    ctx.beginPath(); ctx.moveTo(-15, -15); ctx.lineTo(-45, -40); ctx.lineTo(-15, 5); ctx.fill();
    ctx.beginPath(); ctx.moveTo(15, -15); ctx.lineTo(45, -40); ctx.lineTo(15, 5); ctx.fill();
    drawMechanicalPart(ctx, -22, -25, 12, 12, '#fbbf24', 2);
    drawMechanicalPart(ctx, 10, -25, 12, 12, '#fbbf24', 2);
    const legSwing = Math.sin(frame * 0.15) * 5;
    drawMechanicalPart(ctx, -12, 15, 12, 22 + legSwing, '#333', 4);
    drawMechanicalPart(ctx, 0, 15, 12, 22 - legSwing, '#333', 4);
    ctx.restore();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, type = 'bot', alpha = 1, tier = 0) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8;
    const armSwing = Math.cos(time) * 10;
    let scale = 1;
    if (type === 'scout') scale = 0.8;
    if (type === 'heavy' || type === 'titan') scale = 1.4;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(scale, scale);
    drawMechanicalPart(ctx, -12, -18, 24, 28, color, 4);
    if (!isEnemy && tier > 0) {
      drawMechanicalPart(ctx, -18, -22, 12, 10, '#333', 2);
      drawMechanicalPart(ctx, 6, -22, 12, 10, '#333', 2);
      ctx.fillStyle = '#fff'; ctx.shadowBlur = 10; ctx.shadowColor = color; ctx.beginPath(); ctx.arc(0, -6, 4, 0, Math.PI * 2); ctx.fill(); ctx.shadowBlur = 0;
    }
    if (!isEnemy && tier > 1) {
      drawMechanicalPart(ctx, -14, 10, 8, 8, '#444', 1); drawMechanicalPart(ctx, 6, 10, 8, 8, '#444', 1);
      drawMechanicalPart(ctx, -20, -10, 6, 12, '#555', 1); drawMechanicalPart(ctx, 14, -10, 6, 12, '#555', 1);
    }
    if (!isEnemy && tier > 2) {
      drawMechanicalPart(ctx, -4, -38, 8, 10, color, 2);
      ctx.fillStyle = '#00f3ff'; ctx.beginPath(); ctx.moveTo(-20, -15); ctx.lineTo(-35, -35); ctx.lineTo(-20, -5); ctx.fill();
      ctx.beginPath(); ctx.moveTo(20, -15); ctx.lineTo(35, -35); ctx.lineTo(20, -5); ctx.fill();
    }
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? '#ff0000' : '#00f3ff'; ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);
    ctx.restore();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, color: string, frame: number, alpha = 1, tier = 0) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    switch(unit) {
      case RobotUnit.SENTINEL:
        drawMechanicalPart(ctx, -28, -10, 56, 20, color, 8);
        drawMechanicalPart(ctx, -18, -22, 36, 14, '#111', 4);
        ctx.fillStyle = frame % 10 < 5 ? '#ff0000' : '#0000ff'; ctx.fillRect(-6, -24, 12, 4);
        ctx.fillStyle = '#111'; ctx.beginPath(); ctx.arc(-18, 12, 8, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.arc(18, 12, 8, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = '#ffffaa'; ctx.fillRect(20, -4, 8, 6);
        if (tier > 0) { ctx.fillStyle = '#fff'; ctx.fillRect(-20, -6, 40, 4); }
        break;
      case RobotUnit.TITAN:
        drawMechanicalPart(ctx, -35, -8, 70, 24, color, 4);
        drawMechanicalPart(ctx, -18, -26, 36, 18, '#222', 4);
        drawMechanicalPart(ctx, 12, -22, 30, 8, '#444', 1);
        ctx.fillStyle = '#111'; ctx.fillRect(-33, 10, 66, 8);
        break;
      case RobotUnit.FALCON:
        drawMechanicalPart(ctx, -24, -8, 48, 16, color, 12);
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.moveTo(-10, -5); ctx.lineTo(-40, -20); ctx.lineTo(-10, 10); ctx.fill();
        ctx.fillStyle = '#ffaa00'; ctx.fillRect(-35, -5, 10, 6);
        break;
      default:
        drawMechanicalPart(ctx, -25, -12, 50, 24, color, 6);
        drawMechanicalPart(ctx, -10, -22, 20, 10, '#333', 2);
        break;
    }
    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy = false, isInvuln = false, isTransformed = false, type = 'bot', alpha = 1, tier = 0, isCombiner = false) => {
    if (isInvuln && frame % 4 < 2) return;
    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    if (facing === -1) ctx.scale(-1, 1);
    if (isCombiner) {
      drawCombiner(ctx, frame, alpha);
    } else {
      const stats = ROBOT_STATS[unit];
      const color = isEnemy ? '#ff0055' : (stats?.color || '#00f3ff');
      if (isTransformed) {
        drawAltMode(ctx, unit, color, frame, alpha, tier);
      } else {
        drawHumanoid(ctx, color, frame, isEnemy, type, alpha, tier);
      }
    }
    ctx.restore();
  };

  const resetLevel = useCallback((fullReset = true) => {
    const e = engineRef.current;
    const stats = ROBOT_STATS[e.unit];
    const baseHP = 100 + (upgrades.robotTier * 50);

    if (fullReset) {
      e.player.maxHealth = baseHP * stats.hpMult;
      e.player.health = e.player.maxHealth;
      e.player.unionTimer = 0;
      setUnionTime(0);
      setMaxHealth(e.player.maxHealth);
      setHealth(e.player.health);
      e.player.pos = { x: 100, y: 300 };
      e.player.checkpoint.reached = false;
      e.player.vel = { x: 0, y: 0 };
      e.player.invulnerable = 0;
      e.player.isTransformed = false;
      setIsTransformed(false);
      e.bullets = [];
      e.cameraX = 0;

      const enemies: Enemy[] = [];
      const floorY = 398;
      if (e.level === 5) {
        for (let i = 0; i < 5; i++) {
          enemies.push({ 
            id: i, pos: { x: 1200 + i * 900, y: floorY - 32 }, vel: { x: 0, y: 0 }, 
            width: 70, height: 40, health: 1000, maxHealth: 1000, 
            isDead: false, type: 'heavy', lastShot: 0, isTransformed: true, unit: RobotUnit.TITAN 
          });
        }
      } else {
        const enemyTypes = ['bot', 'scout', 'sniper', 'heavy'];
        for (let i = 0; i < 5; i++) {
          const type = enemyTypes[i % (e.level < 5 ? 1 : e.level < 10 ? 2 : 4)];
          let w = 32, h = 48;
          if (type === 'scout') { w = 24; h = 36; }
          if (type === 'heavy') { w = 48; h = 72; }
          enemies.push({ 
            id: i, pos: { x: 800 + i * 800, y: floorY - h }, vel: { x: 0, y: 0 }, 
            width: w, height: h, health: 100, maxHealth: 100, 
            isDead: false, type: type, lastShot: 0, unit: RobotUnit.SENTINEL 
          });
        }
      }
      e.enemies = enemies;
    }
  }, [upgrades.robotTier]);

  useEffect(() => {
    resetLevel(true);
  }, [level, resetLevel]);

  useEffect(() => {
    const e = engineRef.current;
    const handleKeyDown = (ev: KeyboardEvent) => {
      e.keys[ev.code] = true;
      if (ev.code === 'ShiftLeft' || ev.code === 'ShiftRight') {
        e.player.isTransformed = !e.player.isTransformed;
        setIsTransformed(e.player.isTransformed);
      }
      if (ev.code === 'KeyC' && e.player.unionTimer <= 0) {
        e.player.unionTimer = SQUAD_UNION_DURATION;
        e.player.health = 500;
        e.player.maxHealth = 500;
        setHealth(500);
        setMaxHealth(500);
        soundService.playFly();
      }
      const trySwitch = (unit: RobotUnit) => {
        if (upgrades.unlockedUnits.includes(unit)) {
          e.unit = unit;
          setCurrentUnit(unit);
          if (e.player.unionTimer <= 0) {
             const stats = ROBOT_STATS[unit];
             const baseHP = 100 + (upgrades.robotTier * 50);
             e.player.maxHealth = baseHP * stats.hpMult;
             e.player.health = Math.min(e.player.health, e.player.maxHealth);
             setHealth(e.player.health);
             setMaxHealth(e.player.maxHealth);
          }
        }
      };
      if (ev.code === 'Digit1') trySwitch(RobotUnit.SENTINEL);
      if (ev.code === 'Digit2') trySwitch(RobotUnit.STRIKER);
      if (ev.code === 'Digit3') trySwitch(RobotUnit.FALCON);
      if (ev.code === 'Digit4') trySwitch(RobotUnit.TITAN);
      if (ev.code === 'Digit5') trySwitch(RobotUnit.SPECTER);
    };
    const handleKeyUp = (ev: KeyboardEvent) => { e.keys[ev.code] = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!e.isPaused) update();
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const isCombiner = e.player.unionTimer > 0;
      const stats = ROBOT_STATS[e.unit];
      const currentStats = e.player.isTransformed ? stats.alt : stats.robot;
      e.frame++;

      if (isCombiner) {
        e.player.unionTimer--;
        if (e.frame % 10 === 0) setUnionTime(e.player.unionTimer);
        if (e.player.unionTimer === 0) {
          const baseHP = 100 + (upgrades.robotTier * 50);
          e.player.maxHealth = baseHP * stats.hpMult;
          e.player.health = Math.min(e.player.health, e.player.maxHealth);
          setHealth(e.player.health);
          setMaxHealth(e.player.maxHealth);
        }
      }

      const ph = isCombiner ? 80 : (e.player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48));
      const pw = isCombiner ? 64 : (e.player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32));

      const moveSpeed = isCombiner ? 6 : currentStats.speed;
      if (e.keys['ArrowRight'] || e.keys['KeyD']) { e.player.vel.x = moveSpeed; e.player.facing = 1; }
      else if (e.keys['ArrowLeft'] || e.keys['KeyA']) { e.player.vel.x = -moveSpeed; e.player.facing = -1; }
      else { e.player.vel.x *= 0.8; }

      if (e.unit === RobotUnit.FALCON && e.player.isTransformed) {
        if (e.keys['ArrowUp'] || e.keys['KeyW']) e.player.vel.y = -moveSpeed;
        else if (e.keys['ArrowDown'] || e.keys['KeyS']) e.player.vel.y = moveSpeed;
        else e.player.vel.y *= 0.9;
      } else {
        const jumpPower = isCombiner ? -15 : currentStats.jump;
        if ((e.keys['ArrowUp'] || e.keys['KeyW'] || e.keys['Space']) && e.player.grounded) {
          e.player.vel.y = jumpPower;
          e.player.grounded = false;
        }
        e.player.vel.y += GRAVITY;
      }

      e.player.pos.x += e.player.vel.x;
      e.player.pos.y += e.player.vel.y;
      const floorY = 398;
      if (e.player.pos.y > floorY - ph) { e.player.pos.y = floorY - ph; e.player.vel.y = 0; e.player.grounded = true; }
      if (e.player.pos.x < 0) e.player.pos.x = 0;
      // Fix: Removed call to undefined setDistance function

      const fr = isCombiner ? 8 : Math.max(5, currentStats.fireRate - upgrades.weaponTier * 2);
      if (e.keys['Space'] && e.frame - e.player.lastShot > fr) {
        soundService.playShoot();
        if (isCombiner) {
          e.bullets.push({ pos: { x: e.player.pos.x + (e.player.facing === 1 ? pw : 0), y: e.player.pos.y + ph/2 - 10 }, vel: { x: e.player.facing * 20, y: 0 }, width: 32, height: 20, owner: 'player', health: 1, maxHealth: 1, damage: 99999, color: '#fff' });
        } else {
          e.bullets.push({ pos: { x: e.player.pos.x + (e.player.facing === 1 ? pw : 0), y: e.player.pos.y + ph/2 }, vel: { x: e.player.facing * 15, y: 0 }, width: 12, height: 4, owner: 'player', health: 1, maxHealth: 1, damage: 99999, color: stats.color });
        }
        e.player.lastShot = e.frame;
      }

      for (let i = e.bullets.length - 1; i >= 0; i--) {
        const b = e.bullets[i]; b.pos.x += b.vel.x; b.pos.y += b.vel.y;
        if (b.owner === 'enemy' && !e.player.invulnerable) {
          if (b.pos.x < e.player.pos.x + pw && b.pos.x + b.width > e.player.pos.x && b.pos.y < e.player.pos.y + ph && b.pos.y + b.height > e.player.pos.y) {
            e.player.health = Math.max(0, e.player.health - 20); e.player.invulnerable = 40;
            setHealth(e.player.health);
            e.bullets.splice(i, 1); soundService.playLose(); continue;
          }
        }
        if (Math.abs(b.pos.x - e.player.pos.x) > 1000) e.bullets.splice(i, 1);
      }

      let allDead = true;
      e.enemies.forEach(en => {
        if (en.isDead) return;
        allDead = false;
        const dir = Math.sign(e.player.pos.x - en.pos.x);
        en.pos.x += dir * 0.5;
        if (Math.abs(en.pos.x - e.player.pos.x) < 500 && e.frame - en.lastShot > 120) {
          e.bullets.push({ pos: {x: en.pos.x, y: en.pos.y + 15}, vel: {x: dir * 6, y: 0}, width: 10, height: 4, owner: 'enemy', health: 1, maxHealth: 1, damage: 20, color: '#f00' });
          en.lastShot = e.frame;
        }
        e.bullets.forEach((b, idx) => {
          if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) {
            en.isDead = true; e.bullets.splice(idx, 1);
          }
        });
      });

      if (e.player.health <= 0) onDie();
      if (allDead) onWin();
      if (e.player.invulnerable > 0) e.player.invulnerable--;
      e.cameraX = e.player.pos.x - CANVAS_WIDTH/3;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      ctx.fillStyle = '#050510'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
      ctx.fillStyle = '#111'; ctx.fillRect(0, 398, CANVAS_WIDTH, 52); ctx.strokeStyle = '#222';
      for(let i = 0; i < CANVAS_WIDTH; i += 40) ctx.strokeRect(i - (e.cameraX % 40), 398, 40, 52);
      e.enemies.forEach(en => { if(!en.isDead) drawUnit(ctx, en.pos.x - e.cameraX, en.pos.y, en.width, en.height, en.unit || RobotUnit.SENTINEL, Math.sign(e.player.pos.x - en.pos.x), e.frame, true, false, en.isTransformed, en.type); });
      const isCombiner = e.player.unionTimer > 0;
      const pw = isCombiner ? 64 : (e.player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32));
      const ph = isCombiner ? 80 : (e.player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48));
      drawUnit(ctx, e.player.pos.x - e.cameraX, e.player.pos.y, pw, ph, e.unit, e.player.facing, e.frame, false, e.player.invulnerable > 0, e.player.isTransformed, 'bot', 1, upgrades.robotTier, isCombiner);
      e.bullets.forEach(b => { ctx.fillStyle = b.color || '#00f3ff'; if (b.width > 20) { ctx.shadowBlur = 10; ctx.shadowColor = b.color || '#fff'; } ctx.fillRect(b.pos.x - e.cameraX, b.pos.y, b.width, b.height); ctx.shadowBlur = 0; });
    };

    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [onWin, onDie, upgrades.unlockedUnits, upgrades.weaponTier, upgrades.robotTier]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden">
      <div className="absolute top-4 left-4 z-10 space-y-4 pointer-events-none w-[400px]">
        <div className="bg-black/80 border border-cyan-500/50 p-3 rounded backdrop-blur-md shadow-lg">
          <div className="text-[10px] text-cyan-400 font-bold uppercase mb-1 flex justify-between font-orbitron">
            <span>{unionTime > 0 ? 'SQUAD COMBINER' : `${ROBOT_STATS[currentUnit].name} CHASSIS [TIER ${upgrades.robotTier}]`}</span>
            <span>{Math.round(health)}/{Math.round(maxHealth)}</span>
          </div>
          <div className="w-48 h-2.5 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
            <div className="h-full shadow-[0_0_15px_#00f3ff] transition-all duration-300" style={{ width: `${(health / maxHealth) * 100}%`, backgroundColor: health < maxHealth * 0.3 ? '#ef4444' : (unionTime > 0 ? '#fff' : '#00f3ff') }} />
          </div>
          {unionTime > 0 && (
            <div className="mt-2">
              <div className="text-[8px] text-yellow-400 font-bold uppercase mb-0.5 font-orbitron">COMBINER INTEGRITY DURATION</div>
              <div className="w-full h-1 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
                <div className="h-full bg-yellow-500 shadow-[0_0_10px_#fbbf24] transition-all duration-100" style={{ width: `${(unionTime / SQUAD_UNION_DURATION) * 100}%` }} />
              </div>
            </div>
          )}
        </div>
      </div>
      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full aspect-video shadow-2xl rounded-lg border-2 border-cyan-900/50" />
      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 pointer-events-none text-white/30 text-[8px] font-mono tracking-widest uppercase flex gap-6">
        <span>WASD: Move</span><span>Space: Fire</span><span>Shift: Transform</span><span>1-5: Squad</span><span>C: COMBINE</span>
      </div>
      {unionTime > SQUAD_UNION_DURATION - 60 && (
        <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
          <div className="text-6xl font-black italic text-white font-orbitron tracking-tighter shadow-2xl animate-pulse">SQUAD COMBINATION ENGAGED</div>
        </div>
      )}
    </div>
  );
};

export default GameView;

import React, { useState, useEffect, useCallback } from 'react';
import { GameState, LevelInfo, RobotUnit, Upgrades } from './types';
import { getLevelBriefing } from './services/geminiService';
import MainMenu from './components/MainMenu';
import Briefing from './components/Briefing';
import GameView from './components/GameView';
import GameOver from './components/GameOver';
import Victory from './components/Victory';
import Shop from './components/Shop';
import RobotShop from './components/RobotShop';
import LevelSelect from './components/LevelSelect';

const SAVE_KEY = 'cybercop_save_data';

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>(GameState.MENU);
  const [level, setLevel] = useState(1);
  const [maxUnlockedLevel, setMaxUnlockedLevel] = useState(1);
  const [money, setMoney] = useState(0);
  const [upgrades, setUpgrades] = useState<Upgrades>({ 
    robotTier: 0, 
    weaponTier: 0, 
    unlockedUnits: [RobotUnit.SENTINEL] 
  });
  const [briefing, setBriefing] = useState<LevelInfo | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [hasSave, setHasSave] = useState(false);
  const [shopOrigin, setShopOrigin] = useState<GameState>(GameState.MENU);
  const [saveFeedback, setSaveFeedback] = useState(false);

  // Load progress on mount
  useEffect(() => {
    const savedData = localStorage.getItem(SAVE_KEY);
    if (savedData) {
      const parsed = JSON.parse(savedData);
      setHasSave(true);
      const savedLvl = parsed.level || 1;
      setLevel(savedLvl);
      setMaxUnlockedLevel(parsed.maxUnlockedLevel || savedLvl || 1);
      setMoney(parsed.money || 0);
      setUpgrades(parsed.upgrades || { 
        robotTier: 0, 
        weaponTier: 0, 
        unlockedUnits: [RobotUnit.SENTINEL] 
      });
    }
  }, []);

  // Global pause listener
  useEffect(() => {
    const handleGlobalKeyDown = (e: KeyboardEvent) => {
      if (e.code === 'KeyP') {
        setGameState(prev => {
          if (prev === GameState.PLAYING) return GameState.PAUSED;
          if (prev === GameState.PAUSED) return GameState.PLAYING;
          return prev;
        });
      }
    };
    window.addEventListener('keydown', handleGlobalKeyDown);
    return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, []);

  const saveToStorage = useCallback(() => {
    const saveData = {
      level,
      maxUnlockedLevel,
      money,
      upgrades
    };
    localStorage.setItem(SAVE_KEY, JSON.stringify(saveData));
    setHasSave(true);
    setSaveFeedback(true);
    setTimeout(() => setSaveFeedback(false), 2000);
  }, [level, maxUnlockedLevel, money, upgrades]);

  useEffect(() => {
    if (gameState !== GameState.MENU && gameState !== GameState.PAUSED && gameState !== GameState.LEVEL_SELECT) {
      const saveData = {
        level,
        maxUnlockedLevel,
        money,
        upgrades
      };
      localStorage.setItem(SAVE_KEY, JSON.stringify(saveData));
    }
  }, [level, maxUnlockedLevel, money, upgrades, gameState]);

  const startLevel = useCallback(async (lvl: number) => {
    setIsLoading(true);
    setGameState(GameState.BRIEFING);
    setLevel(lvl);
    const data = await getLevelBriefing(lvl);
    setBriefing(data);
    setIsLoading(false);
  }, []);

  const handleStartGame = () => {
    setLevel(1);
    setMaxUnlockedLevel(1);
    setMoney(0);
    setUpgrades({ robotTier: 0, weaponTier: 0, unlockedUnits: [RobotUnit.SENTINEL] });
    startLevel(1);
  };

  const handleContinueGame = () => {
    const savedData = localStorage.getItem(SAVE_KEY);
    if (savedData) {
      const parsed = JSON.parse(savedData);
      const targetLevel = parsed.level || 1;
      setLevel(targetLevel);
      setMaxUnlockedLevel(parsed.maxUnlockedLevel || targetLevel || 1);
      setMoney(parsed.money || 0);
      setUpgrades(parsed.upgrades || { 
        robotTier: 0, 
        weaponTier: 0, 
        unlockedUnits: [RobotUnit.SENTINEL] 
      });
      startLevel(targetLevel);
    }
  };

  const handleLevelComplete = () => {
    setMoney(prev => prev + 50); 
    const completedLevel = level;
    const nextLvl = level + 1;

    if (nextLvl > maxUnlockedLevel) {
      setMaxUnlockedLevel(nextLvl);
    }

    if (completedLevel >= 20) {
      setGameState(GameState.VICTORY);
    } else {
      setLevel(nextLvl);
      setGameState(GameState.LEVEL_COMPLETE);
    }
  };

  const openShop = (origin: GameState) => {
    setShopOrigin(origin);
    setGameState(GameState.SHOP);
  };

  const openRobotShop = () => {
    setGameState(GameState.ROBOT_SHOP);
  };

  const openLevelSelect = () => {
    setGameState(GameState.LEVEL_SELECT);
  };

  const handleSelectLevel = (lvlNum: number) => {
    startLevel(lvlNum);
  };

  const handleNextLevel = () => {
    startLevel(level);
  };

  const handleShopExit = () => {
    if (shopOrigin === GameState.MENU) {
      setGameState(GameState.MENU);
      setHasSave(true);
    } else {
      handleNextLevel();
    }
  };

  const handlePlayerDeath = () => {
    setGameState(GameState.GAMEOVER);
  };

  const handleRetry = () => {
    startLevel(level);
  };

  const buyRobotTier = () => {
    if (money >= 100) {
      setMoney(m => m - 100);
      setUpgrades(u => ({ ...u, robotTier: u.robotTier + 1 }));
    }
  };

  const buyWeaponTier = () => {
    if (money >= 50) {
      setMoney(m => m - 50);
      setUpgrades(u => ({ ...u, weaponTier: u.weaponTier + 1 }));
    }
  };

  const unlockRobotUnit = (unit: RobotUnit, price: number) => {
    if (money >= price && !upgrades.unlockedUnits.includes(unit)) {
      setMoney(m => m - price);
      setUpgrades(u => ({
        ...u,
        unlockedUnits: [...u.unlockedUnits, unit]
      }));
    }
  };

  const isGameVisible = gameState === GameState.PLAYING || gameState === GameState.PAUSED;

  return (
    <div className="w-full h-screen bg-black overflow-hidden select-none text-white font-rajdhani">
      {/* Global Save Button */}
      <button 
        onClick={saveToStorage}
        className={`fixed top-4 right-4 z-[100] px-4 py-2 border font-bold text-xs uppercase tracking-widest transition-all font-orbitron shadow-lg ${
          saveFeedback 
            ? 'bg-emerald-600 border-emerald-400 text-white animate-pulse' 
            : 'bg-cyan-950/80 border-cyan-500 text-cyan-400 hover:bg-cyan-500 hover:text-black'
        }`}
      >
        {saveFeedback ? 'SYSTEM SAVED' : 'SAVE PROGRESS'}
      </button>

      {gameState === GameState.MENU && (
        <MainMenu 
          onStart={handleStartGame} 
          onContinue={handleContinueGame} 
          onOpenShop={() => openShop(GameState.MENU)}
          onOpenRobotShop={openRobotShop}
          onOpenLevelSelect={openLevelSelect}
          hasSave={hasSave} 
        />
      )}

      {gameState === GameState.LEVEL_SELECT && (
        <LevelSelect 
          currentUnlocked={maxUnlockedLevel} 
          onSelect={handleSelectLevel} 
          onBack={() => setGameState(GameState.MENU)} 
        />
      )}

      {gameState === GameState.BRIEFING && briefing && (
        <Briefing 
          briefing={briefing} 
          isLoading={isLoading} 
          onConfirm={() => setGameState(GameState.PLAYING)} 
        />
      )}

      {isGameVisible && (
        <GameView 
          level={level} 
          upgrades={upgrades}
          isPaused={gameState === GameState.PAUSED}
          onWin={handleLevelComplete} 
          onDie={handlePlayerDeath} 
        />
      )}

      {gameState === GameState.PAUSED && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex flex-col items-center justify-center z-50 animate-in fade-in duration-200">
          <div className="p-10 border-2 border-cyan-500 bg-black/80 relative overflow-hidden group">
            <div className="absolute top-0 left-0 w-full h-1 bg-cyan-500 animate-scan"></div>
            <h2 className="text-6xl font-black text-cyan-400 italic tracking-tighter uppercase mb-4">SYSTEM SUSPENDED</h2>
            <p className="text-cyan-200 font-mono tracking-widest text-center mb-8">TACTICAL ANALYSIS IN PROGRESS</p>
            <div className="flex flex-col gap-4 items-center">
              <button 
                onClick={() => setGameState(GameState.PLAYING)}
                className="px-12 py-4 bg-cyan-600 hover:bg-cyan-500 text-white font-bold text-2xl border-b-4 border-cyan-900 transition-all w-full uppercase"
              >
                RESUME MISSION
              </button>
              <button 
                onClick={() => setGameState(GameState.MENU)}
                className="px-12 py-2 text-cyan-400 font-bold hover:text-white transition-all uppercase text-sm"
              >
                ABORT TO HQ
              </button>
            </div>
          </div>
        </div>
      )}

      {gameState === GameState.LEVEL_COMPLETE && (
        <div className="fixed inset-0 bg-black/90 flex flex-col items-center justify-center z-50">
          <h2 className="text-5xl text-cyan-400 mb-2 font-black italic tracking-tighter animate-pulse uppercase">
            Sector {level - 1} Secured
          </h2>
          <div className="text-2xl text-yellow-400 mb-8 font-bold tracking-widest font-orbitron">REWARD EARNED: $50</div>
          <div className="flex gap-4 mb-4">
            <button 
              onClick={() => openShop(GameState.LEVEL_COMPLETE)}
              className="px-8 py-4 bg-yellow-600 hover:bg-yellow-500 text-white font-bold rounded-sm border-b-4 border-yellow-800 transition-all active:translate-y-1 w-64 shadow-[0_0_20px_rgba(202,138,4,0.3)] font-orbitron uppercase"
            >
              VISIT ARMORY
            </button>
            <button 
              onClick={() => setGameState(GameState.ROBOT_SHOP)}
              className="px-8 py-4 bg-purple-700 hover:bg-purple-600 text-white font-bold rounded-sm border-b-4 border-purple-900 transition-all active:translate-y-1 w-64 shadow-[0_0_20px_rgba(168,85,247,0.3)] font-orbitron uppercase"
            >
              SQUAD ASSEMBLY
            </button>
          </div>
          <button 
            onClick={handleNextLevel}
            className="px-12 py-3 bg-cyan-700 hover:bg-cyan-600 text-white font-bold rounded-sm transition-all w-[33rem] uppercase tracking-wider font-orbitron"
          >
            Deploy to Sector {level}
          </button>
          <button 
            onClick={() => {
              setGameState(GameState.MENU);
              setHasSave(true);
            }}
            className="px-12 py-2 text-gray-400 font-bold hover:text-white transition-all uppercase text-sm mt-8 border border-gray-800 hover:border-gray-400 bg-gray-950/40"
          >
            Return to HQ
          </button>
        </div>
      )}

      {gameState === GameState.SHOP && (
        <Shop 
          money={money} 
          upgrades={upgrades} 
          onBuyRobot={buyRobotTier} 
          onBuyWeapon={buyWeaponTier} 
          onExit={handleShopExit}
          isFromMenu={shopOrigin === GameState.MENU}
        />
      )}

      {gameState === GameState.ROBOT_SHOP && (
        <RobotShop 
          money={money} 
          unlockedUnits={upgrades.unlockedUnits} 
          onUnlock={unlockRobotUnit} 
          onExit={() => setGameState(GameState.MENU)}
        />
      )}

      {gameState === GameState.GAMEOVER && (
        <GameOver level={level} onRetry={handleRetry} onMenu={() => setGameState(GameState.MENU)} />
      )}

      {gameState === GameState.VICTORY && (
        <Victory onMenu={() => {
          localStorage.removeItem(SAVE_KEY);
          setHasSave(false);
          setGameState(GameState.MENU);
        }} />
      )}
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const SQUAD_UNION_DURATION = 60 * 60; // 60 seconds (1 minute) at 60fps

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { 
    name: "SENTINEL", color: '#00f3ff', hpMult: 1.0, 
    robot: { speed: 4, jump: -11, fireRate: 15 },
