const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [currentUnit, setCurrentUnit] = useState<RobotUnit>(RobotUnit.SENTINEL);
  const [isTransformed, setIsTransformed] = useState(false);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [unionTime, setUnionTime] = useState(0);

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      health: 100,
      maxHealth: 100,
      isTransformed: false,
      unionTimer: 0,
      history: [] as {x: number, y: number}[],
      checkpoint: { x: 100, y: 300, reached: false }
    },
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    unit: RobotUnit.SENTINEL,
    level: level,
  });

  useEffect(() => { engineRef.current.isPaused = isPaused; }, [isPaused]);
  useEffect(() => { engineRef.current.level = level; }, [level]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4, border = true) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff66');
    grad.addColorStop(1, '#000000aa');
    ctx.fillStyle = grad;
    ctx.fill();
    if (border) {
      ctx.strokeStyle = 'rgba(0,0,0,0.6)';
      ctx.lineWidth = 1;
      ctx.stroke();
    }
  };

  const drawCombiner = (ctx: CanvasRenderingContext2D, frame: number, alpha: number, isEnemy = false) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(1.8, 1.8);
    ctx.shadowBlur = 15;
    ctx.shadowColor = isEnemy ? '#ff0055' : '#fff';

    const primaryColor = isEnemy ? '#ff0055' : '#00f3ff';
    const secondaryColor = isEnemy ? '#440022' : '#ef4444';

    drawMechanicalPart(ctx, -15, -20, 30, 35, primaryColor, 6);
    drawMechanicalPart(ctx, -10, -15, 20, 20, secondaryColor, 4);
    ctx.fillStyle = isEnemy ? '#ff0000' : '#fff';
    ctx.beginPath();
    ctx.arc(0, -5, 6 + Math.sin(frame * 0.2) * 2, 0, Math.PI * 2);
    ctx.fill();
    drawMechanicalPart(ctx, -8, -38, 16, 16, '#111', 8);
    ctx.fillStyle = '#fff';
    ctx.fillRect(-5, -30, 10, 2);

    ctx.fillStyle = isEnemy ? '#ff5555' : '#22d3ee';
    ctx.beginPath(); ctx.moveTo(-15, -15); ctx.lineTo(-45, -40); ctx.lineTo(-15, 5); ctx.fill();
    ctx.beginPath(); ctx.moveTo(15, -15); ctx.lineTo(45, -40); ctx.lineTo(15, 5); ctx.fill();

    drawMechanicalPart(ctx, -22, -25, 12, 12, '#fbbf24', 2);
    drawMechanicalPart(ctx, 10, -25, 12, 12, '#fbbf24', 2);

    const legSwing = Math.sin(frame * 0.15) * 5;
    drawMechanicalPart(ctx, -12, 15, 12, 22 + legSwing, '#333', 4);
    drawMechanicalPart(ctx, 0, 15, 12, 22 - legSwing, '#333', 4);
    ctx.restore();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, type = 'bot', alpha = 1, tier = 0) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8;
    const armSwing = Math.cos(time) * 10;
    let scale = 1;
    if (type === 'scout') scale = 0.8;
    if (type === 'heavy' || type === 'titan') scale = 1.4;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(scale, scale);
    drawMechanicalPart(ctx, -12, -18, 24, 28, color, 4);
    if (!isEnemy && tier > 0) {
      drawMechanicalPart(ctx, -18, -22, 12, 10, '#333', 2);
      drawMechanicalPart(ctx, 6, -22, 12, 10, '#333', 2);
      ctx.fillStyle = '#fff'; ctx.shadowBlur = 10; ctx.shadowColor = color; ctx.beginPath(); ctx.arc(0, -6, 4, 0, Math.PI * 2); ctx.fill(); ctx.shadowBlur = 0;
    }
    if (!isEnemy && tier > 1) {
      drawMechanicalPart(ctx, -14, 10, 8, 8, '#444', 1); drawMechanicalPart(ctx, 6, 10, 8, 8, '#444', 1);
      drawMechanicalPart(ctx, -20, -10, 6, 12, '#555', 1); drawMechanicalPart(ctx, 14, -10, 6, 12, '#555', 1);
    }
    if (!isEnemy && tier > 2) {
      drawMechanicalPart(ctx, -4, -38, 8, 10, color, 2);
      ctx.fillStyle = '#00f3ff'; ctx.beginPath(); ctx.moveTo(-20, -15); ctx.lineTo(-35, -35); ctx.lineTo(-20, -5); ctx.fill();
      ctx.beginPath(); ctx.moveTo(20, -15); ctx.lineTo(35, -35); ctx.lineTo(20, -5); ctx.fill();
    }
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? '#ff0000' : '#00f3ff'; ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);
    ctx.restore();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, color: string, frame: number, alpha = 1, tier = 0) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    switch(unit) {
      case RobotUnit.SENTINEL:
        drawMechanicalPart(ctx, -28, -10, 56, 20, color, 8);
        drawMechanicalPart(ctx, -18, -22, 36, 14, '#111', 4);
        ctx.fillStyle = frame % 10 < 5 ? '#ff0000' : '#0000ff'; ctx.fillRect(-6, -24, 12, 4);
        ctx.fillStyle = '#111'; ctx.beginPath(); ctx.arc(-18, 12, 8, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.arc(18, 12, 8, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = '#ffffaa'; ctx.fillRect(20, -4, 8, 6);
        if (tier > 0) { ctx.fillStyle = '#fff'; ctx.fillRect(-20, -6, 40, 4); }
        break;
      case RobotUnit.TITAN:
        drawMechanicalPart(ctx, -35, -8, 70, 24, color, 4);
        drawMechanicalPart(ctx, -18, -26, 36, 18, '#222', 4);
        drawMechanicalPart(ctx, 12, -22, 30, 8, '#444', 1);
        ctx.fillStyle = '#111'; ctx.fillRect(-33, 10, 66, 8);
        break;
      case RobotUnit.FALCON:
        drawMechanicalPart(ctx, -24, -8, 48, 16, color, 12);
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.moveTo(-10, -5); ctx.lineTo(-40, -20); ctx.lineTo(-10, 10); ctx.fill();
        ctx.fillStyle = '#ffaa00'; ctx.fillRect(-35, -5, 10, 6);
        break;
      default:
        drawMechanicalPart(ctx, -25, -12, 50, 24, color, 6);
        drawMechanicalPart(ctx, -10, -22, 20, 10, '#333', 2);
        break;
    }
    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy = false, isInvuln = false, isTransformed = false, type = 'bot', alpha = 1, tier = 0, isCombiner = false) => {
    if (isInvuln && frame % 4 < 2) return;
    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    if (facing === -1) ctx.scale(-1, 1);
    if (isCombiner) {
      drawCombiner(ctx, frame, alpha, isEnemy);
    } else {
      const stats = ROBOT_STATS[unit];
      const color = isEnemy ? '#ff0055' : (stats?.color || '#00f3ff');
      if (isTransformed) {
        drawAltMode(ctx, unit, color, frame, alpha, tier);
      } else {
        drawHumanoid(ctx, color, frame, isEnemy, type, alpha, tier);
      }
    }
    ctx.restore();
  };

  const resetLevel = useCallback((fullReset = true) => {
    const e = engineRef.current;
    const stats = ROBOT_STATS[e.unit];
    const baseHP = 100 + (upgrades.robotTier * 50);

    if (fullReset) {
      e.player.maxHealth = baseHP * stats.hpMult;
      e.player.health = e.player.maxHealth;
      e.player.unionTimer = 0;
      setUnionTime(0);
      setMaxHealth(e.player.maxHealth);
      setHealth(e.player.health);
      e.player.pos = { x: 100, y: 300 };
      e.player.checkpoint.reached = false;
      e.player.vel = { x: 0, y: 0 };
      e.player.invulnerable = 0;
      e.player.isTransformed = false;
      setIsTransformed(false);
      e.bullets = [];
      e.cameraX = 0;

      const enemies: Enemy[] = [];
      const floorY = 398;

      const enemyCount = 5;
      for (let i = 0; i < enemyCount; i++) {
        const isBoss = i === enemyCount - 1;
        if (isBoss) {
          // Last enemy is a combiner boss
          enemies.push({
            id: i, pos: { x: 1000 + i * 800, y: floorY - 80 }, vel: { x: 0, y: 0 },
            width: 64, height: 80, health: 500 + (e.level * 100), maxHealth: 500 + (e.level * 100),
            isDead: false, type: 'combinerBoss', lastShot: 0, hasSplit: false, unit: RobotUnit.SENTINEL
          });
        } else if (e.level === 5) {
          enemies.push({ 
            id: i, pos: { x: 1200 + i * 900, y: floorY - 32 }, vel: { x: 0, y: 0 }, 
            width: 70, height: 40, health: 1000, maxHealth: 1000, 
            isDead: false, type: 'heavy', lastShot: 0, isTransformed: true, unit: RobotUnit.TITAN 
          });
        } else {
          const enemyTypes = ['bot', 'scout', 'sniper', 'heavy'];
          const type = enemyTypes[i % (e.level < 5 ? 1 : e.level < 10 ? 2 : 4)];
          let w = 32, h = 48;
          if (type === 'scout') { w = 24; h = 36; }
          if (type === 'heavy') { w = 48; h = 72; }
          enemies.push({ 
            id: i, pos: { x: 800 + i * 800, y: floorY - h }, vel: { x: 0, y: 0 }, 
            width: w, height: h, health: 100, maxHealth: 100, 
            isDead: false, type: type, lastShot: 0, unit: RobotUnit.SENTINEL 
          });
        }
      }
      e.enemies = enemies;
    }
  }, [upgrades.robotTier]);

  useEffect(() => {
    resetLevel(true);
  }, [level, resetLevel]);

  useEffect(() => {
    const e = engineRef.current;
    const handleKeyDown = (ev: KeyboardEvent) => {
      e.keys[ev.code] = true;
      if (ev.code === 'ShiftLeft' || ev.code === 'ShiftRight') {
        e.player.isTransformed = !e.player.isTransformed;
        setIsTransformed(e.player.isTransformed);
      }
      if (ev.code === 'KeyC' && e.player.unionTimer <= 0) {
        e.player.unionTimer = SQUAD_UNION_DURATION;
        e.player.health = 500;
        e.player.maxHealth = 500;
        setHealth(500);
        setMaxHealth(500);
        soundService.playFly();
      }
      const trySwitch = (unit: RobotUnit) => {
        if (upgrades.unlockedUnits.includes(unit)) {
          e.unit = unit;
          setCurrentUnit(unit);
          if (e.player.unionTimer <= 0) {
             const stats = ROBOT_STATS[unit];
             const baseHP = 100 + (upgrades.robotTier * 50);
             e.player.maxHealth = baseHP * stats.hpMult;
             e.player.health = Math.min(e.player.health, e.player.maxHealth);
             setHealth(e.player.health);
             setMaxHealth(e.player.maxHealth);
          }
        }
      };
      if (ev.code === 'Digit1') trySwitch(RobotUnit.SENTINEL);
      if (ev.code === 'Digit2') trySwitch(RobotUnit.STRIKER);
      if (ev.code === 'Digit3') trySwitch(RobotUnit.FALCON);
      if (ev.code === 'Digit4') trySwitch(RobotUnit.TITAN);
      if (ev.code === 'Digit5') trySwitch(RobotUnit.SPECTER);
    };
    const handleKeyUp = (ev: KeyboardEvent) => { e.keys[ev.code] = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!e.isPaused) update();
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const isCombiner = e.player.unionTimer > 0;
      const stats = ROBOT_STATS[e.unit];
      const currentStats = e.player.isTransformed ? stats.alt : stats.robot;
      e.frame++;

      if (isCombiner) {
        e.player.unionTimer--;
        if (e.frame % 10 === 0) setUnionTime(e.player.unionTimer);
        if (e.player.unionTimer === 0) {
          const baseHP = 100 + (upgrades.robotTier * 50);
          e.player.maxHealth = baseHP * stats.hpMult;
          e.player.health = Math.min(e.player.health, e.player.maxHealth);
          setHealth(e.player.health);
          setMaxHealth(e.player.maxHealth);
        }
      }

      const ph = isCombiner ? 80 : (e.player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48));
      const pw = isCombiner ? 64 : (e.player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32));

      const moveSpeed = isCombiner ? 6 : currentStats.speed;
      if (e.keys['ArrowRight'] || e.keys['KeyD']) { e.player.vel.x = moveSpeed; e.player.facing = 1; }
      else if (e.keys['ArrowLeft'] || e.keys['KeyA']) { e.player.vel.x = -moveSpeed; e.player.facing = -1; }
      else { e.player.vel.x *= 0.8; }

      if (e.unit === RobotUnit.FALCON && e.player.isTransformed) {
        if (e.keys['ArrowUp'] || e.keys['KeyW']) e.player.vel.y = -moveSpeed;
        else if (e.keys['ArrowDown'] || e.keys['KeyS']) e.player.vel.y = moveSpeed;
        else e.player.vel.y *= 0.9;
      } else {
        const jumpPower = isCombiner ? -15 : currentStats.jump;
        if ((e.keys['ArrowUp'] || e.keys['KeyW'] || e.keys['Space']) && e.player.grounded) {
          e.player.vel.y = jumpPower;
          e.player.grounded = false;
        }
        e.player.vel.y += GRAVITY;
      }

      e.player.pos.x += e.player.vel.x;
      e.player.pos.y += e.player.vel.y;
      const floorY = 398;
      if (e.player.pos.y > floorY - ph) { e.player.pos.y = floorY - ph; e.player.vel.y = 0; e.player.grounded = true; }
      if (e.player.pos.x < 0) e.player.pos.x = 0;

      const fr = isCombiner ? 8 : Math.max(5, currentStats.fireRate - upgrades.weaponTier * 2);
      if (e.keys['Space'] && e.frame - e.player.lastShot > fr) {
        soundService.playShoot();
        const dmg = isCombiner ? 500 : 100; // Player bullets deal massive damage
        if (isCombiner) {
          e.bullets.push({ pos: { x: e.player.pos.x + (e.player.facing === 1 ? pw : 0), y: e.player.pos.y + ph/2 - 10 }, vel: { x: e.player.facing * 20, y: 0 }, width: 32, height: 20, owner: 'player', health: 1, maxHealth: 1, damage: dmg, color: '#fff' });
        } else {
          e.bullets.push({ pos: { x: e.player.pos.x + (e.player.facing === 1 ? pw : 0), y: e.player.pos.y + ph/2 }, vel: { x: e.player.facing * 15, y: 0 }, width: 12, height: 4, owner: 'player', health: 1, maxHealth: 1, damage: dmg, color: stats.color });
        }
        e.player.lastShot = e.frame;
      }

      for (let i = e.bullets.length - 1; i >= 0; i--) {
        const b = e.bullets[i]; b.pos.x += b.vel.x; b.pos.y += b.vel.y;
        if (b.owner === 'enemy' && !e.player.invulnerable) {
          if (b.pos.x < e.player.pos.x + pw && b.pos.x + b.width > e.player.pos.x && b.pos.y < e.player.pos.y + ph && b.pos.y + b.height > e.player.pos.y) {
            e.player.health = Math.max(0, e.player.health - 20); e.player.invulnerable = 40;
            setHealth(e.player.health);
            e.bullets.splice(i, 1); soundService.playLose(); continue;
          }
        }
        if (Math.abs(b.pos.x - e.player.pos.x) > 1000) e.bullets.splice(i, 1);
      }

      let allDead = true;
      const newEnemies: Enemy[] = [];
      e.enemies.forEach(en => {
        if (en.isDead) return;
        allDead = false;

        // Split logic for combiner boss
        if (en.type === 'combinerBoss' && !en.hasSplit && en.health < en.maxHealth * 0.2) {
          en.isDead = true;
          en.hasSplit = true;
          soundService.playFly(); // Power surge sound
          for (let s = 0; s < 6; s++) {
            newEnemies.push({
              id: Date.now() + s,
              pos: { x: en.pos.x + (Math.random() - 0.5) * 100, y: en.pos.y + (Math.random() - 0.5) * 50 },
              vel: { x: (Math.random() - 0.5) * 10, y: -5 },
              width: 24, height: 36, health: 100, maxHealth: 100,
              isDead: false, type: 'scout', lastShot: e.frame, unit: RobotUnit.STRIKER
            });
          }
          return;
        }

        const dir = Math.sign(e.player.pos.x - en.pos.x);
        en.pos.x += dir * (en.type === 'scout' ? 2 : 0.5);
        if (Math.abs(en.pos.x - e.player.pos.x) < 500 && e.frame - en.lastShot > (en.type === 'combinerBoss' ? 60 : 120)) {
          e.bullets.push({ pos: {x: en.pos.x, y: en.pos.y + 15}, vel: {x: dir * 6, y: 0}, width: 10, height: 4, owner: 'enemy', health: 1, maxHealth: 1, damage: 20, color: '#f00' });
          en.lastShot = e.frame;
        }

        e.bullets.forEach((b, bIdx) => {
          if (b.owner === 'player' && !en.isDead && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) {
            en.health -= (b.damage || 100);
            if (en.health <= 0) en.isDead = true;
            e.bullets.splice(bIdx, 1);
          }
        });
      });

      if (newEnemies.length > 0) e.enemies.push(...newEnemies);

      if (e.player.health <= 0) onDie();
      if (allDead && newEnemies.length === 0) onWin();
      if (e.player.invulnerable > 0) e.player.invulnerable--;
      e.cameraX = e.player.pos.x - CANVAS_WIDTH/3;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      ctx.fillStyle = '#050510'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
      ctx.fillStyle = '#111'; ctx.fillRect(0, 398, CANVAS_WIDTH, 52); ctx.strokeStyle = '#222';
      for(let i = 0; i < CANVAS_WIDTH; i += 40) ctx.strokeRect(i - (e.cameraX % 40), 398, 40, 52);

      e.enemies.forEach(en => { 
        if(!en.isDead) drawUnit(ctx, en.pos.x - e.cameraX, en.pos.y, en.width, en.height, en.unit || RobotUnit.SENTINEL, Math.sign(e.player.pos.x - en.pos.x), e.frame, true, false, en.isTransformed, en.type, 1, 0, en.type === 'combinerBoss'); 
      });

      const isCombiner = e.player.unionTimer > 0;
      const pw = isCombiner ? 64 : (e.player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32));
      const ph = isCombiner ? 80 : (e.player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48));
      drawUnit(ctx, e.player.pos.x - e.cameraX, e.player.pos.y, pw, ph, e.unit, e.player.facing, e.frame, false, e.player.invulnerable > 0, e.player.isTransformed, 'bot', 1, upgrades.robotTier, isCombiner);

      e.bullets.forEach(b => { 
        ctx.fillStyle = b.color || '#00f3ff'; 
        if (b.width > 20) { ctx.shadowBlur = 10; ctx.shadowColor = b.color || '#fff'; } 
        ctx.fillRect(b.pos.x - e.cameraX, b.pos.y, b.width, b.height); 
        ctx.shadowBlur = 0; 
      });
    };

    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [onWin, onDie, upgrades.unlockedUnits, upgrades.weaponTier, upgrades.robotTier]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden">
      <div className="absolute top-4 left-4 z-10 space-y-4 pointer-events-none w-[400px]">
        <div className="bg-black/80 border border-cyan-500/50 p-3 rounded backdrop-blur-md shadow-lg">
          <div className="text-[10px] text-cyan-400 font-bold uppercase mb-1 flex justify-between font-orbitron">
            <span>{unionTime > 0 ? 'SQUAD COMBINER' : `${ROBOT_STATS[currentUnit].name} CHASSIS [TIER ${upgrades.robotTier}]`}</span>
            <span>{Math.round(health)}/{Math.round(maxHealth)}</span>
          </div>
          <div className="w-48 h-2.5 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
            <div className="h-full shadow-[0_0_15px_#00f3ff] transition-all duration-300" style={{ width: `${(health / maxHealth) * 100}%`, backgroundColor: health < maxHealth * 0.3 ? '#ef4444' : (unionTime > 0 ? '#fff' : '#00f3ff') }} />
          </div>
          {unionTime > 0 && (
            <div className="mt-2">
              <div className="text-[8px] text-yellow-400 font-bold uppercase mb-0.5 font-orbitron">COMBINER INTEGRITY DURATION</div>
              <div className="w-full h-1 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
                <div className="h-full bg-yellow-500 shadow-[0_0_10px_#fbbf24] transition-all duration-100" style={{ width: `${(unionTime / SQUAD_UNION_DURATION) * 100}%` }} />
              </div>
            </div>
          )}
        </div>
      </div>
      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full aspect-video shadow-2xl rounded-lg border-2 border-cyan-900/50" />
      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 pointer-events-none text-white/30 text-[8px] font-mono tracking-widest uppercase flex gap-6">
        <span>WASD: Move</span><span>Space: Fire</span><span>Shift: Transform</span><span>1-5: Squad</span><span>C: COMBINE</span>
      </div>
      {unionTime > SQUAD_UNION_DURATION - 60 && (
        <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
          <div className="text-6xl font-black italic text-white font-orbitron tracking-tighter shadow-2xl animate-pulse">SQUAD COMBINATION ENGAGED</div>
        </div>
      )}
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const SQUAD_UNION_DURATION = 60 * 60; // 60 seconds (1 minute) at 60fps

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { 
    name: "SENTINEL", color: '#00f3ff', hpMult: 1.0, 
    robot: { speed: 4, jump: -11, fireRate: 15 },
    alt: { speed: 8, jump: -5, fireRate: 25, type: 'Car' }
  },
  [RobotUnit.STRIKER]: { 
    name: "STRIKER", color: '#fbbf24', hpMult: 0.8,
    robot: { speed: 6, jump: -10, fireRate: 10 },
    alt: { speed: 12, jump: -4, fireRate: 20, type: 'Bike' }
  },
  [RobotUnit.FALCON]: { 
    name: "FALCON", color: '#22d3ee', hpMult: 0.7,
    robot: { speed: 5, jump: -10, fireRate: 12 },
    alt: { speed: 7, jump: -7, fireRate: 15, type: 'Jet' }
  },
  [RobotUnit.TITAN]: { 
    name: "TITAN", color: '#ef4444', hpMult: 2.5,
    robot: { speed: 2.5, jump: -12, fireRate: 30 },
    alt: { speed: 4, jump: 0, fireRate: 20, type: 'Tank' }
  },
  [RobotUnit.SPECTER]: { 
    name: "SPECTER", color: '#a855f7', hpMult: 0.6,
    robot: { speed: 5, jump: -11, fireRate: 20 },
    alt: { speed: 6, jump: -14, fireRate: 40, type: 'Energy Sphere' }
  },
  [RobotUnit.VANGUARD]: { 
    name: "VANGUARD", color: '#10b981', hpMult: 2.0, 
    robot: { speed: 3.5, jump: -10, fireRate: 25 },
    alt: { speed: 6, jump: -4, fireRate: 30, type: 'Shield Truck' }
  },
  [RobotUnit.NIGHTSHADE]: { 
    name: "NIGHTSHADE", color: '#6366f1', hpMult: 0.9, 
    robot: { speed: 7, jump: -13, fireRate: 12 },
    alt: { speed: 10, jump: -6, fireRate: 18, type: 'Interceptor' }
  },
  [RobotUnit.BLAZE]: { 
    name: "BLAZE", color: '#f97316', hpMult: 1.2, 
    robot: { speed: 4.5, jump: -11, fireRate: 18 },
    alt: { speed: 7, jump: -5, fireRate: 22, type: 'Rig' }
  },
  [RobotUnit.GLITCH]: { 
    name: "GLITCH", color: '#ec4899', hpMult: 1.0, 
    robot: { speed: 5, jump: -12, fireRate: 14 },
    alt: { speed: 9, jump: -12, fireRate: 16, type: 'Splicer' }
  },
  [RobotUnit.OMEGA]: { 
    name: "OMEGA", color: '#ffffff', hpMult: 3.0, 
    robot: { speed: 6, jump: -14, fireRate: 10 },
    alt: { speed: 10, jump: -8, fireRate: 15, type: 'Fortress' }
  },
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [currentUnit, setCurrentUnit] = useState<RobotUnit>(RobotUnit.SENTINEL);
  const [isTransformed, setIsTransformed] = useState(false);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [unionTime, setUnionTime] = useState(0);

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      health: 100,
      maxHealth: 100,
      isTransformed: false,
      unionTimer: 0,
      history: [] as {x: number, y: number}[],
      checkpoint: { x: 100, y: 300, reached: false }
    },
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    isPaused: isPaused,
    unit: RobotUnit.SENTINEL,
    level: level,
  });

  useEffect(() => { engineRef.current.isPaused = isPaused; }, [isPaused]);
  useEffect(() => { engineRef.current.level = level; }, [level]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4, border = true) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff66');
    grad.addColorStop(1, '#000000aa');
    ctx.fillStyle = grad;
    ctx.fill();
    if (border) {
      ctx.strokeStyle = 'rgba(0,0,0,0.6)';
      ctx.lineWidth = 1;
      ctx.stroke();
    }
  };

  const drawCombiner = (ctx: CanvasRenderingContext2D, frame: number, alpha: number, isEnemy = false, scaleOverride?: number) => {
    ctx.save();
    ctx.globalAlpha = alpha;

    // Default combiner scale is 1.8. If scaleOverride exists (for the 10x Titan), we use that.
    const scale = scaleOverride || 1.8;
    ctx.scale(scale, scale);

    ctx.shadowBlur = isEnemy ? 25 : 15;
    ctx.shadowColor = isEnemy ? '#ff0055' : '#fff';

    const primaryColor = isEnemy ? '#ff0055' : '#00f3ff';
    const secondaryColor = isEnemy ? '#440022' : '#ef4444';

    // Massive Chest
    drawMechanicalPart(ctx, -15, -20, 30, 35, primaryColor, 6);
    drawMechanicalPart(ctx, -10, -15, 20, 20, secondaryColor, 4);

    // Core Reactor
    ctx.fillStyle = isEnemy ? '#ff0000' : '#fff';
    ctx.beginPath();
    ctx.arc(0, -5, 6 + Math.sin(frame * 0.2) * 2, 0, Math.PI * 2);
    ctx.fill();

    // Head unit
    drawMechanicalPart(ctx, -8, -38, 16, 16, '#111', 8);
    ctx.fillStyle = '#fff';
    ctx.fillRect(-5, -30, 10, 2);

    // Wings / Shoulder plates
    ctx.fillStyle = isEnemy ? '#ff5555' : '#22d3ee';
    ctx.beginPath(); ctx.moveTo(-15, -15); ctx.lineTo(-45, -40); ctx.lineTo(-15, 5); ctx.fill();
    ctx.beginPath(); ctx.moveTo(15, -15); ctx.lineTo(45, -40); ctx.lineTo(15, 5); ctx.fill();

    // Auxiliary engines
    drawMechanicalPart(ctx, -22, -25, 12, 12, '#fbbf24', 2);
    drawMechanicalPart(ctx, 10, -25, 12, 12, '#fbbf24', 2);

    // Heavy legs
    const legSwing = Math.sin(frame * 0.15) * 5;
    drawMechanicalPart(ctx, -12, 15, 12, 22 + legSwing, '#333', 4);
    drawMechanicalPart(ctx, 0, 15, 12, 22 - legSwing, '#333', 4);

    ctx.restore();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, type = 'bot', alpha = 1, tier = 0) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8;
    const armSwing = Math.cos(time) * 10;
    let scale = 1;
    if (type === 'scout') scale = 0.8;
    if (type === 'heavy' || type === 'titan') scale = 1.4;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(scale, scale);
    drawMechanicalPart(ctx, -12, -18, 24, 28, color, 4);
    if (!isEnemy && tier > 0) {
      drawMechanicalPart(ctx, -18, -22, 12, 10, '#333', 2);
      drawMechanicalPart(ctx, 6, -22, 12, 10, '#333', 2);
      ctx.fillStyle = '#fff'; ctx.shadowBlur = 10; ctx.shadowColor = color; ctx.beginPath(); ctx.arc(0, -6, 4, 0, Math.PI * 2); ctx.fill(); ctx.shadowBlur = 0;
    }
    if (!isEnemy && tier > 1) {
      drawMechanicalPart(ctx, -14, 10, 8, 8, '#444', 1); drawMechanicalPart(ctx, 6, 10, 8, 8, '#444', 1);
      drawMechanicalPart(ctx, -20, -10, 6, 12, '#555', 1); drawMechanicalPart(ctx, 14, -10, 6, 12, '#555', 1);
    }
    if (!isEnemy && tier > 2) {
      drawMechanicalPart(ctx, -4, -38, 8, 10, color, 2);
      ctx.fillStyle = '#00f3ff'; ctx.beginPath(); ctx.moveTo(-20, -15); ctx.lineTo(-35, -35); ctx.lineTo(-20, -5); ctx.fill();
      ctx.beginPath(); ctx.moveTo(20, -15); ctx.lineTo(35, -35); ctx.lineTo(20, -5); ctx.fill();
    }
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? '#ff0000' : '#00f3ff'; ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);
    ctx.restore();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, color: string, frame: number, alpha = 1, tier = 0) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    switch(unit) {
      case RobotUnit.SENTINEL:
        drawMechanicalPart(ctx, -28, -10, 56, 20, color, 8);
        drawMechanicalPart(ctx, -18, -22, 36, 14, '#111', 4);
        ctx.fillStyle = frame % 10 < 5 ? '#ff0000' : '#0000ff'; ctx.fillRect(-6, -24, 12, 4);
        ctx.fillStyle = '#111'; ctx.beginPath(); ctx.arc(-18, 12, 8, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.arc(18, 12, 8, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = '#ffffaa'; ctx.fillRect(20, -4, 8, 6);
        if (tier > 0) { ctx.fillStyle = '#fff'; ctx.fillRect(-20, -6, 40, 4); }
        break;
      case RobotUnit.TITAN:
        drawMechanicalPart(ctx, -35, -8, 70, 24, color, 4);
        drawMechanicalPart(ctx, -18, -26, 36, 18, '#222', 4);
        drawMechanicalPart(ctx, 12, -22, 30, 8, '#444', 1);
        ctx.fillStyle = '#111'; ctx.fillRect(-33, 10, 66, 8);
        break;
      case RobotUnit.FALCON:
        drawMechanicalPart(ctx, -24, -8, 48, 16, color, 12);
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.moveTo(-10, -5); ctx.lineTo(-40, -20); ctx.lineTo(-10, 10); ctx.fill();
        ctx.fillStyle = '#ffaa00'; ctx.fillRect(-35, -5, 10, 6);
        break;
      default:
        drawMechanicalPart(ctx, -25, -12, 50, 24, color, 6);
        drawMechanicalPart(ctx, -10, -22, 20, 10, '#333', 2);
        break;
    }
    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy = false, isInvuln = false, isTransformed = false, type = 'bot', alpha = 1, tier = 0, isCombiner = false) => {
    if (isInvuln && frame % 4 < 2) return;
    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    if (facing === -1) ctx.scale(-1, 1);

    if (isCombiner) {
      // If it's the Level 10 Titan, scale it 10x bigger than the player's combiner (1.8 * 10)
      const isGigantus = isEnemy && engineRef.current.level === 10;
      drawCombiner(ctx, frame, alpha, isEnemy, isGigantus ? 18 : undefined);
    } else {
      const stats = ROBOT_STATS[unit];
      const color = isEnemy ? '#ff0055' : (stats?.color || '#00f3ff');
      if (isTransformed) {
        drawAltMode(ctx, unit, color, frame, alpha, tier);
      } else {
        drawHumanoid(ctx, color, frame, isEnemy, type, alpha, tier);
      }
    }
    ctx.restore();
  };

  const resetLevel = useCallback((fullReset = true) => {
    const e = engineRef.current;
    const stats = ROBOT_STATS[e.unit];
    const baseHP = 100 + (upgrades.robotTier * 50);

    if (fullReset) {
      e.player.maxHealth = baseHP * stats.hpMult;
      e.player.health = e.player.maxHealth;
      e.player.unionTimer = 0;
      setUnionTime(0);
      setMaxHealth(e.player.maxHealth);
      setHealth(e.player.health);
      e.player.pos = { x: 100, y: 300 };
      e.player.checkpoint.reached = false;
      e.player.vel = { x: 0, y: 0 };
      e.player.invulnerable = 0;
      e.player.isTransformed = false;
      setIsTransformed(false);
      e.bullets = [];
      e.cameraX = 0;

      const enemies: Enemy[] = [];
      const floorY = 398;

      const enemyCount = 5;
      for (let i = 0; i < enemyCount; i++) {
        const isBoss = i === enemyCount - 1;
        if (isBoss) {
          // Final enemy on EACH level is a combiner boss
          // Level 10 is the Gigantus Titan (10x size)
          const isLvl10Titan = e.level === 10;
          const bossW = isLvl10Titan ? 640 : 64;
          const bossH = isLvl10Titan ? 800 : 80;
          const bossHP = isLvl10Titan ? 20000 : (500 + (e.level * 100));

          enemies.push({
            id: i, 
            pos: { x: 2000 + i * 800, y: floorY - bossH }, 
            vel: { x: 0, y: 0 },
            width: bossW, 
            height: bossH, 
            health: bossHP, 
            maxHealth: bossHP,
            isDead: false, 
            type: 'combinerBoss', 
            lastShot: 0, 
            hasSplit: false, 
            unit: RobotUnit.OMEGA
          });
        } else if (e.level === 5) {
          enemies.push({ 
            id: i, pos: { x: 1200 + i * 900, y: floorY - 32 }, vel: { x: 0, y: 0 }, 
            width: 70, height: 40, health: 1000, maxHealth: 1000, 
            isDead: false, type: 'heavy', lastShot: 0, isTransformed: true, unit: RobotUnit.TITAN 
          });
        } else {
          const enemyTypes = ['bot', 'scout', 'sniper', 'heavy'];
          const type = enemyTypes[i % (e.level < 5 ? 1 : e.level < 10 ? 2 : 4)];
          let w = 32, h = 48;
          if (type === 'scout') { w = 24; h = 36; }
          if (type === 'heavy') { w = 48; h = 72; }
          enemies.push({ 
            id: i, pos: { x: 800 + i * 800, y: floorY - h }, vel: { x: 0, y: 0 }, 
            width: w, height: h, health: 100, maxHealth: 100, 
            isDead: false, type: type, lastShot: 0, unit: RobotUnit.SENTINEL 
          });
        }
      }
      e.enemies = enemies;
    }
  }, [upgrades.robotTier]);

  useEffect(() => {
    resetLevel(true);
  }, [level, resetLevel]);

  useEffect(() => {
    const e = engineRef.current;
    const handleKeyDown = (ev: KeyboardEvent) => {
      e.keys[ev.code] = true;
      if (ev.code === 'ShiftLeft' || ev.code === 'ShiftRight') {
        e.player.isTransformed = !e.player.isTransformed;
        setIsTransformed(e.player.isTransformed);
      }
      if (ev.code === 'KeyC' && e.player.unionTimer <= 0) {
        e.player.unionTimer = SQUAD_UNION_DURATION;
        e.player.health = 500;
        e.player.maxHealth = 500;
        setHealth(500);
        setMaxHealth(500);
        soundService.playFly();
      }
      const trySwitch = (unit: RobotUnit) => {
        if (upgrades.unlockedUnits.includes(unit)) {
          e.unit = unit;
          setCurrentUnit(unit);
          if (e.player.unionTimer <= 0) {
             const stats = ROBOT_STATS[unit];
             const baseHP = 100 + (upgrades.robotTier * 50);
             e.player.maxHealth = baseHP * stats.hpMult;
             e.player.health = Math.min(e.player.health, e.player.maxHealth);
             setHealth(e.player.health);
             setMaxHealth(e.player.maxHealth);
          }
        }
      };
      if (ev.code === 'Digit1') trySwitch(RobotUnit.SENTINEL);
      if (ev.code === 'Digit2') trySwitch(RobotUnit.STRIKER);
      if (ev.code === 'Digit3') trySwitch(RobotUnit.FALCON);
      if (ev.code === 'Digit4') trySwitch(RobotUnit.TITAN);
      if (ev.code === 'Digit5') trySwitch(RobotUnit.SPECTER);
    };
    const handleKeyUp = (ev: KeyboardEvent) => { e.keys[ev.code] = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!e.isPaused) update();
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const isCombiner = e.player.unionTimer > 0;
      const stats = ROBOT_STATS[e.unit];
      const currentStats = e.player.isTransformed ? stats.alt : stats.robot;
      e.frame++;

      if (isCombiner) {
        e.player.unionTimer--;
        if (e.frame % 10 === 0) setUnionTime(e.player.unionTimer);
        if (e.player.unionTimer === 0) {
          const baseHP = 100 + (upgrades.robotTier * 50);
          e.player.maxHealth = baseHP * stats.hpMult;
          e.player.health = Math.min(e.player.health, e.player.maxHealth);
          setHealth(e.player.health);
          setMaxHealth(e.player.maxHealth);
        }
      }

      const ph = isCombiner ? 80 : (e.player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48));
      const pw = isCombiner ? 64 : (e.player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32));

      const moveSpeed = isCombiner ? 6 : currentStats.speed;
      if (e.keys['ArrowRight'] || e.keys['KeyD']) { e.player.vel.x = moveSpeed; e.player.facing = 1; }
      else if (e.keys['ArrowLeft'] || e.keys['KeyA']) { e.player.vel.x = -moveSpeed; e.player.facing = -1; }
      else { e.player.vel.x *= 0.8; }

      if (e.unit === RobotUnit.FALCON && e.player.isTransformed) {
        if (e.keys['ArrowUp'] || e.keys['KeyW']) e.player.vel.y = -moveSpeed;
        else if (e.keys['ArrowDown'] || e.keys['KeyS']) e.player.vel.y = moveSpeed;
        else e.player.vel.y *= 0.9;
      } else {
        const jumpPower = isCombiner ? -15 : currentStats.jump;
        if ((e.keys['ArrowUp'] || e.keys['KeyW'] || e.keys['Space']) && e.player.grounded) {
          e.player.vel.y = jumpPower;
          e.player.grounded = false;
        }
        e.player.vel.y += GRAVITY;
      }

      e.player.pos.x += e.player.vel.x;
      e.player.pos.y += e.player.vel.y;
      const floorY = 398;
      if (e.player.pos.y > floorY - ph) { e.player.pos.y = floorY - ph; e.player.vel.y = 0; e.player.grounded = true; }
      if (e.player.pos.x < 0) e.player.pos.x = 0;

      const fr = isCombiner ? 8 : Math.max(5, currentStats.fireRate - upgrades.weaponTier * 2);
      if (e.keys['Space'] && e.frame - e.player.lastShot > fr) {
        soundService.playShoot();
        const dmg = isCombiner ? 500 : 100;
        if (isCombiner) {
          e.bullets.push({ 
            pos: { x: e.player.pos.x + (e.player.facing === 1 ? pw : 0), y: e.player.pos.y + ph/2 - 10 }, 
            vel: { x: e.player.facing * 20, y: 0 }, 
            width: 32, height: 20, owner: 'player', health: 1, maxHealth: 1, damage: dmg, color: '#fff' 
          });
        } else {
          e.bullets.push({ 
            pos: { x: e.player.pos.x + (e.player.facing === 1 ? pw : 0), y: e.player.pos.y + ph/2 }, 
            vel: { x: e.player.facing * 15, y: 0 }, 
            width: 12, height: 4, owner: 'player', health: 1, maxHealth: 1, damage: dmg, color: stats.color 
          });
        }
        e.player.lastShot = e.frame;
      }

      for (let i = e.bullets.length - 1; i >= 0; i--) {
        const b = e.bullets[i]; b.pos.x += b.vel.x; b.pos.y += b.vel.y;
        if (b.owner === 'enemy' && !e.player.invulnerable) {
          if (b.pos.x < e.player.pos.x + pw && b.pos.x + b.width > e.player.pos.x && b.pos.y < e.player.pos.y + ph && b.pos.y + b.height > e.player.pos.y) {
            e.player.health = Math.max(0, e.player.health - 20); e.player.invulnerable = 40;
            setHealth(e.player.health);
            e.bullets.splice(i, 1); soundService.playLose(); continue;
          }
        }
        if (Math.abs(b.pos.x - e.player.pos.x) > 2000) e.bullets.splice(i, 1);
      }

      let allDead = true;
      const newEnemies: Enemy[] = [];
      e.enemies.forEach(en => {
        if (en.isDead) return;
        allDead = false;

        // Split logic for ANY combiner boss (including Level 10 Titan)
        if (en.type === 'combinerBoss' && !en.hasSplit && en.health < en.maxHealth * 0.2) {
          en.isDead = true;
          en.hasSplit = true;
          soundService.playFly();
          for (let s = 0; s < 6; s++) {
            newEnemies.push({
              id: Date.now() + s,
              pos: { 
                x: en.pos.x + (Math.random() * en.width), 
                y: en.pos.y + (Math.random() * en.height) 
              },
              vel: { x: (Math.random() - 0.5) * 15, y: -8 },
              width: 24, height: 36, health: 150, maxHealth: 150,
              isDead: false, type: 'scout', lastShot: e.frame, unit: RobotUnit.STRIKER
            });
          }
          return;
        }

        const dir = Math.sign(e.player.pos.x - en.pos.x);
        const speed = en.type === 'scout' ? 2.5 : (en.type === 'combinerBoss' ? 0.3 : 0.6);
        en.pos.x += dir * speed;

        // Firing logic
        const shootFreq = en.type === 'combinerBoss' ? 45 : (en.type === 'scout' ? 90 : 120);
        if (Math.abs(en.pos.x - e.player.pos.x) < 1000 && e.frame - en.lastShot > shootFreq) {
          const bW = en.type === 'combinerBoss' ? 24 : 10;
          const bH = en.type === 'combinerBoss' ? 10 : 4;
          e.bullets.push({ 
            pos: {x: en.pos.x + (dir > 0 ? en.width : 0), y: en.pos.y + en.height / 2}, 
            vel: {x: dir * 8, y: 0}, 
            width: bW, height: bH, owner: 'enemy', health: 1, maxHealth: 1, damage: 20, color: '#f00' 
          });
          en.lastShot = e.frame;
        }

        e.bullets.forEach((b, bIdx) => {
          if (b.owner === 'player' && !en.isDead && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) {
            en.health -= (b.damage || 100);
            if (en.health <= 0) en.isDead = true;
            e.bullets.splice(bIdx, 1);
          }
        });
      });

      if (newEnemies.length > 0) e.enemies.push(...newEnemies);

      if (e.player.health <= 0) onDie();
      if (allDead && newEnemies.length === 0) onWin();
      if (e.player.invulnerable > 0) e.player.invulnerable--;
      e.cameraX = e.player.pos.x - CANVAS_WIDTH/3;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      ctx.fillStyle = '#050510'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
      ctx.fillStyle = '#111'; ctx.fillRect(0, 398, CANVAS_WIDTH, 52); ctx.strokeStyle = '#222';
      for(let i = 0; i < CANVAS_WIDTH; i += 40) ctx.strokeRect(i - (e.cameraX % 40), 398, 40, 52);

      e.enemies.forEach(en => { 
        if(!en.isDead) drawUnit(ctx, en.pos.x - e.cameraX, en.pos.y, en.width, en.height, en.unit || RobotUnit.SENTINEL, Math.sign(e.player.pos.x - en.pos.x), e.frame, true, false, en.isTransformed, en.type, 1, 0, en.type === 'combinerBoss'); 
      });

      const isCombiner = e.player.unionTimer > 0;
      const pw = isCombiner ? 64 : (e.player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32));
      const ph = isCombiner ? 80 : (e.player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48));
      drawUnit(ctx, e.player.pos.x - e.cameraX, e.player.pos.y, pw, ph, e.unit, e.player.facing, e.frame, false, e.player.invulnerable > 0, e.player.isTransformed, 'bot', 1, upgrades.robotTier, isCombiner);

      e.bullets.forEach(b => { 
        ctx.fillStyle = b.color || '#00f3ff'; 
        if (b.width > 20) { ctx.shadowBlur = 10; ctx.shadowColor = b.color || '#fff'; } 
        ctx.fillRect(b.pos.x - e.cameraX, b.pos.y, b.width, b.height); 
        ctx.shadowBlur = 0; 
      });
    };

    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [onWin, onDie, upgrades.unlockedUnits, upgrades.weaponTier, upgrades.robotTier]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden">
      <div className="absolute top-4 left-4 z-10 space-y-4 pointer-events-none w-[400px]">
        <div className="bg-black/80 border border-cyan-500/50 p-3 rounded backdrop-blur-md shadow-lg">
          <div className="text-[10px] text-cyan-400 font-bold uppercase mb-1 flex justify-between font-orbitron">
            <span>{unionTime > 0 ? 'SQUAD COMBINER' : `${ROBOT_STATS[currentUnit].name} CHASSIS [TIER ${upgrades.robotTier}]`}</span>
            <span>{Math.round(health)}/{Math.round(maxHealth)}</span>
          </div>
          <div className="w-48 h-2.5 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
            <div className="h-full shadow-[0_0_15px_#00f3ff] transition-all duration-300" style={{ width: `${(health / maxHealth) * 100}%`, backgroundColor: health < maxHealth * 0.3 ? '#ef4444' : (unionTime > 0 ? '#fff' : '#00f3ff') }} />
          </div>
          {unionTime > 0 && (
            <div className="mt-2">
              <div className="text-[8px] text-yellow-400 font-bold uppercase mb-0.5 font-orbitron">COMBINER INTEGRITY DURATION</div>
              <div className="w-full h-1 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
                <div className="h-full bg-yellow-500 shadow-[0_0_10px_#fbbf24] transition-all duration-100" style={{ width: `${(unionTime / SQUAD_UNION_DURATION) * 100}%` }} />
              </div>
            </div>
          )}
        </div>
      </div>
      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full aspect-video shadow-2xl rounded-lg border-2 border-cyan-900/50" />
      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 pointer-events-none text-white/30 text-[8px] font-mono tracking-widest uppercase flex gap-6">
        <span>WASD: Move</span><span>Space: Fire</span><span>Shift: Transform</span><span>1-5: Squad</span><span>C: COMBINE</span>
      </div>
      {unionTime > SQUAD_UNION_DURATION - 60 && (
        <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
          <div className="text-6xl font-black italic text-white font-orbitron tracking-tighter shadow-2xl animate-pulse">SQUAD COMBINATION ENGAGED</div>
        </div>
      )}
      {level === 10 && (
        <div className="absolute top-20 right-4 p-4 border border-red-500 bg-red-950/20 text-red-500 font-orbitron text-xs animate-pulse uppercase tracking-widest">
           WARNING: GIGANTUS TITAN DETECTED IN SECTOR
        </div>
      )}
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const SQUAD_UNION_DURATION = 60 * 60; // 60 seconds (1 minute) at 60fps

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { 
    name: "SENTINEL", color: '#00f3ff', hpMult: 1.0, 
    robot: { speed: 4, jump: -11, fireRate: 15 },
    alt: { speed: 8, jump: -5, fireRate: 25, type: 'Car' }
  },
  [RobotUnit.STRIKER]: { 
    name: "STRIKER", color: '#fbbf24', hpMult: 0.8,
    robot: { speed: 6, jump: -10, fireRate: 10 },
    alt: { speed: 12, jump: -4, fireRate: 20, type: 'Bike' }
  },
  [RobotUnit.FALCON]: { 
    name: "FALCON", color: '#22d3ee', hpMult: 0.7,
    robot: { speed: 5, jump: -10, fireRate: 12 },
    alt: { speed: 7, jump: -7, fireRate: 15, type: 'Jet' }
  },
  [RobotUnit.TITAN]: { 
    name: "TITAN", color: '#ef4444', hpMult: 2.5,
    robot: { speed: 2.5, jump: -12, fireRate: 30 },
    alt: { speed: 4, jump: 0, fireRate: 20, type: 'Tank' }
  },
  [RobotUnit.SPECTER]: { 
    name: "SPECTER", color: '#a855f7', hpMult: 0.6,
    robot: { speed: 5, jump: -11, fireRate: 20 },
    alt: { speed: 6, jump: -14, fireRate: 40, type: 'Energy Sphere' }
  },
  [RobotUnit.VANGUARD]: { 
    name: "VANGUARD", color: '#10b981', hpMult: 2.0, 
    robot: { speed: 3.5, jump: -10, fireRate: 25 },
    alt: { speed: 6, jump: -4, fireRate: 30, type: 'Shield Truck' }
  },
  [RobotUnit.NIGHTSHADE]: { 
    name: "NIGHTSHADE", color: '#6366f1', hpMult: 0.9, 
    robot: { speed: 7, jump: -13, fireRate: 12 },
    alt: { speed: 10, jump: -6, fireRate: 18, type: 'Interceptor' }
  },
  [RobotUnit.BLAZE]: { 
    name: "BLAZE", color: '#f97316', hpMult: 1.2, 
    robot: { speed: 4.5, jump: -11, fireRate: 18 },
    alt: { speed: 7, jump: -5, fireRate: 22, type: 'Rig' }
  },
  [RobotUnit.GLITCH]: { 
    name: "GLITCH", color: '#ec4899', hpMult: 1.0, 
    robot: { speed: 5, jump: -12, fireRate: 14 },
    alt: { speed: 9, jump: -12, fireRate: 16, type: 'Splicer' }
  },
  [RobotUnit.OMEGA]: { 
    name: "OMEGA", color: '#ffffff', hpMult: 3.0, 
    robot: { speed: 6, jump: -14, fireRate: 10 },
    alt: { speed: 10, jump: -8, fireRate: 15, type: 'Fortress' }
  },
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [currentUnit, setCurrentUnit] = useState<RobotUnit>(RobotUnit.SENTINEL);
  const [isTransformed, setIsTransformed] = useState(false);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [unionTime, setUnionTime] = useState(0);

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      health: 100,
      maxHealth: 100,
      isTransformed: false,
      unionTimer: 0,
      history: [] as {x: number, y: number}[],
      checkpoint: { x: 100, y: 300, reached: false }
    },
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    cameraY: 0,
    zoom: 1.0,
    isPaused: isPaused,
    unit: RobotUnit.SENTINEL,
    level: level,
  });

  useEffect(() => { engineRef.current.isPaused = isPaused; }, [isPaused]);
  useEffect(() => { engineRef.current.level = level; }, [level]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4, border = true) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff66');
    grad.addColorStop(1, '#000000aa');
    ctx.fillStyle = grad;
    ctx.fill();
    if (border) {
      ctx.strokeStyle = 'rgba(0,0,0,0.6)';
      ctx.lineWidth = 1;
      ctx.stroke();
    }
  };

  const drawCombiner = (ctx: CanvasRenderingContext2D, frame: number, alpha: number, isEnemy = false, scaleOverride?: number) => {
    ctx.save();
    ctx.globalAlpha = alpha;

    const scale = scaleOverride || 1.8;
    ctx.scale(scale, scale);

    ctx.shadowBlur = isEnemy ? 25 : 15;
    ctx.shadowColor = isEnemy ? '#ff0055' : '#fff';

    const primaryColor = isEnemy ? '#ff0055' : '#00f3ff';
    const secondaryColor = isEnemy ? '#440022' : '#ef4444';

    drawMechanicalPart(ctx, -15, -20, 30, 35, primaryColor, 6);
    drawMechanicalPart(ctx, -10, -15, 20, 20, secondaryColor, 4);

    ctx.fillStyle = isEnemy ? '#ff0000' : '#fff';
    ctx.beginPath();
    ctx.arc(0, -5, 6 + Math.sin(frame * 0.2) * 2, 0, Math.PI * 2);
    ctx.fill();

    drawMechanicalPart(ctx, -8, -38, 16, 16, '#111', 8);
    ctx.fillStyle = '#fff';
    ctx.fillRect(-5, -30, 10, 2);

    ctx.fillStyle = isEnemy ? '#ff5555' : '#22d3ee';
    ctx.beginPath(); ctx.moveTo(-15, -15); ctx.lineTo(-45, -40); ctx.lineTo(-15, 5); ctx.fill();
    ctx.beginPath(); ctx.moveTo(15, -15); ctx.lineTo(45, -40); ctx.lineTo(15, 5); ctx.fill();

    drawMechanicalPart(ctx, -22, -25, 12, 12, '#fbbf24', 2);
    drawMechanicalPart(ctx, 10, -25, 12, 12, '#fbbf24', 2);

    const legSwing = Math.sin(frame * 0.15) * 5;
    drawMechanicalPart(ctx, -12, 15, 12, 22 + legSwing, '#333', 4);
    drawMechanicalPart(ctx, 0, 15, 12, 22 - legSwing, '#333', 4);

    ctx.restore();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, type = 'bot', alpha = 1, tier = 0) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8;
    const armSwing = Math.cos(time) * 10;
    let scale = 1;
    if (type === 'scout') scale = 0.8;
    if (type === 'heavy' || type === 'titan') scale = 1.4;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(scale, scale);
    drawMechanicalPart(ctx, -12, -18, 24, 28, color, 4);
    if (!isEnemy && tier > 0) {
      drawMechanicalPart(ctx, -18, -22, 12, 10, '#333', 2);
      drawMechanicalPart(ctx, 6, -22, 12, 10, '#333', 2);
      ctx.fillStyle = '#fff'; ctx.shadowBlur = 10; ctx.shadowColor = color; ctx.beginPath(); ctx.arc(0, -6, 4, 0, Math.PI * 2); ctx.fill(); ctx.shadowBlur = 0;
    }
    if (!isEnemy && tier > 1) {
      drawMechanicalPart(ctx, -14, 10, 8, 8, '#444', 1); drawMechanicalPart(ctx, 6, 10, 8, 8, '#444', 1);
      drawMechanicalPart(ctx, -20, -10, 6, 12, '#555', 1); drawMechanicalPart(ctx, 14, -10, 6, 12, '#555', 1);
    }
    if (!isEnemy && tier > 2) {
      drawMechanicalPart(ctx, -4, -38, 8, 10, color, 2);
      ctx.fillStyle = '#00f3ff'; ctx.beginPath(); ctx.moveTo(-20, -15); ctx.lineTo(-35, -35); ctx.lineTo(-20, -5); ctx.fill();
      ctx.beginPath(); ctx.moveTo(20, -15); ctx.lineTo(35, -35); ctx.lineTo(20, -5); ctx.fill();
    }
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? '#ff0000' : '#00f3ff'; ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);
    ctx.restore();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, color: string, frame: number, alpha = 1, tier = 0) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    switch(unit) {
      case RobotUnit.SENTINEL:
        drawMechanicalPart(ctx, -28, -10, 56, 20, color, 8);
        drawMechanicalPart(ctx, -18, -22, 36, 14, '#111', 4);
        ctx.fillStyle = frame % 10 < 5 ? '#ff0000' : '#0000ff'; ctx.fillRect(-6, -24, 12, 4);
        ctx.fillStyle = '#111'; ctx.beginPath(); ctx.arc(-18, 12, 8, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.arc(18, 12, 8, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = '#ffffaa'; ctx.fillRect(20, -4, 8, 6);
        if (tier > 0) { ctx.fillStyle = '#fff'; ctx.fillRect(-20, -6, 40, 4); }
        break;
      case RobotUnit.TITAN:
        drawMechanicalPart(ctx, -35, -8, 70, 24, color, 4);
        drawMechanicalPart(ctx, -18, -26, 36, 18, '#222', 4);
        drawMechanicalPart(ctx, 12, -22, 30, 8, '#444', 1);
        ctx.fillStyle = '#111'; ctx.fillRect(-33, 10, 66, 8);
        break;
      case RobotUnit.FALCON:
        drawMechanicalPart(ctx, -24, -8, 48, 16, color, 12);
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.moveTo(-10, -5); ctx.lineTo(-40, -20); ctx.lineTo(-10, 10); ctx.fill();
        ctx.fillStyle = '#ffaa00'; ctx.fillRect(-35, -5, 10, 6);
        break;
      default:
        drawMechanicalPart(ctx, -25, -12, 50, 24, color, 6);
        drawMechanicalPart(ctx, -10, -22, 20, 10, '#333', 2);
        break;
    }
    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy = false, isInvuln = false, isTransformed = false, type = 'bot', alpha = 1, tier = 0, isCombiner = false) => {
    if (isInvuln && frame % 4 < 2) return;
    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    if (facing === -1) ctx.scale(-1, 1);

    if (isCombiner) {
      const isGigantus = isEnemy && engineRef.current.level === 10;
      drawCombiner(ctx, frame, alpha, isEnemy, isGigantus ? 18 : undefined);
    } else {
      const stats = ROBOT_STATS[unit];
      const color = isEnemy ? '#ff0055' : (stats?.color || '#00f3ff');
      if (isTransformed) {
        drawAltMode(ctx, unit, color, frame, alpha, tier);
      } else {
        drawHumanoid(ctx, color, frame, isEnemy, type, alpha, tier);
      }
    }
    ctx.restore();
  };

  const resetLevel = useCallback((fullReset = true) => {
    const e = engineRef.current;
    const stats = ROBOT_STATS[e.unit];
    const baseHP = 100 + (upgrades.robotTier * 50);

    if (fullReset) {
      e.player.maxHealth = baseHP * stats.hpMult;
      e.player.health = e.player.maxHealth;
      e.player.unionTimer = 0;
      setUnionTime(0);
      setMaxHealth(e.player.maxHealth);
      setHealth(e.player.health);
      e.player.pos = { x: 100, y: 300 };
      e.player.checkpoint.reached = false;
      e.player.vel = { x: 0, y: 0 };
      e.player.invulnerable = 0;
      e.player.isTransformed = false;
      setIsTransformed(false);
      e.bullets = [];
      e.cameraX = 0;
      e.cameraY = 0;
      e.zoom = 1.0;

      const enemies: Enemy[] = [];
      const floorY = 398;

      const enemyCount = 5;
      for (let i = 0; i < enemyCount; i++) {
        const isBoss = i === enemyCount - 1;
        if (isBoss) {
          const isLvl10Titan = e.level === 10;
          const bossW = isLvl10Titan ? 640 : 64;
          const bossH = isLvl10Titan ? 800 : 80;
          const bossHP = isLvl10Titan ? 20000 : (500 + (e.level * 100));

          enemies.push({
            id: i, 
            pos: { x: 2000 + i * 800, y: floorY - bossH }, 
            vel: { x: 0, y: 0 },
            width: bossW, 
            height: bossH, 
            health: bossHP, 
            maxHealth: bossHP,
            isDead: false, 
            type: 'combinerBoss', 
            lastShot: 0, 
            hasSplit: false, 
            unit: RobotUnit.OMEGA
          });
        } else if (e.level === 5) {
          enemies.push({ 
            id: i, pos: { x: 1200 + i * 900, y: floorY - 32 }, vel: { x: 0, y: 0 }, 
            width: 70, height: 40, health: 1000, maxHealth: 1000, 
            isDead: false, type: 'heavy', lastShot: 0, isTransformed: true, unit: RobotUnit.TITAN 
          });
        } else {
          const enemyTypes = ['bot', 'scout', 'sniper', 'heavy'];
          const type = enemyTypes[i % (e.level < 5 ? 1 : e.level < 10 ? 2 : 4)];
          let w = 32, h = 48;
          if (type === 'scout') { w = 24; h = 36; }
          if (type === 'heavy') { w = 48; h = 72; }
          enemies.push({ 
            id: i, pos: { x: 800 + i * 800, y: floorY - h }, vel: { x: 0, y: 0 }, 
            width: w, height: h, health: 100, maxHealth: 100, 
            isDead: false, type: type, lastShot: 0, unit: RobotUnit.SENTINEL 
          });
        }
      }
      e.enemies = enemies;
    }
  }, [upgrades.robotTier]);

  useEffect(() => {
    resetLevel(true);
  }, [level, resetLevel]);

  useEffect(() => {
    const e = engineRef.current;
    const handleKeyDown = (ev: KeyboardEvent) => {
      e.keys[ev.code] = true;
      if (ev.code === 'ShiftLeft' || ev.code === 'ShiftRight') {
        e.player.isTransformed = !e.player.isTransformed;
        setIsTransformed(e.player.isTransformed);
      }
      if (ev.code === 'KeyC' && e.player.unionTimer <= 0) {
        e.player.unionTimer = SQUAD_UNION_DURATION;
        e.player.health = 500;
        e.player.maxHealth = 500;
        setHealth(500);
        setMaxHealth(500);
        soundService.playFly();
      }
      const trySwitch = (unit: RobotUnit) => {
        if (upgrades.unlockedUnits.includes(unit)) {
          e.unit = unit;
          setCurrentUnit(unit);
          if (e.player.unionTimer <= 0) {
             const stats = ROBOT_STATS[unit];
             const baseHP = 100 + (upgrades.robotTier * 50);
             e.player.maxHealth = baseHP * stats.hpMult;
             e.player.health = Math.min(e.player.health, e.player.maxHealth);
             setHealth(e.player.health);
             setMaxHealth(e.player.maxHealth);
          }
        }
      };
      if (ev.code === 'Digit1') trySwitch(RobotUnit.SENTINEL);
      if (ev.code === 'Digit2') trySwitch(RobotUnit.STRIKER);
      if (ev.code === 'Digit3') trySwitch(RobotUnit.FALCON);
      if (ev.code === 'Digit4') trySwitch(RobotUnit.TITAN);
      if (ev.code === 'Digit5') trySwitch(RobotUnit.SPECTER);
    };
    const handleKeyUp = (ev: KeyboardEvent) => { e.keys[ev.code] = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => {
      if (!e.isPaused) update();
      draw();
      animationId = requestAnimationFrame(loop);
    };

    const update = () => {
      const isCombiner = e.player.unionTimer > 0;
      const stats = ROBOT_STATS[e.unit];
      const currentStats = e.player.isTransformed ? stats.alt : stats.robot;
      e.frame++;

      if (isCombiner) {
        e.player.unionTimer--;
        if (e.frame % 10 === 0) setUnionTime(e.player.unionTimer);
        if (e.player.unionTimer === 0) {
          const baseHP = 100 + (upgrades.robotTier * 50);
          e.player.maxHealth = baseHP * stats.hpMult;
          e.player.health = Math.min(e.player.health, e.player.maxHealth);
          setHealth(e.player.health);
          setMaxHealth(e.player.maxHealth);
        }
      }

      const ph = isCombiner ? 80 : (e.player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48));
      const pw = isCombiner ? 64 : (e.player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32));

      const moveSpeed = isCombiner ? 6 : currentStats.speed;
      if (e.keys['ArrowRight'] || e.keys['KeyD']) { e.player.vel.x = moveSpeed; e.player.facing = 1; }
      else if (e.keys['ArrowLeft'] || e.keys['KeyA']) { e.player.vel.x = -moveSpeed; e.player.facing = -1; }
      else { e.player.vel.x *= 0.8; }

      if (e.unit === RobotUnit.FALCON && e.player.isTransformed) {
        if (e.keys['ArrowUp'] || e.keys['KeyW']) e.player.vel.y = -moveSpeed;
        else if (e.keys['ArrowDown'] || e.keys['KeyS']) e.player.vel.y = moveSpeed;
        else e.player.vel.y *= 0.9;
      } else {
        const jumpPower = isCombiner ? -15 : currentStats.jump;
        if ((e.keys['ArrowUp'] || e.keys['KeyW'] || e.keys['Space']) && e.player.grounded) {
          e.player.vel.y = jumpPower;
          e.player.grounded = false;
        }
        e.player.vel.y += GRAVITY;
      }

      e.player.pos.x += e.player.vel.x;
      e.player.pos.y += e.player.vel.y;
      const floorY = 398;
      if (e.player.pos.y > floorY - ph) { e.player.pos.y = floorY - ph; e.player.vel.y = 0; e.player.grounded = true; }
      if (e.player.pos.x < 0) e.player.pos.x = 0;

      const fr = isCombiner ? 8 : Math.max(5, currentStats.fireRate - upgrades.weaponTier * 2);
      if (e.keys['Space'] && e.frame - e.player.lastShot > fr) {
        soundService.playShoot();
        const dmg = isCombiner ? 500 : 100;
        if (isCombiner) {
          e.bullets.push({ 
            pos: { x: e.player.pos.x + (e.player.facing === 1 ? pw : 0), y: e.player.pos.y + ph/2 - 10 }, 
            vel: { x: e.player.facing * 20, y: 0 }, 
            width: 32, height: 20, owner: 'player', health: 1, maxHealth: 1, damage: dmg, color: '#fff' 
          });
        } else {
          e.bullets.push({ 
            pos: { x: e.player.pos.x + (e.player.facing === 1 ? pw : 0), y: e.player.pos.y + ph/2 }, 
            vel: { x: e.player.facing * 15, y: 0 }, 
            width: 12, height: 4, owner: 'player', health: 1, maxHealth: 1, damage: dmg, color: stats.color 
          });
        }
        e.player.lastShot = e.frame;
      }

      for (let i = e.bullets.length - 1; i >= 0; i--) {
        const b = e.bullets[i]; b.pos.x += b.vel.x; b.pos.y += b.vel.y;
        if (b.owner === 'enemy' && !e.player.invulnerable) {
          if (b.pos.x < e.player.pos.x + pw && b.pos.x + b.width > e.player.pos.x && b.pos.y < e.player.pos.y + ph && b.pos.y + b.height > e.player.pos.y) {
            e.player.health = Math.max(0, e.player.health - 20); e.player.invulnerable = 40;
            setHealth(e.player.health);
            e.bullets.splice(i, 1); soundService.playLose(); continue;
          }
        }
        if (Math.abs(b.pos.x - e.player.pos.x) > 3000) e.bullets.splice(i, 1);
      }

      let allDead = true;
      const newEnemies: Enemy[] = [];
      e.enemies.forEach(en => {
        if (en.isDead) return;
        allDead = false;

        if (en.type === 'combinerBoss' && !en.hasSplit && en.health < en.maxHealth * 0.2) {
          en.isDead = true;
          en.hasSplit = true;
          soundService.playFly();
          for (let s = 0; s < 6; s++) {
            newEnemies.push({
              id: Date.now() + s,
              pos: { 
                x: en.pos.x + (Math.random() * en.width), 
                y: en.pos.y + (Math.random() * en.height) 
              },
              vel: { x: (Math.random() - 0.5) * 15, y: -8 },
              width: 24, height: 36, health: 150, maxHealth: 150,
              isDead: false, type: 'scout', lastShot: e.frame, unit: RobotUnit.STRIKER
            });
          }
          return;
        }

        const dir = Math.sign(e.player.pos.x - en.pos.x);
        const speed = en.type === 'scout' ? 2.5 : (en.type === 'combinerBoss' ? 0.3 : 0.6);
        en.pos.x += dir * speed;

        const shootFreq = en.type === 'combinerBoss' ? 45 : (en.type === 'scout' ? 90 : 120);
        if (Math.abs(en.pos.x - e.player.pos.x) < 1200 && e.frame - en.lastShot > shootFreq) {
          const bW = en.type === 'combinerBoss' ? 24 : 10;
          const bH = en.type === 'combinerBoss' ? 10 : 4;
          e.bullets.push({ 
            pos: {x: en.pos.x + (dir > 0 ? en.width : 0), y: en.pos.y + en.height / 2}, 
            vel: {x: dir * 8, y: 0}, 
            width: bW, height: bH, owner: 'enemy', health: 1, maxHealth: 1, damage: 20, color: '#f00' 
          });
          en.lastShot = e.frame;
        }

        e.bullets.forEach((b, bIdx) => {
          if (b.owner === 'player' && !en.isDead && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) {
            en.health -= (b.damage || 100);
            if (en.health <= 0) en.isDead = true;
            e.bullets.splice(bIdx, 1);
          }
        });
      });

      if (newEnemies.length > 0) e.enemies.push(...newEnemies);

      if (e.player.health <= 0) onDie();
      if (allDead && newEnemies.length === 0) onWin();
      if (e.player.invulnerable > 0) e.player.invulnerable--;

      // Dynamic Camera & Zoom Logic
      const isLvl10 = e.level === 10;
      const targetZoom = isLvl10 ? 0.45 : 1.0;
      e.zoom += (targetZoom - e.zoom) * 0.05;

      // Horizontally center player with a slight offset to look ahead
      const visibleWidth = CANVAS_WIDTH / e.zoom;
      e.cameraX = e.player.pos.x - visibleWidth * 0.3;

      // Vertically center based on floor level but allow seeing higher up if zoomed out
      const targetCameraY = isLvl10 ? (398 - (CANVAS_HEIGHT / e.zoom) + 120) : 0;
      e.cameraY += (targetCameraY - e.cameraY) * 0.05;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;

      ctx.save();
      ctx.scale(e.zoom, e.zoom);
      ctx.translate(-e.cameraX, -e.cameraY);

      // Background
      const visibleWidth = CANVAS_WIDTH / e.zoom;
      const visibleHeight = CANVAS_HEIGHT / e.zoom;
      ctx.fillStyle = '#050510'; 
      ctx.fillRect(e.cameraX, e.cameraY, visibleWidth, visibleHeight);

      // Ground/Floor
      ctx.fillStyle = '#111'; 
      ctx.fillRect(e.cameraX - 1000, 398, visibleWidth + 2000, 1000); 
      ctx.strokeStyle = '#222';
      const startX = Math.floor(e.cameraX / 40) * 40;
      for(let i = startX - 40; i < e.cameraX + visibleWidth + 40; i += 40) {
        ctx.strokeRect(i, 398, 40, 52);
      }

      e.enemies.forEach(en => { 
        if(!en.isDead) drawUnit(ctx, en.pos.x, en.pos.y, en.width, en.height, en.unit || RobotUnit.SENTINEL, Math.sign(e.player.pos.x - en.pos.x), e.frame, true, false, en.isTransformed, en.type, 1, 0, en.type === 'combinerBoss'); 
      });

      const isCombiner = e.player.unionTimer > 0;
      const pw = isCombiner ? 64 : (e.player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32));
      const ph = isCombiner ? 80 : (e.player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48));
      drawUnit(ctx, e.player.pos.x, e.player.pos.y, pw, ph, e.unit, e.player.facing, e.frame, false, e.player.invulnerable > 0, e.player.isTransformed, 'bot', 1, upgrades.robotTier, isCombiner);

      e.bullets.forEach(b => { 
        ctx.fillStyle = b.color || '#00f3ff'; 
        if (b.width > 20) { ctx.shadowBlur = 10; ctx.shadowColor = b.color || '#fff'; } 
        ctx.fillRect(b.pos.x, b.pos.y, b.width, b.height); 
        ctx.shadowBlur = 0; 
      });

      ctx.restore();
    };

    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [onWin, onDie, upgrades.unlockedUnits, upgrades.weaponTier, upgrades.robotTier]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden">
      <div className="absolute top-4 left-4 z-10 space-y-4 pointer-events-none w-[400px]">
        <div className="bg-black/80 border border-cyan-500/50 p-3 rounded backdrop-blur-md shadow-lg">
          <div className="text-[10px] text-cyan-400 font-bold uppercase mb-1 flex justify-between font-orbitron">
            <span>{unionTime > 0 ? 'SQUAD COMBINER' : `${ROBOT_STATS[currentUnit].name} CHASSIS [TIER ${upgrades.robotTier}]`}</span>
            <span>{Math.round(health)}/{Math.round(maxHealth)}</span>
          </div>
          <div className="w-48 h-2.5 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
            <div className="h-full shadow-[0_0_15px_#00f3ff] transition-all duration-300" style={{ width: `${(health / maxHealth) * 100}%`, backgroundColor: health < maxHealth * 0.3 ? '#ef4444' : (unionTime > 0 ? '#fff' : '#00f3ff') }} />
          </div>
          {unionTime > 0 && (
            <div className="mt-2">
              <div className="text-[8px] text-yellow-400 font-bold uppercase mb-0.5 font-orbitron">COMBINER INTEGRITY DURATION</div>
              <div className="w-full h-1 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
                <div className="h-full bg-yellow-500 shadow-[0_0_10px_#fbbf24] transition-all duration-100" style={{ width: `${(unionTime / SQUAD_UNION_DURATION) * 100}%` }} />
              </div>
            </div>
          )}
        </div>
      </div>
      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full aspect-video shadow-2xl rounded-lg border-2 border-cyan-900/50" />
      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 pointer-events-none text-white/30 text-[8px] font-mono tracking-widest uppercase flex gap-6">
        <span>WASD: Move</span><span>Space: Fire</span><span>Shift: Transform</span><span>1-5: Squad</span><span>C: COMBINE</span>
      </div>
      {unionTime > SQUAD_UNION_DURATION - 60 && (
        <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
          <div className="text-6xl font-black italic text-white font-orbitron tracking-tighter shadow-2xl animate-pulse">SQUAD COMBINATION ENGAGED</div>
        </div>
      )}
      {level === 10 && (
        <div className="absolute top-20 right-4 p-4 border border-red-500 bg-red-950/20 text-red-500 font-orbitron text-xs animate-pulse uppercase tracking-widest">
           WARNING: GIGANTUS TITAN DETECTED IN SECTOR
        </div>
      )}
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const SQUAD_UNION_DURATION = 60 * 60; // 60 seconds (1 minute) at 60fps

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { 
    name: "SENTINEL", color: '#00f3ff', hpMult: 1.0, 
    robot: { speed: 4, jump: -11, fireRate: 15 },
    alt: { speed: 8, jump: -5, fireRate: 25, type: 'Car' }
  },
  [RobotUnit.STRIKER]: { 
    name: "STRIKER", color: '#fbbf24', hpMult: 0.8,
    robot: { speed: 6, jump: -10, fireRate: 10 },
    alt: { speed: 12, jump: -4, fireRate: 20, type: 'Bike' }
  },
  [RobotUnit.FALCON]: { 
    name: "FALCON", color: '#22d3ee', hpMult: 0.7,
    robot: { speed: 5, jump: -10, fireRate: 12 },
    alt: { speed: 7, jump: -7, fireRate: 15, type: 'Jet' }
  },
  [RobotUnit.TITAN]: { 
    name: "TITAN", color: '#ef4444', hpMult: 2.5,
    robot: { speed: 2.5, jump: -12, fireRate: 30 },
    alt: { speed: 4, jump: 0, fireRate: 20, type: 'Tank' }
  },
  [RobotUnit.SPECTER]: { 
    name: "SPECTER", color: '#a855f7', hpMult: 0.6,
    robot: { speed: 5, jump: -11, fireRate: 20 },
    alt: { speed: 6, jump: -14, fireRate: 40, type: 'Energy Sphere' }
  },
  [RobotUnit.VANGUARD]: { 
    name: "VANGUARD", color: '#10b981', hpMult: 2.0, 
    robot: { speed: 3.5, jump: -10, fireRate: 25 },
    alt: { speed: 6, jump: -4, fireRate: 30, type: 'Shield Truck' }
  },
  [RobotUnit.NIGHTSHADE]: { 
    name: "NIGHTSHADE", color: '#6366f1', hpMult: 0.9, 
    robot: { speed: 7, jump: -13, fireRate: 12 },
    alt: { speed: 10, jump: -6, fireRate: 18, type: 'Interceptor' }
  },
  [RobotUnit.BLAZE]: { 
    name: "BLAZE", color: '#f97316', hpMult: 1.2, 
    robot: { speed: 4.5, jump: -11, fireRate: 18 },
    alt: { speed: 7, jump: -5, fireRate: 22, type: 'Rig' }
  },
  [RobotUnit.GLITCH]: { 
    name: "GLITCH", color: '#ec4899', hpMult: 1.0, 
    robot: { speed: 5, jump: -12, fireRate: 14 },
    alt: { speed: 9, jump: -12, fireRate: 16, type: 'Splicer' }
  },
  [RobotUnit.OMEGA]: { 
    name: "OMEGA", color: '#ffffff', hpMult: 3.0, 
    robot: { speed: 6, jump: -14, fireRate: 10 },
    alt: { speed: 10, jump: -8, fireRate: 15, type: 'Fortress' }
  },
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [currentUnit, setCurrentUnit] = useState<RobotUnit>(RobotUnit.SENTINEL);
  const [isTransformed, setIsTransformed] = useState(false);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [unionTime, setUnionTime] = useState(0);
  const [isSpaceshipMode, setIsSpaceshipMode] = useState(false);

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      health: 100,
      maxHealth: 100,
      isTransformed: false,
      unionTimer: 0,
      inSpaceship: false,
      spaceshipPos: { x: 300, y: 340 },
    },
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    cameraY: 0,
    zoom: 1.0,
    isPaused: isPaused,
    unit: RobotUnit.SENTINEL,
    level: level,
  });

  useEffect(() => { engineRef.current.isPaused = isPaused; }, [isPaused]);
  useEffect(() => { engineRef.current.level = level; }, [level]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4, border = true) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff66');
    grad.addColorStop(1, '#000000aa');
    ctx.fillStyle = grad;
    ctx.fill();
    if (border) {
      ctx.strokeStyle = 'rgba(0,0,0,0.6)';
      ctx.lineWidth = 1;
      ctx.stroke();
    }
  };

  const drawSpaceship = (ctx: CanvasRenderingContext2D, frame: number, alpha: number) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(1.5, 1.2);
    // Body
    drawMechanicalPart(ctx, -40, -15, 80, 30, '#1e293b', 15);
    drawMechanicalPart(ctx, -30, -25, 60, 20, '#334155', 10);
    // Cockpit
    ctx.fillStyle = '#00f3ff';
    ctx.beginPath();
    ctx.ellipse(0, -15, 20, 10, 0, 0, Math.PI * 2);
    ctx.fill();
    // Wings
    ctx.fillStyle = '#1e293b';
    ctx.beginPath(); ctx.moveTo(-20, 0); ctx.lineTo(-60, 20); ctx.lineTo(-20, 15); ctx.fill();
    ctx.beginPath(); ctx.moveTo(20, 0); ctx.lineTo(60, 20); ctx.lineTo(20, 15); ctx.fill();
    // Thrusters
    const fireSize = 10 + Math.sin(frame * 0.5) * 5;
    ctx.fillStyle = '#fbbf24';
    ctx.beginPath(); ctx.arc(-35, 10, fireSize, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(35, 10, fireSize, 0, Math.PI * 2); ctx.fill();
    // Laser Cannons
    drawMechanicalPart(ctx, -45, -5, 15, 5, '#475569', 2);
    drawMechanicalPart(ctx, 30, -5, 15, 5, '#475569', 2);
    ctx.restore();
  };

  const drawCombiner = (ctx: CanvasRenderingContext2D, frame: number, alpha: number, isEnemy = false, scaleOverride?: number) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    const scale = scaleOverride || 1.8;
    ctx.scale(scale, scale);
    ctx.shadowBlur = isEnemy ? 25 : 15;
    ctx.shadowColor = isEnemy ? '#ff0055' : '#fff';
    const primaryColor = isEnemy ? '#ff0055' : '#00f3ff';
    const secondaryColor = isEnemy ? '#440022' : '#ef4444';
    drawMechanicalPart(ctx, -15, -20, 30, 35, primaryColor, 6);
    drawMechanicalPart(ctx, -10, -15, 20, 20, secondaryColor, 4);
    ctx.fillStyle = isEnemy ? '#ff0000' : '#fff';
    ctx.beginPath();
    ctx.arc(0, -5, 6 + Math.sin(frame * 0.2) * 2, 0, Math.PI * 2);
    ctx.fill();
    drawMechanicalPart(ctx, -8, -38, 16, 16, '#111', 8);
    ctx.fillStyle = '#fff'; ctx.fillRect(-5, -30, 10, 2);
    ctx.fillStyle = isEnemy ? '#ff5555' : '#22d3ee';
    ctx.beginPath(); ctx.moveTo(-15, -15); ctx.lineTo(-45, -40); ctx.lineTo(-15, 5); ctx.fill();
    ctx.beginPath(); ctx.moveTo(15, -15); ctx.lineTo(45, -40); ctx.lineTo(15, 5); ctx.fill();
    drawMechanicalPart(ctx, -22, -25, 12, 12, '#fbbf24', 2);
    drawMechanicalPart(ctx, 10, -25, 12, 12, '#fbbf24', 2);
    const legSwing = Math.sin(frame * 0.15) * 5;
    drawMechanicalPart(ctx, -12, 15, 12, 22 + legSwing, '#333', 4);
    drawMechanicalPart(ctx, 0, 15, 12, 22 - legSwing, '#333', 4);
    ctx.restore();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, type = 'bot', alpha = 1, tier = 0) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8;
    const armSwing = Math.cos(time) * 10;
    let scale = 1;
    if (type === 'scout') scale = 0.8;
    if (type === 'heavy' || type === 'titan') scale = 1.4;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(scale, scale);
    drawMechanicalPart(ctx, -12, -18, 24, 28, color, 4);
    if (!isEnemy && tier > 0) {
      drawMechanicalPart(ctx, -18, -22, 12, 10, '#333', 2);
      drawMechanicalPart(ctx, 6, -22, 12, 10, '#333', 2);
      ctx.fillStyle = '#fff'; ctx.shadowBlur = 10; ctx.shadowColor = color; ctx.beginPath(); ctx.arc(0, -6, 4, 0, Math.PI * 2); ctx.fill(); ctx.shadowBlur = 0;
    }
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? '#ff0000' : '#00f3ff'; ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);
    ctx.restore();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, color: string, frame: number, alpha = 1, tier = 0) => {
    ctx.save(); ctx.globalAlpha = alpha;
    switch(unit) {
      case RobotUnit.SENTINEL:
        drawMechanicalPart(ctx, -28, -10, 56, 20, color, 8);
        drawMechanicalPart(ctx, -18, -22, 36, 14, '#111', 4);
        ctx.fillStyle = frame % 10 < 5 ? '#ff0000' : '#0000ff'; ctx.fillRect(-6, -24, 12, 4);
        ctx.fillStyle = '#111'; ctx.beginPath(); ctx.arc(-18, 12, 8, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.arc(18, 12, 8, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = '#ffffaa'; ctx.fillRect(20, -4, 8, 6);
        if (tier > 0) { ctx.fillStyle = '#fff'; ctx.fillRect(-20, -6, 40, 4); }
        break;
      case RobotUnit.TITAN:
        drawMechanicalPart(ctx, -35, -8, 70, 24, color, 4);
        drawMechanicalPart(ctx, -18, -26, 36, 18, '#222', 4);
        drawMechanicalPart(ctx, 12, -22, 30, 8, '#444', 1);
        ctx.fillStyle = '#111'; ctx.fillRect(-33, 10, 66, 8);
        break;
      case RobotUnit.FALCON:
        drawMechanicalPart(ctx, -24, -8, 48, 16, color, 12);
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.moveTo(-10, -5); ctx.lineTo(-40, -20); ctx.lineTo(-10, 10); ctx.fill();
        ctx.fillStyle = '#ffaa00'; ctx.fillRect(-35, -5, 10, 6);
        break;
      default:
        drawMechanicalPart(ctx, -25, -12, 50, 24, color, 6);
        drawMechanicalPart(ctx, -10, -22, 20, 10, '#333', 2);
        break;
    }
    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy = false, isInvuln = false, isTransformed = false, type = 'bot', alpha = 1, tier = 0, isCombiner = false) => {
    if (isInvuln && frame % 4 < 2) return;
    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    if (facing === -1) ctx.scale(-1, 1);
    if (isCombiner) {
      const isGigantus = isEnemy && engineRef.current.level === 10;
      drawCombiner(ctx, frame, alpha, isEnemy, isGigantus ? 18 : undefined);
    } else {
      const stats = ROBOT_STATS[unit];
      const color = isEnemy ? '#ff0055' : (stats?.color || '#00f3ff');
      if (isTransformed) drawAltMode(ctx, unit, color, frame, alpha, tier);
      else drawHumanoid(ctx, color, frame, isEnemy, type, alpha, tier);
    }
    ctx.restore();
  };

  const resetLevel = useCallback((fullReset = true) => {
    const e = engineRef.current;
    const stats = ROBOT_STATS[e.unit];
    const baseHP = 100 + (upgrades.robotTier * 50);
    if (fullReset) {
      e.player.maxHealth = baseHP * stats.hpMult;
      e.player.health = e.player.maxHealth;
      e.player.unionTimer = 0;
      e.player.inSpaceship = false;
      setIsSpaceshipMode(false);
      e.player.spaceshipPos = { x: 300, y: 340 };
      setUnionTime(0);
      setMaxHealth(e.player.maxHealth);
      setHealth(e.player.health);
      e.player.pos = { x: 100, y: 300 };
      e.player.vel = { x: 0, y: 0 };
      e.player.invulnerable = 0;
      e.player.isTransformed = false;
      setIsTransformed(false);
      e.bullets = [];
      e.cameraX = 0; e.cameraY = 0; e.zoom = 1.0;
      const enemies: Enemy[] = [];
      const floorY = 398;
      const enemyCount = 5;
      for (let i = 0; i < enemyCount; i++) {
        const isBoss = i === enemyCount - 1;
        if (isBoss) {
          const isLvl10Titan = e.level === 10;
          const bossW = isLvl10Titan ? 640 : 64;
          const bossH = isLvl10Titan ? 800 : 80;
          const bossHP = isLvl10Titan ? 20000 : (500 + (e.level * 100));
          enemies.push({ id: i, pos: { x: 2000 + i * 800, y: floorY - bossH }, vel: { x: 0, y: 0 }, width: bossW, height: bossH, health: bossHP, maxHealth: bossHP, isDead: false, type: 'combinerBoss', lastShot: 0, hasSplit: false, unit: RobotUnit.OMEGA });
        } else {
          const type = 'heavy';
          enemies.push({ id: i, pos: { x: 800 + i * 800, y: floorY - 72 }, vel: { x: 0, y: 0 }, width: 48, height: 72, health: 100, maxHealth: 100, isDead: false, type: type, lastShot: 0, unit: RobotUnit.SENTINEL });
        }
      }
      e.enemies = enemies;
    }
  }, [upgrades.robotTier]);

  useEffect(() => { resetLevel(true); }, [level, resetLevel]);

  useEffect(() => {
    const e = engineRef.current;
    const handleKeyDown = (ev: KeyboardEvent) => {
      e.keys[ev.code] = true;
      if (ev.code === 'ShiftLeft' || ev.code === 'ShiftRight') {
        e.player.isTransformed = !e.player.isTransformed;
        setIsTransformed(e.player.isTransformed);
      }
      if (ev.code === 'KeyM' && e.level === 10) {
        const dx = e.player.pos.x - e.player.spaceshipPos.x;
        const dy = e.player.pos.y - e.player.spaceshipPos.y;
        const dist = Math.sqrt(dx*dx + dy*dy);
        if (dist < 100 || e.player.inSpaceship) {
          e.player.inSpaceship = !e.player.inSpaceship;
          setIsSpaceshipMode(e.player.inSpaceship);
          if (e.player.inSpaceship) {
            e.player.maxHealth = 2000;
            e.player.health = 2000;
            setMaxHealth(2000); setHealth(2000);
            soundService.playFly();
          } else {
             const stats = ROBOT_STATS[e.unit];
             const baseHP = 100 + (upgrades.robotTier * 50);
             e.player.maxHealth = baseHP * stats.hpMult;
             e.player.health = Math.min(e.player.health, e.player.maxHealth);
             e.player.spaceshipPos = { ...e.player.pos };
             setMaxHealth(e.player.maxHealth); setHealth(e.player.health);
          }
        }
      }
      if (ev.code === 'KeyC' && e.player.unionTimer <= 0 && !e.player.inSpaceship) {
        e.player.unionTimer = SQUAD_UNION_DURATION;
        e.player.health = 500; e.player.maxHealth = 500;
        setHealth(500); setMaxHealth(500);
        soundService.playFly();
      }
      const trySwitch = (unit: RobotUnit) => {
        if (upgrades.unlockedUnits.includes(unit) && !e.player.inSpaceship) {
          e.unit = unit; setCurrentUnit(unit);
          if (e.player.unionTimer <= 0) {
             const stats = ROBOT_STATS[unit];
             const baseHP = 100 + (upgrades.robotTier * 50);
             e.player.maxHealth = baseHP * stats.hpMult;
             e.player.health = Math.min(e.player.health, e.player.maxHealth);
             setHealth(e.player.health); setMaxHealth(e.player.maxHealth);
          }
        }
      };
      if (ev.code === 'Digit1') trySwitch(RobotUnit.SENTINEL);
      if (ev.code === 'Digit2') trySwitch(RobotUnit.STRIKER);
      if (ev.code === 'Digit3') trySwitch(RobotUnit.FALCON);
      if (ev.code === 'Digit4') trySwitch(RobotUnit.TITAN);
      if (ev.code === 'Digit5') trySwitch(RobotUnit.SPECTER);
    };
    const handleKeyUp = (ev: KeyboardEvent) => { e.keys[ev.code] = false; };
    window.addEventListener('keydown', handleKeyDown); window.addEventListener('keyup', handleKeyUp);
    let animationId: number;
    const loop = () => { if (!e.isPaused) update(); draw(); animationId = requestAnimationFrame(loop); };

    const update = () => {
      const isCombiner = e.player.unionTimer > 0;
      const isShip = e.player.inSpaceship;
      const stats = ROBOT_STATS[e.unit];
      const currentStats = e.player.isTransformed ? stats.alt : stats.robot;
      e.frame++;
      if (isCombiner) {
        e.player.unionTimer--;
        if (e.frame % 10 === 0) setUnionTime(e.player.unionTimer);
      }
      const pw = isShip ? 120 : (isCombiner ? 64 : (e.player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32)));
      const ph = isShip ? 40 : (isCombiner ? 80 : (e.player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48)));
      const moveSpeed = isShip ? 12 : (isCombiner ? 6 : currentStats.speed);
      if (e.keys['ArrowRight'] || e.keys['KeyD']) { e.player.vel.x = moveSpeed; e.player.facing = 1; }
      else if (e.keys['ArrowLeft'] || e.keys['KeyA']) { e.player.vel.x = -moveSpeed; e.player.facing = -1; }
      else e.player.vel.x *= 0.8;
      if (isShip || (e.unit === RobotUnit.FALCON && e.player.isTransformed)) {
        if (e.keys['ArrowUp'] || e.keys['KeyW']) e.player.vel.y = -moveSpeed;
        else if (e.keys['ArrowDown'] || e.keys['KeyS']) e.player.vel.y = moveSpeed;
        else e.player.vel.y *= 0.9;
      } else {
        const jumpPower = isCombiner ? -15 : currentStats.jump;
        if ((e.keys['ArrowUp'] || e.keys['KeyW'] || e.keys['Space']) && e.player.grounded) { e.player.vel.y = jumpPower; e.player.grounded = false; }
        e.player.vel.y += GRAVITY;
      }
      e.player.pos.x += e.player.vel.x; e.player.pos.y += e.player.vel.y;
      const floorY = 398;
      if (!isShip && e.player.pos.y > floorY - ph) { e.player.pos.y = floorY - ph; e.player.vel.y = 0; e.player.grounded = true; }
      if (e.player.pos.x < 0) e.player.pos.x = 0;
      const fr = isShip ? 3 : (isCombiner ? 8 : Math.max(5, currentStats.fireRate - upgrades.weaponTier * 2));
      if (e.keys['Space'] && e.frame - e.player.lastShot > fr) {
        soundService.playShoot();
        const dmg = isShip ? 1200 : (isCombiner ? 500 : 100);
        if (isShip) {
          e.bullets.push({ pos: { x: e.player.pos.x + (e.player.facing === 1 ? pw : -400), y: e.player.pos.y + ph/2 - 4 }, vel: { x: e.player.facing * 35, y: 0 }, width: 400, height: 8, owner: 'player', health: 1, maxHealth: 1, damage: dmg, color: '#00f3ff' });
        } else if (isCombiner) {
          e.bullets.push({ pos: { x: e.player.pos.x + (e.player.facing === 1 ? pw : 0), y: e.player.pos.y + ph/2 - 10 }, vel: { x: e.player.facing * 20, y: 0 }, width: 32, height: 20, owner: 'player', health: 1, maxHealth: 1, damage: dmg, color: '#fff' });
        } else {
          e.bullets.push({ pos: { x: e.player.pos.x + (e.player.facing === 1 ? pw : 0), y: e.player.pos.y + ph/2 }, vel: { x: e.player.facing * 15, y: 0 }, width: 12, height: 4, owner: 'player', health: 1, maxHealth: 1, damage: dmg, color: stats.color });
        }
        e.player.lastShot = e.frame;
      }
      for (let i = e.bullets.length - 1; i >= 0; i--) {
        const b = e.bullets[i]; b.pos.x += b.vel.x; b.pos.y += b.vel.y;
        if (b.owner === 'enemy' && !e.player.invulnerable) {
          if (b.pos.x < e.player.pos.x + pw && b.pos.x + b.width > e.player.pos.x && b.pos.y < e.player.pos.y + ph && b.pos.y + b.height > e.player.pos.y) {
            e.player.health = Math.max(0, e.player.health - 20); e.player.invulnerable = 40;
            setHealth(e.player.health); e.bullets.splice(i, 1); soundService.playLose(); continue;
          }
        }
        if (Math.abs(b.pos.x - e.player.pos.x) > 3000) e.bullets.splice(i, 1);
      }
      let allDead = true;
      const newEnemies: Enemy[] = [];
      e.enemies.forEach(en => {
        if (en.isDead) return;
        allDead = false;
        if (en.type === 'combinerBoss' && !en.hasSplit && en.health < en.maxHealth * 0.2) {
          en.isDead = true; en.hasSplit = true; soundService.playFly();
          for (let s = 0; s < 6; s++) {
            newEnemies.push({ id: Date.now() + s, pos: { x: en.pos.x + (Math.random() * en.width), y: en.pos.y + (Math.random() * en.height) }, vel: { x: (Math.random() - 0.5) * 15, y: -8 }, width: 24, height: 36, health: 150, maxHealth: 150, isDead: false, type: 'scout', lastShot: e.frame, unit: RobotUnit.STRIKER });
          }
          return;
        }
        const dir = Math.sign(e.player.pos.x - en.pos.x);
        const speed = en.type === 'scout' ? 2.5 : (en.type === 'combinerBoss' ? 0.3 : 0.6);
        en.pos.x += dir * speed;
        const shootFreq = en.type === 'combinerBoss' ? 45 : (en.type === 'scout' ? 90 : 120);
        if (Math.abs(en.pos.x - e.player.pos.x) < 1200 && e.frame - en.lastShot > shootFreq) {
          const bW = en.type === 'combinerBoss' ? 24 : 10;
          const bH = en.type === 'combinerBoss' ? 10 : 4;
          e.bullets.push({ pos: {x: en.pos.x + (dir > 0 ? en.width : 0), y: en.pos.y + en.height / 2}, vel: {x: dir * 8, y: 0}, width: bW, height: bH, owner: 'enemy', health: 1, maxHealth: 1, damage: 20, color: '#f00' });
          en.lastShot = e.frame;
        }
        e.bullets.forEach((b, bIdx) => {
          if (b.owner === 'player' && !en.isDead && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) {
            en.health -= (b.damage || 100); if (en.health <= 0) en.isDead = true;
            e.bullets.splice(bIdx, 1);
          }
        });
      });
      if (newEnemies.length > 0) e.enemies.push(...newEnemies);
      if (e.player.health <= 0) onDie();
      if (allDead && newEnemies.length === 0) onWin();
      if (e.player.invulnerable > 0) e.player.invulnerable--;
      const isLvl10 = e.level === 10;
      const targetZoom = isLvl10 ? 0.45 : 1.0;
      e.zoom += (targetZoom - e.zoom) * 0.05;
      const visibleWidth = CANVAS_WIDTH / e.zoom;
      e.cameraX = e.player.pos.x - visibleWidth * 0.3;
      const targetCameraY = isLvl10 ? (398 - (CANVAS_HEIGHT / e.zoom) + 120) : 0;
      e.cameraY += (targetCameraY - e.cameraY) * 0.05;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      ctx.save(); ctx.scale(e.zoom, e.zoom); ctx.translate(-e.cameraX, -e.cameraY);
      const visibleWidth = CANVAS_WIDTH / e.zoom; const visibleHeight = CANVAS_HEIGHT / e.zoom;
      ctx.fillStyle = '#050510'; ctx.fillRect(e.cameraX, e.cameraY, visibleWidth, visibleHeight);
      ctx.fillStyle = '#111'; ctx.fillRect(e.cameraX - 1000, 398, visibleWidth + 2000, 1000); ctx.strokeStyle = '#222';
      const startX = Math.floor(e.cameraX / 40) * 40;
      for(let i = startX - 40; i < e.cameraX + visibleWidth + 40; i += 40) ctx.strokeRect(i, 398, 40, 52);
      if (e.level === 10 && !e.player.inSpaceship) {
        ctx.save(); ctx.translate(e.player.spaceshipPos.x + 60, e.player.spaceshipPos.y + 20); drawSpaceship(ctx, e.frame, 0.8); ctx.restore();
        ctx.fillStyle = '#fff'; ctx.font = '10px Orbitron'; ctx.fillText("[M] ENTER SHIP", e.player.spaceshipPos.x + 10, e.player.spaceshipPos.y - 20);
      }
      e.enemies.forEach(en => { if(!en.isDead) drawUnit(ctx, en.pos.x, en.pos.y, en.width, en.height, en.unit || RobotUnit.SENTINEL, Math.sign(e.player.pos.x - en.pos.x), e.frame, true, false, en.isTransformed, en.type, 1, 0, en.type === 'combinerBoss'); });
      if (e.player.inSpaceship) {
        ctx.save(); ctx.translate(e.player.pos.x + 60, e.player.pos.y + 20); if (e.player.facing === -1) ctx.scale(-1, 1);
        drawSpaceship(ctx, e.frame, 1); ctx.restore();
      } else {
        const isCombiner = e.player.unionTimer > 0;
        const pw = isCombiner ? 64 : (e.player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32));
        const ph = isCombiner ? 80 : (e.player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48));
        drawUnit(ctx, e.player.pos.x, e.player.pos.y, pw, ph, e.unit, e.player.facing, e.frame, false, e.player.invulnerable > 0, e.player.isTransformed, 'bot', 1, upgrades.robotTier, isCombiner);
      }
      e.bullets.forEach(b => { 
        ctx.fillStyle = b.color || '#00f3ff'; if (b.width > 20) { ctx.shadowBlur = 10; ctx.shadowColor = b.color || '#fff'; } 
        ctx.fillRect(b.pos.x, b.pos.y, b.width, b.height); ctx.shadowBlur = 0; 
      });
      ctx.restore();
    };
    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [onWin, onDie, upgrades.unlockedUnits, upgrades.weaponTier, upgrades.robotTier]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden font-orbitron">
      <div className="absolute top-4 left-4 z-10 space-y-4 pointer-events-none w-[400px]">
        <div className="bg-black/80 border border-cyan-500/50 p-3 rounded backdrop-blur-md shadow-lg">
          <div className="text-[10px] text-cyan-400 font-bold uppercase mb-1 flex justify-between">
            <span>{isSpaceshipMode ? 'INTERCEPTOR SHIP' : (unionTime > 0 ? 'SQUAD COMBINER' : `${ROBOT_STATS[currentUnit].name} CHASSIS`)}</span>
            <span>{Math.round(health)}/{Math.round(maxHealth)}</span>
          </div>
          <div className="w-48 h-2.5 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
            <div className="h-full shadow-[0_0_15px_#00f3ff] transition-all duration-300" style={{ width: `${(health / maxHealth) * 100}%`, backgroundColor: health < maxHealth * 0.3 ? '#ef4444' : (unionTime > 0 || isSpaceshipMode ? '#fff' : '#00f3ff') }} />
          </div>
          {unionTime > 0 && (
            <div className="mt-2">
              <div className="text-[8px] text-yellow-400 font-bold uppercase mb-0.5">COMBINER INTEGRITY</div>
              <div className="w-full h-1 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
                <div className="h-full bg-yellow-500 shadow-[0_0_10px_#fbbf24] transition-all duration-100" style={{ width: `${(unionTime / SQUAD_UNION_DURATION) * 100}%` }} />
              </div>
            </div>
          )}
        </div>
      </div>
      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full aspect-video shadow-2xl rounded-lg border-2 border-cyan-900/50" />
      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 pointer-events-none text-white/30 text-[8px] font-mono tracking-widest uppercase flex gap-6">
        <span>WASD: Move</span><span>Space: Fire</span><span>Shift: Transform</span><span>1-5: Squad</span><span>C: Combine</span>{level === 10 && <span>M: Ship</span>}
      </div>
      {(unionTime > SQUAD_UNION_DURATION - 60 || (isSpaceshipMode && engineRef.current.frame % 60 < 30)) && (
        <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
          <div className="text-6xl font-black italic text-white tracking-tighter shadow-2xl animate-pulse uppercase">{isSpaceshipMode ? 'Heavy Laser Online' : 'Squad Combination Engaged'}</div>
        </div>
      )}
      {level === 10 && (
        <div className="absolute top-20 right-4 p-4 border border-red-500 bg-red-950/20 text-red-500 text-xs animate-pulse uppercase tracking-widest">
           Warning: Gigantus Titan Detected
        </div>
      )}
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const SQUAD_UNION_DURATION = 60 * 60; // 60 seconds (1 minute) at 60fps

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { 
    name: "SENTINEL", color: '#00f3ff', hpMult: 1.0, 
    robot: { speed: 4, jump: -11, fireRate: 15 },
    alt: { speed: 8, jump: -5, fireRate: 25, type: 'Car' }
  },
  [RobotUnit.STRIKER]: { 
    name: "STRIKER", color: '#fbbf24', hpMult: 0.8,
    robot: { speed: 6, jump: -10, fireRate: 10 },
    alt: { speed: 12, jump: -4, fireRate: 20, type: 'Bike' }
  },
  [RobotUnit.FALCON]: { 
    name: "FALCON", color: '#22d3ee', hpMult: 0.7,
    robot: { speed: 5, jump: -10, fireRate: 12 },
    alt: { speed: 7, jump: -7, fireRate: 15, type: 'Jet' }
  },
  [RobotUnit.TITAN]: { 
    name: "TITAN", color: '#ef4444', hpMult: 2.5,
    robot: { speed: 2.5, jump: -12, fireRate: 30 },
    alt: { speed: 4, jump: 0, fireRate: 20, type: 'Tank' }
  },
  [RobotUnit.SPECTER]: { 
    name: "SPECTER", color: '#a855f7', hpMult: 0.6,
    robot: { speed: 5, jump: -11, fireRate: 20 },
    alt: { speed: 6, jump: -14, fireRate: 40, type: 'Energy Sphere' }
  },
  [RobotUnit.VANGUARD]: { 
    name: "VANGUARD", color: '#10b981', hpMult: 2.0, 
    robot: { speed: 3.5, jump: -10, fireRate: 25 },
    alt: { speed: 6, jump: -4, fireRate: 30, type: 'Shield Truck' }
  },
  [RobotUnit.NIGHTSHADE]: { 
    name: "NIGHTSHADE", color: '#6366f1', hpMult: 0.9, 
    robot: { speed: 7, jump: -13, fireRate: 12 },
    alt: { speed: 10, jump: -6, fireRate: 18, type: 'Interceptor' }
  },
  [RobotUnit.BLAZE]: { 
    name: "BLAZE", color: '#f97316', hpMult: 1.2, 
    robot: { speed: 4.5, jump: -11, fireRate: 18 },
    alt: { speed: 7, jump: -5, fireRate: 22, type: 'Rig' }
  },
  [RobotUnit.GLITCH]: { 
    name: "GLITCH", color: '#ec4899', hpMult: 1.0, 
    robot: { speed: 5, jump: -12, fireRate: 14 },
    alt: { speed: 9, jump: -12, fireRate: 16, type: 'Splicer' }
  },
  [RobotUnit.OMEGA]: { 
    name: "OMEGA", color: '#ffffff', hpMult: 3.0, 
    robot: { speed: 6, jump: -14, fireRate: 10 },
    alt: { speed: 10, jump: -8, fireRate: 15, type: 'Fortress' }
  },
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [currentUnit, setCurrentUnit] = useState<RobotUnit>(RobotUnit.SENTINEL);
  const [isTransformed, setIsTransformed] = useState(false);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [unionTime, setUnionTime] = useState(0);
  const [isSpaceshipMode, setIsSpaceshipMode] = useState(false);

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      health: 100,
      maxHealth: 100,
      isTransformed: false,
      unionTimer: 0,
      inSpaceship: false,
      spaceshipPos: { x: 300, y: 340 },
    },
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    cameraY: 0,
    zoom: 1.0,
    isPaused: isPaused,
    unit: RobotUnit.SENTINEL,
    level: level,
  });

  useEffect(() => { engineRef.current.isPaused = isPaused; }, [isPaused]);
  useEffect(() => { engineRef.current.level = level; }, [level]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4, border = true) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff66');
    grad.addColorStop(1, '#000000aa');
    ctx.fillStyle = grad;
    ctx.fill();
    if (border) {
      ctx.strokeStyle = 'rgba(0,0,0,0.6)';
      ctx.lineWidth = 1;
      ctx.stroke();
    }
  };

  const drawSpaceship = (ctx: CanvasRenderingContext2D, frame: number, alpha: number) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(1.5, 1.2);
    // Body
    drawMechanicalPart(ctx, -40, -15, 80, 30, '#1e293b', 15);
    drawMechanicalPart(ctx, -30, -25, 60, 20, '#334155', 10);
    // Cockpit
    ctx.fillStyle = '#00f3ff';
    ctx.beginPath();
    ctx.ellipse(0, -15, 20, 10, 0, 0, Math.PI * 2);
    ctx.fill();
    // Wings
    ctx.fillStyle = '#1e293b';
    ctx.beginPath(); ctx.moveTo(-20, 0); ctx.lineTo(-60, 20); ctx.lineTo(-20, 15); ctx.fill();
    ctx.beginPath(); ctx.moveTo(20, 0); ctx.lineTo(60, 20); ctx.lineTo(20, 15); ctx.fill();
    // Thrusters
    const fireSize = 10 + Math.sin(frame * 0.5) * 5;
    ctx.fillStyle = '#fbbf24';
    ctx.beginPath(); ctx.arc(-35, 10, fireSize, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(35, 10, fireSize, 0, Math.PI * 2); ctx.fill();
    // Laser Cannons
    drawMechanicalPart(ctx, -45, -5, 15, 5, '#475569', 2);
    drawMechanicalPart(ctx, 30, -5, 15, 5, '#475569', 2);
    ctx.restore();
  };

  const drawCombiner = (ctx: CanvasRenderingContext2D, frame: number, alpha: number, isEnemy = false, scaleOverride?: number) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    const scale = scaleOverride || 1.8;
    ctx.scale(scale, scale);
    ctx.shadowBlur = isEnemy ? 25 : 15;
    ctx.shadowColor = isEnemy ? '#ff0055' : '#fff';
    const primaryColor = isEnemy ? '#ff0055' : '#00f3ff';
    const secondaryColor = isEnemy ? '#440022' : '#ef4444';
    drawMechanicalPart(ctx, -15, -20, 30, 35, primaryColor, 6);
    drawMechanicalPart(ctx, -10, -15, 20, 20, secondaryColor, 4);
    ctx.fillStyle = isEnemy ? '#ff0000' : '#fff';
    ctx.beginPath();
    ctx.arc(0, -5, 6 + Math.sin(frame * 0.2) * 2, 0, Math.PI * 2);
    ctx.fill();
    drawMechanicalPart(ctx, -8, -38, 16, 16, '#111', 8);
    ctx.fillStyle = '#fff'; ctx.fillRect(-5, -30, 10, 2);
    ctx.fillStyle = isEnemy ? '#ff5555' : '#22d3ee';
    ctx.beginPath(); ctx.moveTo(-15, -15); ctx.lineTo(-45, -40); ctx.lineTo(-15, 5); ctx.fill();
    ctx.beginPath(); ctx.moveTo(15, -15); ctx.lineTo(45, -40); ctx.lineTo(15, 5); ctx.fill();
    drawMechanicalPart(ctx, -22, -25, 12, 12, '#fbbf24', 2);
    drawMechanicalPart(ctx, 10, -25, 12, 12, '#fbbf24', 2);
    const legSwing = Math.sin(frame * 0.15) * 5;
    drawMechanicalPart(ctx, -12, 15, 12, 22 + legSwing, '#333', 4);
    drawMechanicalPart(ctx, 0, 15, 12, 22 - legSwing, '#333', 4);
    ctx.restore();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, type = 'bot', alpha = 1, tier = 0) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8;
    const armSwing = Math.cos(time) * 10;
    let scale = 1;
    if (type === 'scout') scale = 0.8;
    if (type === 'heavy' || type === 'titan') scale = 1.4;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(scale, scale);
    drawMechanicalPart(ctx, -12, -18, 24, 28, color, 4);
    if (!isEnemy && tier > 0) {
      drawMechanicalPart(ctx, -18, -22, 12, 10, '#333', 2);
      drawMechanicalPart(ctx, 6, -22, 12, 10, '#333', 2);
      ctx.fillStyle = '#fff'; ctx.shadowBlur = 10; ctx.shadowColor = color; ctx.beginPath(); ctx.arc(0, -6, 4, 0, Math.PI * 2); ctx.fill(); ctx.shadowBlur = 0;
    }
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? '#ff0000' : '#00f3ff'; ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);
    ctx.restore();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, color: string, frame: number, alpha = 1, tier = 0) => {
    ctx.save(); ctx.globalAlpha = alpha;
    switch(unit) {
      case RobotUnit.SENTINEL:
        drawMechanicalPart(ctx, -28, -10, 56, 20, color, 8);
        drawMechanicalPart(ctx, -18, -22, 36, 14, '#111', 4);
        ctx.fillStyle = frame % 10 < 5 ? '#ff0000' : '#0000ff'; ctx.fillRect(-6, -24, 12, 4);
        ctx.fillStyle = '#111'; ctx.beginPath(); ctx.arc(-18, 12, 8, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.arc(18, 12, 8, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = '#ffffaa'; ctx.fillRect(20, -4, 8, 6);
        if (tier > 0) { ctx.fillStyle = '#fff'; ctx.fillRect(-20, -6, 40, 4); }
        break;
      case RobotUnit.TITAN:
        drawMechanicalPart(ctx, -35, -8, 70, 24, color, 4);
        drawMechanicalPart(ctx, -18, -26, 36, 18, '#222', 4);
        drawMechanicalPart(ctx, 12, -22, 30, 8, '#444', 1);
        ctx.fillStyle = '#111'; ctx.fillRect(-33, 10, 66, 8);
        break;
      case RobotUnit.FALCON:
        drawMechanicalPart(ctx, -24, -8, 48, 16, color, 12);
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.moveTo(-10, -5); ctx.lineTo(-40, -20); ctx.lineTo(-10, 10); ctx.fill();
        ctx.fillStyle = '#ffaa00'; ctx.fillRect(-35, -5, 10, 6);
        break;
      default:
        drawMechanicalPart(ctx, -25, -12, 50, 24, color, 6);
        drawMechanicalPart(ctx, -10, -22, 20, 10, '#333', 2);
        break;
    }
    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy = false, isInvuln = false, isTransformed = false, type = 'bot', alpha = 1, tier = 0, isCombiner = false) => {
    if (isInvuln && frame % 4 < 2) return;
    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    if (facing === -1) ctx.scale(-1, 1);
    if (isCombiner) {
      const isGigantus = isEnemy && engineRef.current.level === 10;
      drawCombiner(ctx, frame, alpha, isEnemy, isGigantus ? 18 : undefined);
    } else {
      const stats = ROBOT_STATS[unit];
      const color = isEnemy ? '#ff0055' : (stats?.color || '#00f3ff');
      if (isTransformed) drawAltMode(ctx, unit, color, frame, alpha, tier);
      else drawHumanoid(ctx, color, frame, isEnemy, type, alpha, tier);
    }
    ctx.restore();
  };

  const resetLevel = useCallback((fullReset = true) => {
    const e = engineRef.current;
    const stats = ROBOT_STATS[e.unit];
    const baseHP = 100 + (upgrades.robotTier * 50);
    if (fullReset) {
      e.player.maxHealth = baseHP * stats.hpMult;
      e.player.health = e.player.maxHealth;
      e.player.unionTimer = 0;
      e.player.inSpaceship = false;
      setIsSpaceshipMode(false);
      e.player.spaceshipPos = { x: 300, y: 340 };
      setUnionTime(0);
      setMaxHealth(e.player.maxHealth);
      setHealth(e.player.health);
      e.player.pos = { x: 100, y: 300 };
      e.player.vel = { x: 0, y: 0 };
      e.player.invulnerable = 0;
      e.player.isTransformed = false;
      setIsTransformed(false);
      e.bullets = [];
      e.cameraX = 0; e.cameraY = 0; e.zoom = 1.0;
      const enemies: Enemy[] = [];
      const floorY = 398;
      const enemyCount = 5;
      for (let i = 0; i < enemyCount; i++) {
        const isBoss = i === enemyCount - 1;
        if (isBoss) {
          const isLvl10Titan = e.level === 10;
          const bossW = isLvl10Titan ? 640 : 64;
          const bossH = isLvl10Titan ? 800 : 80;
          const bossHP = isLvl10Titan ? 20000 : (500 + (e.level * 100));
          enemies.push({ id: i, pos: { x: 2000 + i * 800, y: floorY - bossH }, vel: { x: 0, y: 0 }, width: bossW, height: bossH, health: bossHP, maxHealth: bossHP, isDead: false, type: 'combinerBoss', lastShot: 0, hasSplit: false, unit: RobotUnit.OMEGA });
        } else {
          const type = 'heavy';
          enemies.push({ id: i, pos: { x: 800 + i * 800, y: floorY - 72 }, vel: { x: 0, y: 0 }, width: 48, height: 72, health: 100, maxHealth: 100, isDead: false, type: type, lastShot: 0, unit: RobotUnit.SENTINEL });
        }
      }
      e.enemies = enemies;
    }
  }, [upgrades.robotTier]);

  useEffect(() => { resetLevel(true); }, [level, resetLevel]);

  useEffect(() => {
    const e = engineRef.current;
    const handleKeyDown = (ev: KeyboardEvent) => {
      e.keys[ev.code] = true;
      if (ev.code === 'ShiftLeft' || ev.code === 'ShiftRight') {
        e.player.isTransformed = !e.player.isTransformed;
        setIsTransformed(e.player.isTransformed);
      }
      if (ev.code === 'KeyM' && e.level === 10) {
        const dx = e.player.pos.x - e.player.spaceshipPos.x;
        const dy = e.player.pos.y - e.player.spaceshipPos.y;
        const dist = Math.sqrt(dx*dx + dy*dy);
        if (dist < 100 || e.player.inSpaceship) {
          e.player.inSpaceship = !e.player.inSpaceship;
          setIsSpaceshipMode(e.player.inSpaceship);
          if (e.player.inSpaceship) {
            e.player.maxHealth = 2000;
            e.player.health = 2000;
            setMaxHealth(2000); setHealth(2000);
            soundService.playFly();
          } else {
             const stats = ROBOT_STATS[e.unit];
             const baseHP = 100 + (upgrades.robotTier * 50);
             e.player.maxHealth = baseHP * stats.hpMult;
             e.player.health = Math.min(e.player.health, e.player.maxHealth);
             e.player.spaceshipPos = { ...e.player.pos };
             setMaxHealth(e.player.maxHealth); setHealth(e.player.health);
          }
        }
      }
      if (ev.code === 'KeyC' && e.player.unionTimer <= 0 && !e.player.inSpaceship) {
        e.player.unionTimer = SQUAD_UNION_DURATION;
        e.player.health = 500; e.player.maxHealth = 500;
        setHealth(500); setMaxHealth(500);
        soundService.playFly();
      }
      const trySwitch = (unit: RobotUnit) => {
        if (upgrades.unlockedUnits.includes(unit) && !e.player.inSpaceship) {
          e.unit = unit; setCurrentUnit(unit);
          if (e.player.unionTimer <= 0) {
             const stats = ROBOT_STATS[unit];
             const baseHP = 100 + (upgrades.robotTier * 50);
             e.player.maxHealth = baseHP * stats.hpMult;
             e.player.health = Math.min(e.player.health, e.player.maxHealth);
             setHealth(e.player.health); setMaxHealth(e.player.maxHealth);
          }
        }
      };
      if (ev.code === 'Digit1') trySwitch(RobotUnit.SENTINEL);
      if (ev.code === 'Digit2') trySwitch(RobotUnit.STRIKER);
      if (ev.code === 'Digit3') trySwitch(RobotUnit.FALCON);
      if (ev.code === 'Digit4') trySwitch(RobotUnit.TITAN);
      if (ev.code === 'Digit5') trySwitch(RobotUnit.SPECTER);
    };
    const handleKeyUp = (ev: KeyboardEvent) => { e.keys[ev.code] = false; };
    window.addEventListener('keydown', handleKeyDown); window.addEventListener('keyup', handleKeyUp);
    let animationId: number;
    const loop = () => { if (!e.isPaused) update(); draw(); animationId = requestAnimationFrame(loop); };

    const update = () => {
      const isCombiner = e.player.unionTimer > 0;
      const isShip = e.player.inSpaceship;
      const stats = ROBOT_STATS[e.unit];
      const currentStats = e.player.isTransformed ? stats.alt : stats.robot;
      e.frame++;
      if (isCombiner) {
        e.player.unionTimer--;
        if (e.frame % 10 === 0) setUnionTime(e.player.unionTimer);
      }
      const pw = isShip ? 120 : (isCombiner ? 64 : (e.player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32)));
      const ph = isShip ? 40 : (isCombiner ? 80 : (e.player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48)));
      const moveSpeed = isShip ? 12 : (isCombiner ? 6 : currentStats.speed);
      if (e.keys['ArrowRight'] || e.keys['KeyD']) { e.player.vel.x = moveSpeed; e.player.facing = 1; }
      else if (e.keys['ArrowLeft'] || e.keys['KeyA']) { e.player.vel.x = -moveSpeed; e.player.facing = -1; }
      else e.player.vel.x *= 0.8;
      if (isShip || (e.unit === RobotUnit.FALCON && e.player.isTransformed)) {
        if (e.keys['ArrowUp'] || e.keys['KeyW']) e.player.vel.y = -moveSpeed;
        else if (e.keys['ArrowDown'] || e.keys['KeyS']) e.player.vel.y = moveSpeed;
        else e.player.vel.y *= 0.9;
      } else {
        const jumpPower = isCombiner ? -15 : currentStats.jump;
        if ((e.keys['ArrowUp'] || e.keys['KeyW'] || e.keys['Space']) && e.player.grounded) { e.player.vel.y = jumpPower; e.player.grounded = false; }
        e.player.vel.y += GRAVITY;
      }
      e.player.pos.x += e.player.vel.x; e.player.pos.y += e.player.vel.y;
      const floorY = 398;
      if (!isShip && e.player.pos.y > floorY - ph) { e.player.pos.y = floorY - ph; e.player.vel.y = 0; e.player.grounded = true; }
      if (e.player.pos.x < 0) e.player.pos.x = 0;
      const fr = isShip ? 3 : (isCombiner ? 8 : Math.max(5, currentStats.fireRate - upgrades.weaponTier * 2));
      if (e.keys['Space'] && e.frame - e.player.lastShot > fr) {
        soundService.playShoot();
        const dmg = isShip ? 1200 : (isCombiner ? 500 : 100);
        if (isShip) {
          e.bullets.push({ pos: { x: e.player.pos.x + (e.player.facing === 1 ? pw : -400), y: e.player.pos.y + ph/2 - 4 }, vel: { x: e.player.facing * 35, y: 0 }, width: 400, height: 8, owner: 'player', health: 1, maxHealth: 1, damage: dmg, color: '#00f3ff' });
        } else if (isCombiner) {
          e.bullets.push({ pos: { x: e.player.pos.x + (e.player.facing === 1 ? pw : 0), y: e.player.pos.y + ph/2 - 10 }, vel: { x: e.player.facing * 20, y: 0 }, width: 32, height: 20, owner: 'player', health: 1, maxHealth: 1, damage: dmg, color: '#fff' });
        } else {
          e.bullets.push({ pos: { x: e.player.pos.x + (e.player.facing === 1 ? pw : 0), y: e.player.pos.y + ph/2 }, vel: { x: e.player.facing * 15, y: 0 }, width: 12, height: 4, owner: 'player', health: 1, maxHealth: 1, damage: dmg, color: stats.color });
        }
        e.player.lastShot = e.frame;
      }
      for (let i = e.bullets.length - 1; i >= 0; i--) {
        const b = e.bullets[i]; b.pos.x += b.vel.x; b.pos.y += b.vel.y;
        if (b.owner === 'enemy' && !e.player.invulnerable) {
          if (b.pos.x < e.player.pos.x + pw && b.pos.x + b.width > e.player.pos.x && b.pos.y < e.player.pos.y + ph && b.pos.y + b.height > e.player.pos.y) {
            e.player.health = Math.max(0, e.player.health - 20); e.player.invulnerable = 40;
            setHealth(e.player.health); e.bullets.splice(i, 1); soundService.playLose(); continue;
          }
        }
        if (Math.abs(b.pos.x - e.player.pos.x) > 3000) e.bullets.splice(i, 1);
      }
      let allDead = true;
      const newEnemies: Enemy[] = [];
      e.enemies.forEach(en => {
        if (en.isDead) return;
        allDead = false;

        // Split logic: Spawn robots directly on the ground
        if (en.type === 'combinerBoss' && !en.hasSplit && en.health < en.maxHealth * 0.2) {
          en.isDead = true; en.hasSplit = true; soundService.playFly();
          const scoutHeight = 36;
          for (let s = 0; s < 6; s++) {
            newEnemies.push({ 
              id: Date.now() + s, 
              pos: { 
                x: en.pos.x + (Math.random() * en.width), 
                y: floorY - scoutHeight // PLACED DIRECTLY ON THE GROUND
              }, 
              vel: { x: (Math.random() - 0.5) * 6, y: 0 }, // ZERO VERTICAL VELOCITY
              width: 24, 
              height: scoutHeight, 
              health: 150, 
              maxHealth: 150, 
              isDead: false, 
              type: 'scout', 
              lastShot: e.frame, 
              unit: RobotUnit.STRIKER 
            });
          }
          return;
        }
        const dir = Math.sign(e.player.pos.x - en.pos.x);
        const speed = en.type === 'scout' ? 2.5 : (en.type === 'combinerBoss' ? 0.3 : 0.6);
        en.pos.x += dir * speed;
        const shootFreq = en.type === 'combinerBoss' ? 45 : (en.type === 'scout' ? 90 : 120);
        if (Math.abs(en.pos.x - e.player.pos.x) < 1200 && e.frame - en.lastShot > shootFreq) {
          const bW = en.type === 'combinerBoss' ? 24 : 10;
          const bH = en.type === 'combinerBoss' ? 10 : 4;
          e.bullets.push({ pos: {x: en.pos.x + (dir > 0 ? en.width : 0), y: en.pos.y + en.height / 2}, vel: {x: dir * 8, y: 0}, width: bW, height: bH, owner: 'enemy', health: 1, maxHealth: 1, damage: 20, color: '#f00' });
          en.lastShot = e.frame;
        }
        e.bullets.forEach((b, bIdx) => {
          if (b.owner === 'player' && !en.isDead && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) {
            en.health -= (b.damage || 100); if (en.health <= 0) en.isDead = true;
            e.bullets.splice(bIdx, 1);
          }
        });
      });
      if (newEnemies.length > 0) e.enemies.push(...newEnemies);
      if (e.player.health <= 0) onDie();
      if (allDead && newEnemies.length === 0) onWin();
      if (e.player.invulnerable > 0) e.player.invulnerable--;
      const isLvl10 = e.level === 10;
      const targetZoom = isLvl10 ? 0.45 : 1.0;
      e.zoom += (targetZoom - e.zoom) * 0.05;
      const visibleWidth = CANVAS_WIDTH / e.zoom;
      e.cameraX = e.player.pos.x - visibleWidth * 0.3;
      const targetCameraY = isLvl10 ? (398 - (CANVAS_HEIGHT / e.zoom) + 120) : 0;
      e.cameraY += (targetCameraY - e.cameraY) * 0.05;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      ctx.save(); ctx.scale(e.zoom, e.zoom); ctx.translate(-e.cameraX, -e.cameraY);
      const visibleWidth = CANVAS_WIDTH / e.zoom; const visibleHeight = CANVAS_HEIGHT / e.zoom;
      ctx.fillStyle = '#050510'; ctx.fillRect(e.cameraX, e.cameraY, visibleWidth, visibleHeight);
      ctx.fillStyle = '#111'; ctx.fillRect(e.cameraX - 1000, 398, visibleWidth + 2000, 1000); ctx.strokeStyle = '#222';
      const startX = Math.floor(e.cameraX / 40) * 40;
      for(let i = startX - 40; i < e.cameraX + visibleWidth + 40; i += 40) ctx.strokeRect(i, 398, 40, 52);
      if (e.level === 10 && !e.player.inSpaceship) {
        ctx.save(); ctx.translate(e.player.spaceshipPos.x + 60, e.player.spaceshipPos.y + 20); drawSpaceship(ctx, e.frame, 0.8); ctx.restore();
        ctx.fillStyle = '#fff'; ctx.font = '10px Orbitron'; ctx.fillText("[M] ENTER SHIP", e.player.spaceshipPos.x + 10, e.player.spaceshipPos.y - 20);
      }
      e.enemies.forEach(en => { if(!en.isDead) drawUnit(ctx, en.pos.x, en.pos.y, en.width, en.height, en.unit || RobotUnit.SENTINEL, Math.sign(e.player.pos.x - en.pos.x), e.frame, true, false, en.isTransformed, en.type, 1, 0, en.type === 'combinerBoss'); });
      if (e.player.inSpaceship) {
        ctx.save(); ctx.translate(e.player.pos.x + 60, e.player.pos.y + 20); if (e.player.facing === -1) ctx.scale(-1, 1);
        drawSpaceship(ctx, e.frame, 1); ctx.restore();
      } else {
        const isCombiner = e.player.unionTimer > 0;
        const pw = isCombiner ? 64 : (e.player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32));
        const ph = isCombiner ? 80 : (e.player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48));
        drawUnit(ctx, e.player.pos.x, e.player.pos.y, pw, ph, e.unit, e.player.facing, e.frame, false, e.player.invulnerable > 0, e.player.isTransformed, 'bot', 1, upgrades.robotTier, isCombiner);
      }
      e.bullets.forEach(b => { 
        ctx.fillStyle = b.color || '#00f3ff'; if (b.width > 20) { ctx.shadowBlur = 10; ctx.shadowColor = b.color || '#fff'; } 
        ctx.fillRect(b.pos.x, b.pos.y, b.width, b.height); ctx.shadowBlur = 0; 
      });
      ctx.restore();
    };
    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [onWin, onDie, upgrades.unlockedUnits, upgrades.weaponTier, upgrades.robotTier]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden font-orbitron">
      <div className="absolute top-4 left-4 z-10 space-y-4 pointer-events-none w-[400px]">
        <div className="bg-black/80 border border-cyan-500/50 p-3 rounded backdrop-blur-md shadow-lg">
          <div className="text-[10px] text-cyan-400 font-bold uppercase mb-1 flex justify-between">
            <span>{isSpaceshipMode ? 'INTERCEPTOR SHIP' : (unionTime > 0 ? 'SQUAD COMBINER' : `${ROBOT_STATS[currentUnit].name} CHASSIS`)}</span>
            <span>{Math.round(health)}/{Math.round(maxHealth)}</span>
          </div>
          <div className="w-48 h-2.5 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
            <div className="h-full shadow-[0_0_15px_#00f3ff] transition-all duration-300" style={{ width: `${(health / maxHealth) * 100}%`, backgroundColor: health < maxHealth * 0.3 ? '#ef4444' : (unionTime > 0 || isSpaceshipMode ? '#fff' : '#00f3ff') }} />
          </div>
          {unionTime > 0 && (
            <div className="mt-2">
              <div className="text-[8px] text-yellow-400 font-bold uppercase mb-0.5">COMBINER INTEGRITY</div>
              <div className="w-full h-1 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
                <div className="h-full bg-yellow-500 shadow-[0_0_10px_#fbbf24] transition-all duration-100" style={{ width: `${(unionTime / SQUAD_UNION_DURATION) * 100}%` }} />
              </div>
            </div>
          )}
        </div>
      </div>
      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full aspect-video shadow-2xl rounded-lg border-2 border-cyan-900/50" />
      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 pointer-events-none text-white/30 text-[8px] font-mono tracking-widest uppercase flex gap-6">
        <span>WASD: Move</span><span>Space: Fire</span><span>Shift: Transform</span><span>1-5: Squad</span><span>C: Combine</span>{level === 10 && <span>M: Ship</span>}
      </div>
      {(unionTime > SQUAD_UNION_DURATION - 60 || (isSpaceshipMode && engineRef.current.frame % 60 < 30)) && (
        <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
          <div className="text-6xl font-black italic text-white tracking-tighter shadow-2xl animate-pulse uppercase">{isSpaceshipMode ? 'Heavy Laser Online' : 'Squad Combination Engaged'}</div>
        </div>
      )}
      {level === 10 && (
        <div className="absolute top-20 right-4 p-4 border border-red-500 bg-red-950/20 text-red-500 text-xs animate-pulse uppercase tracking-widest">
           Warning: Gigantus Titan Detected
        </div>
      )}
    </div>
  );
};

export default GameView;

import React, { useState, useEffect, useCallback } from 'react';
import { GameState, LevelInfo, RobotUnit, Upgrades } from './types';
import { getLevelBriefing } from './services/geminiService';
import MainMenu from './components/MainMenu';
import Briefing from './components/Briefing';
import GameView from './components/GameView';
import GameOver from './components/GameOver';
import Victory from './components/Victory';
import Shop from './components/Shop';
import RobotShop from './components/RobotShop';
import LevelSelect from './components/LevelSelect';

const SAVE_KEY = 'cybercop_save_data';

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>(GameState.MENU);
  const [level, setLevel] = useState(1);
  const [maxUnlockedLevel, setMaxUnlockedLevel] = useState(1);
  const [money, setMoney] = useState(0);
  const [upgrades, setUpgrades] = useState<Upgrades>({ 
    robotTier: 0, 
    weaponTier: 0, 
    unlockedUnits: [RobotUnit.SENTINEL] 
  });
  const [briefing, setBriefing] = useState<LevelInfo | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [hasSave, setHasSave] = useState(false);
  const [shopOrigin, setShopOrigin] = useState<GameState>(GameState.MENU);
  const [saveFeedback, setSaveFeedback] = useState(false);

  // Load progress on mount
  useEffect(() => {
    const savedData = localStorage.getItem(SAVE_KEY);
    if (savedData) {
      const parsed = JSON.parse(savedData);
      setHasSave(true);
      const savedLvl = parsed.level || 1;
      setLevel(savedLvl);
      setMaxUnlockedLevel(parsed.maxUnlockedLevel || savedLvl || 1);
      setMoney(parsed.money || 0);
      setUpgrades(parsed.upgrades || { 
        robotTier: 0, 
        weaponTier: 0, 
        unlockedUnits: [RobotUnit.SENTINEL] 
      });
    }
  }, []);

  // Global pause listener
  useEffect(() => {
    const handleGlobalKeyDown = (e: KeyboardEvent) => {
      if (e.code === 'KeyP') {
        setGameState(prev => {
          if (prev === GameState.PLAYING) return GameState.PAUSED;
          if (prev === GameState.PAUSED) return GameState.PLAYING;
          return prev;
        });
      }
    };
    window.addEventListener('keydown', handleGlobalKeyDown);
    return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, []);

  const saveToStorage = useCallback(() => {
    const saveData = {
      level,
      maxUnlockedLevel,
      money,
      upgrades
    };
    localStorage.setItem(SAVE_KEY, JSON.stringify(saveData));
    setHasSave(true);
    setSaveFeedback(true);
    setTimeout(() => setSaveFeedback(false), 2000);
  }, [level, maxUnlockedLevel, money, upgrades]);

  useEffect(() => {
    if (gameState !== GameState.MENU && gameState !== GameState.PAUSED && gameState !== GameState.LEVEL_SELECT) {
      const saveData = {
        level,
        maxUnlockedLevel,
        money,
        upgrades
      };
      localStorage.setItem(SAVE_KEY, JSON.stringify(saveData));
    }
  }, [level, maxUnlockedLevel, money, upgrades, gameState]);

  const startLevel = useCallback(async (lvl: number) => {
    setIsLoading(true);
    setGameState(GameState.BRIEFING);
    setLevel(lvl);
    const data = await getLevelBriefing(lvl);
    setBriefing(data);
    setIsLoading(false);
  }, []);

  const handleStartGame = () => {
    setLevel(1);
    setMaxUnlockedLevel(1);
    setMoney(0);
    setUpgrades({ robotTier: 0, weaponTier: 0, unlockedUnits: [RobotUnit.SENTINEL] });
    startLevel(1);
  };

  const handleContinueGame = () => {
    const savedData = localStorage.getItem(SAVE_KEY);
    if (savedData) {
      const parsed = JSON.parse(savedData);
      const targetLevel = parsed.level || 1;
      setLevel(targetLevel);
      setMaxUnlockedLevel(parsed.maxUnlockedLevel || targetLevel || 1);
      setMoney(parsed.money || 0);
      setUpgrades(parsed.upgrades || { 
        robotTier: 0, 
        weaponTier: 0, 
        unlockedUnits: [RobotUnit.SENTINEL] 
      });
      startLevel(targetLevel);
    }
  };

  const handleLevelComplete = () => {
    // Huge reward for Level 20 boss to allow buying all robots
    const reward = level === 20 ? 15000 : 150;
    setMoney(prev => prev + reward); 
    const completedLevel = level;
    const nextLvl = level + 1;

    if (nextLvl > maxUnlockedLevel) {
      setMaxUnlockedLevel(nextLvl);
    }

    if (completedLevel >= 20) {
      setGameState(GameState.VICTORY);
    } else {
      setLevel(nextLvl);
      setGameState(GameState.LEVEL_COMPLETE);
    }
  };

  const openShop = (origin: GameState) => {
    setShopOrigin(origin);
    setGameState(GameState.SHOP);
  };

  const openRobotShop = () => {
    setGameState(GameState.ROBOT_SHOP);
  };

  const openLevelSelect = () => {
    setGameState(GameState.LEVEL_SELECT);
  };

  const handleSelectLevel = (lvlNum: number) => {
    startLevel(lvlNum);
  };

  const handleNextLevel = () => {
    startLevel(level);
  };

  const handleShopExit = () => {
    if (shopOrigin === GameState.MENU) {
      setGameState(GameState.MENU);
      setHasSave(true);
    } else {
      handleNextLevel();
    }
  };

  const handlePlayerDeath = () => {
    setGameState(GameState.GAMEOVER);
  };

  const handleRetry = () => {
    startLevel(level);
  };

  const buyRobotTier = () => {
    if (money >= 100) {
      setMoney(m => m - 100);
      setUpgrades(u => ({ ...u, robotTier: u.robotTier + 1 }));
    }
  };

  const buyWeaponTier = () => {
    if (money >= 50) {
      setMoney(m => m - 50);
      setUpgrades(u => ({ ...u, weaponTier: u.weaponTier + 1 }));
    }
  };

  const unlockRobotUnit = (unit: RobotUnit, price: number) => {
    if (money >= price && !upgrades.unlockedUnits.includes(unit)) {
      setMoney(m => m - price);
      setUpgrades(u => ({
        ...u,
        unlockedUnits: [...u.unlockedUnits, unit]
      }));
    }
  };

  const isGameVisible = gameState === GameState.PLAYING || gameState === GameState.PAUSED;

  return (
    <div className="w-full h-screen bg-black overflow-hidden select-none text-white font-rajdhani">
      {/* Global Save Button */}
      <button 
        onClick={saveToStorage}
        className={`fixed top-4 right-4 z-[100] px-4 py-2 border font-bold text-xs uppercase tracking-widest transition-all font-orbitron shadow-lg ${
          saveFeedback 
            ? 'bg-emerald-600 border-emerald-400 text-white animate-pulse' 
            : 'bg-cyan-950/80 border-cyan-500 text-cyan-400 hover:bg-cyan-500 hover:text-black'
        }`}
      >
        {saveFeedback ? 'SYSTEM SAVED' : 'SAVE PROGRESS'}
      </button>

      {gameState === GameState.MENU && (
        <MainMenu 
          onStart={handleStartGame} 
          onContinue={handleContinueGame} 
          onOpenShop={() => openShop(GameState.MENU)}
          onOpenRobotShop={openRobotShop}
          onOpenLevelSelect={openLevelSelect}
          hasSave={hasSave} 
        />
      )}

      {gameState === GameState.LEVEL_SELECT && (
        <LevelSelect 
          currentUnlocked={maxUnlockedLevel} 
          onSelect={handleSelectLevel} 
          onBack={() => setGameState(GameState.MENU)} 
        />
      )}

      {gameState === GameState.BRIEFING && briefing && (
        <Briefing 
          briefing={briefing} 
          isLoading={isLoading} 
          onConfirm={() => setGameState(GameState.PLAYING)} 
        />
      )}

      {isGameVisible && (
        <GameView 
          level={level} 
          upgrades={upgrades}
          isPaused={gameState === GameState.PAUSED}
          onWin={handleLevelComplete} 
          onDie={handlePlayerDeath} 
        />
      )}

      {gameState === GameState.PAUSED && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex flex-col items-center justify-center z-50 animate-in fade-in duration-200">
          <div className="p-10 border-2 border-cyan-500 bg-black/80 relative overflow-hidden group">
            <div className="absolute top-0 left-0 w-full h-1 bg-cyan-500 animate-scan"></div>
            <h2 className="text-6xl font-black text-cyan-400 italic tracking-tighter uppercase mb-4">SYSTEM SUSPENDED</h2>
            <p className="text-cyan-200 font-mono tracking-widest text-center mb-8">TACTICAL ANALYSIS IN PROGRESS</p>
            <div className="flex flex-col gap-4 items-center">
              <button 
                onClick={() => setGameState(GameState.PLAYING)}
                className="px-12 py-4 bg-cyan-600 hover:bg-cyan-500 text-white font-bold text-2xl border-b-4 border-cyan-900 transition-all w-full uppercase"
              >
                RESUME MISSION
              </button>
              <button 
                onClick={() => setGameState(GameState.MENU)}
                className="px-12 py-2 text-cyan-400 font-bold hover:text-white transition-all uppercase text-sm"
              >
                ABORT TO HQ
              </button>
            </div>
          </div>
        </div>
      )}

      {gameState === GameState.LEVEL_COMPLETE && (
        <div className="fixed inset-0 bg-black/90 flex flex-col items-center justify-center z-50">
          <h2 className="text-5xl text-cyan-400 mb-2 font-black italic tracking-tighter animate-pulse uppercase">
            Sector {level - 1} Secured
          </h2>
          <div className="text-2xl text-yellow-400 mb-8 font-bold tracking-widest font-orbitron">REWARD EARNED: ${level === 20 ? 15000 : 150}</div>
          <div className="flex gap-4 mb-4">
            <button 
              onClick={() => openShop(GameState.LEVEL_COMPLETE)}
              className="px-8 py-4 bg-yellow-600 hover:bg-yellow-500 text-white font-bold rounded-sm border-b-4 border-yellow-800 transition-all active:translate-y-1 w-64 shadow-[0_0_20px_rgba(202,138,4,0.3)] font-orbitron uppercase"
            >
              VISIT ARMORY
            </button>
            <button 
              onClick={() => setGameState(GameState.ROBOT_SHOP)}
              className="px-8 py-4 bg-purple-700 hover:bg-purple-600 text-white font-bold rounded-sm border-b-4 border-purple-900 transition-all active:translate-y-1 w-64 shadow-[0_0_20px_rgba(168,85,247,0.3)] font-orbitron uppercase"
            >
              SQUAD ASSEMBLY
            </button>
          </div>
          <button 
            onClick={handleNextLevel}
            className="px-12 py-3 bg-cyan-700 hover:bg-cyan-600 text-white font-bold rounded-sm transition-all w-[33rem] uppercase tracking-wider font-orbitron"
          >
            Deploy to Sector {level}
          </button>
          <button 
            onClick={() => {
              setGameState(GameState.MENU);
              setHasSave(true);
            }}
            className="px-12 py-2 text-gray-400 font-bold hover:text-white transition-all uppercase text-sm mt-8 border border-gray-800 hover:border-gray-400 bg-gray-950/40"
          >
            Return to HQ
          </button>
        </div>
      )}

      {gameState === GameState.SHOP && (
        <Shop 
          money={money} 
          upgrades={upgrades} 
          onBuyRobot={buyRobotTier} 
          onBuyWeapon={buyWeaponTier} 
          onExit={handleShopExit}
          isFromMenu={shopOrigin === GameState.MENU}
        />
      )}

      {gameState === GameState.ROBOT_SHOP && (
        <RobotShop 
          money={money} 
          unlockedUnits={upgrades.unlockedUnits} 
          onUnlock={unlockRobotUnit} 
          onExit={() => setGameState(GameState.MENU)}
        />
      )}

      {gameState === GameState.GAMEOVER && (
        <GameOver level={level} onRetry={handleRetry} onMenu={() => setGameState(GameState.MENU)} />
      )}

      {gameState === GameState.VICTORY && (
        <Victory onMenu={() => {
          localStorage.removeItem(SAVE_KEY);
          setHasSave(false);
          setGameState(GameState.MENU);
        }} />
      )}
    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { LevelInfo } from "../types";

// Fix: Initialize the GoogleGenAI client correctly using only process.env.API_KEY as per guidelines
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const delay = (ms: number) => new Promise(res => setTimeout(res, ms));

async function callGeminiWithRetry(level: number, specialPrompt: string, retries = 2): Promise<any> {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Generate a short cyberpunk mission briefing for Level ${level} of a robot police officer game. 
      ${specialPrompt || "The goal is to destroy hostiles in the sector."}
      Provide a cool title, threat level, and a 2-sentence description emphasizing the threat in the burning city.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            level: { type: Type.INTEGER },
            title: { type: Type.STRING },
            description: { type: Type.STRING },
            threatLevel: { type: Type.STRING },
            enemyType: { type: Type.STRING }
          },
          required: ["level", "title", "description", "threatLevel", "enemyType"]
        }
      }
    });
    return JSON.parse(response.text || "{}");
  } catch (error: any) {
    if (retries > 0 && (error?.status === 429 || error?.message?.includes('429'))) {
      console.warn(`Gemini 429 encountered. Retrying in ${3 - retries}s...`);
      await delay(1000 * (3 - retries));
      return callGeminiWithRetry(level, specialPrompt, retries - 1);
    }
    throw error;
  }
}

export const getLevelBriefing = async (level: number): Promise<LevelInfo> => {
  let specialPrompt = "";
  if (level === 5) specialPrompt = "The player must destroy a battalion of heavy 'Tank-formers' — massive transforming siege units that are leveling the district.";
  if (level === 10) specialPrompt = "Gigantus Titan encounter. A massive combiner robot that threatens the entire sector.";
  if (level === 20) specialPrompt = "This is the final showdown against the CYBER DRAGON. A massive flying mechanical beast with laser breath. Mention that this is the final hurdle to world peace.";

  try {
    return await callGeminiWithRetry(level, specialPrompt);
  } catch (error) {
    console.error("Gemini failed, using fallback briefing", error);
    return {
      level,
      title: level === 20 ? "The Cyber Dragon" : (level === 5 ? "Tank-former Siege" : `Sector ${level} Purge`),
      description: level === 5 
        ? "Heavy transforming units have breached the perimeter. Neutralize all Tank-formers before they flatten the sector." 
        : (level === 20 ? "The final rogue AI core has manifested as a colossal Cyber Dragon. Neutralize this airborne terror to secure permanent peace for the city." : "Hostile units detected in the burning sector. Cleanse the area."),
      threatLevel: level >= 20 ? "GODLIKE" : (level >= 10 ? "Extreme" : (level >= 5 ? "Very High" : "High")),
      enemyType: level === 20 ? "Ancient Cyber Dragon" : (level === 10 ? "Gigantus Titan" : (level === 5 ? "Tank-formers" : "Rogue Battalion"))
    };
  }
};

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const SQUAD_UNION_DURATION = 60 * 60; // 60 seconds (1 minute) at 60fps

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { 
    name: "SENTINEL", color: '#00f3ff', hpMult: 1.0, 
    robot: { speed: 4, jump: -11, fireRate: 15 },
    alt: { speed: 8, jump: -5, fireRate: 25, type: 'Car' }
  },
  [RobotUnit.STRIKER]: { 
    name: "STRIKER", color: '#fbbf24', hpMult: 0.8,
    robot: { speed: 6, jump: -10, fireRate: 10 },
    alt: { speed: 12, jump: -4, fireRate: 20, type: 'Bike' }
  },
  [RobotUnit.FALCON]: { 
    name: "FALCON", color: '#22d3ee', hpMult: 0.7,
    robot: { speed: 5, jump: -10, fireRate: 12 },
    alt: { speed: 7, jump: -7, fireRate: 15, type: 'Jet' }
  },
  [RobotUnit.TITAN]: { 
    name: "TITAN", color: '#ef4444', hpMult: 2.5,
    robot: { speed: 2.5, jump: -12, fireRate: 30 },
    alt: { speed: 4, jump: 0, fireRate: 20, type: 'Tank' }
  },
  [RobotUnit.SPECTER]: { 
    name: "SPECTER", color: '#a855f7', hpMult: 0.6,
    robot: { speed: 5, jump: -11, fireRate: 20 },
    alt: { speed: 6, jump: -14, fireRate: 40, type: 'Energy Sphere' }
  },
  [RobotUnit.VANGUARD]: { 
    name: "VANGUARD", color: '#10b981', hpMult: 2.0, 
    robot: { speed: 3.5, jump: -10, fireRate: 25 },
    alt: { speed: 6, jump: -4, fireRate: 30, type: 'Shield Truck' }
  },
  [RobotUnit.NIGHTSHADE]: { 
    name: "NIGHTSHADE", color: '#6366f1', hpMult: 0.9, 
    robot: { speed: 7, jump: -13, fireRate: 12 },
    alt: { speed: 10, jump: -6, fireRate: 18, type: 'Interceptor' }
  },
  [RobotUnit.BLAZE]: { 
    name: "BLAZE", color: '#f97316', hpMult: 1.2, 
    robot: { speed: 4.5, jump: -11, fireRate: 18 },
    alt: { speed: 7, jump: -5, fireRate: 22, type: 'Rig' }
  },
  [RobotUnit.GLITCH]: { 
    name: "GLITCH", color: '#ec4899', hpMult: 1.0, 
    robot: { speed: 5, jump: -12, fireRate: 14 },
    alt: { speed: 9, jump: -12, fireRate: 16, type: 'Splicer' }
  },
  [RobotUnit.OMEGA]: { 
    name: "OMEGA", color: '#ffffff', hpMult: 3.0, 
    robot: { speed: 6, jump: -14, fireRate: 10 },
    alt: { speed: 10, jump: -8, fireRate: 15, type: 'Fortress' }
  },
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [currentUnit, setCurrentUnit] = useState<RobotUnit>(RobotUnit.SENTINEL);
  const [isTransformed, setIsTransformed] = useState(false);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [unionTime, setUnionTime] = useState(0);
  const [isSpaceshipMode, setIsSpaceshipMode] = useState(false);

  const engineRef = useRef({
    player: {
      pos: { x: 100, y: 300 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      health: 100,
      maxHealth: 100,
      isTransformed: false,
      unionTimer: 0,
      inSpaceship: false,
      spaceshipPos: { x: 300, y: 340 },
    },
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    cameraY: 0,
    zoom: 1.0,
    isPaused: isPaused,
    unit: RobotUnit.SENTINEL,
    level: level,
  });

  useEffect(() => { engineRef.current.isPaused = isPaused; }, [isPaused]);
  useEffect(() => { engineRef.current.level = level; }, [level]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4, border = true) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff66');
    grad.addColorStop(1, '#000000aa');
    ctx.fillStyle = grad;
    ctx.fill();
    if (border) {
      ctx.strokeStyle = 'rgba(0,0,0,0.6)';
      ctx.lineWidth = 1;
      ctx.stroke();
    }
  };

  const drawDragon = (ctx: CanvasRenderingContext2D, frame: number, alpha: number) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(2.5, 2.5);

    const bodyColor = '#334155';
    const highlightColor = '#ff0055';
    const time = frame * 0.1;

    // Wings
    const wingFlap = Math.sin(time * 0.5) * 40;
    ctx.fillStyle = highlightColor;
    ctx.beginPath();
    ctx.moveTo(0, 0); ctx.lineTo(-80, -40 + wingFlap); ctx.lineTo(-20, 20); ctx.fill();
    ctx.beginPath();
    ctx.moveTo(0, 0); ctx.lineTo(80, -40 + wingFlap); ctx.lineTo(20, 20); ctx.fill();

    // Segments (Tail)
    for (let i = 0; i < 8; i++) {
        const segX = Math.sin(time + i * 0.5) * 20;
        const segY = 20 + i * 15;
        drawMechanicalPart(ctx, -10 + segX, segY, 20, 15, bodyColor, 4);
    }

    // Body
    drawMechanicalPart(ctx, -15, -10, 30, 40, bodyColor, 10);

    // Neck & Head
    const headSwing = Math.sin(time * 0.8) * 10;
    ctx.save();
    ctx.translate(headSwing, -30);
    drawMechanicalPart(ctx, -10, -10, 20, 25, bodyColor, 5); // Neck
    drawMechanicalPart(ctx, -12, -25, 24, 18, bodyColor, 8); // Head

    // Eyes
    ctx.fillStyle = '#ff0000';
    ctx.beginPath(); ctx.arc(-6, -20, 3, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(6, -20, 3, 0, Math.PI * 2); ctx.fill();

    // Fire Breath glow
    if (frame % 60 < 20) {
        ctx.fillStyle = '#ff5500';
        ctx.shadowBlur = 15; ctx.shadowColor = '#ff0000';
        ctx.beginPath(); ctx.arc(0, -15, 8, 0, Math.PI * 2); ctx.fill();
        ctx.shadowBlur = 0;
    }
    ctx.restore();

    ctx.restore();
  };

  const drawSpaceship = (ctx: CanvasRenderingContext2D, frame: number, alpha: number) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(1.5, 1.2);
    // Body
    drawMechanicalPart(ctx, -40, -15, 80, 30, '#1e293b', 15);
    drawMechanicalPart(ctx, -30, -25, 60, 20, '#334155', 10);
    // Cockpit
    ctx.fillStyle = '#00f3ff';
    ctx.beginPath();
    ctx.ellipse(0, -15, 20, 10, 0, 0, Math.PI * 2);
    ctx.fill();
    // Wings
    ctx.fillStyle = '#1e293b';
    ctx.beginPath(); ctx.moveTo(-20, 0); ctx.lineTo(-60, 20); ctx.lineTo(-20, 15); ctx.fill();
    ctx.beginPath(); ctx.moveTo(20, 0); ctx.lineTo(60, 20); ctx.lineTo(20, 15); ctx.fill();
    // Thrusters
    const fireSize = 10 + Math.sin(frame * 0.5) * 5;
    ctx.fillStyle = '#fbbf24';
    ctx.beginPath(); ctx.arc(-35, 10, fireSize, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(35, 10, fireSize, 0, Math.PI * 2); ctx.fill();
    // Laser Cannons
    drawMechanicalPart(ctx, -45, -5, 15, 5, '#475569', 2);
    drawMechanicalPart(ctx, 30, -5, 15, 5, '#475569', 2);
    ctx.restore();
  };

  const drawCombiner = (ctx: CanvasRenderingContext2D, frame: number, alpha: number, isEnemy = false, scaleOverride?: number) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    const scale = scaleOverride || 1.8;
    ctx.scale(scale, scale);
    ctx.shadowBlur = isEnemy ? 25 : 15;
    ctx.shadowColor = isEnemy ? '#ff0055' : '#fff';
    const primaryColor = isEnemy ? '#ff0055' : '#00f3ff';
    const secondaryColor = isEnemy ? '#440022' : '#ef4444';
    drawMechanicalPart(ctx, -15, -20, 30, 35, primaryColor, 6);
    drawMechanicalPart(ctx, -10, -15, 20, 20, secondaryColor, 4);
    ctx.fillStyle = isEnemy ? '#ff0000' : '#fff';
    ctx.beginPath();
    ctx.arc(0, -5, 6 + Math.sin(frame * 0.2) * 2, 0, Math.PI * 2);
    ctx.fill();
    drawMechanicalPart(ctx, -8, -38, 16, 16, '#111', 8);
    ctx.fillStyle = '#fff'; ctx.fillRect(-5, -30, 10, 2);
    ctx.fillStyle = isEnemy ? '#ff5555' : '#22d3ee';
    ctx.beginPath(); ctx.moveTo(-15, -15); ctx.lineTo(-45, -40); ctx.lineTo(-15, 5); ctx.fill();
    ctx.beginPath(); ctx.moveTo(15, -15); ctx.lineTo(45, -40); ctx.lineTo(15, 5); ctx.fill();
    drawMechanicalPart(ctx, -22, -25, 12, 12, '#fbbf24', 2);
    drawMechanicalPart(ctx, 10, -25, 12, 12, '#fbbf24', 2);
    const legSwing = Math.sin(frame * 0.15) * 5;
    drawMechanicalPart(ctx, -12, 15, 12, 22 + legSwing, '#333', 4);
    drawMechanicalPart(ctx, 0, 15, 12, 22 - legSwing, '#333', 4);
    ctx.restore();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, type = 'bot', alpha = 1, tier = 0) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8;
    const armSwing = Math.cos(time) * 10;
    let scale = 1;
    if (type === 'scout') scale = 0.8;
    if (type === 'heavy' || type === 'titan') scale = 1.4;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(scale, scale);
    drawMechanicalPart(ctx, -12, -18, 24, 28, color, 4);
    if (!isEnemy && tier > 0) {
      drawMechanicalPart(ctx, -18, -22, 12, 10, '#333', 2);
      drawMechanicalPart(ctx, 6, -22, 12, 10, '#333', 2);
      ctx.fillStyle = '#fff'; ctx.shadowBlur = 10; ctx.shadowColor = color; ctx.beginPath(); ctx.arc(0, -6, 4, 0, Math.PI * 2); ctx.fill(); ctx.shadowBlur = 0;
    }
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? '#ff0000' : '#00f3ff'; ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);
    ctx.restore();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, color: string, frame: number, alpha = 1, tier = 0) => {
    ctx.save(); ctx.globalAlpha = alpha;
    switch(unit) {
      case RobotUnit.SENTINEL:
        drawMechanicalPart(ctx, -28, -10, 56, 20, color, 8);
        drawMechanicalPart(ctx, -18, -22, 36, 14, '#111', 4);
        ctx.fillStyle = frame % 10 < 5 ? '#ff0000' : '#0000ff'; ctx.fillRect(-6, -24, 12, 4);
        ctx.fillStyle = '#111'; ctx.beginPath(); ctx.arc(-18, 12, 8, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.arc(18, 12, 8, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = '#ffffaa'; ctx.fillRect(20, -4, 8, 6);
        if (tier > 0) { ctx.fillStyle = '#fff'; ctx.fillRect(-20, -6, 40, 4); }
        break;
      case RobotUnit.TITAN:
        drawMechanicalPart(ctx, -35, -8, 70, 24, color, 4);
        drawMechanicalPart(ctx, -18, -26, 36, 18, '#222', 4);
        drawMechanicalPart(ctx, 12, -22, 30, 8, '#444', 1);
        ctx.fillStyle = '#111'; ctx.fillRect(-33, 10, 66, 8);
        break;
      case RobotUnit.FALCON:
        drawMechanicalPart(ctx, -24, -8, 48, 16, color, 12);
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.moveTo(-10, -5); ctx.lineTo(-40, -20); ctx.lineTo(-10, 10); ctx.fill();
        ctx.fillStyle = '#ffaa00'; ctx.fillRect(-35, -5, 10, 6);
        break;
      default:
        drawMechanicalPart(ctx, -25, -12, 50, 24, color, 6);
        drawMechanicalPart(ctx, -10, -22, 20, 10, '#333', 2);
        break;
    }
    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy = false, isInvuln = false, isTransformed = false, type = 'bot', alpha = 1, tier = 0, isCombiner = false) => {
    if (isInvuln && frame % 4 < 2) return;
    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    if (facing === -1) ctx.scale(-1, 1);
    if (type === 'dragonBoss') {
        drawDragon(ctx, frame, alpha);
    } else if (isCombiner) {
      const isGigantus = isEnemy && engineRef.current.level === 10;
      drawCombiner(ctx, frame, alpha, isEnemy, isGigantus ? 18 : undefined);
    } else {
      const stats = ROBOT_STATS[unit];
      const color = isEnemy ? '#ff0055' : (stats?.color || '#00f3ff');
      if (isTransformed) drawAltMode(ctx, unit, color, frame, alpha, tier);
      else drawHumanoid(ctx, color, frame, isEnemy, type, alpha, tier);
    }
    ctx.restore();
  };

  const resetLevel = useCallback((fullReset = true) => {
    const e = engineRef.current;
    const stats = ROBOT_STATS[e.unit];
    const baseHP = 100 + (upgrades.robotTier * 50);
    if (fullReset) {
      e.player.maxHealth = baseHP * stats.hpMult;
      e.player.health = e.player.maxHealth;
      e.player.unionTimer = 0;
      e.player.inSpaceship = false;
      setIsSpaceshipMode(false);
      e.player.spaceshipPos = { x: 300, y: 340 };
      setUnionTime(0);
      setMaxHealth(e.player.maxHealth);
      setHealth(e.player.health);
      e.player.pos = { x: 100, y: 300 };
      e.player.vel = { x: 0, y: 0 };
      e.player.invulnerable = 0;
      e.player.isTransformed = false;
      setIsTransformed(false);
      e.bullets = [];
      e.cameraX = 0; e.cameraY = 0; e.zoom = 1.0;
      const enemies: Enemy[] = [];
      const floorY = 398;

      const enemyCount = 5;
      for (let i = 0; i < enemyCount; i++) {
        const isBoss = i === enemyCount - 1;
        if (isBoss) {
          const isLvl20Dragon = e.level === 20;
          const isLvl10Titan = e.level === 10;
          const bossW = isLvl20Dragon ? 300 : (isLvl10Titan ? 640 : 64);
          const bossH = isLvl20Dragon ? 200 : (isLvl10Titan ? 800 : 80);
          const bossHP = isLvl20Dragon ? 50000 : (isLvl10Titan ? 20000 : (500 + (e.level * 100)));

          enemies.push({ 
            id: i, 
            pos: { x: 2000 + i * 800, y: isLvl20Dragon ? 50 : floorY - bossH }, 
            vel: { x: 0, y: 0 }, 
            width: bossW, height: bossH, 
            health: bossHP, maxHealth: bossHP, 
            isDead: false, 
            type: isLvl20Dragon ? 'dragonBoss' : 'combinerBoss', 
            lastShot: 0, hasSplit: false, 
            unit: RobotUnit.OMEGA 
          });
        } else {
          const type = 'heavy';
          enemies.push({ id: i, pos: { x: 800 + i * 800, y: floorY - 72 }, vel: { x: 0, y: 0 }, width: 48, height: 72, health: 100, maxHealth: 100, isDead: false, type: type, lastShot: 0, unit: RobotUnit.SENTINEL });
        }
      }
      e.enemies = enemies;
    }
  }, [upgrades.robotTier]);

  useEffect(() => { resetLevel(true); }, [level, resetLevel]);

  useEffect(() => {
    const e = engineRef.current;
    const handleKeyDown = (ev: KeyboardEvent) => {
      e.keys[ev.code] = true;
      if (ev.code === 'ShiftLeft' || ev.code === 'ShiftRight') {
        e.player.isTransformed = !e.player.isTransformed;
        setIsTransformed(e.player.isTransformed);
      }
      if (ev.code === 'KeyM' && (e.level === 10 || e.level === 20)) {
        const dx = e.player.pos.x - e.player.spaceshipPos.x;
        const dy = e.player.pos.y - e.player.spaceshipPos.y;
        const dist = Math.sqrt(dx*dx + dy*dy);
        if (dist < 100 || e.player.inSpaceship) {
          e.player.inSpaceship = !e.player.inSpaceship;
          setIsSpaceshipMode(e.player.inSpaceship);
          if (e.player.inSpaceship) {
            e.player.maxHealth = 2000;
            e.player.health = 2000;
            setMaxHealth(2000); setHealth(2000);
            soundService.playFly();
          } else {
             const stats = ROBOT_STATS[e.unit];
             const baseHP = 100 + (upgrades.robotTier * 50);
             e.player.maxHealth = baseHP * stats.hpMult;
             e.player.health = Math.min(e.player.health, e.player.maxHealth);
             e.player.spaceshipPos = { ...e.player.pos };
             setMaxHealth(e.player.maxHealth); setHealth(e.player.health);
          }
        }
      }
      if (ev.code === 'KeyC' && e.player.unionTimer <= 0 && !e.player.inSpaceship) {
        e.player.unionTimer = SQUAD_UNION_DURATION;
        e.player.health = 500; e.player.maxHealth = 500;
        setHealth(500); setMaxHealth(500);
        soundService.playFly();
      }
      const trySwitch = (unit: RobotUnit) => {
        if (upgrades.unlockedUnits.includes(unit) && !e.player.inSpaceship) {
          e.unit = unit; setCurrentUnit(unit);
          if (e.player.unionTimer <= 0) {
             const stats = ROBOT_STATS[unit];
             const baseHP = 100 + (upgrades.robotTier * 50);
             e.player.maxHealth = baseHP * stats.hpMult;
             e.player.health = Math.min(e.player.health, e.player.maxHealth);
             setHealth(e.player.health); setMaxHealth(e.player.maxHealth);
          }
        }
      };
      if (ev.code === 'Digit1') trySwitch(RobotUnit.SENTINEL);
      if (ev.code === 'Digit2') trySwitch(RobotUnit.STRIKER);
      if (ev.code === 'Digit3') trySwitch(RobotUnit.FALCON);
      if (ev.code === 'Digit4') trySwitch(RobotUnit.TITAN);
      if (ev.code === 'Digit5') trySwitch(RobotUnit.SPECTER);
    };
    const handleKeyUp = (ev: KeyboardEvent) => { e.keys[ev.code] = false; };
    window.addEventListener('keydown', handleKeyDown); window.addEventListener('keyup', handleKeyUp);
    let animationId: number;
    const loop = () => { if (!e.isPaused) update(); draw(); animationId = requestAnimationFrame(loop); };

    const update = () => {
      const isCombiner = e.player.unionTimer > 0;
      const isShip = e.player.inSpaceship;
      const stats = ROBOT_STATS[e.unit];
      const currentStats = e.player.isTransformed ? stats.alt : stats.robot;
      e.frame++;
      if (isCombiner) {
        e.player.unionTimer--;
        if (e.frame % 10 === 0) setUnionTime(e.player.unionTimer);
      }
      const pw = isShip ? 120 : (isCombiner ? 64 : (e.player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32)));
      const ph = isShip ? 40 : (isCombiner ? 80 : (e.player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48)));
      const moveSpeed = isShip ? 12 : (isCombiner ? 6 : currentStats.speed);
      if (e.keys['ArrowRight'] || e.keys['KeyD']) { e.player.vel.x = moveSpeed; e.player.facing = 1; }
      else if (e.keys['ArrowLeft'] || e.keys['KeyA']) { e.player.vel.x = -moveSpeed; e.player.facing = -1; }
      else e.player.vel.x *= 0.8;
      if (isShip || (e.unit === RobotUnit.FALCON && e.player.isTransformed)) {
        if (e.keys['ArrowUp'] || e.keys['KeyW']) e.player.vel.y = -moveSpeed;
        else if (e.keys['ArrowDown'] || e.keys['KeyS']) e.player.vel.y = moveSpeed;
        else e.player.vel.y *= 0.9;
      } else {
        const jumpPower = isCombiner ? -15 : currentStats.jump;
        if ((e.keys['ArrowUp'] || e.keys['KeyW'] || e.keys['Space']) && e.player.grounded) { e.player.vel.y = jumpPower; e.player.grounded = false; }
        e.player.vel.y += GRAVITY;
      }
      e.player.pos.x += e.player.vel.x; e.player.pos.y += e.player.vel.y;
      const floorY = 398;
      if (!isShip && e.player.pos.y > floorY - ph) { e.player.pos.y = floorY - ph; e.player.vel.y = 0; e.player.grounded = true; }
      if (e.player.pos.x < 0) e.player.pos.x = 0;
      const fr = isShip ? 3 : (isCombiner ? 8 : Math.max(5, currentStats.fireRate - upgrades.weaponTier * 2));
      if (e.keys['Space'] && e.frame - e.player.lastShot > fr) {
        soundService.playShoot();
        const dmg = isShip ? 1200 : (isCombiner ? 500 : 100);
        if (isShip) {
          e.bullets.push({ pos: { x: e.player.pos.x + (e.player.facing === 1 ? pw : -400), y: e.player.pos.y + ph/2 - 4 }, vel: { x: e.player.facing * 35, y: 0 }, width: 400, height: 8, owner: 'player', health: 1, maxHealth: 1, damage: dmg, color: '#00f3ff' });
        } else if (isCombiner) {
          e.bullets.push({ pos: { x: e.player.pos.x + (e.player.facing === 1 ? pw : 0), y: e.player.pos.y + ph/2 - 10 }, vel: { x: e.player.facing * 20, y: 0 }, width: 32, height: 20, owner: 'player', health: 1, maxHealth: 1, damage: dmg, color: '#fff' });
        } else {
          e.bullets.push({ pos: { x: e.player.pos.x + (e.player.facing === 1 ? pw : 0), y: e.player.pos.y + ph/2 }, vel: { x: e.player.facing * 15, y: 0 }, width: 12, height: 4, owner: 'player', health: 1, maxHealth: 1, damage: dmg, color: stats.color });
        }
        e.player.lastShot = e.frame;
      }
      for (let i = e.bullets.length - 1; i >= 0; i--) {
        const b = e.bullets[i]; b.pos.x += b.vel.x; b.pos.y += b.vel.y;
        if (b.owner === 'enemy' && !e.player.invulnerable) {
          if (b.pos.x < e.player.pos.x + pw && b.pos.x + b.width > e.player.pos.x && b.pos.y < e.player.pos.y + ph && b.pos.y + b.height > e.player.pos.y) {
            e.player.health = Math.max(0, e.player.health - 20); e.player.invulnerable = 40;
            setHealth(e.player.health); e.bullets.splice(i, 1); soundService.playLose(); continue;
          }
        }
        if (Math.abs(b.pos.x - e.player.pos.x) > 3000) e.bullets.splice(i, 1);
      }
      let allDead = true;
      const newEnemies: Enemy[] = [];
      e.enemies.forEach(en => {
        if (en.isDead) return;
        allDead = false;

        // Split logic: Spawn robots directly on the ground
        if (en.type === 'combinerBoss' && !en.hasSplit && en.health < en.maxHealth * 0.2) {
          en.isDead = true; en.hasSplit = true; soundService.playFly();
          const scoutHeight = 36;
          for (let s = 0; s < 6; s++) {
            newEnemies.push({ 
              id: Date.now() + s, 
              pos: { 
                x: en.pos.x + (Math.random() * en.width), 
                y: floorY - scoutHeight
              }, 
              vel: { x: (Math.random() - 0.5) * 6, y: 0 },
              width: 24, 
              height: scoutHeight, 
              health: 150, 
              maxHealth: 150, 
              isDead: false, 
              type: 'scout', 
              lastShot: e.frame, 
              unit: RobotUnit.STRIKER 
            });
          }
          return;
        }

        // Dragon specific movement
        if (en.type === 'dragonBoss') {
            en.pos.y = 100 + Math.sin(e.frame * 0.05) * 100;
            en.pos.x += Math.sin(e.frame * 0.02) * 2;
        }

        const dir = Math.sign(e.player.pos.x - en.pos.x);
        const speed = en.type === 'scout' ? 2.5 : (en.type === 'dragonBoss' ? 0.8 : (en.type === 'combinerBoss' ? 0.3 : 0.6));
        en.pos.x += dir * speed;

        const shootFreq = en.type === 'dragonBoss' ? 30 : (en.type === 'combinerBoss' ? 45 : (en.type === 'scout' ? 90 : 120));
        if (Math.abs(en.pos.x - e.player.pos.x) < 1500 && e.frame - en.lastShot > shootFreq) {
          if (en.type === 'dragonBoss') {
              // Dragon shoots 3 fireballs
              for(let j=-1; j<=1; j++) {
                e.bullets.push({ pos: {x: en.pos.x + en.width/2, y: en.pos.y + en.height/2}, vel: {x: dir * 10, y: j * 2}, width: 20, height: 20, owner: 'enemy', health: 1, maxHealth: 1, damage: 30, color: '#ff5500' });
              }
          } else {
            const bW = en.type === 'combinerBoss' ? 24 : 10;
            const bH = en.type === 'combinerBoss' ? 10 : 4;
            e.bullets.push({ pos: {x: en.pos.x + (dir > 0 ? en.width : 0), y: en.pos.y + en.height / 2}, vel: {x: dir * 8, y: 0}, width: bW, height: bH, owner: 'enemy', health: 1, maxHealth: 1, damage: 20, color: '#f00' });
          }
          en.lastShot = e.frame;
        }
        e.bullets.forEach((b, bIdx) => {
          if (b.owner === 'player' && !en.isDead && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) {
            en.health -= (b.damage || 100); if (en.health <= 0) en.isDead = true;
            e.bullets.splice(bIdx, 1);
          }
        });
      });
      if (newEnemies.length > 0) e.enemies.push(...newEnemies);
      if (e.player.health <= 0) onDie();
      if (allDead && newEnemies.length === 0) onWin();
      if (e.player.invulnerable > 0) e.player.invulnerable--;

      const isLvlBoss = e.level === 10 || e.level === 20;
      const targetZoom = isLvlBoss ? (e.level === 20 ? 0.4 : 0.45) : 1.0;
      e.zoom += (targetZoom - e.zoom) * 0.05;
      const visibleWidth = CANVAS_WIDTH / e.zoom;
      e.cameraX = e.player.pos.x - visibleWidth * 0.3;
      const targetCameraY = isLvlBoss ? (398 - (CANVAS_HEIGHT / e.zoom) + 120) : 0;
      e.cameraY += (targetCameraY - e.cameraY) * 0.05;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      ctx.save(); ctx.scale(e.zoom, e.zoom); ctx.translate(-e.cameraX, -e.cameraY);
      const visibleWidth = CANVAS_WIDTH / e.zoom; const visibleHeight = CANVAS_HEIGHT / e.zoom;
      ctx.fillStyle = '#050510'; ctx.fillRect(e.cameraX, e.cameraY, visibleWidth, visibleHeight);
      ctx.fillStyle = '#111'; ctx.fillRect(e.cameraX - 1000, 398, visibleWidth + 2000, 1000); ctx.strokeStyle = '#222';
      const startX = Math.floor(e.cameraX / 40) * 40;
      for(let i = startX - 40; i < e.cameraX + visibleWidth + 40; i += 40) ctx.strokeRect(i, 398, 40, 52);
      if ((e.level === 10 || e.level === 20) && !e.player.inSpaceship) {
        ctx.save(); ctx.translate(e.player.spaceshipPos.x + 60, e.player.spaceshipPos.y + 20); drawSpaceship(ctx, e.frame, 0.8); ctx.restore();
        ctx.fillStyle = '#fff'; ctx.font = '10px Orbitron'; ctx.fillText("[M] ENTER SHIP", e.player.spaceshipPos.x + 10, e.player.spaceshipPos.y - 20);
      }
      e.enemies.forEach(en => { if(!en.isDead) drawUnit(ctx, en.pos.x, en.pos.y, en.width, en.height, en.unit || RobotUnit.SENTINEL, Math.sign(e.player.pos.x - en.pos.x), e.frame, true, false, en.isTransformed, en.type, 1, 0, en.type === 'combinerBoss'); });
      if (e.player.inSpaceship) {
        ctx.save(); ctx.translate(e.player.pos.x + 60, e.player.pos.y + 20); if (e.player.facing === -1) ctx.scale(-1, 1);
        drawSpaceship(ctx, e.frame, 1); ctx.restore();
      } else {
        const isCombiner = e.player.unionTimer > 0;
        const pw = isCombiner ? 64 : (e.player.isTransformed ? 48 : (e.unit === RobotUnit.TITAN ? 64 : 32));
        const ph = isCombiner ? 80 : (e.player.isTransformed ? 32 : (e.unit === RobotUnit.TITAN ? 80 : 48));
        drawUnit(ctx, e.player.pos.x, e.player.pos.y, pw, ph, e.unit, e.player.facing, e.frame, false, e.player.invulnerable > 0, e.player.isTransformed, 'bot', 1, upgrades.robotTier, isCombiner);
      }
      e.bullets.forEach(b => { 
        ctx.fillStyle = b.color || '#00f3ff'; if (b.width > 20) { ctx.shadowBlur = 10; ctx.shadowColor = b.color || '#fff'; } 
        ctx.fillRect(b.pos.x, b.pos.y, b.width, b.height); ctx.shadowBlur = 0; 
      });
      ctx.restore();
    };
    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [onWin, onDie, upgrades.unlockedUnits, upgrades.weaponTier, upgrades.robotTier]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden font-orbitron">
      <div className="absolute top-4 left-4 z-10 space-y-4 pointer-events-none w-[400px]">
        <div className="bg-black/80 border border-cyan-500/50 p-3 rounded backdrop-blur-md shadow-lg">
          <div className="text-[10px] text-cyan-400 font-bold uppercase mb-1 flex justify-between">
            <span>{isSpaceshipMode ? 'INTERCEPTOR SHIP' : (unionTime > 0 ? 'SQUAD COMBINER' : `${ROBOT_STATS[currentUnit].name} CHASSIS`)}</span>
            <span>{Math.round(health)}/{Math.round(maxHealth)}</span>
          </div>
          <div className="w-48 h-2.5 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
            <div className="h-full shadow-[0_0_15px_#00f3ff] transition-all duration-300" style={{ width: `${(health / maxHealth) * 100}%`, backgroundColor: health < maxHealth * 0.3 ? '#ef4444' : (unionTime > 0 || isSpaceshipMode ? '#fff' : '#00f3ff') }} />
          </div>
          {unionTime > 0 && (
            <div className="mt-2">
              <div className="text-[8px] text-yellow-400 font-bold uppercase mb-0.5">COMBINER INTEGRITY</div>
              <div className="w-full h-1 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
                <div className="h-full bg-yellow-500 shadow-[0_0_10px_#fbbf24] transition-all duration-100" style={{ width: `${(unionTime / SQUAD_UNION_DURATION) * 100}%` }} />
              </div>
            </div>
          )}
        </div>
      </div>
      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full aspect-video shadow-2xl rounded-lg border-2 border-cyan-900/50" />
      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 pointer-events-none text-white/30 text-[8px] font-mono tracking-widest uppercase flex gap-6">
        <span>WASD: Move</span><span>Space: Fire</span><span>Shift: Transform</span><span>1-5: Squad</span><span>C: Combine</span>{(level === 10 || level === 20) && <span>M: Ship</span>}
      </div>
      {(unionTime > SQUAD_UNION_DURATION - 60 || (isSpaceshipMode && engineRef.current.frame % 60 < 30)) && (
        <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
          <div className="text-6xl font-black italic text-white tracking-tighter shadow-2xl animate-pulse uppercase">{isSpaceshipMode ? 'Heavy Laser Online' : 'Squad Combination Engaged'}</div>
        </div>
      )}
      {(level === 10 || level === 20) && (
        <div className="absolute top-20 right-4 p-4 border border-red-500 bg-red-950/20 text-red-500 text-xs animate-pulse uppercase tracking-widest">
           Warning: {level === 20 ? 'Cyber Dragon' : 'Gigantus Titan'} Detected
        </div>
      )}
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
