const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [currentUnit, setCurrentUnit] = useState<RobotUnit>(upgrades.squad[0] || RobotUnit.SENTINEL);
  const [isTransformed, setIsTransformed] = useState(false);
  const [health, setHealth] = useState(100);
  const [maxHealth, setMaxHealth] = useState(100);
  const [unionTime, setUnionTime] = useState(0);
  const [isSpaceshipMode, setIsSpaceshipMode] = useState(false);
  const [isSquadMode, setIsSquadMode] = useState(false);

  const engineRef = useRef({
    players: [] as PlayerEntity[],
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    cameraY: 0,
    zoom: 1.0,
    isPaused: isPaused,
    currentUnit: upgrades.squad[0] || RobotUnit.SENTINEL,
    level: level,
    isSquadMode: false,
    unionTimer: 0,
    inSpaceship: false,
    spaceshipPos: { x: 300, y: 340 },
  });

  useEffect(() => { engineRef.current.isPaused = isPaused; }, [isPaused]);
  useEffect(() => { engineRef.current.level = level; }, [level]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4, border = true) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff66');
    grad.addColorStop(1, '#000000aa');
    ctx.fillStyle = grad;
    ctx.fill();
    if (border) {
      ctx.strokeStyle = 'rgba(0,0,0,0.6)';
      ctx.lineWidth = 1;
      ctx.stroke();
    }
  };

  const drawHelicopter = (ctx: CanvasRenderingContext2D, frame: number, alpha: number) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(1.2, 1.2);
    const bodyColor = '#1e293b';
    const highlightColor = '#ff0055';
    drawMechanicalPart(ctx, -30, -10, 60, 25, bodyColor, 10);
    drawMechanicalPart(ctx, -15, -20, 30, 15, '#334155', 8);
    drawMechanicalPart(ctx, -60, -5, 40, 10, bodyColor, 4);
    drawMechanicalPart(ctx, -65, -15, 10, 20, highlightColor, 2);
    const rotorAngle = frame * 0.8;
    ctx.save();
    ctx.translate(0, -22);
    ctx.rotate(rotorAngle);
    ctx.fillStyle = '#666';
    ctx.fillRect(-50, -2, 100, 4);
    ctx.fillRect(-2, -50, 4, 100);
    ctx.restore();
    ctx.fillStyle = '#111';
    ctx.fillRect(15, 5, 20, 6);
    ctx.restore();
  };

  const drawDragon = (ctx: CanvasRenderingContext2D, frame: number, alpha: number) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(2.5, 2.5);
    const bodyColor = '#1e293b';
    const highlightColor = '#ff0055';
    const time = frame * 0.1;
    const wingFlap = Math.sin(time * 0.5) * 35;
    ctx.fillStyle = highlightColor;
    ctx.beginPath();
    ctx.moveTo(0, -10); ctx.lineTo(-90, -40 + wingFlap); ctx.lineTo(-20, 10); ctx.fill();
    ctx.beginPath();
    ctx.moveTo(0, -10); ctx.lineTo(90, -40 + wingFlap); ctx.lineTo(20, 10); ctx.fill();
    for (let i = 0; i < 10; i++) {
        const segX = Math.sin(time * 0.7 + i * 0.6) * (15 + i * 3);
        const segY = 15 + i * 18;
        drawMechanicalPart(ctx, -12 + segX, segY, 24, 18, bodyColor, 4);
        ctx.fillStyle = highlightColor;
        ctx.fillRect(-2 + segX, segY + 6, 4, 4);
    }
    drawMechanicalPart(ctx, -20, -15, 40, 50, bodyColor, 15);
    const headSwing = Math.sin(time * 0.8) * 15;
    ctx.save();
    ctx.translate(headSwing, -40);
    drawMechanicalPart(ctx, -12, -15, 24, 30, bodyColor, 6);
    drawMechanicalPart(ctx, -15, -35, 30, 25, bodyColor, 10);
    ctx.fillStyle = '#ff0000';
    ctx.shadowBlur = 15; ctx.shadowColor = '#ff0000';
    ctx.beginPath(); ctx.arc(-7, -25, 4, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(7, -25, 4, 0, Math.PI * 2); ctx.fill();
    if (frame % 40 < 15) {
        ctx.fillStyle = '#ff9900';
        ctx.beginPath(); ctx.arc(0, -15, 10 + Math.sin(frame) * 5, 0, Math.PI * 2); ctx.fill();
    }
    ctx.restore();
    ctx.restore();
  };

  const drawSpaceship = (ctx: CanvasRenderingContext2D, frame: number, alpha: number) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(1.5, 1.2);
    drawMechanicalPart(ctx, -40, -15, 80, 30, '#1e293b', 15);
    drawMechanicalPart(ctx, -30, -25, 60, 20, '#334155', 10);
    ctx.fillStyle = '#00f3ff'; ctx.beginPath(); ctx.ellipse(0, -15, 20, 10, 0, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#1e293b';
    ctx.beginPath(); ctx.moveTo(-20, 0); ctx.lineTo(-60, 20); ctx.lineTo(-20, 15); ctx.fill();
    ctx.beginPath(); ctx.moveTo(20, 0); ctx.lineTo(60, 20); ctx.lineTo(20, 15); ctx.fill();
    const fireSize = 10 + Math.sin(frame * 0.5) * 5;
    ctx.fillStyle = '#fbbf24';
    ctx.beginPath(); ctx.arc(-35, 10, fireSize, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(35, 10, fireSize, 0, Math.PI * 2); ctx.fill();
    drawMechanicalPart(ctx, -45, -5, 15, 5, '#475569', 2);
    drawMechanicalPart(ctx, 30, -5, 15, 5, '#475569', 2);
    ctx.restore();
  };

  const drawCombiner = (ctx: CanvasRenderingContext2D, frame: number, alpha: number, isEnemy = false, scaleOverride?: number) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    const scale = scaleOverride || 1.8;
    ctx.scale(scale, scale);
    ctx.shadowBlur = isEnemy ? 25 : 15;
    ctx.shadowColor = isEnemy ? '#ff0055' : '#fff';
    const primaryColor = isEnemy ? '#ff0055' : '#00f3ff';
    const secondaryColor = isEnemy ? '#440022' : '#ef4444';
    drawMechanicalPart(ctx, -15, -20, 30, 35, primaryColor, 6);
    drawMechanicalPart(ctx, -10, -15, 20, 20, secondaryColor, 4);
    ctx.fillStyle = isEnemy ? '#ff0000' : '#fff';
    ctx.beginPath(); ctx.arc(0, -5, 6 + Math.sin(frame * 0.2) * 2, 0, Math.PI * 2); ctx.fill();
    drawMechanicalPart(ctx, -8, -38, 16, 16, '#111', 8);
    ctx.fillStyle = '#fff'; ctx.fillRect(-5, -30, 10, 2);
    ctx.fillStyle = isEnemy ? '#ff5555' : '#22d3ee';
    ctx.beginPath(); ctx.moveTo(-15, -15); ctx.lineTo(-45, -40); ctx.lineTo(-15, 5); ctx.fill();
    ctx.beginPath(); ctx.moveTo(15, -15); ctx.lineTo(45, -40); ctx.lineTo(15, 5); ctx.fill();
    drawMechanicalPart(ctx, -22, -25, 12, 12, '#fbbf24', 2);
    drawMechanicalPart(ctx, 10, -25, 12, 12, '#fbbf24', 2);
    const legSwing = Math.sin(frame * 0.15) * 5;
    drawMechanicalPart(ctx, -12, 15, 12, 22 + legSwing, '#333', 4);
    drawMechanicalPart(ctx, 0, 15, 12, 22 - legSwing, '#333', 4);
    ctx.restore();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, type = 'bot', alpha = 1, tier = 0) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8;
    const armSwing = Math.cos(time) * 10;
    let scale = 1;
    if (type === 'scout') scale = 0.8;
    if (type === 'heavy' || type === 'titan') scale = 1.4;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(scale, scale);
    drawMechanicalPart(ctx, -12, -18, 24, 28, color, 4);
    if (!isEnemy && tier > 0) {
      drawMechanicalPart(ctx, -18, -22, 12, 10, '#333', 2);
      drawMechanicalPart(ctx, 6, -22, 12, 10, '#333', 2);
      ctx.fillStyle = '#fff'; ctx.shadowBlur = 10; ctx.shadowColor = color; ctx.beginPath(); ctx.arc(0, -6, 4, 0, Math.PI * 2); ctx.fill(); ctx.shadowBlur = 0;
    }
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? '#ff0000' : '#00f3ff'; ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);
    ctx.restore();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, color: string, frame: number, alpha = 1, tier = 0) => {
    ctx.save(); ctx.globalAlpha = alpha;
    switch(unit) {
      case RobotUnit.SENTINEL:
        drawMechanicalPart(ctx, -28, -10, 56, 20, color, 8);
        drawMechanicalPart(ctx, -18, -22, 36, 14, '#111', 4);
        ctx.fillStyle = frame % 10 < 5 ? '#ff0000' : '#0000ff'; ctx.fillRect(-6, -24, 12, 4);
        ctx.fillStyle = '#111'; ctx.beginPath(); ctx.arc(-18, 12, 8, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.arc(18, 12, 8, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = '#ffffaa'; ctx.fillRect(20, -4, 8, 6);
        if (tier > 0) { ctx.fillStyle = '#fff'; ctx.fillRect(-20, -6, 40, 4); }
        break;
      case RobotUnit.TITAN:
        drawMechanicalPart(ctx, -35, -8, 70, 24, color, 4);
        drawMechanicalPart(ctx, -18, -26, 36, 18, '#222', 4);
        drawMechanicalPart(ctx, 12, -22, 30, 8, '#444', 1);
        ctx.fillStyle = '#111'; ctx.fillRect(-33, 10, 66, 8);
        break;
      case RobotUnit.FALCON:
        drawMechanicalPart(ctx, -24, -8, 48, 16, color, 12);
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.moveTo(-10, -5); ctx.lineTo(-40, -20); ctx.lineTo(-10, 10); ctx.fill();
        ctx.fillStyle = '#ffaa00'; ctx.fillRect(-35, -5, 10, 6);
        break;
      default:
        drawMechanicalPart(ctx, -25, -12, 50, 24, color, 6);
        drawMechanicalPart(ctx, -10, -22, 20, 10, '#333', 2);
        break;
    }
    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy = false, isInvuln = false, isTransformed = false, type = 'bot', alpha = 1, tier = 0, isCombiner = false) => {
    if (isInvuln && frame % 4 < 2) return;
    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    if (facing === -1) ctx.scale(-1, 1);
    if (type === 'dragonBoss') {
        drawDragon(ctx, frame, alpha);
    } else if (type === 'helicopter') {
        drawHelicopter(ctx, frame, alpha);
    } else if (isCombiner) {
      const isGigantus = isEnemy && (engineRef.current.level === 10 || engineRef.current.level === 20);
      drawCombiner(ctx, frame, alpha, isEnemy, isGigantus ? 18 : undefined);
    } else {
      const stats = ROBOT_STATS[unit];
      const color = isEnemy ? '#ff0055' : (stats?.color || '#00f3ff');
      if (isTransformed) drawAltMode(ctx, unit, color, frame, alpha, tier);
      else drawHumanoid(ctx, color, frame, isEnemy, type, alpha, tier);
    }
    ctx.restore();
  };

  const createPlayer = (unit: RobotUnit, x: number, y: number): PlayerEntity => {
    const stats = ROBOT_STATS[unit];
    const baseHP = 100 + (upgrades.robotTier * 50);
    return {
      id: Math.random().toString(36).substr(2, 9),
      unit,
      pos: { x, y },
      vel: { x: 0, y: 0 },
      width: unit === RobotUnit.TITAN ? 64 : 32,
      height: unit === RobotUnit.TITAN ? 80 : 48,
      facing: 1,
      grounded: false,
      lastShot: 0,
      invulnerable: 0,
      health: baseHP * stats.hpMult,
      maxHealth: baseHP * stats.hpMult,
      isTransformed: false
    };
  };

  const resetLevel = useCallback((fullReset = true) => {
    const e = engineRef.current;
    if (fullReset) {
      e.isSquadMode = false;
      setIsSquadMode(false);
      e.unionTimer = 0;
      e.inSpaceship = false;
      setIsSpaceshipMode(false);
      e.spaceshipPos = { x: 300, y: 340 };
      setUnionTime(0);

      const leader = createPlayer(e.currentUnit, 100, 300);
      e.players = [leader];
      setHealth(leader.health);
      setMaxHealth(leader.maxHealth);

      e.bullets = [];
      e.cameraX = 0; e.cameraY = 0; e.zoom = 1.0;
      const enemies: Enemy[] = [];
      const floorY = 398;

      if (e.level === 20) {
          enemies.push({ id: 999, pos: { x: 4000, y: 50 }, vel: { x: 0, y: 0 }, width: 300, height: 200, health: 120000, maxHealth: 120000, isDead: false, type: 'dragonBoss', lastShot: 0, unit: RobotUnit.OMEGA });
          enemies.push({ id: 998, pos: { x: 2500, y: floorY - 800 }, vel: { x: 0, y: 0 }, width: 640, height: 800, health: 80000, maxHealth: 80000, isDead: false, type: 'combinerBoss', lastShot: 0, unit: RobotUnit.OMEGA });
          for(let i=0; i<5; i++) {
              enemies.push({ id: 800+i, pos: { x: 1200 + i*600, y: 80 + (i%2)*60 }, vel: { x: 0, y: 0 }, width: 80, height: 40, health: 800, maxHealth: 800, isDead: false, type: 'helicopter', lastShot: 0, unit: RobotUnit.FALCON });
          }
          for(let i=0; i<10; i++) {
              enemies.push({ id: 700+i, pos: { x: 800 + i*400, y: floorY - 32 }, vel: { x: 0, y: 0 }, width: 70, height: 32, health: 1500, maxHealth: 1500, isDead: false, type: 'heavy', lastShot: 0, unit: RobotUnit.TITAN, isTransformed: true });
          }
      } else if (e.level === 5) {
          for (let i = 0; i < 5; i++) {
            enemies.push({ id: 500 + i, pos: { x: 800 + i * 600, y: floorY - 32 }, vel: { x: 0, y: 0 }, width: 70, height: 32, health: 800, maxHealth: 800, isDead: false, type: 'heavy', lastShot: 0, unit: RobotUnit.TITAN, isTransformed: true });
          }
      } else {
          const enemyCount = 5;
          for (let i = 0; i < enemyCount; i++) {
            const isBoss = i === enemyCount - 1;
            if (isBoss) {
              const isLvl10Titan = e.level === 10;
              const bossW = isLvl10Titan ? 640 : 64;
              const bossH = isLvl10Titan ? 800 : 80;
              const bossHP = isLvl10Titan ? 40000 : (500 + (e.level * 100));
              enemies.push({ id: i, pos: { x: 2000 + i * 800, y: floorY - bossH }, vel: { x: 0, y: 0 }, width: bossW, height: bossH, health: bossHP, maxHealth: bossHP, isDead: false, type: 'combinerBoss', lastShot: 0, hasSplit: false, unit: RobotUnit.OMEGA });
            } else {
              enemies.push({ id: i, pos: { x: 800 + i * 800, y: floorY - 72 }, vel: { x: 0, y: 0 }, width: 48, height: 72, health: 100, maxHealth: 100, isDead: false, type: 'heavy', lastShot: 0, unit: RobotUnit.SENTINEL });
            }
          }
      }
      e.enemies = enemies;
    }
  }, [upgrades.robotTier]);

  useEffect(() => { resetLevel(true); }, [level, resetLevel]);

  useEffect(() => {
    const e = engineRef.current;
    const handleKeyDown = (ev: KeyboardEvent) => {
      e.keys[ev.code] = true;
      if (ev.code === 'ShiftLeft' || ev.code === 'ShiftRight') {
        e.players.forEach(p => p.isTransformed = !p.isTransformed);
        setIsTransformed(e.players[0]?.isTransformed || false);
      }
      if (ev.code === 'KeyB') {
        e.isSquadMode = !e.isSquadMode;
        setIsSquadMode(e.isSquadMode);
        if (e.isSquadMode) {
          const leader = e.players[0];
          const newSquad = upgrades.squad.map((unit, idx) => {
            const member = createPlayer(unit, leader.pos.x + (idx * 40) - (upgrades.squad.length * 20), leader.pos.y);
            return member;
          });
          e.players = newSquad;
        } else {
          e.players = [e.players[0]]; // Retain only the first unit when toggling off
        }
      }
      if (ev.code === 'KeyM' && (e.level === 10 || e.level === 20)) {
        const leader = e.players[0];
        const dx = leader.pos.x - e.spaceshipPos.x;
        const dy = leader.pos.y - e.spaceshipPos.y;
        const dist = Math.sqrt(dx*dx + dy*dy);
        if (dist < 100 || e.inSpaceship) {
          e.inSpaceship = !e.inSpaceship;
          setIsSpaceshipMode(e.inSpaceship);
          if (e.inSpaceship) {
            leader.maxHealth = 2000;
            leader.health = 2000;
            setMaxHealth(2000); setHealth(2000);
            soundService.playFly();
          } else {
             const stats = ROBOT_STATS[e.currentUnit];
             const baseHP = 100 + (upgrades.robotTier * 50);
             leader.maxHealth = baseHP * stats.hpMult;
             leader.health = Math.min(leader.health, leader.maxHealth);
             e.spaceshipPos = { ...leader.pos };
             setMaxHealth(leader.maxHealth); setHealth(leader.health);
          }
        }
      }
      if (ev.code === 'KeyC' && e.unionTimer <= 0 && !e.inSpaceship) {
        e.unionTimer = SQUAD_UNION_DURATION;
        e.players[0].health = 500; e.players[0].maxHealth = 500;
        setHealth(500); setMaxHealth(500);
        soundService.playFly();
      }
      const trySwitch = (unit: RobotUnit) => {
        if (!e.inSpaceship && !e.isSquadMode) {
          e.currentUnit = unit; setCurrentUnit(unit);
          if (e.unionTimer <= 0) {
             const leader = e.players[0];
             const stats = ROBOT_STATS[unit];
             const baseHP = 100 + (upgrades.robotTier * 50);
             leader.unit = unit;
             leader.maxHealth = baseHP * stats.hpMult;
             leader.health = Math.min(leader.health, leader.maxHealth);
             leader.width = unit === RobotUnit.TITAN ? 64 : 32;
             leader.height = unit === RobotUnit.TITAN ? 80 : 48;
             setHealth(leader.health); setMaxHealth(leader.maxHealth);
          }
        }
      };
      const squad = upgrades.squad;
      if (ev.code === 'Digit1' && squad[0]) trySwitch(squad[0]);
      if (ev.code === 'Digit2' && squad[1]) trySwitch(squad[1]);
      if (ev.code === 'Digit3' && squad[2]) trySwitch(squad[2]);
      if (ev.code === 'Digit4' && squad[3]) trySwitch(squad[3]);
      if (ev.code === 'Digit5' && squad[4]) trySwitch(squad[4]);
    };
    const handleKeyUp = (ev: KeyboardEvent) => { e.keys[ev.code] = false; };
    window.addEventListener('keydown', handleKeyDown); window.addEventListener('keyup', handleKeyUp);
    let animationId: number;
    const loop = () => { if (!e.isPaused) update(); draw(); animationId = requestAnimationFrame(loop); };

    const update = () => {
      const isCombiner = e.unionTimer > 0;
      const isShip = e.inSpaceship;
      // Fixed: Defined floorY at the top level of update function to be accessible by all loops.
      const floorY = 398;
      e.frame++;

      if (isCombiner) {
        e.unionTimer--;
        if (e.frame % 10 === 0) setUnionTime(e.unionTimer);
      }

      // Input Signals
      const moveRight = e.keys['ArrowRight'] || e.keys['KeyD'];
      const moveLeft = e.keys['ArrowLeft'] || e.keys['KeyA'];
      const moveUp = e.keys['ArrowUp'] || e.keys['KeyW'];
      const moveDown = e.keys['ArrowDown'] || e.keys['KeyS'];
      const firing = e.keys['Space'];

      e.players.forEach((player) => {
        const stats = ROBOT_STATS[player.unit];
        const currentStats = player.isTransformed ? stats.alt : stats.robot;
        const pw = isShip ? 120 : (isCombiner ? 64 : (player.isTransformed ? 48 : player.width));
        const ph = isShip ? 40 : (isCombiner ? 80 : (player.isTransformed ? 32 : player.height));
        const moveSpeed = isShip ? 12 : (isCombiner ? 6 : currentStats.speed);

        if (moveRight) { player.vel.x = moveSpeed; player.facing = 1; }
        else if (moveLeft) { player.vel.x = -moveSpeed; player.facing = -1; }
        else player.vel.x *= 0.8;

        if (isShip || (player.unit === RobotUnit.FALCON && player.isTransformed)) {
          if (moveUp) player.vel.y = -moveSpeed;
          else if (moveDown) player.vel.y = moveSpeed;
          else player.vel.y *= 0.9;
        } else {
          const jumpPower = isCombiner ? -15 : currentStats.jump;
          if (moveUp && player.grounded) { player.vel.y = jumpPower; player.grounded = false; }
          player.vel.y += GRAVITY;
        }

        player.pos.x += player.vel.x; player.pos.y += player.vel.y;

        if (!isShip && player.pos.y > floorY - ph) { player.pos.y = floorY - ph; player.vel.y = 0; player.grounded = true; }
        if (player.pos.x < 0) player.pos.x = 0;

        const fr = isShip ? 3 : (isCombiner ? 8 : Math.max(5, currentStats.fireRate - upgrades.weaponTier * 2));
        if (firing && e.frame - player.lastShot > fr) {
          soundService.playShoot();
          const dmg = isShip ? 1200 : (isCombiner ? 500 : 100);
          const bSpeed = isShip ? 35 : (isCombiner ? 20 : 15);
          let bVelX = 0, bVelY = 0;
          if (moveUp) bVelY = -bSpeed;
          else if (moveDown) bVelY = bSpeed;
          if (moveLeft) bVelX = -bSpeed;
          else if (moveRight) bVelX = bSpeed;
          else if (!moveUp && !moveDown) bVelX = player.facing * bSpeed;
          if (bVelX !== 0 && bVelY !== 0) {
            const mag = Math.sqrt(bVelX * bVelX + bVelY * bVelY);
            bVelX = (bVelX / mag) * bSpeed;
            bVelY = (bVelY / mag) * bSpeed;
          }
          e.bullets.push({ 
            pos: { x: player.pos.x + pw/2 - 6, y: player.pos.y + ph/2 - 2 }, 
            vel: { x: bVelX, y: bVelY }, 
            width: isShip ? 400 : (isCombiner ? 24 : 12), 
            height: isShip ? 8 : (isCombiner ? 12 : 4), 
            owner: 'player', health: 1, maxHealth: 1, damage: dmg, color: isShip ? '#00f3ff' : stats.color 
          });
          player.lastShot = e.frame;
        }

        if (player === e.players[0]) {
           setHealth(player.health);
           setMaxHealth(player.maxHealth);
        }
      });

      // Camera follows the first player (Leader)
      const leader = e.players[0];
      if (!leader) return;

      for (let i = e.bullets.length - 1; i >= 0; i--) {
        const b = e.bullets[i]; b.pos.x += b.vel.x; b.pos.y += b.vel.y;
        if (b.owner === 'enemy') {
          e.players.forEach(player => {
             const pw = isShip ? 120 : (isCombiner ? 64 : (player.isTransformed ? 48 : player.width));
             const ph = isShip ? 40 : (isCombiner ? 80 : (player.isTransformed ? 32 : player.height));
             if (!player.invulnerable && b.pos.x < player.pos.x + pw && b.pos.x + b.width > player.pos.x && b.pos.y < player.pos.y + ph && b.pos.y + b.height > player.pos.y) {
               player.health = Math.max(0, player.health - (b.damage || 20)); player.invulnerable = 40;
               e.bullets.splice(i, 1); soundService.playLose();
             }
          });
        }
        if (Math.abs(b.pos.x - leader.pos.x) > 3000 || Math.abs(b.pos.y - leader.pos.y) > 3000) e.bullets.splice(i, 1);
      }

      let allDead = true;
      const newEnemies: Enemy[] = [];
      e.enemies.forEach(en => {
        if (en.isDead) return;
        allDead = false;
        if (en.type === 'combinerBoss' && !en.hasSplit && en.health < en.maxHealth * 0.2 && e.level !== 20) {
          en.isDead = true; en.hasSplit = true; soundService.playFly();
          const scoutHeight = 36;
          for (let s = 0; s < 6; s++) {
            // Fixed: Now floorY is accessible here.
            newEnemies.push({ id: Date.now() + s, pos: { x: en.pos.x + (Math.random() * en.width), y: floorY - scoutHeight }, vel: { x: (Math.random() - 0.5) * 6, y: 0 }, width: 24, height: scoutHeight, health: 150, maxHealth: 150, isDead: false, type: 'scout', lastShot: e.frame, unit: RobotUnit.STRIKER });
          }
          return;
        }
        if (en.type === 'dragonBoss' || en.type === 'helicopter') {
            const hoverY = en.type === 'dragonBoss' ? 100 : (80 + Math.sin(en.id + e.frame * 0.03) * 40);
            en.pos.y += (hoverY - en.pos.y) * 0.02;
            en.pos.x += Math.sin(e.frame * 0.02 + en.id) * 2;
        }
        const dirX = Math.sign(leader.pos.x - en.pos.x);
        const speed = en.type === 'scout' ? 2.5 : (en.type === 'dragonBoss' ? 0.8 : (en.type === 'helicopter' ? 1.5 : (en.type === 'combinerBoss' ? 0.3 : 0.6)));
        en.pos.x += dirX * speed;
        const shootFreq = en.type === 'dragonBoss' ? 20 : (en.type === 'combinerBoss' ? 35 : (en.type === 'scout' || en.type === 'helicopter' ? 70 : 120));
        if (Math.abs(en.pos.x - leader.pos.x) < 1500 && e.frame - en.lastShot > shootFreq) {
          const ebSpeed = (en.type === 'dragonBoss' || en.type === 'combinerBoss') ? 12 : 8;
          const targetPlayer = e.players[Math.floor(Math.random() * e.players.length)];
          const diffX = (targetPlayer.pos.x + targetPlayer.width/2) - (en.pos.x + en.width/2);
          const diffY = (targetPlayer.pos.y + targetPlayer.height/2) - (en.pos.y + en.height/2);
          const mag = Math.sqrt(diffX * diffX + diffY * diffY);
          const ebVelX = (diffX / mag) * ebSpeed;
          const ebVelY = (diffY / mag) * ebSpeed;
          if (en.type === 'dragonBoss') {
              for(let j=-2; j<=2; j++) {
                e.bullets.push({ pos: {x: en.pos.x + en.width/2, y: en.pos.y + en.height/2}, vel: {x: ebVelX, y: ebVelY + j * 3}, width: 20, height: 20, owner: 'enemy', health: 1, maxHealth: 1, damage: 40, color: '#ff5500' });
              }
          } else {
            const bW = (en.type === 'combinerBoss' || en.type === 'helicopter') ? 24 : 10;
            const bH = (en.type === 'combinerBoss' || en.type === 'helicopter') ? 10 : 4;
            e.bullets.push({ pos: {x: en.pos.x + en.width/2, y: en.pos.y + en.height / 2}, vel: {x: ebVelX, y: ebVelY}, width: bW, height: bH, owner: 'enemy', health: 1, maxHealth: 1, damage: 30, color: '#f00' });
          }
          en.lastShot = e.frame;
        }
        e.bullets.forEach((b, bIdx) => {
          if (b.owner === 'player' && !en.isDead && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) {
            en.health -= (b.damage || 100); if (en.health <= 0) en.isDead = true;
            if (!isShip) e.bullets.splice(bIdx, 1);
          }
        });
      });

      // Fixed: Adding split enemies to the main engine list so they appear and are processed.
      if (newEnemies.length > 0) e.enemies.push(...newEnemies);

      if (leader.health <= 0) onDie();
      if (allDead && newEnemies.length === 0) onWin();
      e.players.forEach(p => { if (p.invulnerable > 0) p.invulnerable--; });

      const isLvlBoss = e.level === 10 || e.level === 20;
      const targetZoom = isLvlBoss ? (e.level === 20 ? 0.35 : 0.45) : 1.0;
      e.zoom += (targetZoom - e.zoom) * 0.05;
      const visibleWidth = CANVAS_WIDTH / e.zoom;
      e.cameraX = leader.pos.x - visibleWidth * 0.3;
      const targetCameraY = isLvlBoss ? (398 - (CANVAS_HEIGHT / e.zoom) + 120) : 0;
      e.cameraY += (targetCameraY - e.cameraY) * 0.05;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const isCombiner = engineRef.current.unionTimer > 0;
      const isShip = engineRef.current.inSpaceship;

      ctx.save(); ctx.scale(e.zoom, e.zoom); ctx.translate(-e.cameraX, -e.cameraY);
      const visibleWidth = CANVAS_WIDTH / e.zoom; const visibleHeight = CANVAS_HEIGHT / e.zoom;
      ctx.fillStyle = '#050510'; ctx.fillRect(e.cameraX, e.cameraY, visibleWidth, visibleHeight);
      ctx.fillStyle = '#111'; ctx.fillRect(e.cameraX - 1000, 398, visibleWidth + 5000, 1000); ctx.strokeStyle = '#222';
      const startX = Math.floor(e.cameraX / 40) * 40;
      for(let i = startX - 40; i < e.cameraX + visibleWidth + 40; i += 40) ctx.strokeRect(i, 398, 40, 52);

      if ((e.level === 10 || e.level === 20) && !e.inSpaceship) {
        ctx.save(); ctx.translate(e.spaceshipPos.x + 60, e.spaceshipPos.y + 20); drawSpaceship(ctx, e.frame, 0.8); ctx.restore();
        ctx.fillStyle = '#fff'; ctx.font = '10px Orbitron'; ctx.fillText("[M] ENTER SHIP", e.spaceshipPos.x + 10, e.spaceshipPos.y - 20);
      }

      e.enemies.forEach(en => { if(!en.isDead) drawUnit(ctx, en.pos.x, en.pos.y, en.width, en.height, en.unit || RobotUnit.SENTINEL, Math.sign(e.players[0].pos.x - en.pos.x), e.frame, true, false, en.isTransformed, en.type, 1, 0, en.type === 'combinerBoss'); });

      e.players.forEach(player => {
        if (e.inSpaceship) {
          ctx.save(); ctx.translate(player.pos.x + 60, player.pos.y + 20); if (player.facing === -1) ctx.scale(-1, 1);
          drawSpaceship(ctx, e.frame, 1); ctx.restore();
        } else {
          const pw = isCombiner ? 64 : (player.isTransformed ? 48 : player.width);
          const ph = isCombiner ? 80 : (player.isTransformed ? 32 : player.height);
          drawUnit(ctx, player.pos.x, player.pos.y, pw, ph, player.unit, player.facing, e.frame, false, player.invulnerable > 0, player.isTransformed, 'bot', 1, upgrades.robotTier, isCombiner);
        }
      });

      e.bullets.forEach(b => { 
        ctx.fillStyle = b.color || '#00f3ff'; if (b.width > 20) { ctx.shadowBlur = 10; ctx.shadowColor = b.color || '#fff'; } 
        ctx.fillRect(b.pos.x, b.pos.y, b.width, b.height); ctx.shadowBlur = 0; 
      });
      ctx.restore();
    };
    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [onWin, onDie, upgrades.squad, upgrades.weaponTier, upgrades.robotTier]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden font-orbitron">
      <div className="absolute top-4 left-4 z-10 space-y-4 pointer-events-none w-[400px]">
        <div className="bg-black/80 border border-cyan-500/50 p-3 rounded backdrop-blur-md shadow-lg">
          <div className="text-[10px] text-cyan-400 font-bold uppercase mb-1 flex justify-between">
            <span>{isSpaceshipMode ? 'INTERCEPTOR SHIP' : (isSquadMode ? 'SQUAD COMMAND' : (unionTime > 0 ? 'SQUAD COMBINER' : `${ROBOT_STATS[currentUnit].name} CHASSIS`))}</span>
            <span>{Math.round(health)}/{Math.round(maxHealth)}</span>
          </div>
          <div className="w-48 h-2.5 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
            <div className="h-full shadow-[0_0_15px_#00f3ff] transition-all duration-300" style={{ width: `${(health / maxHealth) * 100}%`, backgroundColor: health < maxHealth * 0.3 ? '#ef4444' : (unionTime > 0 || isSpaceshipMode ? '#fff' : '#00f3ff') }} />
          </div>
          {unionTime > 0 && (
            <div className="mt-2">
              <div className="text-[8px] text-yellow-400 font-bold uppercase mb-0.5">COMBINER INTEGRITY</div>
              <div className="w-full h-1 bg-gray-950 rounded-full overflow-hidden border border-gray-900">
                <div className="h-full bg-yellow-500 shadow-[0_0_10px_#fbbf24] transition-all duration-100" style={{ width: `${(unionTime / SQUAD_UNION_DURATION) * 100}%` }} />
              </div>
            </div>
          )}
        </div>
      </div>
      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full aspect-video shadow-2xl rounded-lg border-2 border-cyan-900/50" />
      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 pointer-events-none text-white/30 text-[8px] font-mono tracking-widest uppercase flex gap-6">
        <span>WASD: Move/Aim</span><span>Space: Fire</span><span>Shift: Transform</span><span>1-5: Squad</span><span>C: Combine</span><span>B: All Robots</span>{(level === 10 || level === 20) && <span>M: Ship</span>}
      </div>
      {(unionTime > SQUAD_UNION_DURATION - 60 || (isSpaceshipMode && engineRef.current.frame % 60 < 30) || (isSquadMode && engineRef.current.frame % 60 < 30)) && (
        <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
          <div className="text-6xl font-black italic text-white tracking-tighter shadow-2xl animate-pulse uppercase">
            {isSpaceshipMode ? 'Heavy Laser Online' : (isSquadMode ? 'Squad Command Active' : 'Squad Combination Engaged')}
          </div>
        </div>
      )}
      {(level === 10 || level === 20) && (
        <div className="absolute top-20 right-4 p-4 border border-red-500 bg-red-950/20 text-red-500 text-xs animate-pulse uppercase tracking-widest">
           Warning: {level === 20 ? 'Level Apocalypse' : 'Gigantus Titan'} Detected
        </div>
      )}
    </div>
  );
};

export default GameView;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { GameState, LevelInfo, RobotUnit, Upgrades } from './types';
import { getLevelBriefing } from './services/geminiService';
import MainMenu from './components/MainMenu';
import Briefing from './components/Briefing';
import GameView from './components/GameView';
import GameOver from './components/GameOver';
import Victory from './components/Victory';
import Shop from './components/Shop';
import RobotShop from './components/RobotShop';
import LevelSelect from './components/LevelSelect';

const SAVE_KEY = 'cybercop_save_data_v2';

const DEFAULT_UPGRADES: Upgrades = { 
  robotTier: 0, 
  weaponTier: 0, 
  unlockedUnits: [RobotUnit.SENTINEL],
  squad: [RobotUnit.SENTINEL]
};

const App: React.FC = () => {
  // Use a function for lazy state initialization to ensure it only runs once and loads from storage immediately
  const [saveData, setSaveData] = useState(() => {
    const data = localStorage.getItem(SAVE_KEY);
    if (!data) return null;
    try {
      return JSON.parse(data);
    } catch (e) {
      return null;
    }
  });

  const [gameState, setGameState] = useState<GameState>(GameState.MENU);
  const [level, setLevel] = useState<number>(saveData?.level || 1);
  const [maxUnlockedLevel, setMaxUnlockedLevel] = useState<number>(saveData?.maxUnlockedLevel || 1);
  const [money, setMoney] = useState<number>(saveData?.money || 0);
  const [upgrades, setUpgrades] = useState<Upgrades>(saveData?.upgrades || DEFAULT_UPGRADES);

  const [briefing, setBriefing] = useState<LevelInfo | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [shopOrigin, setShopOrigin] = useState<GameState>(GameState.MENU);
  const [saveFeedback, setSaveFeedback] = useState(false);

  // Persistence: Save state to localStorage whenever any critical game state changes
  useEffect(() => {
    const dataToSave = {
      level,
      maxUnlockedLevel,
      money,
      upgrades
    };
    localStorage.setItem(SAVE_KEY, JSON.stringify(dataToSave));
    setSaveData(dataToSave);
  }, [level, maxUnlockedLevel, money, upgrades]);

  // Global pause listener
  useEffect(() => {
    const handleGlobalKeyDown = (e: KeyboardEvent) => {
      if (e.code === 'KeyP') {
        setGameState(prev => {
          if (prev === GameState.PLAYING) return GameState.PAUSED;
          if (prev === GameState.PAUSED) return GameState.PLAYING;
          return prev;
        });
      }
    };
    window.addEventListener('keydown', handleGlobalKeyDown);
    return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, []);

  const handleOpenKeySelection = async () => {
    await (window as any).aistudio.openSelectKey();
    if (gameState === GameState.BRIEFING) {
      startLevel(level);
    }
  };

  const startLevel = useCallback(async (lvl: number) => {
    setIsLoading(true);
    setGameState(GameState.BRIEFING);
    setLevel(lvl);

    const data = await getLevelBriefing(lvl);
    setBriefing(data);
    setIsLoading(false);
  }, []);

  const handleStartGame = async () => {
    const hasKey = await (window as any).aistudio.hasSelectedApiKey();
    if (!hasKey) {
      await (window as any).aistudio.openSelectKey();
    }

    // Explicitly reset progress for New Game
    setLevel(1);
    setMaxUnlockedLevel(1);
    setMoney(0);
    setUpgrades({ ...DEFAULT_UPGRADES });

    startLevel(1);
  };

  const handleContinueGame = () => {
    if (saveData) {
      const targetLevel = Math.min(saveData.level || 1, 20);
      setLevel(targetLevel);
      setMaxUnlockedLevel(saveData.maxUnlockedLevel || targetLevel || 1);
      setMoney(saveData.money || 0);
      setUpgrades(saveData.upgrades || DEFAULT_UPGRADES);
      startLevel(targetLevel);
    }
  };

  const handleLevelComplete = () => {
    const reward = level === 20 ? 15000 : 150;
    setMoney(m => m + reward); 

    const newlyUnlocked = level + 1;
    if (newlyUnlocked > maxUnlockedLevel) {
      setMaxUnlockedLevel(newlyUnlocked);
    }

    setGameState(GameState.LEVEL_COMPLETE);
  };

  const openShop = (origin: GameState) => {
    setShopOrigin(origin);
    setGameState(GameState.SHOP);
  };

  const openRobotShop = (origin: GameState) => {
    setShopOrigin(origin);
    setGameState(GameState.ROBOT_SHOP);
  };

  const openLevelSelect = () => {
    setGameState(GameState.LEVEL_SELECT);
  };

  const handleSelectLevel = (lvlNum: number) => {
    startLevel(lvlNum);
  };

  const handleNextLevel = () => {
    const nextLvl = level + 1;
    if (level === 20) {
      setGameState(GameState.VICTORY);
    } else {
      startLevel(nextLvl);
    }
  };

  const handleShopExit = () => {
    if (shopOrigin === GameState.MENU) {
      setGameState(GameState.MENU);
    } else {
      setGameState(GameState.LEVEL_COMPLETE);
    }
  };

  const handlePlayerDeath = () => {
    setGameState(GameState.GAMEOVER);
  };

  const handleRetry = () => {
    startLevel(level);
  };

  const buyRobotTier = () => {
    if (money >= 100) {
      setMoney(m => m - 100);
      setUpgrades(u => ({ ...u, robotTier: u.robotTier + 1 }));
    }
  };

  const buyWeaponTier = () => {
    if (money >= 50) {
      setMoney(m => m - 50);
      setUpgrades(u => ({ ...u, weaponTier: u.weaponTier + 1 }));
    }
  };

  const unlockRobotUnit = (unit: RobotUnit, price: number) => {
    if (money >= price && !upgrades.unlockedUnits.includes(unit)) {
      setMoney(m => m - price);
      setUpgrades(u => {
        const newUnlocked = [...u.unlockedUnits, unit];
        const newSquad = u.squad.length < 5 ? [...u.squad, unit] : u.squad;
        return {
          ...u,
          unlockedUnits: newUnlocked,
          squad: newSquad
        };
      });
    }
  };

  const toggleSquadMember = (unit: RobotUnit) => {
    setUpgrades(u => {
      const isCurrentlyIn = u.squad.includes(unit);
      if (isCurrentlyIn) {
        if (u.squad.length <= 1) return u;
        return { ...u, squad: u.squad.filter(s => s !== unit) };
      } else {
        if (u.squad.length >= 5) return u;
        return { ...u, squad: [...u.squad, unit] };
      }
    });
  };

  const isGameVisible = gameState === GameState.PLAYING || gameState === GameState.PAUSED;

  return (
    <div className="w-full h-screen bg-black overflow-hidden select-none text-white font-rajdhani">
      <div className="fixed top-4 right-4 z-[100] flex gap-2">
        <div className={`px-4 py-2 border font-bold text-[10px] uppercase tracking-widest transition-all font-orbitron shadow-lg bg-black/80 ${saveFeedback ? 'border-emerald-500 text-emerald-400' : 'border-cyan-500/30 text-cyan-400/50'}`}>
          AUTO-SAVE: ACTIVE
        </div>
      </div>

      <button 
        onClick={handleOpenKeySelection}
        className="fixed bottom-4 right-4 z-[100] px-4 py-1 text-[10px] bg-gray-900/50 border border-gray-700 text-gray-500 hover:text-cyan-400 hover:border-cyan-500 transition-all font-mono uppercase tracking-tighter"
      >
        Configure Uplink (API Key)
      </button>

      {gameState === GameState.MENU && (
        <MainMenu 
          onStart={handleStartGame} 
          onContinue={handleContinueGame} 
          onOpenShop={() => openShop(GameState.MENU)}
          onOpenRobotShop={() => openRobotShop(GameState.MENU)}
          onOpenLevelSelect={openLevelSelect}
          hasSave={!!saveData} 
        />
      )}

      {gameState === GameState.LEVEL_SELECT && (
        <LevelSelect 
          currentUnlocked={maxUnlockedLevel} 
          onSelect={handleSelectLevel} 
          onBack={() => setGameState(GameState.MENU)} 
        />
      )}

      {gameState === GameState.BRIEFING && (
        <Briefing 
          briefing={briefing || {} as LevelInfo} 
          isLoading={isLoading} 
          onConfirm={() => setGameState(GameState.PLAYING)}
        />
      )}

      {isGameVisible && (
        <GameView 
          level={level} 
          upgrades={upgrades}
          isPaused={gameState === GameState.PAUSED}
          onWin={handleLevelComplete} 
          onDie={handlePlayerDeath} 
        />
      )}

      {gameState === GameState.PAUSED && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex flex-col items-center justify-center z-50 animate-in fade-in duration-200">
          <div className="p-10 border-2 border-cyan-500 bg-black/80 relative overflow-hidden group">
            <div className="absolute top-0 left-0 w-full h-1 bg-cyan-500 animate-scan"></div>
            <h2 className="text-6xl font-black text-cyan-400 italic tracking-tighter uppercase mb-4 font-orbitron">SYSTEM SUSPENDED</h2>
            <p className="text-cyan-200 font-mono tracking-widest text-center mb-8">TACTICAL ANALYSIS IN PROGRESS</p>
            <div className="flex flex-col gap-4 items-center">
              <button 
                onClick={() => setGameState(GameState.PLAYING)}
                className="px-12 py-4 bg-cyan-600 hover:bg-cyan-500 text-white font-bold text-2xl border-b-4 border-cyan-900 transition-all w-full uppercase font-orbitron"
              >
                RESUME MISSION
              </button>
              <button 
                onClick={() => setGameState(GameState.MENU)}
                className="px-12 py-2 text-cyan-400 font-bold hover:text-white transition-all uppercase text-sm font-orbitron"
              >
                ABORT TO HQ
              </button>
            </div>
          </div>
        </div>
      )}

      {gameState === GameState.LEVEL_COMPLETE && (
        <div className="fixed inset-0 bg-black/95 flex flex-col items-center justify-center z-50">
          <h2 className="text-5xl text-cyan-400 mb-2 font-black italic tracking-tighter animate-pulse uppercase font-orbitron">
            Sector {level} Secured
          </h2>
          <div className="text-2xl text-yellow-400 mb-8 font-bold tracking-widest font-orbitron">
            REWARD EARNED: ${level === 20 ? 15000 : 150}
          </div>

          <div className="flex flex-col items-center gap-6">
            <div className="flex gap-4">
              <button 
                onClick={() => openShop(GameState.LEVEL_COMPLETE)}
                className="px-8 py-4 bg-yellow-600 hover:bg-yellow-500 text-white font-bold rounded-sm border-b-4 border-yellow-800 transition-all active:translate-y-1 w-64 shadow-[0_0_20px_rgba(202,138,4,0.3)] font-orbitron uppercase"
              >
                VISIT ARMORY
              </button>
              <button 
                onClick={() => openRobotShop(GameState.LEVEL_COMPLETE)}
                className="px-8 py-4 bg-purple-700 hover:bg-purple-600 text-white font-bold rounded-sm border-b-4 border-purple-900 transition-all active:translate-y-1 w-64 shadow-[0_0_20px_rgba(168,85,247,0.3)] font-orbitron uppercase"
              >
                SQUAD ASSEMBLY
              </button>
            </div>

            <button 
              onClick={handleNextLevel}
              className={`px-12 py-4 font-black rounded-sm transition-all w-full max-md shadow-[0_0_30px_rgba(6,182,212,0.3)] uppercase tracking-widest font-orbitron text-xl ${
                level >= 20 ? 'bg-white text-black hover:bg-cyan-400' : 'bg-cyan-700 hover:bg-cyan-600 text-white'
              }`}
            >
              {level >= 20 ? 'Finalize Victory' : `Deploy to Sector ${level + 1}`}
            </button>

            <button 
              onClick={() => setGameState(GameState.MENU)}
              className="px-12 py-2 text-gray-400 font-bold hover:text-white transition-all uppercase text-sm mt-4 border border-gray-800 hover:border-gray-400 bg-gray-950/40 font-orbitron"
            >
              Return to HQ
            </button>
          </div>
        </div>
      )}

      {gameState === GameState.SHOP && (
        <Shop 
          money={money} 
          upgrades={upgrades} 
          onBuyRobot={buyRobotTier} 
          onBuyWeapon={buyWeaponTier} 
          onExit={handleShopExit}
          isFromMenu={shopOrigin === GameState.MENU}
        />
      )}

      {gameState === GameState.ROBOT_SHOP && (
        <RobotShop 
          money={money} 
          unlockedUnits={upgrades.unlockedUnits} 
          squad={upgrades.squad}
          onUnlock={unlockRobotUnit} 
          onToggleSquad={toggleSquadMember}
          onExit={handleShopExit}
        />
      )}

      {gameState === GameState.GAMEOVER && (
        <GameOver level={level} onRetry={handleRetry} onMenu={() => setGameState(GameState.MENU)} />
      )}

      {gameState === GameState.VICTORY && (
        <Victory onMenu={() => setGameState(GameState.MENU)} />
      )}
    </div>
  );
};

export default App;

