                          : 'bg-gray-800 text-gray-500 cursor-not-allowed'
                      }`}
                    >
                      {canAfford ? 'AUTHORIZE' : 'INSUFFICIENT'}
                    </button>
                  )}
                </div>
              </div>
            );
          })}
        </div>

        <button 
          onClick={onExit}
          className="w-full py-3 border-2 border-purple-500 text-purple-400 font-black text-lg hover:bg-purple-500 hover:text-black transition-all uppercase font-orbitron shrink-0"
        >
          Confirm Squad & Exit
        </button>
      </div>
      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 6px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: rgba(0,0,0,0.3); }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #7e22ce; border-radius: 10px; }
      `}</style>
    </div>
  );
};

