import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { GameState, LevelInfo, RobotUnit, Upgrades } from './types';
import { getLevelBriefing } from './services/geminiService';
import MainMenu from './components/MainMenu';
import Briefing from './components/Briefing';
import GameView from './components/GameView';
import GameOver from './components/GameOver';
import Victory from './components/Victory';
import Shop from './components/Shop';
import LevelSelect from './components/LevelSelect';

const SAVE_KEY = 'cybercop_save_data_v3';

const DEFAULT_UPGRADES: Upgrades = { 
  robotTier: 0, 
  weaponTier: 0, 
  unlockedUnits: [RobotUnit.SENTINEL]
};

const App: React.FC = () => {
  const [saveData, setSaveData] = useState(() => {
    const data = localStorage.getItem(SAVE_KEY);
    if (!data) return null;
    try {
      return JSON.parse(data);
    } catch (e) {
      return null;
    }
  });

  const [gameState, setGameState] = useState<GameState>(GameState.MENU);
  const [level, setLevel] = useState<number>(saveData?.level || 1);
  const [maxUnlockedLevel, setMaxUnlockedLevel] = useState<number>(saveData?.maxUnlockedLevel || 1);
  const [money, setMoney] = useState<number>(saveData?.money || 0);
  const [upgrades, setUpgrades] = useState<Upgrades>(saveData?.upgrades || DEFAULT_UPGRADES);

  const [briefing, setBriefing] = useState<LevelInfo | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [shopOrigin, setShopOrigin] = useState<GameState>(GameState.MENU);

  useEffect(() => {
    const dataToSave = { level, maxUnlockedLevel, money, upgrades };
    localStorage.setItem(SAVE_KEY, JSON.stringify(dataToSave));
  }, [level, maxUnlockedLevel, money, upgrades]);

  useEffect(() => {
    const handleGlobalKeyDown = (e: KeyboardEvent) => {
      if (e.code === 'KeyP') {
        setGameState(prev => {
          if (prev === GameState.PLAYING) return GameState.PAUSED;
          if (prev === GameState.PAUSED) return GameState.PLAYING;
          return prev;
        });
      }
    };
    window.addEventListener('keydown', handleGlobalKeyDown);
    return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, []);

  const handleOpenKeySelection = async () => {
    await (window as any).aistudio.openSelectKey();
    if (gameState === GameState.BRIEFING) {
      startLevel(level);
    }
  };

  const startLevel = useCallback(async (lvl: number) => {
    setIsLoading(true);
    setGameState(GameState.BRIEFING);
    setLevel(lvl);
    const data = await getLevelBriefing(lvl);
    setBriefing(data);
    setIsLoading(false);
  }, []);

  const handleStartGame = async () => {
    const hasKey = await (window as any).aistudio.hasSelectedApiKey();
    if (!hasKey) await (window as any).aistudio.openSelectKey();
    setLevel(1);
    setMaxUnlockedLevel(1);
    setMoney(0);
    setUpgrades({ ...DEFAULT_UPGRADES });
    startLevel(1);
  };

  const handleContinueGame = () => {
    if (saveData) {
      setLevel(saveData.level || 1);
      setMaxUnlockedLevel(saveData.maxUnlockedLevel || 1);
      setMoney(saveData.money || 0);
      setUpgrades(saveData.upgrades || DEFAULT_UPGRADES);
      startLevel(saveData.level || 1);
    }
  };

  const handleLevelComplete = () => {
    const reward = level === 20 ? 15000 : 500;
    setMoney(m => m + reward); 
    const newlyUnlocked = level + 1;
    if (newlyUnlocked > maxUnlockedLevel && newlyUnlocked <= 20) {
      setMaxUnlockedLevel(newlyUnlocked);
    }
    setGameState(GameState.LEVEL_COMPLETE);
  };

  const openShop = (origin: GameState) => {
    setShopOrigin(origin);
    setGameState(GameState.SHOP);
  };

  const handleSelectLevel = (lvlNum: number) => startLevel(lvlNum);

  const handleNextLevel = () => {
    if (level === 20) setGameState(GameState.VICTORY);
    else startLevel(level + 1);
  };

  const handleShopExit = () => {
    setGameState(shopOrigin === GameState.MENU ? GameState.MENU : GameState.LEVEL_COMPLETE);
  };

  const handlePlayerDeath = () => setGameState(GameState.GAMEOVER);

  const buyRobotTier = () => {
    if (money >= 100) {
      setMoney(m => m - 100);
      setUpgrades(u => ({ ...u, robotTier: u.robotTier + 1 }));
    }
  };

  const buyWeaponTier = () => {
    if (money >= 50) {
      setMoney(m => m - 50);
      setUpgrades(u => ({ ...u, weaponTier: u.weaponTier + 1 }));
    }
  };

  const unlockRobotUnit = (unit: RobotUnit, price: number) => {
    if (money >= price && !upgrades.unlockedUnits.includes(unit)) {
      setMoney(m => m - price);
      setUpgrades(u => ({
        ...u,
        unlockedUnits: [...u.unlockedUnits, unit]
      }));
    }
  };

  const isGameVisible = gameState === GameState.PLAYING || gameState === GameState.PAUSED;

  return (
    <div className="w-full h-screen bg-black overflow-hidden select-none text-white font-rajdhani">
      <button onClick={handleOpenKeySelection} className="fixed bottom-4 right-4 z-[100] px-4 py-1 text-[10px] bg-gray-900/50 border border-gray-700 text-gray-500 hover:text-cyan-400 hover:border-cyan-500 transition-all font-mono uppercase tracking-tighter">
        Configure Uplink (API Key)
      </button>

      {gameState === GameState.MENU && (
        <MainMenu onStart={handleStartGame} onContinue={handleContinueGame} onOpenShop={() => openShop(GameState.MENU)} onOpenLevelSelect={() => setGameState(GameState.LEVEL_SELECT)} hasSave={!!saveData} />
      )}

      {gameState === GameState.LEVEL_SELECT && (
        <LevelSelect currentUnlocked={maxUnlockedLevel} onSelect={handleSelectLevel} onBack={() => setGameState(GameState.MENU)} />
      )}

      {gameState === GameState.BRIEFING && (
        <Briefing briefing={briefing || {} as LevelInfo} isLoading={isLoading} onConfirm={() => setGameState(GameState.PLAYING)} />
      )}

      {isGameVisible && (
        <GameView level={level} upgrades={upgrades} isPaused={gameState === GameState.PAUSED} onWin={handleLevelComplete} onDie={handlePlayerDeath} />
      )}

      {gameState === GameState.PAUSED && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex flex-col items-center justify-center z-50">
          <div className="p-10 border-2 border-cyan-500 bg-black/80 relative overflow-hidden group">
            <h2 className="text-6xl font-black text-cyan-400 italic tracking-tighter uppercase mb-4 font-orbitron">SYSTEM SUSPENDED</h2>
            <div className="flex flex-col gap-4 items-center">
              <button onClick={() => setGameState(GameState.PLAYING)} className="px-12 py-4 bg-cyan-600 hover:bg-cyan-500 text-white font-bold text-2xl border-b-4 border-cyan-900 transition-all w-full uppercase font-orbitron">RESUME MISSION</button>
              <button onClick={() => setGameState(GameState.MENU)} className="px-12 py-2 text-cyan-400 font-bold hover:text-white transition-all uppercase text-sm font-orbitron">ABORT TO HQ</button>
            </div>
          </div>
        </div>
      )}

      {gameState === GameState.LEVEL_COMPLETE && (
        <div className="fixed inset-0 bg-black/95 flex flex-col items-center justify-center z-50">
          <h2 className="text-5xl text-cyan-400 mb-2 font-black italic tracking-tighter animate-pulse uppercase font-orbitron">Sector {level} Secured</h2>
          <div className="text-2xl text-yellow-400 mb-8 font-bold tracking-widest font-orbitron">REWARD EARNED: ${level === 20 ? 15000 : 500}</div>
          <div className="flex flex-col items-center gap-6">
            <button onClick={() => openShop(GameState.LEVEL_COMPLETE)} className="px-8 py-4 bg-yellow-600 hover:bg-yellow-500 text-white font-bold rounded-sm border-b-4 border-yellow-800 transition-all w-64 font-orbitron uppercase">VISIT ARMORY</button>
            <button onClick={handleNextLevel} className={`px-12 py-4 font-black rounded-sm transition-all w-full max-md shadow-[0_0_30px_rgba(6,182,212,0.3)] uppercase tracking-widest font-orbitron text-xl ${level >= 20 ? 'bg-white text-black hover:bg-cyan-400' : 'bg-cyan-700 hover:bg-cyan-600 text-white'}`}>{level >= 20 ? 'Finalize Victory' : `Deploy to Sector ${level + 1}`}</button>
            <button onClick={() => setGameState(GameState.MENU)} className="px-12 py-2 text-gray-400 font-bold hover:text-white transition-all uppercase text-sm mt-4 border border-gray-800 hover:border-gray-400 bg-gray-950/40 font-orbitron">Return to HQ</button>
          </div>
        </div>
      )}

      {gameState === GameState.SHOP && (
        <Shop money={money} upgrades={upgrades} onBuyRobot={buyRobotTier} onBuyWeapon={buyWeaponTier} onUnlockUnit={unlockRobotUnit} onExit={handleShopExit} isFromMenu={shopOrigin === GameState.MENU} />
      )}

      {gameState === GameState.GAMEOVER && (
        <GameOver level={level} onRetry={() => startLevel(level)} onMenu={() => setGameState(GameState.MENU)} />
      )}

      {gameState === GameState.VICTORY && <Victory onMenu={() => setGameState(GameState.MENU)} />}
    </div>
  );
};

export default App;

