          <div className="p-4 border-2 border-red-500 bg-red-950/10 flex flex-col justify-between">
            <div>
              <h3 className="text-lg font-bold text-white uppercase font-orbitron">Overclock Systems (Weapon)</h3>
              <p className="text-gray-400 text-xs mt-1">Faster recharge cycles for all offensive modules.</p>
              <p className="text-red-300 font-mono text-[10px] mt-2 uppercase tracking-widest">Current Tier: {upgrades.weaponTier}</p>
            </div>
            <button disabled={money < 50} onClick={onBuyWeapon} className={`mt-4 py-2 font-bold uppercase transition-all font-orbitron ${money >= 50 ? 'bg-red-600 hover:bg-red-500 text-white' : 'bg-gray-800 text-gray-500'}`}>Upgrade Weapons ($50)</button>
