        </div>

        <div className="mb-4">
          <h3 className="text-cyan-400 font-bold uppercase tracking-widest text-sm mb-3 font-orbitron">Recruit Specialized Units</h3>
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
            {ROBOT_CATALOG.map(robot => {
              const isUnlocked = upgrades.unlockedUnits.includes(robot.unit);
              const canAfford = money >= robot.price;
              return (
                <div key={robot.unit} className={`p-3 border transition-all ${isUnlocked ? 'border-gray-700 bg-gray-900/40 opacity-50' : canAfford ? 'border-yellow-600/50 bg-yellow-950/5' : 'border-gray-800'}`}>
                  <h4 className="text-[10px] font-black font-orbitron" style={{ color: robot.color }}>{robot.name}</h4>
                  <p className="text-[8px] text-gray-500 mb-2 truncate">{robot.description}</p>
                  {isUnlocked ? (
                    <div className="text-[9px] text-emerald-500 font-bold uppercase text-center py-1">Deployed</div>
                  ) : (
                    <button disabled={!canAfford} onClick={() => onUnlockUnit(robot.unit, robot.price)} className={`w-full py-1 text-[9px] font-bold uppercase font-orbitron ${canAfford ? 'bg-yellow-600 hover:bg-yellow-500 text-black' : 'bg-gray-800 text-gray-500'}`}>Unlock ${robot.price}</button>
                  )}
                </div>
              );
            })}
          </div>
        </div>

        <button onClick={onExit} className="w-full py-4 border-2 border-cyan-500 text-cyan-400 font-black text-xl hover:bg-cyan-500 hover:text-black transition-all uppercase font-orbitron">Return to Operations</button>
      </div>
    </div>
  );
};

