import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const GROUND_Y = 350;

interface PlayerEntity {
  unit: RobotUnit;
  pos: { x: number; y: number };
  vel: { x: number; y: number };
  width: number;
  height: number;
  facing: number;
  grounded: boolean;
  lastShot: number;
  invulnerable: number;
  health: number;
  maxHealth: number;
  isTransformed: boolean;
  id: string;
}

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { name: "SENTINEL", color: '#00f3ff', hpMult: 1.0, robot: { speed: 4, jump: -11, fireRate: 15 }, alt: { speed: 8, jump: -5, fireRate: 25, type: 'Police Car' }},
  [RobotUnit.STRIKER]: { name: "STRIKER", color: '#fbbf24', hpMult: 0.8, robot: { speed: 6, jump: -10, fireRate: 10 }, alt: { speed: 12, jump: -4, fireRate: 20, type: 'Bike' }},
  [RobotUnit.FALCON]: { name: "FALCON", color: '#22d3ee', hpMult: 0.7, robot: { speed: 5, jump: -10, fireRate: 12 }, alt: { speed: 7, jump: -7, fireRate: 15, type: 'Jet' }},
  [RobotUnit.TITAN]: { name: "TITAN", color: '#ef4444', hpMult: 2.5, robot: { speed: 2.5, jump: -12, fireRate: 30 }, alt: { speed: 4, jump: 0, fireRate: 20, type: 'Tank' }},
  [RobotUnit.SPECTER]: { name: "SPECTER", color: '#a855f7', hpMult: 0.6, robot: { speed: 5, jump: -11, fireRate: 20 }, alt: { speed: 6, jump: -14, fireRate: 40, type: 'Ambulance' }},
  [RobotUnit.VANGUARD]: { name: "VANGUARD", color: '#10b981', hpMult: 2.0, robot: { speed: 3.5, jump: -10, fireRate: 25 }, alt: { speed: 6, jump: -4, fireRate: 30, type: 'Fire Truck' }},
  [RobotUnit.NIGHTSHADE]: { name: "NIGHTSHADE", color: '#6366f1', hpMult: 0.9, robot: { speed: 7, jump: -13, fireRate: 12 }, alt: { speed: 10, jump: -6, fireRate: 18, type: 'Cyber Tiger' }},
  [RobotUnit.BLAZE]: { name: "BLAZE", color: '#f97316', hpMult: 1.2, robot: { speed: 4.5, jump: -11, fireRate: 18 }, alt: { speed: 12, jump: -5, fireRate: 15, type: 'Canon Race Car' }},
  [RobotUnit.GLITCH]: { name: "GLITCH", color: '#ec4899', hpMult: 1.0, robot: { speed: 5, jump: -12, fireRate: 14 }, alt: { speed: 10, jump: -12, fireRate: 16, type: 'Flying Car' }},
  [RobotUnit.OMEGA]: { name: "OMEGA", color: '#ffffff', hpMult: 3.0, robot: { speed: 6, jump: -14, fireRate: 10 }, alt: { speed: 8, jump: -10, fireRate: 10, type: 'Combat Blimp' }},
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [squadStatus, setSquadStatus] = useState<PlayerEntity[]>([]);

  const engineRef = useRef({
    players: [] as PlayerEntity[],
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    cameraY: 0,
    zoom: 1.0,
    isPaused: isPaused,
    level: level,
    upgrades: upgrades,
  });

  useEffect(() => { 
    engineRef.current.isPaused = isPaused; 
    engineRef.current.level = level;
    engineRef.current.upgrades = upgrades;
  }, [isPaused, level, upgrades]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff66');
    grad.addColorStop(1, '#000000aa');
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.6)';
    ctx.lineWidth = 1;
    ctx.stroke();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, alpha = 1) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8;
    const armSwing = Math.cos(time) * 10;
    ctx.save();
    ctx.globalAlpha = alpha;
    drawMechanicalPart(ctx, -12, -18, 24, 28, color, 4);
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? '#ff0000' : '#00f3ff'; ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);
    ctx.restore();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, color: string, frame: number, alpha = 1) => {
    ctx.save(); ctx.globalAlpha = alpha;
    switch(unit) {
      case RobotUnit.SENTINEL:
        drawMechanicalPart(ctx, -28, -10, 56, 20, color, 8);
        drawMechanicalPart(ctx, -18, -22, 36, 14, '#111', 4);
        ctx.fillStyle = frame % 10 < 5 ? '#ff0000' : '#0000ff'; ctx.fillRect(-6, -24, 12, 4);
        ctx.fillStyle = '#111'; ctx.beginPath(); ctx.arc(-18, 12, 8, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.arc(18, 12, 8, 0, Math.PI * 2); ctx.fill();
        break;
      case RobotUnit.OMEGA:
        const bSwing = Math.sin(frame * 0.05) * 5; ctx.translate(0, bSwing);
        ctx.save(); ctx.scale(1.2, 0.8); drawMechanicalPart(ctx, -40, -40, 80, 80, color, 50); ctx.restore();
        ctx.save(); ctx.translate(0, -35); drawMechanicalPart(ctx, -8, -10, 16, 10, '#222', 2); drawMechanicalPart(ctx, 0, -8, 30, 6, '#555', 1); ctx.restore();
        break;
      default:
        drawMechanicalPart(ctx, -25, -12, 50, 24, color, 6);
        drawMechanicalPart(ctx, -10, -22, 20, 10, '#333', 2);
        break;
    }
    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy: boolean, invulnerable: boolean, transformed: boolean, alpha: number) => {
    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    ctx.scale(facing < 0 ? -1 : 1, 1);
    const drawAlpha = invulnerable ? (0.5 + Math.sin(frame * 0.5) * 0.3) * alpha : alpha;
    const color = isEnemy ? '#ff0055' : ROBOT_STATS[unit].color;
    if (transformed) drawAltMode(ctx, unit, color, frame, drawAlpha);
    else drawHumanoid(ctx, color, frame, isEnemy, drawAlpha);
    ctx.restore();
  };

  const createPlayer = (unit: RobotUnit, x: number, y: number): PlayerEntity => {
    const stats = ROBOT_STATS[unit];
    const baseHP = 100 + (engineRef.current.upgrades.robotTier * 50);
    return {
      id: Math.random().toString(36).substr(2, 9),
      unit,
      pos: { x, y: GROUND_Y - 48 }, // Spawning directly on ground
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: true,
      lastShot: 0,
      invulnerable: 0,
      health: baseHP * stats.hpMult,
      maxHealth: baseHP * stats.hpMult,
      isTransformed: false
    };
  };

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    e.frame = 0; e.cameraX = 0; e.cameraY = 0; e.bullets = [];
    const players = upgrades.unlockedUnits.map((unit, i) => createPlayer(unit, 100 - i * 40, GROUND_Y - 48));
    e.players = players;

    const enemies: Enemy[] = [];
    const enemyCount = level === 20 ? 15 : 5;
    for (let i = 0; i < enemyCount; i++) {
      const isBoss = i === enemyCount - 1;
      const eh = isBoss ? 2000 + level * 500 : 100;
      enemies.push({ id: i, pos: { x: 800 + i * 500, y: GROUND_Y - 72 }, vel: { x: 0, y: 0 }, width: isBoss ? 64 : 48, height: isBoss ? 72 : 72, health: eh, maxHealth: eh, isDead: false, type: isBoss ? 'boss' : 'grunt', lastShot: 0 });
    }
    e.enemies = enemies;
    setSquadStatus([...players]);
  }, [level, upgrades]);

  useEffect(() => { resetLevel(); }, [resetLevel]);

  const drawParallax = (ctx: CanvasRenderingContext2D, frame: number, camX: number) => {
    // 1. Far Deep Sky - Background
    ctx.fillStyle = '#020208';
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // 2. Stars - Move at 5% of camera speed
    const farCamX = camX * 0.05;
    for (let i = 0; i < 60; i++) {
      const sx = (Math.sin(i * 123.4) * 20000 - farCamX) % CANVAS_WIDTH;
      const sy = (Math.cos(i * 456.7) * 20000) % (CANVAS_HEIGHT - 100);
      const starX = sx < 0 ? sx + CANVAS_WIDTH : sx;
      const starY = sy < 0 ? sy + (CANVAS_HEIGHT - 100) : sy;
      ctx.fillStyle = i % 15 === 0 ? '#00f3ff88' : '#ffffff22';
      ctx.fillRect(starX, starY, 1.2, 1.2);
    }

    // 3. Very Distant Towers - Move at 15% speed
    const veryFarTowersX = camX * 0.15;
    ctx.fillStyle = '#0a0a1a';
    for (let i = 0; i < 12; i++) {
      const w = 40 + Math.abs(Math.sin(i * 11)) * 30;
      const h = 80 + Math.abs(Math.cos(i * 5)) * 120;
      const x = ((i * 150) - veryFarTowersX) % (CANVAS_WIDTH + w);
      const realX = x < -w ? x + (CANVAS_WIDTH + 150 + w) : x;
      ctx.fillRect(realX, GROUND_Y - h + 50, w, h);
    }

    // 4. Mid City - Move at 35% speed
    const midCamX = camX * 0.35;
    ctx.fillStyle = '#121228';
    for (let i = 0; i < 10; i++) {
      const w = 80 + Math.abs(Math.sin(i * 1.5)) * 40;
      const h = 100 + Math.abs(Math.cos(i * 2.1)) * 150;
      const x = ((i * 250) - midCamX) % (CANVAS_WIDTH + w);
      const realX = x < -w ? x + (CANVAS_WIDTH + 250 + w) : x;
      ctx.fillRect(realX, GROUND_Y - h + 50, w, h);
      // Windows / Highlights
      ctx.fillStyle = '#00f3ff11';
      ctx.fillRect(realX + 5, GROUND_Y - h + 60, w - 10, 5);
      ctx.fillStyle = '#121228';
    }

    // 5. Near Structural Structures - Move at 65% speed
    const nearCamX = camX * 0.65;
    ctx.fillStyle = '#1a1a35';
    for (let i = 0; i < 8; i++) {
      const w = 120;
      const h = 50 + Math.abs(Math.sin(i * 3.3)) * 40;
      const x = ((i * 400) - nearCamX) % (CANVAS_WIDTH + w);
      const realX = x < -w ? x + (CANVAS_WIDTH + 400 + w) : x;
      ctx.fillRect(realX, GROUND_Y - h + 50, w, h);
      ctx.strokeStyle = '#00f3ff11';
      ctx.strokeRect(realX, GROUND_Y - h + 50, w, h);
    }
  };

  useEffect(() => {
    const e = engineRef.current;
    const handleKeyDown = (ev: KeyboardEvent) => {
      e.keys[ev.code] = true;
      if (ev.code === 'ShiftLeft' || ev.code === 'ShiftRight') {
        e.players.forEach(p => p.isTransformed = !p.isTransformed);
      }
    };
    const handleKeyUp = (ev: KeyboardEvent) => { e.keys[ev.code] = false; };
    window.addEventListener('keydown', handleKeyDown); window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => { if (!e.isPaused) update(); draw(); animationId = requestAnimationFrame(loop); };

    const update = () => {
      e.frame++;
      const moveRight = e.keys['ArrowRight'] || e.keys['KeyD'];
      const moveLeft = e.keys['ArrowLeft'] || e.keys['KeyA'];
      const moveUp = e.keys['ArrowUp'] || e.keys['KeyW'];
      const firing = e.keys['Space'];

      const leader = e.players[0];
      if (!leader) { onDie(); return; }

      e.players.forEach((player, i) => {
        if (player.health <= 0) return;
        const stats = ROBOT_STATS[player.unit];
        const currentStats = player.isTransformed ? stats.alt : stats.robot;

        if (i === 0) {
          if (moveRight) { player.vel.x = currentStats.speed; player.facing = 1; }
          else if (moveLeft) { player.vel.x = -currentStats.speed; player.facing = -1; }
          else player.vel.x *= 0.8;
          if (moveUp && player.grounded) { player.vel.y = currentStats.jump; player.grounded = false; }
        } else {
          const targetX = leader.pos.x - (i * 40 * leader.facing);
          const dist = targetX - player.pos.x;
          if (Math.abs(dist) > 20) {
            player.vel.x = Math.sign(dist) * currentStats.speed * 0.9;
            player.facing = Math.sign(dist) || 1;
          } else player.vel.x *= 0.8;
          if (moveUp && player.grounded && leader.vel.y < -5) { player.vel.y = currentStats.jump; player.grounded = false; }
        }

        player.vel.y += GRAVITY;
        player.pos.x += player.vel.x; player.pos.y += player.vel.y;
        if (player.pos.y > GROUND_Y - player.height) { 
          player.pos.y = GROUND_Y - player.height; 
          player.vel.y = 0; 
          player.grounded = true; 
        }
        if (player.pos.x < 0) player.pos.x = 0;

        const fr = Math.max(5, currentStats.fireRate - e.upgrades.weaponTier * 2);
        if (firing && e.frame - player.lastShot > fr) {
          soundService.playShoot();
          e.bullets.push({ pos: { x: player.pos.x + 16, y: player.pos.y + 20 }, vel: { x: player.facing * 15, y: 0 }, width: 12, height: 4, owner: 'player', health: 1, maxHealth: 1, damage: 100, color: stats.color });
          player.lastShot = e.frame;
        }
        if (player.invulnerable > 0) player.invulnerable--;
      });

      for (let i = e.bullets.length - 1; i >= 0; i--) {
        const b = e.bullets[i]; b.pos.x += b.vel.x;
        if (b.owner === 'enemy') {
          e.players.forEach(p => {
            if (p.health > 0 && !p.invulnerable && b.pos.x < p.pos.x + p.width && b.pos.x + b.width > p.pos.x && b.pos.y < p.pos.y + p.height && b.pos.y + b.height > p.pos.y) {
              p.health -= 25; p.invulnerable = 40; e.bullets.splice(i, 1);
            }
          });
        }
        if (Math.abs(b.pos.x - leader.pos.x) > 1000) e.bullets.splice(i, 1);
      }

      let enemiesAlive = 0;
      e.enemies.forEach(en => {
        if (en.isDead) return;
        enemiesAlive++;
        en.pos.x += Math.sign(leader.pos.x - en.pos.x) * 0.5;
        if (Math.abs(en.pos.x - leader.pos.x) < 600 && e.frame - en.lastShot > 100) {
          e.bullets.push({ pos: { x: en.pos.x, y: en.pos.y + 20 }, vel: { x: Math.sign(leader.pos.x - en.pos.x) * 8, y: 0 }, width: 10, height: 4, owner: 'enemy', health: 1, maxHealth: 1, damage: 25, color: '#f00' });
          en.lastShot = e.frame;
        }
        e.bullets.forEach((b, bi) => {
          if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) {
            en.health -= b.damage || 100; if (en.health <= 0) en.isDead = true;
            e.bullets.splice(bi, 1);
          }
        });
      });

      if (e.frame % 15 === 0) setSquadStatus([...e.players]);
      if (enemiesAlive === 0) onWin();
      if (e.players.every(p => p.health <= 0)) onDie();

      e.cameraX = leader.pos.x - 200;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const leader = e.players[0];
      if (!leader) return;

      // Draw Enhanced Parallax Background
      drawParallax(ctx, e.frame, e.cameraX);

      ctx.save(); ctx.translate(-e.cameraX, 0);

      // Ground / Floor Floor
      ctx.fillStyle = '#080815'; ctx.fillRect(e.cameraX - 500, GROUND_Y + 48, CANVAS_WIDTH + 1000, 100);
      ctx.strokeStyle = '#00f3ff33';
      ctx.lineWidth = 1;
      const gridSpacing = 40;
      const startGrid = Math.floor((e.cameraX - 500) / gridSpacing) * gridSpacing;
      for (let gx = startGrid; gx < e.cameraX + CANVAS_WIDTH + 500; gx += gridSpacing) {
        ctx.beginPath();
        ctx.moveTo(gx, GROUND_Y + 48);
        ctx.lineTo(gx, CANVAS_HEIGHT);
        ctx.stroke();
      }
      ctx.fillStyle = '#101025'; ctx.fillRect(e.cameraX - 500, GROUND_Y + 46, CANVAS_WIDTH + 1000, 2);

      e.enemies.forEach(en => { if(!en.isDead) drawUnit(ctx, en.pos.x, en.pos.y, en.width, en.height, RobotUnit.SENTINEL, Math.sign(leader.pos.x - en.pos.x), e.frame, true, false, false, 1); });
      e.players.forEach(p => { if(p.health > 0) drawUnit(ctx, p.pos.x, p.pos.y, p.width, p.height, p.unit, p.facing, e.frame, false, p.invulnerable > 0, p.isTransformed, 1); });
      e.bullets.forEach(b => { ctx.fillStyle = b.color || '#fff'; ctx.fillRect(b.pos.x, b.pos.y, b.width, b.height); });
      ctx.restore();
    };
    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [onWin, onDie, upgrades]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden font-orbitron">
      <div className="absolute top-4 left-4 z-10 space-y-2 pointer-events-none">
        <div className="text-xs text-cyan-400 font-bold uppercase tracking-widest mb-2 border-b border-cyan-500/30 pb-1">Omnibot Squad Alpha</div>
        {squadStatus.map(p => (
          <div key={p.id} className={`bg-black/80 border p-2 rounded backdrop-blur-md transition-all ${p.health <= 0 ? 'border-red-900 opacity-40' : 'border-cyan-500/40 shadow-sm'}`}>
            <div className="flex justify-between items-center text-[10px] mb-1">
              <span className="font-bold" style={{ color: p.health > 0 ? ROBOT_STATS[p.unit].color : '#444' }}>{ROBOT_STATS[p.unit].name}</span>
              <span className="font-mono text-gray-400">{Math.max(0, Math.round(p.health))}%</span>
            </div>
            <div className="w-32 h-1.5 bg-gray-900 rounded-full overflow-hidden">
              <div className="h-full transition-all duration-300" style={{ width: `${(p.health / p.maxHealth) * 100}%`, backgroundColor: p.health < p.maxHealth * 0.3 ? '#ef4444' : ROBOT_STATS[p.unit].color }} />
            </div>
          </div>
        ))}
      </div>

      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full aspect-video shadow-2xl rounded-lg border-2 border-cyan-900/50" />

      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 pointer-events-none text-white/40 text-[9px] font-mono tracking-widest uppercase flex gap-10 bg-black/40 px-6 py-2 rounded-full border border-white/5">
        <span>WASD: Move/Jump</span><span>Space: Primary Fire</span><span>Shift: All Units Transform</span>
      </div>
    </div>
  );
};

export default GameView;

