                {levelNum === 5 && isUnlocked && <div className="absolute top-5 right-1 text-[6px] bg-red-900 text-red-200 px-1 font-orbitron uppercase">TANK-FORMER</div>}
                {levelNum === 20 && <div className="absolute bottom-1 right-1 text-[6px] bg-purple-900 text-purple-200 px-1 font-orbitron uppercase">BOSS</div>}
              </button>
            );
          })}
        </div>

        <div className="flex flex-col gap-6">
          <button 
            onClick={onBack}
            className="w-full py-4 bg-gray-900 hover:bg-gray-800 text-cyan-400 font-black border border-cyan-900 hover:border-cyan-400 transition-all uppercase font-orbitron tracking-widest text-lg shadow-[0_0_20px_rgba(6,182,212,0.1)] active:scale-[0.98]"
          >
            EXIT TO MAIN MENU
          </button>

          <div className="flex justify-center gap-6">
            <div className="flex items-center gap-2">
              <div className="w-3 h-3 bg-cyan-950 border border-cyan-800"></div>
              <span className="text-[8px] text-gray-400 font-orbitron uppercase">AVAILABLE</span>
            </div>
            <div className="flex items-center gap-2">
              <div className="w-3 h-3 bg-gray-950 border border-gray-900 opacity-40"></div>
              <span className="text-[8px] text-gray-400 font-orbitron uppercase">RESTRICTED</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

