import { GoogleGenAI, Type } from "@google/genai";
import { LevelInfo } from "../types";

const delay = (ms: number) => new Promise(res => setTimeout(res, ms));

async function callGeminiWithRetry(level: number, specialPrompt: string, retries = 2): Promise<any> {
  const currentAttempt = 3 - retries;

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Generate a short mission briefing for Level ${level} of a game called EarthBots. 
      The EarthBots are specialized defenders protecting the planet from a rogue machine uprising.
      ${specialPrompt || "The goal is to destroy hostiles in the sector."}
      Provide a cool title, threat level, and a 2-sentence description emphasizing the high-tech mechanical warfare.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            level: { type: Type.INTEGER },
            title: { type: Type.STRING },
            description: { type: Type.STRING },
            threatLevel: { type: Type.STRING },
            enemyType: { type: Type.STRING }
          },
          required: ["level", "title", "description", "threatLevel", "enemyType"]
        }
      }
    });

    if (!response.text) throw new Error("Empty response from AI");
    return JSON.parse(response.text);
  } catch (error: any) {
    const errorString = JSON.stringify(error).toLowerCase();
    const isQuotaError = 
      error?.status === 429 || 
      error?.message?.includes('429') || 
      errorString.includes('resource_exhausted') ||
      errorString.includes('quota');

    if (retries > 0 && isQuotaError) {
      const waitTime = Math.pow(2, currentAttempt) * 1000;
      await delay(waitTime);
      return callGeminiWithRetry(level, specialPrompt, retries - 1);
    }

    throw error;
  }
}

export const getLevelBriefing = async (level: number): Promise<LevelInfo> => {
  let specialPrompt = "";
  if (level === 5) specialPrompt = "EarthBots face a battalion of heavy 'Tank-formers' leveling the district.";
  if (level === 10) specialPrompt = "Gigantus Titan encounter. The rogue AI has sent its own combiner robot.";
  if (level === 20) specialPrompt = "FINAL SIEGE. EarthBots must stop a Cyber Dragon and a full Legion. Apocalypse scenario.";

  const fallback: LevelInfo = {
    level,
    title: level === 20 ? "Project Earthrise" : (level === 5 ? "Tank-former Breach" : (level === 10 ? "Colossus Conflict" : `Sector ${level} Cleanup`)),
    description: level === 5 
      ? "Massive heavy-tread units have breached the outer wall. Mobilize the EarthBot squad to halt their advance." 
      : (level === 20 ? "The Rogue Core has manifested. This is the end of the line for humanity. Combine and conquer or fall forever." : "Scouts report rogue hardware active in this sector. Neutralize all targets to secure the area."),
    threatLevel: level >= 20 ? "EXTINCTION" : (level >= 10 ? "Critical" : (level >= 5 ? "High" : "Moderate")),
    enemyType: level === 20 ? "Rogue Core Sovereign" : (level === 10 ? "Prototype Colossus" : (level === 5 ? "Siege Tanks" : "Rogue Hardware"))
  };

  try {
    return await callGeminiWithRetry(level, specialPrompt);
  } catch (error: any) {
    console.warn("Gemini service unavailable, using local EarthBot data.", error.message || error);
    return fallback;
  }
};

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const GROUND_Y = 350;

interface PlayerEntity {
  unit: RobotUnit;
  pos: { x: number; y: number };
  vel: { x: number; y: number };
  width: number;
  height: number;
  facing: number;
  grounded: boolean;
  lastShot: number;
  invulnerable: number;
  health: number;
  maxHealth: number;
  isTransformed: boolean;
  id: string;
}

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { name: "SENTINEL", color: '#00f3ff', hpMult: 1.0, robot: { speed: 4, jump: -11, fireRate: 15 }, alt: { speed: 8, jump: -5, fireRate: 25, type: 'Police Car' }},
  [RobotUnit.STRIKER]: { name: "STRIKER", color: '#fbbf24', hpMult: 0.8, robot: { speed: 6, jump: -10, fireRate: 10 }, alt: { speed: 12, jump: -4, fireRate: 20, type: 'Bike' }},
  [RobotUnit.FALCON]: { name: "FALCON", color: '#22d3ee', hpMult: 0.7, robot: { speed: 5, jump: -10, fireRate: 12 }, alt: { speed: 7, jump: -7, fireRate: 15, type: 'Jet' }},
  [RobotUnit.TITAN]: { name: "TITAN", color: '#ef4444', hpMult: 2.5, robot: { speed: 2.5, jump: -12, fireRate: 30 }, alt: { speed: 4, jump: 0, fireRate: 20, type: 'Tank' }},
  [RobotUnit.SPECTER]: { name: "SPECTER", color: '#a855f7', hpMult: 0.6, robot: { speed: 5, jump: -11, fireRate: 20 }, alt: { speed: 6, jump: -14, fireRate: 40, type: 'Ambulance' }},
  [RobotUnit.VANGUARD]: { name: "VANGUARD", color: '#10b981', hpMult: 2.0, robot: { speed: 3.5, jump: -10, fireRate: 25 }, alt: { speed: 6, jump: -4, fireRate: 30, type: 'Fire Truck' }},
  [RobotUnit.NIGHTSHADE]: { name: "NIGHTSHADE", color: '#6366f1', hpMult: 0.9, robot: { speed: 7, jump: -13, fireRate: 12 }, alt: { speed: 10, jump: -6, fireRate: 18, type: 'Cyber Tiger' }},
  [RobotUnit.BLAZE]: { name: "BLAZE", color: '#f97316', hpMult: 1.2, robot: { speed: 4.5, jump: -11, fireRate: 18 }, alt: { speed: 12, jump: -5, fireRate: 15, type: 'Canon Race Car' }},
  [RobotUnit.GLITCH]: { name: "GLITCH", color: '#ec4899', hpMult: 1.0, robot: { speed: 5, jump: -12, fireRate: 14 }, alt: { speed: 10, jump: -12, fireRate: 16, type: 'Flying Car' }},
  [RobotUnit.OMEGA]: { name: "OMEGA", color: '#ffffff', hpMult: 3.0, robot: { speed: 6, jump: -14, fireRate: 10 }, alt: { speed: 8, jump: -10, fireRate: 10, type: 'Combat Blimp' }},
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [squadStatus, setSquadStatus] = useState<PlayerEntity[]>([]);
  const [isCombinedUI, setIsCombinedUI] = useState(false);

  const engineRef = useRef({
    players: [] as PlayerEntity[],
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    cameraY: 0,
    zoom: 1.0,
    isPaused: isPaused,
    level: level,
    upgrades: upgrades,
    isCombined: false,
    combinedHealth: 0,
    combinedMaxHealth: 0,
  });

  useEffect(() => { 
    engineRef.current.isPaused = isPaused; 
    engineRef.current.level = level;
    engineRef.current.upgrades = upgrades;
  }, [isPaused, level, upgrades]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff66');
    grad.addColorStop(1, '#000000aa');
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.6)';
    ctx.lineWidth = 1;
    ctx.stroke();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, alpha = 1, sizeMult = 1) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8 * sizeMult;
    const armSwing = Math.cos(time) * 10 * sizeMult;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(sizeMult, sizeMult);

    drawMechanicalPart(ctx, -12, -18, 24, 28, color, 4);
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? '#ff0000' : '#00f3ff'; ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);
    ctx.restore();
  };

  const drawCombiner = (ctx: CanvasRenderingContext2D, color: string, frame: number, alpha = 1) => {
    ctx.save();
    ctx.translate(0, -30);
    const combineColor = '#facc15'; 
    drawHumanoid(ctx, combineColor, frame, false, alpha, 2.5);

    // Core glow
    const coreGlow = 0.4 + Math.sin(frame * 0.2) * 0.3;
    ctx.beginPath();
    ctx.arc(0, -10, 8, 0, Math.PI * 2);
    ctx.fillStyle = `rgba(0, 243, 255, ${coreGlow})`;
    ctx.fill();

    // Electric arcs
    if (frame % 30 < 5) {
      ctx.strokeStyle = '#00f3ff';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(-40, -80);
      ctx.lineTo(40, -10);
      ctx.stroke();
    }

    ctx.globalAlpha = 0.2 + Math.sin(frame * 0.1) * 0.1;
    ctx.strokeStyle = '#facc15';
    ctx.lineWidth = 2;
    ctx.strokeRect(-35, -90, 70, 130);
    ctx.restore();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, color: string, frame: number, alpha = 1) => {
    ctx.save(); ctx.globalAlpha = alpha;
    switch(unit) {
      case RobotUnit.SENTINEL:
        drawMechanicalPart(ctx, -28, -10, 56, 20, color, 8);
        drawMechanicalPart(ctx, -18, -22, 36, 14, '#111', 4);
        ctx.fillStyle = frame % 10 < 5 ? '#ff0000' : '#0000ff'; ctx.fillRect(-6, -24, 12, 4);
        ctx.fillStyle = '#111'; ctx.beginPath(); ctx.arc(-18, 12, 8, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.arc(18, 12, 8, 0, Math.PI * 2); ctx.fill();
        break;
      case RobotUnit.OMEGA:
        const bSwing = Math.sin(frame * 0.05) * 5; ctx.translate(0, bSwing);
        ctx.save(); ctx.scale(1.2, 0.8); drawMechanicalPart(ctx, -40, -40, 80, 80, color, 50); ctx.restore();
        ctx.save(); ctx.translate(0, -35); drawMechanicalPart(ctx, -8, -10, 16, 10, '#222', 2); drawMechanicalPart(ctx, 0, -8, 30, 6, '#555', 1); ctx.restore();
        break;
      default:
        drawMechanicalPart(ctx, -25, -12, 50, 24, color, 6);
        drawMechanicalPart(ctx, -10, -22, 20, 10, '#333', 2);
        break;
    }
    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy: boolean, invulnerable: boolean, transformed: boolean, alpha: number, isCombiner = false) => {
    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    ctx.scale(facing < 0 ? -1 : 1, 1);
    const drawAlpha = invulnerable ? (0.5 + Math.sin(frame * 0.5) * 0.3) * alpha : alpha;
    const color = isEnemy ? '#ff0055' : ROBOT_STATS[unit].color;

    if (isCombiner) {
      drawCombiner(ctx, color, frame, drawAlpha);
    } else if (transformed) {
      drawAltMode(ctx, unit, color, frame, drawAlpha);
    } else {
      drawHumanoid(ctx, color, frame, isEnemy, drawAlpha);
    }
    ctx.restore();
  };

  const createPlayer = (unit: RobotUnit, x: number, y: number): PlayerEntity => {
    const stats = ROBOT_STATS[unit];
    const baseHP = 100 + (engineRef.current.upgrades.robotTier * 50);
    return {
      id: Math.random().toString(36).substr(2, 9),
      unit,
      pos: { x, y: GROUND_Y - 48 },
      vel: { x: 0, y: 0 },
      width: 32,
      height: 48,
      facing: 1,
      grounded: true,
      lastShot: 0,
      invulnerable: 0,
      health: baseHP * stats.hpMult,
      maxHealth: baseHP * stats.hpMult,
      isTransformed: false
    };
  };

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    e.frame = 0; e.cameraX = 0; e.cameraY = 0; e.bullets = []; e.isCombined = false;
    const players = upgrades.unlockedUnits.map((unit, i) => createPlayer(unit, 100 - i * 40, GROUND_Y - 48));
    e.players = players;

    const enemies: Enemy[] = [];
    const enemyCount = level === 20 ? 15 : 5;
    for (let i = 0; i < enemyCount; i++) {
      const isBoss = i === enemyCount - 1;
      const eh = isBoss ? 2000 + level * 500 : 100;
      enemies.push({ id: i, pos: { x: 800 + i * 500, y: GROUND_Y - 72 }, vel: { x: 0, y: 0 }, width: isBoss ? 64 : 48, height: isBoss ? 72 : 72, health: eh, maxHealth: eh, isDead: false, type: isBoss ? 'boss' : 'grunt', lastShot: 0 });
    }
    e.enemies = enemies;
    setSquadStatus([...players]);
    setIsCombinedUI(false);
  }, [level, upgrades]);

  useEffect(() => { resetLevel(); }, [resetLevel]);

  const drawParallax = (ctx: CanvasRenderingContext2D, frame: number, camX: number) => {
    ctx.fillStyle = '#020208'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    const farCamX = camX * 0.05;
    for (let i = 0; i < 60; i++) {
      const sx = (Math.sin(i * 123.4) * 20000 - farCamX) % CANVAS_WIDTH;
      const sy = (Math.cos(i * 456.7) * 20000) % (CANVAS_HEIGHT - 100);
      const starX = sx < 0 ? sx + CANVAS_WIDTH : sx;
      const starY = sy < 0 ? sy + (CANVAS_HEIGHT - 100) : sy;
      ctx.fillStyle = i % 15 === 0 ? '#00f3ff88' : '#ffffff22'; ctx.fillRect(starX, starY, 1.2, 1.2);
    }
    const veryFarTowersX = camX * 0.15; ctx.fillStyle = '#0a0a1a';
    for (let i = 0; i < 12; i++) {
      const w = 40 + Math.abs(Math.sin(i * 11)) * 30; const h = 80 + Math.abs(Math.cos(i * 5)) * 120;
      const x = ((i * 150) - veryFarTowersX) % (CANVAS_WIDTH + w); const realX = x < -w ? x + (CANVAS_WIDTH + 150 + w) : x;
      ctx.fillRect(realX, GROUND_Y - h + 50, w, h);
    }
    const midCamX = camX * 0.35; ctx.fillStyle = '#121228';
    for (let i = 0; i < 10; i++) {
      const w = 80 + Math.abs(Math.sin(i * 1.5)) * 40; const h = 100 + Math.abs(Math.cos(i * 2.1)) * 150;
      const x = ((i * 250) - midCamX) % (CANVAS_WIDTH + w); const realX = x < -w ? x + (CANVAS_WIDTH + 250 + w) : x;
      ctx.fillRect(realX, GROUND_Y - h + 50, w, h); ctx.fillStyle = '#00f3ff11'; ctx.fillRect(realX + 5, GROUND_Y - h + 60, w - 10, 5); ctx.fillStyle = '#121228';
    }
    const nearCamX = camX * 0.65; ctx.fillStyle = '#1a1a35';
    for (let i = 0; i < 8; i++) {
      const w = 120; const h = 50 + Math.abs(Math.sin(i * 3.3)) * 40;
      const x = ((i * 400) - nearCamX) % (CANVAS_WIDTH + w); const realX = x < -w ? x + (CANVAS_WIDTH + 400 + w) : x;
      ctx.fillRect(realX, GROUND_Y - h + 50, w, h); ctx.strokeStyle = '#00f3ff11'; ctx.strokeRect(realX, GROUND_Y - h + 50, w, h);
    }
  };

  useEffect(() => {
    const e = engineRef.current;
    const handleKeyDown = (ev: KeyboardEvent) => {
      e.keys[ev.code] = true;
      if (ev.code === 'ShiftLeft' || ev.code === 'ShiftRight') {
        if (!e.isCombined) {
          e.players.forEach(p => p.isTransformed = !p.isTransformed);
        }
      }
      if (ev.code === 'KeyC') {
        if (e.isCombined) {
          e.isCombined = false;
          setIsCombinedUI(false);
          const hPer = e.combinedHealth / e.players.length;
          e.players.forEach(p => {
             p.health = Math.min(p.maxHealth, hPer);
             p.width = 32;
             p.height = 48;
          });
          e.players.forEach((p, i) => { p.pos.x = e.players[0].pos.x - i * 40; p.pos.y = e.players[0].pos.y; });
        } else if (upgrades.unlockedUnits.length >= 5) {
          e.isCombined = true;
          setIsCombinedUI(true);
          e.combinedMaxHealth = e.players.reduce((sum, p) => sum + p.maxHealth, 0) * 1.2;
          e.combinedHealth = e.players.reduce((sum, p) => sum + p.health, 0) * 1.2;
          e.players[0].width = 64; e.players[0].height = 96;
        }
      }
    };
    const handleKeyUp = (ev: KeyboardEvent) => { e.keys[ev.code] = false; };
    window.addEventListener('keydown', handleKeyDown); window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => { if (!e.isPaused) update(); draw(); animationId = requestAnimationFrame(loop); };

    const update = () => {
      e.frame++;
      const moveRight = e.keys['ArrowRight'] || e.keys['KeyD'];
      const moveLeft = e.keys['ArrowLeft'] || e.keys['KeyA'];
      const moveUp = e.keys['ArrowUp'] || e.keys['KeyW'];
      const firing = e.keys['Space'];

      const leader = e.players[0];
      if (!leader) { onDie(); return; }

      if (e.isCombined) {
        const stats = { speed: 4, jump: -15, fireRate: 6 };
        if (moveRight) { leader.vel.x = stats.speed; leader.facing = 1; }
        else if (moveLeft) { leader.vel.x = -stats.speed; leader.facing = -1; }
        else leader.vel.x *= 0.85;

        if (moveUp && leader.grounded) { leader.vel.y = stats.jump; leader.grounded = false; }
        leader.vel.y += GRAVITY;
        leader.pos.x += leader.vel.x; leader.pos.y += leader.vel.y;

        if (leader.pos.y > GROUND_Y - leader.height) { 
          leader.pos.y = GROUND_Y - leader.height; 
          leader.vel.y = 0; leader.grounded = true; 
        }
        if (leader.pos.x < 0) leader.pos.x = 0;

        if (firing && e.frame - leader.lastShot > stats.fireRate) {
          soundService.playShoot();
          for(let i=-1; i<=1; i++) {
            e.bullets.push({ pos: { x: leader.pos.x + 32, y: leader.pos.y + 40 + (i*15) }, vel: { x: leader.facing * 20, y: i * 1.5 }, width: 25, height: 8, owner: 'player', health: 1, maxHealth: 1, damage: 180, color: '#facc15' });
          }
          leader.lastShot = e.frame;
        }
        if (leader.invulnerable > 0) leader.invulnerable--;
      } else {
        e.players.forEach((player, i) => {
          if (player.health <= 0) return;
          const stats = ROBOT_STATS[player.unit];
          const currentStats = player.isTransformed ? stats.alt : stats.robot;

          if (i === 0) {
            if (moveRight) { player.vel.x = currentStats.speed; player.facing = 1; }
            else if (moveLeft) { player.vel.x = -currentStats.speed; player.facing = -1; }
            else player.vel.x *= 0.8;
            if (moveUp && player.grounded) { player.vel.y = currentStats.jump; player.grounded = false; }
          } else {
            const targetX = leader.pos.x - (i * 45 * leader.facing);
            const dist = targetX - player.pos.x;
            if (Math.abs(dist) > 20) {
              player.vel.x = Math.sign(dist) * currentStats.speed * 0.9;
              player.facing = Math.sign(dist) || 1;
            } else player.vel.x *= 0.8;
            if (moveUp && player.grounded && leader.vel.y < -5) { player.vel.y = currentStats.jump; player.grounded = false; }
          }

          player.vel.y += GRAVITY;
          player.pos.x += player.vel.x; player.pos.y += player.vel.y;
          if (player.pos.y > GROUND_Y - player.height) { player.pos.y = GROUND_Y - player.height; player.vel.y = 0; player.grounded = true; }
          if (player.pos.x < 0) player.pos.x = 0;

          const fr = Math.max(5, currentStats.fireRate - e.upgrades.weaponTier * 2);
          if (firing && e.frame - player.lastShot > fr) {
            soundService.playShoot();
            e.bullets.push({ pos: { x: player.pos.x + 16, y: player.pos.y + 20 }, vel: { x: player.facing * 15, y: 0 }, width: 12, height: 4, owner: 'player', health: 1, maxHealth: 1, damage: 100, color: stats.color });
            player.lastShot = e.frame;
          }
          if (player.invulnerable > 0) player.invulnerable--;
        });
      }

      for (let i = e.bullets.length - 1; i >= 0; i--) {
        const b = e.bullets[i]; b.pos.x += b.vel.x; b.pos.y += b.vel.y || 0;
        if (b.owner === 'enemy') {
          if (e.isCombined) {
            if (!leader.invulnerable && b.pos.x < leader.pos.x + leader.width && b.pos.x + b.width > leader.pos.x && b.pos.y < leader.pos.y + leader.height && b.pos.y + b.height > leader.pos.y) {
              e.combinedHealth -= 60; leader.invulnerable = 30; e.bullets.splice(i, 1);
              if (e.combinedHealth <= 0) onDie();
            }
          } else {
            e.players.forEach(p => {
              if (p.health > 0 && !p.invulnerable && b.pos.x < p.pos.x + p.width && b.pos.x + b.width > p.pos.x && b.pos.y < p.pos.y + p.height && b.pos.y + b.height > p.pos.y) {
                p.health -= 25; p.invulnerable = 40; e.bullets.splice(i, 1);
              }
            });
          }
        }
        if (Math.abs(b.pos.x - (leader.pos.x)) > 1000) e.bullets.splice(i, 1);
      }

      let enemiesAlive = 0;
      e.enemies.forEach(en => {
        if (en.isDead) return;
        enemiesAlive++;
        en.pos.x += Math.sign(leader.pos.x - en.pos.x) * 0.5;
        if (Math.abs(en.pos.x - leader.pos.x) < 600 && e.frame - en.lastShot > 100) {
          e.bullets.push({ pos: { x: en.pos.x, y: en.pos.y + 20 }, vel: { x: Math.sign(leader.pos.x - en.pos.x) * 8, y: 0 }, width: 10, height: 4, owner: 'enemy', health: 1, maxHealth: 1, damage: 25, color: '#f00' });
          en.lastShot = e.frame;
        }
        e.bullets.forEach((b, bi) => {
          if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) {
            en.health -= b.damage || 100; if (en.health <= 0) en.isDead = true;
            e.bullets.splice(bi, 1);
          }
        });
      });

      if (e.frame % 15 === 0) setSquadStatus([...e.players]);
      if (enemiesAlive === 0) onWin();
      if (!e.isCombined && e.players.every(p => p.health <= 0)) onDie();

      e.cameraX = leader.pos.x - 200;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const leader = e.players[0]; if (!leader) return;

      drawParallax(ctx, e.frame, e.cameraX);
      ctx.save(); ctx.translate(-e.cameraX, 0);

      ctx.fillStyle = '#080815'; ctx.fillRect(e.cameraX - 500, GROUND_Y + 48, CANVAS_WIDTH + 1000, 100);
      ctx.strokeStyle = '#00f3ff22'; ctx.lineWidth = 1;
      const gridSpacing = 40; const startGrid = Math.floor((e.cameraX - 500) / gridSpacing) * gridSpacing;
      for (let gx = startGrid; gx < e.cameraX + CANVAS_WIDTH + 500; gx += gridSpacing) {
        ctx.beginPath(); ctx.moveTo(gx, GROUND_Y + 48); ctx.lineTo(gx, CANVAS_HEIGHT); ctx.stroke();
      }
      ctx.fillStyle = '#1a1a35'; ctx.fillRect(e.cameraX - 500, GROUND_Y + 46, CANVAS_WIDTH + 1000, 2);

      e.enemies.forEach(en => { if(!en.isDead) drawUnit(ctx, en.pos.x, en.pos.y, en.width, en.height, RobotUnit.SENTINEL, Math.sign(leader.pos.x - en.pos.x), e.frame, true, false, false, 1); });

      if (e.isCombined) {
        drawUnit(ctx, leader.pos.x, leader.pos.y, leader.width, leader.height, leader.unit, leader.facing, e.frame, false, leader.invulnerable > 0, false, 1, true);
      } else {
        e.players.forEach(p => { if(p.health > 0) drawUnit(ctx, p.pos.x, p.pos.y, p.width, p.height, p.unit, p.facing, e.frame, false, p.invulnerable > 0, p.isTransformed, 1); });
      }

      e.bullets.forEach(b => { 
        ctx.fillStyle = b.color || '#fff'; 
        ctx.fillRect(b.pos.x, b.pos.y, b.width, b.height);
        if (b.damage && b.damage > 150) {
           ctx.strokeStyle = '#fff'; ctx.lineWidth = 1; ctx.strokeRect(b.pos.x, b.pos.y, b.width, b.height);
        }
      });
      ctx.restore();
    };
    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [onWin, onDie, upgrades]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden font-orbitron">
      {/* HUD: Combiner Warning */}
      {!isCombinedUI && upgrades.unlockedUnits.length >= 5 && (
        <div className="absolute top-1/4 right-8 flex flex-col items-end">
          <div className="animate-pulse bg-emerald-600/20 border border-emerald-500 p-3 text-[12px] text-emerald-400 font-bold uppercase tracking-widest shadow-[0_0_15px_rgba(16,185,129,0.4)]">
            COMBINER LINK READY
          </div>
          <div className="text-[10px] text-emerald-600 mt-2 font-black uppercase tracking-widest">Press [C] To Merge Squad</div>
        </div>
      )}

      {/* Squad Status Sidebar */}
      <div className="absolute top-4 left-4 z-10 space-y-2 pointer-events-none">
        <div className="text-[10px] text-cyan-400 font-bold uppercase tracking-[0.2em] mb-3 border-b border-cyan-500/30 pb-1 flex items-center gap-2">
          <div className="w-2 h-2 bg-cyan-400 rounded-full animate-ping"></div>
          {isCombinedUI ? "MEGA EARTHBOT ONLINE" : "EarthBot Active Squad"}
        </div>
        {isCombinedUI ? (
          <div className="bg-yellow-950/80 border border-yellow-500 p-4 rounded backdrop-blur-md shadow-[0_0_30px_rgba(250,204,21,0.3)] border-b-4 border-r-4">
            <div className="flex justify-between items-center text-xs mb-1">
              <span className="font-black text-yellow-400 italic tracking-widest">GIGANTUS COMBINER</span>
              <span className="font-mono text-yellow-200 font-bold">{Math.max(0, Math.round((engineRef.current.combinedHealth / engineRef.current.combinedMaxHealth) * 100))}%</span>
            </div>
            <div className="w-56 h-4 bg-gray-950 rounded border border-yellow-600/30 relative overflow-hidden">
               <div className="absolute inset-0 bg-yellow-400/10 animate-pulse"></div>
              <div className="h-full bg-gradient-to-r from-yellow-700 to-yellow-400 transition-all duration-300 relative" style={{ width: `${(engineRef.current.combinedHealth / engineRef.current.combinedMaxHealth) * 100}%` }}>
                 <div className="absolute top-0 right-0 w-2 h-full bg-white opacity-40"></div>
              </div>
            </div>
            <div className="mt-2 text-[8px] text-yellow-600 font-bold uppercase tracking-widest text-right">UNLEASH POWER MODE</div>
          </div>
        ) : (
          squadStatus.map(p => (
            <div key={p.id} className={`bg-black/80 border p-2 rounded backdrop-blur-md transition-all ${p.health <= 0 ? 'border-red-900 opacity-40' : 'border-cyan-500/30 shadow-sm'}`}>
              <div className="flex justify-between items-center text-[10px] mb-1">
                <span className="font-black italic" style={{ color: p.health > 0 ? ROBOT_STATS[p.unit].color : '#444' }}>{ROBOT_STATS[p.unit].name}</span>
                <span className="font-mono text-gray-500">{Math.max(0, Math.round(p.health))}%</span>
              </div>
              <div className="w-36 h-1.5 bg-gray-900 rounded overflow-hidden">
                <div className="h-full transition-all duration-300" style={{ width: `${(p.health / p.maxHealth) * 100}%`, backgroundColor: p.health < p.maxHealth * 0.3 ? '#ef4444' : ROBOT_STATS[p.unit].color }} />
              </div>
            </div>
          ))
        )}
      </div>

      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full aspect-video shadow-2xl rounded-lg border-2 border-cyan-900/50" />

      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 pointer-events-none text-white/40 text-[9px] font-mono tracking-widest uppercase flex gap-10 bg-black/40 px-8 py-3 rounded-full border border-white/5 backdrop-blur-sm">
        <span className="hover:text-white transition-colors">WASD: MOVE</span>
        <span className="hover:text-white transition-colors">SPACE: FIRE</span>
        <span className="hover:text-white transition-colors">SHIFT: TRANSFORM</span>
        <span className={`${upgrades.unlockedUnits.length >= 5 ? 'text-emerald-400' : 'text-gray-600'}`}>C: COMBINE (5+)</span>
      </div>
    </div>
  );
};

