import React from 'react';
import { LevelInfo } from '../types';

interface BriefingProps {
  briefing: LevelInfo;
  isLoading: boolean;
  onConfirm: () => void;
}

const Briefing: React.FC<BriefingProps> = ({ briefing, isLoading, onConfirm }) => {
  if (isLoading) {
    return (
      <div className="h-full w-full flex flex-col items-center justify-center bg-black">
        <div className="w-16 h-16 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin mb-4"></div>
        <p className="text-cyan-400 animate-pulse font-mono tracking-widest uppercase">Establishing Secure Uplink...</p>
        <p className="text-gray-600 text-[10px] mt-2 font-mono uppercase">Bypassing local firewalls... [Attempting sync]</p>
      </div>
    );
  }

  return (
    <div className="h-full w-full flex flex-col items-center justify-start bg-gray-950 p-6 py-12 overflow-y-auto">
      <div className="max-w-lg w-full bg-gray-900 border border-cyan-900 p-8 relative overflow-hidden shadow-2xl">
        <div className="absolute top-0 right-0 p-2 text-[8px] text-cyan-800 font-mono">SECURE_CHANNEL_v4.2</div>

        <div className="mb-6">
          <h3 className="text-cyan-600 font-bold mb-1 uppercase tracking-tighter font-orbitron">Mission {briefing.level}</h3>
          <h2 className="text-3xl text-white font-black uppercase tracking-tight font-orbitron">{briefing.title}</h2>
        </div>

        <div className="space-y-4 text-gray-300 font-medium">
          <div className="flex justify-between items-center bg-gray-950 p-2 border-l-2 border-red-600">
            <span className="text-red-400 text-xs uppercase font-bold">Threat Level</span>
            <span className="text-white font-bold font-mono">{briefing.threatLevel}</span>
          </div>

          <div className="flex justify-between items-center bg-gray-950 p-2 border-l-2 border-cyan-600">
            <span className="text-cyan-400 text-xs uppercase font-bold">Hostile Type</span>
            <span className="text-white font-bold font-mono">{briefing.enemyType}</span>
          </div>

          <div className="p-4 bg-gray-950 rounded italic text-sm border border-gray-800 leading-relaxed shadow-inner">
            "{briefing.description}"
          </div>
        </div>

        <div className="mt-8 flex flex-col space-y-2">
          <div className="text-[10px] text-gray-600 uppercase text-center mb-2 font-mono tracking-tighter">Primary Objective: Eliminate All High-Value Rogue Units</div>
          <button 
            onClick={onConfirm}
            className="w-full py-4 bg-cyan-600 hover:bg-cyan-500 text-white font-bold text-xl transition-all border-b-4 border-cyan-900 shadow-[0_0_20px_rgba(6,182,212,0.2)] uppercase font-orbitron"
          >
            Engage Mission
          </button>
        </div>
      </div>
    </div>
  );
};

export default Briefing;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 450;
const GRAVITY = 0.5;
const GROUND_Y = 350;

interface PlayerEntity {
  unit: RobotUnit;
  pos: { x: number; y: number };
  vel: { x: number; y: number };
  width: number;
  height: number;
  facing: number;
  grounded: boolean;
  lastShot: number;
  invulnerable: number;
  health: number;
  maxHealth: number;
  isTransformed: boolean;
  id: string;
}

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { name: "SENTINEL", color: '#00f3ff', hpMult: 1.0, robot: { speed: 4, jump: -11, fireRate: 15 }, alt: { speed: 8, jump: -5, fireRate: 25, type: 'Police Car' }},
  [RobotUnit.STRIKER]: { name: "STRIKER", color: '#fbbf24', hpMult: 0.8, robot: { speed: 6, jump: -10, fireRate: 10 }, alt: { speed: 12, jump: -4, fireRate: 20, type: 'Bike' }},
  [RobotUnit.FALCON]: { name: "FALCON", color: '#22d3ee', hpMult: 0.7, robot: { speed: 5, jump: -10, fireRate: 12 }, alt: { speed: 7, jump: -7, fireRate: 15, type: 'Jet' }},
  [RobotUnit.TITAN]: { name: "TITAN", color: '#ef4444', hpMult: 2.5, robot: { speed: 2.5, jump: -12, fireRate: 30 }, alt: { speed: 4, jump: 0, fireRate: 20, type: 'Tank' }},
  [RobotUnit.SPECTER]: { name: "SPECTER", color: '#a855f7', hpMult: 0.6, robot: { speed: 5, jump: -11, fireRate: 20 }, alt: { speed: 6, jump: -14, fireRate: 40, type: 'Ambulance' }},
  [RobotUnit.VANGUARD]: { name: "VANGUARD", color: '#10b981', hpMult: 2.0, robot: { speed: 3.5, jump: -10, fireRate: 25 }, alt: { speed: 6, jump: -4, fireRate: 30, type: 'Fire Truck' }},
  [RobotUnit.NIGHTSHADE]: { name: "NIGHTSHADE", color: '#6366f1', hpMult: 0.9, robot: { speed: 7, jump: -13, fireRate: 12 }, alt: { speed: 10, jump: -6, fireRate: 18, type: 'Cyber Tiger' }},
  [RobotUnit.BLAZE]: { name: "BLAZE", color: '#f97316', hpMult: 1.2, robot: { speed: 4.5, jump: -11, fireRate: 18 }, alt: { speed: 12, jump: -5, fireRate: 15, type: 'Canon Race Car' }},
  [RobotUnit.GLITCH]: { name: "GLITCH", color: '#ec4899', hpMult: 1.0, robot: { speed: 5, jump: -12, fireRate: 14 }, alt: { speed: 10, jump: -12, fireRate: 16, type: 'Flying Car' }},
  [RobotUnit.OMEGA]: { name: "OMEGA", color: '#ffffff', hpMult: 3.0, robot: { speed: 6, jump: -14, fireRate: 10 }, alt: { speed: 8, jump: -10, fireRate: 10, type: 'Combat Blimp' }},
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isCombinedUI, setIsCombinedUI] = useState(false);

  const engineRef = useRef({
    players: [] as PlayerEntity[],
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    cameraY: 0,
    isPaused: isPaused,
    level: level,
    upgrades: upgrades,
    isCombined: false,
    combinedHealth: 0,
    combinedMaxHealth: 0,
  });

  useEffect(() => { 
    engineRef.current.isPaused = isPaused; 
    engineRef.current.level = level;
    engineRef.current.upgrades = upgrades;
  }, [isPaused, level, upgrades]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff66');
    grad.addColorStop(1, '#000000aa');
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.6)';
    ctx.lineWidth = 1;
    ctx.stroke();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, alpha = 1, sizeMult = 1) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8 * sizeMult;
    const armSwing = Math.cos(time) * 10 * sizeMult;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(sizeMult, sizeMult);
    drawMechanicalPart(ctx, -12, -18, 24, 28, color, 4);
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? '#ff0000' : '#00f3ff'; ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);
    ctx.restore();
  };

  const drawCombiner = (ctx: CanvasRenderingContext2D, color: string, frame: number, alpha = 1) => {
    ctx.save();
    ctx.translate(0, -30);
    drawHumanoid(ctx, '#facc15', frame, false, alpha, 2.5);
    const coreGlow = 0.4 + Math.sin(frame * 0.2) * 0.3;
    ctx.beginPath(); ctx.arc(0, -10, 8, 0, Math.PI * 2); ctx.fillStyle = `rgba(0, 243, 255, ${coreGlow})`; ctx.fill();
    if (frame % 30 < 5) {
      ctx.strokeStyle = '#00f3ff'; ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(-40, -80); ctx.lineTo(40, -10); ctx.stroke();
    }
    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy: boolean, invulnerable: boolean, transformed: boolean, alpha: number, isCombiner = false) => {
    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    ctx.scale(facing < 0 ? -1 : 1, 1);
    const drawAlpha = invulnerable ? (0.5 + Math.sin(frame * 0.5) * 0.3) * alpha : alpha;
    const color = isEnemy ? '#ff0055' : ROBOT_STATS[unit].color;
    if (isCombiner) drawCombiner(ctx, color, frame, drawAlpha);
    else if (transformed) {
       ctx.save(); ctx.globalAlpha = drawAlpha;
       drawMechanicalPart(ctx, -25, -12, 50, 24, color, 6);
       drawMechanicalPart(ctx, -10, -22, 20, 10, '#333', 2);
       ctx.restore();
    }
    else drawHumanoid(ctx, color, frame, isEnemy, drawAlpha);
    ctx.restore();
  };

  const createPlayer = (unit: RobotUnit, x: number, y: number): PlayerEntity => {
    const stats = ROBOT_STATS[unit];
    const baseHP = 100 + (engineRef.current.upgrades.robotTier * 50);
    return { id: Math.random().toString(36).substr(2, 9), unit, pos: { x, y: GROUND_Y - 48 }, vel: { x: 0, y: 0 }, width: 32, height: 48, facing: 1, grounded: true, lastShot: 0, invulnerable: 0, health: baseHP * stats.hpMult, maxHealth: baseHP * stats.hpMult, isTransformed: false };
  };

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    e.frame = 0; e.cameraX = 0; e.cameraY = 0; e.bullets = []; e.isCombined = false;
    e.players = upgrades.unlockedUnits.map((unit, i) => createPlayer(unit, 100 - i * 45, GROUND_Y - 48));
    const enemyCount = level === 20 ? 15 : 5;
    e.enemies = Array.from({ length: enemyCount }, (_, i) => ({ id: i, pos: { x: 800 + i * 500, y: GROUND_Y - 72 }, vel: { x: 0, y: 0 }, width: 48, height: 72, health: 100, maxHealth: 100, isDead: false, type: 'grunt', lastShot: 0 }));
    setIsCombinedUI(false);
  }, [level, upgrades]);

  useEffect(() => { resetLevel(); }, [resetLevel]);

  const drawHUD = (ctx: CanvasRenderingContext2D, e: any) => {
    ctx.save();
    // Offset HUD slightly further from edges (20, 20) instead of (10, 10)
    const hudX = 20;
    const hudY = 20;
    const hudW = 220;
    const hudH = e.isCombined ? 60 : e.players.length * 28 + 20;

    // Background for HUD area
    ctx.fillStyle = 'rgba(0, 0, 0, 0.6)';
    ctx.fillRect(hudX, hudY, hudW, hudH);
    ctx.strokeStyle = 'rgba(0, 243, 255, 0.5)';
    ctx.lineWidth = 1;
    ctx.strokeRect(hudX, hudY, hudW, hudH);

    ctx.font = 'bold 10px Orbitron';
    ctx.fillStyle = '#00f3ff';
    ctx.fillText(e.isCombined ? "MEGA EARTHBOT ONLINE" : "SQUAD ALPHA STATUS", hudX + 10, hudY + 15);

    if (e.isCombined) {
      const hRatio = Math.max(0, e.combinedHealth / e.combinedMaxHealth);
      ctx.fillStyle = '#facc15';
      ctx.fillText("COMBINER HP", hudX + 10, hudY + 30);
      ctx.fillStyle = '#111';
      ctx.fillRect(hudX + 10, hudY + 35, 180, 8);
      ctx.fillStyle = '#facc15';
      ctx.fillRect(hudX + 10, hudY + 35, 180 * hRatio, 8);
    } else {
      e.players.forEach((p: PlayerEntity, i: number) => {
        const stats = ROBOT_STATS[p.unit];
        const hRatio = Math.max(0, p.health / p.maxHealth);
        const y = hudY + 30 + i * 28;
        ctx.fillStyle = p.health > 0 ? stats.color : '#444';
        ctx.fillText(stats.name, hudX + 10, y);
        ctx.fillStyle = '#111';
        ctx.fillRect(hudX + 10, y + 5, 120, 4);
        ctx.fillStyle = p.health > 0 ? stats.color : '#222';
        ctx.fillRect(hudX + 10, y + 5, 120 * hRatio, 4);
      });
    }
    ctx.restore();
  };

  useEffect(() => {
    const e = engineRef.current;
    const handleKeyDown = (ev: KeyboardEvent) => {
      e.keys[ev.code] = true;
      if ((ev.code === 'ShiftLeft' || ev.code === 'ShiftRight') && !e.isCombined) {
        e.players.forEach(p => p.isTransformed = !p.isTransformed);
      }
      if (ev.code === 'KeyC') {
        if (e.isCombined) {
          e.isCombined = false; setIsCombinedUI(false);
          const hPer = e.combinedHealth / e.players.length;
          e.players.forEach((p, i) => { p.health = Math.min(p.maxHealth, hPer); p.width = 32; p.height = 48; p.pos.x = e.players[0].pos.x - i * 40; p.pos.y = e.players[0].pos.y; });
        } else if (upgrades.unlockedUnits.length >= 5) {
          e.isCombined = true; setIsCombinedUI(true);
          e.combinedMaxHealth = e.players.reduce((s, p) => s + p.maxHealth, 0) * 1.2;
          e.combinedHealth = e.players.reduce((s, p) => s + p.health, 0) * 1.2;
          e.players[0].width = 64; e.players[0].height = 96;
        }
      }
    };
    const handleKeyUp = (ev: KeyboardEvent) => { e.keys[ev.code] = false; };
    window.addEventListener('keydown', handleKeyDown); window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => { if (!e.isPaused) update(); draw(); animationId = requestAnimationFrame(loop); };

    const update = () => {
      e.frame++;
      const leader = e.players[0]; if (!leader) { onDie(); return; }
      const moveRight = e.keys['ArrowRight'] || e.keys['KeyD'];
      const moveLeft = e.keys['ArrowLeft'] || e.keys['KeyA'];
      const moveUp = e.keys['ArrowUp'] || e.keys['KeyW'];
      const firing = e.keys['Space'];

      if (e.isCombined) {
        const s = { speed: 4, jump: -15, fireRate: 6 };
        if (moveRight) { leader.vel.x = s.speed; leader.facing = 1; } else if (moveLeft) { leader.vel.x = -s.speed; leader.facing = -1; } else leader.vel.x *= 0.85;
        if (moveUp && leader.grounded) { leader.vel.y = s.jump; leader.grounded = false; }
        leader.vel.y += GRAVITY; leader.pos.x += leader.vel.x; leader.pos.y += leader.vel.y;
        if (leader.pos.y > GROUND_Y - leader.height) { leader.pos.y = GROUND_Y - leader.height; leader.vel.y = 0; leader.grounded = true; }
        if (firing && e.frame - leader.lastShot > s.fireRate) {
          soundService.playShoot();
          for(let i=-1; i<=1; i++) e.bullets.push({ pos: { x: leader.pos.x + 32, y: leader.pos.y + 40 + (i*15) }, vel: { x: leader.facing * 20, y: i * 1.5 }, width: 25, height: 8, owner: 'player', damage: 180, color: '#facc15', health: 1, maxHealth: 1 });
          leader.lastShot = e.frame;
        }
      } else {
        e.players.forEach((p, i) => {
          if (p.health <= 0) return;
          const stats = ROBOT_STATS[p.unit]; const s = p.isTransformed ? stats.alt : stats.robot;
          if (i === 0) {
            if (moveRight) { p.vel.x = s.speed; p.facing = 1; } else if (moveLeft) { p.vel.x = -s.speed; p.facing = -1; } else p.vel.x *= 0.8;
            if (moveUp && p.grounded) { p.vel.y = s.jump; p.grounded = false; }
          } else {
            const targetX = leader.pos.x - (i * 45 * leader.facing); const dist = targetX - p.pos.x;
            if (Math.abs(dist) > 20) { p.vel.x = Math.sign(dist) * s.speed * 0.9; p.facing = Math.sign(dist) || 1; } else p.vel.x *= 0.8;
            if (moveUp && p.grounded && leader.vel.y < -5) { p.vel.y = s.jump; p.grounded = false; }
          }
          p.vel.y += GRAVITY; p.pos.x += p.vel.x; p.pos.y += p.vel.y;
          if (p.pos.y > GROUND_Y - p.height) { p.pos.y = GROUND_Y - p.height; p.vel.y = 0; p.grounded = true; }
          if (firing && e.frame - p.lastShot > s.fireRate) {
            soundService.playShoot();
            e.bullets.push({ pos: { x: p.pos.x + 16, y: p.pos.y + 20 }, vel: { x: p.facing * 15, y: 0 }, width: 12, height: 4, owner: 'player', damage: 100, color: stats.color, health: 1, maxHealth: 1 });
            p.lastShot = e.frame;
          }
          if (p.invulnerable > 0) p.invulnerable--;
        });
      }

      for (let i = e.bullets.length - 1; i >= 0; i--) {
        const b = e.bullets[i]; b.pos.x += b.vel.x; b.pos.y += b.vel.y || 0;
        if (b.owner === 'enemy') {
          if (e.isCombined) {
            if (!leader.invulnerable && b.pos.x < leader.pos.x + leader.width && b.pos.x + b.width > leader.pos.x && b.pos.y < leader.pos.y + leader.height && b.pos.y + b.height > leader.pos.y) {
              e.combinedHealth -= 60; leader.invulnerable = 30; e.bullets.splice(i, 1); if (e.combinedHealth <= 0) onDie();
            }
          } else {
            e.players.forEach(p => { if (p.health > 0 && !p.invulnerable && b.pos.x < p.pos.x + p.width && b.pos.x + b.width > p.pos.x && b.pos.y < p.pos.y + p.height && b.pos.y + b.height > p.pos.y) { p.health -= 25; p.invulnerable = 40; e.bullets.splice(i, 1); } });
          }
        }
        if (Math.abs(b.pos.x - leader.pos.x) > 1000) e.bullets.splice(i, 1);
      }

      let enemiesAlive = 0;
      e.enemies.forEach(en => {
        if (en.isDead) return; enemiesAlive++;
        en.pos.x += Math.sign(leader.pos.x - en.pos.x) * 0.5;
        if (Math.abs(en.pos.x - leader.pos.x) < 600 && e.frame - en.lastShot > 100) {
          e.bullets.push({ pos: { x: en.pos.x, y: en.pos.y + 20 }, vel: { x: Math.sign(leader.pos.x - en.pos.x) * 8, y: 0 }, width: 10, height: 4, owner: 'enemy', health: 1, maxHealth: 1, damage: 25, color: '#f00' });
          en.lastShot = e.frame;
        }
        e.bullets.forEach((b, bi) => { if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) { en.health -= b.damage || 100; if (en.health <= 0) en.isDead = true; e.bullets.splice(bi, 1); } });
      });

      if (enemiesAlive === 0) onWin();
      if (!e.isCombined && e.players.every(p => p.health <= 0)) onDie();

      // Horizontal and Vertical Camera Follow
      e.cameraX = leader.pos.x - 200;
      const targetCamY = Math.min(0, leader.pos.y - 200);
      e.cameraY += (targetCamY - e.cameraY) * 0.1;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const leader = e.players[0]; if (!leader) return;
      ctx.fillStyle = '#020208'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
      ctx.save(); ctx.translate(-e.cameraX, -e.cameraY);
      ctx.fillStyle = '#080815'; ctx.fillRect(e.cameraX - 500, GROUND_Y + 48, CANVAS_WIDTH + 1000, 500);
      ctx.strokeStyle = '#00f3ff11'; ctx.lineWidth = 1;
      for (let gx = Math.floor((e.cameraX - 500) / 40) * 40; gx < e.cameraX + 1300; gx += 40) { ctx.beginPath(); ctx.moveTo(gx, GROUND_Y + 48); ctx.lineTo(gx, GROUND_Y + 1000); ctx.stroke(); }
      e.enemies.forEach(en => { if(!en.isDead) drawUnit(ctx, en.pos.x, en.pos.y, en.width, en.height, RobotUnit.SENTINEL, Math.sign(leader.pos.x - en.pos.x), e.frame, true, false, false, 1); });
      if (e.isCombined) drawUnit(ctx, leader.pos.x, leader.pos.y, leader.width, leader.height, leader.unit, leader.facing, e.frame, false, leader.invulnerable > 0, false, 1, true);
      else e.players.forEach(p => { if(p.health > 0) drawUnit(ctx, p.pos.x, p.pos.y, p.width, p.height, p.unit, p.facing, e.frame, false, p.invulnerable > 0, p.isTransformed, 1); });
      e.bullets.forEach(b => { ctx.fillStyle = b.color || '#fff'; ctx.fillRect(b.pos.x, b.pos.y, b.width, b.height); });
      ctx.restore();
      drawHUD(ctx, e);
    };
    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [onWin, onDie, upgrades]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden font-orbitron p-4 md:p-10">
      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full max-h-[85vh] aspect-video shadow-2xl rounded-lg border-2 border-cyan-900/50" />
      <div className="absolute bottom-4 md:bottom-8 left-1/2 -translate-x-1/2 pointer-events-none text-white/40 text-[9px] font-mono tracking-widest uppercase flex flex-wrap justify-center gap-4 md:gap-10 bg-black/60 px-6 py-2 md:px-8 md:py-3 rounded-full border border-white/5 backdrop-blur-md">
        <span>WASD: MOVE</span><span>SPACE: FIRE</span><span>SHIFT: TRANSFORM</span><span className={upgrades.unlockedUnits.length >= 5 ? 'text-emerald-400' : ''}>C: COMBINE (5+)</span>
      </div>
    </div>
  );
};

export default GameView;

export enum GameState {
  MENU = 'MENU',
  BRIEFING = 'BRIEFING',
  PLAYING = 'PLAYING',
  PAUSED = 'PAUSED',
  GAMEOVER = 'GAMEOVER',
  VICTORY = 'VICTORY',
  LEVEL_COMPLETE = 'LEVEL_COMPLETE',
  SHOP = 'SHOP',
  LEVEL_SELECT = 'LEVEL_SELECT',
  HOW_TO_PLAY = 'HOW_TO_PLAY'
}

export enum RobotUnit {
  SENTINEL = 'SENTINEL',
  STRIKER = 'STRIKER',
  FALCON = 'FALCON',
  TITAN = 'TITAN',
  SPECTER = 'SPECTER',
  VANGUARD = 'VANGUARD',
  NIGHTSHADE = 'NIGHTSHADE',
  BLAZE = 'BLAZE',
  GLITCH = 'GLITCH',
  OMEGA = 'OMEGA'
}

export interface LevelInfo {
  level: number;
  title: string;
  description: string;
  threatLevel: string;
  enemyType: string;
}

export interface Upgrades {
  robotTier: number;
  weaponTier: number;
  unlockedUnits: RobotUnit[];
}

export interface Vector {
  x: number;
  y: number;
}

export interface Entity {
  pos: Vector;
  vel: Vector;
  width: number;
  height: number;
  health: number;
  maxHealth: number;
}

export interface Bullet extends Entity {
  owner: 'player' | 'enemy';
  damage?: number;
  color?: string;
}

export interface Enemy extends Entity {
  id: number;
  isDead: boolean;
  type: string;
  lastShot: number;
  hasSplit?: boolean;
  sequenceStage?: number;
  sequenceTimer?: number;
  isTransformed?: boolean;
  transformTimer?: number;
  unit?: RobotUnit;
}

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { GameState, LevelInfo, RobotUnit, Upgrades } from './types';
import { getLevelBriefing } from './services/geminiService';
import MainMenu from './components/MainMenu';
import Briefing from './components/Briefing';
import GameView from './components/GameView';
import GameOver from './components/GameOver';
import Victory from './components/Victory';
import Shop from './components/Shop';
import LevelSelect from './components/LevelSelect';
import HowToPlay from './components/HowToPlay';

const SAVE_KEY = 'earthbots_save_data_v4';

const DEFAULT_UPGRADES: Upgrades = { 
  robotTier: 0, 
  weaponTier: 0, 
  unlockedUnits: [RobotUnit.SENTINEL]
};

const App: React.FC = () => {
  const [saveData, setSaveData] = useState(() => {
    const data = localStorage.getItem(SAVE_KEY);
    if (!data) return null;
    try {
      return JSON.parse(data);
    } catch (e) {
      return null;
    }
  });

  const [gameState, setGameState] = useState<GameState>(GameState.MENU);
  const [level, setLevel] = useState<number>(saveData?.level || 1);
  const [maxUnlockedLevel, setMaxUnlockedLevel] = useState<number>(saveData?.maxUnlockedLevel || 1);
  const [money, setMoney] = useState<number>(saveData?.money || 0);
  const [upgrades, setUpgrades] = useState<Upgrades>(saveData?.upgrades || DEFAULT_UPGRADES);

  const [briefing, setBriefing] = useState<LevelInfo | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [shopOrigin, setShopOrigin] = useState<GameState>(GameState.MENU);

  // Persistence Hook: Ensures state is saved to localStorage whenever it changes
  useEffect(() => {
    const dataToSave = { level, maxUnlockedLevel, money, upgrades };
    localStorage.setItem(SAVE_KEY, JSON.stringify(dataToSave));
  }, [level, maxUnlockedLevel, money, upgrades]);

  useEffect(() => {
    const handleGlobalKeyDown = (e: KeyboardEvent) => {
      if (e.code === 'KeyP') {
        setGameState(prev => {
          if (prev === GameState.PLAYING) return GameState.PAUSED;
          if (prev === GameState.PAUSED) return GameState.PLAYING;
          return prev;
        });
      }
    };
    window.addEventListener('keydown', handleGlobalKeyDown);
    return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, []);

  const handleOpenKeySelection = async () => {
    await (window as any).aistudio.openSelectKey();
    if (gameState === GameState.BRIEFING) {
      startLevel(level);
    }
  };

  const startLevel = useCallback(async (lvl: number) => {
    setIsLoading(true);
    setGameState(GameState.BRIEFING);
    setLevel(lvl);
    const data = await getLevelBriefing(lvl);
    setBriefing(data);
    setIsLoading(false);
  }, []);

  const handleStartGame = async () => {
    setGameState(GameState.LEVEL_SELECT);
  };

  const handleContinueGame = () => {
    if (saveData) {
      setLevel(saveData.level || 1);
      setMaxUnlockedLevel(saveData.maxUnlockedLevel || 1);
      setMoney(saveData.money || 0);
      setUpgrades(saveData.upgrades || DEFAULT_UPGRADES);
      startLevel(saveData.level || 1);
    } else {
      startLevel(1);
    }
  };

  const handleLevelComplete = () => {
    const reward = level === 20 ? 15000 : 500;
    setMoney(m => m + reward); 
    const newlyUnlocked = level + 1;
    if (newlyUnlocked > maxUnlockedLevel && newlyUnlocked <= 20) {
      setMaxUnlockedLevel(newlyUnlocked);
    }
    setGameState(GameState.LEVEL_COMPLETE);
  };

  const openShop = (origin: GameState) => {
    setShopOrigin(origin);
    setGameState(GameState.SHOP);
  };

  const handleSelectLevel = (lvlNum: number) => {
    setLevel(lvlNum);
    startLevel(lvlNum);
  };

  const handleNextLevel = () => {
    if (level === 20) setGameState(GameState.VICTORY);
    else startLevel(level + 1);
  };

  const handleShopExit = () => {
    setGameState(shopOrigin === GameState.MENU ? GameState.MENU : GameState.LEVEL_COMPLETE);
  };

  const handlePlayerDeath = () => setGameState(GameState.GAMEOVER);

  const buyRobotTier = () => {
    if (money >= 100) {
      setMoney(m => m - 100);
      setUpgrades(u => ({ ...u, robotTier: u.robotTier + 1 }));
    }
  };

  const buyWeaponTier = () => {
    if (money >= 50) {
      setMoney(m => m - 50);
      setUpgrades(u => ({ ...u, weaponTier: u.weaponTier + 1 }));
    }
  };

  const unlockRobotUnit = (unit: RobotUnit, price: number) => {
    if (money >= price && !upgrades.unlockedUnits.includes(unit)) {
      setMoney(m => m - price);
      setUpgrades(u => ({
        ...u,
        unlockedUnits: [...u.unlockedUnits, unit]
      }));
    }
  };

  const isGameVisible = gameState === GameState.PLAYING || gameState === GameState.PAUSED;

  return (
    <div className="w-full h-screen bg-black overflow-hidden select-none text-white font-rajdhani flex flex-col">
      <button onClick={handleOpenKeySelection} className="fixed bottom-4 right-4 z-[100] px-4 py-1 text-[10px] bg-gray-900/50 border border-gray-700 text-gray-500 hover:text-cyan-400 hover:border-cyan-500 transition-all font-mono uppercase tracking-tighter">
        Configure Uplink (API Key)
      </button>

      <div className="flex-1 overflow-hidden relative">
        {gameState === GameState.MENU && (
          <MainMenu 
            onStart={handleStartGame} 
            onContinue={handleContinueGame} 
            onOpenShop={() => openShop(GameState.MENU)} 
            onOpenLevelSelect={() => setGameState(GameState.LEVEL_SELECT)} 
            onOpenHowToPlay={() => setGameState(GameState.HOW_TO_PLAY)}
            hasSave={!!saveData} 
          />
        )}

        {gameState === GameState.HOW_TO_PLAY && (
          <HowToPlay onBack={() => setGameState(GameState.MENU)} />
        )}

        {gameState === GameState.LEVEL_SELECT && (
          <LevelSelect currentUnlocked={maxUnlockedLevel} onSelect={handleSelectLevel} onBack={() => setGameState(GameState.MENU)} />
        )}

        {gameState === GameState.BRIEFING && (
          <Briefing briefing={briefing || {} as LevelInfo} isLoading={isLoading} onConfirm={() => setGameState(GameState.PLAYING)} />
        )}

        {isGameVisible && (
          <GameView level={level} upgrades={upgrades} isPaused={gameState === GameState.PAUSED} onWin={handleLevelComplete} onDie={handlePlayerDeath} />
        )}

        {gameState === GameState.PAUSED && (
          <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex flex-col items-center justify-center z-50 p-4">
            <div className="p-10 border-2 border-cyan-500 bg-black/80 relative overflow-hidden group max-w-full">
              <h2 className="text-4xl md:text-6xl font-black text-cyan-400 italic tracking-tighter uppercase mb-4 font-orbitron text-center">SYSTEM SUSPENDED</h2>
              <div className="flex flex-col gap-4 items-center">
                <button onClick={() => setGameState(GameState.PLAYING)} className="px-12 py-4 bg-cyan-600 hover:bg-cyan-500 text-white font-bold text-2xl border-b-4 border-cyan-900 transition-all w-full uppercase font-orbitron">RESUME MISSION</button>
                <button onClick={() => setGameState(GameState.MENU)} className="px-12 py-2 text-cyan-400 font-bold hover:text-white transition-all uppercase text-sm font-orbitron">ABORT TO HQ</button>
              </div>
            </div>
          </div>
        )}

        {gameState === GameState.LEVEL_COMPLETE && (
          <div className="fixed inset-0 bg-black/95 flex flex-col items-center justify-start md:justify-center z-50 p-6 overflow-y-auto pt-20 md:pt-6">
            <h2 className="text-4xl md:text-5xl text-cyan-400 mb-2 font-black italic tracking-tighter animate-pulse uppercase font-orbitron text-center">Sector {level} Secured</h2>
            <div className="text-xl md:text-2xl text-yellow-400 mb-8 font-bold tracking-widest font-orbitron text-center">REWARD EARNED: ${level === 20 ? 15000 : 500}</div>
            <div className="flex flex-col items-center gap-6 w-full max-w-xs">
              <button onClick={() => openShop(GameState.LEVEL_COMPLETE)} className="px-8 py-4 bg-yellow-600 hover:bg-yellow-500 text-white font-bold rounded-sm border-b-4 border-yellow-800 transition-all w-full font-orbitron uppercase">VISIT ARMORY</button>
              <button onClick={handleNextLevel} className={`px-12 py-4 font-black rounded-sm transition-all w-full shadow-[0_0_30px_rgba(6,182,212,0.3)] uppercase tracking-widest font-orbitron text-xl ${level >= 20 ? 'bg-white text-black hover:bg-cyan-400' : 'bg-cyan-700 hover:bg-cyan-600 text-white'}`}>{level >= 20 ? 'Finalize Victory' : `Deploy to Sector ${level + 1}`}</button>
              <button onClick={() => setGameState(GameState.MENU)} className="px-12 py-2 text-gray-400 font-bold hover:text-white transition-all uppercase text-sm mt-4 border border-gray-800 hover:border-gray-400 bg-gray-950/40 font-orbitron w-full">Return to HQ</button>
            </div>
          </div>
        )}

        {gameState === GameState.SHOP && (
          <Shop money={money} upgrades={upgrades} onBuyRobot={buyRobotTier} onBuyWeapon={buyWeaponTier} onUnlockUnit={unlockRobotUnit} onExit={handleShopExit} isFromMenu={shopOrigin === GameState.MENU} />
        )}

        {gameState === GameState.GAMEOVER && (
          <GameOver level={level} onRetry={() => startLevel(level)} onMenu={() => setGameState(GameState.MENU)} />
        )}

        {gameState === GameState.VICTORY && <Victory onMenu={() => setGameState(GameState.MENU)} />}
      </div>
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 1200;
const CANVAS_HEIGHT = 675;
const GRAVITY = 0.5;
const GROUND_Y = 575;

interface PlayerEntity {
  unit: RobotUnit;
  pos: { x: number; y: number };
  vel: { x: number; y: number };
  width: number;
  height: number;
  facing: number;
  grounded: boolean;
  lastShot: number;
  invulnerable: number;
  health: number;
  maxHealth: number;
  isTransformed: boolean;
  id: string;
}

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { name: "SENTINEL", color: '#00f3ff', hpMult: 1.0, robot: { speed: 4, jump: -11, fireRate: 15 }, alt: { speed: 8, jump: -5, fireRate: 25, type: 'Police Car' }},
  [RobotUnit.STRIKER]: { name: "STRIKER", color: '#fbbf24', hpMult: 0.8, robot: { speed: 6, jump: -10, fireRate: 10 }, alt: { speed: 12, jump: -4, fireRate: 20, type: 'Bike' }},
  [RobotUnit.FALCON]: { name: "FALCON", color: '#22d3ee', hpMult: 0.7, robot: { speed: 5, jump: -10, fireRate: 12 }, alt: { speed: 7, jump: -7, fireRate: 15, type: 'Jet' }},
  [RobotUnit.TITAN]: { name: "TITAN", color: '#ef4444', hpMult: 2.5, robot: { speed: 2.5, jump: -12, fireRate: 30 }, alt: { speed: 4, jump: 0, fireRate: 20, type: 'Tank' }},
  [RobotUnit.SPECTER]: { name: "SPECTER", color: '#a855f7', hpMult: 0.6, robot: { speed: 5, jump: -11, fireRate: 20 }, alt: { speed: 6, jump: -14, fireRate: 40, type: 'Ambulance' }},
  [RobotUnit.VANGUARD]: { name: "VANGUARD", color: '#10b981', hpMult: 2.0, robot: { speed: 3.5, jump: -10, fireRate: 25 }, alt: { speed: 6, jump: -4, fireRate: 30, type: 'Fire Truck' }},
  [RobotUnit.NIGHTSHADE]: { name: "NIGHTSHADE", color: '#6366f1', hpMult: 0.9, robot: { speed: 7, jump: -13, fireRate: 12 }, alt: { speed: 10, jump: -6, fireRate: 18, type: 'Cyber Tiger' }},
  [RobotUnit.BLAZE]: { name: "BLAZE", color: '#f97316', hpMult: 1.2, robot: { speed: 4.5, jump: -11, fireRate: 18 }, alt: { speed: 12, jump: -5, fireRate: 15, type: 'Canon Race Car' }},
  [RobotUnit.GLITCH]: { name: "GLITCH", color: '#ec4899', hpMult: 1.0, robot: { speed: 5, jump: -12, fireRate: 14 }, alt: { speed: 10, jump: -12, fireRate: 16, type: 'Flying Car' }},
  [RobotUnit.OMEGA]: { name: "OMEGA", color: '#ffffff', hpMult: 3.0, robot: { speed: 6, jump: -14, fireRate: 10 }, alt: { speed: 8, jump: -10, fireRate: 10, type: 'Combat Blimp' }},
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isCombinedUI, setIsCombinedUI] = useState(false);

  const engineRef = useRef({
    players: [] as PlayerEntity[],
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    cameraY: 0,
    isPaused: isPaused,
    level: level,
    upgrades: upgrades,
    isCombined: false,
    combinedHealth: 0,
    combinedMaxHealth: 0,
  });

  useEffect(() => { 
    engineRef.current.isPaused = isPaused; 
    engineRef.current.level = level;
    engineRef.current.upgrades = upgrades;
  }, [isPaused, level, upgrades]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff66');
    grad.addColorStop(1, '#000000aa');
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.6)';
    ctx.lineWidth = 1;
    ctx.stroke();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, alpha = 1, sizeMult = 1) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8 * sizeMult;
    const armSwing = Math.cos(time) * 10 * sizeMult;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(sizeMult, sizeMult);
    drawMechanicalPart(ctx, -12, -18, 24, 28, color, 4);
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? '#ff0000' : '#00f3ff'; ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);
    ctx.restore();
  };

  const drawCombiner = (ctx: CanvasRenderingContext2D, color: string, frame: number, alpha = 1) => {
    ctx.save();
    ctx.translate(0, -30);
    drawHumanoid(ctx, '#facc15', frame, false, alpha, 2.5);
    const coreGlow = 0.4 + Math.sin(frame * 0.2) * 0.3;
    ctx.beginPath(); ctx.arc(0, -10, 8, 0, Math.PI * 2); ctx.fillStyle = `rgba(0, 243, 255, ${coreGlow})`; ctx.fill();
    if (frame % 30 < 5) {
      ctx.strokeStyle = '#00f3ff'; ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(-40, -80); ctx.lineTo(40, -10); ctx.stroke();
    }
    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy: boolean, invulnerable: boolean, transformed: boolean, alpha: number, isCombiner = false) => {
    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    ctx.scale(facing < 0 ? -1 : 1, 1);
    const drawAlpha = invulnerable ? (0.5 + Math.sin(frame * 0.5) * 0.3) * alpha : alpha;
    const color = isEnemy ? '#ff0055' : ROBOT_STATS[unit].color;
    if (isCombiner) drawCombiner(ctx, color, frame, drawAlpha);
    else if (transformed) {
       ctx.save(); ctx.globalAlpha = drawAlpha;
       drawMechanicalPart(ctx, -25, -12, 50, 24, color, 6);
       drawMechanicalPart(ctx, -10, -22, 20, 10, '#333', 2);
       ctx.restore();
    }
    else drawHumanoid(ctx, color, frame, isEnemy, drawAlpha);
    ctx.restore();
  };

  const createPlayer = (unit: RobotUnit, x: number, y: number): PlayerEntity => {
    const stats = ROBOT_STATS[unit];
    const baseHP = 100 + (engineRef.current.upgrades.robotTier * 50);
    return { id: Math.random().toString(36).substr(2, 9), unit, pos: { x, y: GROUND_Y - 48 }, vel: { x: 0, y: 0 }, width: 32, height: 48, facing: 1, grounded: true, lastShot: 0, invulnerable: 0, health: baseHP * stats.hpMult, maxHealth: baseHP * stats.hpMult, isTransformed: false };
  };

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    e.frame = 0; e.cameraX = 0; e.cameraY = 0; e.bullets = []; e.isCombined = false;
    e.players = upgrades.unlockedUnits.map((unit, i) => createPlayer(unit, 100 - i * 45, GROUND_Y - 48));
    const enemyCount = level === 20 ? 15 : 5;
    e.enemies = Array.from({ length: enemyCount }, (_, i) => ({ id: i, pos: { x: 800 + i * 500, y: GROUND_Y - 72 }, vel: { x: 0, y: 0 }, width: 48, height: 72, health: 100, maxHealth: 100, isDead: false, type: 'grunt', lastShot: 0 }));
    setIsCombinedUI(false);
  }, [level, upgrades]);

  useEffect(() => { resetLevel(); }, [resetLevel]);

  const drawHUD = (ctx: CanvasRenderingContext2D, e: any) => {
    ctx.save();
    const hudX = 30;
    const hudY = 30;
    const hudW = 260;
    const hudH = e.isCombined ? 80 : e.players.length * 32 + 30;

    ctx.fillStyle = 'rgba(0, 0, 0, 0.7)';
    ctx.fillRect(hudX, hudY, hudW, hudH);
    ctx.strokeStyle = 'rgba(0, 243, 255, 0.6)';
    ctx.lineWidth = 2;
    ctx.strokeRect(hudX, hudY, hudW, hudH);

    ctx.font = 'bold 12px Orbitron';
    ctx.fillStyle = '#00f3ff';
    ctx.fillText(e.isCombined ? "MEGA EARTHBOT ONLINE" : "SQUAD ALPHA STATUS", hudX + 15, hudY + 20);

    if (e.isCombined) {
      const hRatio = Math.max(0, e.combinedHealth / e.combinedMaxHealth);
      ctx.fillStyle = '#facc15';
      ctx.fillText("COMBINER HP", hudX + 15, hudY + 45);
      ctx.fillStyle = '#111';
      ctx.fillRect(hudX + 15, hudY + 55, 230, 10);
      ctx.fillStyle = '#facc15';
      ctx.fillRect(hudX + 15, hudY + 55, 230 * hRatio, 10);
    } else {
      e.players.forEach((p: PlayerEntity, i: number) => {
        const stats = ROBOT_STATS[p.unit];
        const hRatio = Math.max(0, p.health / p.maxHealth);
        const y = hudY + 45 + i * 32;
        ctx.fillStyle = p.health > 0 ? stats.color : '#444';
        ctx.fillText(stats.name, hudX + 15, y);
        ctx.fillStyle = '#111';
        ctx.fillRect(hudX + 15, y + 8, 200, 6);
        ctx.fillStyle = p.health > 0 ? stats.color : '#222';
        ctx.fillRect(hudX + 15, y + 8, 200 * hRatio, 6);
      });
    }
    ctx.restore();
  };

  useEffect(() => {
    const e = engineRef.current;
    const handleKeyDown = (ev: KeyboardEvent) => {
      e.keys[ev.code] = true;
      if ((ev.code === 'ShiftLeft' || ev.code === 'ShiftRight') && !e.isCombined) {
        e.players.forEach(p => p.isTransformed = !p.isTransformed);
      }
      if (ev.code === 'KeyC') {
        if (e.isCombined) {
          e.isCombined = false; setIsCombinedUI(false);
          const hPer = e.combinedHealth / e.players.length;
          e.players.forEach((p, i) => { p.health = Math.min(p.maxHealth, hPer); p.width = 32; p.height = 48; p.pos.x = e.players[0].pos.x - i * 40; p.pos.y = e.players[0].pos.y; });
        } else if (upgrades.unlockedUnits.length >= 5) {
          e.isCombined = true; setIsCombinedUI(true);
          e.combinedMaxHealth = e.players.reduce((s, p) => s + p.maxHealth, 0) * 1.2;
          e.combinedHealth = e.players.reduce((s, p) => s + p.health, 0) * 1.2;
          e.players[0].width = 64; e.players[0].height = 96;
        }
      }
    };
    const handleKeyUp = (ev: KeyboardEvent) => { e.keys[ev.code] = false; };
    window.addEventListener('keydown', handleKeyDown); window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => { if (!e.isPaused) update(); draw(); animationId = requestAnimationFrame(loop); };

    const update = () => {
      e.frame++;
      const leader = e.players[0]; if (!leader) { onDie(); return; }
      const moveRight = e.keys['ArrowRight'] || e.keys['KeyD'];
      const moveLeft = e.keys['ArrowLeft'] || e.keys['KeyA'];
      const moveUp = e.keys['ArrowUp'] || e.keys['KeyW'];
      const firing = e.keys['Space'];

      if (e.isCombined) {
        const s = { speed: 4, jump: -15, fireRate: 6 };
        if (moveRight) { leader.vel.x = s.speed; leader.facing = 1; } else if (moveLeft) { leader.vel.x = -s.speed; leader.facing = -1; } else leader.vel.x *= 0.85;
        if (moveUp && leader.grounded) { leader.vel.y = s.jump; leader.grounded = false; }
        leader.vel.y += GRAVITY; leader.pos.x += leader.vel.x; leader.pos.y += leader.vel.y;
        if (leader.pos.y > GROUND_Y - leader.height) { leader.pos.y = GROUND_Y - leader.height; leader.vel.y = 0; leader.grounded = true; }
        if (firing && e.frame - leader.lastShot > s.fireRate) {
          soundService.playShoot();
          for(let i=-1; i<=1; i++) e.bullets.push({ pos: { x: leader.pos.x + 32, y: leader.pos.y + 40 + (i*15) }, vel: { x: leader.facing * 20, y: i * 1.5 }, width: 25, height: 8, owner: 'player', damage: 180, color: '#facc15', health: 1, maxHealth: 1 });
          leader.lastShot = e.frame;
        }
      } else {
        e.players.forEach((p, i) => {
          if (p.health <= 0) return;
          const stats = ROBOT_STATS[p.unit]; const s = p.isTransformed ? stats.alt : stats.robot;
          if (i === 0) {
            if (moveRight) { p.vel.x = s.speed; p.facing = 1; } else if (moveLeft) { p.vel.x = -s.speed; p.facing = -1; } else p.vel.x *= 0.8;
            if (moveUp && p.grounded) { p.vel.y = s.jump; p.grounded = false; }
          } else {
            const targetX = leader.pos.x - (i * 45 * leader.facing); const dist = targetX - p.pos.x;
            if (Math.abs(dist) > 20) { p.vel.x = Math.sign(dist) * s.speed * 0.9; p.facing = Math.sign(dist) || 1; } else p.vel.x *= 0.8;
            if (moveUp && p.grounded && leader.vel.y < -5) { p.vel.y = s.jump; p.grounded = false; }
          }
          p.vel.y += GRAVITY; p.pos.x += p.vel.x; p.pos.y += p.vel.y;
          if (p.pos.y > GROUND_Y - p.height) { p.pos.y = GROUND_Y - p.height; p.vel.y = 0; p.grounded = true; }
          if (firing && e.frame - p.lastShot > s.fireRate) {
            soundService.playShoot();
            e.bullets.push({ pos: { x: p.pos.x + 16, y: p.pos.y + 20 }, vel: { x: p.facing * 15, y: 0 }, width: 12, height: 4, owner: 'player', damage: 100, color: stats.color, health: 1, maxHealth: 1 });
            p.lastShot = e.frame;
          }
          if (p.invulnerable > 0) p.invulnerable--;
        });
      }

      for (let i = e.bullets.length - 1; i >= 0; i--) {
        const b = e.bullets[i]; b.pos.x += b.vel.x; b.pos.y += b.vel.y || 0;
        if (b.owner === 'enemy') {
          if (e.isCombined) {
            if (!leader.invulnerable && b.pos.x < leader.pos.x + leader.width && b.pos.x + b.width > leader.pos.x && b.pos.y < leader.pos.y + leader.height && b.pos.y + b.height > leader.pos.y) {
              e.combinedHealth -= 60; leader.invulnerable = 30; e.bullets.splice(i, 1); if (e.combinedHealth <= 0) onDie();
            }
          } else {
            e.players.forEach(p => { if (p.health > 0 && !p.invulnerable && b.pos.x < p.pos.x + p.width && b.pos.x + b.width > p.pos.x && b.pos.y < p.pos.y + p.height && b.pos.y + b.height > p.pos.y) { p.health -= 25; p.invulnerable = 40; e.bullets.splice(i, 1); } });
          }
        }
        if (Math.abs(b.pos.x - leader.pos.x) > 1400) e.bullets.splice(i, 1);
      }

      let enemiesAlive = 0;
      e.enemies.forEach(en => {
        if (en.isDead) return; enemiesAlive++;
        en.pos.x += Math.sign(leader.pos.x - en.pos.x) * 0.5;
        if (Math.abs(en.pos.x - leader.pos.x) < 800 && e.frame - en.lastShot > 100) {
          e.bullets.push({ pos: { x: en.pos.x, y: en.pos.y + 20 }, vel: { x: Math.sign(leader.pos.x - en.pos.x) * 8, y: 0 }, width: 10, height: 4, owner: 'enemy', health: 1, maxHealth: 1, damage: 25, color: '#f00' });
          en.lastShot = e.frame;
        }
        e.bullets.forEach((b, bi) => { if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) { en.health -= b.damage || 100; if (en.health <= 0) en.isDead = true; e.bullets.splice(bi, 1); } });
      });

      if (enemiesAlive === 0) onWin();
      if (!e.isCombined && e.players.every(p => p.health <= 0)) onDie();

      // Horizontal and Vertical Camera Follow
      e.cameraX = leader.pos.x - 400;
      const targetCamY = Math.min(0, leader.pos.y - 300);
      e.cameraY += (targetCamY - e.cameraY) * 0.1;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const leader = e.players[0]; if (!leader) return;
      ctx.fillStyle = '#020208'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
      ctx.save(); ctx.translate(-e.cameraX, -e.cameraY);

      // Extended background ground rendering
      ctx.fillStyle = '#080815'; 
      ctx.fillRect(e.cameraX - 1000, GROUND_Y + 48, CANVAS_WIDTH + 2000, 1000);

      ctx.strokeStyle = '#00f3ff11'; ctx.lineWidth = 1;
      for (let gx = Math.floor((e.cameraX - 1000) / 40) * 40; gx < e.cameraX + 2300; gx += 40) { ctx.beginPath(); ctx.moveTo(gx, GROUND_Y + 48); ctx.lineTo(gx, GROUND_Y + 1000); ctx.stroke(); }

      e.enemies.forEach(en => { if(!en.isDead) drawUnit(ctx, en.pos.x, en.pos.y, en.width, en.height, RobotUnit.SENTINEL, Math.sign(leader.pos.x - en.pos.x), e.frame, true, false, false, 1); });
      if (e.isCombined) drawUnit(ctx, leader.pos.x, leader.pos.y, leader.width, leader.height, leader.unit, leader.facing, e.frame, false, leader.invulnerable > 0, false, 1, true);
      else e.players.forEach(p => { if(p.health > 0) drawUnit(ctx, p.pos.x, p.pos.y, p.width, p.height, p.unit, p.facing, e.frame, false, p.invulnerable > 0, p.isTransformed, 1); });
      e.bullets.forEach(b => { ctx.fillStyle = b.color || '#fff'; ctx.fillRect(b.pos.x, b.pos.y, b.width, b.height); });
      ctx.restore();
      drawHUD(ctx, e);
    };
    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [onWin, onDie, upgrades]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden font-orbitron p-2 md:p-6">
      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full max-h-[95vh] aspect-video shadow-[0_0_60px_rgba(0,0,0,0.8)] rounded-sm border-4 border-cyan-900/30" />
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 1600;
const CANVAS_HEIGHT = 900;
const GRAVITY = 0.5;
const GROUND_Y = 750;

interface PlayerEntity {
  unit: RobotUnit;
  pos: { x: number; y: number };
  vel: { x: number; y: number };
  width: number;
  height: number;
  facing: number;
  grounded: boolean;
  lastShot: number;
  invulnerable: number;
  health: number;
  maxHealth: number;
  isTransformed: boolean;
  id: string;
}

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { name: "SENTINEL", color: '#00f3ff', hpMult: 1.0, robot: { speed: 5, jump: 0, fireRate: 15 }, alt: { speed: 10, jump: 0, fireRate: 25, type: 'Police Car' }},
  [RobotUnit.STRIKER]: { name: "STRIKER", color: '#fbbf24', hpMult: 0.8, robot: { speed: 7, jump: 0, fireRate: 10 }, alt: { speed: 15, jump: 0, fireRate: 20, type: 'Bike' }},
  [RobotUnit.FALCON]: { name: "FALCON", color: '#22d3ee', hpMult: 0.7, robot: { speed: 6, jump: 0, fireRate: 12 }, alt: { speed: 9, jump: 0, fireRate: 15, type: 'Jet' }},
  [RobotUnit.TITAN]: { name: "TITAN", color: '#ef4444', hpMult: 2.5, robot: { speed: 3.5, jump: 0, fireRate: 30 }, alt: { speed: 5, jump: 0, fireRate: 20, type: 'Tank' }},
  [RobotUnit.SPECTER]: { name: "SPECTER", color: '#a855f7', hpMult: 0.6, robot: { speed: 6, jump: 0, fireRate: 20 }, alt: { speed: 8, jump: 0, fireRate: 40, type: 'Ambulance' }},
  [RobotUnit.VANGUARD]: { name: "VANGUARD", color: '#10b981', hpMult: 2.0, robot: { speed: 4.5, jump: 0, fireRate: 25 }, alt: { speed: 8, jump: 0, fireRate: 30, type: 'Fire Truck' }},
  [RobotUnit.NIGHTSHADE]: { name: "NIGHTSHADE", color: '#6366f1', hpMult: 0.9, robot: { speed: 8, jump: 0, fireRate: 12 }, alt: { speed: 12, jump: 0, fireRate: 18, type: 'Cyber Tiger' }},
  [RobotUnit.BLAZE]: { name: "BLAZE", color: '#f97316', hpMult: 1.2, robot: { speed: 5.5, jump: 0, fireRate: 18 }, alt: { speed: 14, jump: 0, fireRate: 15, type: 'Canon Race Car' }},
  [RobotUnit.GLITCH]: { name: "GLITCH", color: '#ec4899', hpMult: 1.0, robot: { speed: 6, jump: 0, fireRate: 14 }, alt: { speed: 12, jump: 0, fireRate: 16, type: 'Flying Car' }},
  [RobotUnit.OMEGA]: { name: "OMEGA", color: '#ffffff', hpMult: 3.0, robot: { speed: 8, jump: 0, fireRate: 10 }, alt: { speed: 10, jump: 0, fireRate: 10, type: 'Combat Blimp' }},
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const engineRef = useRef({
    players: [] as PlayerEntity[],
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    cameraY: 0,
    isPaused: isPaused,
    level: level,
    upgrades: upgrades,
    isCombined: false,
    combinedHealth: 0,
    combinedMaxHealth: 0,
  });

  useEffect(() => { 
    engineRef.current.isPaused = isPaused; 
    engineRef.current.level = level;
    engineRef.current.upgrades = upgrades;
  }, [isPaused, level, upgrades]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff66');
    grad.addColorStop(1, '#000000aa');
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.6)';
    ctx.lineWidth = 1;
    ctx.stroke();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, alpha = 1, sizeMult = 1) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8 * sizeMult;
    const armSwing = Math.cos(time) * 10 * sizeMult;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(sizeMult, sizeMult);
    drawMechanicalPart(ctx, -12, -18, 24, 28, color, 4);
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? '#ff0000' : '#00f3ff'; ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);
    ctx.restore();
  };

  const drawCombiner = (ctx: CanvasRenderingContext2D, color: string, frame: number, alpha = 1) => {
    ctx.save();
    ctx.translate(0, -30);
    drawHumanoid(ctx, '#facc15', frame, false, alpha, 2.5);
    const coreGlow = 0.4 + Math.sin(frame * 0.2) * 0.3;
    ctx.beginPath(); ctx.arc(0, -10, 8, 0, Math.PI * 2); ctx.fillStyle = `rgba(0, 243, 255, ${coreGlow})`; ctx.fill();
    if (frame % 30 < 5) {
      ctx.strokeStyle = '#00f3ff'; ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(-40, -80); ctx.lineTo(40, -10); ctx.stroke();
    }
    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy: boolean, invulnerable: boolean, transformed: boolean, alpha: number, isCombiner = false) => {
    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    ctx.scale(facing < 0 ? -1 : 1, 1);
    const drawAlpha = invulnerable ? (0.5 + Math.sin(frame * 0.5) * 0.3) * alpha : alpha;
    const color = isEnemy ? '#ff0055' : ROBOT_STATS[unit].color;
    if (isCombiner) drawCombiner(ctx, color, frame, drawAlpha);
    else if (transformed) {
       ctx.save(); ctx.globalAlpha = drawAlpha;
       drawMechanicalPart(ctx, -25, -12, 50, 24, color, 6);
       drawMechanicalPart(ctx, -10, -22, 20, 10, '#333', 2);
       ctx.restore();
    }
    else drawHumanoid(ctx, color, frame, isEnemy, drawAlpha);
    ctx.restore();
  };

  const createPlayer = (unit: RobotUnit, x: number, y: number): PlayerEntity => {
    const stats = ROBOT_STATS[unit];
    const baseHP = 100 + (engineRef.current.upgrades.robotTier * 50);
    return { id: Math.random().toString(36).substr(2, 9), unit, pos: { x, y: GROUND_Y - 48 }, vel: { x: 0, y: 0 }, width: 32, height: 48, facing: 1, grounded: true, lastShot: 0, invulnerable: 0, health: baseHP * stats.hpMult, maxHealth: baseHP * stats.hpMult, isTransformed: false };
  };

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    e.frame = 0; e.cameraX = 0; e.cameraY = 0; e.bullets = []; e.isCombined = false;
    e.players = upgrades.unlockedUnits.map((unit, i) => createPlayer(unit, 100 - i * 55, GROUND_Y - 48));
    const enemyCount = level === 20 ? 15 : 5;
    e.enemies = Array.from({ length: enemyCount }, (_, i) => ({ id: i, pos: { x: 1200 + i * 600, y: GROUND_Y - 72 }, vel: { x: 0, y: 0 }, width: 48, height: 72, health: 100, maxHealth: 100, isDead: false, type: 'grunt', lastShot: 0 }));
  }, [level, upgrades]);

  useEffect(() => { resetLevel(); }, [resetLevel]);

  const drawCityscape = (ctx: CanvasRenderingContext2D, e: any) => {
    const camX = e.cameraX;

    // Background sky gradient
    const skyGrad = ctx.createLinearGradient(0, 0, 0, CANVAS_HEIGHT);
    skyGrad.addColorStop(0, '#020208');
    skyGrad.addColorStop(0.7, '#1a0d0a');
    skyGrad.addColorStop(1, '#331100');
    ctx.fillStyle = skyGrad;
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Parallax layers
    const layers = [
      { scroll: 0.1, color: '#0a0a12', count: 12, hMin: 150, hMax: 400 },
      { scroll: 0.3, color: '#160d0a', count: 18, hMin: 200, hMax: 600 },
      { scroll: 0.5, color: '#050505', count: 24, hMin: 250, hMax: 800 },
    ];

    layers.forEach((layer, li) => {
      ctx.fillStyle = layer.color;
      const spacing = 140;
      const startX = Math.floor((camX * layer.scroll) / spacing) * spacing - spacing * 2;

      for (let x = startX; x < startX + CANVAS_WIDTH + spacing * 4; x += spacing) {
        const seed = Math.abs(Math.sin(x * 0.007 + li));
        const h = seed * (layer.hMax - layer.hMin) + layer.hMin;
        const bx = x - (camX * layer.scroll);
        const bw = spacing - 20;
        ctx.fillRect(bx, GROUND_Y - h, bw, h);

        // Burning windows and fire effects
        if (li >= 1) {
          const fireInt = Math.sin(x * 0.5 + e.frame * 0.05);
          if (fireInt > 0.4) {
            ctx.fillStyle = fireInt > 0.8 ? '#ff6600' : '#aa2200';
            // Window rows
            for (let row = 0; row < 6; row++) {
              if (Math.cos(x + row) > 0.2) {
                ctx.fillRect(bx + 15, GROUND_Y - h + 40 + row * 50, 20, 15);
                ctx.fillRect(bx + bw - 35, GROUND_Y - h + 40 + row * 50, 20, 15);
              }
            }
            // Fire on roof
            const flicker = Math.sin(e.frame * 0.2 + x) * 8;
            ctx.beginPath();
            ctx.moveTo(bx + bw * 0.2, GROUND_Y - h);
            ctx.lineTo(bx + bw * 0.5, GROUND_Y - h - 30 - flicker);
            ctx.lineTo(bx + bw * 0.8, GROUND_Y - h);
            ctx.fill();
          }
          ctx.fillStyle = layer.color;
        }
      }
    });
  };

  const drawHUD = (ctx: CanvasRenderingContext2D, e: any) => {
    ctx.save();
    const hudX = 40;
    const hudY = 40;
    const hudW = 320;
    const hudH = e.isCombined ? 100 : e.players.length * 36 + 40;

    ctx.fillStyle = 'rgba(0, 0, 0, 0.75)';
    ctx.fillRect(hudX, hudY, hudW, hudH);
    ctx.strokeStyle = 'rgba(0, 243, 255, 0.6)';
    ctx.lineWidth = 3;
    ctx.strokeRect(hudX, hudY, hudW, hudH);

    ctx.font = 'bold 14px Orbitron';
    ctx.fillStyle = '#00f3ff';
    ctx.fillText(e.isCombined ? "MEGA EARTHBOT ONLINE" : "SQUAD ALPHA STATUS", hudX + 20, hudY + 30);

    if (e.isCombined) {
      const hRatio = Math.max(0, e.combinedHealth / e.combinedMaxHealth);
      ctx.fillStyle = '#facc15';
      ctx.fillText("COMBINER HP", hudX + 20, hudY + 60);
      ctx.fillStyle = '#111';
      ctx.fillRect(hudX + 20, hudY + 70, 280, 12);
      ctx.fillStyle = '#facc15';
      ctx.fillRect(hudX + 20, hudY + 70, 280 * hRatio, 12);
    } else {
      e.players.forEach((p: PlayerEntity, i: number) => {
        const stats = ROBOT_STATS[p.unit];
        const hRatio = Math.max(0, p.health / p.maxHealth);
        const y = hudY + 60 + i * 36;
        ctx.fillStyle = p.health > 0 ? stats.color : '#444';
        ctx.fillText(stats.name, hudX + 20, y);
        ctx.fillStyle = '#111';
        ctx.fillRect(hudX + 20, y + 10, 240, 8);
        ctx.fillStyle = p.health > 0 ? stats.color : '#222';
        ctx.fillRect(hudX + 20, y + 10, 240 * hRatio, 8);
      });
    }
    ctx.restore();
  };

  useEffect(() => {
    const e = engineRef.current;
    const handleKeyDown = (ev: KeyboardEvent) => {
      e.keys[ev.code] = true;
      if ((ev.code === 'ShiftLeft' || ev.code === 'ShiftRight') && !e.isCombined) {
        e.players.forEach(p => p.isTransformed = !p.isTransformed);
      }
      if (ev.code === 'KeyC') {
        if (e.isCombined) {
          e.isCombined = false;
          const hPer = e.combinedHealth / e.players.length;
          e.players.forEach((p, i) => { p.health = Math.min(p.maxHealth, hPer); p.width = 32; p.height = 48; p.pos.x = e.players[0].pos.x - i * 50; p.pos.y = GROUND_Y - 48; });
        } else if (upgrades.unlockedUnits.length >= 5) {
          e.isCombined = true;
          e.combinedMaxHealth = e.players.reduce((s, p) => s + p.maxHealth, 0) * 1.2;
          e.combinedHealth = e.players.reduce((s, p) => s + p.health, 0) * 1.2;
          e.players[0].width = 64; e.players[0].height = 96;
        }
      }
    };
    const handleKeyUp = (ev: KeyboardEvent) => { e.keys[ev.code] = false; };
    window.addEventListener('keydown', handleKeyDown); window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => { if (!e.isPaused) update(); draw(); animationId = requestAnimationFrame(loop); };

    const update = () => {
      e.frame++;
      const leader = e.players[0]; if (!leader) { onDie(); return; }
      const moveRight = e.keys['ArrowRight'] || e.keys['KeyD'];
      const moveLeft = e.keys['ArrowLeft'] || e.keys['KeyA'];
      const firing = e.keys['Space'];

      if (e.isCombined) {
        const s = { speed: 5, fireRate: 6 };
        if (moveRight) { leader.vel.x = s.speed; leader.facing = 1; } else if (moveLeft) { leader.vel.x = -s.speed; leader.facing = -1; } else leader.vel.x *= 0.85;
        leader.pos.x += leader.vel.x; leader.pos.y = GROUND_Y - leader.height;
        if (firing && e.frame - leader.lastShot > s.fireRate) {
          soundService.playShoot();
          for(let i=-1; i<=1; i++) e.bullets.push({ pos: { x: leader.pos.x + 40, y: leader.pos.y + 50 + (i*20) }, vel: { x: leader.facing * 25, y: i * 2 }, width: 30, height: 10, owner: 'player', damage: 180, color: '#facc15', health: 1, maxHealth: 1 });
          leader.lastShot = e.frame;
        }
      } else {
        e.players.forEach((p, i) => {
          if (p.health <= 0) return;
          const stats = ROBOT_STATS[p.unit]; const s = p.isTransformed ? stats.alt : stats.robot;
          if (i === 0) {
            if (moveRight) { p.vel.x = s.speed; p.facing = 1; } else if (moveLeft) { p.vel.x = -s.speed; p.facing = -1; } else p.vel.x *= 0.8;
          } else {
            const targetX = leader.pos.x - (i * 60 * leader.facing); const dist = targetX - p.pos.x;
            if (Math.abs(dist) > 30) { p.vel.x = Math.sign(dist) * s.speed * 0.9; p.facing = Math.sign(dist) || 1; } else p.vel.x *= 0.8;
          }
          p.pos.x += p.vel.x; p.pos.y = GROUND_Y - p.height;
          if (firing && e.frame - p.lastShot > s.fireRate) {
            soundService.playShoot();
            e.bullets.push({ pos: { x: p.pos.x + 20, y: p.pos.y + 25 }, vel: { x: p.facing * 18, y: 0 }, width: 16, height: 6, owner: 'player', damage: 100, color: stats.color, health: 1, maxHealth: 1 });
            p.lastShot = e.frame;
          }
          if (p.invulnerable > 0) p.invulnerable--;
        });
      }

      for (let i = e.bullets.length - 1; i >= 0; i--) {
        const b = e.bullets[i]; b.pos.x += b.vel.x; b.pos.y += b.vel.y || 0;
        if (b.owner === 'enemy') {
          if (e.isCombined) {
            if (!leader.invulnerable && b.pos.x < leader.pos.x + leader.width && b.pos.x + b.width > leader.pos.x && b.pos.y < leader.pos.y + leader.height && b.pos.y + b.height > leader.pos.y) {
              e.combinedHealth -= 60; leader.invulnerable = 30; e.bullets.splice(i, 1); if (e.combinedHealth <= 0) onDie();
            }
          } else {
            e.players.forEach(p => { if (p.health > 0 && !p.invulnerable && b.pos.x < p.pos.x + p.width && b.pos.x + b.width > p.pos.x && b.pos.y < p.pos.y + p.height && b.pos.y + b.height > p.pos.y) { p.health -= 25; p.invulnerable = 40; e.bullets.splice(i, 1); } });
          }
        }
        if (Math.abs(b.pos.x - leader.pos.x) > 2000) e.bullets.splice(i, 1);
      }

      let enemiesAlive = 0;
      e.enemies.forEach(en => {
        if (en.isDead) return; enemiesAlive++;
        en.pos.x += Math.sign(leader.pos.x - en.pos.x) * 0.7;
        if (Math.abs(en.pos.x - leader.pos.x) < 1000 && e.frame - en.lastShot > 100) {
          e.bullets.push({ pos: { x: en.pos.x, y: en.pos.y + 30 }, vel: { x: Math.sign(leader.pos.x - en.pos.x) * 10, y: 0 }, width: 15, height: 6, owner: 'enemy', health: 1, maxHealth: 1, damage: 25, color: '#f00' });
          en.lastShot = e.frame;
        }
        e.bullets.forEach((b, bi) => { if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) { en.health -= b.damage || 100; if (en.health <= 0) en.isDead = true; e.bullets.splice(bi, 1); } });
      });

      if (enemiesAlive === 0) onWin();
      if (!e.isCombined && e.players.every(p => p.health <= 0)) onDie();

      // Horizontal Camera Follow
      e.cameraX = leader.pos.x - 600;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const leader = e.players[0]; if (!leader) return;

      // Background City
      drawCityscape(ctx, e);

      ctx.save(); ctx.translate(-e.cameraX, 0);

      // Ground Platform
      ctx.fillStyle = '#101015'; 
      ctx.fillRect(e.cameraX - 1000, GROUND_Y, CANVAS_WIDTH + 2000, 200);
      ctx.strokeStyle = '#00f3ff22'; ctx.lineWidth = 2;
      for (let gx = Math.floor((e.cameraX - 1000) / 60) * 60; gx < e.cameraX + 2600; gx += 60) { ctx.beginPath(); ctx.moveTo(gx, GROUND_Y); ctx.lineTo(gx, GROUND_Y + 200); ctx.stroke(); }

      e.enemies.forEach(en => { if(!en.isDead) drawUnit(ctx, en.pos.x, en.pos.y, en.width, en.height, RobotUnit.SENTINEL, Math.sign(leader.pos.x - en.pos.x), e.frame, true, false, false, 1.2); });
      if (e.isCombined) drawUnit(ctx, leader.pos.x, leader.pos.y, leader.width, leader.height, leader.unit, leader.facing, e.frame, false, leader.invulnerable > 0, false, 1, true);
      else e.players.forEach(p => { if(p.health > 0) drawUnit(ctx, p.pos.x, p.pos.y, p.width, p.height, p.unit, p.facing, e.frame, false, p.invulnerable > 0, p.isTransformed, 1); });
      e.bullets.forEach(b => { ctx.fillStyle = b.color || '#fff'; ctx.fillRect(b.pos.x, b.pos.y, b.width, b.height); });
      ctx.restore();
      drawHUD(ctx, e);
    };
    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [onWin, onDie, upgrades]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden font-orbitron">
      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full max-h-[100vh] aspect-video shadow-[0_0_100px_rgba(0,0,0,1)]" />
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 1600;
const CANVAS_HEIGHT = 900;
const GRAVITY = 0.5;
const GROUND_Y = 750;

interface PlayerEntity {
  unit: RobotUnit;
  pos: { x: number; y: number };
  vel: { x: number; y: number };
  width: number;
  height: number;
  facing: number;
  grounded: boolean;
  lastShot: number;
  invulnerable: number;
  health: number;
  maxHealth: number;
  isTransformed: boolean;
  id: string;
}

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { name: "SENTINEL", color: '#00f3ff', hpMult: 1.0, robot: { speed: 5, jump: 0, fireRate: 15 }, alt: { speed: 10, jump: 0, fireRate: 25, type: 'Police Car' }},
  [RobotUnit.STRIKER]: { name: "STRIKER", color: '#fbbf24', hpMult: 0.8, robot: { speed: 7, jump: 0, fireRate: 10 }, alt: { speed: 15, jump: 0, fireRate: 20, type: 'Bike' }},
  [RobotUnit.FALCON]: { name: "FALCON", color: '#22d3ee', hpMult: 0.7, robot: { speed: 6, jump: 0, fireRate: 12 }, alt: { speed: 9, jump: 0, fireRate: 15, type: 'Jet' }},
  [RobotUnit.TITAN]: { name: "TITAN", color: '#ef4444', hpMult: 2.5, robot: { speed: 3.5, jump: 0, fireRate: 30 }, alt: { speed: 5, jump: 0, fireRate: 20, type: 'Tank' }},
  [RobotUnit.SPECTER]: { name: "SPECTER", color: '#a855f7', hpMult: 0.6, robot: { speed: 6, jump: 0, fireRate: 20 }, alt: { speed: 8, jump: 0, fireRate: 40, type: 'Ambulance' }},
  [RobotUnit.VANGUARD]: { name: "VANGUARD", color: '#10b981', hpMult: 2.0, robot: { speed: 4.5, jump: 0, fireRate: 25 }, alt: { speed: 8, jump: 0, fireRate: 30, type: 'Fire Truck' }},
  [RobotUnit.NIGHTSHADE]: { name: "NIGHTSHADE", color: '#6366f1', hpMult: 0.9, robot: { speed: 8, jump: 0, fireRate: 12 }, alt: { speed: 12, jump: 0, fireRate: 18, type: 'Cyber Tiger' }},
  [RobotUnit.BLAZE]: { name: "BLAZE", color: '#f97316', hpMult: 1.2, robot: { speed: 5.5, jump: 0, fireRate: 18 }, alt: { speed: 14, jump: 0, fireRate: 15, type: 'Canon Race Car' }},
  [RobotUnit.GLITCH]: { name: "GLITCH", color: '#ec4899', hpMult: 1.0, robot: { speed: 6, jump: 0, fireRate: 14 }, alt: { speed: 12, jump: 0, fireRate: 16, type: 'Flying Car' }},
  [RobotUnit.OMEGA]: { name: "OMEGA", color: '#ffffff', hpMult: 3.0, robot: { speed: 8, jump: 0, fireRate: 10 }, alt: { speed: 10, jump: 0, fireRate: 10, type: 'Combat Blimp' }},
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const engineRef = useRef({
    players: [] as PlayerEntity[],
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    cameraY: 0,
    isPaused: isPaused,
    level: level,
    upgrades: upgrades,
    isCombined: false,
    combinedHealth: 0,
    combinedMaxHealth: 0,
  });

  useEffect(() => { 
    engineRef.current.isPaused = isPaused; 
    engineRef.current.level = level;
    engineRef.current.upgrades = upgrades;
  }, [isPaused, level, upgrades]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff66');
    grad.addColorStop(1, '#000000aa');
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.6)';
    ctx.lineWidth = 1;
    ctx.stroke();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, alpha = 1, sizeMult = 1) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8 * sizeMult;
    const armSwing = Math.cos(time) * 10 * sizeMult;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(sizeMult, sizeMult);
    drawMechanicalPart(ctx, -12, -18, 24, 28, color, 4);
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? '#ff0000' : '#00f3ff'; ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);
    ctx.restore();
  };

  const drawHelicopter = (ctx: CanvasRenderingContext2D, color: string, frame: number, alpha = 1) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    // Body
    drawMechanicalPart(ctx, -20, -10, 40, 20, color, 10);
    // Tail
    drawMechanicalPart(ctx, -40, -5, 25, 8, color, 2);
    // Rotor
    const rotorWidth = 60 * Math.sin(frame * 0.8);
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(-rotorWidth/2, -15);
    ctx.lineTo(rotorWidth/2, -15);
    ctx.stroke();
    // Glass
    ctx.fillStyle = '#00f3ff55';
    ctx.fillRect(5, -5, 12, 8);
    ctx.restore();
  };

  const drawCombiner = (ctx: CanvasRenderingContext2D, color: string, frame: number, alpha = 1) => {
    ctx.save();
    ctx.translate(0, -30);
    drawHumanoid(ctx, '#facc15', frame, false, alpha, 2.5);
    const coreGlow = 0.4 + Math.sin(frame * 0.2) * 0.3;
    ctx.beginPath(); ctx.arc(0, -10, 8, 0, Math.PI * 2); ctx.fillStyle = `rgba(0, 243, 255, ${coreGlow})`; ctx.fill();
    if (frame % 30 < 5) {
      ctx.strokeStyle = '#00f3ff'; ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(-40, -80); ctx.lineTo(40, -10); ctx.stroke();
    }
    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy: boolean, invulnerable: boolean, transformed: boolean, alpha: number, isCombiner = false, type: string = 'grunt') => {
    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    ctx.scale(facing < 0 ? -1 : 1, 1);
    const drawAlpha = invulnerable ? (0.5 + Math.sin(frame * 0.5) * 0.3) * alpha : alpha;
    const color = isEnemy ? '#ff0055' : ROBOT_STATS[unit].color;

    if (isCombiner) {
      drawCombiner(ctx, color, frame, drawAlpha);
    } else if (type === 'helicopter') {
      drawHelicopter(ctx, color, frame, drawAlpha);
    } else if (transformed) {
       ctx.save(); ctx.globalAlpha = drawAlpha;
       drawMechanicalPart(ctx, -25, -12, 50, 24, color, 6);
       drawMechanicalPart(ctx, -10, -22, 20, 10, '#333', 2);
       ctx.restore();
    } else {
      drawHumanoid(ctx, color, frame, isEnemy, drawAlpha);
    }
    ctx.restore();
  };

  const createPlayer = (unit: RobotUnit, x: number, y: number): PlayerEntity => {
    const stats = ROBOT_STATS[unit];
    const baseHP = 100 + (engineRef.current.upgrades.robotTier * 50);
    return { id: Math.random().toString(36).substr(2, 9), unit, pos: { x, y: GROUND_Y - 48 }, vel: { x: 0, y: 0 }, width: 32, height: 48, facing: 1, grounded: true, lastShot: 0, invulnerable: 0, health: baseHP * stats.hpMult, maxHealth: baseHP * stats.hpMult, isTransformed: false };
  };

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    e.frame = 0; e.cameraX = 0; e.cameraY = 0; e.bullets = []; e.isCombined = false;
    e.players = upgrades.unlockedUnits.map((unit, i) => createPlayer(unit, 100 - i * 55, GROUND_Y - 48));

    // Exactly 5 enemies per level as requested, with helicopters mixed in
    const enemyCount = 5;
    e.enemies = Array.from({ length: enemyCount }, (_, i) => {
      const isHelicopter = i % 2 === 1 && level > 2; // Introduce helicopters after level 2
      const type = isHelicopter ? 'helicopter' : 'grunt';
      const width = isHelicopter ? 60 : 48;
      const height = isHelicopter ? 40 : 72;
      const startY = isHelicopter ? 200 + Math.random() * 200 : GROUND_Y - height;

      return { 
        id: i, 
        pos: { x: 1400 + i * 500, y: startY }, 
        vel: { x: 0, y: 0 }, 
        width, 
        height, 
        health: 100 + (level * 10), 
        maxHealth: 100 + (level * 10), 
        isDead: false, 
        type, 
        lastShot: 0 
      };
    });
  }, [level, upgrades]);

  useEffect(() => { resetLevel(); }, [resetLevel]);

  const drawCityscape = (ctx: CanvasRenderingContext2D, e: any) => {
    const camX = e.cameraX;

    // Background sky gradient
    const skyGrad = ctx.createLinearGradient(0, 0, 0, CANVAS_HEIGHT);
    skyGrad.addColorStop(0, '#020208');
    skyGrad.addColorStop(0.7, '#1a0d0a');
    skyGrad.addColorStop(1, '#331100');
    ctx.fillStyle = skyGrad;
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Parallax layers for the burning city
    const layers = [
      { scroll: 0.1, color: '#0a0a12', spacing: 200, hMin: 200, hMax: 500 },
      { scroll: 0.3, color: '#160d0a', spacing: 180, hMin: 300, hMax: 700 },
      { scroll: 0.5, color: '#050505', spacing: 160, hMin: 400, hMax: 850 },
    ];

    layers.forEach((layer, li) => {
      ctx.fillStyle = layer.color;
      const startX = Math.floor((camX * layer.scroll) / layer.spacing) * layer.spacing - layer.spacing * 2;

      for (let x = startX; x < startX + CANVAS_WIDTH + layer.spacing * 4; x += layer.spacing) {
        const seed = Math.abs(Math.sin(x * 0.007 + li));
        const h = seed * (layer.hMax - layer.hMin) + layer.hMin;
        const bx = x - (camX * layer.scroll);
        const bw = layer.spacing - 30;
        ctx.fillRect(bx, GROUND_Y - h, bw, h);

        // Burning windows and flickering fire effects
        if (li >= 1) {
          const fireInt = Math.sin(x * 0.5 + e.frame * 0.04);
          if (fireInt > 0.3) {
            ctx.fillStyle = fireInt > 0.8 ? '#ff8800' : '#bb3300';
            // Window grids
            for (let row = 0; row < 8; row++) {
              if (Math.cos(x + row) > 0.1) {
                const winY = GROUND_Y - h + 50 + row * 60;
                if (winY < GROUND_Y - 20) {
                  ctx.fillRect(bx + 20, winY, 25, 20);
                  ctx.fillRect(bx + bw - 45, winY, 25, 20);
                }
              }
            }
            // Roof fires
            const flicker = Math.sin(e.frame * 0.25 + x) * 12;
            ctx.beginPath();
            ctx.moveTo(bx + bw * 0.1, GROUND_Y - h);
            ctx.lineTo(bx + bw * 0.5, GROUND_Y - h - 40 - flicker);
            ctx.lineTo(bx + bw * 0.9, GROUND_Y - h);
            ctx.fill();
          }
          ctx.fillStyle = layer.color;
        }
      }
    });
  };

  const drawHUD = (ctx: CanvasRenderingContext2D, e: any) => {
    ctx.save();
    const hudX = 40;
    const hudY = 40;
    const hudW = 340;
    const hudH = e.isCombined ? 100 : e.players.length * 36 + 45;

    ctx.fillStyle = 'rgba(0, 0, 0, 0.8)';
    ctx.fillRect(hudX, hudY, hudW, hudH);
    ctx.strokeStyle = 'rgba(0, 243, 255, 0.7)';
    ctx.lineWidth = 3;
    ctx.strokeRect(hudX, hudY, hudW, hudH);

    ctx.font = 'bold 15px Orbitron';
    ctx.fillStyle = '#00f3ff';
    ctx.fillText(e.isCombined ? "MEGA EARTHBOT ONLINE" : "SQUAD ALPHA: SECTOR STATUS", hudX + 20, hudY + 30);

    if (e.isCombined) {
      const hRatio = Math.max(0, e.combinedHealth / e.combinedMaxHealth);
      ctx.fillStyle = '#facc15';
      ctx.fillText("CHASSIS INTEGRITY", hudX + 20, hudY + 60);
      ctx.fillStyle = '#111';
      ctx.fillRect(hudX + 20, hudY + 70, 300, 14);
      ctx.fillStyle = '#facc15';
      ctx.fillRect(hudX + 20, hudY + 70, 300 * hRatio, 14);
    } else {
      e.players.forEach((p: PlayerEntity, i: number) => {
        const stats = ROBOT_STATS[p.unit];
        const hRatio = Math.max(0, p.health / p.maxHealth);
        const y = hudY + 65 + i * 36;
        ctx.fillStyle = p.health > 0 ? stats.color : '#444';
        ctx.fillText(stats.name, hudX + 20, y);
        ctx.fillStyle = '#111';
        ctx.fillRect(hudX + 20, y + 10, 280, 8);
        ctx.fillStyle = p.health > 0 ? stats.color : '#222';
        ctx.fillRect(hudX + 20, y + 10, 280 * hRatio, 8);
      });
    }
    ctx.restore();
  };

  useEffect(() => {
    const e = engineRef.current;
    const handleKeyDown = (ev: KeyboardEvent) => {
      e.keys[ev.code] = true;
      if ((ev.code === 'ShiftLeft' || ev.code === 'ShiftRight') && !e.isCombined) {
        e.players.forEach(p => p.isTransformed = !p.isTransformed);
      }
      if (ev.code === 'KeyC') {
        if (e.isCombined) {
          e.isCombined = false;
          const hPer = e.combinedHealth / e.players.length;
          e.players.forEach((p, i) => { 
            p.health = Math.min(p.maxHealth, hPer); 
            p.width = 32; p.height = 48; 
            p.pos.x = e.players[0].pos.x - i * 55; 
            p.pos.y = GROUND_Y - 48; 
          });
        } else if (upgrades.unlockedUnits.length >= 5) {
          e.isCombined = true;
          e.combinedMaxHealth = e.players.reduce((s, p) => s + p.maxHealth, 0) * 1.2;
          e.combinedHealth = e.players.reduce((s, p) => s + p.health, 0) * 1.2;
          e.players[0].width = 64; e.players[0].height = 96;
        }
      }
    };
    const handleKeyUp = (ev: KeyboardEvent) => { e.keys[ev.code] = false; };
    window.addEventListener('keydown', handleKeyDown); window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => { if (!e.isPaused) update(); draw(); animationId = requestAnimationFrame(loop); };

    const update = () => {
      e.frame++;
      const leader = e.players[0]; if (!leader) { onDie(); return; }
      const moveRight = e.keys['ArrowRight'] || e.keys['KeyD'];
      const moveLeft = e.keys['ArrowLeft'] || e.keys['KeyA'];
      const firing = e.keys['Space'];

      if (e.isCombined) {
        const s = { speed: 5, fireRate: 6 };
        if (moveRight) { leader.vel.x = s.speed; leader.facing = 1; } else if (moveLeft) { leader.vel.x = -s.speed; leader.facing = -1; } else leader.vel.x *= 0.85;
        leader.pos.x += leader.vel.x; 
        leader.pos.y = GROUND_Y - leader.height;
        if (firing && e.frame - leader.lastShot > s.fireRate) {
          soundService.playShoot();
          for(let i=-1; i<=1; i++) e.bullets.push({ pos: { x: leader.pos.x + 40, y: leader.pos.y + 50 + (i*20) }, vel: { x: leader.facing * 25, y: i * 2 }, width: 35, height: 12, owner: 'player', damage: 180, color: '#facc15', health: 1, maxHealth: 1 });
          leader.lastShot = e.frame;
        }
      } else {
        e.players.forEach((p, i) => {
          if (p.health <= 0) return;
          const stats = ROBOT_STATS[p.unit]; const s = p.isTransformed ? stats.alt : stats.robot;
          if (i === 0) {
            if (moveRight) { p.vel.x = s.speed; p.facing = 1; } else if (moveLeft) { p.vel.x = -s.speed; p.facing = -1; } else p.vel.x *= 0.8;
          } else {
            const targetX = leader.pos.x - (i * 60 * leader.facing); const dist = targetX - p.pos.x;
            if (Math.abs(dist) > 30) { p.vel.x = Math.sign(dist) * s.speed * 0.9; p.facing = Math.sign(dist) || 1; } else p.vel.x *= 0.8;
          }
          p.pos.x += p.vel.x; 
          p.pos.y = GROUND_Y - p.height; // Players always on ground
          if (firing && e.frame - p.lastShot > s.fireRate) {
            soundService.playShoot();
            e.bullets.push({ pos: { x: p.pos.x + 20, y: p.pos.y + 25 }, vel: { x: p.facing * 20, y: 0 }, width: 18, height: 8, owner: 'player', damage: 100, color: stats.color, health: 1, maxHealth: 1 });
            p.lastShot = e.frame;
          }
          if (p.invulnerable > 0) p.invulnerable--;
        });
      }

      for (let i = e.bullets.length - 1; i >= 0; i--) {
        const b = e.bullets[i]; b.pos.x += b.vel.x; b.pos.y += b.vel.y || 0;
        if (b.owner === 'enemy') {
          if (e.isCombined) {
            if (!leader.invulnerable && b.pos.x < leader.pos.x + leader.width && b.pos.x + b.width > leader.pos.x && b.pos.y < leader.pos.y + leader.height && b.pos.y + b.height > leader.pos.y) {
              e.combinedHealth -= 60; leader.invulnerable = 30; e.bullets.splice(i, 1); if (e.combinedHealth <= 0) onDie();
            }
          } else {
            e.players.forEach(p => { if (p.health > 0 && !p.invulnerable && b.pos.x < p.pos.x + p.width && b.pos.x + b.width > p.pos.x && b.pos.y < p.pos.y + p.height && b.pos.y + b.height > p.pos.y) { p.health -= 25; p.invulnerable = 40; e.bullets.splice(i, 1); } });
          }
        }
        if (Math.abs(b.pos.x - leader.pos.x) > 2200) e.bullets.splice(i, 1);
      }

      let enemiesAlive = 0;
      e.enemies.forEach(en => {
        if (en.isDead) return; enemiesAlive++;

        // Movement logic
        en.pos.x += Math.sign(leader.pos.x - en.pos.x) * 0.8;
        if (en.type === 'helicopter') {
          // Helicopter bobs and stays in air
          en.pos.y = 200 + Math.sin(e.frame * 0.05 + en.id) * 50;
        } else {
          // All other robots must be on ground
          en.pos.y = GROUND_Y - en.height;
        }

        if (Math.abs(en.pos.x - leader.pos.x) < 1100 && e.frame - en.lastShot > 90) {
          const dy = en.type === 'helicopter' ? 10 : 30;
          e.bullets.push({ pos: { x: en.pos.x, y: en.pos.y + dy }, vel: { x: Math.sign(leader.pos.x - en.pos.x) * 11, y: 0 }, width: 18, height: 8, owner: 'enemy', health: 1, maxHealth: 1, damage: 30, color: '#f00' });
          en.lastShot = e.frame;
        }

        e.bullets.forEach((b, bi) => { 
          if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) { 
            en.health -= b.damage || 100; 
            if (en.health <= 0) en.isDead = true; 
            e.bullets.splice(bi, 1); 
          } 
        });
      });

      if (enemiesAlive === 0) onWin();
      if (!e.isCombined && e.players.every(p => p.health <= 0)) onDie();

      // Camera
      e.cameraX = leader.pos.x - 600;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const leader = e.players[0]; if (!leader) return;

      drawCityscape(ctx, e);

      ctx.save(); ctx.translate(-e.cameraX, 0);

      // Ground Platform with glowing grid
      ctx.fillStyle = '#10101c'; 
      ctx.fillRect(e.cameraX - 1200, GROUND_Y, CANVAS_WIDTH + 2400, 300);
      ctx.strokeStyle = '#00f3ff33'; ctx.lineWidth = 3;
      for (let gx = Math.floor((e.cameraX - 1200) / 70) * 70; gx < e.cameraX + 2800; gx += 70) { ctx.beginPath(); ctx.moveTo(gx, GROUND_Y); ctx.lineTo(gx, GROUND_Y + 300); ctx.stroke(); }

      e.enemies.forEach(en => { 
        if(!en.isDead) drawUnit(ctx, en.pos.x, en.pos.y, en.width, en.height, RobotUnit.SENTINEL, Math.sign(leader.pos.x - en.pos.x), e.frame, true, false, false, 1.3, false, en.type); 
      });

      if (e.isCombined) drawUnit(ctx, leader.pos.x, leader.pos.y, leader.width, leader.height, leader.unit, leader.facing, e.frame, false, leader.invulnerable > 0, false, 1, true);
      else e.players.forEach(p => { if(p.health > 0) drawUnit(ctx, p.pos.x, p.pos.y, p.width, p.height, p.unit, p.facing, e.frame, false, p.invulnerable > 0, p.isTransformed, 1); });

      e.bullets.forEach(b => { ctx.fillStyle = b.color || '#fff'; ctx.fillRect(b.pos.x, b.pos.y, b.width, b.height); });
      ctx.restore();

      drawHUD(ctx, e);
    };
    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [onWin, onDie, upgrades, level]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden font-orbitron">
      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full max-h-[100vh] aspect-video shadow-[0_0_120px_rgba(0,0,0,1)] border-2 border-cyan-900/40" />
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 1600;
const CANVAS_HEIGHT = 900;
const GROUND_Y = 750;

interface PlayerEntity {
  unit: RobotUnit;
  pos: { x: number; y: number };
  vel: { x: number; y: number };
  width: number;
  height: number;
  facing: number;
  grounded: boolean;
  lastShot: number;
  invulnerable: number;
  health: number;
  maxHealth: number;
  isTransformed: boolean;
  id: string;
}

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { name: "SENTINEL", color: '#ffffff', hpMult: 1.0, robot: { speed: 5, fireRate: 15 }, alt: { speed: 10, fireRate: 25, type: 'Police Car' }},
  [RobotUnit.STRIKER]: { name: "STRIKER", color: '#fbbf24', hpMult: 0.8, robot: { speed: 7, fireRate: 10 }, alt: { speed: 15, fireRate: 20, type: 'Bike' }},
  [RobotUnit.FALCON]: { name: "FALCON", color: '#22d3ee', hpMult: 0.7, robot: { speed: 6, fireRate: 12 }, alt: { speed: 9, fireRate: 15, type: 'Jet' }},
  [RobotUnit.TITAN]: { name: "TITAN", color: '#ef4444', hpMult: 2.5, robot: { speed: 3.5, fireRate: 30 }, alt: { speed: 5, fireRate: 20, type: 'Tank' }},
  [RobotUnit.SPECTER]: { name: "SPECTER", color: '#a855f7', hpMult: 0.6, robot: { speed: 6, fireRate: 20 }, alt: { speed: 8, fireRate: 40, type: 'Ambulance' }},
  [RobotUnit.VANGUARD]: { name: "VANGUARD", color: '#10b981', hpMult: 2.0, robot: { speed: 4.5, fireRate: 25 }, alt: { speed: 8, fireRate: 30, type: 'Fire Truck' }},
  [RobotUnit.NIGHTSHADE]: { name: "NIGHTSHADE", color: '#6366f1', hpMult: 0.9, robot: { speed: 8, fireRate: 12 }, alt: { speed: 12, fireRate: 18, type: 'Cyber Tiger' }},
  [RobotUnit.BLAZE]: { name: "BLAZE", color: '#f97316', hpMult: 1.2, robot: { speed: 5.5, fireRate: 18 }, alt: { speed: 14, fireRate: 15, type: 'Canon Race Car' }},
  [RobotUnit.GLITCH]: { name: "GLITCH", color: '#ec4899', hpMult: 1.0, robot: { speed: 6, fireRate: 14 }, alt: { speed: 12, fireRate: 16, type: 'Flying Car' }},
  [RobotUnit.OMEGA]: { name: "OMEGA", color: '#ffffff', hpMult: 3.0, robot: { speed: 8, fireRate: 10 }, alt: { speed: 10, fireRate: 10, type: 'Combat Blimp' }},
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const engineRef = useRef({
    players: [] as PlayerEntity[],
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    cameraY: 0,
    isPaused: isPaused,
    level: level,
    upgrades: upgrades,
    isCombined: false,
    combinedHealth: 0,
    combinedMaxHealth: 0,
  });

  useEffect(() => { 
    engineRef.current.isPaused = isPaused; 
    engineRef.current.level = level;
    engineRef.current.upgrades = upgrades;
  }, [isPaused, level, upgrades]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff88');
    grad.addColorStop(1, '#000000aa');
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.6)';
    ctx.lineWidth = 1;
    ctx.stroke();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, alpha = 1, sizeMult = 1) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8 * sizeMult;
    const armSwing = Math.cos(time) * 10 * sizeMult;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(sizeMult, sizeMult);
    drawMechanicalPart(ctx, -12, -18, 24, 28, color, 4); // Torso
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6); // Head
    ctx.fillStyle = isEnemy ? '#ff0000' : '#00f3ff'; 
    ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2); // Visor
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2); // Left Arm
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2); // Right Arm
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2); // Left Leg
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2); // Right Leg
    ctx.restore();
  };

  const drawHelicopter = (ctx: CanvasRenderingContext2D, color: string, frame: number, alpha = 1) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    drawMechanicalPart(ctx, -25, -10, 50, 25, '#333', 12); // Body
    drawMechanicalPart(ctx, -50, -5, 30, 8, '#222', 2); // Tail
    const rotorWidth = 80 * Math.sin(frame * 0.8);
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(-rotorWidth/2, -18);
    ctx.lineTo(rotorWidth/2, -18);
    ctx.stroke();
    ctx.fillStyle = '#ff0000';
    ctx.fillRect(15, -2, 8, 8); // Lights
    ctx.restore();
  };

  const drawPoliceCar = (ctx: CanvasRenderingContext2D, frame: number, alpha = 1) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    // Main Body
    drawMechanicalPart(ctx, -30, -10, 60, 22, '#fff', 4);
    drawMechanicalPart(ctx, -30, -5, 60, 17, '#000', 2);
    // Roof/Lights
    drawMechanicalPart(ctx, -10, -20, 20, 10, '#111', 2);
    const sirenFlicker = Math.sin(frame * 0.5) > 0;
    ctx.fillStyle = sirenFlicker ? '#f00' : '#00f';
    ctx.fillRect(-8, -20, 16, 4);
    // Wheels
    ctx.fillStyle = '#111';
    ctx.beginPath(); ctx.arc(-20, 12, 8, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(20, 12, 8, 0, Math.PI * 2); ctx.fill();
    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy: boolean, invulnerable: boolean, transformed: boolean, alpha: number, isCombiner = false, type: string = 'grunt') => {
    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    ctx.scale(facing < 0 ? -1 : 1, 1);
    const drawAlpha = invulnerable ? (0.5 + Math.sin(frame * 0.5) * 0.3) * alpha : alpha;

    if (isCombiner) {
      ctx.save(); ctx.translate(0, -30);
      drawHumanoid(ctx, '#facc15', frame, false, drawAlpha, 2.5);
      const coreGlow = 0.4 + Math.sin(frame * 0.2) * 0.3;
      ctx.beginPath(); ctx.arc(0, -10, 8, 0, Math.PI * 2); ctx.fillStyle = `rgba(0, 243, 255, ${coreGlow})`; ctx.fill();
      ctx.restore();
    } else if (type === 'helicopter') {
      drawHelicopter(ctx, '#444', frame, drawAlpha);
    } else if (transformed) {
      if (unit === RobotUnit.SENTINEL) {
        drawPoliceCar(ctx, frame, drawAlpha);
      } else {
        drawMechanicalPart(ctx, -25, -12, 50, 24, ROBOT_STATS[unit].color, 6);
      }
    } else {
      drawHumanoid(ctx, isEnemy ? '#ff0055' : ROBOT_STATS[unit].color, frame, isEnemy, drawAlpha);
    }
    ctx.restore();
  };

  const createPlayer = (unit: RobotUnit, x: number, y: number): PlayerEntity => {
    const stats = ROBOT_STATS[unit];
    const baseHP = 100 + (engineRef.current.upgrades.robotTier * 50);
    return { id: Math.random().toString(36).substr(2, 9), unit, pos: { x, y: GROUND_Y - 48 }, vel: { x: 0, y: 0 }, width: 32, height: 48, facing: 1, grounded: true, lastShot: 0, invulnerable: 0, health: baseHP * stats.hpMult, maxHealth: baseHP * stats.hpMult, isTransformed: false };
  };

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    e.frame = 0; e.cameraX = 0; e.bullets = []; e.isCombined = false;
    e.players = upgrades.unlockedUnits.map((unit, i) => createPlayer(unit, 100 - i * 60, GROUND_Y - 48));

    // Exactly 5 enemies
    const enemyCount = 5;
    e.enemies = Array.from({ length: enemyCount }, (_, i) => {
      const isHelicopter = i >= 3 && level > 2; // Only 2 helicopters max per early level if level > 2
      const type = isHelicopter ? 'helicopter' : 'grunt';
      const width = isHelicopter ? 80 : 48;
      const height = isHelicopter ? 50 : 72;
      const startY = isHelicopter ? 150 + Math.random() * 250 : GROUND_Y - height;

      return { 
        id: i, 
        pos: { x: 1500 + i * 600, y: startY }, 
        vel: { x: 0, y: 0 }, 
        width, 
        height, 
        health: 120 + (level * 20), 
        maxHealth: 120 + (level * 20), 
        isDead: false, 
        type, 
        lastShot: 0 
      };
    });
  }, [level, upgrades]);

  useEffect(() => { resetLevel(); }, [resetLevel]);

  const drawCityscape = (ctx: CanvasRenderingContext2D, e: any) => {
    const camX = e.cameraX;

    // Sky
    const skyGrad = ctx.createLinearGradient(0, 0, 0, CANVAS_HEIGHT);
    skyGrad.addColorStop(0, '#010105');
    skyGrad.addColorStop(0.6, '#1a0805');
    skyGrad.addColorStop(1, '#441100');
    ctx.fillStyle = skyGrad;
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    const layers = [
      { scroll: 0.1, color: '#0a0a14', spacing: 250, hMin: 300, hMax: 600 },
      { scroll: 0.4, color: '#160d0a', spacing: 200, hMin: 400, hMax: 800 },
      { scroll: 0.7, color: '#030303', spacing: 180, hMin: 500, hMax: 900 },
    ];

    layers.forEach((layer, li) => {
      ctx.fillStyle = layer.color;
      const startX = Math.floor((camX * layer.scroll) / layer.spacing) * layer.spacing - layer.spacing * 2;

      for (let x = startX; x < startX + CANVAS_WIDTH + layer.spacing * 4; x += layer.spacing) {
        const seed = Math.abs(Math.sin(x * 0.01 + li));
        const h = seed * (layer.hMax - layer.hMin) + layer.hMin;
        const bx = x - (camX * layer.scroll);
        const bw = layer.spacing - 20;
        ctx.fillRect(bx, GROUND_Y - h, bw, h);

        // Detailed burning buildings
        if (li >= 1) {
          const fireSeed = Math.sin(x * 0.7 + e.frame * 0.03);
          if (fireSeed > 0.2) {
            ctx.fillStyle = fireSeed > 0.8 ? '#ffcc00' : '#ee4400';
            // Windows glowing with fire
            for (let r = 0; r < 10; r++) {
              for (let c = 0; c < 3; c++) {
                const winX = bx + 20 + c * (bw / 4);
                const winY = GROUND_Y - h + 60 + r * 70;
                if (winY < GROUND_Y - 40 && Math.cos(x + r + c) > 0) {
                  ctx.fillRect(winX, winY, 15, 25);
                }
              }
            }
            // Roof flame plumes
            const flicker = Math.sin(e.frame * 0.3 + x) * 15;
            ctx.beginPath();
            ctx.moveTo(bx + 10, GROUND_Y - h);
            ctx.bezierCurveTo(bx + bw / 2, GROUND_Y - h - 60 - flicker, bx + bw / 2, GROUND_Y - h - 60 - flicker, bx + bw - 10, GROUND_Y - h);
            ctx.fill();
          }
          ctx.fillStyle = layer.color;
        }
      }
    });
  };

  const drawHUD = (ctx: CanvasRenderingContext2D, e: any) => {
    ctx.save();
    const hudX = 50;
    const hudY = 50;
    const hudW = 380;
    const hudH = e.isCombined ? 110 : e.players.length * 38 + 50;

    ctx.fillStyle = 'rgba(0, 0, 0, 0.85)';
    ctx.fillRect(hudX, hudY, hudW, hudH);
    ctx.strokeStyle = '#00f3ff';
    ctx.lineWidth = 3;
    ctx.strokeRect(hudX, hudY, hudW, hudH);

    ctx.font = 'bold 16px Orbitron';
    ctx.fillStyle = '#00f3ff';
    ctx.fillText(e.isCombined ? "ULTIMATE COMBINER ONLINE" : "SQUAD STATUS: SECTOR " + e.level, hudX + 25, hudY + 35);

    if (e.isCombined) {
      const hRatio = Math.max(0, e.combinedHealth / e.combinedMaxHealth);
      ctx.fillStyle = '#facc15';
      ctx.fillText("COMBINED CHASSIS INTEGRITY", hudX + 25, hudY + 65);
      ctx.fillStyle = '#111';
      ctx.fillRect(hudX + 25, hudY + 75, 330, 16);
      ctx.fillStyle = '#facc15';
      ctx.fillRect(hudX + 25, hudY + 75, 330 * hRatio, 16);
    } else {
      e.players.forEach((p: PlayerEntity, i: number) => {
        const stats = ROBOT_STATS[p.unit];
        const hRatio = Math.max(0, p.health / p.maxHealth);
        const y = hudY + 70 + i * 38;
        ctx.fillStyle = p.health > 0 ? stats.color : '#444';
        ctx.fillText(stats.name + (p.isTransformed ? " [" + stats.alt.type + "]" : ""), hudX + 25, y);
        ctx.fillStyle = '#111';
        ctx.fillRect(hudX + 25, y + 10, 300, 10);
        ctx.fillStyle = p.health > 0 ? stats.color : '#222';
        ctx.fillRect(hudX + 25, y + 10, 300 * hRatio, 10);
      });
    }
    ctx.restore();
  };

  useEffect(() => {
    const e = engineRef.current;
    const handleKeyDown = (ev: KeyboardEvent) => {
      e.keys[ev.code] = true;
      if ((ev.code === 'ShiftLeft' || ev.code === 'ShiftRight') && !e.isCombined) {
        e.players.forEach(p => p.isTransformed = !p.isTransformed);
      }
      if (ev.code === 'KeyC') {
        if (e.isCombined) {
          e.isCombined = false;
          const hPer = e.combinedHealth / e.players.length;
          e.players.forEach((p, i) => { 
            p.health = Math.min(p.maxHealth, hPer); 
            p.width = 32; p.height = 48; 
            p.pos.x = e.players[0].pos.x - i * 65; 
            p.pos.y = GROUND_Y - 48; 
          });
        } else if (upgrades.unlockedUnits.length >= 5) {
          e.isCombined = true;
          e.combinedMaxHealth = e.players.reduce((s, p) => s + p.maxHealth, 0) * 1.5;
          e.combinedHealth = e.players.reduce((s, p) => s + p.health, 0) * 1.5;
          e.players[0].width = 80; e.players[0].height = 120;
        }
      }
    };
    const handleKeyUp = (ev: KeyboardEvent) => { e.keys[ev.code] = false; };
    window.addEventListener('keydown', handleKeyDown); window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => { if (!e.isPaused) update(); draw(); animationId = requestAnimationFrame(loop); };

    const update = () => {
      e.frame++;
      const leader = e.players[0]; if (!leader) { onDie(); return; }
      const moveRight = e.keys['ArrowRight'] || e.keys['KeyD'];
      const moveLeft = e.keys['ArrowLeft'] || e.keys['KeyA'];
      const firing = e.keys['Space'];

      if (e.isCombined) {
        const s = { speed: 5, fireRate: 5 };
        if (moveRight) { leader.vel.x = s.speed; leader.facing = 1; } else if (moveLeft) { leader.vel.x = -s.speed; leader.facing = -1; } else leader.vel.x *= 0.8;
        leader.pos.x += leader.vel.x; 
        leader.pos.y = GROUND_Y - leader.height;
        if (firing && e.frame - leader.lastShot > s.fireRate) {
          soundService.playShoot();
          for(let i=-2; i<=2; i++) e.bullets.push({ pos: { x: leader.pos.x + 50, y: leader.pos.y + 60 + (i*20) }, vel: { x: leader.facing * 30, y: i * 2.5 }, width: 40, height: 12, owner: 'player', damage: 200, color: '#facc15', health: 1, maxHealth: 1 });
          leader.lastShot = e.frame;
        }
      } else {
        e.players.forEach((p, i) => {
          if (p.health <= 0) return;
          const stats = ROBOT_STATS[p.unit]; const s = p.isTransformed ? stats.alt : stats.robot;
          if (i === 0) {
            if (moveRight) { p.vel.x = s.speed; p.facing = 1; } else if (moveLeft) { p.vel.x = -s.speed; p.facing = -1; } else p.vel.x *= 0.8;
          } else {
            const targetX = leader.pos.x - (i * 70 * leader.facing); const dist = targetX - p.pos.x;
            if (Math.abs(dist) > 35) { p.vel.x = Math.sign(dist) * s.speed * 0.95; p.facing = Math.sign(dist) || 1; } else p.vel.x *= 0.8;
          }
          p.pos.x += p.vel.x; 
          p.pos.y = GROUND_Y - p.height; // Always on ground
          if (firing && e.frame - p.lastShot > s.fireRate) {
            soundService.playShoot();
            e.bullets.push({ pos: { x: p.pos.x + 20, y: p.pos.y + 25 }, vel: { x: p.facing * 22, y: 0 }, width: 22, height: 10, owner: 'player', damage: 100 + (upgrades.weaponTier * 10), color: stats.color, health: 1, maxHealth: 1 });
            p.lastShot = e.frame;
          }
          if (p.invulnerable > 0) p.invulnerable--;
        });
      }

      for (let i = e.bullets.length - 1; i >= 0; i--) {
        const b = e.bullets[i]; b.pos.x += b.vel.x; b.pos.y += b.vel.y || 0;
        if (b.owner === 'enemy') {
          if (e.isCombined) {
            if (!leader.invulnerable && b.pos.x < leader.pos.x + leader.width && b.pos.x + b.width > leader.pos.x && b.pos.y < leader.pos.y + leader.height && b.pos.y + b.height > leader.pos.y) {
              e.combinedHealth -= 80; leader.invulnerable = 25; e.bullets.splice(i, 1); if (e.combinedHealth <= 0) onDie();
            }
          } else {
            e.players.forEach(p => { if (p.health > 0 && !p.invulnerable && b.pos.x < p.pos.x + p.width && b.pos.x + b.width > p.pos.x && b.pos.y < p.pos.y + p.height && b.pos.y + b.height > p.pos.y) { p.health -= 35; p.invulnerable = 40; e.bullets.splice(i, 1); } });
          }
        }
        if (Math.abs(b.pos.x - leader.pos.x) > 2500) e.bullets.splice(i, 1);
      }

      let enemiesAlive = 0;
      e.enemies.forEach(en => {
        if (en.isDead) return; enemiesAlive++;

        en.pos.x += Math.sign(leader.pos.x - en.pos.x) * 1.2;
        if (en.type === 'helicopter') {
          en.pos.y = 150 + Math.sin(e.frame * 0.04 + en.id) * 60;
        } else {
          en.pos.y = GROUND_Y - en.height; // Robot enemies on ground
        }

        if (Math.abs(en.pos.x - leader.pos.x) < 1200 && e.frame - en.lastShot > 80) {
          const dy = en.type === 'helicopter' ? 15 : 35;
          e.bullets.push({ pos: { x: en.pos.x, y: en.pos.y + dy }, vel: { x: Math.sign(leader.pos.x - en.pos.x) * 12, y: 0 }, width: 20, height: 10, owner: 'enemy', health: 1, maxHealth: 1, damage: 30, color: '#f00' });
          en.lastShot = e.frame;
        }

        e.bullets.forEach((b, bi) => { 
          if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) { 
            en.health -= b.damage || 100; 
            if (en.health <= 0) en.isDead = true; 
            e.bullets.splice(bi, 1); 
          } 
        });
      });

      if (enemiesAlive === 0) onWin();
      if (!e.isCombined && e.players.every(p => p.health <= 0)) onDie();

      e.cameraX = leader.pos.x - 600;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const leader = e.players[0]; if (!leader) return;

      drawCityscape(ctx, e);

      ctx.save(); ctx.translate(-e.cameraX, 0);

      // Cyber-Street Ground
      ctx.fillStyle = '#0a0a0f'; 
      ctx.fillRect(e.cameraX - 1500, GROUND_Y, CANVAS_WIDTH + 3000, 300);
      ctx.strokeStyle = '#00f3ff22'; ctx.lineWidth = 4;
      for (let gx = Math.floor((e.cameraX - 1500) / 80) * 80; gx < e.cameraX + 3500; gx += 80) { ctx.beginPath(); ctx.moveTo(gx, GROUND_Y); ctx.lineTo(gx, GROUND_Y + 300); ctx.stroke(); }

      e.enemies.forEach(en => { 
        if(!en.isDead) drawUnit(ctx, en.pos.x, en.pos.y, en.width, en.height, RobotUnit.SENTINEL, Math.sign(leader.pos.x - en.pos.x), e.frame, true, false, false, 1.4, false, en.type); 
      });

      if (e.isCombined) drawUnit(ctx, leader.pos.x, leader.pos.y, leader.width, leader.height, leader.unit, leader.facing, e.frame, false, leader.invulnerable > 0, false, 1, true);
      else e.players.forEach(p => { if(p.health > 0) drawUnit(ctx, p.pos.x, p.pos.y, p.width, p.height, p.unit, p.facing, e.frame, false, p.invulnerable > 0, p.isTransformed, 1); });

      e.bullets.forEach(b => { ctx.fillStyle = b.color || '#fff'; ctx.fillRect(b.pos.x, b.pos.y, b.width, b.height); });
      ctx.restore();

      drawHUD(ctx, e);
    };
    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [onWin, onDie, upgrades, level]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden font-orbitron">
      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full max-h-[100vh] aspect-video shadow-[0_0_150px_rgba(0,0,0,1)] border-b-4 border-cyan-500/20" />
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 1600;
const CANVAS_HEIGHT = 900;
const GRAVITY = 0.5;
const GROUND_Y = 750;

interface PlayerEntity {
  unit: RobotUnit;
  pos: { x: number; y: number };
  vel: { x: number; y: number };
  width: number;
  height: number;
  facing: number;
  grounded: boolean;
  lastShot: number;
  invulnerable: number;
  health: number;
  maxHealth: number;
  isTransformed: boolean;
  id: string;
}

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { name: "SENTINEL", color: '#ffffff', hpMult: 1.0, robot: { speed: 5, jump: -12, fireRate: 15 }, alt: { speed: 10, jump: -6, fireRate: 25, type: 'Police Car' }},
  [RobotUnit.STRIKER]: { name: "STRIKER", color: '#fbbf24', hpMult: 0.8, robot: { speed: 7, jump: -10, fireRate: 10 }, alt: { speed: 15, jump: -4, fireRate: 20, type: 'Police Motorcycle' }},
  [RobotUnit.FALCON]: { name: "FALCON", color: '#22d3ee', hpMult: 0.7, robot: { speed: 6, jump: -15, fireRate: 12 }, alt: { speed: 12, jump: -12, fireRate: 15, type: 'Jet' }},
  [RobotUnit.TITAN]: { name: "TITAN", color: '#ef4444', hpMult: 2.5, robot: { speed: 3.5, jump: -13, fireRate: 30 }, alt: { speed: 5, jump: 0, fireRate: 20, type: 'Tank' }},
  [RobotUnit.SPECTER]: { name: "SPECTER", color: '#a855f7', hpMult: 0.6, robot: { speed: 6, jump: -11, fireRate: 20 }, alt: { speed: 8, jump: -5, fireRate: 40, type: 'Ambulance' }},
  [RobotUnit.VANGUARD]: { name: "VANGUARD", color: '#10b981', hpMult: 2.0, robot: { speed: 4.5, jump: -12, fireRate: 25 }, alt: { speed: 7, jump: -4, fireRate: 30, type: 'Fire Truck' }},
  [RobotUnit.NIGHTSHADE]: { name: "NIGHTSHADE", color: '#6366f1', hpMult: 0.9, robot: { speed: 8, jump: -14, fireRate: 12 }, alt: { speed: 12, jump: -10, fireRate: 18, type: 'Cyber Tiger' }},
  [RobotUnit.BLAZE]: { name: "BLAZE", color: '#f97316', hpMult: 1.2, robot: { speed: 5.5, jump: -11, fireRate: 18 }, alt: { speed: 18, jump: -6, fireRate: 15, type: 'Race Car' }},
  [RobotUnit.GLITCH]: { name: "GLITCH", color: '#ec4899', hpMult: 1.0, robot: { speed: 6, jump: -12, fireRate: 14 }, alt: { speed: 12, jump: -12, fireRate: 16, type: 'Flying Car' }},
  [RobotUnit.OMEGA]: { name: "OMEGA", color: '#ffffff', hpMult: 3.0, robot: { speed: 8, jump: -16, fireRate: 10 }, alt: { speed: 6, jump: -8, fireRate: 10, type: 'Blimp' }},
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const engineRef = useRef({
    players: [] as PlayerEntity[],
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    cameraY: 0,
    isPaused: isPaused,
    level: level,
    upgrades: upgrades,
    isCombined: false,
    combinedHealth: 0,
    combinedMaxHealth: 0,
  });

  useEffect(() => { 
    engineRef.current.isPaused = isPaused; 
    engineRef.current.level = level;
    engineRef.current.upgrades = upgrades;
  }, [isPaused, level, upgrades]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff88');
    grad.addColorStop(1, '#000000aa');
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.6)';
    ctx.lineWidth = 1;
    ctx.stroke();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, frame: number, alpha: number) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    const color = ROBOT_STATS[unit].color;

    switch (unit) {
      case RobotUnit.SENTINEL: // Police Car
        drawMechanicalPart(ctx, -30, -10, 60, 24, '#eee', 4);
        drawMechanicalPart(ctx, -30, 0, 60, 14, '#111', 2);
        const siren = Math.sin(frame * 0.5) > 0;
        ctx.fillStyle = siren ? '#f00' : '#00f'; ctx.fillRect(-10, -18, 20, 8);
        break;
      case RobotUnit.STRIKER: // Motorcycle
        drawMechanicalPart(ctx, -20, -5, 40, 15, color, 8);
        ctx.fillStyle = '#111'; ctx.beginPath(); ctx.arc(-15, 10, 8, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(15, 10, 8, 0, Math.PI * 2); ctx.fill();
        break;
      case RobotUnit.FALCON: // Jet
        ctx.beginPath(); ctx.moveTo(-35, 0); ctx.lineTo(25, -15); ctx.lineTo(35, 0); ctx.lineTo(25, 15); ctx.closePath();
        ctx.fillStyle = color; ctx.fill();
        drawMechanicalPart(ctx, -10, -5, 30, 10, '#333', 2);
        break;
      case RobotUnit.TITAN: // Tank
        drawMechanicalPart(ctx, -35, -5, 70, 25, '#222', 2); // Treads
        drawMechanicalPart(ctx, -25, -20, 50, 20, color, 4); // Turret
        drawMechanicalPart(ctx, 10, -15, 40, 8, '#111', 1); // Barrel
        break;
      case RobotUnit.SPECTER: // Ambulance
        drawMechanicalPart(ctx, -30, -15, 60, 30, '#fff', 4);
        ctx.fillStyle = '#a855f7'; ctx.fillRect(-5, -5, 10, 10); ctx.fillRect(-15, -2, 30, 4);
        break;
      case RobotUnit.VANGUARD: // Fire Truck
        drawMechanicalPart(ctx, -40, -15, 80, 32, '#d92b2b', 2);
        drawMechanicalPart(ctx, -35, -25, 60, 10, '#888', 1); // Ladder
        break;
      case RobotUnit.NIGHTSHADE: // Cyber Tiger
        const legMov = Math.sin(frame * 0.2) * 10;
        drawMechanicalPart(ctx, -25, -15, 50, 20, color, 10); // Body
        drawMechanicalPart(ctx, 20, -20, 15, 15, color, 4); // Head
        drawMechanicalPart(ctx, -20, 5, 8, 15 + legMov, '#111', 2); // Leg
        drawMechanicalPart(ctx, 10, 5, 8, 15 - legMov, '#111', 2); // Leg
        break;
      case RobotUnit.BLAZE: // Race Car
        drawMechanicalPart(ctx, -35, 0, 70, 18, color, 2);
        drawMechanicalPart(ctx, -20, -8, 30, 8, '#111', 10); // Cockpit
        drawMechanicalPart(ctx, -45, -5, 20, 5, color, 1); // Spoiler
        break;
      case RobotUnit.GLITCH: // Flying Car
        drawMechanicalPart(ctx, -30, -10, 60, 22, color, 12);
        const hoverGlow = 0.5 + Math.sin(frame * 0.3) * 0.3;
        ctx.fillStyle = `rgba(0, 243, 255, ${hoverGlow})`;
        ctx.beginPath(); ctx.arc(-20, 12, 10, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(20, 12, 10, 0, Math.PI * 2); ctx.fill();
        break;
      case RobotUnit.OMEGA: // Blimp
        drawMechanicalPart(ctx, -60, -40, 120, 70, '#fff', 35);
        drawMechanicalPart(ctx, -20, 30, 40, 15, '#444', 4); // Gondola
        break;
      default:
        drawMechanicalPart(ctx, -25, -12, 50, 24, color, 6);
    }
    ctx.restore();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, alpha = 1, sizeMult = 1) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8 * sizeMult;
    const armSwing = Math.cos(time) * 10 * sizeMult;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(sizeMult, sizeMult);
    drawMechanicalPart(ctx, -12, -18, 24, 28, color, 4);
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? '#ff0000' : '#00f3ff'; 
    ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);
    ctx.restore();
  };

  const drawHelicopter = (ctx: CanvasRenderingContext2D, frame: number, alpha = 1) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    drawMechanicalPart(ctx, -30, -10, 60, 30, '#333', 15);
    drawMechanicalPart(ctx, -60, -5, 35, 10, '#222', 2);
    const rotorWidth = 100 * Math.sin(frame * 1.0);
    ctx.strokeStyle = '#fff'; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(-rotorWidth/2, -22); ctx.lineTo(rotorWidth/2, -22); ctx.stroke();
    ctx.fillStyle = '#f00'; ctx.fillRect(15, 0, 10, 10);
    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy: boolean, invulnerable: boolean, transformed: boolean, alpha: number, isCombiner = false, type: string = 'grunt') => {
    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    ctx.scale(facing < 0 ? -1 : 1, 1);
    const drawAlpha = invulnerable ? (0.5 + Math.sin(frame * 0.5) * 0.3) * alpha : alpha;

    if (isCombiner) {
      ctx.save(); ctx.translate(0, -30);
      drawHumanoid(ctx, '#facc15', frame, false, drawAlpha, 2.8);
      ctx.restore();
    } else if (type === 'helicopter') {
      drawHelicopter(ctx, frame, drawAlpha);
    } else if (transformed) {
      drawAltMode(ctx, unit, frame, drawAlpha);
    } else {
      drawHumanoid(ctx, isEnemy ? '#ff0055' : ROBOT_STATS[unit].color, frame, isEnemy, drawAlpha);
    }
    ctx.restore();
  };

  const createPlayer = (unit: RobotUnit, x: number, y: number): PlayerEntity => {
    const stats = ROBOT_STATS[unit];
    const baseHP = 100 + (engineRef.current.upgrades.robotTier * 50);
    return { id: Math.random().toString(36).substr(2, 9), unit, pos: { x, y: GROUND_Y - 48 }, vel: { x: 0, y: 0 }, width: 32, height: 48, facing: 1, grounded: true, lastShot: 0, invulnerable: 0, health: baseHP * stats.hpMult, maxHealth: baseHP * stats.hpMult, isTransformed: false };
  };

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    e.frame = 0; e.cameraX = 0; e.bullets = []; e.isCombined = false;
    e.players = upgrades.unlockedUnits.map((unit, i) => createPlayer(unit, 100 - i * 65, GROUND_Y - 48));

    // Exactly 5 enemies as requested
    const enemyCount = 5;
    e.enemies = Array.from({ length: enemyCount }, (_, i) => {
      const isHelicopter = i >= 3 && level > 1; 
      const type = isHelicopter ? 'helicopter' : 'grunt';
      const width = isHelicopter ? 100 : 48;
      const height = isHelicopter ? 60 : 72;
      const startY = isHelicopter ? 100 + Math.random() * 300 : GROUND_Y - height;

      return { 
        id: i, 
        pos: { x: 1600 + i * 700, y: startY }, 
        vel: { x: 0, y: 0 }, 
        width, 
        height, 
        health: 150 + (level * 25), 
        maxHealth: 150 + (level * 25), 
        isDead: false, 
        type, 
        lastShot: 0 
      };
    });
  }, [level, upgrades]);

  useEffect(() => { resetLevel(); }, [resetLevel]);

  const drawCityscape = (ctx: CanvasRenderingContext2D, e: any) => {
    const camX = e.cameraX;
    const skyGrad = ctx.createLinearGradient(0, 0, 0, CANVAS_HEIGHT);
    skyGrad.addColorStop(0, '#000008');
    skyGrad.addColorStop(0.7, '#1e0a05');
    skyGrad.addColorStop(1, '#552200');
    ctx.fillStyle = skyGrad; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    const layers = [
      { scroll: 0.1, color: '#0a0a14', spacing: 300, hMin: 300, hMax: 600 },
      { scroll: 0.4, color: '#160d0a', spacing: 250, hMin: 400, hMax: 850 },
      { scroll: 0.8, color: '#030303', spacing: 200, hMin: 500, hMax: 1000 },
    ];

    layers.forEach((layer, li) => {
      ctx.fillStyle = layer.color;
      const startX = Math.floor((camX * layer.scroll) / layer.spacing) * layer.spacing - layer.spacing * 2;
      for (let x = startX; x < startX + CANVAS_WIDTH + layer.spacing * 4; x += layer.spacing) {
        const seed = Math.abs(Math.sin(x * 0.01 + li));
        const h = seed * (layer.hMax - layer.hMin) + layer.hMin;
        const bx = x - (camX * layer.scroll);
        const bw = layer.spacing - 30;
        ctx.fillRect(bx, GROUND_Y - h, bw, h);
        if (li >= 1) {
          const fireSeed = Math.sin(x * 0.8 + e.frame * 0.04);
          if (fireSeed > 0.1) {
            ctx.fillStyle = fireSeed > 0.7 ? '#ffaa00' : '#cc3300';
            for (let r = 0; r < 8; r++) {
              const winY = GROUND_Y - h + 50 + r * 70;
              if (winY < GROUND_Y - 50) {
                ctx.fillRect(bx + 15, winY, 15, 20);
                ctx.fillRect(bx + bw - 30, winY, 15, 20);
              }
            }
            const flicker = Math.sin(e.frame * 0.4 + x) * 15;
            ctx.beginPath(); ctx.moveTo(bx + 5, GROUND_Y - h);
            ctx.lineTo(bx + bw/2, GROUND_Y - h - 50 - flicker);
            ctx.lineTo(bx + bw - 5, GROUND_Y - h); ctx.fill();
          }
          ctx.fillStyle = layer.color;
        }
      }
    });
  };

  const drawHUD = (ctx: CanvasRenderingContext2D, e: any) => {
    ctx.save();
    const hudX = 60; const hudY = 60;
    const hudW = 420; const hudH = e.isCombined ? 120 : e.players.length * 42 + 60;
    ctx.fillStyle = 'rgba(0, 0, 0, 0.9)'; ctx.fillRect(hudX, hudY, hudW, hudH);
    ctx.strokeStyle = '#00f3ff'; ctx.lineWidth = 3; ctx.strokeRect(hudX, hudY, hudW, hudH);
    ctx.font = 'bold 18px Orbitron'; ctx.fillStyle = '#00f3ff';
    ctx.fillText(e.isCombined ? "WAR-READY COMBINER" : "SQUAD STATUS: SECTOR " + e.level, hudX + 25, hudY + 40);

    if (e.isCombined) {
      const hRatio = Math.max(0, e.combinedHealth / e.combinedMaxHealth);
      ctx.fillStyle = '#facc15'; ctx.fillText("CHASSIS INTEGRITY", hudX + 25, hudY + 75);
      ctx.fillStyle = '#111'; ctx.fillRect(hudX + 25, hudY + 85, 370, 20);
      ctx.fillStyle = '#facc15'; ctx.fillRect(hudX + 25, hudY + 85, 370 * hRatio, 20);
    } else {
      e.players.forEach((p: PlayerEntity, i: number) => {
        const stats = ROBOT_STATS[p.unit];
        const hRatio = Math.max(0, p.health / p.maxHealth);
        const y = hudY + 80 + i * 42;
        ctx.fillStyle = p.health > 0 ? stats.color : '#444';
        ctx.fillText(stats.name + (p.isTransformed ? " (" + stats.alt.type + ")" : ""), hudX + 25, y);
        ctx.fillStyle = '#111'; ctx.fillRect(hudX + 25, y + 10, 350, 10);
        ctx.fillStyle = p.health > 0 ? stats.color : '#222';
        ctx.fillRect(hudX + 25, y + 10, 350 * hRatio, 10);
      });
    }
    ctx.restore();
  };

  useEffect(() => {
    const e = engineRef.current;
    const handleKeyDown = (ev: KeyboardEvent) => {
      e.keys[ev.code] = true;
      if ((ev.code === 'ShiftLeft' || ev.code === 'ShiftRight') && !e.isCombined) {
        e.players.forEach(p => p.isTransformed = !p.isTransformed);
      }
      if (ev.code === 'KeyC') {
        if (e.isCombined) {
          e.isCombined = false;
          const hPer = e.combinedHealth / e.players.length;
          e.players.forEach((p, i) => { 
            p.health = Math.min(p.maxHealth, hPer); 
            p.width = 32; p.height = 48; 
            p.pos.x = e.players[0].pos.x - i * 70; 
            p.pos.y = GROUND_Y - 48; 
          });
        } else if (upgrades.unlockedUnits.length >= 5) {
          e.isCombined = true;
          e.combinedMaxHealth = e.players.reduce((s, p) => s + p.maxHealth, 0) * 1.5;
          e.combinedHealth = e.players.reduce((s, p) => s + p.health, 0) * 1.5;
          e.players[0].width = 100; e.players[0].height = 140;
        }
      }
    };
    const handleKeyUp = (ev: KeyboardEvent) => { e.keys[ev.code] = false; };
    window.addEventListener('keydown', handleKeyDown); window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => { if (!e.isPaused) update(); draw(); animationId = requestAnimationFrame(loop); };

    const update = () => {
      e.frame++;
      const leader = e.players[0]; if (!leader) { onDie(); return; }
      const moveRight = e.keys['ArrowRight'] || e.keys['KeyD'];
      const moveLeft = e.keys['ArrowLeft'] || e.keys['KeyA'];
      const moveUp = e.keys['ArrowUp'] || e.keys['KeyW'];
      const firing = e.keys['Space'];

      if (e.isCombined) {
        const s = { speed: 5, jump: -18, fireRate: 5 };
        if (moveRight) { leader.vel.x = s.speed; leader.facing = 1; } else if (moveLeft) { leader.vel.x = -s.speed; leader.facing = -1; } else leader.vel.x *= 0.8;
        if (moveUp && leader.grounded) { leader.vel.y = s.jump; leader.grounded = false; }
        leader.vel.y += GRAVITY; leader.pos.x += leader.vel.x; leader.pos.y += leader.vel.y;
        if (leader.pos.y > GROUND_Y - leader.height) { leader.pos.y = GROUND_Y - leader.height; leader.vel.y = 0; leader.grounded = true; }
        if (firing && e.frame - leader.lastShot > s.fireRate) {
          soundService.playShoot();
          for(let i=-2; i<=2; i++) e.bullets.push({ pos: { x: leader.pos.x + 60, y: leader.pos.y + 70 + (i*25) }, vel: { x: leader.facing * 35, y: i * 3 }, width: 45, height: 14, owner: 'player', damage: 220, color: '#facc15', health: 1, maxHealth: 1 });
          leader.lastShot = e.frame;
        }
      } else {
        e.players.forEach((p, i) => {
          if (p.health <= 0) return;
          const stats = ROBOT_STATS[p.unit]; const s = p.isTransformed ? stats.alt : stats.robot;
          if (i === 0) {
            if (moveRight) { p.vel.x = s.speed; p.facing = 1; } else if (moveLeft) { p.vel.x = -s.speed; p.facing = -1; } else p.vel.x *= 0.8;
            if (moveUp && p.grounded) { p.vel.y = s.jump; p.grounded = false; }
          } else {
            const targetX = leader.pos.x - (i * 80 * leader.facing); const dist = targetX - p.pos.x;
            if (Math.abs(dist) > 40) { p.vel.x = Math.sign(dist) * s.speed * 0.98; p.facing = Math.sign(dist) || 1; } else p.vel.x *= 0.8;
            if (leader.vel.y < -5 && p.grounded) { p.vel.y = s.jump; p.grounded = false; }
          }
          p.vel.y += GRAVITY; p.pos.x += p.vel.x; p.pos.y += p.vel.y;
          if (p.pos.y > GROUND_Y - p.height) { p.pos.y = GROUND_Y - p.height; p.vel.y = 0; p.grounded = true; }
          if (firing && e.frame - p.lastShot > s.fireRate) {
            soundService.playShoot();
            e.bullets.push({ pos: { x: p.pos.x + 20, y: p.pos.y + 25 }, vel: { x: p.facing * 25, y: 0 }, width: 25, height: 12, owner: 'player', damage: 110 + (upgrades.weaponTier * 15), color: stats.color, health: 1, maxHealth: 1 });
            p.lastShot = e.frame;
          }
          if (p.invulnerable > 0) p.invulnerable--;
        });
      }

      for (let i = e.bullets.length - 1; i >= 0; i--) {
        const b = e.bullets[i]; b.pos.x += b.vel.x; b.pos.y += b.vel.y || 0;
        if (b.owner === 'enemy') {
          if (e.isCombined) {
            if (!leader.invulnerable && b.pos.x < leader.pos.x + leader.width && b.pos.x + b.width > leader.pos.x && b.pos.y < leader.pos.y + leader.height && b.pos.y + b.height > leader.pos.y) {
              e.combinedHealth -= 80; leader.invulnerable = 20; e.bullets.splice(i, 1); if (e.combinedHealth <= 0) onDie();
            }
          } else {
            e.players.forEach(p => { if (p.health > 0 && !p.invulnerable && b.pos.x < p.pos.x + p.width && b.pos.x + b.width > p.pos.x && b.pos.y < p.pos.y + p.height && b.pos.y + b.height > p.pos.y) { p.health -= 40; p.invulnerable = 35; e.bullets.splice(i, 1); } });
          }
        }
        if (Math.abs(b.pos.x - leader.pos.x) > 3000) e.bullets.splice(i, 1);
      }

      let enemiesAlive = 0;
      e.enemies.forEach(en => {
        if (en.isDead) return; enemiesAlive++;
        en.pos.x += Math.sign(leader.pos.x - en.pos.x) * 1.5;
        if (en.type === 'helicopter') { en.pos.y = 100 + Math.sin(e.frame * 0.05 + en.id) * 80; } 
        else { en.pos.y = GROUND_Y - en.height; }

        if (Math.abs(en.pos.x - leader.pos.x) < 1300 && e.frame - en.lastShot > 70) {
          const dy = en.type === 'helicopter' ? 20 : 35;
          e.bullets.push({ pos: { x: en.pos.x, y: en.pos.y + dy }, vel: { x: Math.sign(leader.pos.x - en.pos.x) * 14, y: 0 }, width: 22, height: 12, owner: 'enemy', health: 1, maxHealth: 1, damage: 35, color: '#f00' });
          en.lastShot = e.frame;
        }
        e.bullets.forEach((b, bi) => { if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) { en.health -= b.damage || 100; if (en.health <= 0) en.isDead = true; e.bullets.splice(bi, 1); } });
      });

      if (enemiesAlive === 0) onWin();
      if (!e.isCombined && e.players.every(p => p.health <= 0)) onDie();

      e.cameraX = leader.pos.x - 600;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const leader = e.players[0]; if (!leader) return;
      drawCityscape(ctx, e);
      ctx.save(); ctx.translate(-e.cameraX, 0);
      ctx.fillStyle = '#08080c'; ctx.fillRect(e.cameraX - 2000, GROUND_Y, CANVAS_WIDTH + 4000, 300);
      ctx.strokeStyle = '#00f3ff11'; ctx.lineWidth = 4;
      for (let gx = Math.floor((e.cameraX - 2000) / 100) * 100; gx < e.cameraX + 4500; gx += 100) { ctx.beginPath(); ctx.moveTo(gx, GROUND_Y); ctx.lineTo(gx, GROUND_Y + 300); ctx.stroke(); }
      e.enemies.forEach(en => { if(!en.isDead) drawUnit(ctx, en.pos.x, en.pos.y, en.width, en.height, RobotUnit.SENTINEL, Math.sign(leader.pos.x - en.pos.x), e.frame, true, false, false, 1.5, false, en.type); });
      if (e.isCombined) drawUnit(ctx, leader.pos.x, leader.pos.y, leader.width, leader.height, leader.unit, leader.facing, e.frame, false, leader.invulnerable > 0, false, 1, true);
      else e.players.forEach(p => { if(p.health > 0) drawUnit(ctx, p.pos.x, p.pos.y, p.width, p.height, p.unit, p.facing, e.frame, false, p.invulnerable > 0, p.isTransformed, 1); });
      e.bullets.forEach(b => { ctx.fillStyle = b.color || '#fff'; ctx.fillRect(b.pos.x, b.pos.y, b.width, b.height); });
      ctx.restore();
      drawHUD(ctx, e);
    };
    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [onWin, onDie, upgrades, level]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden font-orbitron">
      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full max-h-[100vh] aspect-video shadow-[0_0_200px_rgba(0,0,0,1)]" />
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 1600;
const CANVAS_HEIGHT = 900;
const GRAVITY = 0.5;
const GROUND_Y = 750;

interface PlayerEntity {
  unit: RobotUnit;
  pos: { x: number; y: number };
  vel: { x: number; y: number };
  width: number;
  height: number;
  facing: number;
  grounded: boolean;
  lastShot: number;
  invulnerable: number;
  health: number;
  maxHealth: number;
  isTransformed: boolean;
  id: string;
}

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { name: "SENTINEL", color: '#ffffff', hpMult: 1.0, robot: { speed: 5, jump: -12, fireRate: 15 }, alt: { speed: 10, jump: -6, fireRate: 25, type: 'Police Car' }},
  [RobotUnit.STRIKER]: { name: "STRIKER", color: '#fbbf24', hpMult: 0.8, robot: { speed: 7, jump: -10, fireRate: 10 }, alt: { speed: 15, jump: -4, fireRate: 20, type: 'Police Motorcycle' }},
  [RobotUnit.FALCON]: { name: "FALCON", color: '#22d3ee', hpMult: 0.7, robot: { speed: 6, jump: -15, fireRate: 12 }, alt: { speed: 12, jump: -12, fireRate: 15, type: 'Jet' }},
  [RobotUnit.TITAN]: { name: "TITAN", color: '#ef4444', hpMult: 2.5, robot: { speed: 3.5, jump: -13, fireRate: 30 }, alt: { speed: 5, jump: 0, fireRate: 20, type: 'Tank' }},
  [RobotUnit.SPECTER]: { name: "SPECTER", color: '#a855f7', hpMult: 0.6, robot: { speed: 6, jump: -11, fireRate: 20 }, alt: { speed: 8, jump: -5, fireRate: 40, type: 'Ambulance' }},
  [RobotUnit.VANGUARD]: { name: "VANGUARD", color: '#10b981', hpMult: 2.0, robot: { speed: 4.5, jump: -12, fireRate: 25 }, alt: { speed: 7, jump: -4, fireRate: 30, type: 'Fire Truck' }},
  [RobotUnit.NIGHTSHADE]: { name: "NIGHTSHADE", color: '#6366f1', hpMult: 0.9, robot: { speed: 8, jump: -14, fireRate: 12 }, alt: { speed: 12, jump: -10, fireRate: 18, type: 'Cyber Tiger' }},
  [RobotUnit.BLAZE]: { name: "BLAZE", color: '#f97316', hpMult: 1.2, robot: { speed: 5.5, jump: -11, fireRate: 18 }, alt: { speed: 18, jump: -6, fireRate: 15, type: 'Race Car' }},
  [RobotUnit.GLITCH]: { name: "GLITCH", color: '#ec4899', hpMult: 1.0, robot: { speed: 6, jump: -12, fireRate: 14 }, alt: { speed: 12, jump: -12, fireRate: 16, type: 'Flying Car' }},
  [RobotUnit.OMEGA]: { name: "OMEGA", color: '#ffffff', hpMult: 3.0, robot: { speed: 8, jump: -16, fireRate: 10 }, alt: { speed: 6, jump: -8, fireRate: 10, type: 'Blimp' }},
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const engineRef = useRef({
    players: [] as PlayerEntity[],
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    cameraY: 0,
    isPaused: isPaused,
    level: level,
    upgrades: upgrades,
    isCombined: false,
    combinedHealth: 0,
    combinedMaxHealth: 0,
  });

  useEffect(() => { 
    engineRef.current.isPaused = isPaused; 
    engineRef.current.level = level;
    engineRef.current.upgrades = upgrades;
  }, [isPaused, level, upgrades]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff88');
    grad.addColorStop(1, '#000000aa');
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.6)';
    ctx.lineWidth = 1;
    ctx.stroke();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, frame: number, alpha: number) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    const color = ROBOT_STATS[unit].color;

    switch (unit) {
      case RobotUnit.SENTINEL: // Police Car
        drawMechanicalPart(ctx, -30, -10, 60, 24, '#eee', 4);
        drawMechanicalPart(ctx, -30, 0, 60, 14, '#111', 2);
        const siren = Math.sin(frame * 0.5) > 0;
        ctx.fillStyle = siren ? '#f00' : '#00f'; ctx.fillRect(-10, -18, 20, 8);
        break;
      case RobotUnit.STRIKER: // Motorcycle
        drawMechanicalPart(ctx, -20, -5, 40, 15, color, 8);
        ctx.fillStyle = '#111'; ctx.beginPath(); ctx.arc(-15, 10, 8, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(15, 10, 8, 0, Math.PI * 2); ctx.fill();
        break;
      case RobotUnit.FALCON: // Jet
        ctx.beginPath(); ctx.moveTo(-35, 0); ctx.lineTo(25, -15); ctx.lineTo(35, 0); ctx.lineTo(25, 15); ctx.closePath();
        ctx.fillStyle = color; ctx.fill();
        drawMechanicalPart(ctx, -10, -5, 30, 10, '#333', 2);
        break;
      case RobotUnit.TITAN: // Tank
        drawMechanicalPart(ctx, -35, -5, 70, 25, '#222', 2); // Treads
        drawMechanicalPart(ctx, -25, -20, 50, 20, color, 4); // Turret
        drawMechanicalPart(ctx, 10, -15, 40, 8, '#111', 1); // Barrel
        break;
      case RobotUnit.SPECTER: // Ambulance
        drawMechanicalPart(ctx, -30, -15, 60, 30, '#fff', 4);
        ctx.fillStyle = '#a855f7'; ctx.fillRect(-5, -5, 10, 10); ctx.fillRect(-15, -2, 30, 4);
        break;
      case RobotUnit.VANGUARD: // Fire Truck
        drawMechanicalPart(ctx, -40, -15, 80, 32, '#d92b2b', 2);
        drawMechanicalPart(ctx, -35, -25, 60, 10, '#888', 1); // Ladder
        break;
      case RobotUnit.NIGHTSHADE: // Cyber Tiger
        const legMov = Math.sin(frame * 0.2) * 10;
        drawMechanicalPart(ctx, -25, -15, 50, 20, color, 10); // Body
        drawMechanicalPart(ctx, 20, -20, 15, 15, color, 4); // Head
        drawMechanicalPart(ctx, -20, 5, 8, 15 + legMov, '#111', 2); // Leg
        drawMechanicalPart(ctx, 10, 5, 8, 15 - legMov, '#111', 2); // Leg
        break;
      case RobotUnit.BLAZE: // Race Car
        drawMechanicalPart(ctx, -35, 0, 70, 18, color, 2);
        drawMechanicalPart(ctx, -20, -8, 30, 8, '#111', 10); // Cockpit
        drawMechanicalPart(ctx, -45, -5, 20, 5, color, 1); // Spoiler
        break;
      case RobotUnit.GLITCH: // Flying Car
        drawMechanicalPart(ctx, -30, -10, 60, 22, color, 12);
        const hoverGlow = 0.5 + Math.sin(frame * 0.3) * 0.3;
        ctx.fillStyle = `rgba(0, 243, 255, ${hoverGlow})`;
        ctx.beginPath(); ctx.arc(-20, 12, 10, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(20, 12, 10, 0, Math.PI * 2); ctx.fill();
        break;
      case RobotUnit.OMEGA: // Blimp
        drawMechanicalPart(ctx, -60, -40, 120, 70, '#fff', 35);
        drawMechanicalPart(ctx, -20, 30, 40, 15, '#444', 4); // Gondola
        break;
      default:
        drawMechanicalPart(ctx, -25, -12, 50, 24, color, 6);
    }
    ctx.restore();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, alpha = 1, sizeMult = 1) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8 * sizeMult;
    const armSwing = Math.cos(time) * 10 * sizeMult;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(sizeMult, sizeMult);
    drawMechanicalPart(ctx, -12, -18, 24, 28, color, 4);
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? '#ff0000' : '#00f3ff'; 
    ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);
    ctx.restore();
  };

  const drawHelicopter = (ctx: CanvasRenderingContext2D, frame: number, alpha = 1) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    drawMechanicalPart(ctx, -30, -10, 60, 30, '#333', 15);
    drawMechanicalPart(ctx, -60, -5, 35, 10, '#222', 2);
    const rotorWidth = 100 * Math.sin(frame * 1.0);
    ctx.strokeStyle = '#fff'; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(-rotorWidth/2, -22); ctx.lineTo(rotorWidth/2, -22); ctx.stroke();
    ctx.fillStyle = '#f00'; ctx.fillRect(15, 0, 10, 10);
    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy: boolean, invulnerable: boolean, transformed: boolean, alpha: number, isCombiner = false, type: string = 'grunt') => {
    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    ctx.scale(facing < 0 ? -1 : 1, 1);
    const drawAlpha = invulnerable ? (0.5 + Math.sin(frame * 0.5) * 0.3) * alpha : alpha;

    if (isCombiner) {
      ctx.save(); ctx.translate(0, -30);
      drawHumanoid(ctx, '#facc15', frame, false, drawAlpha, 2.8);
      ctx.restore();
    } else if (type === 'helicopter') {
      drawHelicopter(ctx, frame, drawAlpha);
    } else if (transformed) {
      drawAltMode(ctx, unit, frame, drawAlpha);
    } else {
      drawHumanoid(ctx, isEnemy ? '#ff0055' : ROBOT_STATS[unit].color, frame, isEnemy, drawAlpha);
    }
    ctx.restore();
  };

  const createPlayer = (unit: RobotUnit, x: number, y: number): PlayerEntity => {
    const stats = ROBOT_STATS[unit];
    const baseHP = 100 + (engineRef.current.upgrades.robotTier * 50);
    return { id: Math.random().toString(36).substr(2, 9), unit, pos: { x, y: GROUND_Y - 48 }, vel: { x: 0, y: 0 }, width: 32, height: 48, facing: 1, grounded: true, lastShot: 0, invulnerable: 0, health: baseHP * stats.hpMult, maxHealth: baseHP * stats.hpMult, isTransformed: false };
  };

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    e.frame = 0; e.cameraX = 0; e.bullets = []; e.isCombined = false;
    e.players = upgrades.unlockedUnits.map((unit, i) => createPlayer(unit, 100 - i * 65, GROUND_Y - 48));

    const enemyCount = 5;
    e.enemies = Array.from({ length: enemyCount }, (_, i) => {
      const isHelicopter = i >= 3 && level > 1; 
      const type = isHelicopter ? 'helicopter' : 'grunt';
      const width = isHelicopter ? 100 : 48;
      const height = isHelicopter ? 60 : 72;
      const startY = isHelicopter ? 100 + Math.random() * 300 : GROUND_Y - height;

      return { 
        id: i, 
        pos: { x: 1600 + i * 700, y: startY }, 
        vel: { x: 0, y: 0 }, 
        width, 
        height, 
        health: 10, // Reduced base health, though collision logic will override
        maxHealth: 150, 
        isDead: false, 
        type, 
        lastShot: 0 
      };
    });
  }, [level, upgrades]);

  useEffect(() => { resetLevel(); }, [resetLevel]);

  const drawCityscape = (ctx: CanvasRenderingContext2D, e: any) => {
    const camX = e.cameraX;
    const skyGrad = ctx.createLinearGradient(0, 0, 0, CANVAS_HEIGHT);
    skyGrad.addColorStop(0, '#000008');
    skyGrad.addColorStop(0.7, '#1e0a05');
    skyGrad.addColorStop(1, '#552200');
    ctx.fillStyle = skyGrad; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    const layers = [
      { scroll: 0.1, color: '#0a0a14', spacing: 300, hMin: 300, hMax: 600 },
      { scroll: 0.4, color: '#160d0a', spacing: 250, hMin: 400, hMax: 850 },
      { scroll: 0.8, color: '#030303', spacing: 200, hMin: 500, hMax: 1000 },
    ];

    layers.forEach((layer, li) => {
      ctx.fillStyle = layer.color;
      const startX = Math.floor((camX * layer.scroll) / layer.spacing) * layer.spacing - layer.spacing * 2;
      for (let x = startX; x < startX + CANVAS_WIDTH + layer.spacing * 4; x += layer.spacing) {
        const seed = Math.abs(Math.sin(x * 0.01 + li));
        const h = seed * (layer.hMax - layer.hMin) + layer.hMin;
        const bx = x - (camX * layer.scroll);
        const bw = layer.spacing - 30;
        ctx.fillRect(bx, GROUND_Y - h, bw, h);
        if (li >= 1) {
          const fireSeed = Math.sin(x * 0.8 + e.frame * 0.04);
          if (fireSeed > 0.1) {
            ctx.fillStyle = fireSeed > 0.7 ? '#ffaa00' : '#cc3300';
            for (let r = 0; r < 8; r++) {
              const winY = GROUND_Y - h + 50 + r * 70;
              if (winY < GROUND_Y - 50) {
                ctx.fillRect(bx + 15, winY, 15, 20);
                ctx.fillRect(bx + bw - 30, winY, 15, 20);
              }
            }
            const flicker = Math.sin(e.frame * 0.4 + x) * 15;
            ctx.beginPath(); ctx.moveTo(bx + 5, GROUND_Y - h);
            ctx.lineTo(bx + bw/2, GROUND_Y - h - 50 - flicker);
            ctx.lineTo(bx + bw - 5, GROUND_Y - h); ctx.fill();
          }
          ctx.fillStyle = layer.color;
        }
      }
    });
  };

  const drawHUD = (ctx: CanvasRenderingContext2D, e: any) => {
    ctx.save();
    const hudX = 60; const hudY = 60;
    const hudW = 420; const hudH = e.isCombined ? 120 : e.players.length * 42 + 60;
    ctx.fillStyle = 'rgba(0, 0, 0, 0.9)'; ctx.fillRect(hudX, hudY, hudW, hudH);
    ctx.strokeStyle = '#00f3ff'; ctx.lineWidth = 3; ctx.strokeRect(hudX, hudY, hudW, hudH);
    ctx.font = 'bold 18px Orbitron'; ctx.fillStyle = '#00f3ff';
    ctx.fillText(e.isCombined ? "WAR-READY COMBINER" : "SQUAD STATUS: SECTOR " + e.level, hudX + 25, hudY + 40);

    if (e.isCombined) {
      const hRatio = Math.max(0, e.combinedHealth / e.combinedMaxHealth);
      ctx.fillStyle = '#facc15'; ctx.fillText("CHASSIS INTEGRITY", hudX + 25, hudY + 75);
      ctx.fillStyle = '#111'; ctx.fillRect(hudX + 25, hudY + 85, 370, 20);
      ctx.fillStyle = '#facc15'; ctx.fillRect(hudX + 25, hudY + 85, 370 * hRatio, 20);
    } else {
      e.players.forEach((p: PlayerEntity, i: number) => {
        const stats = ROBOT_STATS[p.unit];
        const hRatio = Math.max(0, p.health / p.maxHealth);
        const y = hudY + 80 + i * 42;
        ctx.fillStyle = p.health > 0 ? stats.color : '#444';
        ctx.fillText(stats.name + (p.isTransformed ? " (" + stats.alt.type + ")" : ""), hudX + 25, y);
        ctx.fillStyle = '#111'; ctx.fillRect(hudX + 25, y + 10, 350, 10);
        ctx.fillStyle = p.health > 0 ? stats.color : '#222';
        ctx.fillRect(hudX + 25, y + 10, 350 * hRatio, 10);
      });
    }
    ctx.restore();
  };

  useEffect(() => {
    const e = engineRef.current;
    const handleKeyDown = (ev: KeyboardEvent) => {
      e.keys[ev.code] = true;
      if ((ev.code === 'ShiftLeft' || ev.code === 'ShiftRight') && !e.isCombined) {
        e.players.forEach(p => p.isTransformed = !p.isTransformed);
      }
      if (ev.code === 'KeyC') {
        if (e.isCombined) {
          e.isCombined = false;
          const hPer = e.combinedHealth / e.players.length;
          e.players.forEach((p, i) => { 
            p.health = Math.min(p.maxHealth, hPer); 
            p.width = 32; p.height = 48; 
            p.pos.x = e.players[0].pos.x - i * 70; 
            p.pos.y = GROUND_Y - 48; 
          });
        } else if (upgrades.unlockedUnits.length >= 5) {
          e.isCombined = true;
          e.combinedMaxHealth = e.players.reduce((s, p) => s + p.maxHealth, 0) * 1.5;
          e.combinedHealth = e.players.reduce((s, p) => s + p.health, 0) * 1.5;
          e.players[0].width = 100; e.players[0].height = 140;
        }
      }
    };
    const handleKeyUp = (ev: KeyboardEvent) => { e.keys[ev.code] = false; };
    window.addEventListener('keydown', handleKeyDown); window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => { if (!e.isPaused) update(); draw(); animationId = requestAnimationFrame(loop); };

    const update = () => {
      e.frame++;
      const leader = e.players[0]; if (!leader) { onDie(); return; }
      const moveRight = e.keys['ArrowRight'] || e.keys['KeyD'];
      const moveLeft = e.keys['ArrowLeft'] || e.keys['KeyA'];
      const moveUp = e.keys['ArrowUp'] || e.keys['KeyW'];
      const firing = e.keys['Space'];

      if (e.isCombined) {
        const s = { speed: 5, jump: -18, fireRate: 5 };
        if (moveRight) { leader.vel.x = s.speed; leader.facing = 1; } else if (moveLeft) { leader.vel.x = -s.speed; leader.facing = -1; } else leader.vel.x *= 0.8;
        if (moveUp && leader.grounded) { leader.vel.y = s.jump; leader.grounded = false; }
        leader.vel.y += GRAVITY; leader.pos.x += leader.vel.x; leader.pos.y += leader.vel.y;
        if (leader.pos.y > GROUND_Y - leader.height) { leader.pos.y = GROUND_Y - leader.height; leader.vel.y = 0; leader.grounded = true; }
        if (firing && e.frame - leader.lastShot > s.fireRate) {
          soundService.playShoot();
          for(let i=-2; i<=2; i++) e.bullets.push({ pos: { x: leader.pos.x + 60, y: leader.pos.y + 70 + (i*25) }, vel: { x: leader.facing * 35, y: i * 3 }, width: 45, height: 14, owner: 'player', damage: 220, color: '#facc15', health: 1, maxHealth: 1 });
          leader.lastShot = e.frame;
        }
      } else {
        e.players.forEach((p, i) => {
          if (p.health <= 0) return;
          const stats = ROBOT_STATS[p.unit]; const s = p.isTransformed ? stats.alt : stats.robot;
          if (i === 0) {
            if (moveRight) { p.vel.x = s.speed; p.facing = 1; } else if (moveLeft) { p.vel.x = -s.speed; p.facing = -1; } else p.vel.x *= 0.8;
            if (moveUp && p.grounded) { p.vel.y = s.jump; p.grounded = false; }
          } else {
            const targetX = leader.pos.x - (i * 80 * leader.facing); const dist = targetX - p.pos.x;
            if (Math.abs(dist) > 40) { p.vel.x = Math.sign(dist) * s.speed * 0.98; p.facing = Math.sign(dist) || 1; } else p.vel.x *= 0.8;
            if (leader.vel.y < -5 && p.grounded) { p.vel.y = s.jump; p.grounded = false; }
          }
          p.vel.y += GRAVITY; p.pos.x += p.vel.x; p.pos.y += p.vel.y;
          if (p.pos.y > GROUND_Y - p.height) { p.pos.y = GROUND_Y - p.height; p.vel.y = 0; p.grounded = true; }
          if (firing && e.frame - p.lastShot > s.fireRate) {
            soundService.playShoot();
            e.bullets.push({ pos: { x: p.pos.x + 20, y: p.pos.y + 25 }, vel: { x: p.facing * 25, y: 0 }, width: 25, height: 12, owner: 'player', damage: 110 + (upgrades.weaponTier * 15), color: stats.color, health: 1, maxHealth: 1 });
            p.lastShot = e.frame;
          }
          if (p.invulnerable > 0) p.invulnerable--;
        });
      }

      for (let i = e.bullets.length - 1; i >= 0; i--) {
        const b = e.bullets[i]; b.pos.x += b.vel.x; b.pos.y += b.vel.y || 0;
        if (b.owner === 'enemy') {
          if (e.isCombined) {
            if (!leader.invulnerable && b.pos.x < leader.pos.x + leader.width && b.pos.x + b.width > leader.pos.x && b.pos.y < leader.pos.y + leader.height && b.pos.y + b.height > leader.pos.y) {
              e.combinedHealth -= 80; leader.invulnerable = 20; e.bullets.splice(i, 1); if (e.combinedHealth <= 0) onDie();
            }
          } else {
            e.players.forEach(p => { if (p.health > 0 && !p.invulnerable && b.pos.x < p.pos.x + p.width && b.pos.x + b.width > p.pos.x && b.pos.y < p.pos.y + p.height && b.pos.y + b.height > p.pos.y) { p.health -= 40; p.invulnerable = 35; e.bullets.splice(i, 1); } });
          }
        }
        if (Math.abs(b.pos.x - leader.pos.x) > 3000) e.bullets.splice(i, 1);
      }

      let enemiesAlive = 0;
      e.enemies.forEach(en => {
        if (en.isDead) return; enemiesAlive++;
        en.pos.x += Math.sign(leader.pos.x - en.pos.x) * 1.5;
        if (en.type === 'helicopter') { en.pos.y = 100 + Math.sin(e.frame * 0.05 + en.id) * 80; } 
        else { en.pos.y = GROUND_Y - en.height; }

        if (Math.abs(en.pos.x - leader.pos.x) < 1300 && e.frame - en.lastShot > 70) {
          const dy = en.type === 'helicopter' ? 20 : 35;
          e.bullets.push({ pos: { x: en.pos.x, y: en.pos.y + dy }, vel: { x: Math.sign(leader.pos.x - en.pos.x) * 14, y: 0 }, width: 22, height: 12, owner: 'enemy', health: 1, maxHealth: 1, damage: 35, color: '#f00' });
          en.lastShot = e.frame;
        }

        e.bullets.forEach((b, bi) => { 
          if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) { 
            en.isDead = true; // ONE SHOT KILL logic
            e.bullets.splice(bi, 1); 
          } 
        });
      });

      if (enemiesAlive === 0) onWin();
      if (!e.isCombined && e.players.every(p => p.health <= 0)) onDie();

      e.cameraX = leader.pos.x - 600;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const leader = e.players[0]; if (!leader) return;
      drawCityscape(ctx, e);
      ctx.save(); ctx.translate(-e.cameraX, 0);
      ctx.fillStyle = '#08080c'; ctx.fillRect(e.cameraX - 2000, GROUND_Y, CANVAS_WIDTH + 4000, 300);
      ctx.strokeStyle = '#00f3ff11'; ctx.lineWidth = 4;
      for (let gx = Math.floor((e.cameraX - 2000) / 100) * 100; gx < e.cameraX + 4500; gx += 100) { ctx.beginPath(); ctx.moveTo(gx, GROUND_Y); ctx.lineTo(gx, GROUND_Y + 300); ctx.stroke(); }
      e.enemies.forEach(en => { if(!en.isDead) drawUnit(ctx, en.pos.x, en.pos.y, en.width, en.height, RobotUnit.SENTINEL, Math.sign(leader.pos.x - en.pos.x), e.frame, true, false, false, 1.5, false, en.type); });
      if (e.isCombined) drawUnit(ctx, leader.pos.x, leader.pos.y, leader.width, leader.height, leader.unit, leader.facing, e.frame, false, leader.invulnerable > 0, false, 1, true);
      else e.players.forEach(p => { if(p.health > 0) drawUnit(ctx, p.pos.x, p.pos.y, p.width, p.height, p.unit, p.facing, e.frame, false, p.invulnerable > 0, p.isTransformed, 1); });
      e.bullets.forEach(b => { ctx.fillStyle = b.color || '#fff'; ctx.fillRect(b.pos.x, b.pos.y, b.width, b.height); });
      ctx.restore();
      drawHUD(ctx, e);
    };
    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [onWin, onDie, upgrades, level]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden font-orbitron">
      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full max-h-[100vh] aspect-video shadow-[0_0_200px_rgba(0,0,0,1)]" />
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 1600;
const CANVAS_HEIGHT = 900;
const GRAVITY = 0.5;
const GROUND_Y = 750;

interface PlayerEntity {
  unit: RobotUnit;
  pos: { x: number; y: number };
  vel: { x: number; y: number };
  width: number;
  height: number;
  facing: number;
  grounded: boolean;
  lastShot: number;
  invulnerable: number;
  health: number;
  maxHealth: number;
  isTransformed: boolean;
  id: string;
}

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { name: "SENTINEL", color: '#ffffff', hpMult: 1.0, robot: { speed: 5, jump: -12, fireRate: 15 }, alt: { speed: 10, jump: -6, fireRate: 25, type: 'Police Car' }},
  [RobotUnit.STRIKER]: { name: "STRIKER", color: '#fbbf24', hpMult: 0.8, robot: { speed: 7, jump: -10, fireRate: 10 }, alt: { speed: 15, jump: -4, fireRate: 20, type: 'Police Motorcycle' }},
  [RobotUnit.FALCON]: { name: "FALCON", color: '#22d3ee', hpMult: 0.7, robot: { speed: 6, jump: -15, fireRate: 12 }, alt: { speed: 12, jump: -12, fireRate: 15, type: 'Jet' }},
  [RobotUnit.TITAN]: { name: "TITAN", color: '#ef4444', hpMult: 2.5, robot: { speed: 3.5, jump: -13, fireRate: 30 }, alt: { speed: 5, jump: 0, fireRate: 20, type: 'Tank' }},
  [RobotUnit.SPECTER]: { name: "SPECTER", color: '#a855f7', hpMult: 0.6, robot: { speed: 6, jump: -11, fireRate: 20 }, alt: { speed: 8, jump: -5, fireRate: 40, type: 'Ambulance' }},
  [RobotUnit.VANGUARD]: { name: "VANGUARD", color: '#10b981', hpMult: 2.0, robot: { speed: 4.5, jump: -12, fireRate: 25 }, alt: { speed: 7, jump: -4, fireRate: 30, type: 'Fire Truck' }},
  [RobotUnit.NIGHTSHADE]: { name: "NIGHTSHADE", color: '#6366f1', hpMult: 0.9, robot: { speed: 8, jump: -14, fireRate: 12 }, alt: { speed: 12, jump: -10, fireRate: 18, type: 'Cyber Tiger' }},
  [RobotUnit.BLAZE]: { name: "BLAZE", color: '#f97316', hpMult: 1.2, robot: { speed: 5.5, jump: -11, fireRate: 18 }, alt: { speed: 18, jump: -6, fireRate: 15, type: 'Race Car' }},
  [RobotUnit.GLITCH]: { name: "GLITCH", color: '#ec4899', hpMult: 1.0, robot: { speed: 6, jump: -12, fireRate: 14 }, alt: { speed: 12, jump: -12, fireRate: 16, type: 'Flying Car' }},
  [RobotUnit.OMEGA]: { name: "OMEGA", color: '#ffffff', hpMult: 3.0, robot: { speed: 8, jump: -16, fireRate: 10 }, alt: { speed: 6, jump: -8, fireRate: 10, type: 'Blimp' }},
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const engineRef = useRef({
    players: [] as PlayerEntity[],
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    cameraY: 0,
    isPaused: isPaused,
    level: level,
    upgrades: upgrades,
    isCombined: false,
    combinedHealth: 0,
    combinedMaxHealth: 0,
  });

  useEffect(() => { 
    engineRef.current.isPaused = isPaused; 
    engineRef.current.level = level;
    engineRef.current.upgrades = upgrades;
  }, [isPaused, level, upgrades]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff88');
    grad.addColorStop(1, '#000000aa');
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.6)';
    ctx.lineWidth = 1;
    ctx.stroke();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, frame: number, alpha: number) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    const color = ROBOT_STATS[unit].color;

    switch (unit) {
      case RobotUnit.SENTINEL: // Police Car
        drawMechanicalPart(ctx, -35, -10, 70, 24, '#eee', 4);
        drawMechanicalPart(ctx, -35, 0, 70, 14, '#111', 2);
        const siren = Math.sin(frame * 0.5) > 0;
        ctx.fillStyle = siren ? '#f00' : '#00f'; ctx.fillRect(-12, -20, 24, 10);
        break;
      case RobotUnit.STRIKER: // Police Motorcycle
        drawMechanicalPart(ctx, -20, -8, 40, 15, color, 8);
        ctx.fillStyle = '#111'; ctx.beginPath(); ctx.arc(-18, 12, 10, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(18, 12, 10, 0, Math.PI * 2); ctx.fill();
        const sirenSmall = Math.sin(frame * 0.8) > 0;
        ctx.fillStyle = sirenSmall ? '#f00' : '#00f'; ctx.fillRect(5, -12, 10, 5);
        break;
      case RobotUnit.FALCON: // Jet
        ctx.beginPath(); ctx.moveTo(-40, 0); ctx.lineTo(30, -18); ctx.lineTo(40, 0); ctx.lineTo(30, 18); ctx.closePath();
        ctx.fillStyle = color; ctx.fill();
        drawMechanicalPart(ctx, -15, -6, 35, 12, '#333', 2);
        break;
      case RobotUnit.TITAN: // Tank
        drawMechanicalPart(ctx, -40, -5, 80, 25, '#222', 2); // Treads
        drawMechanicalPart(ctx, -30, -22, 60, 22, color, 4); // Turret
        drawMechanicalPart(ctx, 15, -16, 45, 10, '#111', 1); // Barrel
        break;
      case RobotUnit.SPECTER: // Ambulance
        drawMechanicalPart(ctx, -35, -15, 70, 32, '#fff', 4);
        ctx.fillStyle = '#a855f7'; ctx.fillRect(-6, -8, 12, 16); ctx.fillRect(-18, -2, 36, 4);
        break;
      case RobotUnit.VANGUARD: // Fire Truck
        drawMechanicalPart(ctx, -45, -15, 90, 34, '#d92b2b', 2);
        drawMechanicalPart(ctx, -40, -28, 65, 12, '#888', 1); // Ladder
        break;
      case RobotUnit.NIGHTSHADE: // Cyber Tiger
        const legMov = Math.sin(frame * 0.25) * 12;
        drawMechanicalPart(ctx, -30, -15, 60, 25, color, 12); // Body
        drawMechanicalPart(ctx, 25, -22, 18, 18, color, 4); // Head
        drawMechanicalPart(ctx, -25, 8, 10, 18 + legMov, '#111', 2); // Leg
        drawMechanicalPart(ctx, 15, 8, 10, 18 - legMov, '#111', 2); // Leg
        break;
      case RobotUnit.BLAZE: // Race Car
        drawMechanicalPart(ctx, -40, 0, 80, 20, color, 2);
        drawMechanicalPart(ctx, -25, -10, 35, 10, '#111', 12); // Cockpit
        drawMechanicalPart(ctx, -50, -8, 25, 6, color, 1); // Spoiler
        break;
      case RobotUnit.GLITCH: // Flying Car
        drawMechanicalPart(ctx, -35, -12, 70, 24, color, 15);
        const hoverGlow = 0.6 + Math.sin(frame * 0.4) * 0.4;
        ctx.fillStyle = `rgba(0, 243, 255, ${hoverGlow})`;
        ctx.beginPath(); ctx.arc(-25, 14, 12, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(25, 14, 12, 0, Math.PI * 2); ctx.fill();
        break;
      case RobotUnit.OMEGA: // Blimp
        drawMechanicalPart(ctx, -80, -50, 160, 90, '#fff', 45);
        drawMechanicalPart(ctx, -30, 40, 60, 20, '#444', 5); // Gondola
        break;
      default:
        drawMechanicalPart(ctx, -25, -12, 50, 24, color, 6);
    }
    ctx.restore();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, alpha = 1, sizeMult = 1) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8 * sizeMult;
    const armSwing = Math.cos(time) * 10 * sizeMult;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(sizeMult, sizeMult);
    drawMechanicalPart(ctx, -12, -18, 24, 28, color, 4);
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? '#ff0000' : '#00f3ff'; 
    ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);
    ctx.restore();
  };

  const drawHelicopter = (ctx: CanvasRenderingContext2D, frame: number, alpha = 1) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    drawMechanicalPart(ctx, -35, -12, 70, 35, '#333', 18);
    drawMechanicalPart(ctx, -70, -6, 40, 12, '#222', 2);
    const rotorWidth = 120 * Math.sin(frame * 1.2);
    ctx.strokeStyle = '#fff'; ctx.lineWidth = 4;
    ctx.beginPath(); ctx.moveTo(-rotorWidth/2, -25); ctx.lineTo(rotorWidth/2, -25); ctx.stroke();
    ctx.fillStyle = '#f00'; ctx.fillRect(20, 0, 12, 12);
    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy: boolean, invulnerable: boolean, transformed: boolean, alpha: number, isCombiner = false, type: string = 'grunt') => {
    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    ctx.scale(facing < 0 ? -1 : 1, 1);
    const drawAlpha = invulnerable ? (0.5 + Math.sin(frame * 0.5) * 0.3) * alpha : alpha;

    if (isCombiner) {
      ctx.save(); ctx.translate(0, -40);
      drawHumanoid(ctx, '#facc15', frame, false, drawAlpha, 3.0);
      ctx.restore();
    } else if (type === 'helicopter') {
      drawHelicopter(ctx, frame, drawAlpha);
    } else if (transformed) {
      drawAltMode(ctx, unit, frame, drawAlpha);
    } else {
      drawHumanoid(ctx, isEnemy ? '#ff0055' : ROBOT_STATS[unit].color, frame, isEnemy, drawAlpha);
    }
    ctx.restore();
  };

  const createPlayer = (unit: RobotUnit, x: number, y: number): PlayerEntity => {
    const stats = ROBOT_STATS[unit];
    const baseHP = 100 + (engineRef.current.upgrades.robotTier * 50);
    return { id: Math.random().toString(36).substr(2, 9), unit, pos: { x, y: GROUND_Y - 48 }, vel: { x: 0, y: 0 }, width: 32, height: 48, facing: 1, grounded: true, lastShot: 0, invulnerable: 0, health: baseHP * stats.hpMult, maxHealth: baseHP * stats.hpMult, isTransformed: false };
  };

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    e.frame = 0; e.cameraX = 0; e.bullets = []; e.isCombined = false;
    e.players = upgrades.unlockedUnits.map((unit, i) => createPlayer(unit, 100 - i * 70, GROUND_Y - 48));

    const enemyCount = 5;
    e.enemies = Array.from({ length: enemyCount }, (_, i) => {
      const isHelicopter = i >= 3 && level > 1; 
      const type = isHelicopter ? 'helicopter' : 'grunt';
      const width = isHelicopter ? 120 : 48;
      const height = isHelicopter ? 70 : 72;
      const startY = isHelicopter ? 100 + Math.random() * 300 : GROUND_Y - height;

      return { 
        id: i, 
        pos: { x: 1800 + i * 800, y: startY }, 
        vel: { x: 0, y: 0 }, 
        width, 
        height, 
        health: 1, // Will die in one shot
        maxHealth: 150, 
        isDead: false, 
        type, 
        lastShot: 0 
      };
    });
  }, [level, upgrades]);

  useEffect(() => { resetLevel(); }, [resetLevel]);

  const drawCityscape = (ctx: CanvasRenderingContext2D, e: any) => {
    const camX = e.cameraX;
    const skyGrad = ctx.createLinearGradient(0, 0, 0, CANVAS_HEIGHT);
    skyGrad.addColorStop(0, '#00000c');
    skyGrad.addColorStop(0.7, '#2a0d08');
    skyGrad.addColorStop(1, '#662200');
    ctx.fillStyle = skyGrad; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    const layers = [
      { scroll: 0.1, color: '#0c0c18', spacing: 350, hMin: 300, hMax: 600 },
      { scroll: 0.4, color: '#1a0f0a', spacing: 300, hMin: 400, hMax: 850 },
      { scroll: 0.8, color: '#050505', spacing: 250, hMin: 500, hMax: 1000 },
    ];

    layers.forEach((layer, li) => {
      ctx.fillStyle = layer.color;
      const startX = Math.floor((camX * layer.scroll) / layer.spacing) * layer.spacing - layer.spacing * 2;
      for (let x = startX; x < startX + CANVAS_WIDTH + layer.spacing * 4; x += layer.spacing) {
        const seed = Math.abs(Math.sin(x * 0.01 + li));
        const h = seed * (layer.hMax - layer.hMin) + layer.hMin;
        const bx = x - (camX * layer.scroll);
        const bw = layer.spacing - 40;
        ctx.fillRect(bx, GROUND_Y - h, bw, h);
        if (li >= 1) {
          const fireSeed = Math.sin(x * 0.9 + e.frame * 0.05);
          if (fireSeed > 0.1) {
            ctx.fillStyle = fireSeed > 0.7 ? '#ffbb00' : '#d43300';
            for (let r = 0; r < 10; r++) {
              const winY = GROUND_Y - h + 60 + r * 80;
              if (winY < GROUND_Y - 60) {
                ctx.fillRect(bx + 20, winY, 20, 25);
                ctx.fillRect(bx + bw - 40, winY, 20, 25);
              }
            }
            const flicker = Math.sin(e.frame * 0.5 + x) * 20;
            ctx.beginPath(); ctx.moveTo(bx + 10, GROUND_Y - h);
            ctx.lineTo(bx + bw/2, GROUND_Y - h - 60 - flicker);
            ctx.lineTo(bx + bw - 10, GROUND_Y - h); ctx.fill();
          }
          ctx.fillStyle = layer.color;
        }
      }
    });
  };

  const drawHUD = (ctx: CanvasRenderingContext2D, e: any) => {
    ctx.save();
    const hudX = 70; const hudY = 70;
    const hudW = 460; const hudH = e.isCombined ? 130 : e.players.length * 45 + 70;
    ctx.fillStyle = 'rgba(0, 0, 0, 0.92)'; ctx.fillRect(hudX, hudY, hudW, hudH);
    ctx.strokeStyle = '#00f3ff'; ctx.lineWidth = 4; ctx.strokeRect(hudX, hudY, hudW, hudH);
    ctx.font = 'bold 20px Orbitron'; ctx.fillStyle = '#00f3ff';
    ctx.fillText(e.isCombined ? "WAR-READY COMBINER ACTIVE" : "ALPHA SQUAD: SECTOR " + e.level, hudX + 30, hudY + 45);

    if (e.isCombined) {
      const hRatio = Math.max(0, e.combinedHealth / e.combinedMaxHealth);
      ctx.fillStyle = '#facc15'; ctx.fillText("ULTIMATE ARMOR INTEGRITY", hudX + 30, hudY + 85);
      ctx.fillStyle = '#111'; ctx.fillRect(hudX + 30, hudY + 95, 400, 25);
      ctx.fillStyle = '#facc15'; ctx.fillRect(hudX + 30, hudY + 95, 400 * hRatio, 25);
    } else {
      e.players.forEach((p: PlayerEntity, i: number) => {
        const stats = ROBOT_STATS[p.unit];
        const hRatio = Math.max(0, p.health / p.maxHealth);
        const y = hudY + 90 + i * 45;
        ctx.fillStyle = p.health > 0 ? stats.color : '#444';
        ctx.fillText(stats.name + (p.isTransformed ? " [" + stats.alt.type + "]" : ""), hudX + 30, y);
        ctx.fillStyle = '#111'; ctx.fillRect(hudX + 30, y + 12, 380, 12);
        ctx.fillStyle = p.health > 0 ? stats.color : '#222';
        ctx.fillRect(hudX + 30, y + 12, 380 * hRatio, 12);
      });
    }
    ctx.restore();
  };

  useEffect(() => {
    const e = engineRef.current;
    const handleKeyDown = (ev: KeyboardEvent) => {
      e.keys[ev.code] = true;
      if ((ev.code === 'ShiftLeft' || ev.code === 'ShiftRight') && !e.isCombined) {
        e.players.forEach(p => p.isTransformed = !p.isTransformed);
      }
      if (ev.code === 'KeyC') {
        if (e.isCombined) {
          e.isCombined = false;
          const hPer = e.combinedHealth / e.players.length;
          e.players.forEach((p, i) => { 
            p.health = Math.min(p.maxHealth, hPer); 
            p.width = 32; p.height = 48; 
            p.pos.x = e.players[0].pos.x - i * 80; 
            p.pos.y = GROUND_Y - 48; 
          });
        } else if (upgrades.unlockedUnits.length >= 5) {
          e.isCombined = true;
          e.combinedMaxHealth = e.players.reduce((s, p) => s + p.maxHealth, 0) * 1.5;
          e.combinedHealth = e.players.reduce((s, p) => s + p.health, 0) * 1.5;
          e.players[0].width = 110; e.players[0].height = 160;
        }
      }
    };
    const handleKeyUp = (ev: KeyboardEvent) => { e.keys[ev.code] = false; };
    window.addEventListener('keydown', handleKeyDown); window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => { if (!e.isPaused) update(); draw(); animationId = requestAnimationFrame(loop); };

    const update = () => {
      e.frame++;
      const leader = e.players[0]; if (!leader) { onDie(); return; }
      const moveRight = e.keys['ArrowRight'] || e.keys['KeyD'];
      const moveLeft = e.keys['ArrowLeft'] || e.keys['KeyA'];
      const moveUp = e.keys['ArrowUp'] || e.keys['KeyW'];
      const firing = e.keys['Space'];

      if (e.isCombined) {
        const s = { speed: 6, jump: -20, fireRate: 4 };
        if (moveRight) { leader.vel.x = s.speed; leader.facing = 1; } else if (moveLeft) { leader.vel.x = -s.speed; leader.facing = -1; } else leader.vel.x *= 0.8;
        if (moveUp && leader.grounded) { leader.vel.y = s.jump; leader.grounded = false; }
        leader.vel.y += GRAVITY; leader.pos.x += leader.vel.x; leader.pos.y += leader.vel.y;
        if (leader.pos.y > GROUND_Y - leader.height) { leader.pos.y = GROUND_Y - leader.height; leader.vel.y = 0; leader.grounded = true; }
        if (firing && e.frame - leader.lastShot > s.fireRate) {
          soundService.playShoot();
          for(let i=-2; i<=2; i++) e.bullets.push({ pos: { x: leader.pos.x + 70, y: leader.pos.y + 80 + (i*30) }, vel: { x: leader.facing * 40, y: i * 4 }, width: 50, height: 16, owner: 'player', damage: 300, color: '#facc15', health: 1, maxHealth: 1 });
          leader.lastShot = e.frame;
        }
      } else {
        e.players.forEach((p, i) => {
          if (p.health <= 0) return;
          const stats = ROBOT_STATS[p.unit]; const s = p.isTransformed ? stats.alt : stats.robot;
          if (i === 0) {
            if (moveRight) { p.vel.x = s.speed; p.facing = 1; } else if (moveLeft) { p.vel.x = -s.speed; p.facing = -1; } else p.vel.x *= 0.8;
            if (moveUp && p.grounded) { p.vel.y = s.jump; p.grounded = false; }
          } else {
            const targetX = leader.pos.x - (i * 90 * leader.facing); const dist = targetX - p.pos.x;
            if (Math.abs(dist) > 50) { p.vel.x = Math.sign(dist) * s.speed * 0.98; p.facing = Math.sign(dist) || 1; } else p.vel.x *= 0.8;
            if (leader.vel.y < -5 && p.grounded) { p.vel.y = s.jump; p.grounded = false; }
          }
          p.vel.y += GRAVITY; p.pos.x += p.vel.x; p.pos.y += p.vel.y;
          if (p.pos.y > GROUND_Y - p.height) { p.pos.y = GROUND_Y - p.height; p.vel.y = 0; p.grounded = true; }
          if (firing && e.frame - p.lastShot > s.fireRate) {
            soundService.playShoot();
            e.bullets.push({ pos: { x: p.pos.x + 25, y: p.pos.y + 30 }, vel: { x: p.facing * 30, y: 0 }, width: 30, height: 14, owner: 'player', damage: 150 + (upgrades.weaponTier * 20), color: stats.color, health: 1, maxHealth: 1 });
            p.lastShot = e.frame;
          }
          if (p.invulnerable > 0) p.invulnerable--;
        });
      }

      for (let i = e.bullets.length - 1; i >= 0; i--) {
        const b = e.bullets[i]; b.pos.x += b.vel.x; b.pos.y += b.vel.y || 0;
        if (b.owner === 'enemy') {
          if (e.isCombined) {
            if (!leader.invulnerable && b.pos.x < leader.pos.x + leader.width && b.pos.x + b.width > leader.pos.x && b.pos.y < leader.pos.y + leader.height && b.pos.y + b.height > leader.pos.y) {
              e.combinedHealth -= 100; leader.invulnerable = 25; e.bullets.splice(i, 1); if (e.combinedHealth <= 0) onDie();
            }
          } else {
            e.players.forEach(p => { if (p.health > 0 && !p.invulnerable && b.pos.x < p.pos.x + p.width && b.pos.x + b.width > p.pos.x && b.pos.y < p.pos.y + p.height && b.pos.y + b.height > p.pos.y) { p.health -= 50; p.invulnerable = 40; e.bullets.splice(i, 1); } });
          }
        }
        if (Math.abs(b.pos.x - leader.pos.x) > 4000) e.bullets.splice(i, 1);
      }

      let enemiesAlive = 0;
      e.enemies.forEach(en => {
        if (en.isDead) return; enemiesAlive++;
        en.pos.x += Math.sign(leader.pos.x - en.pos.x) * 1.8;
        if (en.type === 'helicopter') { en.pos.y = 120 + Math.sin(e.frame * 0.06 + en.id) * 100; } 
        else { en.pos.y = GROUND_Y - en.height; }

        if (Math.abs(en.pos.x - leader.pos.x) < 1400 && e.frame - en.lastShot > 60) {
          const dy = en.type === 'helicopter' ? 25 : 40;
          e.bullets.push({ pos: { x: en.pos.x, y: en.pos.y + dy }, vel: { x: Math.sign(leader.pos.x - en.pos.x) * 16, y: 0 }, width: 25, height: 14, owner: 'enemy', health: 1, maxHealth: 1, damage: 40, color: '#f00' });
          en.lastShot = e.frame;
        }

        e.bullets.forEach((b, bi) => { 
          if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) { 
            en.isDead = true; // One-shot kill enforced
            e.bullets.splice(bi, 1); 
          } 
        });
      });

      if (enemiesAlive === 0) onWin();
      if (!e.isCombined && e.players.every(p => p.health <= 0)) onDie();

      e.cameraX = leader.pos.x - 700;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const leader = e.players[0]; if (!leader) return;
      drawCityscape(ctx, e);
      ctx.save(); ctx.translate(-e.cameraX, 0);
      ctx.fillStyle = '#06060a'; ctx.fillRect(e.cameraX - 2500, GROUND_Y, CANVAS_WIDTH + 5000, 300);
      ctx.strokeStyle = '#00f3ff11'; ctx.lineWidth = 5;
      for (let gx = Math.floor((e.cameraX - 2500) / 120) * 120; gx < e.cameraX + 5500; gx += 120) { ctx.beginPath(); ctx.moveTo(gx, GROUND_Y); ctx.lineTo(gx, GROUND_Y + 300); ctx.stroke(); }
      e.enemies.forEach(en => { if(!en.isDead) drawUnit(ctx, en.pos.x, en.pos.y, en.width, en.height, RobotUnit.SENTINEL, Math.sign(leader.pos.x - en.pos.x), e.frame, true, false, false, 1.6, false, en.type); });
      if (e.isCombined) drawUnit(ctx, leader.pos.x, leader.pos.y, leader.width, leader.height, leader.unit, leader.facing, e.frame, false, leader.invulnerable > 0, false, 1, true);
      else e.players.forEach(p => { if(p.health > 0) drawUnit(ctx, p.pos.x, p.pos.y, p.width, p.height, p.unit, p.facing, e.frame, false, p.invulnerable > 0, p.isTransformed, 1); });
      e.bullets.forEach(b => { ctx.fillStyle = b.color || '#fff'; ctx.fillRect(b.pos.x, b.pos.y, b.width, b.height); });
      ctx.restore();
      drawHUD(ctx, e);
    };
    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [onWin, onDie, upgrades, level]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden font-orbitron">
      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full max-h-[100vh] aspect-video shadow-[0_0_250px_rgba(0,0,0,1)]" />
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 1600;
const CANVAS_HEIGHT = 900;
const GRAVITY = 0.5;
const GROUND_Y = 750;

interface PlayerEntity {
  unit: RobotUnit;
  pos: { x: number; y: number };
  vel: { x: number; y: number };
  width: number;
  height: number;
  facing: number;
  grounded: boolean;
  lastShot: number;
  invulnerable: number;
  health: number;
  maxHealth: number;
  isTransformed: boolean;
  id: string;
}

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { name: "SENTINEL", color: '#ffffff', hpMult: 1.0, robot: { speed: 5, jump: -12, fireRate: 15 }, alt: { speed: 10, jump: -6, fireRate: 25, type: 'Police Car' }},
  [RobotUnit.STRIKER]: { name: "STRIKER", color: '#fbbf24', hpMult: 0.8, robot: { speed: 7, jump: -10, fireRate: 10 }, alt: { speed: 15, jump: -4, fireRate: 20, type: 'Police Motorcycle' }},
  [RobotUnit.FALCON]: { name: "FALCON", color: '#22d3ee', hpMult: 0.7, robot: { speed: 6, jump: -15, fireRate: 12 }, alt: { speed: 12, jump: -12, fireRate: 15, type: 'Jet' }},
  [RobotUnit.TITAN]: { name: "TITAN", color: '#ef4444', hpMult: 2.5, robot: { speed: 3.5, jump: -13, fireRate: 30 }, alt: { speed: 5, jump: 0, fireRate: 20, type: 'Tank' }},
  [RobotUnit.SPECTER]: { name: "SPECTER", color: '#a855f7', hpMult: 0.6, robot: { speed: 6, jump: -11, fireRate: 20 }, alt: { speed: 8, jump: -5, fireRate: 40, type: 'Ambulance' }},
  [RobotUnit.VANGUARD]: { name: "VANGUARD", color: '#10b981', hpMult: 2.0, robot: { speed: 4.5, jump: -12, fireRate: 25 }, alt: { speed: 7, jump: -4, fireRate: 30, type: 'Fire Truck' }},
  [RobotUnit.NIGHTSHADE]: { name: "NIGHTSHADE", color: '#6366f1', hpMult: 0.9, robot: { speed: 8, jump: -14, fireRate: 12 }, alt: { speed: 12, jump: -10, fireRate: 18, type: 'Cyber Tiger' }},
  [RobotUnit.BLAZE]: { name: "BLAZE", color: '#f97316', hpMult: 1.2, robot: { speed: 5.5, jump: -11, fireRate: 18 }, alt: { speed: 18, jump: -6, fireRate: 15, type: 'Race Car' }},
  [RobotUnit.GLITCH]: { name: "GLITCH", color: '#ec4899', hpMult: 1.0, robot: { speed: 6, jump: -12, fireRate: 14 }, alt: { speed: 12, jump: -12, fireRate: 16, type: 'Flying Car' }},
  [RobotUnit.OMEGA]: { name: "OMEGA", color: '#ffffff', hpMult: 3.0, robot: { speed: 8, jump: -16, fireRate: 10 }, alt: { speed: 6, jump: -8, fireRate: 10, type: 'Blimp' }},
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const engineRef = useRef({
    players: [] as PlayerEntity[],
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    cameraY: 0,
    isPaused: isPaused,
    level: level,
    upgrades: upgrades,
    isCombined: false,
    combinedHealth: 0,
    combinedMaxHealth: 0,
  });

  useEffect(() => { 
    engineRef.current.isPaused = isPaused; 
    engineRef.current.level = level;
    engineRef.current.upgrades = upgrades;
  }, [isPaused, level, upgrades]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff88');
    grad.addColorStop(1, '#000000aa');
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.6)';
    ctx.lineWidth = 1;
    ctx.stroke();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, frame: number, alpha: number) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    const color = ROBOT_STATS[unit].color;

    switch (unit) {
      case RobotUnit.SENTINEL: // Police Car
        drawMechanicalPart(ctx, -35, -10, 70, 24, '#eee', 4);
        drawMechanicalPart(ctx, -35, 0, 70, 14, '#111', 2);
        const siren = Math.sin(frame * 0.5) > 0;
        ctx.fillStyle = siren ? '#f00' : '#00f'; ctx.fillRect(-12, -20, 24, 10);
        break;
      case RobotUnit.STRIKER: // Police Motorcycle
        drawMechanicalPart(ctx, -20, -8, 40, 15, color, 8);
        ctx.fillStyle = '#111'; ctx.beginPath(); ctx.arc(-18, 12, 10, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(18, 12, 10, 0, Math.PI * 2); ctx.fill();
        const sirenSmall = Math.sin(frame * 0.8) > 0;
        ctx.fillStyle = sirenSmall ? '#f00' : '#00f'; ctx.fillRect(5, -12, 10, 5);
        break;
      case RobotUnit.FALCON: // Jet
        ctx.beginPath(); ctx.moveTo(-40, 0); ctx.lineTo(30, -18); ctx.lineTo(40, 0); ctx.lineTo(30, 18); ctx.closePath();
        ctx.fillStyle = color; ctx.fill();
        drawMechanicalPart(ctx, -15, -6, 35, 12, '#333', 2);
        break;
      case RobotUnit.TITAN: // Tank
        drawMechanicalPart(ctx, -40, -5, 80, 25, '#222', 2); // Treads
        drawMechanicalPart(ctx, -30, -22, 60, 22, color, 4); // Turret
        drawMechanicalPart(ctx, 15, -16, 45, 10, '#111', 1); // Barrel
        break;
      case RobotUnit.SPECTER: // Ambulance
        drawMechanicalPart(ctx, -35, -15, 70, 32, '#fff', 4);
        ctx.fillStyle = '#a855f7'; ctx.fillRect(-6, -8, 12, 16); ctx.fillRect(-18, -2, 36, 4);
        break;
      case RobotUnit.VANGUARD: // Fire Truck
        drawMechanicalPart(ctx, -45, -15, 90, 34, '#d92b2b', 2);
        drawMechanicalPart(ctx, -40, -28, 65, 12, '#888', 1); // Ladder
        break;
      case RobotUnit.NIGHTSHADE: // Cyber Tiger
        const legMov = Math.sin(frame * 0.25) * 12;
        drawMechanicalPart(ctx, -30, -15, 60, 25, color, 12); // Body
        drawMechanicalPart(ctx, 25, -22, 18, 18, color, 4); // Head
        drawMechanicalPart(ctx, -25, 8, 10, 18 + legMov, '#111', 2); // Leg
        drawMechanicalPart(ctx, 15, 8, 10, 18 - legMov, '#111', 2); // Leg
        break;
      case RobotUnit.BLAZE: // Race Car
        drawMechanicalPart(ctx, -40, 0, 80, 20, color, 2);
        drawMechanicalPart(ctx, -25, -10, 35, 10, '#111', 12); // Cockpit
        drawMechanicalPart(ctx, -50, -8, 25, 6, color, 1); // Spoiler
        break;
      case RobotUnit.GLITCH: // Flying Car
        drawMechanicalPart(ctx, -35, -12, 70, 24, color, 15);
        const hoverGlow = 0.6 + Math.sin(frame * 0.4) * 0.4;
        ctx.fillStyle = `rgba(0, 243, 255, ${hoverGlow})`;
        ctx.beginPath(); ctx.arc(-25, 14, 12, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(25, 14, 12, 0, Math.PI * 2); ctx.fill();
        break;
      case RobotUnit.OMEGA: // Blimp
        drawMechanicalPart(ctx, -80, -50, 160, 90, '#fff', 45);
        drawMechanicalPart(ctx, -30, 40, 60, 20, '#444', 5); // Gondola
        break;
      default:
        drawMechanicalPart(ctx, -25, -12, 50, 24, color, 6);
    }
    ctx.restore();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, alpha = 1, sizeMult = 1) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8 * sizeMult;
    const armSwing = Math.cos(time) * 10 * sizeMult;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(sizeMult, sizeMult);
    drawMechanicalPart(ctx, -12, -18, 24, 28, color, 4);
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? '#ff0000' : '#00f3ff'; 
    ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);
    ctx.restore();
  };

  const drawHelicopter = (ctx: CanvasRenderingContext2D, frame: number, alpha = 1) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    drawMechanicalPart(ctx, -35, -12, 70, 35, '#333', 18);
    drawMechanicalPart(ctx, -70, -6, 40, 12, '#222', 2);
    const rotorWidth = 120 * Math.sin(frame * 1.2);
    ctx.strokeStyle = '#fff'; ctx.lineWidth = 4;
    ctx.beginPath(); ctx.moveTo(-rotorWidth/2, -25); ctx.lineTo(rotorWidth/2, -25); ctx.stroke();
    ctx.fillStyle = '#f00'; ctx.fillRect(20, 0, 12, 12);
    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy: boolean, invulnerable: boolean, transformed: boolean, alpha: number, isCombiner = false, type: string = 'grunt') => {
    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    ctx.scale(facing < 0 ? -1 : 1, 1);
    const drawAlpha = invulnerable ? (0.5 + Math.sin(frame * 0.5) * 0.3) * alpha : alpha;

    if (isCombiner) {
      ctx.save(); ctx.translate(0, -40);
      drawHumanoid(ctx, '#facc15', frame, false, drawAlpha, 3.0);
      ctx.restore();
    } else if (type === 'helicopter') {
      drawHelicopter(ctx, frame, drawAlpha);
    } else if (transformed) {
      drawAltMode(ctx, unit, frame, drawAlpha);
    } else {
      drawHumanoid(ctx, isEnemy ? '#ff0055' : ROBOT_STATS[unit].color, frame, isEnemy, drawAlpha);
    }
    ctx.restore();
  };

  const createPlayer = (unit: RobotUnit, x: number, y: number): PlayerEntity => {
    const stats = ROBOT_STATS[unit];
    const baseHP = 100 + (engineRef.current.upgrades.robotTier * 50);
    return { id: Math.random().toString(36).substr(2, 9), unit, pos: { x, y: GROUND_Y - 48 }, vel: { x: 0, y: 0 }, width: 32, height: 48, facing: 1, grounded: true, lastShot: 0, invulnerable: 0, health: baseHP * stats.hpMult, maxHealth: baseHP * stats.hpMult, isTransformed: false };
  };

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    e.frame = 0; e.cameraX = 0; e.bullets = []; e.isCombined = false;
    e.players = upgrades.unlockedUnits.map((unit, i) => createPlayer(unit, 100 - i * 70, GROUND_Y - 48));

    const enemyCount = 5;
    e.enemies = Array.from({ length: enemyCount }, (_, i) => {
      const isHelicopter = i >= 3 && level > 1; 
      const type = isHelicopter ? 'helicopter' : 'grunt';
      const width = isHelicopter ? 120 : 48;
      const height = isHelicopter ? 70 : 72;
      const startY = isHelicopter ? 100 + Math.random() * 300 : GROUND_Y - height;

      return { 
        id: i, 
        pos: { x: 1800 + i * 800, y: startY }, 
        vel: { x: 0, y: 0 }, 
        width, 
        height, 
        health: 1, // Will die in one shot
        maxHealth: 150, 
        isDead: false, 
        type, 
        lastShot: 0 
      };
    });
  }, [level, upgrades]);

  useEffect(() => { resetLevel(); }, [resetLevel]);

  const drawCityscape = (ctx: CanvasRenderingContext2D, e: any) => {
    const camX = e.cameraX;
    const skyGrad = ctx.createLinearGradient(0, 0, 0, CANVAS_HEIGHT);
    skyGrad.addColorStop(0, '#00000c');
    skyGrad.addColorStop(0.7, '#2a0d08');
    skyGrad.addColorStop(1, '#662200');
    ctx.fillStyle = skyGrad; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    const layers = [
      { scroll: 0.1, color: '#0c0c18', spacing: 350, hMin: 300, hMax: 600 },
      { scroll: 0.4, color: '#1a0f0a', spacing: 300, hMin: 400, hMax: 850 },
      { scroll: 0.8, color: '#050505', spacing: 250, hMin: 500, hMax: 1000 },
    ];

    layers.forEach((layer, li) => {
      ctx.fillStyle = layer.color;
      const startX = Math.floor((camX * layer.scroll) / layer.spacing) * layer.spacing - layer.spacing * 2;
      for (let x = startX; x < startX + CANVAS_WIDTH + layer.spacing * 4; x += layer.spacing) {
        const seed = Math.abs(Math.sin(x * 0.01 + li));
        const h = seed * (layer.hMax - layer.hMin) + layer.hMin;
        const bx = x - (camX * layer.scroll);
        const bw = layer.spacing - 40;
        ctx.fillRect(bx, GROUND_Y - h, bw, h);
        if (li >= 1) {
          const fireSeed = Math.sin(x * 0.9 + e.frame * 0.05);
          if (fireSeed > 0.1) {
            ctx.fillStyle = fireSeed > 0.7 ? '#ffbb00' : '#d43300';
            for (let r = 0; r < 10; r++) {
              const winY = GROUND_Y - h + 60 + r * 80;
              if (winY < GROUND_Y - 60) {
                ctx.fillRect(bx + 20, winY, 20, 25);
                ctx.fillRect(bx + bw - 40, winY, 20, 25);
              }
            }
            const flicker = Math.sin(e.frame * 0.5 + x) * 20;
            ctx.beginPath(); ctx.moveTo(bx + 10, GROUND_Y - h);
            ctx.lineTo(bx + bw/2, GROUND_Y - h - 60 - flicker);
            ctx.lineTo(bx + bw - 10, GROUND_Y - h); ctx.fill();
          }
          ctx.fillStyle = layer.color;
        }
      }
    });
  };

  const drawHUD = (ctx: CanvasRenderingContext2D, e: any) => {
    ctx.save();
    const hudX = 70; const hudY = 70;
    const hudW = 460; const hudH = e.isCombined ? 130 : e.players.length * 45 + 70;
    ctx.fillStyle = 'rgba(0, 0, 0, 0.92)'; ctx.fillRect(hudX, hudY, hudW, hudH);
    ctx.strokeStyle = '#00f3ff'; ctx.lineWidth = 4; ctx.strokeRect(hudX, hudY, hudW, hudH);
    ctx.font = 'bold 20px Orbitron'; ctx.fillStyle = '#00f3ff';
    ctx.fillText(e.isCombined ? "WAR-READY COMBINER ACTIVE" : "ALPHA SQUAD: SECTOR " + e.level, hudX + 30, hudY + 45);

    if (e.isCombined) {
      const hRatio = Math.max(0, e.combinedHealth / e.combinedMaxHealth);
      ctx.fillStyle = '#facc15'; ctx.fillText("ULTIMATE ARMOR INTEGRITY", hudX + 30, hudY + 85);
      ctx.fillStyle = '#111'; ctx.fillRect(hudX + 30, hudY + 95, 400, 25);
      ctx.fillStyle = '#facc15'; ctx.fillRect(hudX + 30, hudY + 95, 400 * hRatio, 25);
    } else {
      e.players.forEach((p: PlayerEntity, i: number) => {
        const stats = ROBOT_STATS[p.unit];
        const hRatio = Math.max(0, p.health / p.maxHealth);
        const y = hudY + 90 + i * 45;
        ctx.fillStyle = p.health > 0 ? stats.color : '#444';
        ctx.fillText(stats.name + (p.isTransformed ? " [" + stats.alt.type + "]" : ""), hudX + 30, y);
        ctx.fillStyle = '#111'; ctx.fillRect(hudX + 30, y + 12, 380, 12);
        ctx.fillStyle = p.health > 0 ? stats.color : '#222';
        ctx.fillRect(hudX + 30, y + 12, 380 * hRatio, 12);
      });
    }
    ctx.restore();
  };

  useEffect(() => {
    const e = engineRef.current;
    const handleKeyDown = (ev: KeyboardEvent) => {
      e.keys[ev.code] = true;
      if ((ev.code === 'ShiftLeft' || ev.code === 'ShiftRight') && !e.isCombined) {
        e.players.forEach(p => p.isTransformed = !p.isTransformed);
      }
      if (ev.code === 'KeyC') {
        if (e.isCombined) {
          e.isCombined = false;
          const hPer = e.combinedHealth / e.players.length;
          e.players.forEach((p, i) => { 
            p.health = Math.min(p.maxHealth, hPer); 
            p.width = 32; p.height = 48; 
            p.pos.x = e.players[0].pos.x - i * 80; 
            p.pos.y = GROUND_Y - 48; 
          });
        } else if (upgrades.unlockedUnits.length >= 5) {
          e.isCombined = true;
          e.combinedMaxHealth = e.players.reduce((s, p) => s + p.maxHealth, 0) * 1.5;
          e.combinedHealth = e.players.reduce((s, p) => s + p.health, 0) * 1.5;
          const firstAlive = e.players.find(p => p.health > 0);
          if (firstAlive) {
              firstAlive.width = 110; firstAlive.height = 160;
          }
        }
      }
    };
    const handleKeyUp = (ev: KeyboardEvent) => { e.keys[ev.code] = false; };
    window.addEventListener('keydown', handleKeyDown); window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => { if (!e.isPaused) update(); draw(); animationId = requestAnimationFrame(loop); };

    const update = () => {
      e.frame++;
      const activeLeaderIndex = e.players.findIndex(p => p.health > 0);
      if (activeLeaderIndex === -1) { onDie(); return; }
      const activeLeader = e.players[activeLeaderIndex];

      const moveRight = e.keys['ArrowRight'] || e.keys['KeyD'];
      const moveLeft = e.keys['ArrowLeft'] || e.keys['KeyA'];
      const moveUp = e.keys['ArrowUp'] || e.keys['KeyW'];
      const moveDown = e.keys['ArrowDown'] || e.keys['KeyS'];
      const firing = e.keys['Space'];

      if (e.isCombined) {
        const leader = activeLeader;
        const s = { speed: 6, jump: -20, fireRate: 4 };
        if (moveRight) { leader.vel.x = s.speed; leader.facing = 1; } else if (moveLeft) { leader.vel.x = -s.speed; leader.facing = -1; } else leader.vel.x *= 0.8;
        if (moveUp && leader.grounded) { leader.vel.y = s.jump; leader.grounded = false; }
        leader.vel.y += GRAVITY; leader.pos.x += leader.vel.x; leader.pos.y += leader.vel.y;
        if (leader.pos.y > GROUND_Y - leader.height) { leader.pos.y = GROUND_Y - leader.height; leader.vel.y = 0; leader.grounded = true; }
        if (firing && e.frame - leader.lastShot > s.fireRate) {
          soundService.playShoot();
          for(let i=-2; i<=2; i++) e.bullets.push({ pos: { x: leader.pos.x + 70, y: leader.pos.y + 80 + (i*30) }, vel: { x: leader.facing * 40, y: i * 4 }, width: 50, height: 16, owner: 'player', damage: 300, color: '#facc15', health: 1, maxHealth: 1 });
          leader.lastShot = e.frame;
        }
      } else {
        e.players.forEach((p, i) => {
          if (p.health <= 0) return;
          const stats = ROBOT_STATS[p.unit]; const s = p.isTransformed ? stats.alt : stats.robot;
          const isFalconJet = p.unit === RobotUnit.FALCON && p.isTransformed;

          if (i === activeLeaderIndex) {
            // Player Control
            if (moveRight) { p.vel.x = s.speed; p.facing = 1; } else if (moveLeft) { p.vel.x = -s.speed; p.facing = -1; } else p.vel.x *= 0.8;

            if (isFalconJet) {
                // Jet Flight Mechanics
                if (moveUp) p.vel.y = -s.speed;
                else if (moveDown) p.vel.y = s.speed;
                else p.vel.y *= 0.9; // Horizontal damping
                p.grounded = false;
            } else {
                // Normal Ground/Jump Mechanics
                if (moveUp && p.grounded) { p.vel.y = s.jump; p.grounded = false; }
                p.vel.y += GRAVITY;
            }
          } else {
            // Squad Follower AI
            const targetX = activeLeader.pos.x - ((i - activeLeaderIndex) * 90 * activeLeader.facing); 
            const dist = targetX - p.pos.x;
            if (Math.abs(dist) > 50) { p.vel.x = Math.sign(dist) * s.speed * 0.98; p.facing = Math.sign(dist) || 1; } else p.vel.x *= 0.8;

            if (isFalconJet) {
                // Follow leader's height if also a jet
                const hDist = activeLeader.pos.y - p.pos.y;
                if (Math.abs(hDist) > 10) p.vel.y = Math.sign(hDist) * s.speed * 0.5;
                else p.vel.y *= 0.8;
            } else {
                if (activeLeader.vel.y < -5 && p.grounded) { p.vel.y = s.jump; p.grounded = false; }
                p.vel.y += GRAVITY;
            }
          }

          p.pos.x += p.vel.x; p.pos.y += p.vel.y;

          // Collision with Ground
          if (p.pos.y > GROUND_Y - p.height) { 
              p.pos.y = GROUND_Y - p.height; 
              p.vel.y = 0; 
              p.grounded = true; 
          }
          // Clamp top
          if (p.pos.y < 50) {
              p.pos.y = 50;
              p.vel.y = 0;
          }

          if (firing && e.frame - p.lastShot > s.fireRate) {
            soundService.playShoot();
            e.bullets.push({ pos: { x: p.pos.x + 25, y: p.pos.y + 30 }, vel: { x: p.facing * 30, y: 0 }, width: 30, height: 14, owner: 'player', damage: 150 + (upgrades.weaponTier * 20), color: stats.color, health: 1, maxHealth: 1 });
            p.lastShot = e.frame;
          }
          if (p.invulnerable > 0) p.invulnerable--;
        });
      }

      // Bullets Update
      for (let i = e.bullets.length - 1; i >= 0; i--) {
        const b = e.bullets[i]; b.pos.x += b.vel.x; b.pos.y += b.vel.y || 0;
        if (b.owner === 'enemy') {
          if (e.isCombined) {
            const combinedUnit = activeLeader;
            if (!combinedUnit.invulnerable && b.pos.x < combinedUnit.pos.x + combinedUnit.width && b.pos.x + b.width > combinedUnit.pos.x && b.pos.y < combinedUnit.pos.y + combinedUnit.height && b.pos.y + b.height > combinedUnit.pos.y) {
              e.combinedHealth -= 100; combinedUnit.invulnerable = 25; e.bullets.splice(i, 1); if (e.combinedHealth <= 0) onDie();
            }
          } else {
            e.players.forEach(p => { if (p.health > 0 && !p.invulnerable && b.pos.x < p.pos.x + p.width && b.pos.x + b.width > p.pos.x && b.pos.y < p.pos.y + p.height && b.pos.y + b.height > p.pos.y) { p.health -= 50; p.invulnerable = 40; e.bullets.splice(i, 1); } });
          }
        }
        if (Math.abs(b.pos.x - activeLeader.pos.x) > 4000) e.bullets.splice(i, 1);
      }

      // Enemies Update
      let enemiesAlive = 0;
      e.enemies.forEach(en => {
        if (en.isDead) return; enemiesAlive++;
        en.pos.x += Math.sign(activeLeader.pos.x - en.pos.x) * 1.8;
        if (en.type === 'helicopter') { en.pos.y = 120 + Math.sin(e.frame * 0.06 + en.id) * 100; } 
        else { en.pos.y = GROUND_Y - en.height; }

        if (Math.abs(en.pos.x - activeLeader.pos.x) < 1400 && e.frame - en.lastShot > 60) {
          const dy = en.type === 'helicopter' ? 25 : 40;
          e.bullets.push({ pos: { x: en.pos.x, y: en.pos.y + dy }, vel: { x: Math.sign(activeLeader.pos.x - en.pos.x) * 16, y: 0 }, width: 25, height: 14, owner: 'enemy', health: 1, maxHealth: 1, damage: 40, color: '#f00' });
          en.lastShot = e.frame;
        }

        e.bullets.forEach((b, bi) => { 
          if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) { 
            en.isDead = true; 
            e.bullets.splice(bi, 1); 
          } 
        });
      });

      if (enemiesAlive === 0) onWin();
      if (!e.isCombined && e.players.every(p => p.health <= 0)) onDie();

      e.cameraX = activeLeader.pos.x - 700;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const activeLeader = e.players.find(p => p.health > 0);
      if (!activeLeader) return;

      drawCityscape(ctx, e);
      ctx.save(); ctx.translate(-e.cameraX, 0);
      ctx.fillStyle = '#06060a'; ctx.fillRect(e.cameraX - 2500, GROUND_Y, CANVAS_WIDTH + 5000, 300);
      ctx.strokeStyle = '#00f3ff11'; ctx.lineWidth = 5;
      for (let gx = Math.floor((e.cameraX - 2500) / 120) * 120; gx < e.cameraX + 5500; gx += 120) { ctx.beginPath(); ctx.moveTo(gx, GROUND_Y); ctx.lineTo(gx, GROUND_Y + 300); ctx.stroke(); }
      e.enemies.forEach(en => { if(!en.isDead) drawUnit(ctx, en.pos.x, en.pos.y, en.width, en.height, RobotUnit.SENTINEL, Math.sign(activeLeader.pos.x - en.pos.x), e.frame, true, false, false, 1.6, false, en.type); });

      if (e.isCombined) {
          drawUnit(ctx, activeLeader.pos.x, activeLeader.pos.y, activeLeader.width, activeLeader.height, activeLeader.unit, activeLeader.facing, e.frame, false, activeLeader.invulnerable > 0, false, 1, true);
      } else {
          e.players.forEach(p => { if(p.health > 0) drawUnit(ctx, p.pos.x, p.pos.y, p.width, p.height, p.unit, p.facing, e.frame, false, p.invulnerable > 0, p.isTransformed, 1); });
      }

      e.bullets.forEach(b => { ctx.fillStyle = b.color || '#fff'; ctx.fillRect(b.pos.x, b.pos.y, b.width, b.height); });
      ctx.restore();
      drawHUD(ctx, e);
    };
    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [onWin, onDie, upgrades, level]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden font-orbitron">
      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full max-h-[100vh] aspect-video shadow-[0_0_250px_rgba(0,0,0,1)]" />
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 1600;
const CANVAS_HEIGHT = 900;
const GRAVITY = 0.5;
const GROUND_Y = 750;

interface PlayerEntity {
  unit: RobotUnit;
  pos: { x: number; y: number };
  vel: { x: number; y: number };
  width: number;
  height: number;
  facing: number;
  grounded: boolean;
  lastShot: number;
  invulnerable: number;
  health: number;
  maxHealth: number;
  isTransformed: boolean;
  id: string;
}

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { name: "SENTINEL", color: '#ffffff', hpMult: 1.0, robot: { speed: 5, jump: -12, fireRate: 15 }, alt: { speed: 10, jump: -6, fireRate: 25, type: 'Police Car' }},
  [RobotUnit.STRIKER]: { name: "STRIKER", color: '#fbbf24', hpMult: 0.8, robot: { speed: 7, jump: -10, fireRate: 10 }, alt: { speed: 15, jump: -4, fireRate: 20, type: 'Police Motorcycle' }},
  [RobotUnit.FALCON]: { name: "FALCON", color: '#22d3ee', hpMult: 0.7, robot: { speed: 6, jump: -15, fireRate: 12 }, alt: { speed: 12, jump: -12, fireRate: 15, type: 'Jet' }},
  [RobotUnit.TITAN]: { name: "TITAN", color: '#ef4444', hpMult: 2.5, robot: { speed: 3.5, jump: -13, fireRate: 30 }, alt: { speed: 5, jump: 0, fireRate: 20, type: 'Tank' }},
  [RobotUnit.SPECTER]: { name: "SPECTER", color: '#a855f7', hpMult: 0.6, robot: { speed: 6, jump: -11, fireRate: 20 }, alt: { speed: 8, jump: -5, fireRate: 40, type: 'Ambulance' }},
  [RobotUnit.VANGUARD]: { name: "VANGUARD", color: '#10b981', hpMult: 2.0, robot: { speed: 4.5, jump: -12, fireRate: 25 }, alt: { speed: 7, jump: -4, fireRate: 30, type: 'Fire Truck' }},
  [RobotUnit.NIGHTSHADE]: { name: "NIGHTSHADE", color: '#6366f1', hpMult: 0.9, robot: { speed: 8, jump: -14, fireRate: 12 }, alt: { speed: 12, jump: -10, fireRate: 18, type: 'Cyber Tiger' }},
  [RobotUnit.BLAZE]: { name: "BLAZE", color: '#f97316', hpMult: 1.2, robot: { speed: 5.5, jump: -11, fireRate: 18 }, alt: { speed: 18, jump: -6, fireRate: 15, type: 'Race Car' }},
  [RobotUnit.GLITCH]: { name: "GLITCH", color: '#ec4899', hpMult: 1.0, robot: { speed: 6, jump: -12, fireRate: 14 }, alt: { speed: 12, jump: -12, fireRate: 16, type: 'Flying Car' }},
  [RobotUnit.OMEGA]: { name: "OMEGA", color: '#ffffff', hpMult: 3.0, robot: { speed: 8, jump: -16, fireRate: 10 }, alt: { speed: 6, jump: -8, fireRate: 10, type: 'Blimp' }},
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const engineRef = useRef({
    players: [] as PlayerEntity[],
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    cameraY: 0,
    isPaused: isPaused,
    level: level,
    upgrades: upgrades,
    isCombined: false,
    combinedHealth: 0,
    combinedMaxHealth: 0,
  });

  useEffect(() => { 
    engineRef.current.isPaused = isPaused; 
    engineRef.current.level = level;
    engineRef.current.upgrades = upgrades;
  }, [isPaused, level, upgrades]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff88');
    grad.addColorStop(1, '#000000aa');
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.6)';
    ctx.lineWidth = 1;
    ctx.stroke();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, frame: number, alpha: number) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    const color = ROBOT_STATS[unit].color;

    switch (unit) {
      case RobotUnit.SENTINEL: // Police Car
        drawMechanicalPart(ctx, -35, -10, 70, 24, '#eee', 4);
        drawMechanicalPart(ctx, -35, 0, 70, 14, '#111', 2);
        const siren = Math.sin(frame * 0.5) > 0;
        ctx.fillStyle = siren ? '#f00' : '#00f'; ctx.fillRect(-12, -20, 24, 10);
        break;
      case RobotUnit.STRIKER: // Police Motorcycle
        drawMechanicalPart(ctx, -20, -8, 40, 15, color, 8);
        ctx.fillStyle = '#111'; ctx.beginPath(); ctx.arc(-18, 12, 10, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(18, 12, 10, 0, Math.PI * 2); ctx.fill();
        const sirenSmall = Math.sin(frame * 0.8) > 0;
        ctx.fillStyle = sirenSmall ? '#f00' : '#00f'; ctx.fillRect(5, -12, 10, 5);
        break;
      case RobotUnit.FALCON: // Jet
        ctx.beginPath(); ctx.moveTo(-40, 0); ctx.lineTo(30, -18); ctx.lineTo(40, 0); ctx.lineTo(30, 18); ctx.closePath();
        ctx.fillStyle = color; ctx.fill();
        drawMechanicalPart(ctx, -15, -6, 35, 12, '#333', 2);
        break;
      case RobotUnit.TITAN: // Tank
        drawMechanicalPart(ctx, -40, -5, 80, 25, '#222', 2); 
        drawMechanicalPart(ctx, -30, -22, 60, 22, color, 4);
        drawMechanicalPart(ctx, 15, -16, 45, 10, '#111', 1);
        break;
      case RobotUnit.SPECTER: // Ambulance
        drawMechanicalPart(ctx, -35, -15, 70, 32, '#fff', 4);
        ctx.fillStyle = '#a855f7'; ctx.fillRect(-6, -8, 12, 16); ctx.fillRect(-18, -2, 36, 4);
        break;
      case RobotUnit.VANGUARD: // Fire Truck
        drawMechanicalPart(ctx, -45, -15, 90, 34, '#d92b2b', 2);
        drawMechanicalPart(ctx, -40, -28, 65, 12, '#888', 1);
        break;
      case RobotUnit.NIGHTSHADE: // Cyber Tiger
        const legMov = Math.sin(frame * 0.25) * 12;
        drawMechanicalPart(ctx, -30, -15, 60, 25, color, 12);
        drawMechanicalPart(ctx, 25, -22, 18, 18, color, 4);
        drawMechanicalPart(ctx, -25, 8, 10, 18 + legMov, '#111', 2);
        drawMechanicalPart(ctx, 15, 8, 10, 18 - legMov, '#111', 2);
        break;
      case RobotUnit.BLAZE: // Race Car
        drawMechanicalPart(ctx, -40, 0, 80, 20, color, 2);
        drawMechanicalPart(ctx, -25, -10, 35, 10, '#111', 12);
        drawMechanicalPart(ctx, -50, -8, 25, 6, color, 1);
        break;
      case RobotUnit.GLITCH: // Flying Car
        drawMechanicalPart(ctx, -35, -12, 70, 24, color, 15);
        const hoverGlow = 0.6 + Math.sin(frame * 0.4) * 0.4;
        ctx.fillStyle = `rgba(0, 243, 255, ${hoverGlow})`;
        ctx.beginPath(); ctx.arc(-25, 14, 12, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(25, 14, 12, 0, Math.PI * 2); ctx.fill();
        break;
      case RobotUnit.OMEGA: // Blimp
        drawMechanicalPart(ctx, -80, -50, 160, 90, '#fff', 45);
        drawMechanicalPart(ctx, -30, 40, 60, 20, '#444', 5);
        break;
      default:
        drawMechanicalPart(ctx, -25, -12, 50, 24, color, 6);
    }
    ctx.restore();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, alpha = 1, sizeMult = 1) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8 * sizeMult;
    const armSwing = Math.cos(time) * 10 * sizeMult;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(sizeMult, sizeMult);
    drawMechanicalPart(ctx, -12, -18, 24, 28, color, 4);
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? '#ff0000' : '#00f3ff'; 
    ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);
    ctx.restore();
  };

  const drawHelicopter = (ctx: CanvasRenderingContext2D, frame: number, alpha = 1) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    drawMechanicalPart(ctx, -35, -12, 70, 35, '#333', 18);
    drawMechanicalPart(ctx, -70, -6, 40, 12, '#222', 2);
    const rotorWidth = 120 * Math.sin(frame * 1.2);
    ctx.strokeStyle = '#fff'; ctx.lineWidth = 4;
    ctx.beginPath(); ctx.moveTo(-rotorWidth/2, -25); ctx.lineTo(rotorWidth/2, -25); ctx.stroke();
    ctx.fillStyle = '#f00'; ctx.fillRect(20, 0, 12, 12);
    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy: boolean, invulnerable: boolean, transformed: boolean, alpha: number, isCombiner = false, type: string = 'grunt') => {
    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    ctx.scale(facing < 0 ? -1 : 1, 1);
    const drawAlpha = invulnerable ? (0.5 + Math.sin(frame * 0.5) * 0.3) * alpha : alpha;

    if (isCombiner) {
      ctx.save(); ctx.translate(0, -40);
      drawHumanoid(ctx, '#facc15', frame, false, drawAlpha, 3.0);
      ctx.restore();
    } else if (type === 'helicopter') {
      drawHelicopter(ctx, frame, drawAlpha);
    } else if (transformed) {
      drawAltMode(ctx, unit, frame, drawAlpha);
    } else {
      drawHumanoid(ctx, isEnemy ? '#ff0055' : ROBOT_STATS[unit].color, frame, isEnemy, drawAlpha);
    }
    ctx.restore();
  };

  const createPlayer = (unit: RobotUnit, x: number, y: number): PlayerEntity => {
    const stats = ROBOT_STATS[unit];
    const baseHP = 100 + (engineRef.current.upgrades.robotTier * 50);
    return { id: Math.random().toString(36).substr(2, 9), unit, pos: { x, y: GROUND_Y - 48 }, vel: { x: 0, y: 0 }, width: 32, height: 48, facing: 1, grounded: true, lastShot: 0, invulnerable: 0, health: baseHP * stats.hpMult, maxHealth: baseHP * stats.hpMult, isTransformed: false };
  };

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    e.frame = 0; e.cameraX = 0; e.bullets = []; e.isCombined = false;
    e.players = upgrades.unlockedUnits.map((unit, i) => createPlayer(unit, 100 - i * 80, GROUND_Y - 48));

    const enemyCount = 5;
    e.enemies = Array.from({ length: enemyCount }, (_, i) => {
      const isHelicopter = i === 4 && level > 3; 
      const type = isHelicopter ? 'helicopter' : 'grunt';
      const width = isHelicopter ? 120 : 48;
      const height = isHelicopter ? 70 : 72;
      const startY = isHelicopter ? 150 : GROUND_Y - height;

      return { 
        id: i, 
        pos: { x: 1800 + i * 900, y: startY }, 
        vel: { x: 0, y: 0 }, 
        width, 
        height, 
        health: 1, // Will die in one shot
        maxHealth: 100, 
        isDead: false, 
        type, 
        lastShot: 0 
      };
    });
  }, [level, upgrades]);

  useEffect(() => { resetLevel(); }, [resetLevel]);

  const drawCityscape = (ctx: CanvasRenderingContext2D, e: any) => {
    const camX = e.cameraX;
    const skyGrad = ctx.createLinearGradient(0, 0, 0, CANVAS_HEIGHT);
    skyGrad.addColorStop(0, '#00000c');
    skyGrad.addColorStop(0.7, '#2a0d08');
    skyGrad.addColorStop(1, '#662200');
    ctx.fillStyle = skyGrad; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    const layers = [
      { scroll: 0.1, color: '#0c0c18', spacing: 400, hMin: 300, hMax: 600 },
      { scroll: 0.4, color: '#1a0f0a', spacing: 350, hMin: 400, hMax: 850 },
      { scroll: 0.8, color: '#050505', spacing: 300, hMin: 500, hMax: 1000 },
    ];

    layers.forEach((layer, li) => {
      ctx.fillStyle = layer.color;
      const startX = Math.floor((camX * layer.scroll) / layer.spacing) * layer.spacing - layer.spacing * 2;
      for (let x = startX; x < startX + CANVAS_WIDTH + layer.spacing * 4; x += layer.spacing) {
        const seed = Math.abs(Math.sin(x * 0.01 + li));
        const h = seed * (layer.hMax - layer.hMin) + layer.hMin;
        const bx = x - (camX * layer.scroll);
        const bw = layer.spacing - 40;
        ctx.fillRect(bx, GROUND_Y - h, bw, h);
        if (li >= 1) {
          const fireSeed = Math.sin(x * 0.9 + e.frame * 0.05);
          if (fireSeed > 0.1) {
            ctx.fillStyle = fireSeed > 0.7 ? '#ffbb00' : '#d43300';
            for (let r = 0; r < 10; r++) {
              const winY = GROUND_Y - h + 60 + r * 80;
              if (winY < GROUND_Y - 60) {
                ctx.fillRect(bx + 20, winY, 20, 25);
                ctx.fillRect(bx + bw - 40, winY, 20, 25);
              }
            }
            const flicker = Math.sin(e.frame * 0.5 + x) * 20;
            ctx.beginPath(); ctx.moveTo(bx + 10, GROUND_Y - h);
            ctx.lineTo(bx + bw/2, GROUND_Y - h - 60 - flicker);
            ctx.lineTo(bx + bw - 10, GROUND_Y - h); ctx.fill();
          }
          ctx.fillStyle = layer.color;
        }
      }
    });
  };

  const drawHUD = (ctx: CanvasRenderingContext2D, e: any) => {
    ctx.save();
    const hudX = 70; const hudY = 70;
    const hudW = 460; const hudH = e.isCombined ? 130 : e.players.length * 45 + 70;
    ctx.fillStyle = 'rgba(0, 0, 0, 0.92)'; ctx.fillRect(hudX, hudY, hudW, hudH);
    ctx.strokeStyle = '#00f3ff'; ctx.lineWidth = 4; ctx.strokeRect(hudX, hudY, hudW, hudH);
    ctx.font = 'bold 20px Orbitron'; ctx.fillStyle = '#00f3ff';
    ctx.fillText(e.isCombined ? "COMBINER UNIT ACTIVE" : "ALPHA SQUAD: SECTOR " + e.level, hudX + 30, hudY + 45);

    if (e.isCombined) {
      const hRatio = Math.max(0, e.combinedHealth / e.combinedMaxHealth);
      ctx.fillStyle = '#facc15'; ctx.fillText("ULTIMATE ARMOR INTEGRITY", hudX + 30, hudY + 85);
      ctx.fillStyle = '#111'; ctx.fillRect(hudX + 30, hudY + 95, 400, 25);
      ctx.fillStyle = '#facc15'; ctx.fillRect(hudX + 30, hudY + 95, 400 * hRatio, 25);
    } else {
      e.players.forEach((p: PlayerEntity, i: number) => {
        const stats = ROBOT_STATS[p.unit];
        const hRatio = Math.max(0, p.health / p.maxHealth);
        const y = hudY + 90 + i * 45;
        ctx.fillStyle = p.health > 0 ? stats.color : '#444';
        ctx.fillText(stats.name + (p.isTransformed ? " [" + stats.alt.type + "]" : ""), hudX + 30, y);
        ctx.fillStyle = '#111'; ctx.fillRect(hudX + 30, y + 12, 380, 12);
        ctx.fillStyle = p.health > 0 ? stats.color : '#222';
        ctx.fillRect(hudX + 30, y + 12, 380 * hRatio, 12);
      });
    }
    ctx.restore();
  };

  useEffect(() => {
    const e = engineRef.current;
    const handleKeyDown = (ev: KeyboardEvent) => {
      e.keys[ev.code] = true;
      if ((ev.code === 'ShiftLeft' || ev.code === 'ShiftRight') && !e.isCombined) {
        e.players.forEach(p => p.isTransformed = !p.isTransformed);
      }
      if (ev.code === 'KeyC') {
        if (e.isCombined) {
          e.isCombined = false;
          const hPer = e.combinedHealth / e.players.length;
          e.players.forEach((p, i) => { 
            p.health = Math.min(p.maxHealth, hPer); 
            p.width = 32; p.height = 48; 
            p.pos.x = e.players[0].pos.x - i * 90; 
            p.pos.y = GROUND_Y - 48; 
          });
        } else if (upgrades.unlockedUnits.length >= 5) {
          const aliveOnes = e.players.filter(p => p.health > 0);
          if (aliveOnes.length >= 5) {
            e.isCombined = true;
            e.combinedMaxHealth = e.players.reduce((s, p) => s + p.maxHealth, 0) * 1.5;
            e.combinedHealth = e.players.reduce((s, p) => s + p.health, 0) * 1.5;
            aliveOnes[0].width = 110; aliveOnes[0].height = 160;
          }
        }
      }
    };
    const handleKeyUp = (ev: KeyboardEvent) => { e.keys[ev.code] = false; };
    window.addEventListener('keydown', handleKeyDown); window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => { if (!e.isPaused) update(); draw(); animationId = requestAnimationFrame(loop); };

    const update = () => {
      e.frame++;
      const activeLeaderIndex = e.players.findIndex(p => p.health > 0);
      if (activeLeaderIndex === -1) { onDie(); return; }
      const leader = e.players[activeLeaderIndex];

      const moveRight = e.keys['ArrowRight'] || e.keys['KeyD'];
      const moveLeft = e.keys['ArrowLeft'] || e.keys['KeyA'];
      const moveUp = e.keys['ArrowUp'] || e.keys['KeyW'];
      const moveDown = e.keys['ArrowDown'] || e.keys['KeyS'];
      const firing = e.keys['Space'];

      if (e.isCombined) {
        const s = { speed: 6, jump: -22, fireRate: 4 };
        if (moveRight) { leader.vel.x = s.speed; leader.facing = 1; } else if (moveLeft) { leader.vel.x = -s.speed; leader.facing = -1; } else leader.vel.x *= 0.8;
        if (moveUp && leader.grounded) { leader.vel.y = s.jump; leader.grounded = false; }
        leader.vel.y += GRAVITY; leader.pos.x += leader.vel.x; leader.pos.y += leader.vel.y;
        if (leader.pos.y > GROUND_Y - leader.height) { leader.pos.y = GROUND_Y - leader.height; leader.vel.y = 0; leader.grounded = true; }
        if (firing && e.frame - leader.lastShot > s.fireRate) {
          soundService.playShoot();
          for(let i=-2; i<=2; i++) e.bullets.push({ pos: { x: leader.pos.x + 70, y: leader.pos.y + 80 + (i*30) }, vel: { x: leader.facing * 45, y: i * 4 }, width: 50, height: 16, owner: 'player', damage: 300, color: '#facc15', health: 1, maxHealth: 1 });
          leader.lastShot = e.frame;
        }
      } else {
        e.players.forEach((p, i) => {
          if (p.health <= 0) return;
          const stats = ROBOT_STATS[p.unit]; const s = p.isTransformed ? stats.alt : stats.robot;
          const isFalconJet = p.unit === RobotUnit.FALCON && p.isTransformed;

          if (i === activeLeaderIndex) {
            // Leader Control
            if (moveRight) { p.vel.x = s.speed; p.facing = 1; } else if (moveLeft) { p.vel.x = -s.speed; p.facing = -1; } else p.vel.x *= 0.8;

            if (isFalconJet) {
                // Jet Flight Mechanics: Ignore gravity, use Up/Down for direct vertical flight
                if (moveUp) p.vel.y = -s.speed;
                else if (moveDown) p.vel.y = s.speed;
                else p.vel.y *= 0.9;
                p.grounded = false;
            } else {
                if (moveUp && p.grounded) { p.vel.y = s.jump; p.grounded = false; }
                p.vel.y += GRAVITY;
            }
          } else {
            // Followers
            const targetX = leader.pos.x - ((i - activeLeaderIndex) * 95 * leader.facing); 
            const dist = targetX - p.pos.x;
            if (Math.abs(dist) > 50) { p.vel.x = Math.sign(dist) * s.speed * 0.98; p.facing = Math.sign(dist) || 1; } else p.vel.x *= 0.8;

            if (isFalconJet) {
                const hDist = leader.pos.y - p.pos.y;
                if (Math.abs(hDist) > 10) p.vel.y = Math.sign(hDist) * s.speed * 0.5;
                else p.vel.y *= 0.8;
            } else {
                if (leader.vel.y < -5 && p.grounded) { p.vel.y = s.jump; p.grounded = false; }
                p.vel.y += GRAVITY;
            }
          }

          p.pos.x += p.vel.x; p.pos.y += p.vel.y;
          if (p.pos.y > GROUND_Y - p.height) { p.pos.y = GROUND_Y - p.height; p.vel.y = 0; p.grounded = true; }
          if (p.pos.y < 50) { p.pos.y = 50; p.vel.y = 0; }

          if (firing && e.frame - p.lastShot > s.fireRate) {
            soundService.playShoot();
            e.bullets.push({ pos: { x: p.pos.x + 25, y: p.pos.y + 30 }, vel: { x: p.facing * 35, y: 0 }, width: 35, height: 14, owner: 'player', damage: 150, color: stats.color, health: 1, maxHealth: 1 });
            p.lastShot = e.frame;
          }
          if (p.invulnerable > 0) p.invulnerable--;
        });
      }

      // Bullet Collision
      for (let i = e.bullets.length - 1; i >= 0; i--) {
        const b = e.bullets[i]; b.pos.x += b.vel.x; b.pos.y += b.vel.y || 0;
        if (b.owner === 'enemy') {
          if (e.isCombined) {
            const combinedUnit = leader;
            if (!combinedUnit.invulnerable && b.pos.x < combinedUnit.pos.x + combinedUnit.width && b.pos.x + b.width > combinedUnit.pos.x && b.pos.y < combinedUnit.pos.y + combinedUnit.height && b.pos.y + b.height > combinedUnit.pos.y) {
              e.combinedHealth -= 100; combinedUnit.invulnerable = 25; e.bullets.splice(i, 1); if (e.combinedHealth <= 0) onDie();
            }
          } else {
            e.players.forEach(p => { if (p.health > 0 && !p.invulnerable && b.pos.x < p.pos.x + p.width && b.pos.x + b.width > p.pos.x && b.pos.y < p.pos.y + p.height && b.pos.y + b.height > p.pos.y) { p.health -= 50; p.invulnerable = 40; e.bullets.splice(i, 1); } });
          }
        }
        if (Math.abs(b.pos.x - leader.pos.x) > 4000) e.bullets.splice(i, 1);
      }

      // Enemy Logic & One-Shot Kill
      let enemiesAliveCount = 0;
      e.enemies.forEach(en => {
        if (en.isDead) return;
        enemiesAliveCount++;
        en.pos.x += Math.sign(leader.pos.x - en.pos.x) * 1.8;
        if (en.type === 'helicopter') { en.pos.y = 150 + Math.sin(e.frame * 0.05 + en.id) * 80; } 
        else { en.pos.y = GROUND_Y - en.height; }

        if (Math.abs(en.pos.x - leader.pos.x) < 1400 && e.frame - en.lastShot > 65) {
          const dy = en.type === 'helicopter' ? 25 : 40;
          e.bullets.push({ pos: { x: en.pos.x, y: en.pos.y + dy }, vel: { x: Math.sign(leader.pos.x - en.pos.x) * 15, y: 0 }, width: 25, height: 14, owner: 'enemy', health: 1, maxHealth: 1, damage: 40, color: '#ff0055' });
          en.lastShot = e.frame;
        }

        e.bullets.forEach((b, bi) => { 
          if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) { 
            en.isDead = true; 
            e.bullets.splice(bi, 1); 
            soundService.playDrive(0.5); // Use as impact sound
          } 
        });
      });

      if (enemiesAliveCount === 0) onWin();
      e.cameraX = leader.pos.x - 700;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const activeLeader = e.players.find(p => p.health > 0);
      if (!activeLeader) return;

      drawCityscape(ctx, e);
      ctx.save(); ctx.translate(-e.cameraX, 0);
      ctx.fillStyle = '#06060a'; ctx.fillRect(e.cameraX - 2500, GROUND_Y, CANVAS_WIDTH + 5000, 300);
      ctx.strokeStyle = '#00f3ff11'; ctx.lineWidth = 5;
      for (let gx = Math.floor((e.cameraX - 2500) / 120) * 120; gx < e.cameraX + 5500; gx += 120) { ctx.beginPath(); ctx.moveTo(gx, GROUND_Y); ctx.lineTo(gx, GROUND_Y + 300); ctx.stroke(); }

      e.enemies.forEach(en => { if(!en.isDead) drawUnit(ctx, en.pos.x, en.pos.y, en.width, en.height, RobotUnit.SENTINEL, Math.sign(activeLeader.pos.x - en.pos.x), e.frame, true, false, false, 1.6, false, en.type); });

      if (e.isCombined) {
          drawUnit(ctx, activeLeader.pos.x, activeLeader.pos.y, activeLeader.width, activeLeader.height, activeLeader.unit, activeLeader.facing, e.frame, false, activeLeader.invulnerable > 0, false, 1, true);
      } else {
          e.players.forEach(p => { if(p.health > 0) drawUnit(ctx, p.pos.x, p.pos.y, p.width, p.height, p.unit, p.facing, e.frame, false, p.invulnerable > 0, p.isTransformed, 1); });
      }

      e.bullets.forEach(b => { ctx.fillStyle = b.color || '#fff'; ctx.fillRect(b.pos.x, b.pos.y, b.width, b.height); });
      ctx.restore();
      drawHUD(ctx, e);
    };
    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [onWin, onDie, upgrades, level]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden font-orbitron">
      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full max-h-[100vh] aspect-video shadow-[0_0_250px_rgba(0,0,0,1)]" />
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 1600;
const CANVAS_HEIGHT = 900;
const GRAVITY = 0.5;
const GROUND_Y = 750;

interface PlayerEntity {
  unit: RobotUnit;
  pos: { x: number; y: number };
  vel: { x: number; y: number };
  width: number;
  height: number;
  facing: number;
  grounded: boolean;
  lastShot: number;
  invulnerable: number;
  health: number;
  maxHealth: number;
  isTransformed: boolean;
  id: string;
}

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { name: "SENTINEL", color: '#ffffff', hpMult: 1.0, robot: { speed: 5, jump: -12, fireRate: 15 }, alt: { speed: 10, jump: -6, fireRate: 25, type: 'Police Car' }},
  [RobotUnit.STRIKER]: { name: "STRIKER", color: '#fbbf24', hpMult: 0.8, robot: { speed: 7, jump: -10, fireRate: 10 }, alt: { speed: 15, jump: -4, fireRate: 20, type: 'Police Motorcycle' }},
  [RobotUnit.FALCON]: { name: "FALCON", color: '#22d3ee', hpMult: 0.7, robot: { speed: 6, jump: -15, fireRate: 12 }, alt: { speed: 12, jump: -12, fireRate: 15, type: 'Jet' }},
  [RobotUnit.TITAN]: { name: "TITAN", color: '#ef4444', hpMult: 2.5, robot: { speed: 3.5, jump: -13, fireRate: 30 }, alt: { speed: 5, jump: 0, fireRate: 20, type: 'Tank' }},
  [RobotUnit.SPECTER]: { name: "SPECTER", color: '#a855f7', hpMult: 0.6, robot: { speed: 6, jump: -11, fireRate: 20 }, alt: { speed: 8, jump: -5, fireRate: 40, type: 'Ambulance' }},
  [RobotUnit.VANGUARD]: { name: "VANGUARD", color: '#10b981', hpMult: 2.0, robot: { speed: 4.5, jump: -12, fireRate: 25 }, alt: { speed: 7, jump: -4, fireRate: 30, type: 'Fire Truck' }},
  [RobotUnit.NIGHTSHADE]: { name: "NIGHTSHADE", color: '#6366f1', hpMult: 0.9, robot: { speed: 8, jump: -14, fireRate: 12 }, alt: { speed: 12, jump: -10, fireRate: 18, type: 'Cyber Tiger' }},
  [RobotUnit.BLAZE]: { name: "BLAZE", color: '#f97316', hpMult: 1.2, robot: { speed: 5.5, jump: -11, fireRate: 18 }, alt: { speed: 18, jump: -6, fireRate: 15, type: 'Race Car' }},
  [RobotUnit.GLITCH]: { name: "GLITCH", color: '#ec4899', hpMult: 1.0, robot: { speed: 6, jump: -12, fireRate: 14 }, alt: { speed: 12, jump: -12, fireRate: 16, type: 'Flying Car' }},
  [RobotUnit.OMEGA]: { name: "OMEGA", color: '#ffffff', hpMult: 3.0, robot: { speed: 8, jump: -16, fireRate: 10 }, alt: { speed: 6, jump: -8, fireRate: 10, type: 'Blimp' }},
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const engineRef = useRef({
    players: [] as PlayerEntity[],
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    cameraY: 0,
    isPaused: isPaused,
    level: level,
    upgrades: upgrades,
    isCombined: false,
    combinedHealth: 0,
    combinedMaxHealth: 0,
  });

  useEffect(() => { 
    engineRef.current.isPaused = isPaused; 
    engineRef.current.level = level;
    engineRef.current.upgrades = upgrades;
  }, [isPaused, level, upgrades]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff88');
    grad.addColorStop(1, '#000000aa');
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.6)';
    ctx.lineWidth = 1;
    ctx.stroke();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, frame: number, alpha: number) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    const color = ROBOT_STATS[unit].color;

    switch (unit) {
      case RobotUnit.SENTINEL: // Police Car
        drawMechanicalPart(ctx, -35, -10, 70, 24, '#eee', 4);
        drawMechanicalPart(ctx, -35, 0, 70, 14, '#111', 2);
        const siren = Math.sin(frame * 0.5) > 0;
        ctx.fillStyle = siren ? '#f00' : '#00f'; ctx.fillRect(-12, -20, 24, 10);
        break;
      case RobotUnit.STRIKER: // Police Motorcycle
        drawMechanicalPart(ctx, -20, -8, 40, 15, color, 8);
        ctx.fillStyle = '#111'; ctx.beginPath(); ctx.arc(-18, 12, 10, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(18, 12, 10, 0, Math.PI * 2); ctx.fill();
        const sirenSmall = Math.sin(frame * 0.8) > 0;
        ctx.fillStyle = sirenSmall ? '#f00' : '#00f'; ctx.fillRect(5, -12, 10, 5);
        break;
      case RobotUnit.FALCON: // Jet
        ctx.beginPath(); ctx.moveTo(-40, 0); ctx.lineTo(30, -18); ctx.lineTo(40, 0); ctx.lineTo(30, 18); ctx.closePath();
        ctx.fillStyle = color; ctx.fill();
        drawMechanicalPart(ctx, -15, -6, 35, 12, '#333', 2);
        break;
      case RobotUnit.TITAN: // Tank
        drawMechanicalPart(ctx, -40, -5, 80, 25, '#222', 2); 
        drawMechanicalPart(ctx, -30, -22, 60, 22, color, 4);
        drawMechanicalPart(ctx, 15, -16, 45, 10, '#111', 1);
        break;
      case RobotUnit.SPECTER: // Ambulance
        drawMechanicalPart(ctx, -35, -15, 70, 32, '#fff', 4);
        ctx.fillStyle = '#a855f7'; ctx.fillRect(-6, -8, 12, 16); ctx.fillRect(-18, -2, 36, 4);
        break;
      case RobotUnit.VANGUARD: // Fire Truck
        drawMechanicalPart(ctx, -45, -15, 90, 34, '#d92b2b', 2);
        drawMechanicalPart(ctx, -40, -28, 65, 12, '#888', 1);
        break;
      case RobotUnit.NIGHTSHADE: // Cyber Tiger
        const legMov = Math.sin(frame * 0.25) * 12;
        drawMechanicalPart(ctx, -30, -15, 60, 25, color, 12);
        drawMechanicalPart(ctx, 25, -22, 18, 18, color, 4);
        drawMechanicalPart(ctx, -25, 8, 10, 18 + legMov, '#111', 2);
        drawMechanicalPart(ctx, 15, 8, 10, 18 - legMov, '#111', 2);
        break;
      case RobotUnit.BLAZE: // Race Car
        drawMechanicalPart(ctx, -40, 0, 80, 20, color, 2);
        drawMechanicalPart(ctx, -25, -10, 35, 10, '#111', 12);
        drawMechanicalPart(ctx, -50, -8, 25, 6, color, 1);
        break;
      case RobotUnit.GLITCH: // Flying Car
        drawMechanicalPart(ctx, -35, -12, 70, 24, color, 15);
        const hoverGlow = 0.6 + Math.sin(frame * 0.4) * 0.4;
        ctx.fillStyle = `rgba(0, 243, 255, ${hoverGlow})`;
        ctx.beginPath(); ctx.arc(-25, 14, 12, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(25, 14, 12, 0, Math.PI * 2); ctx.fill();
        break;
      case RobotUnit.OMEGA: // Blimp
        drawMechanicalPart(ctx, -80, -50, 160, 90, '#fff', 45);
        drawMechanicalPart(ctx, -30, 40, 60, 20, '#444', 5);
        break;
      default:
        drawMechanicalPart(ctx, -25, -12, 50, 24, color, 6);
    }
    ctx.restore();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, alpha = 1, sizeMult = 1) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8 * sizeMult;
    const armSwing = Math.cos(time) * 10 * sizeMult;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(sizeMult, sizeMult);
    drawMechanicalPart(ctx, -12, -18, 24, 28, color, 4);
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? '#ff0000' : '#00f3ff'; 
    ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);
    ctx.restore();
  };

  const drawHelicopter = (ctx: CanvasRenderingContext2D, frame: number, alpha = 1) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    drawMechanicalPart(ctx, -35, -12, 70, 35, '#333', 18);
    drawMechanicalPart(ctx, -70, -6, 40, 12, '#222', 2);
    const rotorWidth = 120 * Math.sin(frame * 1.2);
    ctx.strokeStyle = '#fff'; ctx.lineWidth = 4;
    ctx.beginPath(); ctx.moveTo(-rotorWidth/2, -25); ctx.lineTo(rotorWidth/2, -25); ctx.stroke();
    ctx.fillStyle = '#f00'; ctx.fillRect(20, 0, 12, 12);
    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy: boolean, invulnerable: boolean, transformed: boolean, alpha: number, isCombiner = false, type: string = 'grunt') => {
    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    ctx.scale(facing < 0 ? -1 : 1, 1);
    const drawAlpha = invulnerable ? (0.5 + Math.sin(frame * 0.5) * 0.3) * alpha : alpha;

    if (isCombiner) {
      ctx.save(); ctx.translate(0, -40);
      drawHumanoid(ctx, '#facc15', frame, false, drawAlpha, 3.0);
      ctx.restore();
    } else if (type === 'helicopter') {
      drawHelicopter(ctx, frame, drawAlpha);
    } else if (transformed) {
      drawAltMode(ctx, unit, frame, drawAlpha);
    } else {
      drawHumanoid(ctx, isEnemy ? '#ff0055' : ROBOT_STATS[unit].color, frame, isEnemy, drawAlpha);
    }
    ctx.restore();
  };

  const createPlayer = (unit: RobotUnit, x: number, y: number): PlayerEntity => {
    const stats = ROBOT_STATS[unit];
    const baseHP = 100 + (engineRef.current.upgrades.robotTier * 50);
    return { id: Math.random().toString(36).substr(2, 9), unit, pos: { x, y: GROUND_Y - 48 }, vel: { x: 0, y: 0 }, width: 32, height: 48, facing: 1, grounded: true, lastShot: 0, invulnerable: 0, health: baseHP * stats.hpMult, maxHealth: baseHP * stats.hpMult, isTransformed: false };
  };

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    e.frame = 0; e.cameraX = 0; e.bullets = []; e.isCombined = false;
    e.players = upgrades.unlockedUnits.map((unit, i) => createPlayer(unit, 100 - i * 85, GROUND_Y - 48));

    const enemyCount = 5;
    e.enemies = Array.from({ length: enemyCount }, (_, i) => {
      const isHelicopter = i === 4 && level > 3; 
      const type = isHelicopter ? 'helicopter' : 'grunt';
      const width = isHelicopter ? 120 : 48;
      const height = isHelicopter ? 70 : 72;
      const startY = isHelicopter ? 150 : GROUND_Y - height;

      return { 
        id: i, 
        pos: { x: 1800 + i * 900, y: startY }, 
        vel: { x: 0, y: 0 }, 
        width, 
        height, 
        health: 1, // Enforced one-shot kill logic
        maxHealth: 100, 
        isDead: false, 
        type, 
        lastShot: 0 
      };
    });
  }, [level, upgrades]);

  useEffect(() => { resetLevel(); }, [resetLevel]);

  const drawCityscape = (ctx: CanvasRenderingContext2D, e: any) => {
    const camX = e.cameraX;
    const skyGrad = ctx.createLinearGradient(0, 0, 0, CANVAS_HEIGHT);
    skyGrad.addColorStop(0, '#00000c');
    skyGrad.addColorStop(0.7, '#2a0d08');
    skyGrad.addColorStop(1, '#662200');
    ctx.fillStyle = skyGrad; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    const layers = [
      { scroll: 0.1, color: '#0c0c18', spacing: 400, hMin: 300, hMax: 600 },
      { scroll: 0.4, color: '#1a0f0a', spacing: 350, hMin: 400, hMax: 850 },
      { scroll: 0.8, color: '#050505', spacing: 300, hMin: 500, hMax: 1000 },
    ];

    layers.forEach((layer, li) => {
      ctx.fillStyle = layer.color;
      const startX = Math.floor((camX * layer.scroll) / layer.spacing) * layer.spacing - layer.spacing * 2;
      for (let x = startX; x < startX + CANVAS_WIDTH + layer.spacing * 4; x += layer.spacing) {
        const seed = Math.abs(Math.sin(x * 0.01 + li));
        const h = seed * (layer.hMax - layer.hMin) + layer.hMin;
        const bx = x - (camX * layer.scroll);
        const bw = layer.spacing - 40;
        ctx.fillRect(bx, GROUND_Y - h, bw, h);
        if (li >= 1) {
          const fireSeed = Math.sin(x * 0.9 + e.frame * 0.05);
          if (fireSeed > 0.1) {
            ctx.fillStyle = fireSeed > 0.7 ? '#ffbb00' : '#d43300';
            for (let r = 0; r < 10; r++) {
              const winY = GROUND_Y - h + 60 + r * 80;
              if (winY < GROUND_Y - 60) {
                ctx.fillRect(bx + 20, winY, 20, 25);
                ctx.fillRect(bx + bw - 40, winY, 20, 25);
              }
            }
            const flicker = Math.sin(e.frame * 0.5 + x) * 20;
            ctx.beginPath(); ctx.moveTo(bx + 10, GROUND_Y - h);
            ctx.lineTo(bx + bw/2, GROUND_Y - h - 60 - flicker);
            ctx.lineTo(bx + bw - 10, GROUND_Y - h); ctx.fill();
          }
          ctx.fillStyle = layer.color;
        }
      }
    });
  };

  const drawHUD = (ctx: CanvasRenderingContext2D, e: any) => {
    ctx.save();
    const hudX = 70; const hudY = 70;
    const hudW = 460; const hudH = e.isCombined ? 130 : e.players.length * 45 + 70;
    ctx.fillStyle = 'rgba(0, 0, 0, 0.92)'; ctx.fillRect(hudX, hudY, hudW, hudH);
    ctx.strokeStyle = '#00f3ff'; ctx.lineWidth = 4; ctx.strokeRect(hudX, hudY, hudW, hudH);
    ctx.font = 'bold 20px Orbitron'; ctx.fillStyle = '#00f3ff';
    ctx.fillText(e.isCombined ? "COMBINER UNIT ACTIVE" : "ALPHA SQUAD: SECTOR " + e.level, hudX + 30, hudY + 45);

    if (e.isCombined) {
      const hRatio = Math.max(0, e.combinedHealth / e.combinedMaxHealth);
      ctx.fillStyle = '#facc15'; ctx.fillText("ULTIMATE ARMOR INTEGRITY", hudX + 30, hudY + 85);
      ctx.fillStyle = '#111'; ctx.fillRect(hudX + 30, hudY + 95, 400, 25);
      ctx.fillStyle = '#facc15'; ctx.fillRect(hudX + 30, hudY + 95, 400 * hRatio, 25);
    } else {
      e.players.forEach((p: PlayerEntity, i: number) => {
        const stats = ROBOT_STATS[p.unit];
        const hRatio = Math.max(0, p.health / p.maxHealth);
        const y = hudY + 90 + i * 45;
        ctx.fillStyle = p.health > 0 ? stats.color : '#444';
        ctx.fillText(stats.name + (p.isTransformed ? " [" + stats.alt.type + "]" : ""), hudX + 30, y);
        ctx.fillStyle = '#111'; ctx.fillRect(hudX + 30, y + 12, 380, 12);
        ctx.fillStyle = p.health > 0 ? stats.color : '#222';
        ctx.fillRect(hudX + 30, y + 12, 380 * hRatio, 12);
      });
    }
    ctx.restore();
  };

  useEffect(() => {
    const e = engineRef.current;
    const handleKeyDown = (ev: KeyboardEvent) => {
      e.keys[ev.code] = true;
      if ((ev.code === 'ShiftLeft' || ev.code === 'ShiftRight') && !e.isCombined) {
        e.players.forEach(p => p.isTransformed = !p.isTransformed);
      }
      if (ev.code === 'KeyC') {
        if (e.isCombined) {
          e.isCombined = false;
          const hPer = e.combinedHealth / e.players.length;
          e.players.forEach((p, i) => { 
            p.health = Math.min(p.maxHealth, hPer); 
            p.width = 32; p.height = 48; 
            p.pos.x = e.players[0].pos.x - i * 90; 
            p.pos.y = GROUND_Y - 48; 
          });
        } else if (upgrades.unlockedUnits.length >= 5) {
          const aliveOnes = e.players.filter(p => p.health > 0);
          if (aliveOnes.length >= 5) {
            e.isCombined = true;
            e.combinedMaxHealth = e.players.reduce((s, p) => s + p.maxHealth, 0) * 1.5;
            e.combinedHealth = e.players.reduce((s, p) => s + p.health, 0) * 1.5;
            aliveOnes[0].width = 110; aliveOnes[0].height = 160;
          }
        }
      }
    };
    const handleKeyUp = (ev: KeyboardEvent) => { e.keys[ev.code] = false; };
    window.addEventListener('keydown', handleKeyDown); window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => { if (!e.isPaused) update(); draw(); animationId = requestAnimationFrame(loop); };

    const update = () => {
      e.frame++;
      // Determine dynamic leader (first alive player)
      const activeLeaderIndex = e.players.findIndex(p => p.health > 0);
      if (activeLeaderIndex === -1) { onDie(); return; }
      const leader = e.players[activeLeaderIndex];

      const moveRight = e.keys['ArrowRight'] || e.keys['KeyD'];
      const moveLeft = e.keys['ArrowLeft'] || e.keys['KeyA'];
      const moveUp = e.keys['ArrowUp'] || e.keys['KeyW'];
      const moveDown = e.keys['ArrowDown'] || e.keys['KeyS'];
      const firing = e.keys['Space'];

      if (e.isCombined) {
        const s = { speed: 6, jump: -22, fireRate: 4 };
        if (moveRight) { leader.vel.x = s.speed; leader.facing = 1; } else if (moveLeft) { leader.vel.x = -s.speed; leader.facing = -1; } else leader.vel.x *= 0.8;
        if (moveUp && leader.grounded) { leader.vel.y = s.jump; leader.grounded = false; }
        leader.vel.y += GRAVITY; leader.pos.x += leader.vel.x; leader.pos.y += leader.vel.y;
        if (leader.pos.y > GROUND_Y - leader.height) { leader.pos.y = GROUND_Y - leader.height; leader.vel.y = 0; leader.grounded = true; }
        if (firing && e.frame - leader.lastShot > s.fireRate) {
          soundService.playShoot();
          for(let i=-2; i<=2; i++) e.bullets.push({ pos: { x: leader.pos.x + 70, y: leader.pos.y + 80 + (i*30) }, vel: { x: leader.facing * 45, y: i * 4 }, width: 50, height: 16, owner: 'player', damage: 300, color: '#facc15', health: 1, maxHealth: 1 });
          leader.lastShot = e.frame;
        }
      } else {
        e.players.forEach((p, i) => {
          if (p.health <= 0) return;
          const stats = ROBOT_STATS[p.unit]; 
          const s = p.isTransformed ? stats.alt : stats.robot;
          const isFalconJet = p.unit === RobotUnit.FALCON && p.isTransformed;

          if (i === activeLeaderIndex) {
            // Player-controlled leader
            if (moveRight) { p.vel.x = s.speed; p.facing = 1; } else if (moveLeft) { p.vel.x = -s.speed; p.facing = -1; } else p.vel.x *= 0.8;

            if (isFalconJet) {
              // Specialized flight for Falcon Jet: use Up/Down keys
              if (moveUp) p.vel.y = -s.speed;
              else if (moveDown) p.vel.y = s.speed;
              else p.vel.y *= 0.9;
              p.grounded = false;
            } else {
              // Normal humanoid/car/motorcycle mechanics
              if (moveUp && p.grounded) { p.vel.y = s.jump; p.grounded = false; }
              p.vel.y += GRAVITY;
            }
          } else {
            // AI-controlled squad follower
            const targetX = leader.pos.x - ((i - activeLeaderIndex) * 95 * leader.facing); 
            const dist = targetX - p.pos.x;
            if (Math.abs(dist) > 50) { p.vel.x = Math.sign(dist) * s.speed * 0.98; p.facing = Math.sign(dist) || 1; } else p.vel.x *= 0.8;

            if (isFalconJet) {
              // Jets follow leader height if they are also flying or follow leader position
              const targetY = leader.pos.y + (i * 20); // offset slightly
              const hDist = targetY - p.pos.y;
              if (Math.abs(hDist) > 10) p.vel.y = Math.sign(hDist) * s.speed * 0.5;
              else p.vel.y *= 0.8;
            } else {
              if (leader.vel.y < -5 && p.grounded) { p.vel.y = s.jump; p.grounded = false; }
              p.vel.y += GRAVITY;
            }
          }

          p.pos.x += p.vel.x; p.pos.y += p.vel.y;

          // Collision and clamping
          if (p.pos.y > GROUND_Y - p.height) { 
            p.pos.y = GROUND_Y - p.height; 
            p.vel.y = 0; 
            p.grounded = true; 
          }
          if (p.pos.y < 50) { p.pos.y = 50; p.vel.y = 0; }

          if (firing && e.frame - p.lastShot > s.fireRate) {
            soundService.playShoot();
            e.bullets.push({ pos: { x: p.pos.x + 25, y: p.pos.y + 30 }, vel: { x: p.facing * 35, y: 0 }, width: 35, height: 14, owner: 'player', damage: 150, color: stats.color, health: 1, maxHealth: 1 });
            p.lastShot = e.frame;
          }
          if (p.invulnerable > 0) p.invulnerable--;
        });
      }

      // Bullet Physics
      for (let i = e.bullets.length - 1; i >= 0; i--) {
        const b = e.bullets[i]; b.pos.x += b.vel.x; b.pos.y += b.vel.y || 0;
        if (b.owner === 'enemy') {
          if (e.isCombined) {
            const currentCombined = e.players.find(p => p.health > 0);
            if (currentCombined && !currentCombined.invulnerable && b.pos.x < currentCombined.pos.x + currentCombined.width && b.pos.x + b.width > currentCombined.pos.x && b.pos.y < currentCombined.pos.y + currentCombined.height && b.pos.y + b.height > currentCombined.pos.y) {
              e.combinedHealth -= 100; currentCombined.invulnerable = 25; e.bullets.splice(i, 1); if (e.combinedHealth <= 0) onDie();
            }
          } else {
            e.players.forEach(p => { if (p.health > 0 && !p.invulnerable && b.pos.x < p.pos.x + p.width && b.pos.x + b.width > p.pos.x && b.pos.y < p.pos.y + p.height && b.pos.y + b.height > p.pos.y) { p.health -= 50; p.invulnerable = 40; e.bullets.splice(i, 1); } });
          }
        }
        if (Math.abs(b.pos.x - leader.pos.x) > 4000) e.bullets.splice(i, 1);
      }

      // Enemy Updates (5 rogue robots per level)
      let enemiesAliveCount = 0;
      e.enemies.forEach(en => {
        if (en.isDead) return;
        enemiesAliveCount++;
        en.pos.x += Math.sign(leader.pos.x - en.pos.x) * 1.8;
        if (en.type === 'helicopter') { en.pos.y = 150 + Math.sin(e.frame * 0.05 + en.id) * 80; } 
        else { en.pos.y = GROUND_Y - en.height; }

        if (Math.abs(en.pos.x - leader.pos.x) < 1400 && e.frame - en.lastShot > 65) {
          const dy = en.type === 'helicopter' ? 25 : 40;
          e.bullets.push({ pos: { x: en.pos.x, y: en.pos.y + dy }, vel: { x: Math.sign(leader.pos.x - en.pos.x) * 15, y: 0 }, width: 25, height: 14, owner: 'enemy', health: 1, maxHealth: 1, damage: 40, color: '#ff0055' });
          en.lastShot = e.frame;
        }

        e.bullets.forEach((b, bi) => { 
          if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) { 
            en.isDead = true; 
            e.bullets.splice(bi, 1); 
            soundService.playDrive(0.3); // Impact sound simulation
          } 
        });
      });

      if (enemiesAliveCount === 0) onWin();
      e.cameraX = leader.pos.x - 700;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const activeLeader = e.players.find(p => p.health > 0);
      if (!activeLeader) return;

      drawCityscape(ctx, e);
      ctx.save(); ctx.translate(-e.cameraX, 0);
      ctx.fillStyle = '#06060a'; ctx.fillRect(e.cameraX - 2500, GROUND_Y, CANVAS_WIDTH + 5000, 300);
      ctx.strokeStyle = '#00f3ff11'; ctx.lineWidth = 5;
      for (let gx = Math.floor((e.cameraX - 2500) / 120) * 120; gx < e.cameraX + 5500; gx += 120) { ctx.beginPath(); ctx.moveTo(gx, GROUND_Y); ctx.lineTo(gx, GROUND_Y + 300); ctx.stroke(); }

      e.enemies.forEach(en => { if(!en.isDead) drawUnit(ctx, en.pos.x, en.pos.y, en.width, en.height, RobotUnit.SENTINEL, Math.sign(activeLeader.pos.x - en.pos.x), e.frame, true, false, false, 1.6, false, en.type); });

      if (e.isCombined) {
          drawUnit(ctx, activeLeader.pos.x, activeLeader.pos.y, activeLeader.width, activeLeader.height, activeLeader.unit, activeLeader.facing, e.frame, false, activeLeader.invulnerable > 0, false, 1, true);
      } else {
          e.players.forEach(p => { if(p.health > 0) drawUnit(ctx, p.pos.x, p.pos.y, p.width, p.height, p.unit, p.facing, e.frame, false, p.invulnerable > 0, p.isTransformed, 1); });
      }

      e.bullets.forEach(b => { ctx.fillStyle = b.color || '#fff'; ctx.fillRect(b.pos.x, b.pos.y, b.width, b.height); });
      ctx.restore();
      drawHUD(ctx, e);
    };
    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [onWin, onDie, upgrades, level]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden font-orbitron">
      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full max-h-[100vh] aspect-video shadow-[0_0_250px_rgba(0,0,0,1)]" />
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 1600;
const CANVAS_HEIGHT = 900;
const GRAVITY = 0.5;
const GROUND_Y = 750;

interface PlayerEntity {
  unit: RobotUnit;
  pos: { x: number; y: number };
  vel: { x: number; y: number };
  width: number;
  height: number;
  facing: number;
  grounded: boolean;
  lastShot: number;
  invulnerable: number;
  health: number;
  maxHealth: number;
  isTransformed: boolean;
  id: string;
}

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { name: "SENTINEL", color: '#ffffff', hpMult: 1.0, robot: { speed: 5, jump: -12, fireRate: 15 }, alt: { speed: 10, jump: -6, fireRate: 25, type: 'Police Car' }},
  [RobotUnit.STRIKER]: { name: "STRIKER", color: '#fbbf24', hpMult: 0.8, robot: { speed: 7, jump: -10, fireRate: 10 }, alt: { speed: 15, jump: -4, fireRate: 20, type: 'Police Motorcycle' }},
  [RobotUnit.FALCON]: { name: "FALCON", color: '#22d3ee', hpMult: 0.7, robot: { speed: 6, jump: -15, fireRate: 12 }, alt: { speed: 14, jump: -12, fireRate: 15, type: 'Jet' }},
  [RobotUnit.TITAN]: { name: "TITAN", color: '#ef4444', hpMult: 2.5, robot: { speed: 3.5, jump: -13, fireRate: 30 }, alt: { speed: 5, jump: 0, fireRate: 20, type: 'Tank' }},
  [RobotUnit.SPECTER]: { name: "SPECTER", color: '#a855f7', hpMult: 0.6, robot: { speed: 6, jump: -11, fireRate: 20 }, alt: { speed: 8, jump: -5, fireRate: 40, type: 'Ambulance' }},
  [RobotUnit.VANGUARD]: { name: "VANGUARD", color: '#10b981', hpMult: 2.0, robot: { speed: 4.5, jump: -12, fireRate: 25 }, alt: { speed: 7, jump: -4, fireRate: 30, type: 'Fire Truck' }},
  [RobotUnit.NIGHTSHADE]: { name: "NIGHTSHADE", color: '#6366f1', hpMult: 0.9, robot: { speed: 8, jump: -14, fireRate: 12 }, alt: { speed: 12, jump: -10, fireRate: 18, type: 'Cyber Tiger' }},
  [RobotUnit.BLAZE]: { name: "BLAZE", color: '#f97316', hpMult: 1.2, robot: { speed: 5.5, jump: -11, fireRate: 18 }, alt: { speed: 18, jump: -6, fireRate: 15, type: 'Race Car' }},
  [RobotUnit.GLITCH]: { name: "GLITCH", color: '#ec4899', hpMult: 1.0, robot: { speed: 6, jump: -12, fireRate: 14 }, alt: { speed: 12, jump: -12, fireRate: 16, type: 'Flying Car' }},
  [RobotUnit.OMEGA]: { name: "OMEGA", color: '#ffffff', hpMult: 3.0, robot: { speed: 8, jump: -16, fireRate: 10 }, alt: { speed: 6, jump: -8, fireRate: 10, type: 'Blimp' }},
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const engineRef = useRef({
    players: [] as PlayerEntity[],
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    cameraY: 0,
    isPaused: isPaused,
    level: level,
    upgrades: upgrades,
    isCombined: false,
    combinedHealth: 0,
    combinedMaxHealth: 0,
  });

  useEffect(() => { 
    engineRef.current.isPaused = isPaused; 
    engineRef.current.level = level;
    engineRef.current.upgrades = upgrades;
  }, [isPaused, level, upgrades]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff88');
    grad.addColorStop(1, '#000000aa');
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.6)';
    ctx.lineWidth = 1;
    ctx.stroke();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, frame: number, alpha: number) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    const color = ROBOT_STATS[unit].color;

    switch (unit) {
      case RobotUnit.SENTINEL: // Police Car
        drawMechanicalPart(ctx, -35, -10, 70, 24, '#eee', 4);
        drawMechanicalPart(ctx, -35, 0, 70, 14, '#111', 2);
        const siren = Math.sin(frame * 0.5) > 0;
        ctx.fillStyle = siren ? '#f00' : '#00f'; ctx.fillRect(-12, -20, 24, 10);
        break;
      case RobotUnit.STRIKER: // Police Motorcycle
        drawMechanicalPart(ctx, -20, -8, 40, 15, color, 8);
        ctx.fillStyle = '#111'; ctx.beginPath(); ctx.arc(-18, 12, 10, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(18, 12, 10, 0, Math.PI * 2); ctx.fill();
        const sirenSmall = Math.sin(frame * 0.8) > 0;
        ctx.fillStyle = sirenSmall ? '#f00' : '#00f'; ctx.fillRect(5, -12, 10, 5);
        break;
      case RobotUnit.FALCON: // Jet
        // Wings
        ctx.beginPath(); ctx.moveTo(-40, 0); ctx.lineTo(10, -22); ctx.lineTo(30, 0); ctx.lineTo(10, 22); ctx.closePath();
        ctx.fillStyle = color; ctx.fill();
        // Body
        drawMechanicalPart(ctx, -45, -8, 85, 16, '#333', 2);
        // Cockpit
        drawMechanicalPart(ctx, 10, -6, 25, 12, '#00f3ff', 8);
        // Thruster flame
        if (frame % 3 !== 0) {
            ctx.fillStyle = '#ff7700';
            ctx.beginPath(); ctx.moveTo(-45, -5); ctx.lineTo(-65 - (Math.random() * 15), 0); ctx.lineTo(-45, 5); ctx.fill();
        }
        break;
      case RobotUnit.TITAN: // Tank
        drawMechanicalPart(ctx, -40, -5, 80, 25, '#222', 2); 
        drawMechanicalPart(ctx, -30, -22, 60, 22, color, 4);
        drawMechanicalPart(ctx, 15, -16, 45, 10, '#111', 1);
        break;
      case RobotUnit.SPECTER: // Ambulance
        drawMechanicalPart(ctx, -35, -15, 70, 32, '#fff', 4);
        ctx.fillStyle = '#a855f7'; ctx.fillRect(-6, -8, 12, 16); ctx.fillRect(-18, -2, 36, 4);
        break;
      case RobotUnit.VANGUARD: // Fire Truck
        drawMechanicalPart(ctx, -45, -15, 90, 34, '#d92b2b', 2);
        drawMechanicalPart(ctx, -40, -28, 65, 12, '#888', 1);
        break;
      case RobotUnit.NIGHTSHADE: // Cyber Tiger
        const legMov = Math.sin(frame * 0.25) * 12;
        drawMechanicalPart(ctx, -30, -15, 60, 25, color, 12);
        drawMechanicalPart(ctx, 25, -22, 18, 18, color, 4);
        drawMechanicalPart(ctx, -25, 8, 10, 18 + legMov, '#111', 2);
        drawMechanicalPart(ctx, 15, 8, 10, 18 - legMov, '#111', 2);
        break;
      case RobotUnit.BLAZE: // Race Car
        drawMechanicalPart(ctx, -40, 0, 80, 20, color, 2);
        drawMechanicalPart(ctx, -25, -10, 35, 10, '#111', 12);
        drawMechanicalPart(ctx, -50, -8, 25, 6, color, 1);
        break;
      case RobotUnit.GLITCH: // Flying Car
        drawMechanicalPart(ctx, -35, -12, 70, 24, color, 15);
        const hoverGlow = 0.6 + Math.sin(frame * 0.4) * 0.4;
        ctx.fillStyle = `rgba(0, 243, 255, ${hoverGlow})`;
        ctx.beginPath(); ctx.arc(-25, 14, 12, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(25, 14, 12, 0, Math.PI * 2); ctx.fill();
        break;
      case RobotUnit.OMEGA: // Blimp
        drawMechanicalPart(ctx, -80, -50, 160, 90, '#fff', 45);
        drawMechanicalPart(ctx, -30, 40, 60, 20, '#444', 5);
        break;
      default:
        drawMechanicalPart(ctx, -25, -12, 50, 24, color, 6);
    }
    ctx.restore();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, alpha = 1, sizeMult = 1) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8 * sizeMult;
    const armSwing = Math.cos(time) * 10 * sizeMult;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(sizeMult, sizeMult);
    drawMechanicalPart(ctx, -12, -18, 24, 28, color, 4);
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? '#ff0000' : '#00f3ff'; 
    ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);
    ctx.restore();
  };

  const drawHelicopter = (ctx: CanvasRenderingContext2D, frame: number, alpha = 1) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    drawMechanicalPart(ctx, -35, -12, 70, 35, '#333', 18);
    drawMechanicalPart(ctx, -70, -6, 40, 12, '#222', 2);
    const rotorWidth = 120 * Math.sin(frame * 1.2);
    ctx.strokeStyle = '#fff'; ctx.lineWidth = 4;
    ctx.beginPath(); ctx.moveTo(-rotorWidth/2, -25); ctx.lineTo(rotorWidth/2, -25); ctx.stroke();
    ctx.fillStyle = '#f00'; ctx.fillRect(20, 0, 12, 12);
    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy: boolean, invulnerable: boolean, transformed: boolean, alpha: number, isCombiner = false, type: string = 'grunt') => {
    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    ctx.scale(facing < 0 ? -1 : 1, 1);
    const drawAlpha = invulnerable ? (0.5 + Math.sin(frame * 0.5) * 0.3) * alpha : alpha;

    if (isCombiner) {
      ctx.save(); ctx.translate(0, -40);
      drawHumanoid(ctx, '#facc15', frame, false, drawAlpha, 3.0);
      ctx.restore();
    } else if (type === 'helicopter') {
      drawHelicopter(ctx, frame, drawAlpha);
    } else if (transformed) {
      drawAltMode(ctx, unit, frame, drawAlpha);
    } else {
      drawHumanoid(ctx, isEnemy ? '#ff0055' : ROBOT_STATS[unit].color, frame, isEnemy, drawAlpha);
    }
    ctx.restore();
  };

  const createPlayer = (unit: RobotUnit, x: number, y: number): PlayerEntity => {
    const stats = ROBOT_STATS[unit];
    const baseHP = 100 + (engineRef.current.upgrades.robotTier * 50);
    return { id: Math.random().toString(36).substr(2, 9), unit, pos: { x, y: GROUND_Y - 48 }, vel: { x: 0, y: 0 }, width: 32, height: 48, facing: 1, grounded: true, lastShot: 0, invulnerable: 0, health: baseHP * stats.hpMult, maxHealth: baseHP * stats.hpMult, isTransformed: false };
  };

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    e.frame = 0; e.cameraX = 0; e.bullets = []; e.isCombined = false;
    e.players = upgrades.unlockedUnits.map((unit, i) => createPlayer(unit, 100 - i * 90, GROUND_Y - 48));

    const enemyCount = 5;
    e.enemies = Array.from({ length: enemyCount }, (_, i) => {
      const isHelicopter = i >= 3 && level > 2; 
      const type = isHelicopter ? 'helicopter' : 'grunt';
      const width = isHelicopter ? 120 : 48;
      const height = isHelicopter ? 70 : 72;
      const startY = isHelicopter ? 200 : GROUND_Y - height;

      return { 
        id: i, 
        pos: { x: 1800 + i * 1000, y: startY }, 
        vel: { x: 0, y: 0 }, 
        width, 
        height, 
        health: 1, 
        maxHealth: 100, 
        isDead: false, 
        type, 
        lastShot: 0 
      };
    });
  }, [level, upgrades]);

  useEffect(() => { resetLevel(); }, [resetLevel]);

  const drawCityscape = (ctx: CanvasRenderingContext2D, e: any) => {
    const camX = e.cameraX;
    const skyGrad = ctx.createLinearGradient(0, 0, 0, CANVAS_HEIGHT);
    skyGrad.addColorStop(0, '#00000c');
    skyGrad.addColorStop(0.7, '#2a0d08');
    skyGrad.addColorStop(1, '#662200');
    ctx.fillStyle = skyGrad; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    const layers = [
      { scroll: 0.1, color: '#0c0c18', spacing: 450, hMin: 300, hMax: 600 },
      { scroll: 0.4, color: '#1a0f0a', spacing: 400, hMin: 400, hMax: 850 },
      { scroll: 0.8, color: '#050505', spacing: 350, hMin: 500, hMax: 1000 },
    ];

    layers.forEach((layer, li) => {
      ctx.fillStyle = layer.color;
      const startX = Math.floor((camX * layer.scroll) / layer.spacing) * layer.spacing - layer.spacing * 2;
      for (let x = startX; x < startX + CANVAS_WIDTH + layer.spacing * 4; x += layer.spacing) {
        const seed = Math.abs(Math.sin(x * 0.01 + li));
        const h = seed * (layer.hMax - layer.hMin) + layer.hMin;
        const bx = x - (camX * layer.scroll);
        const bw = layer.spacing - 40;
        ctx.fillRect(bx, GROUND_Y - h, bw, h);
        if (li >= 1) {
          const fireSeed = Math.sin(x * 0.9 + e.frame * 0.05);
          if (fireSeed > 0.1) {
            ctx.fillStyle = fireSeed > 0.7 ? '#ffbb00' : '#d43300';
            for (let r = 0; r < 10; r++) {
              const winY = GROUND_Y - h + 60 + r * 80;
              if (winY < GROUND_Y - 60) {
                ctx.fillRect(bx + 20, winY, 20, 25);
                ctx.fillRect(bx + bw - 40, winY, 20, 25);
              }
            }
            const flicker = Math.sin(e.frame * 0.5 + x) * 20;
            ctx.beginPath(); ctx.moveTo(bx + 10, GROUND_Y - h);
            ctx.lineTo(bx + bw/2, GROUND_Y - h - 60 - flicker);
            ctx.lineTo(bx + bw - 10, GROUND_Y - h); ctx.fill();
          }
          ctx.fillStyle = layer.color;
        }
      }
    });
  };

  const drawHUD = (ctx: CanvasRenderingContext2D, e: any) => {
    ctx.save();
    const hudX = 70; const hudY = 70;
    const hudW = 460; const hudH = e.isCombined ? 130 : e.players.length * 45 + 70;
    ctx.fillStyle = 'rgba(0, 0, 0, 0.92)'; ctx.fillRect(hudX, hudY, hudW, hudH);
    ctx.strokeStyle = '#00f3ff'; ctx.lineWidth = 4; ctx.strokeRect(hudX, hudY, hudW, hudH);
    ctx.font = 'bold 20px Orbitron'; ctx.fillStyle = '#00f3ff';
    ctx.fillText(e.isCombined ? "COMBINER UNIT ACTIVE" : "ALPHA SQUAD: SECTOR " + e.level, hudX + 30, hudY + 45);

    if (e.isCombined) {
      const hRatio = Math.max(0, e.combinedHealth / e.combinedMaxHealth);
      ctx.fillStyle = '#facc15'; ctx.fillText("ULTIMATE ARMOR INTEGRITY", hudX + 30, hudY + 85);
      ctx.fillStyle = '#111'; ctx.fillRect(hudX + 30, hudY + 95, 400, 25);
      ctx.fillStyle = '#facc15'; ctx.fillRect(hudX + 30, hudY + 95, 400 * hRatio, 25);
    } else {
      e.players.forEach((p: PlayerEntity, i: number) => {
        const stats = ROBOT_STATS[p.unit];
        const hRatio = Math.max(0, p.health / p.maxHealth);
        const y = hudY + 90 + i * 45;
        ctx.fillStyle = p.health > 0 ? stats.color : '#444';
        ctx.fillText(stats.name + (p.isTransformed ? " [" + stats.alt.type + "]" : ""), hudX + 30, y);
        ctx.fillStyle = '#111'; ctx.fillRect(hudX + 30, y + 12, 380, 12);
        ctx.fillStyle = p.health > 0 ? stats.color : '#222';
        ctx.fillRect(hudX + 30, y + 12, 380 * hRatio, 12);
      });
    }
    ctx.restore();
  };

  useEffect(() => {
    const e = engineRef.current;
    const handleKeyDown = (ev: KeyboardEvent) => {
      e.keys[ev.code] = true;
      if ((ev.code === 'ShiftLeft' || ev.code === 'ShiftRight') && !e.isCombined) {
        e.players.forEach(p => p.isTransformed = !p.isTransformed);
      }
      if (ev.code === 'KeyC') {
        if (e.isCombined) {
          e.isCombined = false;
          const hPer = e.combinedHealth / e.players.length;
          e.players.forEach((p, i) => { 
            p.health = Math.min(p.maxHealth, hPer); 
            p.width = 32; p.height = 48; 
            p.pos.x = e.players[0].pos.x - i * 90; 
            p.pos.y = GROUND_Y - 48; 
          });
        } else if (upgrades.unlockedUnits.length >= 5) {
          const aliveOnes = e.players.filter(p => p.health > 0);
          if (aliveOnes.length >= 5) {
            e.isCombined = true;
            e.combinedMaxHealth = e.players.reduce((s, p) => s + p.maxHealth, 0) * 1.5;
            e.combinedHealth = e.players.reduce((s, p) => s + p.health, 0) * 1.5;
            aliveOnes[0].width = 110; aliveOnes[0].height = 160;
          }
        }
      }
    };
    const handleKeyUp = (ev: KeyboardEvent) => { e.keys[ev.code] = false; };
    window.addEventListener('keydown', handleKeyDown); window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => { if (!e.isPaused) update(); draw(); animationId = requestAnimationFrame(loop); };

    const update = () => {
      e.frame++;
      const activeLeaderIndex = e.players.findIndex(p => p.health > 0);
      if (activeLeaderIndex === -1) { onDie(); return; }
      const leader = e.players[activeLeaderIndex];

      const moveRight = e.keys['ArrowRight'] || e.keys['KeyD'];
      const moveLeft = e.keys['ArrowLeft'] || e.keys['KeyA'];
      const moveUp = e.keys['ArrowUp'] || e.keys['KeyW'];
      const moveDown = e.keys['ArrowDown'] || e.keys['KeyS'];
      const firing = e.keys['Space'];

      if (e.isCombined) {
        const s = { speed: 6, jump: -22, fireRate: 4 };
        if (moveRight) { leader.vel.x = s.speed; leader.facing = 1; } else if (moveLeft) { leader.vel.x = -s.speed; leader.facing = -1; } else leader.vel.x *= 0.8;
        if (moveUp && leader.grounded) { leader.vel.y = s.jump; leader.grounded = false; }
        leader.vel.y += GRAVITY; leader.pos.x += leader.vel.x; leader.pos.y += leader.vel.y;
        if (leader.pos.y > GROUND_Y - leader.height) { leader.pos.y = GROUND_Y - leader.height; leader.vel.y = 0; leader.grounded = true; }
        if (firing && e.frame - leader.lastShot > s.fireRate) {
          soundService.playShoot();
          for(let i=-2; i<=2; i++) e.bullets.push({ pos: { x: leader.pos.x + 70, y: leader.pos.y + 80 + (i*30) }, vel: { x: leader.facing * 45, y: i * 4 }, width: 50, height: 16, owner: 'player', damage: 300, color: '#facc15', health: 1, maxHealth: 1 });
          leader.lastShot = e.frame;
        }
      } else {
        e.players.forEach((p, i) => {
          if (p.health <= 0) return;
          const stats = ROBOT_STATS[p.unit]; 
          const s = p.isTransformed ? stats.alt : stats.robot;
          const isFalconJet = p.unit === RobotUnit.FALCON && p.isTransformed;

          if (i === activeLeaderIndex) {
            // Leader movement control
            if (moveRight) { p.vel.x = s.speed; p.facing = 1; } else if (moveLeft) { p.vel.x = -s.speed; p.facing = -1; } else p.vel.x *= 0.8;

            if (isFalconJet) {
              // FALCON FLIGHT: Vertical movement control in Jet mode
              if (moveUp) p.vel.y = -s.speed;
              else if (moveDown) p.vel.y = s.speed;
              else p.vel.y *= 0.9; // Air friction
              p.grounded = false;
            } else {
              if (moveUp && p.grounded) { p.vel.y = s.jump; p.grounded = false; }
              p.vel.y += GRAVITY;
            }
          } else {
            // Squad follower AI
            const targetX = leader.pos.x - ((i - activeLeaderIndex) * 95 * leader.facing); 
            const dist = targetX - p.pos.x;
            if (Math.abs(dist) > 50) { p.vel.x = Math.sign(dist) * s.speed * 0.98; p.facing = Math.sign(dist) || 1; } else p.vel.x *= 0.8;

            if (isFalconJet) {
              // Automated flight height following for followers
              const targetY = leader.pos.y + (i * 30);
              const hDist = targetY - p.pos.y;
              if (Math.abs(hDist) > 10) p.vel.y = Math.sign(hDist) * s.speed * 0.6;
              else p.vel.y *= 0.8;
            } else {
              if (leader.vel.y < -5 && p.grounded) { p.vel.y = s.jump; p.grounded = false; }
              p.vel.y += GRAVITY;
            }
          }

          p.pos.x += p.vel.x; p.pos.y += p.vel.y;

          // Clamp within world bounds
          if (p.pos.y > GROUND_Y - p.height) { 
            p.pos.y = GROUND_Y - p.height; 
            p.vel.y = 0; 
            p.grounded = true; 
          }
          if (p.pos.y < 50) { p.pos.y = 50; p.vel.y = 0; }

          if (firing && e.frame - p.lastShot > s.fireRate) {
            soundService.playShoot();
            e.bullets.push({ pos: { x: p.pos.x + 25, y: p.pos.y + 30 }, vel: { x: p.facing * 35, y: 0 }, width: 35, height: 14, owner: 'player', damage: 150, color: stats.color, health: 1, maxHealth: 1 });
            p.lastShot = e.frame;
          }
          if (p.invulnerable > 0) p.invulnerable--;
        });
      }

      // Bullet logic
      for (let i = e.bullets.length - 1; i >= 0; i--) {
        const b = e.bullets[i]; b.pos.x += b.vel.x; b.pos.y += b.vel.y || 0;
        if (b.owner === 'enemy') {
          if (e.isCombined) {
            const currentCombined = e.players.find(p => p.health > 0);
            if (currentCombined && !currentCombined.invulnerable && b.pos.x < currentCombined.pos.x + currentCombined.width && b.pos.x + b.width > currentCombined.pos.x && b.pos.y < currentCombined.pos.y + currentCombined.height && b.pos.y + b.height > currentCombined.pos.y) {
              e.combinedHealth -= 100; currentCombined.invulnerable = 25; e.bullets.splice(i, 1); if (e.combinedHealth <= 0) onDie();
            }
          } else {
            e.players.forEach(p => { if (p.health > 0 && !p.invulnerable && b.pos.x < p.pos.x + p.width && b.pos.x + b.width > p.pos.x && b.pos.y < p.pos.y + p.height && b.pos.y + b.height > p.pos.y) { p.health -= 50; p.invulnerable = 40; e.bullets.splice(i, 1); } });
          }
        }
        if (Math.abs(b.pos.x - leader.pos.x) > 4000) e.bullets.splice(i, 1);
      }

      // Enemy behavior
      let enemiesAliveCount = 0;
      e.enemies.forEach(en => {
        if (en.isDead) return;
        enemiesAliveCount++;
        en.pos.x += Math.sign(leader.pos.x - en.pos.x) * 1.8;
        if (en.type === 'helicopter') { en.pos.y = 180 + Math.sin(e.frame * 0.05 + en.id) * 90; } 
        else { en.pos.y = GROUND_Y - en.height; }

        if (Math.abs(en.pos.x - leader.pos.x) < 1400 && e.frame - en.lastShot > 70) {
          const dy = en.type === 'helicopter' ? 25 : 40;
          e.bullets.push({ pos: { x: en.pos.x, y: en.pos.y + dy }, vel: { x: Math.sign(leader.pos.x - en.pos.x) * 15, y: 0 }, width: 25, height: 14, owner: 'enemy', health: 1, maxHealth: 1, damage: 40, color: '#ff0055' });
          en.lastShot = e.frame;
        }

        e.bullets.forEach((b, bi) => { 
          if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) { 
            en.isDead = true; 
            e.bullets.splice(bi, 1); 
            soundService.playDrive(0.3);
          } 
        });
      });

      if (enemiesAliveCount === 0) onWin();
      e.cameraX = leader.pos.x - 700;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const activeLeader = e.players.find(p => p.health > 0);
      if (!activeLeader) return;

      drawCityscape(ctx, e);
      ctx.save(); ctx.translate(-e.cameraX, 0);
      ctx.fillStyle = '#06060a'; ctx.fillRect(e.cameraX - 2500, GROUND_Y, CANVAS_WIDTH + 5000, 300);
      ctx.strokeStyle = '#00f3ff11'; ctx.lineWidth = 5;
      for (let gx = Math.floor((e.cameraX - 2500) / 120) * 120; gx < e.cameraX + 5500; gx += 120) { ctx.beginPath(); ctx.moveTo(gx, GROUND_Y); ctx.lineTo(gx, GROUND_Y + 300); ctx.stroke(); }

      e.enemies.forEach(en => { if(!en.isDead) drawUnit(ctx, en.pos.x, en.pos.y, en.width, en.height, RobotUnit.SENTINEL, Math.sign(activeLeader.pos.x - en.pos.x), e.frame, true, false, false, 1.6, false, en.type); });

      if (e.isCombined) {
          drawUnit(ctx, activeLeader.pos.x, activeLeader.pos.y, activeLeader.width, activeLeader.height, activeLeader.unit, activeLeader.facing, e.frame, false, activeLeader.invulnerable > 0, false, 1, true);
      } else {
          e.players.forEach(p => { if(p.health > 0) drawUnit(ctx, p.pos.x, p.pos.y, p.width, p.height, p.unit, p.facing, e.frame, false, p.invulnerable > 0, p.isTransformed, 1); });
      }

      e.bullets.forEach(b => { ctx.fillStyle = b.color || '#fff'; ctx.fillRect(b.pos.x, b.pos.y, b.width, b.height); });
      ctx.restore();
      drawHUD(ctx, e);
    };
    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [onWin, onDie, upgrades, level]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden font-orbitron">
      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full max-h-[100vh] aspect-video shadow-[0_0_250px_rgba(0,0,0,1)]" />
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 1600;
const CANVAS_HEIGHT = 900;
const GRAVITY = 0.5;
const GROUND_Y = 750;

interface PlayerEntity {
  unit: RobotUnit;
  pos: { x: number; y: number };
  vel: { x: number; y: number };
  width: number;
  height: number;
  facing: number;
  grounded: boolean;
  lastShot: number;
  invulnerable: number;
  health: number;
  maxHealth: number;
  isTransformed: boolean;
  id: string;
}

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { name: "SENTINEL", color: '#ffffff', hpMult: 1.0, robot: { speed: 5, jump: -12, fireRate: 15 }, alt: { speed: 10, jump: -6, fireRate: 25, type: 'Police Car' }},
  [RobotUnit.STRIKER]: { name: "STRIKER", color: '#fbbf24', hpMult: 0.8, robot: { speed: 7, jump: -10, fireRate: 10 }, alt: { speed: 15, jump: -4, fireRate: 20, type: 'Police Motorcycle' }},
  [RobotUnit.FALCON]: { name: "FALCON", color: '#22d3ee', hpMult: 0.7, robot: { speed: 6, jump: -15, fireRate: 12 }, alt: { speed: 14, jump: -12, fireRate: 15, type: 'Jet' }},
  [RobotUnit.TITAN]: { name: "TITAN", color: '#ef4444', hpMult: 2.5, robot: { speed: 3.5, jump: -13, fireRate: 30 }, alt: { speed: 5, jump: 0, fireRate: 20, type: 'Tank' }},
  [RobotUnit.SPECTER]: { name: "SPECTER", color: '#a855f7', hpMult: 0.6, robot: { speed: 6, jump: -11, fireRate: 20 }, alt: { speed: 8, jump: -5, fireRate: 40, type: 'Ambulance' }},
  [RobotUnit.VANGUARD]: { name: "VANGUARD", color: '#10b981', hpMult: 2.0, robot: { speed: 4.5, jump: -12, fireRate: 25 }, alt: { speed: 7, jump: -4, fireRate: 30, type: 'Fire Truck' }},
  [RobotUnit.NIGHTSHADE]: { name: "NIGHTSHADE", color: '#6366f1', hpMult: 0.9, robot: { speed: 8, jump: -14, fireRate: 12 }, alt: { speed: 12, jump: -10, fireRate: 18, type: 'Cyber Tiger' }},
  [RobotUnit.BLAZE]: { name: "BLAZE", color: '#f97316', hpMult: 1.2, robot: { speed: 5.5, jump: -11, fireRate: 18 }, alt: { speed: 18, jump: -6, fireRate: 15, type: 'Race Car' }},
  [RobotUnit.GLITCH]: { name: "GLITCH", color: '#ec4899', hpMult: 1.0, robot: { speed: 6, jump: -12, fireRate: 14 }, alt: { speed: 12, jump: -12, fireRate: 16, type: 'Flying Car' }},
  [RobotUnit.OMEGA]: { name: "OMEGA", color: '#ffffff', hpMult: 3.0, robot: { speed: 8, jump: -16, fireRate: 10 }, alt: { speed: 6, jump: -8, fireRate: 10, type: 'Blimp' }},
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const engineRef = useRef({
    players: [] as PlayerEntity[],
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    cameraY: 0,
    isPaused: isPaused,
    level: level,
    upgrades: upgrades,
    isCombined: false,
    combinedHealth: 0,
    combinedMaxHealth: 0,
  });

  useEffect(() => { 
    engineRef.current.isPaused = isPaused; 
    engineRef.current.level = level;
    engineRef.current.upgrades = upgrades;
  }, [isPaused, level, upgrades]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff88');
    grad.addColorStop(1, '#000000aa');
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.6)';
    ctx.lineWidth = 1;
    ctx.stroke();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, frame: number, alpha: number) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    const color = ROBOT_STATS[unit].color;

    switch (unit) {
      case RobotUnit.SENTINEL: // Police Car
        drawMechanicalPart(ctx, -35, -10, 70, 24, '#eee', 4);
        drawMechanicalPart(ctx, -35, 0, 70, 14, '#111', 2);
        const siren = Math.sin(frame * 0.5) > 0;
        ctx.fillStyle = siren ? '#f00' : '#00f'; ctx.fillRect(-12, -20, 24, 10);
        break;
      case RobotUnit.STRIKER: // Police Motorcycle
        drawMechanicalPart(ctx, -20, -8, 40, 15, color, 8);
        ctx.fillStyle = '#111'; ctx.beginPath(); ctx.arc(-18, 12, 10, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(18, 12, 10, 0, Math.PI * 2); ctx.fill();
        const sirenSmall = Math.sin(frame * 0.8) > 0;
        ctx.fillStyle = sirenSmall ? '#f00' : '#00f'; ctx.fillRect(5, -12, 10, 5);
        break;
      case RobotUnit.FALCON: // Jet
        // Wings
        ctx.beginPath(); ctx.moveTo(-40, 0); ctx.lineTo(10, -22); ctx.lineTo(30, 0); ctx.lineTo(10, 22); ctx.closePath();
        ctx.fillStyle = color; ctx.fill();
        // Body
        drawMechanicalPart(ctx, -45, -8, 85, 16, '#333', 2);
        // Cockpit
        drawMechanicalPart(ctx, 10, -6, 25, 12, '#00f3ff', 8);
        // Thruster flame
        if (frame % 3 !== 0) {
            ctx.fillStyle = '#ff7700';
            ctx.beginPath(); ctx.moveTo(-45, -5); ctx.lineTo(-65 - (Math.random() * 15), 0); ctx.lineTo(-45, 5); ctx.fill();
        }
        break;
      case RobotUnit.TITAN: // Tank
        drawMechanicalPart(ctx, -40, -5, 80, 25, '#222', 2); 
        drawMechanicalPart(ctx, -30, -22, 60, 22, color, 4);
        drawMechanicalPart(ctx, 15, -16, 45, 10, '#111', 1);
        break;
      case RobotUnit.SPECTER: // Ambulance
        drawMechanicalPart(ctx, -35, -15, 70, 32, '#fff', 4);
        ctx.fillStyle = '#a855f7'; ctx.fillRect(-6, -8, 12, 16); ctx.fillRect(-18, -2, 36, 4);
        break;
      case RobotUnit.VANGUARD: // Fire Truck
        drawMechanicalPart(ctx, -45, -15, 90, 34, '#d92b2b', 2);
        drawMechanicalPart(ctx, -40, -28, 65, 12, '#888', 1);
        break;
      case RobotUnit.NIGHTSHADE: // Cyber Tiger
        const legMov = Math.sin(frame * 0.25) * 12;
        drawMechanicalPart(ctx, -30, -15, 60, 25, color, 12);
        drawMechanicalPart(ctx, 25, -22, 18, 18, color, 4);
        drawMechanicalPart(ctx, -25, 8, 10, 18 + legMov, '#111', 2);
        drawMechanicalPart(ctx, 15, 8, 10, 18 - legMov, '#111', 2);
        break;
      case RobotUnit.BLAZE: // Race Car
        drawMechanicalPart(ctx, -40, 0, 80, 20, color, 2);
        drawMechanicalPart(ctx, -25, -10, 35, 10, '#111', 12);
        drawMechanicalPart(ctx, -50, -8, 25, 6, color, 1);
        break;
      case RobotUnit.GLITCH: // Flying Car
        drawMechanicalPart(ctx, -35, -12, 70, 24, color, 15);
        const hoverGlow = 0.6 + Math.sin(frame * 0.4) * 0.4;
        ctx.fillStyle = `rgba(0, 243, 255, ${hoverGlow})`;
        ctx.beginPath(); ctx.arc(-25, 14, 12, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(25, 14, 12, 0, Math.PI * 2); ctx.fill();
        break;
      case RobotUnit.OMEGA: // Blimp
        drawMechanicalPart(ctx, -80, -50, 160, 90, '#fff', 45);
        drawMechanicalPart(ctx, -30, 40, 60, 20, '#444', 5);
        break;
      default:
        drawMechanicalPart(ctx, -25, -12, 50, 24, color, 6);
    }
    ctx.restore();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, alpha = 1, sizeMult = 1) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8 * sizeMult;
    const armSwing = Math.cos(time) * 10 * sizeMult;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(sizeMult, sizeMult);
    drawMechanicalPart(ctx, -12, -18, 24, 28, color, 4);
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);
    ctx.fillStyle = isEnemy ? '#ff0000' : '#00f3ff'; 
    ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);
    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);
    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy: boolean, invulnerable: boolean, transformed: boolean, alpha: number, isCombiner = false, type: string = 'grunt') => {
    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    ctx.scale(facing < 0 ? -1 : 1, 1);
    const drawAlpha = invulnerable ? (0.5 + Math.sin(frame * 0.5) * 0.3) * alpha : alpha;

    if (isCombiner) {
      ctx.save(); ctx.translate(0, -40);
      drawHumanoid(ctx, '#facc15', frame, false, drawAlpha, 3.0);
      ctx.restore();
    } else if (transformed) {
      drawAltMode(ctx, unit, frame, drawAlpha);
    } else {
      drawHumanoid(ctx, isEnemy ? '#ff0055' : ROBOT_STATS[unit].color, frame, isEnemy, drawAlpha);
    }
    ctx.restore();
  };

  const createPlayer = (unit: RobotUnit, x: number, y: number): PlayerEntity => {
    const stats = ROBOT_STATS[unit];
    const baseHP = 100 + (engineRef.current.upgrades.robotTier * 50);
    return { id: Math.random().toString(36).substr(2, 9), unit, pos: { x, y: GROUND_Y - 48 }, vel: { x: 0, y: 0 }, width: 32, height: 48, facing: 1, grounded: true, lastShot: 0, invulnerable: 0, health: baseHP * stats.hpMult, maxHealth: baseHP * stats.hpMult, isTransformed: false };
  };

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    e.frame = 0; e.cameraX = 0; e.bullets = []; e.isCombined = false;
    e.players = upgrades.unlockedUnits.map((unit, i) => createPlayer(unit, 100 - i * 95, GROUND_Y - 48));

    const enemyCount = 5;
    e.enemies = Array.from({ length: enemyCount }, (_, i) => {
      // All enemies are ground-based rogue bots as per requirement
      const type = 'grunt';
      const width = 48;
      const height = 72;
      const startY = GROUND_Y - height;

      return { 
        id: i, 
        pos: { x: 1800 + i * 1100, y: startY }, 
        vel: { x: 0, y: 0 }, 
        width, 
        height, 
        health: 1, // Enforce one-shot kill as requested
        maxHealth: 100, 
        isDead: false, 
        type, 
        lastShot: 0 
      };
    });
  }, [level, upgrades]);

  useEffect(() => { resetLevel(); }, [resetLevel]);

  const drawCityscape = (ctx: CanvasRenderingContext2D, e: any) => {
    const camX = e.cameraX;
    const skyGrad = ctx.createLinearGradient(0, 0, 0, CANVAS_HEIGHT);
    skyGrad.addColorStop(0, '#00000c');
    skyGrad.addColorStop(0.7, '#2a0d08');
    skyGrad.addColorStop(1, '#662200');
    ctx.fillStyle = skyGrad; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    const layers = [
      { scroll: 0.1, color: '#0c0c18', spacing: 450, hMin: 300, hMax: 600 },
      { scroll: 0.4, color: '#1a0f0a', spacing: 400, hMin: 400, hMax: 850 },
      { scroll: 0.8, color: '#050505', spacing: 350, hMin: 500, hMax: 1000 },
    ];

    layers.forEach((layer, li) => {
      ctx.fillStyle = layer.color;
      const startX = Math.floor((camX * layer.scroll) / layer.spacing) * layer.spacing - layer.spacing * 2;
      for (let x = startX; x < startX + CANVAS_WIDTH + layer.spacing * 4; x += layer.spacing) {
        const seed = Math.abs(Math.sin(x * 0.01 + li));
        const h = seed * (layer.hMax - layer.hMin) + layer.hMin;
        const bx = x - (camX * layer.scroll);
        const bw = layer.spacing - 40;
        ctx.fillRect(bx, GROUND_Y - h, bw, h);
        if (li >= 1) {
          const fireSeed = Math.sin(x * 0.9 + e.frame * 0.05);
          if (fireSeed > 0.1) {
            ctx.fillStyle = fireSeed > 0.7 ? '#ffbb00' : '#d43300';
            for (let r = 0; r < 10; r++) {
              const winY = GROUND_Y - h + 60 + r * 80;
              if (winY < GROUND_Y - 60) {
                ctx.fillRect(bx + 20, winY, 20, 25);
                ctx.fillRect(bx + bw - 40, winY, 20, 25);
              }
            }
            const flicker = Math.sin(e.frame * 0.5 + x) * 20;
            ctx.beginPath(); ctx.moveTo(bx + 10, GROUND_Y - h);
            ctx.lineTo(bx + bw/2, GROUND_Y - h - 60 - flicker);
            ctx.lineTo(bx + bw - 10, GROUND_Y - h); ctx.fill();
          }
          ctx.fillStyle = layer.color;
        }
      }
    });
  };

  const drawHUD = (ctx: CanvasRenderingContext2D, e: any) => {
    ctx.save();
    const hudX = 70; const hudY = 70;
    const hudW = 460; const hudH = e.isCombined ? 130 : e.players.length * 45 + 70;
    ctx.fillStyle = 'rgba(0, 0, 0, 0.92)'; ctx.fillRect(hudX, hudY, hudW, hudH);
    ctx.strokeStyle = '#00f3ff'; ctx.lineWidth = 4; ctx.strokeRect(hudX, hudY, hudW, hudH);
    ctx.font = 'bold 20px Orbitron'; ctx.fillStyle = '#00f3ff';
    ctx.fillText(e.isCombined ? "COMBINER UNIT ACTIVE" : "ALPHA SQUAD: SECTOR " + e.level, hudX + 30, hudY + 45);

    if (e.isCombined) {
      const hRatio = Math.max(0, e.combinedHealth / e.combinedMaxHealth);
      ctx.fillStyle = '#facc15'; ctx.fillText("ULTIMATE ARMOR INTEGRITY", hudX + 30, hudY + 85);
      ctx.fillStyle = '#111'; ctx.fillRect(hudX + 30, hudY + 95, 400, 25);
      ctx.fillStyle = '#facc15'; ctx.fillRect(hudX + 30, hudY + 95, 400 * hRatio, 25);
    } else {
      e.players.forEach((p: PlayerEntity, i: number) => {
        const stats = ROBOT_STATS[p.unit];
        const hRatio = Math.max(0, p.health / p.maxHealth);
        const y = hudY + 90 + i * 45;
        ctx.fillStyle = p.health > 0 ? stats.color : '#444';
        ctx.fillText(stats.name + (p.isTransformed ? " [" + stats.alt.type + "]" : ""), hudX + 30, y);
        ctx.fillStyle = '#111'; ctx.fillRect(hudX + 30, y + 12, 380, 12);
        ctx.fillStyle = p.health > 0 ? stats.color : '#222';
        ctx.fillRect(hudX + 30, y + 12, 380 * hRatio, 12);
      });
    }
    ctx.restore();
  };

  useEffect(() => {
    const e = engineRef.current;
    const handleKeyDown = (ev: KeyboardEvent) => {
      e.keys[ev.code] = true;
      if ((ev.code === 'ShiftLeft' || ev.code === 'ShiftRight') && !e.isCombined) {
        e.players.forEach(p => p.isTransformed = !p.isTransformed);
      }
      if (ev.code === 'KeyC') {
        if (e.isCombined) {
          e.isCombined = false;
          const hPer = e.combinedHealth / e.players.length;
          e.players.forEach((p, i) => { 
            p.health = Math.min(p.maxHealth, hPer); 
            p.width = 32; p.height = 48; 
            p.pos.x = e.players[0].pos.x - i * 90; 
            p.pos.y = GROUND_Y - 48; 
          });
        } else if (upgrades.unlockedUnits.length >= 5) {
          const aliveOnes = e.players.filter(p => p.health > 0);
          if (aliveOnes.length >= 5) {
            e.isCombined = true;
            e.combinedMaxHealth = e.players.reduce((s, p) => s + p.maxHealth, 0) * 1.5;
            e.combinedHealth = e.players.reduce((s, p) => s + p.health, 0) * 1.5;
            aliveOnes[0].width = 110; aliveOnes[0].height = 160;
          }
        }
      }
    };
    const handleKeyUp = (ev: KeyboardEvent) => { e.keys[ev.code] = false; };
    window.addEventListener('keydown', handleKeyDown); window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => { if (!e.isPaused) update(); draw(); animationId = requestAnimationFrame(loop); };

    const update = () => {
      e.frame++;
      const activeLeaderIndex = e.players.findIndex(p => p.health > 0);
      if (activeLeaderIndex === -1) { onDie(); return; }
      const leader = e.players[activeLeaderIndex];

      const moveRight = e.keys['ArrowRight'] || e.keys['KeyD'];
      const moveLeft = e.keys['ArrowLeft'] || e.keys['KeyA'];
      const moveUp = e.keys['ArrowUp'] || e.keys['KeyW'];
      const moveDown = e.keys['ArrowDown'] || e.keys['KeyS'];
      const firing = e.keys['Space'];

      if (e.isCombined) {
        const s = { speed: 6, jump: -22, fireRate: 4 };
        if (moveRight) { leader.vel.x = s.speed; leader.facing = 1; } else if (moveLeft) { leader.vel.x = -s.speed; leader.facing = -1; } else leader.vel.x *= 0.8;
        if (moveUp && leader.grounded) { leader.vel.y = s.jump; leader.grounded = false; }
        leader.vel.y += GRAVITY; leader.pos.x += leader.vel.x; leader.pos.y += leader.vel.y;
        if (leader.pos.y > GROUND_Y - leader.height) { leader.pos.y = GROUND_Y - leader.height; leader.vel.y = 0; leader.grounded = true; }
        if (firing && e.frame - leader.lastShot > s.fireRate) {
          soundService.playShoot();
          for(let i=-2; i<=2; i++) e.bullets.push({ pos: { x: leader.pos.x + 70, y: leader.pos.y + 80 + (i*30) }, vel: { x: leader.facing * 45, y: i * 4 }, width: 50, height: 16, owner: 'player', damage: 300, color: '#facc15', health: 1, maxHealth: 1 });
          leader.lastShot = e.frame;
        }
      } else {
        e.players.forEach((p, i) => {
          if (p.health <= 0) return;
          const stats = ROBOT_STATS[p.unit]; 
          const s = p.isTransformed ? stats.alt : stats.robot;
          const isFalconJet = p.unit === RobotUnit.FALCON && p.isTransformed;

          if (i === activeLeaderIndex) {
            // Leader movement control
            if (moveRight) { p.vel.x = s.speed; p.facing = 1; } else if (moveLeft) { p.vel.x = -s.speed; p.facing = -1; } else p.vel.x *= 0.8;

            if (isFalconJet) {
              // FALCON FLIGHT: Vertical movement control in Jet mode using Up/Down arrow keys
              if (moveUp) p.vel.y = -s.speed;
              else if (moveDown) p.vel.y = s.speed;
              else p.vel.y *= 0.92; // Air stabilization damping
              p.grounded = false;
            } else {
              if (moveUp && p.grounded) { p.vel.y = s.jump; p.grounded = false; }
              p.vel.y += GRAVITY;
            }
          } else {
            // Squad follower AI: Handover logic allows others to continue if Sentinel dies
            const targetX = leader.pos.x - ((i - activeLeaderIndex) * 110 * leader.facing); 
            const dist = targetX - p.pos.x;
            if (Math.abs(dist) > 50) { p.vel.x = Math.sign(dist) * s.speed * 0.98; p.facing = Math.sign(dist) || 1; } else p.vel.x *= 0.8;

            if (isFalconJet) {
              // Automated flight height following for followers
              const targetY = leader.pos.y + (i * 35);
              const hDist = targetY - p.pos.y;
              if (Math.abs(hDist) > 10) p.vel.y = Math.sign(hDist) * s.speed * 0.7;
              else p.vel.y *= 0.85;
            } else {
              if (leader.vel.y < -5 && p.grounded) { p.vel.y = s.jump; p.grounded = false; }
              p.vel.y += GRAVITY;
            }
          }

          p.pos.x += p.vel.x; p.pos.y += p.vel.y;

          // Clamp within world bounds
          if (p.pos.y > GROUND_Y - p.height) { 
            p.pos.y = GROUND_Y - p.height; 
            p.vel.y = 0; 
            p.grounded = true; 
          }
          if (p.pos.y < 50) { p.pos.y = 50; p.vel.y = 0; }

          if (firing && e.frame - p.lastShot > s.fireRate) {
            soundService.playShoot();
            e.bullets.push({ pos: { x: p.pos.x + 25, y: p.pos.y + 30 }, vel: { x: p.facing * 35, y: 0 }, width: 35, height: 14, owner: 'player', damage: 150, color: stats.color, health: 1, maxHealth: 1 });
            p.lastShot = e.frame;
          }
          if (p.invulnerable > 0) p.invulnerable--;
        });
      }

      // Bullet logic
      for (let i = e.bullets.length - 1; i >= 0; i--) {
        const b = e.bullets[i]; b.pos.x += b.vel.x; b.pos.y += b.vel.y || 0;
        if (b.owner === 'enemy') {
          if (e.isCombined) {
            const currentCombined = e.players.find(p => p.health > 0);
            if (currentCombined && !currentCombined.invulnerable && b.pos.x < currentCombined.pos.x + currentCombined.width && b.pos.x + b.width > currentCombined.pos.x && b.pos.y < currentCombined.pos.y + currentCombined.height && b.pos.y + b.height > currentCombined.pos.y) {
              e.combinedHealth -= 100; currentCombined.invulnerable = 25; e.bullets.splice(i, 1); if (e.combinedHealth <= 0) onDie();
            }
          } else {
            e.players.forEach(p => { if (p.health > 0 && !p.invulnerable && b.pos.x < p.pos.x + p.width && b.pos.x + b.width > p.pos.x && b.pos.y < p.pos.y + p.height && b.pos.y + b.height > p.pos.y) { p.health -= 50; p.invulnerable = 40; e.bullets.splice(i, 1); } });
          }
        }
        if (Math.abs(b.pos.x - leader.pos.x) > 4000) e.bullets.splice(i, 1);
      }

      // Enemy behavior - Ground rogue robots only
      let enemiesAliveCount = 0;
      e.enemies.forEach(en => {
        if (en.isDead) return;
        enemiesAliveCount++;
        en.pos.x += Math.sign(leader.pos.x - en.pos.x) * 1.6;
        en.pos.y = GROUND_Y - en.height;

        if (Math.abs(en.pos.x - leader.pos.x) < 1400 && e.frame - en.lastShot > 75) {
          e.bullets.push({ pos: { x: en.pos.x, y: en.pos.y + 40 }, vel: { x: Math.sign(leader.pos.x - en.pos.x) * 14, y: 0 }, width: 25, height: 14, owner: 'enemy', health: 1, maxHealth: 1, damage: 40, color: '#ff0055' });
          en.lastShot = e.frame;
        }

        e.bullets.forEach((b, bi) => { 
          if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) { 
            en.isDead = true; 
            e.bullets.splice(bi, 1); 
            soundService.playDrive(0.3);
          } 
        });
      });

      if (enemiesAliveCount === 0) onWin();
      e.cameraX = leader.pos.x - 700;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const activeLeader = e.players.find(p => p.health > 0);
      if (!activeLeader) return;

      drawCityscape(ctx, e);
      ctx.save(); ctx.translate(-e.cameraX, 0);
      ctx.fillStyle = '#06060a'; ctx.fillRect(e.cameraX - 2500, GROUND_Y, CANVAS_WIDTH + 5000, 300);
      ctx.strokeStyle = '#00f3ff11'; ctx.lineWidth = 5;
      for (let gx = Math.floor((e.cameraX - 2500) / 120) * 120; gx < e.cameraX + 5500; gx += 120) { ctx.beginPath(); ctx.moveTo(gx, GROUND_Y); ctx.lineTo(gx, GROUND_Y + 300); ctx.stroke(); }

      e.enemies.forEach(en => { if(!en.isDead) drawUnit(ctx, en.pos.x, en.pos.y, en.width, en.height, RobotUnit.SENTINEL, Math.sign(activeLeader.pos.x - en.pos.x), e.frame, true, false, false, 1.6, false, en.type); });

      if (e.isCombined) {
          drawUnit(ctx, activeLeader.pos.x, activeLeader.pos.y, activeLeader.width, activeLeader.height, activeLeader.unit, activeLeader.facing, e.frame, false, activeLeader.invulnerable > 0, false, 1, true);
      } else {
          e.players.forEach(p => { if(p.health > 0) drawUnit(ctx, p.pos.x, p.pos.y, p.width, p.height, p.unit, p.facing, e.frame, false, p.invulnerable > 0, p.isTransformed, 1); });
      }

      e.bullets.forEach(b => { ctx.fillStyle = b.color || '#fff'; ctx.fillRect(b.pos.x, b.pos.y, b.width, b.height); });
      ctx.restore();
      drawHUD(ctx, e);
    };
    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [onWin, onDie, upgrades, level]);

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden font-orbitron">
      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full max-h-[100vh] aspect-video shadow-[0_0_250px_rgba(0,0,0,1)]" />
    </div>
  );
};

