import { GoogleGenAI, Type } from "@google/genai";
import { LevelInfo } from "../types";

const delay = (ms: number) => new Promise(res => setTimeout(res, ms));

export const getStaticBriefing = (level: number): LevelInfo => {
  return {
    level,
    title: level === 20 ? "Project Earthrise" : (level === 5 ? "Tank-former Breach" : (level === 10 ? "Colossus Conflict" : `Sector ${level} Cleanup`)),
    description: level === 5 
      ? "Massive heavy-tread units have breached the outer wall. Mobilize the EarthBot squad to halt their advance." 
      : (level === 20 ? "The Rogue Core has manifested. This is the end of the line for humanity. Combine and conquer or fall forever." : "Scouts report rogue hardware active in this sector. Neutralize all targets to secure the area."),
    threatLevel: level >= 20 ? "EXTINCTION" : (level >= 10 ? "Critical" : (level >= 5 ? "High" : "Moderate")),
    enemyType: level === 20 ? "Rogue Core Sovereign" : (level === 10 ? "Prototype Colossus" : (level === 5 ? "Siege Tanks" : "Rogue Hardware"))
  };
};

async function callGeminiWithRetry(level: number, specialPrompt: string, retries = 2): Promise<any> {
  const currentAttempt = 3 - retries;

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Generate a short mission briefing for Level ${level} of a game called EarthBots. 
      The EarthBots are specialized defenders protecting the planet from a rogue machine uprising.
      ${specialPrompt || "The goal is to destroy hostiles in the sector."}
      Provide a cool title, threat level, and a 2-sentence description emphasizing the high-tech mechanical warfare.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            level: { type: Type.INTEGER },
            title: { type: Type.STRING },
            description: { type: Type.STRING },
            threatLevel: { type: Type.STRING },
            enemyType: { type: Type.STRING }
          },
          required: ["level", "title", "description", "threatLevel", "enemyType"]
        }
      }
    });

    if (!response.text) throw new Error("Empty response from AI");
    return JSON.parse(response.text);
  } catch (error: any) {
    const errorString = JSON.stringify(error).toLowerCase();
    const isQuotaError = 
      error?.status === 429 || 
      error?.message?.includes('429') || 
      errorString.includes('resource_exhausted') ||
      errorString.includes('quota');

    if (retries > 0 && isQuotaError) {
      const waitTime = Math.pow(2, currentAttempt) * 1000;
      await delay(waitTime);
      return callGeminiWithRetry(level, specialPrompt, retries - 1);
    }

    throw error;
  }
}

export const getLevelBriefing = async (level: number): Promise<LevelInfo> => {
  let specialPrompt = "";
  if (level === 5) specialPrompt = "EarthBots face a battalion of heavy 'Tank-formers' leveling the district.";
  if (level === 10) specialPrompt = "Gigantus Titan encounter. The rogue AI has sent its own combiner robot.";
  if (level === 20) specialPrompt = "FINAL SIEGE. EarthBots must stop a Cyber Dragon and a full Legion. Apocalypse scenario.";

  try {
    return await callGeminiWithRetry(level, specialPrompt);
  } catch (error: any) {
    console.warn("Gemini service unavailable, using local EarthBot data.", error.message || error);
    return getStaticBriefing(level);
  }
};

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { GameState, LevelInfo, RobotUnit, Upgrades } from './types';
import { getLevelBriefing, getStaticBriefing } from './services/geminiService';
import MainMenu from './components/MainMenu';
import Briefing from './components/Briefing';
import GameView from './components/GameView';
import GameOver from './components/GameOver';
import Victory from './components/Victory';
import Shop from './components/Shop';
import LevelSelect from './components/LevelSelect';
import HowToPlay from './components/HowToPlay';

const SAVE_KEY = 'earthbots_save_data_v4';

const DEFAULT_UPGRADES: Upgrades = { 
  robotTier: 0, 
  weaponTier: 0, 
  unlockedUnits: [RobotUnit.SENTINEL]
};

const App: React.FC = () => {
  const [saveData, setSaveData] = useState(() => {
    const data = localStorage.getItem(SAVE_KEY);
    if (!data) return null;
    try {
      return JSON.parse(data);
    } catch (e) {
      return null;
    }
  });

  const [gameState, setGameState] = useState<GameState>(GameState.MENU);
  const [level, setLevel] = useState<number>(saveData?.level || 1);
  const [maxUnlockedLevel, setMaxUnlockedLevel] = useState<number>(saveData?.maxUnlockedLevel || 1);
  const [money, setMoney] = useState<number>(saveData?.money || 0);
  const [upgrades, setUpgrades] = useState<Upgrades>(saveData?.upgrades || DEFAULT_UPGRADES);

  const [briefing, setBriefing] = useState<LevelInfo | null>(null);
  const [isBriefingLoading, setIsBriefingLoading] = useState(false);
  const [shopOrigin, setShopOrigin] = useState<GameState>(GameState.MENU);

  useEffect(() => {
    const dataToSave = { level, maxUnlockedLevel, money, upgrades };
    localStorage.setItem(SAVE_KEY, JSON.stringify(dataToSave));
  }, [level, maxUnlockedLevel, money, upgrades]);

  useEffect(() => {
    const handleGlobalKeyDown = (e: KeyboardEvent) => {
      if (e.code === 'KeyP') {
        setGameState(prev => {
          if (prev === GameState.PLAYING) return GameState.PAUSED;
          if (prev === GameState.PAUSED) return GameState.PLAYING;
          return prev;
        });
      }
    };
    window.addEventListener('keydown', handleGlobalKeyDown);
    return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, []);

  const handleOpenKeySelection = async () => {
    await (window as any).aistudio.openSelectKey();
    if (gameState === GameState.BRIEFING) {
      startLevel(level);
    }
  };

  const startLevel = useCallback(async (lvl: number) => {
    setGameState(GameState.BRIEFING);
    setLevel(lvl);
    // Immediately show static data
    setBriefing(getStaticBriefing(lvl));
    setIsBriefingLoading(true);

    // Fetch AI briefing in background
    getLevelBriefing(lvl).then(data => {
      setBriefing(data);
      setIsBriefingLoading(false);
    }).catch(() => {
      setIsBriefingLoading(false);
    });
  }, []);

  const handleStartGame = async () => {
    setGameState(GameState.LEVEL_SELECT);
  };

  const handleContinueGame = () => {
    if (saveData) {
      setLevel(saveData.level || 1);
      setMaxUnlockedLevel(saveData.maxUnlockedLevel || 1);
      setMoney(saveData.money || 0);
      setUpgrades(saveData.upgrades || DEFAULT_UPGRADES);
      startLevel(saveData.level || 1);
    } else {
      startLevel(1);
    }
  };

  const handleLevelComplete = () => {
    const reward = level === 20 ? 15000 : 500;
    setMoney(m => m + reward); 
    const newlyUnlocked = level + 1;
    if (newlyUnlocked > maxUnlockedLevel && newlyUnlocked <= 20) {
      setMaxUnlockedLevel(newlyUnlocked);
    }
    setGameState(GameState.LEVEL_COMPLETE);
  };

  const openShop = (origin: GameState) => {
    setShopOrigin(origin);
    setGameState(GameState.SHOP);
  };

  const handleSelectLevel = (lvlNum: number) => {
    setLevel(lvlNum);
    startLevel(lvlNum);
  };

  const handleNextLevel = () => {
    if (level === 20) setGameState(GameState.VICTORY);
    else startLevel(level + 1);
  };

  const handleShopExit = () => {
    setGameState(shopOrigin === GameState.MENU ? GameState.MENU : GameState.LEVEL_COMPLETE);
  };

  const handlePlayerDeath = () => setGameState(GameState.GAMEOVER);

  const buyRobotTier = () => {
    if (money >= 100) {
      setMoney(m => m - 100);
      setUpgrades(u => ({ ...u, robotTier: u.robotTier + 1 }));
    }
  };

  const buyWeaponTier = () => {
    if (money >= 50) {
      setMoney(m => m - 50);
      setUpgrades(u => ({ ...u, weaponTier: u.weaponTier + 1 }));
    }
  };

  const unlockRobotUnit = (unit: RobotUnit, price: number) => {
    if (money >= price && !upgrades.unlockedUnits.includes(unit)) {
      setMoney(m => m - price);
      setUpgrades(u => ({
        ...u,
        unlockedUnits: [...u.unlockedUnits, unit]
      }));
    }
  };

  const isGameVisible = gameState === GameState.PLAYING || gameState === GameState.PAUSED;

  return (
    <div className="w-full h-screen bg-black overflow-hidden select-none text-white font-rajdhani flex flex-col">
      <button onClick={handleOpenKeySelection} className="fixed bottom-4 right-4 z-[100] px-4 py-1 text-[10px] bg-gray-900/50 border border-gray-700 text-gray-500 hover:text-cyan-400 hover:border-cyan-500 transition-all font-mono uppercase tracking-tighter">
        Configure Uplink (API Key)
      </button>

      <div className="flex-1 overflow-hidden relative">
        {gameState === GameState.MENU && (
          <MainMenu 
            onStart={handleStartGame} 
            onContinue={handleContinueGame} 
            onOpenShop={() => openShop(GameState.MENU)} 
            onOpenLevelSelect={() => setGameState(GameState.LEVEL_SELECT)} 
            onOpenHowToPlay={() => setGameState(GameState.HOW_TO_PLAY)}
            hasSave={!!saveData} 
          />
        )}

        {gameState === GameState.HOW_TO_PLAY && (
          <HowToPlay onBack={() => setGameState(GameState.MENU)} />
        )}

        {gameState === GameState.LEVEL_SELECT && (
          <LevelSelect currentUnlocked={maxUnlockedLevel} onSelect={handleSelectLevel} onBack={() => setGameState(GameState.MENU)} />
        )}

        {gameState === GameState.BRIEFING && (
          <Briefing briefing={briefing || {} as LevelInfo} isLoading={isBriefingLoading} onConfirm={() => setGameState(GameState.PLAYING)} />
        )}

        {isGameVisible && (
          <GameView level={level} upgrades={upgrades} isPaused={gameState === GameState.PAUSED} onWin={handleLevelComplete} onDie={handlePlayerDeath} />
        )}

        {gameState === GameState.PAUSED && (
          <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex flex-col items-center justify-center z-50 p-4">
            <div className="p-10 border-2 border-cyan-500 bg-black/80 relative overflow-hidden group max-w-full">
              <h2 className="text-4xl md:text-6xl font-black text-cyan-400 italic tracking-tighter uppercase mb-4 font-orbitron text-center">SYSTEM SUSPENDED</h2>
              <div className="flex flex-col gap-4 items-center">
                <button onClick={() => setGameState(GameState.PLAYING)} className="px-12 py-4 bg-cyan-600 hover:bg-cyan-500 text-white font-bold text-2xl border-b-4 border-cyan-900 transition-all w-full uppercase font-orbitron">RESUME MISSION</button>
                <button onClick={() => setGameState(GameState.MENU)} className="px-12 py-2 text-cyan-400 font-bold hover:text-white transition-all uppercase text-sm font-orbitron">ABORT TO HQ</button>
              </div>
            </div>
          </div>
        )}

        {gameState === GameState.LEVEL_COMPLETE && (
          <div className="fixed inset-0 bg-black/95 flex flex-col items-center justify-start md:justify-center z-50 p-6 overflow-y-auto pt-20 md:pt-6">
            <h2 className="text-4xl md:text-5xl text-cyan-400 mb-2 font-black italic tracking-tighter animate-pulse uppercase font-orbitron text-center">Sector {level} Secured</h2>
            <div className="text-xl md:text-2xl text-yellow-400 mb-8 font-bold tracking-widest font-orbitron text-center">REWARD EARNED: ${level === 20 ? 15000 : 500}</div>
            <div className="flex flex-col items-center gap-6 w-full max-w-xs">
              <button onClick={() => openShop(GameState.LEVEL_COMPLETE)} className="px-8 py-4 bg-yellow-600 hover:bg-yellow-500 text-white font-bold rounded-sm border-b-4 border-yellow-800 transition-all w-full font-orbitron uppercase">VISIT ARMORY</button>
              <button onClick={handleNextLevel} className={`px-12 py-4 font-black rounded-sm transition-all w-full shadow-[0_0_30px_rgba(6,182,212,0.3)] uppercase tracking-widest font-orbitron text-xl ${level >= 20 ? 'bg-white text-black hover:bg-cyan-400' : 'bg-cyan-700 hover:bg-cyan-600 text-white'}`}>{level >= 20 ? 'Finalize Victory' : `Deploy to Sector ${level + 1}`}</button>
              <button onClick={() => setGameState(GameState.MENU)} className="px-12 py-2 text-gray-400 font-bold hover:text-white transition-all uppercase text-sm mt-4 border border-gray-800 hover:border-gray-400 bg-gray-950/40 font-orbitron w-full">Return to HQ</button>
            </div>
          </div>
        )}

        {gameState === GameState.SHOP && (
          <Shop money={money} upgrades={upgrades} onBuyRobot={buyRobotTier} onBuyWeapon={buyWeaponTier} onUnlockUnit={unlockRobotUnit} onExit={handleShopExit} isFromMenu={shopOrigin === GameState.MENU} />
        )}

        {gameState === GameState.GAMEOVER && (
          <GameOver level={level} onRetry={() => startLevel(level)} onMenu={() => setGameState(GameState.MENU)} />
        )}

        {gameState === GameState.VICTORY && <Victory onMenu={() => setGameState(GameState.MENU)} />}
      </div>
    </div>
  );
};

export default App;

