import React, { useState, useEffect, useCallback } from 'react';
import { Settings as SettingsIcon, X, ShieldAlert, Key, RotateCcw, BarChart3, Music as MusicIcon, Volume2, VolumeX, ChevronRight } from 'lucide-react';
import { GameState, LevelInfo, RobotUnit, Upgrades } from './types';
import { getLevelBriefing, getStaticBriefing } from './services/geminiService';
import { soundService } from './services/soundService';
import MainMenu from './components/MainMenu';
import Briefing from './components/Briefing';
import GameView from './components/GameView';
import GameOver from './components/GameOver';
import Victory from './components/Victory';
import Shop from './components/Shop';
import LevelSelect from './components/LevelSelect';
import HowToPlay from './components/HowToPlay';

const SAVE_KEY = 'earthbots_save_data_v4';
const SETTINGS_KEY = 'earthbots_settings_v3';

const DEFAULT_UPGRADES: Upgrades = { 
  robotTier: 0, 
  weaponTier: 0, 
  unlockedUnits: [RobotUnit.SENTINEL]
};

const App: React.FC = () => {
  const [saveData, setSaveData] = useState(() => {
    const data = localStorage.getItem(SAVE_KEY);
    if (!data) return null;
    try { return JSON.parse(data); } catch (e) { return null; }
  });

  const [settings, setSettings] = useState(() => {
    const data = localStorage.getItem(SETTINGS_KEY);
    if (!data) return { music: true, sound: true };
    try { return JSON.parse(data); } catch (e) { return { music: true, sound: true }; }
  });

  const [gameState, setGameState] = useState<GameState>(GameState.MENU);
  const [level, setLevel] = useState<number>(saveData?.level || 1);
  const [maxUnlockedLevel, setMaxUnlockedLevel] = useState<number>(saveData?.maxUnlockedLevel || 1);
  const [money, setMoney] = useState<number>(saveData?.money || 0);
  const [upgrades, setUpgrades] = useState<Upgrades>(saveData?.upgrades || DEFAULT_UPGRADES);

  const [briefing, setBriefing] = useState<LevelInfo | null>(null);
  const [isBriefingLoading, setIsBriefingLoading] = useState(false);
  const [shopOrigin, setShopOrigin] = useState<GameState>(GameState.MENU);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  useEffect(() => {
    const dataToSave = { level, maxUnlockedLevel, money, upgrades };
    localStorage.setItem(SAVE_KEY, JSON.stringify(dataToSave));
  }, [level, maxUnlockedLevel, money, upgrades]);

  useEffect(() => {
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
    soundService.soundEnabled = settings.sound;
  }, [settings]);

  useEffect(() => {
    const handleGlobalKeyDown = (e: KeyboardEvent) => {
      if (e.code === 'KeyP') {
        setGameState(prev => {
          if (prev === GameState.PLAYING) return GameState.PAUSED;
          if (prev === GameState.PAUSED) return GameState.PLAYING;
          return prev;
        });
      }
      if (e.code === 'Escape') {
        setIsSettingsOpen(false);
      }
    };
    window.addEventListener('keydown', handleGlobalKeyDown);
    return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, []);

  const handleOpenKeySelection = async () => {
    await (window as any).aistudio.openSelectKey();
    if (gameState === GameState.BRIEFING) {
      startLevel(level);
    }
  };

  const startLevel = useCallback(async (lvl: number) => {
    setGameState(GameState.BRIEFING);
    setLevel(lvl);
    setBriefing(getStaticBriefing(lvl));
    setIsBriefingLoading(true);

    getLevelBriefing(lvl).then(data => {
      setBriefing(data);
      setIsBriefingLoading(false);
    }).catch(() => {
      setIsBriefingLoading(false);
    });
  }, []);

  const handleStartGame = async () => startLevel(1);

  const handleContinueGame = () => {
    if (saveData) {
      setLevel(saveData.level || 1);
      setMaxUnlockedLevel(saveData.maxUnlockedLevel || 1);
      setMoney(saveData.money || 0);
      setUpgrades(saveData.upgrades || DEFAULT_UPGRADES);
      startLevel(saveData.level || 1);
    } else {
      startLevel(1);
    }
  };

  const handleLevelComplete = () => {
    const reward = level === 20 ? 15000 : 500;
    setMoney(m => m + reward); 
    const newlyUnlocked = level + 1;
    if (newlyUnlocked > maxUnlockedLevel && newlyUnlocked <= 20) {
      setMaxUnlockedLevel(newlyUnlocked);
    }
    setGameState(GameState.LEVEL_COMPLETE);
  };

  const openShop = (origin: GameState) => {
    setShopOrigin(origin);
    setGameState(GameState.SHOP);
  };

  const handleSelectLevel = (lvlNum: number) => {
    setLevel(lvlNum);
    startLevel(lvlNum);
  };

  const handleNextLevel = () => {
    if (level === 20) setGameState(GameState.VICTORY);
    else startLevel(level + 1);
  };

  const handleShopExit = () => {
    setGameState(shopOrigin === GameState.MENU ? GameState.MENU : GameState.LEVEL_COMPLETE);
  };

  const handlePlayerDeath = () => setGameState(GameState.GAMEOVER);

  const resetProgress = () => {
    if (window.confirm("CRITICAL WARNING: ERASE ALL SECURE MISSION DATA?")) {
      localStorage.removeItem(SAVE_KEY);
      window.location.reload();
    }
  };

  const buyRobotTier = () => {
    if (money >= 100) {
      setMoney(m => m - 100);
      setUpgrades(u => ({ ...u, robotTier: u.robotTier + 1 }));
    }
  };

  const buyWeaponTier = () => {
    if (money >= 50) {
      setMoney(m => m - 50);
      setUpgrades(u => ({ ...u, weaponTier: u.weaponTier + 1 }));
    }
  };

  const unlockRobotUnit = (unit: RobotUnit, price: number) => {
    if (money >= price && !upgrades.unlockedUnits.includes(unit)) {
      setMoney(m => m - price);
      setUpgrades(u => ({
        ...u,
        unlockedUnits: [...u.unlockedUnits, unit]
      }));
    }
  };

  const isGameVisible = gameState === GameState.PLAYING || gameState === GameState.PAUSED;

  return (
    <div className="w-full h-screen bg-black overflow-hidden select-none text-white font-rajdhani flex flex-col">
      {/* Settings Toggle (Upper Left) */}
      <button 
        onClick={() => setIsSettingsOpen(true)} 
        className="fixed top-4 left-4 z-[110] p-3 bg-gray-950/80 border border-cyan-900/50 text-cyan-500 hover:text-cyan-400 hover:border-cyan-400 hover:bg-cyan-950 transition-all rounded-full shadow-[0_0_15px_rgba(6,182,212,0.1)] group"
        title="Settings Menu"
      >
        <SettingsIcon className="w-6 h-6 group-hover:rotate-90 transition-transform duration-500" />
      </button>

      {/* Settings Modal (3 Distinct Modules: Progress, Music, Sound) */}
      {isSettingsOpen && (
        <div className="fixed inset-0 z-[150] bg-black/95 backdrop-blur-xl flex items-center justify-center p-4">
          <div className="max-w-3xl w-full bg-black border-2 border-cyan-500 p-8 relative shadow-[0_0_50px_rgba(6,182,212,0.3)] font-orbitron overflow-y-auto max-h-[90vh]">
            <button 
              onClick={() => setIsSettingsOpen(false)}
              className="absolute top-4 right-4 text-gray-500 hover:text-white transition-colors p-2"
            >
              <X className="w-6 h-6" />
            </button>

            <div className="mb-8 border-b-2 border-cyan-900 pb-4">
              <h2 className="text-4xl font-black italic text-cyan-400 tracking-tighter uppercase">Operations Hub</h2>
              <p className="text-[10px] text-cyan-700 tracking-[0.4em] font-bold mt-1">SYSTEM CONFIGURATION // PREFERENCES</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* 1. Progress */}
              <div className="space-y-3">
                <div className="flex items-center gap-2 text-cyan-400 border-b border-cyan-900/50 pb-2">
                  <span className="text-xs font-black bg-cyan-900 px-2 py-0.5 rounded text-white">1</span>
                  <BarChart3 className="w-4 h-4" />
                  <h3 className="text-xs font-black uppercase tracking-widest">Progress</h3>
                </div>
                <div className="bg-gray-950 p-4 border border-gray-800 rounded flex flex-col gap-4">
                  <div>
                    <div className="flex justify-between text-[10px] mb-1">
                      <span className="text-gray-500 font-bold uppercase">Mission Clear Rate</span>
                      <span className="text-cyan-400 font-mono">{maxUnlockedLevel}/20</span>
                    </div>
                    <div className="w-full h-1.5 bg-gray-900 rounded-full overflow-hidden">
                      <div className="h-full bg-cyan-500 shadow-[0_0_10px_rgba(6,182,212,0.8)]" style={{ width: `${(maxUnlockedLevel/20)*100}%` }}></div>
                    </div>
                  </div>
                  <div className="flex flex-col gap-2">
                    <button 
                      onClick={() => { handleOpenKeySelection(); setIsSettingsOpen(false); }}
                      className="w-full flex items-center justify-between p-2.5 bg-cyan-600/10 hover:bg-cyan-600/20 border border-cyan-600/30 hover:border-cyan-500 transition-all text-[9px] font-black uppercase"
                    >
                      <span className="flex items-center gap-2"><Key className="w-3 h-3" /> AI Uplink Setup</span>
                      <ChevronRight className="w-3 h-3" />
                    </button>
                    <button 
                      onClick={resetProgress}
                      className="w-full flex items-center justify-center gap-2 p-2 bg-red-950/10 hover:bg-red-950/30 border border-red-900/40 hover:border-red-500 transition-all text-[9px] font-black uppercase text-red-500"
                    >
                      <RotateCcw className="w-3 h-3" /> Erase Mission Data
                    </button>
                  </div>
                </div>
              </div>

              {/* 2. Music */}
              <div className="space-y-3">
                <div className="flex items-center gap-2 text-cyan-400 border-b border-cyan-900/50 pb-2">
                  <span className="text-xs font-black bg-cyan-900 px-2 py-0.5 rounded text-white">2</span>
                  <MusicIcon className="w-4 h-4" />
                  <h3 className="text-xs font-black uppercase tracking-widest">Music</h3>
                </div>
                <button 
                  onClick={() => setSettings(s => ({ ...s, music: !s.music }))}
                  className={`w-full p-6 flex items-center justify-between border transition-all ${settings.music ? 'border-cyan-500/50 bg-cyan-900/10' : 'border-gray-800 bg-gray-950 opacity-50'}`}
                >
                  <span className="text-[12px] font-black uppercase tracking-widest">{settings.music ? 'ENABLED' : 'DISABLED'}</span>
                  {settings.music ? <Volume2 className="w-6 h-6 text-cyan-400" /> : <VolumeX className="w-6 h-6 text-gray-600" />}
                </button>
              </div>

              {/* 3. Sound */}
              <div className="space-y-3">
                <div className="flex items-center gap-2 text-cyan-400 border-b border-cyan-900/50 pb-2">
                  <span className="text-xs font-black bg-cyan-900 px-2 py-0.5 rounded text-white">3</span>
                  <Volume2 className="w-4 h-4" />
                  <h3 className="text-xs font-black uppercase tracking-widest">Sound</h3>
                </div>
                <button 
                  onClick={() => setSettings(s => ({ ...s, sound: !s.sound }))}
                  className={`w-full p-6 flex items-center justify-between border transition-all ${settings.sound ? 'border-cyan-500/50 bg-cyan-900/10' : 'border-gray-800 bg-gray-950 opacity-50'}`}
                >
                  <span className="text-[12px] font-black uppercase tracking-widest">{settings.sound ? 'ENABLED' : 'DISABLED'}</span>
                  {settings.sound ? <Volume2 className="w-6 h-6 text-cyan-400" /> : <VolumeX className="w-6 h-6 text-gray-600" />}
                </button>
              </div>
            </div>

            <div className="mt-10 space-y-4">
              <button 
                onClick={() => setIsSettingsOpen(false)}
                className="w-full py-5 bg-cyan-600 hover:bg-cyan-500 text-white font-black text-xl transition-all border-b-8 border-cyan-950 uppercase shadow-[0_15px_30px_rgba(6,182,212,0.2)] active:translate-y-1 active:border-b-4"
              >
                Sync Terminal & Exit
              </button>
              <div className="flex items-center justify-center gap-2 opacity-20">
                <ShieldAlert className="w-4 h-4 text-cyan-500" />
                <span className="text-[8px] uppercase tracking-[0.5em] font-mono">EDN-SECURE-PROTOCOL ACTIVE</span>
              </div>
            </div>
          </div>
        </div>
      )}

      <div className="flex-1 overflow-hidden relative">
        {gameState === GameState.MENU && (
          <MainMenu 
            onStart={handleStartGame} 
            onContinue={handleContinueGame} 
            onOpenShop={() => openShop(GameState.MENU)} 
            onOpenLevelSelect={() => setGameState(GameState.LEVEL_SELECT)} 
            onOpenHowToPlay={() => setGameState(GameState.HOW_TO_PLAY)}
            hasSave={!!saveData} 
          />
        )}

        {gameState === GameState.HOW_TO_PLAY && (
          <HowToPlay onBack={() => setGameState(GameState.MENU)} />
        )}

        {gameState === GameState.LEVEL_SELECT && (
          <LevelSelect currentUnlocked={maxUnlockedLevel} onSelect={handleSelectLevel} onBack={() => setGameState(GameState.MENU)} />
        )}

        {gameState === GameState.BRIEFING && (
          <Briefing briefing={briefing || {} as LevelInfo} isLoading={isBriefingLoading} onConfirm={() => setGameState(GameState.PLAYING)} />
        )}

        {isGameVisible && (
          <GameView level={level} upgrades={upgrades} isPaused={gameState === GameState.PAUSED} onWin={handleLevelComplete} onDie={handlePlayerDeath} />
        )}

        {gameState === GameState.PAUSED && (
          <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex flex-col items-center justify-center z-50 p-4">
            <div className="p-10 border-2 border-cyan-500 bg-black/80 relative overflow-hidden group max-w-full font-orbitron">
              <h2 className="text-4xl md:text-6xl font-black text-cyan-400 italic tracking-tighter uppercase mb-4 text-center">SYSTEM SUSPENDED</h2>
              <div className="flex flex-col gap-4 items-center">
                <button onClick={() => setGameState(GameState.PLAYING)} className="px-12 py-4 bg-cyan-600 hover:bg-cyan-500 text-white font-bold text-2xl border-b-4 border-cyan-900 transition-all w-full uppercase">RESUME MISSION</button>
                <button onClick={() => setGameState(GameState.MENU)} className="px-12 py-2 text-cyan-400 font-bold hover:text-white transition-all uppercase text-sm">ABORT TO HQ</button>
              </div>
            </div>
          </div>
        )}

        {gameState === GameState.LEVEL_COMPLETE && (
          <div className="fixed inset-0 bg-black/95 flex flex-col items-center justify-start md:justify-center z-50 p-6 overflow-y-auto pt-20 md:pt-6 font-orbitron">
            <h2 className="text-4xl md:text-5xl text-cyan-400 mb-2 font-black italic tracking-tighter animate-pulse uppercase text-center">Sector {level} Secured</h2>
            <div className="text-xl md:text-2xl text-yellow-400 mb-8 font-bold tracking-widest text-center">REWARD EARNED: ${level === 20 ? 15000 : 500}</div>
            <div className="flex flex-col items-center gap-6 w-full max-w-xs">
              <button onClick={() => openShop(GameState.LEVEL_COMPLETE)} className="px-8 py-4 bg-yellow-600 hover:bg-yellow-500 text-white font-bold rounded-sm border-b-4 border-yellow-800 transition-all w-full uppercase">VISIT ARMORY</button>
              <button onClick={handleNextLevel} className={`px-12 py-4 font-black rounded-sm transition-all w-full shadow-[0_0_30px_rgba(6,182,212,0.3)] uppercase tracking-widest text-xl ${level >= 20 ? 'bg-white text-black hover:bg-cyan-400' : 'bg-cyan-700 hover:bg-cyan-600 text-white'}`}>{level >= 20 ? 'Finalize Victory' : `Deploy to Sector ${level + 1}`}</button>
              <button onClick={() => setGameState(GameState.MENU)} className="px-12 py-2 text-gray-400 font-bold hover:text-white transition-all uppercase text-sm mt-4 border border-gray-800 hover:border-gray-400 bg-gray-950/40 w-full">Return to HQ</button>
            </div>
          </div>
        )}

        {gameState === GameState.SHOP && (
          <Shop money={money} upgrades={upgrades} onBuyRobot={buyRobotTier} onBuyWeapon={buyWeaponTier} onUnlockUnit={unlockRobotUnit} onExit={handleShopExit} isFromMenu={shopOrigin === GameState.MENU} />
        )}

        {gameState === GameState.GAMEOVER && (
          <GameOver level={level} onRetry={() => startLevel(level)} onMenu={() => setGameState(GameState.MENU)} />
        )}

        {gameState === GameState.VICTORY && <Victory onMenu={() => setGameState(GameState.MENU)} />}
      </div>
    </div>
  );
};

export default App;

