interface LevelSelectProps {
  onSelect: (level: number) => void;
  onBack: () => void;
  currentUnlocked: number;
}

const CHAPTERS = [
  { id: 1, title: "THE AWAKENING", description: "Rogue machines have seized the city center. Reclaim the urban sectors.", status: "UNLOCKED", color: "cyan" },
  { id: 2, title: "SANDS OF WASTE", description: "The core has moved to the industrial wastes. Secure the perimeter.", status: "LOCKED", color: "orange" },
  { id: 3, title: "ORBITAL BREACH", description: "Combat high-altitude hostiles and satellite relay towers.", status: "LOCKED", color: "purple" },
