  MENU = 'MENU',
  BRIEFING = 'BRIEFING',
  PLAYING = 'PLAYING',
  PAUSED = 'PAUSED',
  GAMEOVER = 'GAMEOVER',
  VICTORY = 'VICTORY',
  LEVEL_COMPLETE = 'LEVEL_COMPLETE',
  SHOP = 'SHOP',
  LEVEL_SELECT = 'LEVEL_SELECT',
  HOW_TO_PLAY = 'HOW_TO_PLAY'
}

export enum RobotUnit {
  SENTINEL = 'SENTINEL',
  STRIKER = 'STRIKER',
  FALCON = 'FALCON',
  TITAN = 'TITAN',
  SPECTER = 'SPECTER',
  VANGUARD = 'VANGUARD',
  NIGHTSHADE = 'NIGHTSHADE',
