        <div className="absolute -top-4 left-10 bg-cyan-600 px-4 py-1 text-white font-black italic font-orbitron uppercase text-sm">Tactical Interface v5.0</div>

        <div className="flex justify-between items-center mb-8 border-b border-cyan-900 pb-4">
          <div className="flex items-center gap-4">
            {view === 'sectors' && (
              <button 
                onClick={() => setView('chapters')}
                className="p-2 hover:bg-cyan-900/40 text-cyan-400 transition-colors border border-cyan-900"
              >
                <ChevronLeft className="w-5 h-5" />
              </button>
            )}
            <h2 className="text-4xl font-black text-white italic tracking-tighter uppercase font-orbitron">
              {view === 'chapters' ? "SELECT " : `CHAPTER 0${selectedChapter?.id}: `} 
              <span className="text-cyan-400">{view === 'chapters' ? "CHAPTER" : "SECTORS"}</span>
            </h2>
          </div>
          <button 
            onClick={handleBack}
            className="text-cyan-400 hover:text-white transition-colors font-bold uppercase text-sm border border-cyan-500/30 px-4 py-1 font-orbitron"
          >
            {view === 'sectors' ? "Back to Chapters" : "Back to HQ"}
          </button>
        </div>

        {view === 'chapters' ? (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8 flex-1">
            {CHAPTERS_DATA.map(ch => {
              const isUnlocked = ch.id === 1 || currentUnlocked >= ch.startLvl;
              return (
                <button
                  key={ch.id}
                  disabled={!isUnlocked}
                  onClick={() => handleChapterClick(ch)}
                  className={`relative group p-6 border-2 transition-all text-left flex flex-col justify-between h-48 ${
                    isUnlocked
                      ? 'border-cyan-800 bg-cyan-950/10 hover:border-cyan-400 hover:bg-cyan-900/30 cursor-pointer shadow-[inset_0_0_20px_rgba(6,182,212,0.1)]'
                      : 'border-gray-900 bg-gray-950 cursor-not-allowed opacity-50 grayscale'
                  }`}
                >
                  <div className="absolute top-2 right-4 text-[10px] font-mono tracking-widest text-gray-500">MISSION_PACK_0{ch.id}</div>

                  <div>
                    <h3 className={`text-2xl font-black font-orbitron ${isUnlocked ? 'text-white' : 'text-gray-600'}`}>
                      CHAPTER {ch.id}: {ch.title}
                    </h3>
                    <p className="text-xs text-gray-400 mt-2 line-clamp-2 italic font-medium">
                      {ch.description}
                    </p>
                  </div>

                  <div className="flex justify-between items-center mt-4">
                    <div className={`text-[10px] font-bold uppercase tracking-widest ${isUnlocked ? 'text-cyan-400' : 'text-red-900'}`}>
                      {isUnlocked ? (
                        <span className="flex items-center gap-2"><Map className="w-3 h-3"/> {ch.sectors} SECTORS DISCOVERED</span>
                      ) : (
                        <span className="flex items-center gap-2"><Lock className="w-3 h-3"/> ACCESS RESTRICTED</span>
                      )}
                    </div>
                    {isUnlocked && (
                      <div className="text-xs font-black text-cyan-400 group-hover:translate-x-2 transition-transform">DEPLOY >></div>
                    )}
                  </div>
                </button>
              );
            })}
          </div>
        ) : (
          <div className="grid grid-cols-2 sm:grid-cols-4 md:grid-cols-5 gap-4 mb-8 flex-1">
            {selectedChapter && [...Array(selectedChapter.sectors)].map((_, i) => {
              const levelNum = selectedChapter.startLvl + i;
              const isUnlocked = levelNum <= currentUnlocked;

              return (
                <button
                  key={levelNum}
                  disabled={!isUnlocked}
                  onClick={() => onSelect(levelNum)}
                  className={`relative group h-24 flex flex-col items-center justify-center border-2 transition-all overflow-hidden ${
                    isUnlocked 
                      ? 'border-cyan-800 bg-cyan-950/20 hover:border-cyan-400 hover:bg-cyan-900/40 cursor-pointer shadow-[inset_0_0_10px_rgba(6,182,212,0.1)]' 
                      : 'border-gray-900 bg-gray-950 cursor-not-allowed opacity-40 grayscale'
                  }`}
                >
                  {!isUnlocked && (
                    <div className="absolute inset-0 flex items-center justify-center bg-black/60 z-10">
                      <Lock className="w-4 h-4 text-gray-700" />
                    </div>
                  )}
                  <div className="absolute top-1 left-1 text-[8px] text-cyan-600 font-mono uppercase">SEC_{levelNum.toString().padStart(2, '0')}</div>
                  <span className={`text-2xl font-black font-orbitron ${isUnlocked ? 'text-white group-hover:text-cyan-400' : 'text-gray-700'}`}>
                    {levelNum}
                  </span>
                  <span className={`text-[10px] uppercase tracking-widest font-bold mt-1 font-orbitron ${isUnlocked ? 'text-cyan-800' : 'text-gray-800'}`}>Sector</span>

                  {(levelNum === 20 || levelNum === 36) && <div className="absolute bottom-1 right-1 text-[6px] bg-red-900 text-red-200 px-1 font-orbitron uppercase">BOSS</div>}
                  {isUnlocked && <Crosshair className="absolute top-1 right-1 w-2 h-2 text-cyan-500/30 group-hover:text-cyan-400 transition-colors" />}
                </button>
              );
            })}
          </div>
        )}

        <div className="mt-auto pt-6 flex flex-col gap-6">
          <button 
            onClick={handleBack}
            className="w-full py-4 bg-gray-900 hover:bg-gray-800 text-cyan-400 font-black border border-cyan-900 hover:border-cyan-400 transition-all uppercase font-orbitron tracking-widest text-lg shadow-[0_0_20px_rgba(6,182,212,0.1)] active:scale-[0.98]"
          >
            {view === 'sectors' ? "RETURN TO CHAPTER SELECTION" : "EXIT TO MAIN MENU"}
          </button>

          <div className="flex justify-center gap-8 border-t border-white/5 pt-4">
            <div className="flex items-center gap-2">
              <div className="w-3 h-3 bg-cyan-900/40 border border-cyan-800"></div>
              <span className="text-[10px] text-gray-500 font-orbitron uppercase tracking-widest">Active Operative Zone</span>
            </div>
            <div className="flex items-center gap-2">
              <div className="w-3 h-3 bg-gray-950 border border-gray-900 opacity-40"></div>
              <span className="text-[10px] text-gray-500 font-orbitron uppercase tracking-widest">Restricted Airspace</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default LevelSelect;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';
import { ChevronRight } from 'lucide-react';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 1600;
const CANVAS_HEIGHT = 900;
const GRAVITY = 0.5;
const GROUND_Y = 750;

interface PlayerEntity {
  unit: RobotUnit;
  pos: { x: number; y: number };
  vel: { x: number; y: number };
  width: number;
  height: number;
  facing: number;
  grounded: boolean;
  lastShot: number;
  invulnerable: number;
  health: number;
  maxHealth: number;
  isTransformed: boolean;
  id: string;
}

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { name: "SENTINEL", color: '#ffffff', hpMult: 1.0, robot: { speed: 5, jump: -12, fireRate: 15 }, alt: { speed: 10, jump: -6, fireRate: 25, type: 'Police Car' }},
  [RobotUnit.STRIKER]: { name: "STRIKER", color: '#fbbf24', hpMult: 0.8, robot: { speed: 7, jump: -10, fireRate: 10 }, alt: { speed: 15, jump: -4, fireRate: 20, type: 'Police Motorcycle' }},
  [RobotUnit.FALCON]: { name: "FALCON", color: '#22d3ee', hpMult: 0.7, robot: { speed: 6, jump: -15, fireRate: 12 }, alt: { speed: 14, jump: -12, fireRate: 15, type: 'Jet' }},
  [RobotUnit.TITAN]: { name: "TITAN", color: '#ef4444', hpMult: 2.5, robot: { speed: 3.5, jump: -13, fireRate: 30 }, alt: { speed: 5, jump: 0, fireRate: 20, type: 'Tank' }},
  [RobotUnit.SPECTER]: { name: "SPECTER", color: '#a855f7', hpMult: 0.6, robot: { speed: 6, jump: -11, fireRate: 20 }, alt: { speed: 8, jump: -5, fireRate: 40, type: 'Ambulance' }},
  [RobotUnit.VANGUARD]: { name: "VANGUARD", color: '#10b981', hpMult: 2.0, robot: { speed: 4.5, jump: -12, fireRate: 25 }, alt: { speed: 7, jump: -4, fireRate: 30, type: 'Fire Truck' }},
  [RobotUnit.NIGHTSHADE]: { name: "NIGHTSHADE", color: '#6366f1', hpMult: 0.9, robot: { speed: 8, jump: -14, fireRate: 12 }, alt: { speed: 12, jump: -10, fireRate: 18, type: 'Cyber Tiger' }},
  [RobotUnit.BLAZE]: { name: "BLAZE", color: '#f97316', hpMult: 1.2, robot: { speed: 5.5, jump: -11, fireRate: 18 }, alt: { speed: 18, jump: -6, fireRate: 15, type: 'Race Car' }},
  [RobotUnit.GLITCH]: { name: "GLITCH", color: '#ec4899', hpMult: 1.0, robot: { speed: 6, jump: -12, fireRate: 14 }, alt: { speed: 12, jump: -12, fireRate: 16, type: 'Flying Car' }},
  [RobotUnit.OMEGA]: { name: "OMEGA", color: '#ffffff', hpMult: 3.0, robot: { speed: 8, jump: -16, fireRate: 10 }, alt: { speed: 6, jump: -8, fireRate: 10, type: 'Blimp' }},
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [showCutscene, setShowCutscene] = useState(false);
  const [cutsceneStep, setCutsceneStep] = useState(0);

  const engineRef = useRef({
    players: [] as PlayerEntity[],
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    cameraY: 0,
    isPaused: isPaused,
    level: level,
    upgrades: upgrades,
    isCombined: false,
    combinedHealth: 0,
    combinedMaxHealth: 0,
    winTriggered: false,
  });

  useEffect(() => { 
    engineRef.current.isPaused = isPaused || showCutscene; 
    engineRef.current.level = level;
    engineRef.current.upgrades = upgrades;
  }, [isPaused, level, upgrades, showCutscene]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff88');
    grad.addColorStop(1, '#000000aa');
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.6)';
    ctx.lineWidth = 1;
    ctx.stroke();
  };

  const drawBoss = (ctx: CanvasRenderingContext2D, en: Enemy, frame: number) => {
    ctx.save();
    ctx.translate(en.pos.x + en.width / 2, en.pos.y + en.height / 2);
    ctx.scale(en.facing || 1, 1);

    // Add tilt for vehicle movement
    const tilt = (en.vel.x * 0.05);
    ctx.rotate(tilt);

    const isUpgraded = level > 20;
    const coreColor = isUpgraded ? '#a855f7' : '#ff0000';

    if (en.type === 'titan') {
      ctx.scale(2.5, 2.5);
      drawHumanoid(ctx, '#222222', frame, true, 1, 1.2);
      ctx.fillStyle = coreColor;
      ctx.beginPath(); ctx.arc(-5, -28, 3, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(5, -28, 3, 0, Math.PI * 2); ctx.fill();
    } else if (en.type === 'dragon') {
      const time = frame * 0.1;
      for (let i = 0; i < 8; i++) {
        const ox = -i * 30;
        const oy = Math.sin(time + i * 0.5) * 40;
        ctx.save();
        ctx.translate(ox, oy);
        drawMechanicalPart(ctx, -15, -15, 30, 30, i === 0 ? (isUpgraded ? '#8b5cf6' : '#ff0055') : '#440022', 8);
        if (i === 0) { 
          ctx.fillStyle = coreColor;
          ctx.fillRect(5, -8, 8, 4);
          ctx.beginPath(); ctx.moveTo(15, 0); ctx.lineTo(30, -10); ctx.lineTo(30, 10); ctx.fill();
        }
        ctx.restore();
      }
    } else if (en.type === 'omnidroid') {
      const legTime = frame * 0.2;
      ctx.fillStyle = '#1a1a1a';
      ctx.beginPath(); ctx.arc(0, 0, 40, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = isUpgraded ? '#8b5cf6' : '#ff0055'; ctx.lineWidth = 3; ctx.stroke();
      ctx.fillStyle = coreColor;
      ctx.beginPath(); ctx.arc(10, 0, 8, 0, Math.PI * 2); ctx.fill();
      for (let i = 0; i < 4; i++) {
        const angle = legTime + (i * Math.PI / 2);
        const lx = Math.cos(angle) * 60;
        const ly = Math.sin(angle) * 60;
        ctx.strokeStyle = '#333'; ctx.lineWidth = 6;
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(lx, ly); ctx.stroke();
        ctx.fillStyle = isUpgraded ? '#8b5cf6' : '#ff0055'; ctx.beginPath(); ctx.arc(lx, ly, 5, 0, Math.PI * 2); ctx.fill();
      }
    } else if (en.type === 'tank') {
      const isMoving = Math.abs(en.vel.x) > 0.1;
      const rock = isMoving ? Math.sin(frame * 0.2) * 2 : 0;
      const treadOffset = (frame * en.vel.x * 2) % 40;

      if (!en.isTransformed) {
         drawHumanoid(ctx, '#552222', frame, true, 1, 1.5);
      } else {
        ctx.save();
        ctx.translate(0, rock);
        drawMechanicalPart(ctx, -45, 10, 90, 30, '#111', 8);
        ctx.strokeStyle = '#333'; ctx.lineWidth = 4; ctx.setLineDash([10, 10]);
        ctx.lineDashOffset = -treadOffset; ctx.beginPath();
        ctx.moveTo(-40, 18); ctx.lineTo(40, 18); ctx.moveTo(-40, 32); ctx.lineTo(40, 32);
        ctx.stroke(); ctx.setLineDash([]);
        drawMechanicalPart(ctx, -35, -15, 75, 30, '#331111', 4);
        ctx.save();
        const recoil = (frame % 120 < 10) ? -5 : 0;
        ctx.translate(recoil, 0);
        drawMechanicalPart(ctx, -20, -32, 45, 22, '#552222', 2);
        drawMechanicalPart(ctx, 15, -26, 50, 10, '#111', 1);
        ctx.restore();
        ctx.fillStyle = coreColor; ctx.fillRect(15, -24, 6, 4);
        ctx.restore();
      }
    }
    ctx.restore();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, frame: number, alpha: number, vel: {x:number}) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    const color = ROBOT_STATS[unit].color;
    const tilt = vel.x * 0.02;
    ctx.rotate(tilt);

    switch (unit) {
      case RobotUnit.SENTINEL: 
        drawMechanicalPart(ctx, -35, -10, 70, 24, '#eee', 4);
        drawMechanicalPart(ctx, -35, 0, 70, 14, '#111', 2);
        const siren = Math.sin(frame * 0.5) > 0;
        ctx.fillStyle = siren ? '#f00' : '#00f'; ctx.fillRect(-12, -20, 24, 10);
        break;
      case RobotUnit.STRIKER: 
        drawMechanicalPart(ctx, -20, -8, 40, 15, color, 8);
        ctx.fillStyle = '#111'; ctx.beginPath(); ctx.arc(-18, 12, 10, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(18, 12, 10, 0, Math.PI * 2); ctx.fill();
        const sirenSmall = Math.sin(frame * 0.8) > 0;
        ctx.fillStyle = sirenSmall ? '#f00' : '#00f'; ctx.fillRect(5, -12, 10, 5);
        break;
      case RobotUnit.FALCON: 
        ctx.beginPath(); ctx.moveTo(-40, 0); ctx.lineTo(10, -22); ctx.lineTo(30, 0); ctx.lineTo(10, 22); ctx.closePath();
        ctx.fillStyle = color; ctx.fill();
        drawMechanicalPart(ctx, -45, -8, 85, 16, '#333', 2);
        drawMechanicalPart(ctx, 10, -6, 25, 12, '#00f3ff', 8);
        if (frame % 3 !== 0) {
            ctx.fillStyle = '#ff7700';
            ctx.beginPath(); ctx.moveTo(-45, -5); ctx.lineTo(-65 - (Math.random() * 15), 0); ctx.lineTo(-45, 5); ctx.fill();
        }
        break;
      case RobotUnit.TITAN: 
        drawMechanicalPart(ctx, -40, -5, 80, 25, '#222', 2); 
        drawMechanicalPart(ctx, -30, -22, 60, 22, color, 4);
        drawMechanicalPart(ctx, 15, -16, 45, 10, '#111', 1);
        break;
      case RobotUnit.SPECTER: 
        drawMechanicalPart(ctx, -35, -15, 70, 32, '#fff', 4);
        ctx.fillStyle = '#a855f7'; ctx.fillRect(-6, -8, 12, 16); ctx.fillRect(-18, -2, 36, 4);
        break;
      case RobotUnit.VANGUARD: 
        drawMechanicalPart(ctx, -45, -15, 90, 34, '#d92b2b', 2);
        drawMechanicalPart(ctx, -40, -28, 65, 12, '#888', 1);
        break;
      case RobotUnit.NIGHTSHADE: 
        const legMov = Math.sin(frame * 0.25) * 12;
        drawMechanicalPart(ctx, -30, -15, 60, 25, color, 12);
        drawMechanicalPart(ctx, 25, -22, 18, 18, color, 4);
        drawMechanicalPart(ctx, -25, 8, 10, 18 + legMov, '#111', 2);
        drawMechanicalPart(ctx, 15, 8, 10, 18 - legMov, '#111', 2);
        break;
      case RobotUnit.BLAZE: 
        drawMechanicalPart(ctx, -40, 0, 80, 20, color, 2);
        drawMechanicalPart(ctx, -25, -10, 35, 10, '#111', 12);
        drawMechanicalPart(ctx, -50, -8, 25, 6, color, 1);
        break;
      case RobotUnit.GLITCH: 
        drawMechanicalPart(ctx, -35, -12, 70, 24, color, 15);
        const hoverGlow = 0.6 + Math.sin(frame * 0.4) * 0.4;
        ctx.fillStyle = `rgba(0, 243, 255, ${hoverGlow})`;
        ctx.beginPath(); ctx.arc(-25, 14, 12, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(25, 14, 12, 0, Math.PI * 2); ctx.fill();
        break;
      case RobotUnit.OMEGA: 
        drawMechanicalPart(ctx, -80, -50, 160, 90, '#fff', 45);
        drawMechanicalPart(ctx, -30, 40, 60, 20, '#444', 5);
        break;
      default:
        drawMechanicalPart(ctx, -25, -12, 50, 24, color, 6);
    }
    ctx.restore();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, alpha = 1, sizeMult = 1) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8 * sizeMult;
    const armSwing = Math.cos(time) * 10 * sizeMult;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(sizeMult, sizeMult);
    drawMechanicalPart(ctx, -12, -18, 24, 28, color, 4);
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);

    // Violet eyes/cores for upgraded enemies
    const isUpgraded = isEnemy && level > 20;
    ctx.fillStyle = isUpgraded ? '#a855f7' : (isEnemy ? '#ff0000' : '#00f3ff'); 
    ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);

    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);
    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy: boolean, invulnerable: boolean, transformed: boolean, alpha: number, vel: {x:number}, isCombiner = false, type: string = 'grunt') => {
    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    ctx.scale(facing < 0 ? -1 : 1, 1);
    const drawAlpha = invulnerable ? (0.5 + Math.sin(frame * 0.5) * 0.3) * alpha : alpha;

    if (isCombiner) {
      ctx.save(); ctx.translate(0, -40);
      drawHumanoid(ctx, '#facc15', frame, false, drawAlpha, 3.0);
      ctx.restore();
    } else if (transformed) {
      drawAltMode(ctx, unit, frame, drawAlpha, vel);
    } else {
      const isUpgraded = isEnemy && level > 20;
      drawHumanoid(ctx, isEnemy ? (isUpgraded ? '#8b5cf6' : '#ff0055') : ROBOT_STATS[unit].color, frame, isEnemy, drawAlpha);
    }
    ctx.restore();
  };

  const createPlayer = (unit: RobotUnit, x: number, y: number): PlayerEntity => {
    const stats = ROBOT_STATS[unit];
    const baseHP = 100 + (engineRef.current.upgrades.robotTier * 50);
    return { id: Math.random().toString(36).substr(2, 9), unit, pos: { x, y: GROUND_Y - 48 }, vel: { x: 0, y: 0 }, width: 32, height: 48, facing: 1, grounded: true, lastShot: 0, invulnerable: 0, health: baseHP * stats.hpMult, maxHealth: baseHP * stats.hpMult, isTransformed: false };
  };

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    e.frame = 0; e.cameraX = 0; e.bullets = []; e.isCombined = false;
    e.winTriggered = false;
    e.players = upgrades.unlockedUnits.map((unit, i) => createPlayer(unit, 100 - i * 95, GROUND_Y - 48));

    // Difficulty Scaling for Chapter 2
    const isCh2 = level > 20;
    const hpScalar = isCh2 ? 1.5 : 1;
    const speedScalar = isCh2 ? 1.25 : 1;

    if (level === 20 || level === 36) {
      e.enemies = [
        { id: 101, pos: { x: 2500, y: GROUND_Y - 200 }, vel: { x: 0, y: 0 }, width: 120, height: 200, health: 5000 * hpScalar, maxHealth: 5000 * hpScalar, isDead: false, type: 'titan', lastShot: 0, facing: -1 },
        { id: 102, pos: { x: 3500, y: 200 }, vel: { x: 0, y: 0 }, width: 150, height: 100, health: 3000 * hpScalar, maxHealth: 3000 * hpScalar, isDead: false, type: 'dragon', lastShot: 0, facing: -1 },
        { id: 103, pos: { x: 4500, y: GROUND_Y - 100 }, vel: { x: 0, y: 0 }, width: 100, height: 100, health: 2500 * hpScalar, maxHealth: 2500 * hpScalar, isDead: false, type: 'omnidroid', lastShot: 0, facing: -1 },
      ];
    } else if (level === 5 || level === 25) {
      e.enemies = Array.from({ length: 5 }, (_, i) => ({
        id: i,
        pos: { x: 1800 + i * 1100, y: GROUND_Y - 40 },
        vel: { x: 0, y: 0 },
        width: 80,
        height: 40,
        health: 100 * hpScalar,
        maxHealth: 100 * hpScalar,
        isDead: false,
        type: 'tank',
        lastShot: 0,
        facing: -1,
        isTransformed: false,
        transformTimer: 100 + Math.random() * 200
      }));
    } else {
      const enemyCount = 5;
      e.enemies = Array.from({ length: enemyCount }, (_, i) => {
        const type = 'grunt';
        const width = 48;
        const height = 72;
        const startY = GROUND_Y - height;

        return { 
          id: i, 
          pos: { x: 1800 + i * 1100, y: startY }, 
          vel: { x: 0, y: 0 }, 
          width, 
          height, 
          health: 100 * hpScalar, 
          maxHealth: 100 * hpScalar, 
          isDead: false, 
          type, 
          lastShot: 0,
          facing: -1
        };
      });
    }
  }, [level, upgrades]);

  useEffect(() => { resetLevel(); }, [resetLevel]);

  const drawCityscape = (ctx: CanvasRenderingContext2D, e: any) => {
    const camX = e.cameraX;
    const isCh2 = e.level > 20;

    const skyGrad = ctx.createLinearGradient(0, 0, 0, CANVAS_HEIGHT);
    if (isCh2) {
      // Industrial Waste Palette
      skyGrad.addColorStop(0, '#0c000c');
      skyGrad.addColorStop(0.7, '#1e0a25');
      skyGrad.addColorStop(1, '#4c1d95');
    } else {
      skyGrad.addColorStop(0, '#00000c');
      skyGrad.addColorStop(0.7, '#2a0d08');
      skyGrad.addColorStop(1, '#662200');
    }
    ctx.fillStyle = skyGrad; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    const layers = isCh2 ? [
      { scroll: 0.1, color: '#0f0014', spacing: 450, hMin: 300, hMax: 600 },
      { scroll: 0.4, color: '#1a0025', spacing: 400, hMin: 400, hMax: 850 },
      { scroll: 0.8, color: '#030005', spacing: 350, hMin: 500, hMax: 1000 },
    ] : [
      { scroll: 0.1, color: '#0c0c18', spacing: 450, hMin: 300, hMax: 600 },
      { scroll: 0.4, color: '#1a0f0a', spacing: 400, hMin: 400, hMax: 850 },
      { scroll: 0.8, color: '#050505', spacing: 350, hMin: 500, hMax: 1000 },
    ];

    layers.forEach((layer, li) => {
      ctx.fillStyle = layer.color;
      const startX = Math.floor((camX * layer.scroll) / layer.spacing) * layer.spacing - layer.spacing * 2;
      for (let x = startX; x < startX + CANVAS_WIDTH + layer.spacing * 4; x += layer.spacing) {
        const seed = Math.abs(Math.sin(x * 0.01 + li));
        const h = seed * (layer.hMax - layer.hMin) + layer.hMin;
        const bx = x - (camX * layer.scroll);
        const bw = layer.spacing - 40;
        ctx.fillRect(bx, GROUND_Y - h, bw, h);
        if (li >= 1) {
          const fireSeed = Math.sin(x * 0.9 + e.frame * 0.05);
          if (fireSeed > 0.1) {
            ctx.fillStyle = isCh2 
              ? (fireSeed > 0.7 ? '#a855f7' : '#6b21a8')
              : (fireSeed > 0.7 ? '#ffbb00' : '#d43300');
            for (let r = 0; r < 10; r++) {
              const winY = GROUND_Y - h + 60 + r * 80;
              if (winY < GROUND_Y - 60) {
                ctx.fillRect(bx + 20, winY, 20, 25);
                ctx.fillRect(bx + bw - 40, winY, 20, 25);
              }
            }
          }
          ctx.fillStyle = layer.color;
        }
      }
    });
  };

  const drawHUD = (ctx: CanvasRenderingContext2D, e: any) => {
    ctx.save();
    const hudX = 70; const hudY = 70;
    const hudW = 460; const hudH = e.isCombined ? 130 : e.players.length * 45 + 70;
    ctx.fillStyle = 'rgba(0, 0, 0, 0.92)'; ctx.fillRect(hudX, hudY, hudW, hudH);
    ctx.strokeStyle = '#00f3ff'; ctx.lineWidth = 4; ctx.strokeRect(hudX, hudY, hudW, hudH);
    ctx.font = 'bold 20px Orbitron'; ctx.fillStyle = '#00f3ff';
    ctx.fillText(e.isCombined ? "COMBINER UNIT ACTIVE" : "ALPHA SQUAD: SECTOR " + e.level, hudX + 30, hudY + 45);

    if (e.isCombined) {
      const hRatio = Math.max(0, e.combinedHealth / e.combinedMaxHealth);
      ctx.fillStyle = '#facc15'; ctx.fillText("ULTIMATE ARMOR INTEGRITY", hudX + 30, hudY + 85);
      ctx.fillStyle = '#111'; ctx.fillRect(hudX + 30, hudY + 95, 400, 25);
      ctx.fillStyle = '#facc15'; ctx.fillRect(hudX + 30, hudY + 95, 400 * hRatio, 25);
    } else {
      e.players.forEach((p: PlayerEntity, i: number) => {
        const stats = ROBOT_STATS[p.unit];
        const hRatio = Math.max(0, p.health / p.maxHealth);
        const y = hudY + 90 + i * 45;
        ctx.fillStyle = p.health > 0 ? stats.color : '#444';
        ctx.fillText(stats.name + (p.isTransformed ? " [" + stats.alt.type + "]" : ""), hudX + 30, y);
        ctx.fillStyle = '#111'; ctx.fillRect(hudX + 30, y + 12, 380, 12);
        ctx.fillStyle = p.health > 0 ? stats.color : '#222';
        ctx.fillRect(hudX + 30, y + 12, 380 * hRatio, 12);
      });
    }
    ctx.restore();
  };

  useEffect(() => {
    const e = engineRef.current;
    const handleKeyDown = (ev: KeyboardEvent) => {
      e.keys[ev.code] = true;
      if ((ev.code === 'ShiftLeft' || ev.code === 'ShiftRight') && !e.isCombined) {
        soundService.playTransform();
        e.players.forEach(p => p.isTransformed = !p.isTransformed);
      }
      if (ev.code === 'KeyC') {
        if (e.isCombined) {
          e.isCombined = false;
          const hPer = e.combinedHealth / e.players.length;
          e.players.forEach((p, i) => { 
            p.health = Math.min(p.maxHealth, hPer); 
            p.width = 32; p.height = 48; 
            p.pos.x = e.players[0].pos.x - i * 90; 
            p.pos.y = GROUND_Y - 48; 
          });
        } else if (upgrades.unlockedUnits.length >= 5) {
          const aliveOnes = e.players.filter(p => p.health > 0);
          if (aliveOnes.length >= 5) {
            e.isCombined = true;
            e.combinedMaxHealth = e.players.reduce((s, p) => s + p.maxHealth, 0) * 1.5;
            e.combinedHealth = e.players.reduce((s, p) => s + p.health, 0) * 1.5;
            aliveOnes[0].width = 110; aliveOnes[0].height = 160;
          }
        }
      }
    };
    const handleKeyUp = (ev: KeyboardEvent) => { e.keys[ev.code] = false; };
    window.addEventListener('keydown', handleKeyDown); window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => { 
      if (!e.isPaused) update(); 
      draw(); 
      animationId = requestAnimationFrame(loop); 
    };

    const update = () => {
      e.frame++;
      const activeLeaderIndex = e.players.findIndex(p => p.health > 0);
      if (activeLeaderIndex === -1) { onDie(); return; }
      const leader = e.players[activeLeaderIndex];

      const moveRight = e.keys['ArrowRight'] || e.keys['KeyD'];
      const moveLeft = e.keys['ArrowLeft'] || e.keys['KeyA'];
      const moveUp = e.keys['ArrowUp'] || e.keys['KeyW'];
      const moveDown = e.keys['ArrowDown'] || e.keys['KeyS'];
      const firing = e.keys['Space'];

      if (e.isCombined) {
        const s = { speed: 6, jump: -22, fireRate: 4 };
        if (moveRight) { leader.vel.x = s.speed; leader.facing = 1; } else if (moveLeft) { leader.vel.x = -s.speed; leader.facing = -1; } else leader.vel.x *= 0.8;
        if (moveUp && leader.grounded) { leader.vel.y = s.jump; leader.grounded = false; }
        leader.vel.y += GRAVITY; leader.pos.x += leader.vel.x; leader.pos.y += leader.vel.y;
        if (leader.pos.y > GROUND_Y - leader.height) { leader.pos.y = GROUND_Y - leader.height; leader.vel.y = 0; leader.grounded = true; }
        if (firing && e.frame - leader.lastShot > s.fireRate) {
          soundService.playShoot();
          for(let i=-2; i<=2; i++) e.bullets.push({ pos: { x: leader.pos.x + 70, y: leader.pos.y + 80 + (i*30) }, vel: { x: leader.facing * 45, y: i * 4 }, width: 50, height: 16, owner: 'player', damage: 60, color: '#facc15', health: 1, maxHealth: 1 });
          leader.lastShot = e.frame;
        }
      } else {
        e.players.forEach((p, i) => {
          if (p.health <= 0) return;
          const stats = ROBOT_STATS[p.unit]; 
          const s = p.isTransformed ? stats.alt : stats.robot;
          const isFalconJet = p.unit === RobotUnit.FALCON && p.isTransformed;

          if (i === activeLeaderIndex) {
            if (moveRight) { p.vel.x = s.speed; p.facing = 1; } else if (moveLeft) { p.vel.x = -s.speed; p.facing = -1; } else p.vel.x *= 0.8;
            if (isFalconJet) {
              if (moveUp) p.vel.y = -s.speed;
              else if (moveDown) p.vel.y = s.speed;
              else p.vel.y *= 0.92;
              p.grounded = false;
            } else {
              if (moveUp && p.grounded) { p.vel.y = s.jump; p.grounded = false; }
              p.vel.y += GRAVITY;
            }
          } else {
            const targetX = leader.pos.x - ((i - activeLeaderIndex) * 110 * leader.facing); 
            const dist = targetX - p.pos.x;
            if (Math.abs(dist) > 50) { p.vel.x = Math.sign(dist) * s.speed * 0.98; p.facing = Math.sign(dist) || 1; } else p.vel.x *= 0.8;
            if (isFalconJet) {
              const targetY = leader.pos.y + (i * 35);
              const hDist = targetY - p.pos.y;
              if (Math.abs(hDist) > 10) p.vel.y = Math.sign(hDist) * s.speed * 0.7;
              else p.vel.y *= 0.85;
            } else {
              if (leader.vel.y < -5 && p.grounded) { p.vel.y = s.jump; p.grounded = false; }
              p.vel.y += GRAVITY;
            }
          }

          p.pos.x += p.vel.x; p.pos.y += p.vel.y;
          if (p.pos.y > GROUND_Y - p.height) { p.pos.y = GROUND_Y - p.height; p.vel.y = 0; p.grounded = true; }
          if (p.pos.y < 50) { p.pos.y = 50; p.vel.y = 0; }

          if (firing && e.frame - p.lastShot > s.fireRate) {
            soundService.playShoot();
            e.bullets.push({ pos: { x: p.pos.x + 25, y: p.pos.y + 30 }, vel: { x: p.facing * 35, y: 0 }, width: 35, height: 14, owner: 'player', damage: 20, color: stats.color, health: 1, maxHealth: 1 });
            p.lastShot = e.frame;
          }
          if (p.invulnerable > 0) p.invulnerable--;
        });
      }

      for (let i = e.bullets.length - 1; i >= 0; i--) {
        const b = e.bullets[i]; b.pos.x += b.vel.x; b.pos.y += b.vel.y || 0;
        if (b.owner === 'enemy') {
          if (e.isCombined) {
            const currentCombined = e.players.find(p => p.health > 0);
            if (currentCombined && !currentCombined.invulnerable && b.pos.x < currentCombined.pos.x + currentCombined.width && b.pos.x + b.width > currentCombined.pos.x && b.pos.y < currentCombined.pos.y + currentCombined.height && b.pos.y + b.height > currentCombined.pos.y) {
              e.combinedHealth -= 10; currentCombined.invulnerable = 25; e.bullets.splice(i, 1); if (e.combinedHealth <= 0) onDie();
            }
          } else {
            e.players.forEach(p => { 
              if (p.health > 0 && !p.invulnerable && b.pos.x < p.pos.x + p.width && b.pos.x + b.width > p.pos.x && b.pos.y < p.pos.y + p.height && b.pos.y + b.height > p.pos.y) { 
                p.health -= 10; 
                p.invulnerable = 40; 
                e.bullets.splice(i, 1); 
              } 
            });
          }
        }
        if (Math.abs(b.pos.x - leader.pos.x) > 4000) e.bullets.splice(i, 1);
      }

      let enemiesAliveCount = 0;
      const isCh2 = e.level > 20;
      const difficultyFactor = isCh2 ? 1.25 : 1.0;

      e.enemies.forEach(en => {
        if (en.isDead) return;
        enemiesAliveCount++;

        const diff = leader.pos.x - en.pos.x;
        en.facing = Math.sign(diff) || -1;

        if (en.type === 'titan') {
          en.pos.x += Math.sign(leader.pos.x - en.pos.x) * 1.2 * difficultyFactor;
          if (Math.abs(en.pos.x - leader.pos.x) < 1600 && e.frame - en.lastShot > 100 / difficultyFactor) {
            e.bullets.push({ pos: { x: en.pos.x, y: en.pos.y + 100 }, vel: { x: Math.sign(leader.pos.x - en.pos.x) * 10 * difficultyFactor, y: 0 }, width: 60, height: 40, owner: 'enemy', health: 1, maxHealth: 1, damage: 100, color: isCh2 ? '#a855f7' : '#ff0055' });
            en.lastShot = e.frame;
          }
        } else if (en.type === 'dragon') {
          en.pos.x += Math.cos(e.frame * 0.05) * 8 * difficultyFactor;
          en.pos.y = 200 + Math.sin(e.frame * 0.05) * 100;
          if (e.frame - en.lastShot > 60 / difficultyFactor) {
            e.bullets.push({ pos: { x: en.pos.x, y: en.pos.y }, vel: { x: Math.sign(leader.pos.x - en.pos.x) * 18 * difficultyFactor, y: 4 }, width: 30, height: 30, owner: 'enemy', health: 1, maxHealth: 1, damage: 60, color: isCh2 ? '#d946ef' : '#ff7700' });
            en.lastShot = e.frame;
          }
        } else if (en.type === 'omnidroid') {
          en.pos.x += Math.sign(leader.pos.x - en.pos.x) * 4 * difficultyFactor;
          if (e.frame - en.lastShot > 40 / difficultyFactor) {
            for(let j=0; j<8; j++) {
              const ang = (j / 8) * Math.PI * 2;
              e.bullets.push({ pos: { x: en.pos.x, y: en.pos.y }, vel: { x: Math.cos(ang) * 12 * difficultyFactor, y: Math.sin(ang) * 12 * difficultyFactor }, width: 20, height: 20, owner: 'enemy', health: 1, maxHealth: 1, damage: 40, color: '#aa00ff' });
            }
            en.lastShot = e.frame;
          }
        } else if (en.type === 'tank') {
          if (en.transformTimer && en.transformTimer > 0) {
            en.transformTimer--;
          } else {
             en.isTransformed = !en.isTransformed;
             en.transformTimer = 200 + Math.random() * 300;
          }
          const targetDir = Math.sign(leader.pos.x - en.pos.x);
          if (en.isTransformed) {
            const accel = 0.02 * difficultyFactor;
            const maxSpeed = 1.0 * difficultyFactor;
            en.vel.x += targetDir * accel;
            if (Math.abs(en.vel.x) > maxSpeed) en.vel.x = Math.sign(en.vel.x) * maxSpeed;
          } else {
            en.vel.x = targetDir * 1.6 * difficultyFactor;
          }
          en.pos.x += en.vel.x;
          if (Math.abs(en.pos.x - leader.pos.x) < 1400 && e.frame - en.lastShot > (en.isTransformed ? 120 : 60) / difficultyFactor) {
            const bulletY = en.isTransformed ? en.pos.y - 15 : en.pos.y + 30;
            e.bullets.push({ pos: { x: en.pos.x, y: bulletY }, vel: { x: Math.sign(leader.pos.x - en.pos.x) * 12 * difficultyFactor, y: 0 }, width: 40, height: 20, owner: 'enemy', health: 1, maxHealth: 1, damage: 50, color: isCh2 ? '#7e22ce' : '#550000' });
            en.lastShot = e.frame;
          }
        } else {
          en.pos.x += Math.sign(leader.pos.x - en.pos.x) * 1.6 * difficultyFactor;
          en.pos.y = GROUND_Y - en.height;
          if (Math.abs(en.pos.x - leader.pos.x) < 1400 && e.frame - en.lastShot > 75 / difficultyFactor) {
            e.bullets.push({ pos: { x: en.pos.x, y: en.pos.y + 40 }, vel: { x: Math.sign(leader.pos.x - en.pos.x) * 14 * difficultyFactor, y: 0 }, width: 25, height: 14, owner: 'enemy', health: 1, maxHealth: 1, damage: 40, color: isCh2 ? '#a855f7' : '#ff0055' });
            en.lastShot = e.frame;
          }
        }

        for (let bi = e.bullets.length - 1; bi >= 0; bi--) {
          const b = e.bullets[bi];
          if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) { 
            en.health -= (b.damage || 20);
            e.bullets.splice(bi, 1); 
            if (en.health <= 0) {
              en.isDead = true; 
              soundService.playDrive(0.5);
            }
          }
        }
      });

      if (enemiesAliveCount === 0 && !e.winTriggered) {
        e.winTriggered = true;
        if (e.level === 1 || e.level === 5 || e.level === 21 || e.level === 25) {
          setShowCutscene(true);
          setCutsceneStep(0);
        } else {
          onWin();
        }
      }
      e.cameraX = leader.pos.x - 700;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const activeLeader = e.players.find(p => p.health > 0);
      if (!activeLeader) return;

      drawCityscape(ctx, e);
      ctx.save(); ctx.translate(-e.cameraX, 0);
      ctx.fillStyle = e.level > 20 ? '#0a0014' : '#06060a'; ctx.fillRect(e.cameraX - 2500, GROUND_Y, CANVAS_WIDTH + 5000, 300);
      ctx.strokeStyle = e.level > 20 ? '#a855f711' : '#00f3ff11'; ctx.lineWidth = 5;
      for (let gx = Math.floor((e.cameraX - 2500) / 120) * 120; gx < e.cameraX + 5500; gx += 120) { ctx.beginPath(); ctx.moveTo(gx, GROUND_Y); ctx.lineTo(gx, GROUND_Y + 300); ctx.stroke(); }

      e.enemies.forEach(en => { 
        if(!en.isDead) {
          if (['titan', 'dragon', 'omnidroid', 'tank'].includes(en.type)) {
            drawBoss(ctx, en, e.frame);
            ctx.fillStyle = '#222'; ctx.fillRect(en.pos.x, en.pos.y - 20, en.width, 10);
            ctx.fillStyle = e.level > 20 ? '#a855f7' : '#ff0055'; ctx.fillRect(en.pos.x, en.pos.y - 20, en.width * (en.health / en.maxHealth), 10);
          } else {
            drawUnit(ctx, en.pos.x, en.pos.y, en.width, en.height, RobotUnit.SENTINEL, en.facing || -1, e.frame, true, false, false, 1.6, en.vel); 
            ctx.fillStyle = '#222'; ctx.fillRect(en.pos.x, en.pos.y - 15, en.width, 6);
            ctx.fillStyle = e.level > 20 ? '#a855f7' : '#ff0055'; ctx.fillRect(en.pos.x, en.pos.y - 15, en.width * (en.health / en.maxHealth), 6);
          }
        }
      });

      if (e.isCombined) {
          drawUnit(ctx, activeLeader.pos.x, activeLeader.pos.y, activeLeader.width, activeLeader.height, activeLeader.unit, activeLeader.facing, e.frame, false, activeLeader.invulnerable > 0, false, 1, activeLeader.vel, true);
      } else {
          e.players.forEach(p => { if(p.health > 0) drawUnit(ctx, p.pos.x, p.pos.y, p.width, p.height, p.unit, p.facing, e.frame, false, p.invulnerable > 0, p.isTransformed, 1, p.vel); });
      }

      e.bullets.forEach(b => { ctx.fillStyle = b.color || '#fff'; ctx.fillRect(b.pos.x, b.pos.y, b.width, b.height); });
      ctx.restore();
      drawHUD(ctx, e);
    };
    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [onWin, onDie, upgrades, level, showCutscene]);

  const handleCutsceneContinue = () => {
    if ((level === 5 || level === 25) && cutsceneStep === 0) {
      setCutsceneStep(1);
    } else {
      onWin();
    }
  };

  const getCutsceneSpeaker = () => {
    if ((level === 5 || level === 25) && cutsceneStep === 1) return { name: "STRIKER", emoji: "⚡" };
    return { name: "SENTINEL", emoji: "🤖" };
  };

  const getCutsceneText = () => {
    if (level === 1) return '"Where the heck did these guys come from, and why on Earth are they here?"';
    if (level === 21) return '"The city is secure, but the wastes are teeming with V2 hardware. Eyes up, team."';
    if (level === 5 || level === 25) {
      if (cutsceneStep === 0) return '"Now there are tanks, what is going on?!"';
      if (cutsceneStep === 1) return '"Now things are getting a lot more harder."';
    }
    return "...";
  };

  const currentSpeaker = getCutsceneSpeaker();

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden font-orbitron">
      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full max-h-[100vh] aspect-video shadow-[0_0_250px_rgba(0,0,0,1)]" />

      {showCutscene && (
        <div className="fixed inset-0 bg-black/40 flex items-end justify-center pb-20 z-[60] backdrop-blur-[2px] animate-in fade-in duration-500">
          <div className="max-w-2xl w-full bg-black/95 border-2 border-cyan-500 p-8 shadow-[0_0_50px_rgba(6,182,212,0.3)] relative group overflow-hidden">
            <div className="absolute top-0 left-0 w-full h-1 bg-cyan-900 overflow-hidden">
              <div className="w-1/3 h-full bg-cyan-400 animate-[scan_1.5s_linear_infinite]"></div>
            </div>

            <div className="flex items-start gap-6">
              <div className="shrink-0">
                <div className={`w-20 h-20 border border-cyan-500 flex items-center justify-center text-4xl shadow-[0_0_15px_rgba(6,182,212,0.5)] ${currentSpeaker.name === 'STRIKER' ? 'bg-yellow-950/50' : 'bg-cyan-950'}`}>
                  {currentSpeaker.emoji}
                </div>
                <div className="text-[10px] text-cyan-400 font-bold uppercase mt-2 tracking-widest text-center">{currentSpeaker.name}</div>
              </div>

              <div className="flex-1">
                <div className="text-cyan-600 text-[10px] font-black uppercase tracking-tighter mb-2 font-mono">INCOMING COMMS // ALPHA_SQUAD</div>
                <p className="text-white text-xl leading-relaxed font-bold italic">
                  {getCutsceneText()}
                </p>

                <div className="mt-6 flex justify-end">
                  <button 
                    onClick={handleCutsceneContinue}
                    className="flex items-center gap-2 bg-cyan-600 hover:bg-cyan-500 text-white px-6 py-2 font-black uppercase tracking-widest text-sm transition-all group active:scale-95"
                  >
                    {(level === 5 || level === 25) && cutsceneStep === 0 ? "NEXT" : "CONTINUE MISSION"}
                    <ChevronRight className="w-4 h-4 group-hover:translate-x-1 transition-transform" />
                  </button>
                </div>
              </div>
            </div>

            <div className="absolute top-0 bottom-0 left-0 w-1 bg-cyan-500/20"></div>
            <div className="absolute top-0 bottom-0 right-0 w-1 bg-cyan-500/20"></div>
          </div>
        </div>
      )}
    </div>
  );
};

export default GameView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { RobotUnit, Bullet, Enemy, Upgrades } from '../types';
import { soundService } from '../services/soundService';
import { ChevronRight } from 'lucide-react';

interface GameViewProps {
  level: number;
  upgrades: Upgrades;
  isPaused: boolean;
  onWin: () => void;
  onDie: () => void;
}

const CANVAS_WIDTH = 1600;
const CANVAS_HEIGHT = 900;
const GRAVITY = 0.5;
const GROUND_Y = 750;

interface PlayerEntity {
  unit: RobotUnit;
  pos: { x: number; y: number };
  vel: { x: number; y: number };
  width: number;
  height: number;
  facing: number;
  grounded: boolean;
  lastShot: number;
  invulnerable: number;
  health: number;
  maxHealth: number;
  isTransformed: boolean;
  id: string;
}

const ROBOT_STATS: Record<RobotUnit, any> = {
  [RobotUnit.SENTINEL]: { name: "SENTINEL", color: '#ffffff', hpMult: 1.0, robot: { speed: 5, jump: -12, fireRate: 15 }, alt: { speed: 10, jump: -6, fireRate: 25, type: 'Police Car' }},
  [RobotUnit.STRIKER]: { name: "STRIKER", color: '#fbbf24', hpMult: 0.8, robot: { speed: 7, jump: -10, fireRate: 10 }, alt: { speed: 15, jump: -4, fireRate: 20, type: 'Police Motorcycle' }},
  [RobotUnit.FALCON]: { name: "FALCON", color: '#22d3ee', hpMult: 0.7, robot: { speed: 6, jump: -15, fireRate: 12 }, alt: { speed: 14, jump: -12, fireRate: 15, type: 'Jet' }},
  [RobotUnit.TITAN]: { name: "TITAN", color: '#ef4444', hpMult: 2.5, robot: { speed: 3.5, jump: -13, fireRate: 30 }, alt: { speed: 5, jump: 0, fireRate: 20, type: 'Tank' }},
  [RobotUnit.SPECTER]: { name: "SPECTER", color: '#a855f7', hpMult: 0.6, robot: { speed: 6, jump: -11, fireRate: 20 }, alt: { speed: 8, jump: -5, fireRate: 40, type: 'Ambulance' }},
  [RobotUnit.VANGUARD]: { name: "VANGUARD", color: '#10b981', hpMult: 2.0, robot: { speed: 4.5, jump: -12, fireRate: 25 }, alt: { speed: 7, jump: -4, fireRate: 30, type: 'Fire Truck' }},
  [RobotUnit.NIGHTSHADE]: { name: "NIGHTSHADE", color: '#6366f1', hpMult: 0.9, robot: { speed: 8, jump: -14, fireRate: 12 }, alt: { speed: 12, jump: -10, fireRate: 18, type: 'Cyber Tiger' }},
  [RobotUnit.BLAZE]: { name: "BLAZE", color: '#f97316', hpMult: 1.2, robot: { speed: 5.5, jump: -11, fireRate: 18 }, alt: { speed: 18, jump: -6, fireRate: 15, type: 'Race Car' }},
  [RobotUnit.GLITCH]: { name: "GLITCH", color: '#ec4899', hpMult: 1.0, robot: { speed: 6, jump: -12, fireRate: 14 }, alt: { speed: 12, jump: -12, fireRate: 16, type: 'Flying Car' }},
  [RobotUnit.OMEGA]: { name: "OMEGA", color: '#ffffff', hpMult: 3.0, robot: { speed: 8, jump: -16, fireRate: 10 }, alt: { speed: 6, jump: -8, fireRate: 10, type: 'Blimp' }},
};

const GameView: React.FC<GameViewProps> = ({ level, upgrades, isPaused, onWin, onDie }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [showCutscene, setShowCutscene] = useState(false);
  const [cutsceneStep, setCutsceneStep] = useState(0);

  const engineRef = useRef({
    players: [] as PlayerEntity[],
    enemies: [] as Enemy[],
    bullets: [] as Bullet[],
    keys: {} as Record<string, boolean>,
    frame: 0,
    cameraX: 0,
    cameraY: 0,
    isPaused: isPaused,
    level: level,
    upgrades: upgrades,
    isCombined: false,
    combinedHealth: 0,
    combinedMaxHealth: 0,
    winTriggered: false,
  });

  useEffect(() => { 
    engineRef.current.isPaused = isPaused || showCutscene; 
    engineRef.current.level = level;
    engineRef.current.upgrades = upgrades;
  }, [isPaused, level, upgrades, showCutscene]);

  const drawMechanicalPart = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string, cornerRadius = 4) => {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, cornerRadius);
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, color);
    grad.addColorStop(0.3, '#ffffff88');
    grad.addColorStop(1, '#000000aa');
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.6)';
    ctx.lineWidth = 1;
    ctx.stroke();
  };

  const drawBoss = (ctx: CanvasRenderingContext2D, en: Enemy, frame: number) => {
    ctx.save();
    ctx.translate(en.pos.x + en.width / 2, en.pos.y + en.height / 2);
    ctx.scale(en.facing || 1, 1);

    // Add tilt for vehicle movement
    const tilt = (en.vel.x * 0.05);
    ctx.rotate(tilt);

    const isUpgraded = level > 20;
    const coreColor = isUpgraded ? '#a855f7' : '#ff0000';

    if (en.type === 'titan') {
      ctx.scale(2.5, 2.5);
      drawHumanoid(ctx, '#222222', frame, true, 1, 1.2);
      ctx.fillStyle = coreColor;
      ctx.beginPath(); ctx.arc(-5, -28, 3, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(5, -28, 3, 0, Math.PI * 2); ctx.fill();
    } else if (en.type === 'dragon') {
      const time = frame * 0.1;
      for (let i = 0; i < 8; i++) {
        const ox = -i * 30;
        const oy = Math.sin(time + i * 0.5) * 40;
        ctx.save();
        ctx.translate(ox, oy);
        drawMechanicalPart(ctx, -15, -15, 30, 30, i === 0 ? (isUpgraded ? '#8b5cf6' : '#ff0055') : '#440022', 8);
        if (i === 0) { 
          ctx.fillStyle = coreColor;
          ctx.fillRect(5, -8, 8, 4);
          ctx.beginPath(); ctx.moveTo(15, 0); ctx.lineTo(30, -10); ctx.lineTo(30, 10); ctx.fill();
        }
        ctx.restore();
      }
    } else if (en.type === 'omnidroid') {
      const legTime = frame * 0.2;
      ctx.fillStyle = '#1a1a1a';
      ctx.beginPath(); ctx.arc(0, 0, 40, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = isUpgraded ? '#8b5cf6' : '#ff0055'; ctx.lineWidth = 3; ctx.stroke();
      ctx.fillStyle = coreColor;
      ctx.beginPath(); ctx.arc(10, 0, 8, 0, Math.PI * 2); ctx.fill();
      for (let i = 0; i < 4; i++) {
        const angle = legTime + (i * Math.PI / 2);
        const lx = Math.cos(angle) * 60;
        const ly = Math.sin(angle) * 60;
        ctx.strokeStyle = '#333'; ctx.lineWidth = 6;
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(lx, ly); ctx.stroke();
        ctx.fillStyle = isUpgraded ? '#8b5cf6' : '#ff0055'; ctx.beginPath(); ctx.arc(lx, ly, 5, 0, Math.PI * 2); ctx.fill();
      }
    } else if (en.type === 'tank') {
      const isMoving = Math.abs(en.vel.x) > 0.1;
      const rock = isMoving ? Math.sin(frame * 0.2) * 2 : 0;
      const treadOffset = (frame * en.vel.x * 2) % 40;

      if (!en.isTransformed) {
         drawHumanoid(ctx, '#552222', frame, true, 1, 1.5);
      } else {
        ctx.save();
        ctx.translate(0, rock);
        drawMechanicalPart(ctx, -45, 10, 90, 30, '#111', 8);
        ctx.strokeStyle = '#333'; ctx.lineWidth = 4; ctx.setLineDash([10, 10]);
        ctx.lineDashOffset = -treadOffset; ctx.beginPath();
        ctx.moveTo(-40, 18); ctx.lineTo(40, 18); ctx.moveTo(-40, 32); ctx.lineTo(40, 32);
        ctx.stroke(); ctx.setLineDash([]);
        drawMechanicalPart(ctx, -35, -15, 75, 30, '#331111', 4);
        ctx.save();
        const recoil = (frame % 120 < 10) ? -5 : 0;
        ctx.translate(recoil, 0);
        drawMechanicalPart(ctx, -20, -32, 45, 22, '#552222', 2);
        drawMechanicalPart(ctx, 15, -26, 50, 10, '#111', 1);
        ctx.restore();
        ctx.fillStyle = coreColor; ctx.fillRect(15, -24, 6, 4);
        ctx.restore();
      }
    }
    ctx.restore();
  };

  const drawAltMode = (ctx: CanvasRenderingContext2D, unit: RobotUnit, frame: number, alpha: number, vel: {x:number}) => {
    ctx.save();
    ctx.globalAlpha = alpha;
    const color = ROBOT_STATS[unit].color;
    const tilt = vel.x * 0.02;
    ctx.rotate(tilt);

    switch (unit) {
      case RobotUnit.SENTINEL: 
        drawMechanicalPart(ctx, -35, -10, 70, 24, '#eee', 4);
        drawMechanicalPart(ctx, -35, 0, 70, 14, '#111', 2);
        const siren = Math.sin(frame * 0.5) > 0;
        ctx.fillStyle = siren ? '#f00' : '#00f'; ctx.fillRect(-12, -20, 24, 10);
        break;
      case RobotUnit.STRIKER: 
        drawMechanicalPart(ctx, -20, -8, 40, 15, color, 8);
        ctx.fillStyle = '#111'; ctx.beginPath(); ctx.arc(-18, 12, 10, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(18, 12, 10, 0, Math.PI * 2); ctx.fill();
        const sirenSmall = Math.sin(frame * 0.8) > 0;
        ctx.fillStyle = sirenSmall ? '#f00' : '#00f'; ctx.fillRect(5, -12, 10, 5);
        break;
      case RobotUnit.FALCON: 
        ctx.beginPath(); ctx.moveTo(-40, 0); ctx.lineTo(10, -22); ctx.lineTo(30, 0); ctx.lineTo(10, 22); ctx.closePath();
        ctx.fillStyle = color; ctx.fill();
        drawMechanicalPart(ctx, -45, -8, 85, 16, '#333', 2);
        drawMechanicalPart(ctx, 10, -6, 25, 12, '#00f3ff', 8);
        if (frame % 3 !== 0) {
            ctx.fillStyle = '#ff7700';
            ctx.beginPath(); ctx.moveTo(-45, -5); ctx.lineTo(-65 - (Math.random() * 15), 0); ctx.lineTo(-45, 5); ctx.fill();
        }
        break;
      case RobotUnit.TITAN: 
        drawMechanicalPart(ctx, -40, -5, 80, 25, '#222', 2); 
        drawMechanicalPart(ctx, -30, -22, 60, 22, color, 4);
        drawMechanicalPart(ctx, 15, -16, 45, 10, '#111', 1);
        break;
      case RobotUnit.SPECTER: 
        drawMechanicalPart(ctx, -35, -15, 70, 32, '#fff', 4);
        ctx.fillStyle = '#a855f7'; ctx.fillRect(-6, -8, 12, 16); ctx.fillRect(-18, -2, 36, 4);
        break;
      case RobotUnit.VANGUARD: 
        drawMechanicalPart(ctx, -45, -15, 90, 34, '#d92b2b', 2);
        drawMechanicalPart(ctx, -40, -28, 65, 12, '#888', 1);
        break;
      case RobotUnit.NIGHTSHADE: 
        const legMov = Math.sin(frame * 0.25) * 12;
        drawMechanicalPart(ctx, -30, -15, 60, 25, color, 12);
        drawMechanicalPart(ctx, 25, -22, 18, 18, color, 4);
        drawMechanicalPart(ctx, -25, 8, 10, 18 + legMov, '#111', 2);
        drawMechanicalPart(ctx, 15, 8, 10, 18 - legMov, '#111', 2);
        break;
      case RobotUnit.BLAZE: 
        drawMechanicalPart(ctx, -40, 0, 80, 20, color, 2);
        drawMechanicalPart(ctx, -25, -10, 35, 10, '#111', 12);
        drawMechanicalPart(ctx, -50, -8, 25, 6, color, 1);
        break;
      case RobotUnit.GLITCH: 
        drawMechanicalPart(ctx, -35, -12, 70, 24, color, 15);
        const hoverGlow = 0.6 + Math.sin(frame * 0.4) * 0.4;
        ctx.fillStyle = `rgba(0, 243, 255, ${hoverGlow})`;
        ctx.beginPath(); ctx.arc(-25, 14, 12, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(25, 14, 12, 0, Math.PI * 2); ctx.fill();
        break;
      case RobotUnit.OMEGA: 
        drawMechanicalPart(ctx, -80, -50, 160, 90, '#fff', 45);
        drawMechanicalPart(ctx, -30, 40, 60, 20, '#444', 5);
        if (frame % 5 !== 0) {
            ctx.fillStyle = '#00f3ff55';
            ctx.beginPath(); ctx.arc(-60, 50, 15, 0, Math.PI * 2); ctx.fill();
            ctx.beginPath(); ctx.arc(60, 50, 15, 0, Math.PI * 2); ctx.fill();
        }
        break;
      default:
        drawMechanicalPart(ctx, -25, -12, 50, 24, color, 6);
    }
    ctx.restore();
  };

  const drawHumanoid = (ctx: CanvasRenderingContext2D, color: string, frame: number, isEnemy = false, alpha = 1, sizeMult = 1) => {
    const time = frame * 0.15;
    const legSwing = Math.sin(time) * 8 * sizeMult;
    const armSwing = Math.cos(time) * 10 * sizeMult;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.scale(sizeMult, sizeMult);
    drawMechanicalPart(ctx, -12, -18, 24, 28, color, 4);
    drawMechanicalPart(ctx, -8, -32, 16, 14, '#111', 6);

    // Violet eyes/cores for upgraded enemies
    const isUpgraded = isEnemy && level > 20;
    ctx.fillStyle = isUpgraded ? '#a855f7' : (isEnemy ? '#ff0000' : '#00f3ff'); 
    ctx.fillRect(isEnemy ? -4 : 2, -26, 6, 2);

    drawMechanicalPart(ctx, -18, -15, 8, 18 + armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, 10, -15, 8, 18 - armSwing/2, '#222', 2);
    drawMechanicalPart(ctx, -10, 10, 10, 16 + legSwing/2, '#111', 2);
    drawMechanicalPart(ctx, 2, 10, 10, 16 - legSwing/2, '#111', 2);
    ctx.restore();
  };

  const drawUnit = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, unit: RobotUnit, facing: number, frame: number, isEnemy: boolean, invulnerable: boolean, transformed: boolean, alpha: number, vel: {x:number}, isCombiner = false, type: string = 'grunt') => {
    ctx.save();
    ctx.translate(x + w / 2, y + h / 2);
    ctx.scale(facing < 0 ? -1 : 1, 1);
    const drawAlpha = invulnerable ? (0.5 + Math.sin(frame * 0.5) * 0.3) * alpha : alpha;

    if (isCombiner) {
      ctx.save(); ctx.translate(0, -40);
      drawHumanoid(ctx, '#facc15', frame, false, drawAlpha, 3.0);
      ctx.restore();
    } else if (transformed) {
      drawAltMode(ctx, unit, frame, drawAlpha, vel);
    } else {
      const isUpgraded = isEnemy && level > 20;
      drawHumanoid(ctx, isEnemy ? (isUpgraded ? '#8b5cf6' : '#ff0055') : ROBOT_STATS[unit].color, frame, isEnemy, drawAlpha);
    }
    ctx.restore();
  };

  const createPlayer = (unit: RobotUnit, x: number, y: number): PlayerEntity => {
    const stats = ROBOT_STATS[unit];
    const baseHP = 100 + (engineRef.current.upgrades.robotTier * 50);
    return { id: Math.random().toString(36).substr(2, 9), unit, pos: { x, y: GROUND_Y - 48 }, vel: { x: 0, y: 0 }, width: 32, height: 48, facing: 1, grounded: true, lastShot: 0, invulnerable: 0, health: baseHP * stats.hpMult, maxHealth: baseHP * stats.hpMult, isTransformed: false };
  };

  const resetLevel = useCallback(() => {
    const e = engineRef.current;
    e.frame = 0; e.cameraX = 0; e.bullets = []; e.isCombined = false;
    e.winTriggered = false;
    e.players = upgrades.unlockedUnits.map((unit, i) => createPlayer(unit, 100 - i * 95, GROUND_Y - 48));

    // Difficulty Scaling for Chapter 2
    const isCh2 = level > 20;
    const hpScalar = isCh2 ? 1.5 : 1;
    const speedScalar = isCh2 ? 1.25 : 1;

    if (level === 20 || level === 36) {
      e.enemies = [
        { id: 101, pos: { x: 2500, y: GROUND_Y - 200 }, vel: { x: 0, y: 0 }, width: 120, height: 200, health: 5000 * hpScalar, maxHealth: 5000 * hpScalar, isDead: false, type: 'titan', lastShot: 0, facing: -1 },
        { id: 102, pos: { x: 3500, y: 200 }, vel: { x: 0, y: 0 }, width: 150, height: 100, health: 3000 * hpScalar, maxHealth: 3000 * hpScalar, isDead: false, type: 'dragon', lastShot: 0, facing: -1 },
        { id: 103, pos: { x: 4500, y: GROUND_Y - 100 }, vel: { x: 0, y: 0 }, width: 100, height: 100, health: 2500 * hpScalar, maxHealth: 2500 * hpScalar, isDead: false, type: 'omnidroid', lastShot: 0, facing: -1 },
      ];
    } else if (level === 5 || level === 25) {
      e.enemies = Array.from({ length: 5 }, (_, i) => ({
        id: i,
        pos: { x: 1800 + i * 1100, y: GROUND_Y - 40 },
        vel: { x: 0, y: 0 },
        width: 80,
        height: 40,
        health: 100 * hpScalar,
        maxHealth: 100 * hpScalar,
        isDead: false,
        type: 'tank',
        lastShot: 0,
        facing: -1,
        isTransformed: false,
        transformTimer: 100 + Math.random() * 200
      }));
    } else {
      const enemyCount = 5;
      e.enemies = Array.from({ length: enemyCount }, (_, i) => {
        const type = 'grunt';
        const width = 48;
        const height = 72;
        const startY = GROUND_Y - height;

        return { 
          id: i, 
          pos: { x: 1800 + i * 1100, y: startY }, 
          vel: { x: 0, y: 0 }, 
          width, 
          height, 
          health: 100 * hpScalar, 
          maxHealth: 100 * hpScalar, 
          isDead: false, 
          type, 
          lastShot: 0,
          facing: -1
        };
      });
    }
  }, [level, upgrades]);

  useEffect(() => { resetLevel(); }, [resetLevel]);

  const drawCityscape = (ctx: CanvasRenderingContext2D, e: any) => {
    const camX = e.cameraX;
    const isCh2 = e.level > 20;

    const skyGrad = ctx.createLinearGradient(0, 0, 0, CANVAS_HEIGHT);
    if (isCh2) {
      // Industrial Waste Palette
      skyGrad.addColorStop(0, '#0c000c');
      skyGrad.addColorStop(0.7, '#1e0a25');
      skyGrad.addColorStop(1, '#4c1d95');
    } else {
      skyGrad.addColorStop(0, '#00000c');
      skyGrad.addColorStop(0.7, '#2a0d08');
      skyGrad.addColorStop(1, '#662200');
    }
    ctx.fillStyle = skyGrad; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    const layers = isCh2 ? [
      { scroll: 0.1, color: '#0f0014', spacing: 450, hMin: 300, hMax: 600 },
      { scroll: 0.4, color: '#1a0025', spacing: 400, hMin: 400, hMax: 850 },
      { scroll: 0.8, color: '#030005', spacing: 350, hMin: 500, hMax: 1000 },
    ] : [
      { scroll: 0.1, color: '#0c0c18', spacing: 450, hMin: 300, hMax: 600 },
      { scroll: 0.4, color: '#1a0f0a', spacing: 400, hMin: 400, hMax: 850 },
      { scroll: 0.8, color: '#050505', spacing: 350, hMin: 500, hMax: 1000 },
    ];

    layers.forEach((layer, li) => {
      ctx.fillStyle = layer.color;
      const startX = Math.floor((camX * layer.scroll) / layer.spacing) * layer.spacing - layer.spacing * 2;
      for (let x = startX; x < startX + CANVAS_WIDTH + layer.spacing * 4; x += layer.spacing) {
        const seed = Math.abs(Math.sin(x * 0.01 + li));
        const h = seed * (layer.hMax - layer.hMin) + layer.hMin;
        const bx = x - (camX * layer.scroll);
        const bw = layer.spacing - 40;
        ctx.fillRect(bx, GROUND_Y - h, bw, h);
        if (li >= 1) {
          const fireSeed = Math.sin(x * 0.9 + e.frame * 0.05);
          if (fireSeed > 0.1) {
            ctx.fillStyle = isCh2 
              ? (fireSeed > 0.7 ? '#a855f7' : '#6b21a8')
              : (fireSeed > 0.7 ? '#ffbb00' : '#d43300');
            for (let r = 0; r < 10; r++) {
              const winY = GROUND_Y - h + 60 + r * 80;
              if (winY < GROUND_Y - 60) {
                ctx.fillRect(bx + 20, winY, 20, 25);
                ctx.fillRect(bx + bw - 40, winY, 20, 25);
              }
            }
          }
          ctx.fillStyle = layer.color;
        }
      }
    });
  };

  const drawHUD = (ctx: CanvasRenderingContext2D, e: any) => {
    ctx.save();
    const hudX = 70; const hudY = 70;
    const hudW = 460; const hudH = e.isCombined ? 130 : e.players.length * 45 + 70;
    ctx.fillStyle = 'rgba(0, 0, 0, 0.92)'; ctx.fillRect(hudX, hudY, hudW, hudH);
    ctx.strokeStyle = '#00f3ff'; ctx.lineWidth = 4; ctx.strokeRect(hudX, hudY, hudW, hudH);
    ctx.font = 'bold 20px Orbitron'; ctx.fillStyle = '#00f3ff';
    ctx.fillText(e.isCombined ? "COMBINER UNIT ACTIVE" : "ALPHA SQUAD: SECTOR " + e.level, hudX + 30, hudY + 45);

    if (e.isCombined) {
      const hRatio = Math.max(0, e.combinedHealth / e.combinedMaxHealth);
      ctx.fillStyle = '#facc15'; ctx.fillText("ULTIMATE ARMOR INTEGRITY", hudX + 30, hudY + 85);
      ctx.fillStyle = '#111'; ctx.fillRect(hudX + 30, hudY + 95, 400, 25);
      ctx.fillStyle = '#facc15'; ctx.fillRect(hudX + 30, hudY + 95, 400 * hRatio, 25);
    } else {
      e.players.forEach((p: PlayerEntity, i: number) => {
        const stats = ROBOT_STATS[p.unit];
        const hRatio = Math.max(0, p.health / p.maxHealth);
        const y = hudY + 90 + i * 45;
        ctx.fillStyle = p.health > 0 ? stats.color : '#444';
        ctx.fillText(stats.name + (p.isTransformed ? " [" + stats.alt.type + "]" : ""), hudX + 30, y);
        ctx.fillStyle = '#111'; ctx.fillRect(hudX + 30, y + 12, 380, 12);
        ctx.fillStyle = p.health > 0 ? stats.color : '#222';
        ctx.fillRect(hudX + 30, y + 12, 380 * hRatio, 12);
      });
    }
    ctx.restore();
  };

  useEffect(() => {
    const e = engineRef.current;
    const handleKeyDown = (ev: KeyboardEvent) => {
      e.keys[ev.code] = true;
      if ((ev.code === 'ShiftLeft' || ev.code === 'ShiftRight') && !e.isCombined) {
        soundService.playTransform();
        e.players.forEach(p => p.isTransformed = !p.isTransformed);
      }
      if (ev.code === 'KeyC') {
        if (e.isCombined) {
          e.isCombined = false;
          const hPer = e.combinedHealth / e.players.length;
          e.players.forEach((p, i) => { 
            p.health = Math.min(p.maxHealth, hPer); 
            p.width = 32; p.height = 48; 
            p.pos.x = e.players[0].pos.x - i * 90; 
            p.pos.y = GROUND_Y - 48; 
          });
        } else if (upgrades.unlockedUnits.length >= 5) {
          const aliveOnes = e.players.filter(p => p.health > 0);
          if (aliveOnes.length >= 5) {
            e.isCombined = true;
            e.combinedMaxHealth = e.players.reduce((s, p) => s + p.maxHealth, 0) * 1.5;
            e.combinedHealth = e.players.reduce((s, p) => s + p.health, 0) * 1.5;
            aliveOnes[0].width = 110; aliveOnes[0].height = 160;
          }
        }
      }
    };
    const handleKeyUp = (ev: KeyboardEvent) => { e.keys[ev.code] = false; };
    window.addEventListener('keydown', handleKeyDown); window.addEventListener('keyup', handleKeyUp);

    let animationId: number;
    const loop = () => { 
      if (!e.isPaused) update(); 
      draw(); 
      animationId = requestAnimationFrame(loop); 
    };

    const update = () => {
      e.frame++;
      const activeLeaderIndex = e.players.findIndex(p => p.health > 0);
      if (activeLeaderIndex === -1) { onDie(); return; }
      const leader = e.players[activeLeaderIndex];

      const moveRight = e.keys['ArrowRight'] || e.keys['KeyD'];
      const moveLeft = e.keys['ArrowLeft'] || e.keys['KeyA'];
      const moveUp = e.keys['ArrowUp'] || e.keys['KeyW'];
      const moveDown = e.keys['ArrowDown'] || e.keys['KeyS'];
      const firing = e.keys['Space'];

      if (e.isCombined) {
        const s = { speed: 6, jump: -22, fireRate: 4 };
        if (moveRight) { leader.vel.x = s.speed; leader.facing = 1; } else if (moveLeft) { leader.vel.x = -s.speed; leader.facing = -1; } else leader.vel.x *= 0.8;
        if (moveUp && leader.grounded) { leader.vel.y = s.jump; leader.grounded = false; }
        leader.vel.y += GRAVITY; leader.pos.x += leader.vel.x; leader.pos.y += leader.vel.y;
        if (leader.pos.y > GROUND_Y - leader.height) { leader.pos.y = GROUND_Y - leader.height; leader.vel.y = 0; leader.grounded = true; }
        if (firing && e.frame - leader.lastShot > s.fireRate) {
          soundService.playShoot();
          for(let i=-2; i<=2; i++) e.bullets.push({ pos: { x: leader.pos.x + 70, y: leader.pos.y + 80 + (i*30) }, vel: { x: leader.facing * 45, y: i * 4 }, width: 50, height: 16, owner: 'player', damage: 60, color: '#facc15', health: 1, maxHealth: 1 });
          leader.lastShot = e.frame;
        }
      } else {
        e.players.forEach((p, i) => {
          if (p.health <= 0) return;
          const stats = ROBOT_STATS[p.unit]; 
          const s = p.isTransformed ? stats.alt : stats.robot;

          // Flight Logic for Falcon Jet and Omega Blimp
          const isFlyingUnit = (p.unit === RobotUnit.FALCON || p.unit === RobotUnit.OMEGA) && p.isTransformed;

          if (i === activeLeaderIndex) {
            if (moveRight) { p.vel.x = s.speed; p.facing = 1; } else if (moveLeft) { p.vel.x = -s.speed; p.facing = -1; } else p.vel.x *= 0.8;
            if (isFlyingUnit) {
              if (moveUp) p.vel.y = -s.speed;
              else if (moveDown) p.vel.y = s.speed;
              else p.vel.y *= 0.92;
              p.grounded = false;
            } else {
              if (moveUp && p.grounded) { p.vel.y = s.jump; p.grounded = false; }
              p.vel.y += GRAVITY;
            }
          } else {
            const targetX = leader.pos.x - ((i - activeLeaderIndex) * 110 * leader.facing); 
            const dist = targetX - p.pos.x;
            if (Math.abs(dist) > 50) { p.vel.x = Math.sign(dist) * s.speed * 0.98; p.facing = Math.sign(dist) || 1; } else p.vel.x *= 0.8;
            if (isFlyingUnit) {
              const targetY = leader.pos.y + (i * 35);
              const hDist = targetY - p.pos.y;
              if (Math.abs(hDist) > 10) p.vel.y = Math.sign(hDist) * s.speed * 0.7;
              else p.vel.y *= 0.85;
            } else {
              if (leader.vel.y < -5 && p.grounded) { p.vel.y = s.jump; p.grounded = false; }
              p.vel.y += GRAVITY;
            }
          }

          p.pos.x += p.vel.x; p.pos.y += p.vel.y;
          if (p.pos.y > GROUND_Y - p.height) { p.pos.y = GROUND_Y - p.height; p.vel.y = 0; p.grounded = true; }
          if (p.pos.y < 50) { p.pos.y = 50; p.vel.y = 0; }

          if (firing && e.frame - p.lastShot > s.fireRate) {
            soundService.playShoot();
            e.bullets.push({ pos: { x: p.pos.x + 25, y: p.pos.y + 30 }, vel: { x: p.facing * 35, y: 0 }, width: 35, height: 14, owner: 'player', damage: 20, color: stats.color, health: 1, maxHealth: 1 });
            p.lastShot = e.frame;
          }
          if (p.invulnerable > 0) p.invulnerable--;
        });
      }

      for (let i = e.bullets.length - 1; i >= 0; i--) {
        const b = e.bullets[i]; b.pos.x += b.vel.x; b.pos.y += b.vel.y || 0;
        if (b.owner === 'enemy') {
          if (e.isCombined) {
            const currentCombined = e.players.find(p => p.health > 0);
            if (currentCombined && !currentCombined.invulnerable && b.pos.x < currentCombined.pos.x + currentCombined.width && b.pos.x + b.width > currentCombined.pos.x && b.pos.y < currentCombined.pos.y + currentCombined.height && b.pos.y + b.height > currentCombined.pos.y) {
              e.combinedHealth -= 10; currentCombined.invulnerable = 25; e.bullets.splice(i, 1); if (e.combinedHealth <= 0) onDie();
            }
          } else {
            e.players.forEach(p => { 
              if (p.health > 0 && !p.invulnerable && b.pos.x < p.pos.x + p.width && b.pos.x + b.width > p.pos.x && b.pos.y < p.pos.y + p.height && b.pos.y + b.height > p.pos.y) { 
                p.health -= 10; 
                p.invulnerable = 40; 
                e.bullets.splice(i, 1); 
              } 
            });
          }
        }
        if (Math.abs(b.pos.x - leader.pos.x) > 4000) e.bullets.splice(i, 1);
      }

      let enemiesAliveCount = 0;
      const isCh2 = e.level > 20;
      const difficultyFactor = isCh2 ? 1.25 : 1.0;

      e.enemies.forEach(en => {
        if (en.isDead) return;
        enemiesAliveCount++;

        const diff = leader.pos.x - en.pos.x;
        en.facing = Math.sign(diff) || -1;

        if (en.type === 'titan') {
          en.pos.x += Math.sign(leader.pos.x - en.pos.x) * 1.2 * difficultyFactor;
          if (Math.abs(en.pos.x - leader.pos.x) < 1600 && e.frame - en.lastShot > 100 / difficultyFactor) {
            e.bullets.push({ pos: { x: en.pos.x, y: en.pos.y + 100 }, vel: { x: Math.sign(leader.pos.x - en.pos.x) * 10 * difficultyFactor, y: 0 }, width: 60, height: 40, owner: 'enemy', health: 1, maxHealth: 1, damage: 100, color: isCh2 ? '#a855f7' : '#ff0055' });
            en.lastShot = e.frame;
          }
        } else if (en.type === 'dragon') {
          en.pos.x += Math.cos(e.frame * 0.05) * 8 * difficultyFactor;
          en.pos.y = 200 + Math.sin(e.frame * 0.05) * 100;
          if (e.frame - en.lastShot > 60 / difficultyFactor) {
            e.bullets.push({ pos: { x: en.pos.x, y: en.pos.y }, vel: { x: Math.sign(leader.pos.x - en.pos.x) * 18 * difficultyFactor, y: 4 }, width: 30, height: 30, owner: 'enemy', health: 1, maxHealth: 1, damage: 60, color: isCh2 ? '#d946ef' : '#ff7700' });
            en.lastShot = e.frame;
          }
        } else if (en.type === 'omnidroid') {
          en.pos.x += Math.sign(leader.pos.x - en.pos.x) * 4 * difficultyFactor;
          if (e.frame - en.lastShot > 40 / difficultyFactor) {
            for(let j=0; j<8; j++) {
              const ang = (j / 8) * Math.PI * 2;
              e.bullets.push({ pos: { x: en.pos.x, y: en.pos.y }, vel: { x: Math.cos(ang) * 12 * difficultyFactor, y: Math.sin(ang) * 12 * difficultyFactor }, width: 20, height: 20, owner: 'enemy', health: 1, maxHealth: 1, damage: 40, color: '#aa00ff' });
            }
            en.lastShot = e.frame;
          }
        } else if (en.type === 'tank') {
          if (en.transformTimer && en.transformTimer > 0) {
            en.transformTimer--;
          } else {
             en.isTransformed = !en.isTransformed;
             en.transformTimer = 200 + Math.random() * 300;
          }
          const targetDir = Math.sign(leader.pos.x - en.pos.x);
          if (en.isTransformed) {
            const accel = 0.02 * difficultyFactor;
            const maxSpeed = 1.0 * difficultyFactor;
            en.vel.x += targetDir * accel;
            if (Math.abs(en.vel.x) > maxSpeed) en.vel.x = Math.sign(en.vel.x) * maxSpeed;
          } else {
            en.vel.x = targetDir * 1.6 * difficultyFactor;
          }
          en.pos.x += en.vel.x;
          if (Math.abs(en.pos.x - leader.pos.x) < 1400 && e.frame - en.lastShot > (en.isTransformed ? 120 : 60) / difficultyFactor) {
            const bulletY = en.isTransformed ? en.pos.y - 15 : en.pos.y + 30;
            e.bullets.push({ pos: { x: en.pos.x, y: bulletY }, vel: { x: Math.sign(leader.pos.x - en.pos.x) * 12 * difficultyFactor, y: 0 }, width: 40, height: 20, owner: 'enemy', health: 1, maxHealth: 1, damage: 50, color: isCh2 ? '#7e22ce' : '#550000' });
            en.lastShot = e.frame;
          }
        } else {
          en.pos.x += Math.sign(leader.pos.x - en.pos.x) * 1.6 * difficultyFactor;
          en.pos.y = GROUND_Y - en.height;
          if (Math.abs(en.pos.x - leader.pos.x) < 1400 && e.frame - en.lastShot > 75 / difficultyFactor) {
            e.bullets.push({ pos: { x: en.pos.x, y: en.pos.y + 40 }, vel: { x: Math.sign(leader.pos.x - en.pos.x) * 14 * difficultyFactor, y: 0 }, width: 25, height: 14, owner: 'enemy', health: 1, maxHealth: 1, damage: 40, color: isCh2 ? '#a855f7' : '#ff0055' });
            en.lastShot = e.frame;
          }
        }

        for (let bi = e.bullets.length - 1; bi >= 0; bi--) {
          const b = e.bullets[bi];
          if (b.owner === 'player' && b.pos.x < en.pos.x + en.width && b.pos.x + b.width > en.pos.x && b.pos.y < en.pos.y + en.height && b.pos.y + b.height > en.pos.y) { 
            en.health -= (b.damage || 20);
            e.bullets.splice(bi, 1); 
            if (en.health <= 0) {
              en.isDead = true; 
              soundService.playDrive(0.5);
            }
          }
        }
      });

      if (enemiesAliveCount === 0 && !e.winTriggered) {
        e.winTriggered = true;
        // Level 25 cutscene (tank conversation) removed for Chapter 2
        if (e.level === 1 || e.level === 5 || e.level === 21) {
          setShowCutscene(true);
          setCutsceneStep(0);
        } else {
          onWin();
        }
      }
      e.cameraX = leader.pos.x - 700;
    };

    const draw = () => {
      const cvs = canvasRef.current; if (!cvs) return;
      const ctx = cvs.getContext('2d')!;
      const activeLeader = e.players.find(p => p.health > 0);
      if (!activeLeader) return;

      drawCityscape(ctx, e);
      ctx.save(); ctx.translate(-e.cameraX, 0);
      ctx.fillStyle = e.level > 20 ? '#0a0014' : '#06060a'; ctx.fillRect(e.cameraX - 2500, GROUND_Y, CANVAS_WIDTH + 5000, 300);
      ctx.strokeStyle = e.level > 20 ? '#a855f711' : '#00f3ff11'; ctx.lineWidth = 5;
      for (let gx = Math.floor((e.cameraX - 2500) / 120) * 120; gx < e.cameraX + 5500; gx += 120) { ctx.beginPath(); ctx.moveTo(gx, GROUND_Y); ctx.lineTo(gx, GROUND_Y + 300); ctx.stroke(); }

      e.enemies.forEach(en => { 
        if(!en.isDead) {
          if (['titan', 'dragon', 'omnidroid', 'tank'].includes(en.type)) {
            drawBoss(ctx, en, e.frame);
            ctx.fillStyle = '#222'; ctx.fillRect(en.pos.x, en.pos.y - 20, en.width, 10);
            ctx.fillStyle = e.level > 20 ? '#a855f7' : '#ff0055'; ctx.fillRect(en.pos.x, en.pos.y - 20, en.width * (en.health / en.maxHealth), 10);
          } else {
            drawUnit(ctx, en.pos.x, en.pos.y, en.width, en.height, RobotUnit.SENTINEL, en.facing || -1, e.frame, true, false, false, 1.6, en.vel); 
            ctx.fillStyle = '#222'; ctx.fillRect(en.pos.x, en.pos.y - 15, en.width, 6);
            ctx.fillStyle = e.level > 20 ? '#a855f7' : '#ff0055'; ctx.fillRect(en.pos.x, en.pos.y - 15, en.width * (en.health / en.maxHealth), 6);
          }
        }
      });

      if (e.isCombined) {
          drawUnit(ctx, activeLeader.pos.x, activeLeader.pos.y, activeLeader.width, activeLeader.height, activeLeader.unit, activeLeader.facing, e.frame, false, activeLeader.invulnerable > 0, false, 1, activeLeader.vel, true);
      } else {
          e.players.forEach(p => { if(p.health > 0) drawUnit(ctx, p.pos.x, p.pos.y, p.width, p.height, p.unit, p.facing, e.frame, false, p.invulnerable > 0, p.isTransformed, 1, p.vel); });
      }

      e.bullets.forEach(b => { ctx.fillStyle = b.color || '#fff'; ctx.fillRect(b.pos.x, b.pos.y, b.width, b.height); });
      ctx.restore();
      drawHUD(ctx, e);
    };
    loop();
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); cancelAnimationFrame(animationId); };
  }, [onWin, onDie, upgrades, level, showCutscene]);

  const handleCutsceneContinue = () => {
    // Level 25 condition removed to prevent Chapter 2 tank conversation
    if (level === 5 && cutsceneStep === 0) {
      setCutsceneStep(1);
    } else {
      onWin();
    }
  };

  const getCutsceneSpeaker = () => {
    if (level === 5 && cutsceneStep === 1) return { name: "STRIKER", emoji: "⚡" };
    return { name: "SENTINEL", emoji: "🤖" };
  };

  const getCutsceneText = () => {
    if (level === 1) return '"Where the heck did these guys come from, and why on Earth are they here?"';
    if (level === 21) return '"The city is secure, but the wastes are teeming with V2 hardware. Eyes up, team."';
    if (level === 5) {
      if (cutsceneStep === 0) return '"Now there are tanks, what is going on?!"';
      if (cutsceneStep === 1) return '"Now things are getting a lot more harder."';
    }
    return "...";
  };

  const currentSpeaker = getCutsceneSpeaker();

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden font-orbitron">
      <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full max-h-[100vh] aspect-video shadow-[0_0_250px_rgba(0,0,0,1)]" />

      {showCutscene && (
        <div className="fixed inset-0 bg-black/40 flex items-end justify-center pb-20 z-[60] backdrop-blur-[2px] animate-in fade-in duration-500">
          <div className="max-w-2xl w-full bg-black/95 border-2 border-cyan-500 p-8 shadow-[0_0_50px_rgba(6,182,212,0.3)] relative group overflow-hidden">
            <div className="absolute top-0 left-0 w-full h-1 bg-cyan-900 overflow-hidden">
              <div className="w-1/3 h-full bg-cyan-400 animate-[scan_1.5s_linear_infinite]"></div>
            </div>

            <div className="flex items-start gap-6">
              <div className="shrink-0">
                <div className={`w-20 h-20 border border-cyan-500 flex items-center justify-center text-4xl shadow-[0_0_15px_rgba(6,182,212,0.5)] ${currentSpeaker.name === 'STRIKER' ? 'bg-yellow-950/50' : 'bg-cyan-950'}`}>
                  {currentSpeaker.emoji}
                </div>
                <div className="text-[10px] text-cyan-400 font-bold uppercase mt-2 tracking-widest text-center">{currentSpeaker.name}</div>
              </div>

              <div className="flex-1">
                <div className="text-cyan-600 text-[10px] font-black uppercase tracking-tighter mb-2 font-mono">INCOMING COMMS // ALPHA_SQUAD</div>
                <p className="text-white text-xl leading-relaxed font-bold italic">
                  {getCutsceneText()}
                </p>

                <div className="mt-6 flex justify-end">
                  <button 
                    onClick={handleCutsceneContinue}
                    className="flex items-center gap-2 bg-cyan-600 hover:bg-cyan-500 text-white px-6 py-2 font-black uppercase tracking-widest text-sm transition-all group active:scale-95"
                  >
                    {level === 5 && cutsceneStep === 0 ? "NEXT" : "CONTINUE MISSION"}
                    <ChevronRight className="w-4 h-4 group-hover:translate-x-1 transition-transform" />
                  </button>
                </div>
              </div>
            </div>

            <div className="absolute top-0 bottom-0 left-0 w-1 bg-cyan-500/20"></div>
            <div className="absolute top-0 bottom-0 right-0 w-1 bg-cyan-500/20"></div>
          </div>
        </div>
      )}
    </div>
  );
};

export default GameView;

import React, { useState, useEffect, useCallback } from 'react';
import { Settings as SettingsIcon, X, ShieldAlert, Key, BarChart3, Music as MusicIcon, Volume2, VolumeX, ChevronRight, CheckCircle2, Save, Database } from 'lucide-react';
import { GameState, LevelInfo, RobotUnit, Upgrades } from './types';
import { getLevelBriefing, getStaticBriefing } from './services/geminiService';
import { soundService } from './services/soundService';
import MainMenu from './components/MainMenu';
import Briefing from './components/Briefing';
import GameView from './components/GameView';
import GameOver from './components/GameOver';
import Victory from './components/Victory';
import Shop from './components/Shop';
import LevelSelect from './components/LevelSelect';
import HowToPlay from './components/HowToPlay';

const SAVE_KEY = 'earthbots_save_data_v4';
const SETTINGS_KEY = 'earthbots_settings_v3';

const DEFAULT_UPGRADES: Upgrades = { 
  robotTier: 0, 
  weaponTier: 0, 
  unlockedUnits: [RobotUnit.SENTINEL]
};

const MAX_CAMPAIGN_LEVELS = 36; // 20 (Ch1) + 16 (Ch2)

const App: React.FC = () => {
  const [initialSaveData] = useState(() => {
    const data = localStorage.getItem(SAVE_KEY);
    if (!data) return null;
    try { return JSON.parse(data); } catch (e) { return null; }
  });

  const [settings, setSettings] = useState(() => {
    const data = localStorage.getItem(SETTINGS_KEY);
    if (!data) return { music: true, sound: true };
    try { return JSON.parse(data); } catch (e) { return { music: true, sound: true }; }
  });

  const [gameState, setGameState] = useState<GameState>(GameState.MENU);
  const [level, setLevel] = useState<number>(initialSaveData?.level || 1);
  const [maxUnlockedLevel, setMaxUnlockedLevel] = useState<number>(initialSaveData?.maxUnlockedLevel || 1);
  const [money, setMoney] = useState<number>(initialSaveData?.money || 0);
  const [upgrades, setUpgrades] = useState<Upgrades>(initialSaveData?.upgrades || DEFAULT_UPGRADES);

  const [briefing, setBriefing] = useState<LevelInfo | null>(null);
  const [isBriefingLoading, setIsBriefingLoading] = useState(false);
  const [shopOrigin, setShopOrigin] = useState<GameState>(GameState.MENU);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [justSaved, setJustSaved] = useState(false);
  const [savePulse, setSavePulse] = useState(false);

  // Persistent Save Function
  const saveToDisk = useCallback(() => {
    const dataToSave = { level, maxUnlockedLevel, money, upgrades };
    localStorage.setItem(SAVE_KEY, JSON.stringify(dataToSave));
  }, [level, maxUnlockedLevel, money, upgrades]);

  // Auto-save logic: Triggered on any progress state change
  useEffect(() => {
    saveToDisk();

    // Brief visual feedback for auto-save
    setSavePulse(true);
    const timer = setTimeout(() => setSavePulse(false), 800);
    return () => clearTimeout(timer);
  }, [level, maxUnlockedLevel, money, upgrades, saveToDisk]);

  // Robust safety: Save on window close
  useEffect(() => {
    const handleUnload = () => saveToDisk();
    window.addEventListener('beforeunload', handleUnload);
    return () => window.removeEventListener('beforeunload', handleUnload);
  }, [saveToDisk]);

  useEffect(() => {
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
    soundService.soundEnabled = settings.sound;
  }, [settings]);

  useEffect(() => {
    const handleGlobalKeyDown = (e: KeyboardEvent) => {
      if (e.code === 'KeyP') {
        setGameState(prev => {
          if (prev === GameState.PLAYING) return GameState.PAUSED;
          if (prev === GameState.PAUSED) return GameState.PLAYING;
          return prev;
        });
      }
      if (e.code === 'Escape') {
        setIsSettingsOpen(false);
      }
    };
    window.addEventListener('keydown', handleGlobalKeyDown);
    return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, []);

  const handleOpenKeySelection = async () => {
    await (window as any).aistudio.openSelectKey();
    if (gameState === GameState.BRIEFING) {
      startLevel(level);
    }
  };

  const handleSaveProgress = () => {
    saveToDisk();
    setJustSaved(true);
    setTimeout(() => setJustSaved(false), 2000);
  };

  const startLevel = useCallback(async (lvl: number) => {
    setGameState(GameState.BRIEFING);
    setLevel(lvl);
    setBriefing(getStaticBriefing(lvl));
    setIsBriefingLoading(true);

    getLevelBriefing(lvl).then(data => {
      setBriefing(data);
      setIsBriefingLoading(false);
    }).catch(() => {
      setIsBriefingLoading(false);
    });
  }, []);

  const handleStartGame = async () => startLevel(1);

  const handleContinueGame = () => {
    startLevel(level);
  };

  const handleLevelComplete = () => {
    // Reward increases in Chapter 2
    const reward = level > 20 ? 800 : (level === 20 ? 15000 : 300);
    setMoney(m => m + reward); 
    const newlyUnlocked = level + 1;
    if (newlyUnlocked > maxUnlockedLevel && newlyUnlocked <= MAX_CAMPAIGN_LEVELS) {
      setMaxUnlockedLevel(newlyUnlocked);
    }
    setGameState(GameState.LEVEL_COMPLETE);
  };

  const openShop = (origin: GameState) => {
    setShopOrigin(origin);
    setGameState(GameState.SHOP);
  };

  const handleSelectLevel = (lvlNum: number) => {
    setLevel(lvlNum);
    startLevel(lvlNum);
  };

  const handleNextLevel = () => {
    if (level === MAX_CAMPAIGN_LEVELS) setGameState(GameState.VICTORY);
    else startLevel(level + 1);
  };

  const handleShopExit = () => {
    setGameState(shopOrigin === GameState.MENU ? GameState.MENU : GameState.LEVEL_COMPLETE);
  };

  const handlePlayerDeath = () => setGameState(GameState.GAMEOVER);

  const buyRobotTier = () => {
    if (money >= 100) {
      setMoney(m => m - 100);
      setUpgrades(u => ({ ...u, robotTier: u.robotTier + 1 }));
    }
  };

  const buyWeaponTier = () => {
    if (money >= 50) {
      setMoney(m => m - 50);
      setUpgrades(u => ({ ...u, weaponTier: u.weaponTier + 1 }));
    }
  };

  const unlockRobotUnit = (unit: RobotUnit, price: number) => {
    if (money >= price && !upgrades.unlockedUnits.includes(unit)) {
      setMoney(m => m - price);
      setUpgrades(u => ({
        ...u,
        unlockedUnits: [...u.unlockedUnits, unit]
      }));
    }
  };

  const isGameVisible = gameState === GameState.PLAYING || gameState === GameState.PAUSED;

  return (
    <div className="w-full h-screen bg-black overflow-hidden select-none text-white font-rajdhani flex flex-col">
      <button 
        onClick={() => setIsSettingsOpen(true)} 
        className="fixed top-4 left-4 z-[110] p-3 bg-gray-950/80 border border-cyan-900/50 text-cyan-500 hover:text-cyan-400 hover:border-cyan-400 hover:bg-cyan-950 transition-all rounded-full shadow-[0_0_15px_rgba(6,182,212,0.1)] group"
        title="Settings Menu"
      >
        <SettingsIcon className="w-6 h-6 group-hover:rotate-90 transition-transform duration-500" />
      </button>

      <div className={`fixed top-4 right-4 z-[110] flex items-center gap-2 transition-all duration-300 pointer-events-none ${savePulse ? 'opacity-100 translate-y-0' : 'opacity-0 -translate-y-2'}`}>
        <div className="flex flex-col items-end">
           <div className="text-[10px] font-black text-emerald-400 tracking-widest uppercase">Mission_Data_Synced</div>
           <div className="text-[8px] font-bold text-emerald-600/60 uppercase font-mono">ENCRYPTED_UPLINK_SUCCESS</div>
        </div>
        <div className="w-2.5 h-2.5 rounded-full bg-emerald-500 animate-pulse shadow-[0_0_12px_rgba(16,185,129,1)]"></div>
      </div>

